window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["2CH"]={"book":"2CH","editions":{"hbo-source":[[1,1,"וַ⁠יִּתְחַזֵּ֛ק שְׁלֹמֹ֥ה בֶן־דָּוִ֖יד עַל־מַלְכוּת֑⁠וֹ וַ⁠יהוָ֤ה אֱלֹהָי⁠ו֙ עִמּ֔⁠וֹ וַֽ⁠יְגַדְּלֵ֖⁠הוּ לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇ţĕẖazé֛̇q şĕ̌lòmò֥h ben-dá̇wi֖yd ʻal-malĕkẇţ֑⁠wò wa⁠yhwá֤h ʼèlòháy⁠w֙ ʻiṁ֔⁠wò waֽ⁠yĕgadĕ̇lé֖⁠hẇ lĕ⁠máֽʻĕlá⁠h׃"],[1,2,"וַ⁠יֹּ֣אמֶר שְׁלֹמֹ֣ה לְ⁠כָל־יִשְׂרָאֵ֡ל לְ⁠שָׂרֵי֩ הָ⁠אֲלָפִ֨ים וְ⁠הַ⁠מֵּא֜וֹת וְ⁠לַ⁠שֹּֽׁפְטִ֗ים וּ⁠לְ⁠כֹ֛ל נָשִׂ֥יא לְ⁠כָל־יִשְׂרָאֵ֖ל רָאשֵׁ֥י הָ⁠אָבֽוֹת׃","wa⁠yò֣̇ʼmer şĕ̌lòmò֣h lĕ⁠kál-yişĕ̂ráʼé֡l lĕ⁠şá̂réy֩ há⁠ʼàlápi֨ym wĕ⁠ha⁠mé̇ʼ֜wòţ wĕ⁠la⁠şòֽ̇̌pĕti֗ym ẇ⁠lĕ⁠kò֛l náşî֥yʼ lĕ⁠kál-yişĕ̂ráʼé֖l ráʼşé֥̌y há⁠ʼábֽwòţ׃"],[1,3,"וַ⁠יֵּלְכ֗וּ שְׁלֹמֹה֙ וְ⁠כָל־הַ⁠קָּהָ֣ל עִמּ֔⁠וֹ לַ⁠בָּמָ֖ה אֲשֶׁ֣ר בְּ⁠גִבְע֑וֹן כִּי־שָׁ֣ם הָיָ֗ה אֹ֤הֶל מוֹעֵד֙ הָֽ⁠אֱלֹהִ֔ים אֲשֶׁ֥ר עָשָׂ֛ה מֹשֶׁ֥ה עֶֽבֶד־יְהוָ֖ה בַּ⁠מִּדְבָּֽר׃","wa⁠yé̇lĕk֗ẇ şĕ̌lòmòh֙ wĕ⁠kál-ha⁠qá̇há֣l ʻiṁ֔⁠wò la⁠bá̇má֖h ʼàşě֣r bĕ̇⁠gibĕʻ֑wòn ki̇y-şá֣̌m háyá֗h ʼò֤hel mwòʻéd֙ háֽ⁠ʼèlòhi֔ym ʼàşě֥r ʻáşá֛̂h mòşě֥h ʻeֽbed-yĕhwá֖h bȧ⁠mi̇dĕbáֽ̇r׃"],[1,4,"אֲבָ֗ל אֲר֤וֹן הָ⁠אֱלֹהִים֙ הֶעֱלָ֤ה דָוִיד֙ מִ⁠קִּרְיַ֣ת יְעָרִ֔ים בַּֽ⁠הֵכִ֥ין ל֖⁠וֹ דָּוִ֑יד כִּ֧י נָֽטָה־ל֛⁠וֹ אֹ֖הֶל בִּ⁠ירוּשָׁלִָֽם׃","ʼàbá֗l ʼàr֤wòn há⁠ʼèlòhiym֙ heʻèlá֤h dáwiyd֙ mi⁠qi̇rĕya֣ţ yĕʻári֔ym bȧֽ⁠héki֥yn l֖⁠wò dá̇wi֑yd ki֧̇y náֽtáh-l֛⁠wò ʼò֖hel bi̇⁠yrẇşá̌liáֽm׃"],[1,5,"וּ⁠מִזְבַּ֣ח הַ⁠נְּחֹ֗שֶׁת אֲשֶׁ֤ר עָשָׂה֙ בְּצַלְאֵל֙ בֶּן־אוּרִ֣י בֶן־ח֔וּר שָׂ֕ם לִ⁠פְנֵ֖י מִשְׁכַּ֣ן יְהוָ֑ה וַ⁠יִּדְרְשֵׁ֥⁠הוּ שְׁלֹמֹ֖ה וְ⁠הַ⁠קָּהָֽל׃","ẇ⁠mizĕbȧ֣ẖ ha⁠nĕ̇ẖò֗şěţ ʼàşě֤r ʻáşá̂h֙ bĕ̇ẕalĕʼél֙ bėn-ʼẇri֣y ben-ẖ֔ẇr şá̂֕m li⁠pĕné֖y mişĕ̌kȧ֣n yĕhwá֑h wa⁠yi̇dĕrĕşé֥̌⁠hẇ şĕ̌lòmò֖h wĕ⁠ha⁠qá̇háֽl׃"],[1,6,"וַ⁠יַּעַל֩ שְׁלֹמֹ֨ה שָׁ֜ם עַל־מִזְבַּ֤ח הַ⁠נְּחֹ֨שֶׁת֙ לִ⁠פְנֵ֣י יְהוָ֔ה אֲשֶׁ֖ר לְ⁠אֹ֣הֶל מוֹעֵ֑ד וַ⁠יַּ֧עַל עָלָ֛י⁠ו עֹל֖וֹת אָֽלֶף׃","wa⁠yȧʻal֩ şĕ̌lòmò֨h şá̌֜m ʻal-mizĕbȧ֤ẖ ha⁠nĕ̇ẖò֨şěţ֙ li⁠pĕné֣y yĕhwá֔h ʼàşě֖r lĕ⁠ʼò֣hel mwòʻé֑d wa⁠yȧ֧ʻal ʻálá֛y⁠w ʻòl֖wòţ ʼáֽlep׃"],[1,7,"בַּ⁠לַּ֣יְלָה הַ⁠ה֔וּא נִרְאָ֥ה אֱלֹהִ֖ים לִ⁠שְׁלֹמֹ֑ה וַ⁠יֹּ֣אמֶר ל֔⁠וֹ שְׁאַ֖ל מָ֥ה אֶתֶּן־לָֽ⁠ךְ׃","bȧ⁠lȧ֣yĕláh ha⁠h֔ẇʼ nirĕʼá֥h ʼèlòhi֖ym li⁠şĕ̌lòmò֑h wa⁠yò֣̇ʼmer l֔⁠wò şĕ̌ʼa֖l má֥h ʼeţėn-láֽ⁠kĕ׃"],[1,8,"וַ⁠יֹּ֤אמֶר שְׁלֹמֹה֙ לֵֽ⁠אלֹהִ֔ים אַתָּ֗ה עָשִׂ֛יתָ עִם־דָּוִ֥יד אָבִ֖⁠י חֶ֣סֶד גָּד֑וֹל וְ⁠הִמְלַכְתַּ֖⁠נִי תַּחְתָּֽי⁠ו׃","wa⁠yò֤̇ʼmer şĕ̌lòmòh֙ léֽ⁠ʼlòhi֔ym ʼaţá̇֗h ʻáşî֛yţá ʻim-dá̇wi֥yd ʼábi֖⁠y ẖe֣sed gá̇d֑wòl wĕ⁠himĕlakĕţȧ֖⁠niy ţȧẖĕţáֽ̇y⁠w׃"],[1,9,"עַתָּה֙ יְהוָ֣ה אֱלֹהִ֔ים יֵֽאָמֵן֙ דְּבָ֣רְ⁠ךָ֔ עִ֖ם דָּוִ֣יד אָבִ֑⁠י כִּ֤י אַתָּה֙ הִמְלַכְתַּ֔⁠נִי עַל־עַ֕ם רַ֖ב כַּ⁠עֲפַ֥ר הָ⁠אָֽרֶץ׃","ʻaţá̇h֙ yĕhwá֣h ʼèlòhi֔ym yéֽʼámén֙ dĕ̇bá֣rĕ⁠ká֔ ʻi֖m dá̇wi֣yd ʼábi֑⁠y ki֤̇y ʼaţá̇h֙ himĕlakĕţȧ֔⁠niy ʻal-ʻa֕m ra֖b kȧ⁠ʻàpa֥r há⁠ʼáֽreẕ׃"],[1,10,"עַתָּ֗ה חָכְמָ֤ה וּ⁠מַדָּע֙ תֶּן־לִ֔⁠י וְ⁠אֵֽצְאָ֛ה לִ⁠פְנֵ֥י הָֽ⁠עָם־הַ⁠זֶּ֖ה וְ⁠אָב֑וֹאָה כִּֽי־מִ֣י יִשְׁפֹּ֔ט אֶת־עַמְּ⁠ךָ֥ הַ⁠זֶּ֖ה הַ⁠גָּדֽוֹל׃ס","ʻaţá̇֗h ẖákĕmá֤h ẇ⁠madá̇ʻ֙ ţėn-li֔⁠y wĕ⁠ʼéֽẕĕʼá֛h li⁠pĕné֥y háֽ⁠ʻám-ha⁠zė֖h wĕ⁠ʼáb֑wòʼáh kiֽ̇y-mi֣y yişĕ̌pò̇֔t ʼeţ-ʻamĕ̇⁠ká֥ ha⁠zė֖h ha⁠gá̇dֽwòl׃s"],[1,11,"וַ⁠יֹּ֣אמֶר־אֱלֹהִ֣ים ׀ לִ⁠שְׁלֹמֹ֡ה יַ֣עַן אֲשֶׁר֩ הָיְתָ֨ה זֹ֜את עִם־לְבָבֶ֗⁠ךָ וְ⁠לֹֽא־שָׁ֠אַלְתָּ עֹ֣שֶׁר נְכָסִ֤ים וְ⁠כָבוֹד֙ וְ⁠אֵת֙ נֶ֣פֶשׁ שֹׂנְאֶ֔י⁠ךָ וְ⁠גַם־יָמִ֥ים רַבִּ֖ים לֹ֣א שָׁאָ֑לְתָּ וַ⁠תִּֽשְׁאַל־לְ⁠ךָ֙ חָכְמָ֣ה וּ⁠מַדָּ֔ע אֲשֶׁ֤ר תִּשְׁפּוֹט֙ אֶת־עַמִּ֔⁠י אֲשֶׁ֥ר הִמְלַכְתִּ֖י⁠ךָ עָלָֽי⁠ו׃","wa⁠yò֣̇ʼmer-ʼèlòhi֣ym ׀ li⁠şĕ̌lòmò֡h ya֣ʻan ʼàşěr֩ háyĕţá֨h zò֜ʼţ ʻim-lĕbábe֗⁠ká wĕ⁠lòֽʼ-şá̌֠ʼalĕţá̇ ʻò֣şěr nĕkási֤ym wĕ⁠kábwòd֙ wĕ⁠ʼéţ֙ ne֣peş̌ şò̂nĕʼe֔y⁠ká wĕ⁠gam-yámi֥ym rabi֖̇ym lò֣ʼ şá̌ʼá֑lĕţá̇ wa⁠ţiֽ̇şĕ̌ʼal-lĕ⁠ká֙ ẖákĕmá֣h ẇ⁠madá̇֔ʻ ʼàşě֤r ţi̇şĕ̌ṗwòt֙ ʼeţ-ʻami̇֔⁠y ʼàşě֥r himĕlakĕţi֖̇y⁠ká ʻáláֽy⁠w׃"],[1,12,"הַֽ⁠חָכְמָ֥ה וְ⁠הַ⁠מַּדָּ֖ע נָת֣וּן לָ֑⁠ךְ וְ⁠עֹ֨שֶׁר וּ⁠נְכָסִ֤ים וְ⁠כָבוֹד֙ אֶתֶּן־לָ֔⁠ךְ אֲשֶׁ֣ר ׀ לֹא־הָ֣יָה כֵ֗ן לַ⁠מְּלָכִים֙ אֲשֶׁ֣ר לְ⁠פָנֶ֔י⁠ךָ וְ⁠אַחֲרֶ֖י⁠ךָ לֹ֥א יִֽהְיֶה־כֵּֽן׃","haֽ⁠ẖákĕmá֥h wĕ⁠ha⁠mȧdá֖̇ʻ náţ֣ẇn lá֑⁠kĕ wĕ⁠ʻò֨şěr ẇ⁠nĕkási֤ym wĕ⁠kábwòd֙ ʼeţėn-lá֔⁠kĕ ʼàşě֣r ׀ lòʼ-há֣yáh ké֗n la⁠mĕ̇lákiym֙ ʼàşě֣r lĕ⁠páne֔y⁠ká wĕ⁠ʼaẖàre֖y⁠ká lò֥ʼ yiֽhĕyeh-kéֽ̇n׃"],[1,13,"וַ⁠יָּבֹ֨א שְׁלֹמֹ֜ה לַ⁠בָּמָ֤ה אֲשֶׁר־בְּ⁠גִבְעוֹן֙ יְר֣וּשָׁלִַ֔ם מִ⁠לִּ⁠פְנֵ֖י אֹ֣הֶל מוֹעֵ֑ד וַ⁠יִּמְלֹ֖ךְ עַל־יִשְׂרָאֵֽל׃פ","wa⁠yá̇bò֨ʼ şĕ̌lòmò֜h la⁠bá̇má֤h ʼàşěr-bĕ̇⁠gibĕʻwòn֙ yĕr֣ẇşá̌lia֔m mi⁠li̇⁠pĕné֖y ʼò֣hel mwòʻé֑d wa⁠yi̇mĕlò֖kĕ ʻal-yişĕ̂ráʼéֽl׃p"],[1,14,"וַ⁠יֶּאֱסֹ֣ף שְׁלֹמֹה֮ רֶ֣כֶב וּ⁠פָרָשִׁים֒ וַֽ⁠יְהִי־ל֗⁠וֹ אֶ֤לֶף וְ⁠אַרְבַּע־מֵאוֹת֙ רֶ֔כֶב וּ⁠שְׁנֵים־עָשָׂ֥ר אֶ֖לֶף פָּרָשִׁ֑ים וַ⁠יַּנִּיחֵ⁠ם֙ בְּ⁠עָרֵ֣י הָ⁠רֶ֔כֶב וְ⁠עִם־הַ⁠מֶּ֖לֶךְ בִּ⁠ירֽוּשָׁלִָֽם׃","wa⁠yėʼèsò֣p şĕ̌lòmòh֮ re֣keb ẇ⁠páráşǐym֒ waֽ⁠yĕhiy-l֗⁠wò ʼe֤lep wĕ⁠ʼarĕbȧʻ-méʼwòţ֙ re֔keb ẇ⁠şĕ̌néym-ʻáşá֥̂r ʼe֖lep pá̇ráşǐ֑ym wa⁠yȧni̇yẖé⁠m֙ bĕ̇⁠ʻáré֣y há⁠re֔keb wĕ⁠ʻim-ha⁠mė֖lekĕ bi̇⁠yrֽẇşá̌liáֽm׃"],[1,15,"וַ⁠יִּתֵּ֨ן הַ⁠מֶּ֜לֶךְ אֶת־הַ⁠כֶּ֧סֶף וְ⁠אֶת־הַ⁠זָּהָ֛ב בִּ⁠ירוּשָׁלִַ֖ם כָּ⁠אֲבָנִ֑ים וְ⁠אֵ֣ת הָ⁠אֲרָזִ֗ים נָתַ֛ן כַּ⁠שִּׁקְמִ֥ים אֲשֶׁר־בַּ⁠שְּׁפֵלָ֖ה לָ⁠רֹֽב׃","wa⁠yi̇ţé̇֨n ha⁠mė֜lekĕ ʼeţ-ha⁠kė֧sep wĕ⁠ʼeţ-ha⁠zá̇há֛b bi̇⁠yrẇşá̌lia֖m ká̇⁠ʼàbáni֑ym wĕ⁠ʼé֣ţ há⁠ʼàrázi֗ym náţa֛n kȧ⁠şi̇̌qĕmi֥ym ʼàşěr-bȧ⁠şĕ̇̌pélá֖h lá⁠ròֽb׃"],[1,16,"וּ⁠מוֹצָ֧א הַ⁠סּוּסִ֛ים אֲשֶׁ֥ר לִ⁠שְׁלֹמֹ֖ה מִ⁠מִּצְרָ֑יִם וּ⁠מִ⁠קְוֵ֕א סֹחֲרֵ֣י הַ⁠מֶּ֔לֶךְ מִ⁠קְוֵ֥א יִקְח֖וּ בִּ⁠מְחִֽיר׃","ẇ⁠mwòẕá֧ʼ ha⁠ṡẇsi֛ym ʼàşě֥r li⁠şĕ̌lòmò֖h mi⁠mi̇ẕĕrá֑yim ẇ⁠mi⁠qĕwé֕ʼ sòẖàré֣y ha⁠mė֔lekĕ mi⁠qĕwé֥ʼ yiqĕẖ֖ẇ bi̇⁠mĕẖiֽyr׃"],[1,17,"וַֽ֠⁠יַּעֲלוּ וַ⁠יּוֹצִ֨יאוּ מִ⁠מִּצְרַ֤יִם מֶרְכָּבָה֙ בְּ⁠שֵׁ֣שׁ מֵא֣וֹת כֶּ֔סֶף וְ⁠ס֖וּס בַּ⁠חֲמִשִּׁ֣ים וּ⁠מֵאָ֑ה וְ֠⁠כֵן לְ⁠כָל־מַלְכֵ֧י הַֽ⁠חִתִּ֛ים וּ⁠מַלְכֵ֥י אֲרָ֖ם בְּ⁠יָדָ֥⁠ם יוֹצִֽיאוּ׃","waֽ֠⁠yȧʻàlẇ wa⁠ẏwòẕi֨yʼẇ mi⁠mi̇ẕĕra֤yim merĕká̇báh֙ bĕ̇⁠şé֣̌ş̌ méʼ֣wòţ kė֔sep wĕ⁠s֖ẇs bȧ⁠ẖàmişi֣̇̌ym ẇ⁠méʼá֑h wĕ֠⁠kén lĕ⁠kál-malĕké֧y haֽ⁠ẖiţi֛̇ym ẇ⁠malĕké֥y ʼàrá֖m bĕ̇⁠yádá֥⁠m ywòẕiֽyʼẇ׃"],[2,1,"וַ⁠יֹּ֣אמֶר שְׁלֹמֹ֗ה לִ⁠בְנ֥וֹת בַּ֨יִת֙ לְ⁠שֵׁ֣ם יְהוָ֔ה וּ⁠בַ֖יִת לְ⁠מַלְכוּתֽ⁠וֹ׃","wa⁠yò֣̇ʼmer şĕ̌lòmò֗h li⁠bĕn֥wòţ bȧ֨yiţ֙ lĕ⁠şé֣̌m yĕhwá֔h ẇ⁠ba֖yiţ lĕ⁠malĕkẇţֽ⁠wò׃"],[2,2,"וַ⁠יִּסְפֹּ֨ר שְׁלֹמֹ֜ה שִׁבְעִ֥ים אֶ֨לֶף֙ אִ֣ישׁ סַבָּ֔ל וּ⁠שְׁמוֹנִ֥ים אֶ֛לֶף אִ֖ישׁ חֹצֵ֣ב בָּ⁠הָ֑ר וּ⁠מְנַצְּחִ֣ים עֲלֵי⁠הֶ֔ם שְׁלֹ֥שֶׁת אֲלָפִ֖ים וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃פ","wa⁠yi̇sĕpò̇֨r şĕ̌lòmò֜h şǐbĕʻi֥ym ʼe֨lep֙ ʼi֣yş̌ sabá̇֔l ẇ⁠şĕ̌mwòni֥ym ʼe֛lep ʼi֖yş̌ ẖòẕé֣b bá̇⁠há֑r ẇ⁠mĕnaẕĕ̇ẖi֣ym ʻàléy⁠he֔m şĕ̌lò֥şěţ ʼàlápi֖ym wĕ⁠şé֥̌ş̌ méʼֽwòţ׃p"],[2,3,"וַ⁠יִּשְׁלַ֣ח שְׁלֹמֹ֔ה אֶל־חוּרָ֥ם מֶֽלֶךְ־צֹ֖ר לֵ⁠אמֹ֑ר כַּ⁠אֲשֶׁ֤ר עָשִׂ֨יתָ֙ עִם־דָּוִ֣יד אָבִ֔⁠י וַ⁠תִּֽשְׁלַֽח־ל֣⁠וֹ אֲרָזִ֔ים לִ⁠בְנֽוֹת־ל֥⁠וֹ בַ֖יִת לָ⁠שֶׁ֥בֶת בּֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֣ẖ şĕ̌lòmò֔h ʼel-ẖẇrá֥m meֽlekĕ-ẕò֖r lé⁠ʼmò֑r kȧ⁠ʼàşě֤r ʻáşî֨yţá֙ ʻim-dá̇wi֣yd ʼábi֔⁠y wa⁠ţiֽ̇şĕ̌laֽẖ-l֣⁠wò ʼàrázi֔ym li⁠bĕnֽwòţ-l֥⁠wò ba֖yiţ lá⁠şě֥beţ ḃֽ⁠wò׃"],[2,4,"הִנֵּה֩ אֲנִ֨י בֽוֹנֶה־בַּ֜יִת לְ⁠שֵׁ֣ם ׀ יְהוָ֣ה אֱלֹהָ֗⁠י לְ⁠הַקְדִּ֣ישׁ ל֡⁠וֹ לְ⁠הַקְטִ֣יר לְ⁠פָנָ֣י⁠ו קְטֹֽרֶת־סַמִּים֩ וּ⁠מַעֲרֶ֨כֶת תָּמִ֤יד וְ⁠עֹלוֹת֙ לַ⁠בֹּ֣קֶר וְ⁠לָ⁠עֶ֔רֶב לַ⁠שַּׁבָּתוֹת֙ וְ⁠לֶ֣⁠חֳדָשִׁ֔ים וּֽ⁠לְ⁠מוֹעֲדֵ֖י יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ לְ⁠עוֹלָ֖ם זֹ֥את עַל־יִשְׂרָאֵֽל׃","hiné̇h֩ ʼàni֨y bֽwòneh-bȧ֜yiţ lĕ⁠şé֣̌m ׀ yĕhwá֣h ʼèlòhá֗⁠y lĕ⁠haqĕdi֣̇yş̌ l֡⁠wò lĕ⁠haqĕti֣yr lĕ⁠páná֣y⁠w qĕtòֽreţ-sami̇ym֩ ẇ⁠maʻàre֨keţ ţá̇mi֤yd wĕ⁠ʻòlwòţ֙ la⁠bò֣̇qer wĕ⁠lá⁠ʻe֔reb la⁠şȧ̌bá̇ţwòţ֙ wĕ⁠le֣⁠ẖodáşǐ֔ym ẇֽ⁠lĕ⁠mwòʻàdé֖y yĕhwá֣h ʼèlòhé֑y⁠nẇ lĕ⁠ʻwòlá֖m zò֥ʼţ ʻal-yişĕ̂ráʼéֽl׃"],[2,5,"וְ⁠הַ⁠בַּ֛יִת אֲשֶׁר־אֲנִ֥י בוֹנֶ֖ה גָּד֑וֹל כִּֽי־גָד֥וֹל אֱלֹהֵ֖י⁠נוּ מִ⁠כָּל־הָ⁠אֱלֹהִֽים׃","wĕ⁠ha⁠bȧ֛yiţ ʼàşěr-ʼàni֥y bwòne֖h gá̇d֑wòl kiֽ̇y-gád֥wòl ʼèlòhé֖y⁠nẇ mi⁠ká̇l-há⁠ʼèlòhiֽym׃"],[2,6,"וּ⁠מִ֤י יַעֲצָר־כֹּ֨חַ֙ לִ⁠בְנֽוֹת־ל֣⁠וֹ בַ֔יִת כִּ֧י הַ⁠שָּׁמַ֛יִם וּ⁠שְׁמֵ֥י הַ⁠שָּׁמַ֖יִם לֹ֣א יְכַלְכְּלֻ֑⁠הוּ וּ⁠מִ֤י אֲנִי֙ אֲשֶׁ֣ר אֶבְנֶה־לּ֣⁠וֹ בַ֔יִת כִּ֖י אִם־לְ⁠הַקְטִ֥יר לְ⁠פָנָֽי⁠ו׃","ẇ⁠mi֤y yaʻàẕár-kò̇֨ẖa֙ li⁠bĕnֽwòţ-l֣⁠wò ba֔yiţ ki֧̇y ha⁠şá̇̌ma֛yim ẇ⁠şĕ̌mé֥y ha⁠şá̇̌ma֖yim lò֣ʼ yĕkalĕkĕ̇lu֑⁠hẇ ẇ⁠mi֤y ʼàniy֙ ʼàşě֣r ʼebĕneh-l֣̇⁠wò ba֔yiţ ki֖̇y ʼim-lĕ⁠haqĕti֥yr lĕ⁠pánáֽy⁠w׃"],[2,7,"וְ⁠עַתָּ֡ה שְֽׁלַֽח־לִ֣⁠י אִישׁ־חָכָ֡ם לַ⁠עֲשׂוֹת֩ בַּ⁠זָּהָ֨ב וּ⁠בַ⁠כֶּ֜סֶף וּ⁠בַ⁠נְּחֹ֣שֶׁת וּ⁠בַ⁠בַּרְזֶ֗ל וּ⁠בָֽ⁠אַרְגְּוָן֙ וְ⁠כַרְמִ֣יל וּ⁠תְכֵ֔לֶת וְ⁠יֹדֵ֖עַ לְ⁠פַתֵּ֣חַ פִּתּוּחִ֑ים עִם־הַֽ⁠חֲכָמִ֗ים אֲשֶׁ֤ר עִמִּ⁠י֙ בִּֽ⁠יהוּדָ֣ה וּ⁠בִֽ⁠ירוּשָׁלִַ֔ם אֲשֶׁ֥ר הֵכִ֖ין דָּוִ֥יד אָבִֽ⁠י׃","wĕ⁠ʻaţá̇֡h şĕֽ̌laֽẖ-li֣⁠y ʼiyş̌-ẖáká֡m la⁠ʻàş̂wòţ֩ bȧ⁠zá̇há֨b ẇ⁠ba⁠kė֜sep ẇ⁠ba⁠nĕ̇ẖò֣şěţ ẇ⁠ba⁠bȧrĕze֗l ẇ⁠báֽ⁠ʼarĕgĕ̇wán֙ wĕ⁠karĕmi֣yl ẇ⁠ţĕké֔leţ wĕ⁠yòdé֖ʻa lĕ⁠paţé֣̇ẖa pi̇ţ̇ẇẖi֑ym ʻim-haֽ⁠ẖàkámi֗ym ʼàşě֤r ʻimi̇⁠y֙ biֽ̇⁠yhẇdá֣h ẇ⁠biֽ⁠yrẇşá̌lia֔m ʼàşě֥r héki֖yn dá̇wi֥yd ʼábiֽ⁠y׃"],[2,8,"וּֽ⁠שְׁלַֽח־לִ⁠י֩ עֲצֵ֨י אֲרָזִ֜ים בְּרוֹשִׁ֣ים וְ⁠אַלְגּוּמִּים֮ מֵֽ⁠הַ⁠לְּבָנוֹן֒ כִּ֚י אֲנִ֣י יָדַ֔עְתִּי אֲשֶׁ֤ר עֲבָדֶ֨י⁠ךָ֙ יֽוֹדְעִ֔ים לִ⁠כְר֖וֹת עֲצֵ֣י לְבָנ֑וֹן וְ⁠הִנֵּ֥ה עֲבָדַ֖⁠י עִם־עֲבָדֶֽי⁠ךָ׃","ẇֽ⁠şĕ̌laֽẖ-li⁠y֩ ʻàẕé֨y ʼàrázi֜ym bĕ̇rwòşǐ֣ym wĕ⁠ʼalĕġẇmi̇ym֮ méֽ⁠ha⁠lĕ̇bánwòn֒ ki֚̇y ʼàni֣y yáda֔ʻĕţi̇y ʼàşě֤r ʻàbáde֨y⁠ká֙ yֽwòdĕʻi֔ym li⁠kĕr֖wòţ ʻàẕé֣y lĕbán֑wòn wĕ⁠hiné֥̇h ʻàbáda֖⁠y ʻim-ʻàbádeֽy⁠ká׃"],[2,9,"וּ⁠לְ⁠הָכִ֥ין לִ֛⁠י עֵצִ֖ים לָ⁠רֹ֑ב כִּ֥י הַ⁠בַּ֛יִת אֲשֶׁר־אֲנִ֥י בוֹנֶ֖ה גָּד֥וֹל וְ⁠הַפְלֵֽא׃","ẇ⁠lĕ⁠háki֥yn li֛⁠y ʻéẕi֖ym lá⁠rò֑b ki֥̇y ha⁠bȧ֛yiţ ʼàşěr-ʼàni֥y bwòne֖h gá̇d֥wòl wĕ⁠hapĕléֽʼ׃"],[2,10,"וְ⁠הִנֵּ֣ה לַֽ⁠חֹטְבִ֣ים ׀ לְֽ⁠כֹרְתֵ֣י ׀ הָ⁠עֵצִ֡ים נָתַתִּי֩ חִטִּ֨ים ׀ מַכּ֜וֹת לַ⁠עֲבָדֶ֗י⁠ךָ כֹּרִים֙ עֶשְׂרִ֣ים אֶ֔לֶף וּ⁠שְׂעֹרִ֕ים כֹּרִ֖ים עֶשְׂרִ֣ים אָ֑לֶף וְ⁠יַ֗יִן בַּתִּים֙ עֶשְׂרִ֣ים אֶ֔לֶף וְ⁠שֶׁ֕מֶן בַּתִּ֖ים עֶשְׂרִ֥ים אָֽלֶף׃פ","wĕ⁠hiné֣̇h laֽ⁠ẖòtĕbi֣ym ׀ lĕֽ⁠kòrĕţé֣y ׀ há⁠ʻéẕi֡ym náţaţi̇y֩ ẖiti̇֨ym ׀ mak̇֜wòţ la⁠ʻàbáde֗y⁠ká kò̇riym֙ ʻeşĕ̂ri֣ym ʼe֔lep ẇ⁠şĕ̂ʻòri֕ym kò̇ri֖ym ʻeşĕ̂ri֣ym ʼá֑lep wĕ⁠ya֗yin bȧţi̇ym֙ ʻeşĕ̂ri֣ym ʼe֔lep wĕ⁠şě֕men bȧţi֖̇ym ʻeşĕ̂ri֥ym ʼáֽlep׃p"],[2,11,"וַ⁠יֹּ֨אמֶר חוּרָ֤ם מֶֽלֶךְ־צֹר֙ בִּ⁠כְתָ֔ב וַ⁠יִּשְׁלַ֖ח אֶל־שְׁלֹמֹ֑ה בְּ⁠אַהֲבַ֤ת יְהוָה֙ אֶת־עַמּ֔⁠וֹ נְתָנְ⁠ךָ֥ עֲלֵי⁠הֶ֖ם מֶֽלֶךְ׃","wa⁠yò̇֨ʼmer ẖẇrá֤m meֽlekĕ-ẕòr֙ bi̇⁠kĕţá֔b wa⁠yi̇şĕ̌la֖ẖ ʼel-şĕ̌lòmò֑h bĕ̇⁠ʼahàba֤ţ yĕhwáh֙ ʼeţ-ʻaṁ֔⁠wò nĕţánĕ⁠ká֥ ʻàléy⁠he֖m meֽlekĕ׃"],[2,12,"וַ⁠יֹּאמֶר֮ חוּרָם֒ בָּר֤וּךְ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֣ר עָשָׂ֔ה אֶת־הַ⁠שָּׁמַ֖יִם וְ⁠אֶת־הָ⁠אָ֑רֶץ אֲשֶׁ֣ר נָתַן֩ לְ⁠דָוִ֨יד הַ⁠מֶּ֜לֶךְ בֵּ֣ן חָכָ֗ם יוֹדֵ֨עַ֙ שֵׂ֣כֶל וּ⁠בִינָ֔ה אֲשֶׁ֤ר יִבְנֶה־בַּ֨יִת֙ לַ⁠יהוָ֔ה וּ⁠בַ֖יִת לְ⁠מַלְכוּתֽ⁠וֹ׃","wa⁠yò̇ʼmer֮ ẖẇrám֒ bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşě֣r ʻáşá̂֔h ʼeţ-ha⁠şá̇̌ma֖yim wĕ⁠ʼeţ-há⁠ʼá֑reẕ ʼàşě֣r náţan֩ lĕ⁠dáwi֨yd ha⁠mė֜lekĕ bé֣̇n ẖáká֗m ywòdé֨ʻa֙ şé֣̂kel ẇ⁠biyná֔h ʼàşě֤r yibĕneh-bȧ֨yiţ֙ la⁠yhwá֔h ẇ⁠ba֖yiţ lĕ⁠malĕkẇţֽ⁠wò׃"],[2,13,"וְ⁠עַתָּ֗ה שָׁלַ֧חְתִּי אִישׁ־חָכָ֛ם יוֹדֵ֥עַ בִּינָ֖ה לְ⁠חוּרָ֥ם אָבִֽי׃","wĕ⁠ʻaţá̇֗h şá̌la֧ẖĕţi̇y ʼiyş̌-ẖáká֛m ywòdé֥ʻa bi̇yná֖h lĕ⁠ẖẇrá֥m ʼábiֽy׃"],[2,14,"בֶּן־אִשָּׁ֞ה מִן־בְּנ֣וֹת דָּ֗ן וְ⁠אָבִ֣י⁠ו אִישׁ־צֹרִ֡י יוֹדֵ֡עַ לַ⁠עֲשׂ֣וֹת בַּ⁠זָּֽהָב־וּ֠⁠בַ⁠כֶּסֶף בַּ⁠נְּחֹ֨שֶׁת בַּ⁠בַּרְזֶ֜ל בָּ⁠אֲבָנִ֣ים וּ⁠בָ⁠עֵצִ֗ים בָּ⁠אַרְגָּמָ֤ן בַּ⁠תְּכֵ֨לֶת֙ וּ⁠בַ⁠בּ֣וּץ וּ⁠בַ⁠כַּרְמִ֔יל וּ⁠לְ⁠פַתֵּ֨חַ֙ כָּל־פִּתּ֔וּחַ וְ⁠לַ⁠חְשֹׁ֖ב כָּל־מַחֲשָׁ֑בֶת אֲשֶׁ֤ר יִנָּֽתֶן־ל⁠וֹ֙ עִם־חֲכָמֶ֔י⁠ךָ וְֽ⁠חַכְמֵ֔י אֲדֹנִ֖⁠י דָּוִ֥יד אָבִֽי⁠ךָ׃","bėn-ʼişá̇̌֞h min-bĕ̇n֣wòţ dá̇֗n wĕ⁠ʼábi֣y⁠w ʼiyş̌-ẕòri֡y ywòdé֡ʻa la⁠ʻàş֣̂wòţ bȧ⁠záֽ̇háb-ẇ֠⁠ba⁠kėsep bȧ⁠nĕ̇ẖò֨şěţ bȧ⁠bȧrĕze֜l bá̇⁠ʼàbáni֣ym ẇ⁠bá⁠ʻéẕi֗ym bá̇⁠ʼarĕgá̇má֤n bȧ⁠ţĕ̇ké֨leţ֙ ẇ⁠ba⁠ḃ֣ẇẕ ẇ⁠ba⁠kȧrĕmi֔yl ẇ⁠lĕ⁠paţé̇֨ẖa֙ ká̇l-pi̇ţ̇֔ẇẖa wĕ⁠la⁠ẖĕşò֖̌b ká̇l-maẖàşá֑̌beţ ʼàşě֤r yináֽ̇ţen-l⁠wò֙ ʻim-ẖàkáme֔y⁠ká wĕֽ⁠ẖakĕmé֔y ʼàdòni֖⁠y dá̇wi֥yd ʼábiֽy⁠ká׃"],[2,15,"וְ֠⁠עַתָּה הַ⁠חִטִּ֨ים וְ⁠הַ⁠שְּׂעֹרִ֜ים הַ⁠שֶּׁ֤מֶן וְ⁠הַ⁠יַּ֨יִן֙ אֲשֶׁ֣ר אָמַ֣ר אֲדֹנִ֔⁠י יִשְׁלַ֖ח לַ⁠עֲבָדָֽי⁠ו׃","wĕ֠⁠ʻaţá̇h ha⁠ẖiti̇֨ym wĕ⁠ha⁠şĕ̇̂ʻòri֜ym ha⁠şė֤̌men wĕ⁠ha⁠yȧ֨yin֙ ʼàşě֣r ʼáma֣r ʼàdòni֔⁠y yişĕ̌la֖ẖ la⁠ʻàbádáֽy⁠w׃"],[2,16,"וַ֠⁠אֲנַחְנוּ נִכְרֹ֨ת עֵצִ֤ים מִן־הַ⁠לְּבָנוֹן֙ כְּ⁠כָל־צָרְכֶּ֔⁠ךָ וּ⁠נְבִיאֵ֥⁠ם לְ⁠ךָ֛ רַפְסֹד֖וֹת עַל־יָ֣ם יָפ֑וֹ וְ⁠אַתָּ֛ה תַּעֲלֶ֥ה אֹתָ֖⁠ם יְרוּשָׁלִָֽם׃פ","wa֠⁠ʼànaẖĕnẇ nikĕrò֨ţ ʻéẕi֤ym min-ha⁠lĕ̇bánwòn֙ kĕ̇⁠kál-ẕárĕkė֔⁠ká ẇ⁠nĕbiyʼé֥⁠m lĕ⁠ká֛ rapĕsòd֖wòţ ʻal-yá֣m yáp֑wò wĕ⁠ʼaţá֛̇h ţȧʻàle֥h ʼòţá֖⁠m yĕrẇşá̌liáֽm׃p"],[2,17,"וַ⁠יִּסְפֹּ֣ר שְׁלֹמֹ֗ה כָּל־הָ⁠אֲנָשִׁ֤ים הַ⁠גֵּירִים֙ אֲשֶׁר֙ בְּ⁠אֶ֣רֶץ יִשְׂרָאֵ֔ל אַחֲרֵ֣י הַ⁠סְּפָ֔ר אֲשֶׁ֥ר סְפָרָ֖⁠ם דָּוִ֣יד אָבִ֑י⁠ו וַ⁠יִּמָּצְא֗וּ מֵאָ֤ה וַ⁠חֲמִשִּׁים֙ אֶ֔לֶף וּ⁠שְׁלֹ֥שֶׁת אֲלָפִ֖ים וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃","wa⁠yi̇sĕpò֣̇r şĕ̌lòmò֗h ká̇l-há⁠ʼànáşǐ֤ym ha⁠gé̇yriym֙ ʼàşěr֙ bĕ̇⁠ʼe֣reẕ yişĕ̂ráʼé֔l ʼaẖàré֣y ha⁠sĕ̇pá֔r ʼàşě֥r sĕpárá֖⁠m dá̇wi֣yd ʼábi֑y⁠w wa⁠yi̇má̇ẕĕʼ֗ẇ méʼá֤h wa⁠ẖàmişi̇̌ym֙ ʼe֔lep ẇ⁠şĕ̌lò֥şěţ ʼàlápi֖ym wĕ⁠şé֥̌ş̌ méʼֽwòţ׃"],[2,18,"וַ⁠יַּ֨עַשׂ מֵ⁠הֶ֜ם שִׁבְעִ֥ים אֶ֨לֶף֙ סַבָּ֔ל וּ⁠שְׁמֹנִ֥ים אֶ֖לֶף חֹצֵ֣ב בָּ⁠הָ֑ר וּ⁠שְׁלֹ֤שֶׁת אֲלָפִים֙ וְ⁠שֵׁ֣שׁ מֵא֔וֹת מְנַצְּחִ֖ים לְ⁠הַעֲבִ֥יד אֶת־הָ⁠עָֽם׃","wa⁠yȧ֨ʻaş̂ mé⁠he֜m şǐbĕʻi֥ym ʼe֨lep֙ sabá̇֔l ẇ⁠şĕ̌mòni֥ym ʼe֖lep ẖòẕé֣b bá̇⁠há֑r ẇ⁠şĕ̌lò֤şěţ ʼàlápiym֙ wĕ⁠şé֣̌ş̌ méʼ֔wòţ mĕnaẕĕ̇ẖi֖ym lĕ⁠haʻàbi֥yd ʼeţ-há⁠ʻáֽm׃"],[3,1,"וַ⁠יָּ֣חֶל שְׁלֹמֹ֗ה לִ⁠בְנ֤וֹת אֶת־בֵּית־יְהוָה֙ בִּ⁠יר֣וּשָׁלִַ֔ם בְּ⁠הַר֙ הַ⁠מּ֣וֹרִיָּ֔ה אֲשֶׁ֥ר נִרְאָ֖ה לְ⁠דָוִ֣יד אָבִ֑י⁠הוּ אֲשֶׁ֤ר הֵכִין֙ בִּ⁠מְק֣וֹם דָּוִ֔יד בְּ⁠גֹ֖רֶן אָרְנָ֥ן הַ⁠יְבוּסִֽי׃","wa⁠yá֣̇ẖel şĕ̌lòmò֗h li⁠bĕn֤wòţ ʼeţ-bé̇yţ-yĕhwáh֙ bi̇⁠yr֣ẇşá̌lia֔m bĕ̇⁠har֙ ha⁠ṁ֣wòriyá̇֔h ʼàşě֥r nirĕʼá֖h lĕ⁠dáwi֣yd ʼábi֑y⁠hẇ ʼàşě֤r hékiyn֙ bi̇⁠mĕq֣wòm dá̇wi֔yd bĕ̇⁠gò֖ren ʼárĕná֥n ha⁠yĕbẇsiֽy׃"],[3,2,"וַ֠⁠יָּחֶל לִ⁠בְנ֞וֹת בַּ⁠חֹ֤דֶשׁ הַ⁠שֵּׁנִי֙ בַּ⁠שֵּׁנִ֔י בִּ⁠שְׁנַ֥ת אַרְבַּ֖ע לְ⁠מַלְכוּתֽ⁠וֹ׃","wa֠⁠yá̇ẖel li⁠bĕn֞wòţ bȧ⁠ẖò֤deş̌ ha⁠şé̇̌niy֙ bȧ⁠şé̇̌ni֔y bi̇⁠şĕ̌na֥ţ ʼarĕbȧ֖ʻ lĕ⁠malĕkẇţֽ⁠wò׃"],[3,3,"וְ⁠אֵ֨לֶּה֙ הוּסַ֣ד שְׁלֹמֹ֔ה לִ⁠בְנ֖וֹת אֶת־בֵּ֣ית הָ⁠אֱלֹהִ֑ים הָ⁠אֹ֡רֶךְ אַמּ֞וֹת בַּ⁠מִּדָּ֤ה הָ⁠רִֽאשׁוֹנָה֙ אַמּ֣וֹת שִׁשִּׁ֔ים וְ⁠רֹ֖חַב אַמּ֥וֹת עֶשְׂרִֽים׃","wĕ⁠ʼé֨lėh֙ hẇsa֣d şĕ̌lòmò֔h li⁠bĕn֖wòţ ʼeţ-bé֣̇yţ há⁠ʼèlòhi֑ym há⁠ʼò֡rekĕ ʼaṁ֞wòţ bȧ⁠mi̇dá֤̇h há⁠riֽʼş̌wònáh֙ ʼaṁ֣wòţ şǐşi̇̌֔ym wĕ⁠rò֖ẖab ʼaṁ֥wòţ ʻeşĕ̂riֽym׃"],[3,4,"וְ⁠הָ⁠אוּלָ֡ם אֲשֶׁר֩ עַל־פְּנֵ֨י הָ⁠אֹ֜רֶךְ עַל־פְּנֵ֤י רֹֽחַב־הַ⁠בַּ֨יִת֙ אַמּ֣וֹת עֶשְׂרִ֔ים וְ⁠הַ⁠גֹּ֖בַהּ מֵאָ֣ה וְ⁠עֶשְׂרִ֑ים וַ⁠יְצַפֵּ֥⁠הוּ מִ⁠פְּנִ֖ימָה זָהָ֥ב טָהֽוֹר׃","wĕ⁠há⁠ʼẇlá֡m ʼàşěr֩ ʻal-pĕ̇né֨y há⁠ʼò֜rekĕ ʻal-pĕ̇né֤y ròֽẖab-ha⁠bȧ֨yiţ֙ ʼaṁ֣wòţ ʻeşĕ̂ri֔ym wĕ⁠ha⁠gò֖̇baḣ méʼá֣h wĕ⁠ʻeşĕ̂ri֑ym wa⁠yĕẕapé֥̇⁠hẇ mi⁠pĕ̇ni֖ymáh záhá֥b táhֽwòr׃"],[3,5,"וְ⁠אֵ֣ת ׀ הַ⁠בַּ֣יִת הַ⁠גָּד֗וֹל חִפָּה֙ עֵ֣ץ בְּרוֹשִׁ֔ים וַ⁠יְחַפֵּ֖⁠הוּ זָהָ֣ב ט֑וֹב וַ⁠יַּ֧עַל עָלָ֛י⁠ו תִּמֹרִ֖ים וְ⁠שַׁרְשְׁרֽוֹת׃","wĕ⁠ʼé֣ţ ׀ ha⁠bȧ֣yiţ ha⁠gá̇d֗wòl ẖipá̇h֙ ʻé֣ẕ bĕ̇rwòşǐ֔ym wa⁠yĕẖapé֖̇⁠hẇ záhá֣b t֑wòb wa⁠yȧ֧ʻal ʻálá֛y⁠w ţi̇mòri֖ym wĕ⁠şǎrĕşĕ̌rֽwòţ׃"],[3,6,"וַ⁠יְצַ֧ף אֶת־הַ⁠בַּ֛יִת אֶ֥בֶן יְקָרָ֖ה לְ⁠תִפְאָ֑רֶת וְ⁠הַ⁠זָּהָ֖ב זְהַ֥ב פַּרְוָֽיִם׃","wa⁠yĕẕa֧p ʼeţ-ha⁠bȧ֛yiţ ʼe֥ben yĕqárá֖h lĕ⁠ţipĕʼá֑reţ wĕ⁠ha⁠zá̇há֖b zĕha֥b pȧrĕwáֽyim׃"],[3,7,"וַ⁠יְחַ֨ף אֶת־הַ⁠בַּ֜יִת הַ⁠קֹּר֧וֹת הַ⁠סִּפִּ֛ים וְ⁠קִֽירוֹתָ֥י⁠ו וְ⁠דַלְתוֹתָ֖י⁠ו זָהָ֑ב וּ⁠פִתַּ֥ח כְּרוּבִ֖ים עַל־הַ⁠קִּירֽוֹת׃ס","wa⁠yĕẖa֨p ʼeţ-ha⁠bȧ֜yiţ ha⁠qò̇r֧wòţ ha⁠si̇pi֛̇ym wĕ⁠qiֽyrwòţá֥y⁠w wĕ⁠dalĕţwòţá֖y⁠w záhá֑b ẇ⁠piţȧ֥ẖ kĕ̇rẇbi֖ym ʻal-ha⁠qi̇yrֽwòţ׃s"],[3,8,"וַ⁠יַּ֨עַשׂ֙ אֶת־בֵּֽית־קֹ֣דֶשׁ הַ⁠קֳּדָשִׁ֔ים אָרְכּ֞⁠וֹ עַל־פְּנֵ֤י רֹֽחַב־הַ⁠בַּ֨יִת֙ אַמּ֣וֹת עֶשְׂרִ֔ים וְ⁠רָחְבּ֖⁠וֹ אַמּ֣וֹת עֶשְׂרִ֑ים וַ⁠יְחַפֵּ֨⁠הוּ֙ זָהָ֣ב ט֔וֹב לְ⁠כִכָּרִ֖ים שֵׁ֥שׁ מֵאֽוֹת׃","wa⁠yȧ֨ʻaş̂֙ ʼeţ-béֽ̇yţ-qò֣deş̌ ha⁠qȯdáşǐ֔ym ʼárĕk̇֞⁠wò ʻal-pĕ̇né֤y ròֽẖab-ha⁠bȧ֨yiţ֙ ʼaṁ֣wòţ ʻeşĕ̂ri֔ym wĕ⁠ráẖĕḃ֖⁠wò ʼaṁ֣wòţ ʻeşĕ̂ri֑ym wa⁠yĕẖapé̇֨⁠hẇ֙ záhá֣b t֔wòb lĕ⁠kiká̇ri֖ym şé֥̌ş̌ méʼֽwòţ׃"],[3,9,"וּ⁠מִשְׁקָ֛ל לְ⁠מִסְמְר֥וֹת לִ⁠שְׁקָלִ֖ים חֲמִשִּׁ֣ים זָהָ֑ב וְ⁠הָ⁠עֲלִיּ֖וֹת חִפָּ֥ה זָהָֽב׃","ẇ⁠mişĕ̌qá֛l lĕ⁠misĕmĕr֥wòţ li⁠şĕ̌qáli֖ym ẖàmişi֣̇̌ym záhá֑b wĕ⁠há⁠ʻàliẏ֖wòţ ẖipá֥̇h záháֽb׃"],[3,10,"וַ⁠יַּ֜עַשׂ בְּ⁠בֵֽית־קֹ֤דֶשׁ הַ⁠קֳּדָשִׁים֙ כְּרוּבִ֣ים שְׁנַ֔יִם מַעֲשֵׂ֖ה צַעֲצֻעִ֑ים וַ⁠יְצַפּ֥וּ אֹתָ֖⁠ם זָהָֽב׃","wa⁠yȧ֜ʻaş̂ bĕ̇⁠béֽyţ-qò֤deş̌ ha⁠qȯdáşǐym֙ kĕ̇rẇbi֣ym şĕ̌na֔yim maʻàşé֖̂h ẕaʻàẕuʻi֑ym wa⁠yĕẕaṗ֥ẇ ʼòţá֖⁠m záháֽb׃"],[3,11,"וְ⁠כַנְפֵי֙ הַ⁠כְּרוּבִ֔ים אָרְכָּ֖⁠ם אַמּ֣וֹת עֶשְׂרִ֑ים כְּנַ֨ף הָ⁠אֶחָ֜ד לְ⁠אַמּ֣וֹת חָמֵ֗שׁ מַגַּ֨עַת֙ לְ⁠קִ֣יר הַ⁠בַּ֔יִת וְ⁠הַ⁠כָּנָ֤ף הָ⁠אַחֶ֨רֶת֙ אַמּ֣וֹת חָמֵ֔שׁ מַגִּ֕יעַ לִ⁠כְנַ֖ף הַ⁠כְּר֥וּב הָ⁠אַחֵֽר׃","wĕ⁠kanĕpéy֙ ha⁠kĕ̇rẇbi֔ym ʼárĕká֖̇⁠m ʼaṁ֣wòţ ʻeşĕ̂ri֑ym kĕ̇na֨p há⁠ʼeẖá֜d lĕ⁠ʼaṁ֣wòţ ẖámé֗ş̌ magȧ֨ʻaţ֙ lĕ⁠qi֣yr ha⁠bȧ֔yiţ wĕ⁠ha⁠ká̇ná֤p há⁠ʼaẖe֨reţ֙ ʼaṁ֣wòţ ẖámé֔ş̌ magi̇֕yʻa li⁠kĕna֖p ha⁠kĕ̇r֥ẇb há⁠ʼaẖéֽr׃"],[3,12,"וּ⁠כְנַ֨ף הַ⁠כְּר֤וּב הָ⁠אֶחָד֙ אַמּ֣וֹת חָמֵ֔שׁ מַגִּ֖יעַ לְ⁠קִ֣יר הַ⁠בָּ֑יִת וְ⁠הַ⁠כָּנָ֤ף הָ⁠אַחֶ֨רֶת֙ אַמּ֣וֹת חָמֵ֔שׁ דְּבֵקָ֕ה לִ⁠כְנַ֖ף הַ⁠כְּר֥וּב הָ⁠אַחֵֽר׃","ẇ⁠kĕna֨p ha⁠kĕ̇r֤ẇb há⁠ʼeẖád֙ ʼaṁ֣wòţ ẖámé֔ş̌ magi֖̇yʻa lĕ⁠qi֣yr ha⁠bá֑̇yiţ wĕ⁠ha⁠ká̇ná֤p há⁠ʼaẖe֨reţ֙ ʼaṁ֣wòţ ẖámé֔ş̌ dĕ̇béqá֕h li⁠kĕna֖p ha⁠kĕ̇r֥ẇb há⁠ʼaẖéֽr׃"],[3,13,"כַּנְפֵי֙ הַ⁠כְּרוּבִ֣ים הָ⁠אֵ֔לֶּה פֹּֽרְשִׂ֖ים אַמּ֣וֹת עֶשְׂרִ֑ים וְ⁠הֵ֛ם עֹמְדִ֥ים עַל־רַגְלֵי⁠הֶ֖ם וּ⁠פְנֵי⁠הֶ֥ם לַ⁠בָּֽיִת׃ס","kȧnĕpéy֙ ha⁠kĕ̇rẇbi֣ym há⁠ʼé֔lėh pòֽ̇rĕşî֖ym ʼaṁ֣wòţ ʻeşĕ̂ri֑ym wĕ⁠hé֛m ʻòmĕdi֥ym ʻal-ragĕléy⁠he֖m ẇ⁠pĕnéy⁠he֥m la⁠báֽ̇yiţ׃s"],[3,14,"וַ⁠יַּ֨עַשׂ֙ אֶת־הַ⁠פָּרֹ֔כֶת תְּכֵ֥לֶת וְ⁠אַרְגָּמָ֖ן וְ⁠כַרְמִ֣יל וּ⁠ב֑וּץ וַ⁠יַּ֥עַל עָלָ֖י⁠ו כְּרוּבִֽים׃ס","wa⁠yȧ֨ʻaş̂֙ ʼeţ-ha⁠pá̇rò֔keţ ţĕ̇ké֥leţ wĕ⁠ʼarĕgá̇má֖n wĕ⁠karĕmi֣yl ẇ⁠b֑ẇẕ wa⁠yȧ֥ʻal ʻálá֖y⁠w kĕ̇rẇbiֽym׃s"],[3,15,"וַ⁠יַּ֜עַשׂ לִ⁠פְנֵ֤י הַ⁠בַּ֨יִת֙ עַמּוּדִ֣ים שְׁנַ֔יִם אַמּ֕וֹת שְׁלֹשִׁ֥ים וְ⁠חָמֵ֖שׁ אֹ֑רֶךְ וְ⁠הַ⁠צֶּ֥פֶת אֲשֶׁר־עַל־רֹאשׁ֖⁠וֹ אַמּ֥וֹת חָמֵֽשׁ׃ס","wa⁠yȧ֜ʻaş̂ li⁠pĕné֤y ha⁠bȧ֨yiţ֙ ʻaṁẇdi֣ym şĕ̌na֔yim ʼaṁ֕wòţ şĕ̌lòşǐ֥ym wĕ⁠ẖámé֖ş̌ ʼò֑rekĕ wĕ⁠ha⁠ẕė֥peţ ʼàşěr-ʻal-ròʼş֖̌⁠wò ʼaṁ֥wòţ ẖáméֽş̌׃s"],[3,16,"וַ⁠יַּ֤עַשׂ שַׁרְשְׁרוֹת֙ בַּ⁠דְּבִ֔יר וַ⁠יִּתֵּ֖ן עַל־רֹ֣אשׁ הָ⁠עַמֻּדִ֑ים וַ⁠יַּ֤עַשׂ רִמּוֹנִים֙ מֵאָ֔ה וַ⁠יִּתֵּ֖ן בַּֽ⁠שַּׁרְשְׁרֽוֹת׃","wa⁠yȧ֤ʻaş̂ şǎrĕşĕ̌rwòţ֙ bȧ⁠dĕ̇bi֔yr wa⁠yi̇ţé֖̇n ʻal-rò֣ʼş̌ há⁠ʻamu̇di֑ym wa⁠yȧ֤ʻaş̂ riṁwòniym֙ méʼá֔h wa⁠yi̇ţé֖̇n bȧֽ⁠şȧ̌rĕşĕ̌rֽwòţ׃"],[3,17,"וַ⁠יָּ֤קֶם אֶת־הָֽ⁠עַמּוּדִים֙ עַל־פְּנֵ֣י הַ⁠הֵיכָ֔ל אֶחָ֥ד מִ⁠יָּמִ֖ין וְ⁠אֶחָ֣ד מֵֽ⁠הַ⁠שְּׂמֹ֑אול וַ⁠יִּקְרָ֤א שֵׁם־ה⁠ימיני יָכִ֔ין וְ⁠שֵׁ֥ם הַ⁠שְּׂמָאלִ֖י בֹּֽעַז׃ס","wa⁠yá֤̇qem ʼeţ-háֽ⁠ʻaṁẇdiym֙ ʻal-pĕ̇né֣y ha⁠héyká֔l ʼeẖá֥d mi⁠yá̇mi֖yn wĕ⁠ʼeẖá֣d méֽ⁠ha⁠şĕ̇̂mò֑ʼwl wa⁠yi̇qĕrá֤ʼ şé̌m-h⁠ymyny yáki֔yn wĕ⁠şé֥̌m ha⁠şĕ̇̂máʼli֖y bòֽ̇ʻaz׃s"],[4,1,"וַ⁠יַּ֨עַשׂ֙ מִזְבַּ֣ח נְחֹ֔שֶׁת עֶשְׂרִ֤ים אַמָּה֙ אָרְכּ֔⁠וֹ וְ⁠עֶשְׂרִ֥ים אַמָּ֖ה רָחְבּ֑⁠וֹ וְ⁠עֶ֥שֶׂר אַמּ֖וֹת קוֹמָתֽ⁠וֹ׃ס","wa⁠yȧ֨ʻaş̂֙ mizĕbȧ֣ẖ nĕẖò֔şěţ ʻeşĕ̂ri֤ym ʼamá̇h֙ ʼárĕk̇֔⁠wò wĕ⁠ʻeşĕ̂ri֥ym ʼamá֖̇h ráẖĕḃ֑⁠wò wĕ⁠ʻe֥şêr ʼaṁ֖wòţ qwòmáţֽ⁠wò׃s"],[4,2,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠יָּ֖ם מוּצָ֑ק עֶ֣שֶׂר בָּֽ֠⁠אַמָּה מִ⁠שְּׂפָת֨⁠וֹ אֶל־שְׂפָת֜⁠וֹ עָג֣וֹל ׀ סָבִ֗יב וְ⁠חָמֵ֤שׁ בָּֽ⁠אַמָּה֙ קֽוֹמָת֔⁠וֹ וְ⁠קָו֙ שְׁלֹשִׁ֣ים בָּֽ⁠אַמָּ֔ה יָסֹ֥ב אֹת֖⁠וֹ סָבִֽיב׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠yá֖̇m mẇẕá֑q ʻe֣şêr báֽ̇֠⁠ʼamá̇h mi⁠şĕ̇̂páţ֨⁠wò ʼel-şĕ̂páţ֜⁠wò ʻág֣wòl ׀ sábi֗yb wĕ⁠ẖámé֤ş̌ báֽ̇⁠ʼamá̇h֙ qֽwòmáţ֔⁠wò wĕ⁠qáw֙ şĕ̌lòşǐ֣ym báֽ̇⁠ʼamá̇֔h yásò֥b ʼòţ֖⁠wò sábiֽyb׃"],[4,3,"וּ⁠דְמ֣וּת בְּקָרִים֩ תַּ֨חַת ל֜⁠וֹ סָבִ֤יב ׀ סָבִיב֙ סוֹבְבִ֣ים אֹת֔⁠וֹ עֶ֚שֶׂר בָּֽ⁠אַמָּ֔ה מַקִּיפִ֥ים אֶת־הַ⁠יָּ֖ם סָבִ֑יב שְׁנַ֤יִם טוּרִים֙ הַ⁠בָּקָ֔ר יְצוּקִ֖ים בְּ⁠מֻֽצַקְתּֽ⁠וֹ׃","ẇ⁠dĕm֣ẇţ bĕ̇qáriym֩ ţȧ֨ẖaţ l֜⁠wò sábi֤yb ׀ sábiyb֙ swòbĕbi֣ym ʼòţ֔⁠wò ʻe֚şêr báֽ̇⁠ʼamá̇֔h maqi̇ypi֥ym ʼeţ-ha⁠yá֖̇m sábi֑yb şĕ̌na֤yim tẇriym֙ ha⁠bá̇qá֔r yĕẕẇqi֖ym bĕ̇⁠muֽẕaqĕţֽ̇⁠wò׃"],[4,4,"עוֹמֵ֞ד עַל־שְׁנֵ֧ים עָשָׂ֣ר בָּקָ֗ר שְׁלֹשָׁ֣ה פֹנִ֣ים ׀ צָפ֡וֹנָ⁠ה וּ⁠שְׁלוֹשָׁה֩ פֹנִ֨ים ׀ יָ֜מָּ⁠ה וּ⁠שְׁלֹשָׁ֣ה ׀ פֹּנִ֣ים נֶ֗גְבָּ⁠ה וּ⁠שְׁלֹשָׁה֙ פֹּנִ֣ים מִזְרָ֔חָ⁠ה וְ⁠הַ⁠יָּ֥ם עֲלֵי⁠הֶ֖ם מִ⁠לְ⁠מָ֑עְלָ⁠ה וְ⁠כָל־אֲחֹרֵי⁠הֶ֖ם בָּֽיְתָ⁠ה׃","ʻwòmé֞d ʻal-şĕ̌né֧ym ʻáşá֣̂r bá̇qá֗r şĕ̌lòşá֣̌h pòni֣ym ׀ ẕáp֡wòná⁠h ẇ⁠şĕ̌lwòşá̌h֩ pòni֨ym ׀ yá֜má̇⁠h ẇ⁠şĕ̌lòşá֣̌h ׀ pò̇ni֣ym ne֗gĕbá̇⁠h ẇ⁠şĕ̌lòşá̌h֙ pò̇ni֣ym mizĕrá֔ẖá⁠h wĕ⁠ha⁠yá֥̇m ʻàléy⁠he֖m mi⁠lĕ⁠má֑ʻĕlá⁠h wĕ⁠kál-ʼàẖòréy⁠he֖m báֽ̇yĕţá⁠h׃"],[4,5,"וְ⁠עָבְי֣⁠וֹ טֶ֔פַח וּ⁠שְׂפָת⁠וֹ֙ כְּ⁠מַעֲשֵׂ֣ה שְׂפַת־כּ֔וֹס פֶּ֖רַח שֽׁוֹשַׁנָּ֑ה מַחֲזִ֣יק בַּתִּ֔ים שְׁלֹ֥שֶׁת אֲלָפִ֖ים יָכִֽיל׃ס","wĕ⁠ʻábĕy֣⁠wò te֔paẖ ẇ⁠şĕ̂páţ⁠wò֙ kĕ̇⁠maʻàşé֣̂h şĕ̂paţ-k̇֔wòs pė֖raẖ şֽ̌wòşǎná֑̇h maẖàzi֣yq bȧţi̇֔ym şĕ̌lò֥şěţ ʼàlápi֖ym yákiֽyl׃s"],[4,6,"וַ⁠יַּ֣עַשׂ כִּיּוֹרִים֮ עֲשָׂרָה֒ וַ֠⁠יִּתֵּן חֲמִשָּׁ֨ה מִ⁠יָּמִ֜ין וַ⁠חֲמִשָּׁ֤ה מִ⁠שְּׂמֹאול֙ לְ⁠רָחְצָ֣ה בָ⁠הֶ֔ם אֶת־מַעֲשֵׂ֥ה הָ⁠עוֹלָ֖ה יָדִ֣יחוּ בָ֑⁠ם וְ⁠הַ⁠יָּ֕ם לְ⁠רָחְצָ֥ה לַ⁠כֹּהֲנִ֖ים בּֽ⁠וֹ׃ס","wa⁠yȧ֣ʻaş̂ ki̇ẏwòriym֮ ʻàşá̂ráh֒ wa֠⁠yi̇ţé̇n ẖàmişá̇̌֨h mi⁠yá̇mi֜yn wa⁠ẖàmişá֤̇̌h mi⁠şĕ̇̂mòʼwl֙ lĕ⁠ráẖĕẕá֣h bá⁠he֔m ʼeţ-maʻàşé֥̂h há⁠ʻwòlá֖h yádi֣yẖẇ bá֑⁠m wĕ⁠ha⁠yá̇֕m lĕ⁠ráẖĕẕá֥h la⁠kò̇hàni֖ym ḃֽ⁠wò׃s"],[4,7,"וַ֠⁠יַּעַשׂ אֶת־מְנֹר֧וֹת הַ⁠זָּהָ֛ב עֶ֖שֶׂר כְּ⁠מִשְׁפָּטָ֑⁠ם וַ⁠יִּתֵּן֙ בַּֽ⁠הֵיכָ֔ל חָמֵ֥שׁ מִ⁠יָּמִ֖ין וְ⁠חָמֵ֥שׁ מִ⁠שְּׂמֹֽאול׃ס","wa֠⁠yȧʻaş̂ ʼeţ-mĕnòr֧wòţ ha⁠zá̇há֛b ʻe֖şêr kĕ̇⁠mişĕ̌pá̇tá֑⁠m wa⁠yi̇ţé̇n֙ bȧֽ⁠héyká֔l ẖámé֥ş̌ mi⁠yá̇mi֖yn wĕ⁠ẖámé֥ş̌ mi⁠şĕ̇̂mòֽʼwl׃s"],[4,8,"וַ⁠יַּ֣עַשׂ שֻׁלְחָנוֹת֮ עֲשָׂרָה֒ וַ⁠יַּנַּח֙ בַּֽ⁠הֵיכָ֔ל חֲמִשָּׁ֥ה מִ⁠יָּמִ֖ין וַ⁠חֲמִשָּׁ֣ה מִ⁠שְּׂמֹ֑אול וַ⁠יַּ֛עַשׂ מִזְרְקֵ֥י זָהָ֖ב מֵאָֽה׃","wa⁠yȧ֣ʻaş̂ şǔlĕẖánwòţ֮ ʻàşá̂ráh֒ wa⁠yȧnȧẖ֙ bȧֽ⁠héyká֔l ẖàmişá֥̇̌h mi⁠yá̇mi֖yn wa⁠ẖàmişá֣̇̌h mi⁠şĕ̇̂mò֑ʼwl wa⁠yȧ֛ʻaş̂ mizĕrĕqé֥y záhá֖b méʼáֽh׃"],[4,9,"וַ⁠יַּ֨עַשׂ֙ חֲצַ֣ר הַ⁠כֹּהֲנִ֔ים וְ⁠הָ⁠עֲזָרָ֖ה הַ⁠גְּדוֹלָ֑ה וּ⁠דְלָת֧וֹת לָ⁠עֲזָרָ֛ה וְ⁠דַלְתוֹתֵי⁠הֶ֖ם צִפָּ֥ה נְחֹֽשֶׁת׃","wa⁠yȧ֨ʻaş̂֙ ẖàẕa֣r ha⁠kò̇hàni֔ym wĕ⁠há⁠ʻàzárá֖h ha⁠gĕ̇dwòlá֑h ẇ⁠dĕláţ֧wòţ lá⁠ʻàzárá֛h wĕ⁠dalĕţwòţéy⁠he֖m ẕipá֥̇h nĕẖòֽşěţ׃"],[4,10,"וְ⁠אֶת־הַ⁠יָּ֗ם נָתַ֞ן מִ⁠כֶּ֧תֶף הַ⁠יְמָנִ֛ית קֵ֖דְמָ⁠ה מִ⁠מּ֥וּל נֶֽגְבָּ⁠ה׃","wĕ⁠ʼeţ-ha⁠yá̇֗m náţa֞n mi⁠kė֧ţep ha⁠yĕmáni֛yţ qé֖dĕmá⁠h mi⁠ṁ֥ẇl neֽgĕbá̇⁠h׃"],[4,11,"וַ⁠יַּ֣עַשׂ חוּרָ֔ם אֶת־הַ֨⁠סִּיר֔וֹת וְ⁠אֶת־הַ⁠יָּעִ֖ים וְ⁠אֶת־הַ⁠מִּזְרָק֑וֹת ס וַ⁠יְכַ֣ל חירם לַ⁠עֲשׂוֹת֙ אֶת־הַ⁠מְּלָאכָ֔ה אֲשֶׁ֥ר עָשָׂ֛ה לַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה בְּ⁠בֵ֥ית הָ⁠אֱלֹהִֽים׃","wa⁠yȧ֣ʻaş̂ ẖẇrá֔m ʼeţ-ha֨⁠si̇yr֔wòţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֖ym wĕ⁠ʼeţ-ha⁠mi̇zĕráq֑wòţ s wa⁠yĕka֣l ẖyrm la⁠ʻàş̂wòţ֙ ʼeţ-ha⁠mĕ̇láʼká֔h ʼàşě֥r ʻáşá֛̂h la⁠mė֥lekĕ şĕ̌lòmò֖h bĕ̇⁠bé֥yţ há⁠ʼèlòhiֽym׃"],[4,12,"עַמּוּדִ֣ים שְׁנַ֔יִם וְ⁠הַ⁠גֻּלּ֧וֹת וְ⁠הַ⁠כֹּתָר֛וֹת עַל־רֹ֥אשׁ הָ⁠עַמּוּדִ֖ים שְׁתָּ֑יִם וְ⁠הַ⁠שְּׂבָכ֣וֹת שְׁתַּ֔יִם לְ⁠כַסּ֗וֹת אֶת־שְׁתֵּי֙ גֻּלּ֣וֹת הַ⁠כֹּֽתָר֔וֹת אֲשֶׁ֖ר עַל־רֹ֥אשׁ הָֽ⁠עַמּוּדִֽים׃","ʻaṁẇdi֣ym şĕ̌na֔yim wĕ⁠ha⁠gu̇l֧̇wòţ wĕ⁠ha⁠kò̇ţár֛wòţ ʻal-rò֥ʼş̌ há⁠ʻaṁẇdi֖ym şĕ̌ţá֑̇yim wĕ⁠ha⁠şĕ̇̂bák֣wòţ şĕ̌ţȧ֔yim lĕ⁠kaṡ֗wòţ ʼeţ-şĕ̌ţé̇y֙ gu̇l֣̇wòţ ha⁠kòֽ̇ţár֔wòţ ʼàşě֖r ʻal-rò֥ʼş̌ háֽ⁠ʻaṁẇdiֽym׃"],[4,13,"וְ⁠אֶת־הָֽ⁠רִמּוֹנִ֛ים אַרְבַּ֥ע מֵא֖וֹת לִ⁠שְׁתֵּ֣י הַ⁠שְּׂבָכ֑וֹת שְׁנַ֨יִם טוּרִ֤ים רִמּוֹנִים֙ לַ⁠שְּׂבָכָ֣ה הָ⁠אֶחָ֔ת לְ⁠כַסּ֗וֹת אֶת־שְׁתֵּי֙ גֻּלּ֣וֹת הַ⁠כֹּֽתָר֔וֹת אֲשֶׁ֖ר עַל־פְּנֵ֥י הָ⁠עַמּוּדִֽים׃","wĕ⁠ʼeţ-háֽ⁠riṁwòni֛ym ʼarĕbȧ֥ʻ méʼ֖wòţ li⁠şĕ̌ţé֣̇y ha⁠şĕ̇̂bák֑wòţ şĕ̌na֨yim tẇri֤ym riṁwòniym֙ la⁠şĕ̇̂báká֣h há⁠ʼeẖá֔ţ lĕ⁠kaṡ֗wòţ ʼeţ-şĕ̌ţé̇y֙ gu̇l֣̇wòţ ha⁠kòֽ̇ţár֔wòţ ʼàşě֖r ʻal-pĕ̇né֥y há⁠ʻaṁẇdiֽym׃"],[4,14,"וְ⁠אֶת־הַ⁠מְּכֹנ֖וֹת עָשָׂ֑ה וְ⁠אֶת־הַ⁠כִּיֹּר֥וֹת עָשָׂ֖ה עַל־הַ⁠מְּכֹנֽוֹת׃","wĕ⁠ʼeţ-ha⁠mĕ̇kòn֖wòţ ʻáşá֑̂h wĕ⁠ʼeţ-ha⁠ki̇yò̇r֥wòţ ʻáşá֖̂h ʻal-ha⁠mĕ̇kònֽwòţ׃"],[4,15,"אֶת־הַ⁠יָּ֖ם אֶחָ֑ד וְ⁠אֶת־הַ⁠בָּקָ֥ר שְׁנֵים־עָשָׂ֖ר תַּחְתָּֽי⁠ו׃","ʼeţ-ha⁠yá֖̇m ʼeẖá֑d wĕ⁠ʼeţ-ha⁠bá̇qá֥r şĕ̌néym-ʻáşá֖̂r ţȧẖĕţáֽ̇y⁠w׃"],[4,16,"וְ⁠אֶת־הַ֠⁠סִּירוֹת וְ⁠אֶת־הַ⁠יָּעִ֤ים וְ⁠אֶת־הַ⁠מִּזְלָגוֹת֙ וְ⁠אֶת־כָּל־כְּלֵי⁠הֶ֔ם עָשָׂ֞ה חוּרָ֥ם אָבִ֛יו לַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה לְ⁠בֵ֣ית יְהוָ֑ה נְחֹ֖שֶׁת מָרֽוּק׃","wĕ⁠ʼeţ-ha֠⁠si̇yrwòţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֤ym wĕ⁠ʼeţ-ha⁠mi̇zĕlágwòţ֙ wĕ⁠ʼeţ-ká̇l-kĕ̇léy⁠he֔m ʻáşá̂֞h ẖẇrá֥m ʼábi֛yw la⁠mė֥lekĕ şĕ̌lòmò֖h lĕ⁠bé֣yţ yĕhwá֑h nĕẖò֖şěţ márֽẇq׃"],[4,17,"בְּ⁠כִכַּ֤ר הַ⁠יַּרְדֵּן֙ יְצָקָ֣⁠ם הַ⁠מֶּ֔לֶךְ בַּ⁠עֲבִ֖י הָ⁠אֲדָמָ֑ה בֵּ֥ין סֻכּ֖וֹת וּ⁠בֵ֥ין צְרֵדָֽתָ⁠ה׃","bĕ̇⁠kikȧ֤r ha⁠yȧrĕdé̇n֙ yĕẕáqá֣⁠m ha⁠mė֔lekĕ bȧ⁠ʻàbi֖y há⁠ʼàdámá֑h bé֥̇yn suk֖̇wòţ ẇ⁠bé֥yn ẕĕrédáֽţá⁠h׃"],[4,18,"וַ⁠יַּ֧עַשׂ שְׁלֹמֹ֛ה כָּל־הַ⁠כֵּלִ֥ים הָ⁠אֵ֖לֶּה לָ⁠רֹ֣ב מְאֹ֑ד כִּ֛י לֹ֥א נֶחְקַ֖ר מִשְׁקַ֥ל הַ⁠נְּחֹֽשֶׁת׃פ","wa⁠yȧ֧ʻaş̂ şĕ̌lòmò֛h ká̇l-ha⁠ké̇li֥ym há⁠ʼé֖lėh lá⁠rò֣b mĕʼò֑d ki֛̇y lò֥ʼ neẖĕqa֖r mişĕ̌qa֥l ha⁠nĕ̇ẖòֽşěţ׃p"],[4,19,"וַ⁠יַּ֣עַשׂ שְׁלֹמֹ֔ה אֵ֚ת כָּל־הַ⁠כֵּלִ֔ים אֲשֶׁ֖ר בֵּ֣ית הָ⁠אֱלֹהִ֑ים וְ⁠אֵת֙ מִזְבַּ֣ח הַ⁠זָּהָ֔ב וְ⁠אֶת־הַ⁠שֻּׁלְחָנ֔וֹת וַ⁠עֲלֵי⁠הֶ֖ם לֶ֥חֶם הַ⁠פָּנִֽים׃","wa⁠yȧ֣ʻaş̂ şĕ̌lòmò֔h ʼé֚ţ ká̇l-ha⁠ké̇li֔ym ʼàşě֖r bé֣̇yţ há⁠ʼèlòhi֑ym wĕ⁠ʼéţ֙ mizĕbȧ֣ẖ ha⁠zá̇há֔b wĕ⁠ʼeţ-ha⁠şu̇̌lĕẖán֔wòţ wa⁠ʻàléy⁠he֖m le֥ẖem ha⁠pá̇niֽym׃"],[4,20,"וְ⁠אֶת־הַ⁠מְּנֹר֞וֹת וְ⁠נֵרֹתֵי⁠הֶ֗ם לְ⁠בַעֲרָ֧⁠ם כַּ⁠מִּשְׁפָּ֛ט לִ⁠פְנֵ֥י הַ⁠דְּבִ֖יר זָהָ֥ב סָגֽוּר׃","wĕ⁠ʼeţ-ha⁠mĕ̇nòr֞wòţ wĕ⁠néròţéy⁠he֗m lĕ⁠baʻàrá֧⁠m kȧ⁠mi̇şĕ̌pá֛̇t li⁠pĕné֥y ha⁠dĕ̇bi֖yr záhá֥b ságֽẇr׃"],[4,21,"וְ⁠הַ⁠פֶּ֧רַח וְ⁠הַ⁠נֵּר֛וֹת וְ⁠הַ⁠מֶּלְקַחַ֖יִם זָהָ֑ב ה֖וּא מִכְל֥וֹת זָהָֽב׃","wĕ⁠ha⁠pė֧raẖ wĕ⁠ha⁠né̇r֛wòţ wĕ⁠ha⁠mėlĕqaẖa֖yim záhá֑b h֖ẇʼ mikĕl֥wòţ záháֽb׃"],[4,22,"וְ⁠הַֽ⁠מְזַמְּר֧וֹת וְ⁠הַ⁠מִּזְרָק֛וֹת וְ⁠הַ⁠כַּפּ֥וֹת וְ⁠הַ⁠מַּחְתּ֖וֹת זָהָ֣ב סָג֑וּר וּ⁠פֶ֣תַח הַ֠⁠בַּיִת דַּלְתוֹתָ֨י⁠ו הַ⁠פְּנִימִיּ֜וֹת לְ⁠קֹ֣דֶשׁ הַ⁠קֳּדָשִׁ֗ים וְ⁠דַלְתֵ֥י הַ⁠בַּ֛יִת לַ⁠הֵיכָ֖ל זָהָֽב׃","wĕ⁠haֽ⁠mĕzamĕ̇r֧wòţ wĕ⁠ha⁠mi̇zĕráq֛wòţ wĕ⁠ha⁠kȧṗ֥wòţ wĕ⁠ha⁠mȧẖĕţ֖̇wòţ záhá֣b ság֑ẇr ẇ⁠pe֣ţaẖ ha֠⁠bȧyiţ dȧlĕţwòţá֨y⁠w ha⁠pĕ̇niymiẏ֜wòţ lĕ⁠qò֣deş̌ ha⁠qȯdáşǐ֗ym wĕ⁠dalĕţé֥y ha⁠bȧ֛yiţ la⁠héyká֖l záháֽb׃"],[5,1,"וַ⁠תִּשְׁלַם֙ כָּל־הַ⁠מְּלָאכָ֔ה אֲשֶׁר־עָשָׂ֥ה שְׁלֹמֹ֖ה לְ⁠בֵ֣ית יְהוָ֑ה ס וַ⁠יָּבֵ֨א שְׁלֹמֹ֜ה אֶת־קָדְשֵׁ֣י ׀ דָּוִ֣יד אָבִ֗י⁠ו וְ⁠אֶת־הַ⁠כֶּ֤סֶף וְ⁠אֶת־הַ⁠זָּהָב֙ וְ⁠אֶת־כָּל־הַ⁠כֵּלִ֔ים נָתַ֕ן בְּ⁠אֹצְר֖וֹת בֵּ֥ית הָ⁠אֱלֹהִֽים׃פ","wa⁠ţi̇şĕ̌lam֙ ká̇l-ha⁠mĕ̇láʼká֔h ʼàşěr-ʻáşá֥̂h şĕ̌lòmò֖h lĕ⁠bé֣yţ yĕhwá֑h s wa⁠yá̇bé֨ʼ şĕ̌lòmò֜h ʼeţ-qádĕşé֣̌y ׀ dá̇wi֣yd ʼábi֗y⁠w wĕ⁠ʼeţ-ha⁠kė֤sep wĕ⁠ʼeţ-ha⁠zá̇háb֙ wĕ⁠ʼeţ-ká̇l-ha⁠ké̇li֔ym náţa֕n bĕ̇⁠ʼòẕĕr֖wòţ bé֥̇yţ há⁠ʼèlòhiֽym׃p"],[5,2,"אָז֩ יַקְהֵ֨יל שְׁלֹמֹ֜ה אֶת־זִקְנֵ֣י יִשְׂרָאֵ֗ל וְ⁠אֶת־כָּל־רָאשֵׁ֨י הַ⁠מַּטּ֜וֹת נְשִׂיאֵ֧י הָ⁠אָב֛וֹת לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל אֶל־יְרוּשָׁלִָ֑ם לְֽ⁠הַעֲל֞וֹת אֶת־אֲר֧וֹן בְּרִית־יְהוָ֛ה מֵ⁠עִ֥יר דָּוִ֖יד הִ֥יא צִיּֽוֹן׃","ʼáz֩ yaqĕhé֨yl şĕ̌lòmò֜h ʼeţ-ziqĕné֣y yişĕ̂ráʼé֗l wĕ⁠ʼeţ-ká̇l-ráʼşé̌֨y ha⁠mȧṫ֜wòţ nĕşîyʼé֧y há⁠ʼáb֛wòţ li⁠bĕné֥y yişĕ̂ráʼé֖l ʼel-yĕrẇşá̌liá֑m lĕֽ⁠haʻàl֞wòţ ʼeţ-ʼàr֧wòn bĕ̇riyţ-yĕhwá֛h mé⁠ʻi֥yr dá̇wi֖yd hi֥yʼ ẕiẏֽwòn׃"],[5,3,"וַ⁠יִּקָּהֲל֧וּ אֶל־הַ⁠מֶּ֛לֶךְ כָּל־אִ֥ישׁ יִשְׂרָאֵ֖ל בֶּ⁠חָ֑ג ה֖וּא הַ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִעִֽי׃","wa⁠yi̇qá̇hàl֧ẇ ʼel-ha⁠mė֛lekĕ ká̇l-ʼi֥yş̌ yişĕ̂ráʼé֖l bė⁠ẖá֑g h֖ẇʼ ha⁠ẖò֥deş̌ ha⁠şĕ̇̌biʻiֽy׃"],[5,4,"וַ⁠יָּבֹ֕אוּ כֹּ֖ל זִקְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּשְׂא֥וּ הַ⁠לְוִיִּ֖ם אֶת־הָ⁠אָרֽוֹן׃","wa⁠yá̇bò֕ʼẇ kò֖̇l ziqĕné֣y yişĕ̂ráʼé֑l wa⁠yi̇şĕ̂ʼ֥ẇ ha⁠lĕwiyi֖̇m ʼeţ-há⁠ʼárֽwòn׃"],[5,5,"וַ⁠יַּעֲל֤וּ אֶת־הָ⁠אָרוֹן֙ וְ⁠אֶת־אֹ֣הֶל מוֹעֵ֔ד וְ⁠אֶת־כָּל־כְּלֵ֥י הַ⁠קֹּ֖דֶשׁ אֲשֶׁ֣ר בָּ⁠אֹ֑הֶל הֶעֱל֣וּ אֹתָ֔⁠ם הַ⁠כֹּהֲנִ֖ים הַ⁠לְוִיִּֽם׃","wa⁠yȧʻàl֤ẇ ʼeţ-há⁠ʼárwòn֙ wĕ⁠ʼeţ-ʼò֣hel mwòʻé֔d wĕ⁠ʼeţ-ká̇l-kĕ̇lé֥y ha⁠qò֖̇deş̌ ʼàşě֣r bá̇⁠ʼò֑hel heʻèl֣ẇ ʼòţá֔⁠m ha⁠kò̇hàni֖ym ha⁠lĕwiyiֽ̇m׃"],[5,6,"וְ⁠הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה וְ⁠כָל־עֲדַ֧ת יִשְׂרָאֵ֛ל הַ⁠נּוֹעָדִ֥ים עָלָ֖י⁠ו לִ⁠פְנֵ֣י הָ⁠אָר֑וֹן מְזַבְּחִים֙ צֹ֣אן וּ⁠בָקָ֔ר אֲשֶׁ֧ר לֹֽא־יִסָּפְר֛וּ וְ⁠לֹ֥א יִמָּנ֖וּ מֵ⁠רֹֽב׃","wĕ⁠ha⁠mė֣lekĕ şĕ̌lòmò֗h wĕ⁠kál-ʻàda֧ţ yişĕ̂ráʼé֛l ha⁠ṅwòʻádi֥ym ʻálá֖y⁠w li⁠pĕné֣y há⁠ʼár֑wòn mĕzabĕ̇ẖiym֙ ẕò֣ʼn ẇ⁠báqá֔r ʼàşě֧r lòֽʼ-yisá̇pĕr֛ẇ wĕ⁠lò֥ʼ yimá̇n֖ẇ mé⁠ròֽb׃"],[5,7,"וַ⁠יָּבִ֣יאוּ הַ֠⁠כֹּהֲנִים אֶת־אֲר֨וֹן בְּרִית־יְהוָ֧ה אֶל־מְקוֹמ֛⁠וֹ אֶל־דְּבִ֥יר הַ⁠בַּ֖יִת אֶל־קֹ֣דֶשׁ הַ⁠קְּדָשִׁ֑ים אֶל־תַּ֖חַת כַּנְפֵ֥י הַ⁠כְּרוּבִֽים׃","wa⁠yá̇bi֣yʼẇ ha֠⁠kò̇hàniym ʼeţ-ʼàr֨wòn bĕ̇riyţ-yĕhwá֧h ʼel-mĕqwòm֛⁠wò ʼel-dĕ̇bi֥yr ha⁠bȧ֖yiţ ʼel-qò֣deş̌ ha⁠qĕ̇dáşǐ֑ym ʼel-ţȧ֖ẖaţ kȧnĕpé֥y ha⁠kĕ̇rẇbiֽym׃"],[5,8,"וַ⁠יִּהְי֤וּ הַ⁠כְּרוּבִים֙ פֹּרְשִׂ֣ים כְּנָפַ֔יִם עַל־מְק֖וֹם הָ⁠אָר֑וֹן וַ⁠יְכַסּ֧וּ הַ⁠כְּרוּבִ֛ים עַל־הָ⁠אָר֥וֹן וְ⁠עַל־בַּדָּ֖י⁠ו מִ⁠לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇hĕy֤ẇ ha⁠kĕ̇rẇbiym֙ pò̇rĕşî֣ym kĕ̇nápa֔yim ʻal-mĕq֖wòm há⁠ʼár֑wòn wa⁠yĕkaṡ֧ẇ ha⁠kĕ̇rẇbi֛ym ʻal-há⁠ʼár֥wòn wĕ⁠ʻal-bȧdá֖̇y⁠w mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[5,9,"וַֽ⁠יַּאֲרִיכוּ֮ הַ⁠בַּדִּים֒ וַ⁠יֵּרָאוּ֩ רָאשֵׁ֨י הַ⁠בַּדִּ֤ים מִן־הָ⁠אָרוֹן֙ עַל־פְּנֵ֣י הַ⁠דְּבִ֔יר וְ⁠לֹ֥א יֵרָא֖וּ הַ⁠ח֑וּצָ⁠ה וַֽ⁠יְהִי־שָׁ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","waֽ⁠yȧʼàriykẇ֮ ha⁠bȧdi̇ym֒ wa⁠yé̇ráʼẇ֩ ráʼşé̌֨y ha⁠bȧdi֤̇ym min-há⁠ʼárwòn֙ ʻal-pĕ̇né֣y ha⁠dĕ̇bi֔yr wĕ⁠lò֥ʼ yéráʼ֖ẇ ha⁠ẖ֑ẇẕá⁠h waֽ⁠yĕhiy-şá̌֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[5,10,"אֵ֚ין בָּֽ⁠אָר֔וֹן רַ֚ק שְׁנֵ֣י הַ⁠לֻּח֔וֹת אֲשֶׁר־נָתַ֥ן מֹשֶׁ֖ה בְּ⁠חֹרֵ֑ב אֲשֶׁ֨ר כָּרַ֤ת יְהוָה֙ עִם־בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠צֵאתָ֖⁠ם מִ⁠מִּצְרָֽיִם׃פ","ʼé֚yn báֽ̇⁠ʼár֔wòn ra֚q şĕ̌né֣y ha⁠lu̇ẖ֔wòţ ʼàşěr-náţa֥n mòşě֖h bĕ̇⁠ẖòré֑b ʼàşě֨r ká̇ra֤ţ yĕhwáh֙ ʻim-bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠ẕéʼţá֖⁠m mi⁠mi̇ẕĕráֽyim׃p"],[5,11,"וַ⁠יְהִ֕י בְּ⁠צֵ֥את הַ⁠כֹּהֲנִ֖ים מִן־הַ⁠קֹּ֑דֶשׁ כִּ֠י כָּל־הַ⁠כֹּהֲנִ֤ים הַֽ⁠נִּמְצְאִים֙ הִתְקַדָּ֔שׁוּ אֵ֖ין לִ⁠שְׁמ֥וֹר לְ⁠מַחְלְקֽוֹת׃","wa⁠yĕhi֕y bĕ̇⁠ẕé֥ʼţ ha⁠kò̇hàni֖ym min-ha⁠qò֑̇deş̌ ki̇֠y ká̇l-ha⁠kò̇hàni֤ym haֽ⁠ni̇mĕẕĕʼiym֙ hiţĕqadá̇֔ş̌ẇ ʼé֖yn li⁠şĕ̌m֥wòr lĕ⁠maẖĕlĕqֽwòţ׃"],[5,12,"וְ⁠הַ⁠לְוִיִּ֣ם הַ⁠מְשֹׁרֲרִ֣ים לְ⁠כֻלָּ֡⁠ם לְ⁠אָסָ֡ף לְ⁠הֵימָ֣ן לִֽ֠⁠ידֻתוּן וְ⁠לִ⁠בְנֵי⁠הֶ֨ם וְ⁠לַ⁠אֲחֵי⁠הֶ֜ם מְלֻבָּשִׁ֣ים בּ֗וּץ בִּ⁠מְצִלְתַּ֨יִם֙ וּ⁠בִ⁠נְבָלִ֣ים וְ⁠כִנֹּר֔וֹת עֹמְדִ֖ים מִזְרָ֣ח לַ⁠מִּזְבֵּ֑חַ וְ⁠עִמָּ⁠הֶ֤ם כֹּֽהֲנִים֙ לְ⁠מֵאָ֣ה וְ⁠עֶשְׂרִ֔ים מחצררים בַּ⁠חֲצֹֽצְרֽוֹת׃","wĕ⁠ha⁠lĕwiyi֣̇m ha⁠mĕşò̌ràri֣ym lĕ⁠kulá̇֡⁠m lĕ⁠ʼásá֡p lĕ⁠héymá֣n liֽ֠⁠yduţẇn wĕ⁠li⁠bĕnéy⁠he֨m wĕ⁠la⁠ʼàẖéy⁠he֜m mĕlubá̇şǐ֣ym ḃ֗ẇẕ bi̇⁠mĕẕilĕţȧ֨yim֙ ẇ⁠bi⁠nĕbáli֣ym wĕ⁠kinò̇r֔wòţ ʻòmĕdi֖ym mizĕrá֣ẖ la⁠mi̇zĕbé֑̇ẖa wĕ⁠ʻimá̇⁠he֤m kòֽ̇hàniym֙ lĕ⁠méʼá֣h wĕ⁠ʻeşĕ̂ri֔ym mẖẕrrym bȧ⁠ẖàẕòֽẕĕrֽwòţ׃"],[5,13,"וַ⁠יְהִ֣י כְ֠⁠אֶחָד ל⁠מחצצרים וְ⁠לַ⁠מְשֹֽׁרֲרִ֜ים לְ⁠הַשְׁמִ֣יעַ קוֹל־אֶחָ֗ד לְ⁠הַלֵּ֣ל וּ⁠לְ⁠הֹדוֹת֮ לַ⁠יהוָה֒ וּ⁠כְ⁠הָרִ֣ים ק֠וֹל בַּ⁠חֲצֹצְר֨וֹת וּ⁠בִ⁠מְצִלְתַּ֜יִם וּ⁠בִ⁠כְלֵ֣י הַ⁠שִּׁ֗יר וּ⁠בְ⁠הַלֵּ֤ל לַ⁠יהוָה֙ כִּ֣י ט֔וֹב כִּ֥י לְ⁠עוֹלָ֖ם חַסְדּ֑⁠וֹ וְ⁠הַ⁠בַּ֛יִת מָלֵ֥א עָנָ֖ן בֵּ֥ית יְהוָֽה׃","wa⁠yĕhi֣y kĕ֠⁠ʼeẖád l⁠mẖẕẕrym wĕ⁠la⁠mĕşòֽ̌ràri֜ym lĕ⁠haşĕ̌mi֣yʻa qwòl-ʼeẖá֗d lĕ⁠halé֣̇l ẇ⁠lĕ⁠hòdwòţ֮ la⁠yhwáh֒ ẇ⁠kĕ⁠hári֣ym q֠wòl bȧ⁠ẖàẕòẕĕr֨wòţ ẇ⁠bi⁠mĕẕilĕţȧ֜yim ẇ⁠bi⁠kĕlé֣y ha⁠şi̇̌֗yr ẇ⁠bĕ⁠halé֤̇l la⁠yhwáh֙ ki֣̇y t֔wòb ki֥̇y lĕ⁠ʻwòlá֖m ẖasĕḋ֑⁠wò wĕ⁠ha⁠bȧ֛yiţ málé֥ʼ ʻáná֖n bé֥̇yţ yĕhwáֽh׃"],[5,14,"וְ⁠לֹא־יָֽכְל֧וּ הַ⁠כֹּהֲנִ֛ים לַ⁠עֲמ֥וֹד לְ⁠שָׁרֵ֖ת מִ⁠פְּנֵ֣י הֶ⁠עָנָ֑ן כִּֽי־מָלֵ֥א כְבוֹד־יְהוָ֖ה אֶת־בֵּ֥ית הָ⁠אֱלֹהִֽים׃פ","wĕ⁠lòʼ-yֽákĕl֧ẇ ha⁠kò̇hàni֛ym la⁠ʻàm֥wòd lĕ⁠şá̌ré֖ţ mi⁠pĕ̇né֣y he⁠ʻáná֑n kiֽ̇y-málé֥ʼ kĕbwòd-yĕhwá֖h ʼeţ-bé֥̇yţ há⁠ʼèlòhiֽym׃p"],[6,1,"אָ֖ז אָמַ֣ר שְׁלֹמֹ֑ה יְהוָ֣ה אָמַ֔ר לִ⁠שְׁכּ֖וֹן בָּ⁠עֲרָפֶֽל׃","ʼá֖z ʼáma֣r şĕ̌lòmò֑h yĕhwá֣h ʼáma֔r li⁠şĕ̌k֖̇wòn bá̇⁠ʻàrápeֽl׃"],[6,2,"וַֽ⁠אֲנִ֛י בָּנִ֥יתִי בֵית־זְבֻ֖ל לָ֑⁠ךְ וּ⁠מָכ֥וֹן לְ⁠שִׁבְתְּ⁠ךָ֖ עוֹלָמִֽים׃","waֽ⁠ʼàni֛y bá̇ni֥yţiy béyţ-zĕbu֖l lá֑⁠kĕ ẇ⁠mák֥wòn lĕ⁠şǐbĕţĕ̇⁠ká֖ ʻwòlámiֽym׃"],[6,3,"וַ⁠יַּסֵּ֤ב הַ⁠מֶּ֨לֶךְ֙ אֶת־פָּנָ֔י⁠ו וַ⁠יְבָ֕רֶךְ אֵ֖ת כָּל־קְהַ֣ל יִשְׂרָאֵ֑ל וְ⁠כָל־קְהַ֥ל יִשְׂרָאֵ֖ל עוֹמֵֽד׃","wa⁠yȧsé֤̇b ha⁠mė֨lekĕ֙ ʼeţ-pá̇ná֔y⁠w wa⁠yĕbá֕rekĕ ʼé֖ţ ká̇l-qĕha֣l yişĕ̂ráʼé֑l wĕ⁠kál-qĕha֥l yişĕ̂ráʼé֖l ʻwòméֽd׃"],[6,4,"וַ⁠יֹּ֗אמֶר בָּר֤וּךְ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר֙ דִּבֶּ֣ר בְּ⁠פִ֔י⁠ו אֵ֖ת דָּוִ֣יד אָבִ֑⁠י וּ⁠בְ⁠יָדָ֥י⁠ו מִלֵּ֖א לֵ⁠אמֹֽר׃","wa⁠yò̇֗ʼmer bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşěr֙ di̇bė֣r bĕ̇⁠pi֔y⁠w ʼé֖ţ dá̇wi֣yd ʼábi֑⁠y ẇ⁠bĕ⁠yádá֥y⁠w milé֖̇ʼ lé⁠ʼmòֽr׃"],[6,5,"מִן־הַ⁠יּ֗וֹם אֲשֶׁ֨ר הוֹצֵ֣אתִי אֶת־עַמִּ⁠י֮ מֵ⁠אֶ֣רֶץ מִצְרַיִם֒ לֹא־בָחַ֣רְתִּֽי בְ⁠עִ֗יר מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל לִ⁠בְנ֣וֹת בַּ֔יִת לִ⁠הְי֥וֹת שְׁמִ֖⁠י שָׁ֑ם וְ⁠לֹא־בָחַ֣רְתִּֽי בְ⁠אִ֔ישׁ לִ⁠הְי֥וֹת נָגִ֖יד עַל־עַמִּ֥⁠י יִשְׂרָאֵֽל׃","min-ha⁠ẏ֗wòm ʼàşě֨r hwòẕé֣ʼţiy ʼeţ-ʻami̇⁠y֮ mé⁠ʼe֣reẕ miẕĕrayim֒ lòʼ-báẖa֣rĕţiֽ̇y bĕ⁠ʻi֗yr mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l li⁠bĕn֣wòţ bȧ֔yiţ li⁠hĕy֥wòţ şĕ̌mi֖⁠y şá֑̌m wĕ⁠lòʼ-báẖa֣rĕţiֽ̇y bĕ⁠ʼi֔yş̌ li⁠hĕy֥wòţ nági֖yd ʻal-ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[6,6,"וָ⁠אֶבְחַר֙ בִּ⁠יר֣וּשָׁלִַ֔ם לִ⁠הְי֥וֹת שְׁמִ֖⁠י שָׁ֑ם וָ⁠אֶבְחַ֣ר בְּ⁠דָוִ֔יד לִ⁠הְי֖וֹת עַל־עַמִּ֥⁠י יִשְׂרָאֵֽל׃","wá⁠ʼebĕẖar֙ bi̇⁠yr֣ẇşá̌lia֔m li⁠hĕy֥wòţ şĕ̌mi֖⁠y şá֑̌m wá⁠ʼebĕẖa֣r bĕ̇⁠dáwi֔yd li⁠hĕy֖wòţ ʻal-ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[6,7,"וַ⁠יְהִ֕י עִם־לְבַ֖ב דָּוִ֣יד אָבִ֑⁠י לִ⁠בְנ֣וֹת בַּ֔יִת לְ⁠שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕhi֕y ʻim-lĕba֖b dá̇wi֣yd ʼábi֑⁠y li⁠bĕn֣wòţ bȧ֔yiţ lĕ⁠şé֥̌m yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[6,8,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־דָּוִ֣יד אָבִ֔⁠י יַ֗עַן אֲשֶׁ֤ר הָיָה֙ עִם־לְבָ֣בְ⁠ךָ֔ לִ⁠בְנ֥וֹת בַּ֖יִת לִ⁠שְׁמִ֑⁠י הֱֽטִיב֔וֹתָ כִּ֥י הָיָ֖ה עִם־לְבָבֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-dá̇wi֣yd ʼábi֔⁠y ya֗ʻan ʼàşě֤r háyáh֙ ʻim-lĕbá֣bĕ⁠ká֔ li⁠bĕn֥wòţ bȧ֖yiţ li⁠şĕ̌mi֑⁠y hèֽtiyb֔wòţá ki֥̇y háyá֖h ʻim-lĕbábeֽ⁠ká׃"],[6,9,"רַ֣ק אַתָּ֔ה לֹ֥א תִבְנֶ֖ה הַ⁠בָּ֑יִת כִּ֤י בִנְ⁠ךָ֙ הַ⁠יּוֹצֵ֣א מֵֽ⁠חֲלָצֶ֔י⁠ךָ הֽוּא־יִבְנֶ֥ה הַ⁠בַּ֖יִת לִ⁠שְׁמִֽ⁠י׃","ra֣q ʼaţá̇֔h lò֥ʼ ţibĕne֖h ha⁠bá֑̇yiţ ki֤̇y binĕ⁠ká֙ ha⁠ẏwòẕé֣ʼ méֽ⁠ẖàláẕe֔y⁠ká hֽẇʼ-yibĕne֥h ha⁠bȧ֖yiţ li⁠şĕ̌miֽ⁠y׃"],[6,10,"וַ⁠יָּ֣קֶם יְהוָ֔ה אֶת־דְּבָר֖⁠וֹ אֲשֶׁ֣ר דִּבֵּ֑ר וָ⁠אָק֡וּם תַּחַת֩ דָּוִ֨יד אָבִ֜⁠י וָ⁠אֵשֵׁ֣ב ׀ עַל־כִּסֵּ֣א יִשְׂרָאֵ֗ל כַּ⁠אֲשֶׁר֙ דִּבֶּ֣ר יְהוָ֔ה וָ⁠אֶבְנֶ֣ה הַ⁠בַּ֔יִת לְ⁠שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yá֣̇qem yĕhwá֔h ʼeţ-dĕ̇bár֖⁠wò ʼàşě֣r di̇bé֑̇r wá⁠ʼáq֡ẇm ţȧẖaţ֩ dá̇wi֨yd ʼábi֜⁠y wá⁠ʼéşé֣̌b ׀ ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֗l kȧ⁠ʼàşěr֙ di̇bė֣r yĕhwá֔h wá⁠ʼebĕne֣h ha⁠bȧ֔yiţ lĕ⁠şé֥̌m yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[6,11,"וָ⁠אָשִׂ֥ים שָׁם֙ אֶת־הָ֣⁠אָר֔וֹן אֲשֶׁר־שָׁ֖ם בְּרִ֣ית יְהוָ֑ה אֲשֶׁ֥ר כָּרַ֖ת עִם־בְּנֵ֥י יִשְׂרָאֵֽל׃","wá⁠ʼáşî֥ym şá̌m֙ ʼeţ-há֣⁠ʼár֔wòn ʼàşěr-şá֖̌m bĕ̇ri֣yţ yĕhwá֑h ʼàşě֥r ká̇ra֖ţ ʻim-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[6,12,"וַֽ⁠יַּעֲמֹ֗ד לִ⁠פְנֵי֙ מִזְבַּ֣ח יְהוָ֔ה נֶ֖גֶד כָּל־קְהַ֣ל יִשְׂרָאֵ֑ל וַ⁠יִּפְרֹ֖שׂ כַּפָּֽי⁠ו׃","waֽ⁠yȧʻàmò֗d li⁠pĕnéy֙ mizĕbȧ֣ẖ yĕhwá֔h ne֖ged ká̇l-qĕha֣l yişĕ̂ráʼé֑l wa⁠yi̇pĕrò֖ş̂ kȧpáֽ̇y⁠w׃"],[6,13,"כִּֽי־עָשָׂ֨ה שְׁלֹמֹ֜ה כִּיּ֣וֹר נְחֹ֗שֶׁת וַֽ⁠יִּתְּנֵ⁠הוּ֮ בְּ⁠ת֣וֹךְ הָ⁠עֲזָרָה֒ חָמֵ֨שׁ אַמּ֜וֹת אָרְכּ֗⁠וֹ וְ⁠חָמֵ֤שׁ אַמּוֹת֙ רָחְבּ֔⁠וֹ וְ⁠אַמּ֥וֹת שָׁל֖וֹשׁ קוֹמָת֑⁠וֹ וַ⁠יַּעֲמֹ֣ד עָלָ֗י⁠ו וַ⁠יִּבְרַ֤ךְ עַל־בִּרְכָּי⁠ו֙ נֶ֚גֶד כָּל־קְהַ֣ל יִשְׂרָאֵ֔ל וַ⁠יִּפְרֹ֥שׂ כַּפָּ֖י⁠ו הַ⁠שָּׁמָֽיְמָ⁠ה׃","kiֽ̇y-ʻáşá̂֨h şĕ̌lòmò֜h ki̇ẏ֣wòr nĕẖò֗şěţ waֽ⁠yi̇ţĕ̇né⁠hẇ֮ bĕ̇⁠ţ֣wòkĕ há⁠ʻàzáráh֒ ẖámé֨ş̌ ʼaṁ֜wòţ ʼárĕk̇֗⁠wò wĕ⁠ẖámé֤ş̌ ʼaṁwòţ֙ ráẖĕḃ֔⁠wò wĕ⁠ʼaṁ֥wòţ şá̌l֖wòş̌ qwòmáţ֑⁠wò wa⁠yȧʻàmò֣d ʻálá֗y⁠w wa⁠yi̇bĕra֤kĕ ʻal-bi̇rĕká̇y⁠w֙ ne֚ged ká̇l-qĕha֣l yişĕ̂ráʼé֔l wa⁠yi̇pĕrò֥ş̂ kȧpá֖̇y⁠w ha⁠şá̇̌máֽyĕmá⁠h׃"],[6,14,"וַ⁠יֹּאמַ֗ר יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ אֵין־כָּמ֣וֹ⁠ךָ אֱלֹהִ֔ים בַּ⁠שָּׁמַ֖יִם וּ⁠בָ⁠אָ֑רֶץ שֹׁמֵ֤ר הַ⁠בְּרִית֙ וְֽ⁠הַ⁠חֶ֔סֶד לַ⁠עֲבָדֶ֕י⁠ךָ הַ⁠הֹלְכִ֥ים לְ⁠פָנֶ֖י⁠ךָ בְּ⁠כָל־לִבָּֽ⁠ם׃","wa⁠yò̇ʼma֗r yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ ʼéyn-ká̇m֣wò⁠ká ʼèlòhi֔ym bȧ⁠şá̇̌ma֖yim ẇ⁠bá⁠ʼá֑reẕ şò̌mé֤r ha⁠bĕ̇riyţ֙ wĕֽ⁠ha⁠ẖe֔sed la⁠ʻàbáde֕y⁠ká ha⁠hòlĕki֥ym lĕ⁠páne֖y⁠ká bĕ̇⁠kál-libáֽ̇⁠m׃"],[6,15,"אֲשֶׁ֣ר שָׁמַ֗רְתָּ לְ⁠עַבְדְּ⁠ךָ֙ דָּוִ֣יד אָבִ֔⁠י אֵ֥ת אֲשֶׁר־דִּבַּ֖רְתָּ ל֑⁠וֹ וַ⁠תְּדַבֵּ֥ר בְּ⁠פִ֛י⁠ךָ וּ⁠בְ⁠יָדְ⁠ךָ֥ מִלֵּ֖אתָ כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ʼàşě֣r şá̌ma֗rĕţá̇ lĕ⁠ʻabĕdĕ̇⁠ká֙ dá̇wi֣yd ʼábi֔⁠y ʼé֥ţ ʼàşěr-di̇bȧ֖rĕţá̇ l֑⁠wò wa⁠ţĕ̇dabé֥̇r bĕ̇⁠pi֛y⁠ká ẇ⁠bĕ⁠yádĕ⁠ká֥ milé֖̇ʼţá kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[6,16,"וְ⁠עַתָּ֞ה יְהוָ֣ה ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל שְׁ֠מֹר לְ⁠עַבְדְּ⁠ךָ֨ דָוִ֤יד אָבִ⁠י֙ אֵת֩ אֲשֶׁ֨ר דִּבַּ֤רְתָּ לּ⁠וֹ֙ לֵ⁠אמֹ֔ר לֹא־יִכָּרֵ֨ת לְ⁠ךָ֥ אִישׁ֙ מִ⁠לְּ⁠פָנַ֔⁠י יוֹשֵׁ֖ב עַל־כִּסֵּ֣א יִשְׂרָאֵ֑ל רַ֠ק אִם־יִשְׁמְר֨וּ בָנֶ֜י⁠ךָ אֶת־דַּרְכָּ֗⁠ם לָ⁠לֶ֨כֶת֙ בְּ⁠ת֣וֹרָתִ֔⁠י כַּ⁠אֲשֶׁ֥ר הָלַ֖כְתָּ לְ⁠פָנָֽ⁠י׃","wĕ⁠ʻaţá̇֞h yĕhwá֣h ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l şĕ̌֠mòr lĕ⁠ʻabĕdĕ̇⁠ká֨ dáwi֤yd ʼábi⁠y֙ ʼéţ֩ ʼàşě֨r di̇bȧ֤rĕţá̇ l̇⁠wò֙ lé⁠ʼmò֔r lòʼ-yiká̇ré֨ţ lĕ⁠ká֥ ʼiyş̌֙ mi⁠lĕ̇⁠pána֔⁠y ywòşé֖̌b ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֑l ra֠q ʼim-yişĕ̌mĕr֨ẇ báne֜y⁠ká ʼeţ-dȧrĕká̇֗⁠m lá⁠le֨keţ֙ bĕ̇⁠ţ֣wòráţi֔⁠y kȧ⁠ʼàşě֥r hála֖kĕţá̇ lĕ⁠pánáֽ⁠y׃"],[6,17,"וְ⁠עַתָּ֕ה יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל יֵֽאָמֵן֙ דְּבָ֣רְ⁠ךָ֔ אֲשֶׁ֥ר דִּבַּ֖רְתָּ לְ⁠עַבְדְּ⁠ךָ֥ לְ⁠דָוִֽיד׃","wĕ⁠ʻaţá̇֕h yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l yéֽʼámén֙ dĕ̇bá֣rĕ⁠ká֔ ʼàşě֥r di̇bȧ֖rĕţá̇ lĕ⁠ʻabĕdĕ̇⁠ká֥ lĕ⁠dáwiֽyd׃"],[6,18,"כִּ֚י הַֽ⁠אֻמְנָ֔ם יֵשֵׁ֧ב אֱלֹהִ֛ים אֶת־הָ⁠אָדָ֖ם עַל־הָ⁠אָ֑רֶץ הִ֠נֵּה שָׁמַ֜יִם וּ⁠שְׁמֵ֤י הַ⁠שָּׁמַ֨יִם֙ לֹ֣א יְכַלְכְּל֔וּ⁠ךָ אַ֕ף כִּֽי־הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי׃","ki֚̇y haֽ⁠ʼumĕná֔m yéşé֧̌b ʼèlòhi֛ym ʼeţ-há⁠ʼádá֖m ʻal-há⁠ʼá֑reẕ hi֠né̇h şá̌ma֜yim ẇ⁠şĕ̌mé֤y ha⁠şá̇̌ma֨yim֙ lò֣ʼ yĕkalĕkĕ̇l֔ẇ⁠ká ʼa֕p kiֽ̇y-ha⁠bȧ֥yiţ ha⁠zė֖h ʼàşě֥r bá̇niֽyţiy׃"],[6,19,"וּ⁠פָנִ֜יתָ אֶל־תְּפִלַּ֧ת עַבְדְּ⁠ךָ֛ וְ⁠אֶל־תְּחִנָּת֖⁠וֹ יְהוָ֣ה אֱלֹהָ֑⁠י לִ⁠שְׁמֹ֤עַ אֶל־הָ⁠רִנָּה֙ וְ⁠אֶל־הַ⁠תְּפִלָּ֔ה אֲשֶׁ֥ר עַבְדְּ⁠ךָ֖ מִתְפַּלֵּ֥ל לְ⁠פָנֶֽי⁠ךָ׃","ẇ⁠páni֜yţá ʼel-ţĕ̇pilȧ֧ţ ʻabĕdĕ̇⁠ká֛ wĕ⁠ʼel-ţĕ̇ẖiná̇ţ֖⁠wò yĕhwá֣h ʼèlòhá֑⁠y li⁠şĕ̌mò֤ʻa ʼel-há⁠riná̇h֙ wĕ⁠ʼel-ha⁠ţĕ̇pilá̇֔h ʼàşě֥r ʻabĕdĕ̇⁠ká֖ miţĕpȧlé֥̇l lĕ⁠páneֽy⁠ká׃"],[6,20,"לִ⁠הְיוֹת֩ עֵינֶ֨י⁠ךָ פְתֻח֜וֹת אֶל־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ יוֹמָ֣ם וָ⁠לַ֔יְלָה אֶל־הַ֨⁠מָּק֔וֹם אֲשֶׁ֣ר אָמַ֔רְתָּ לָ⁠שׂ֥וּם שִׁמְ⁠ךָ֖ שָׁ֑ם לִ⁠שְׁמ֨וֹעַ֙ אֶל־הַ⁠תְּפִלָּ֔ה אֲשֶׁ֣ר יִתְפַּלֵּ֣ל עַבְדְּ⁠ךָ֔ אֶל־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","li⁠hĕywòţ֩ ʻéyne֨y⁠ká pĕţuẖ֜wòţ ʼel-ha⁠bȧ֤yiţ ha⁠zėh֙ ywòmá֣m wá⁠la֔yĕláh ʼel-ha֨⁠má̇q֔wòm ʼàşě֣r ʼáma֔rĕţá̇ lá⁠ş֥̂ẇm şǐmĕ⁠ká֖ şá֑̌m li⁠şĕ̌m֨wòʻa֙ ʼel-ha⁠ţĕ̇pilá̇֔h ʼàşě֣r yiţĕpȧlé֣̇l ʻabĕdĕ̇⁠ká֔ ʼel-ha⁠má̇q֖wòm ha⁠zėֽh׃"],[6,21,"וְ⁠שָׁ֨מַעְתָּ֜ אֶל־תַּחֲנוּנֵ֤י עַבְדְּ⁠ךָ֙ וְ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר יִֽתְפַּֽלְל֖וּ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וְ֠⁠אַתָּה תִּשְׁמַ֞ע מִ⁠מְּק֤וֹם שִׁבְתְּ⁠ךָ֙ מִן־הַ⁠שָּׁמַ֔יִם וְ⁠שָׁמַעְתָּ֖ וְ⁠סָלָֽחְתָּ׃","wĕ⁠şá̌֨maʻĕţá̇֜ ʼel-ţȧẖànẇné֤y ʻabĕdĕ̇⁠ká֙ wĕ⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l ʼàşě֥r yiֽţĕpȧֽlĕl֖ẇ ʼel-ha⁠má̇q֣wòm ha⁠zė֑h wĕ֠⁠ʼaţá̇h ţi̇şĕ̌ma֞ʻ mi⁠mĕ̇q֤wòm şǐbĕţĕ̇⁠ká֙ min-ha⁠şá̇̌ma֔yim wĕ⁠şá̌maʻĕţá֖̇ wĕ⁠sáláֽẖĕţá̇׃"],[6,22,"אִם־יֶחֱטָ֥א אִישׁ֙ לְ⁠רֵעֵ֔⁠הוּ וְ⁠נָֽשָׁא־ב֥⁠וֹ אָלָ֖ה לְ⁠הַֽאֲלֹת֑⁠וֹ וּ⁠בָ֗א אָלָ֛ה לִ⁠פְנֵ֥י מִֽזְבַּחֲ⁠ךָ֖ בַּ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ʼim-yeẖètá֥ʼ ʼiyş̌֙ lĕ⁠réʻé֔⁠hẇ wĕ⁠náֽşá̌ʼ-b֥⁠wò ʼálá֖h lĕ⁠haֽʼàlòţ֑⁠wò ẇ⁠bá֗ʼ ʼálá֛h li⁠pĕné֥y miֽzĕbȧẖà⁠ká֖ bȧ⁠bȧ֥yiţ ha⁠zėֽh׃"],[6,23,"וְ⁠אַתָּ֣ה ׀ תִּשְׁמַ֣ע מִן־הַ⁠שָּׁמַ֗יִם וְ⁠עָשִׂ֨יתָ֙ וְ⁠שָׁפַטְתָּ֣ אֶת־עֲבָדֶ֔י⁠ךָ לְ⁠הָשִׁ֣יב לְ⁠רָשָׁ֔ע לָ⁠תֵ֥ת דַּרְכּ֖⁠וֹ בְּ⁠רֹאשׁ֑⁠וֹ וּ⁠לְ⁠הַצְדִּ֣יק צַדִּ֔יק לָ֥⁠תֶת ל֖⁠וֹ כְּ⁠צִדְקָתֽ⁠וֹ׃ס","wĕ⁠ʼaţá֣̇h ׀ ţi̇şĕ̌ma֣ʻ min-ha⁠şá̇̌ma֗yim wĕ⁠ʻáşî֨yţá֙ wĕ⁠şá̌patĕţá֣̇ ʼeţ-ʻàbáde֔y⁠ká lĕ⁠háşǐ֣yb lĕ⁠ráşá̌֔ʻ lá⁠ţé֥ţ dȧrĕk֖̇⁠wò bĕ̇⁠ròʼş֑̌⁠wò ẇ⁠lĕ⁠haẕĕdi֣̇yq ẕadi̇֔yq lá֥⁠ţeţ l֖⁠wò kĕ̇⁠ẕidĕqáţֽ⁠wò׃s"],[6,24,"וְֽ⁠אִם־יִנָּגֵ֞ף עַמְּ⁠ךָ֧ יִשְׂרָאֵ֛ל לִ⁠פְנֵ֥י אוֹיֵ֖ב כִּ֣י יֶֽחֶטְאוּ־לָ֑⁠ךְ וְ⁠שָׁ֨בוּ֙ וְ⁠הוֹד֣וּ אֶת־שְׁמֶ֔⁠ךָ וְ⁠הִתְפַּֽלְל֧וּ וְ⁠הִֽתְחַנְּנ֛וּ לְ⁠פָנֶ֖י⁠ךָ בַּ⁠בַּ֥יִת הַ⁠זֶּֽה׃","wĕֽ⁠ʼim-yiná̇gé֞p ʻamĕ̇⁠ká֧ yişĕ̂ráʼé֛l li⁠pĕné֥y ʼwòyé֖b ki֣̇y yeֽẖetĕʼẇ-lá֑⁠kĕ wĕ⁠şá̌֨bẇ֙ wĕ⁠hwòd֣ẇ ʼeţ-şĕ̌me֔⁠ká wĕ⁠hiţĕpȧֽlĕl֧ẇ wĕ⁠hiֽţĕẖanĕ̇n֛ẇ lĕ⁠páne֖y⁠ká bȧ⁠bȧ֥yiţ ha⁠zėֽh׃"],[6,25,"וְ⁠אַתָּה֙ תִּשְׁמַ֣ע מִן־הַ⁠שָּׁמַ֔יִם וְ⁠סָ֣לַחְתָּ֔ לְ⁠חַטַּ֖את עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל וַ⁠הֲשֵׁיבוֹתָ⁠ם֙ אֶל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁר־נָתַ֥תָּה לָ⁠הֶ֖ם וְ⁠לַ⁠אֲבֹתֵי⁠הֶֽם׃פ","wĕ⁠ʼaţá̇h֙ ţi̇şĕ̌ma֣ʻ min-ha⁠şá̇̌ma֔yim wĕ⁠sá֣laẖĕţá̇֔ lĕ⁠ẖatȧ֖ʼţ ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l wa⁠hàşé̌ybwòţá⁠m֙ ʼel-há֣⁠ʼàdámá֔h ʼàşěr-náţa֥ţá̇h lá⁠he֖m wĕ⁠la⁠ʼàbòţéy⁠heֽm׃p"],[6,26,"בְּ⁠הֵעָצֵ֧ר הַ⁠שָּׁמַ֛יִם וְ⁠לֹֽא־יִהְיֶ֥ה מָטָ֖ר כִּ֣י יֶֽחֶטְאוּ־לָ֑⁠ךְ וְ⁠הִֽתְפַּלְל֞וּ אֶל־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ וְ⁠הוֹד֣וּ אֶת־שְׁמֶ֔⁠ךָ מֵ⁠חַטָּאתָ֥⁠ם יְשׁוּב֖וּ⁠ן כִּ֥י תַעֲנֵֽ⁠ם׃","bĕ̇⁠héʻáẕé֧r ha⁠şá̇̌ma֛yim wĕ⁠lòֽʼ-yihĕye֥h mátá֖r ki֣̇y yeֽẖetĕʼẇ-lá֑⁠kĕ wĕ⁠hiֽţĕpȧlĕl֞ẇ ʼel-ha⁠má̇q֤wòm ha⁠zėh֙ wĕ⁠hwòd֣ẇ ʼeţ-şĕ̌me֔⁠ká mé⁠ẖatá̇ʼţá֥⁠m yĕş̌ẇb֖ẇ⁠n ki֥̇y ţaʻànéֽ⁠m׃"],[6,27,"וְ⁠אַתָּ֣ה ׀ תִּשְׁמַ֣ע הַ⁠שָּׁמַ֗יִם וְ⁠סָ֨לַחְתָּ֜ לְ⁠חַטַּ֤את עֲבָדֶ֨י⁠ךָ֙ וְ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל כִּ֥י תוֹרֵ֛⁠ם אֶל־הַ⁠דֶּ֥רֶךְ הַ⁠טּוֹבָ֖ה אֲשֶׁ֣ר יֵֽלְכוּ־בָ֑⁠הּ וְ⁠נָתַתָּ֤ה מָטָר֙ עַֽל־אַרְצְ⁠ךָ֔ אֲשֶׁר־נָתַ֥תָּה לְ⁠עַמְּ⁠ךָ֖ לְ⁠נַחֲלָֽה׃ס","wĕ⁠ʼaţá֣̇h ׀ ţi̇şĕ̌ma֣ʻ ha⁠şá̇̌ma֗yim wĕ⁠sá֨laẖĕţá̇֜ lĕ⁠ẖatȧ֤ʼţ ʻàbáde֨y⁠ká֙ wĕ⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l ki֥̇y ţwòré֛⁠m ʼel-ha⁠dė֥rekĕ ha⁠ṫwòbá֖h ʼàşě֣r yéֽlĕkẇ-bá֑⁠ḣ wĕ⁠náţaţá֤̇h mátár֙ ʻaֽl-ʼarĕẕĕ⁠ká֔ ʼàşěr-náţa֥ţá̇h lĕ⁠ʻamĕ̇⁠ká֖ lĕ⁠naẖàláֽh׃s"],[6,28,"רָעָ֞ב כִּֽי־יִהְיֶ֣ה בָ⁠אָ֗רֶץ דֶּ֣בֶר כִּֽי־יִֽ֠הְיֶה שִׁדָּפ֨וֹן וְ⁠יֵרָק֜וֹן אַרְבֶּ֤ה וְ⁠חָסִיל֙ כִּ֣י יִהְיֶ֔ה כִּ֧י יָֽצַר־ל֛⁠וֹ אוֹיְבָ֖י⁠ו בְּ⁠אֶ֣רֶץ שְׁעָרָ֑י⁠ו כָּל־נֶ֖גַע וְ⁠כָֽל־מַחֲלָֽה׃","ráʻá֞b kiֽ̇y-yihĕye֣h bá⁠ʼá֗reẕ dė֣ber kiֽ̇y-yiֽ֠hĕyeh şǐdá̇p֨wòn wĕ⁠yéráq֜wòn ʼarĕbė֤h wĕ⁠ẖásiyl֙ ki֣̇y yihĕye֔h ki֧̇y yáֽẕar-l֛⁠wò ʼwòyĕbá֖y⁠w bĕ̇⁠ʼe֣reẕ şĕ̌ʻárá֑y⁠w ká̇l-ne֖gaʻ wĕ⁠káֽl-maẖàláֽh׃"],[6,29,"כָּל־תְּפִלָּ֣ה כָל־תְּחִנָּ֗ה אֲשֶׁ֤ר יִהְיֶה֙ לְ⁠כָל־הָ֣⁠אָדָ֔ם וּ⁠לְ⁠כֹ֖ל עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל אֲשֶׁ֣ר יֵדְע֗וּ אִ֤ישׁ נִגְע⁠וֹ֙ וּ⁠מַכְאֹב֔⁠וֹ וּ⁠פָרַ֥שׂ כַּפָּ֖י⁠ו אֶל־הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ká̇l-ţĕ̇pilá֣̇h kál-ţĕ̇ẖiná̇֗h ʼàşě֤r yihĕyeh֙ lĕ⁠kál-há֣⁠ʼádá֔m ẇ⁠lĕ⁠kò֖l ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l ʼàşě֣r yédĕʻ֗ẇ ʼi֤yş̌ nigĕʻ⁠wò֙ ẇ⁠makĕʼòb֔⁠wò ẇ⁠pára֥ş̂ kȧpá֖̇y⁠w ʼel-ha⁠bȧ֥yiţ ha⁠zėֽh׃"],[6,30,"וְ֠⁠אַתָּה תִּשְׁמַ֨ע מִן־הַ⁠שָּׁמַ֜יִם מְכ֤וֹן שִׁבְתֶּ֨⁠ךָ֙ וְ⁠סָ֣לַחְתָּ֔ וְ⁠נָתַתָּ֤ה לָ⁠אִישׁ֙ כְּ⁠כָל־דְּרָכָ֔י⁠ו אֲשֶׁ֥ר תֵּדַ֖ע אֶת־לְבָב֑⁠וֹ כִּ֤י אַתָּה֙ לְ⁠בַדְּ⁠ךָ֣ יָדַ֔עְתָּ אֶת־לְבַ֖ב בְּנֵ֥י הָ⁠אָדָֽם׃","wĕ֠⁠ʼaţá̇h ţi̇şĕ̌ma֨ʻ min-ha⁠şá̇̌ma֜yim mĕk֤wòn şǐbĕţė֨⁠ká֙ wĕ⁠sá֣laẖĕţá̇֔ wĕ⁠náţaţá֤̇h lá⁠ʼiyş̌֙ kĕ̇⁠kál-dĕ̇ráká֔y⁠w ʼàşě֥r ţé̇da֖ʻ ʼeţ-lĕbáb֑⁠wò ki֤̇y ʼaţá̇h֙ lĕ⁠badĕ̇⁠ká֣ yáda֔ʻĕţá̇ ʼeţ-lĕba֖b bĕ̇né֥y há⁠ʼádáֽm׃"],[6,31,"לְמַ֣עַן יִֽירָא֗וּ⁠ךָ לָ⁠לֶ֨כֶת֙ בִּ⁠דְרָכֶ֔י⁠ךָ כָּל־הַ֨⁠יָּמִ֔ים אֲשֶׁר־הֵ֥ם חַיִּ֖ים עַל־פְּנֵ֣י הָ⁠אֲדָמָ֑ה אֲשֶׁ֥ר נָתַ֖תָּה לַ⁠אֲבֹתֵֽי⁠נוּ׃ס","lĕma֣ʻan yiֽyráʼ֗ẇ⁠ká lá⁠le֨keţ֙ bi̇⁠dĕráke֔y⁠ká ká̇l-ha֨⁠yá̇mi֔ym ʼàşěr-hé֥m ẖayi֖̇ym ʻal-pĕ̇né֣y há⁠ʼàdámá֑h ʼàşě֥r náţa֖ţá̇h la⁠ʼàbòţéֽy⁠nẇ׃s"],[6,32,"וְ⁠גַ֣ם אֶל־הַ⁠נָּכְרִ֗י אֲ֠שֶׁר לֹ֥א מֵ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵל֮ הוּא֒ וּ⁠בָ֣א ׀ מֵ⁠אֶ֣רֶץ רְחוֹקָ֗ה לְמַ֨עַן שִׁמְ⁠ךָ֤ הַ⁠גָּדוֹל֙ וְ⁠יָדְ⁠ךָ֣ הַ⁠חֲזָקָ֔ה וּֽ⁠זְרֽוֹעֲ⁠ךָ֖ הַ⁠נְּטוּיָ֑ה וּ⁠בָ֥אוּ וְ⁠הִֽתְפַּלְל֖וּ אֶל־הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","wĕ⁠ga֣m ʼel-ha⁠ná̇kĕri֗y ʼà֠şěr lò֥ʼ mé⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼél֮ hẇʼ֒ ẇ⁠bá֣ʼ ׀ mé⁠ʼe֣reẕ rĕẖwòqá֗h lĕma֨ʻan şǐmĕ⁠ká֤ ha⁠gá̇dwòl֙ wĕ⁠yádĕ⁠ká֣ ha⁠ẖàzáqá֔h ẇֽ⁠zĕrֽwòʻà⁠ká֖ ha⁠nĕ̇tẇyá֑h ẇ⁠bá֥ʼẇ wĕ⁠hiֽţĕpȧlĕl֖ẇ ʼel-ha⁠bȧ֥yiţ ha⁠zėֽh׃"],[6,33,"וְ⁠אַתָּ֞ה תִּשְׁמַ֤ע מִן־הַ⁠שָּׁמַ֨יִם֙ מִ⁠מְּכ֣וֹן שִׁבְתֶּ֔⁠ךָ וְ⁠עָשִׂ֕יתָ כְּ⁠כֹ֛ל אֲשֶׁר־יִקְרָ֥א אֵלֶ֖י⁠ךָ הַ⁠נָּכְרִ֑י לְמַ֣עַן יֵדְעוּ֩ כָל־עַמֵּ֨י הָ⁠אָ֜רֶץ אֶת־שְׁמֶ֗⁠ךָ וּ⁠לְ⁠יִרְאָ֤ה אֹֽתְ⁠ךָ֙ כְּ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל וְ⁠לָ⁠דַ֕עַת כִּֽי־שִׁמְ⁠ךָ֣ נִקְרָ֔א עַל־הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי׃","wĕ⁠ʼaţá̇֞h ţi̇şĕ̌ma֤ʻ min-ha⁠şá̇̌ma֨yim֙ mi⁠mĕ̇k֣wòn şǐbĕţė֔⁠ká wĕ⁠ʻáşî֕yţá kĕ̇⁠kò֛l ʼàşěr-yiqĕrá֥ʼ ʼéle֖y⁠ká ha⁠ná̇kĕri֑y lĕma֣ʻan yédĕʻẇ֩ kál-ʻamé̇֨y há⁠ʼá֜reẕ ʼeţ-şĕ̌me֗⁠ká ẇ⁠lĕ⁠yirĕʼá֤h ʼòֽţĕ⁠ká֙ kĕ̇⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l wĕ⁠lá⁠da֕ʻaţ kiֽ̇y-şǐmĕ⁠ká֣ niqĕrá֔ʼ ʻal-ha⁠bȧ֥yiţ ha⁠zė֖h ʼàşě֥r bá̇niֽyţiy׃"],[6,34,"כִּֽי־יֵצֵ֨א עַמְּ⁠ךָ֤ לַ⁠מִּלְחָמָה֙ עַל־א֣וֹיְבָ֔י⁠ו בַּ⁠דֶּ֖רֶךְ אֲשֶׁ֣ר תִּשְׁלָחֵ֑⁠ם וְ⁠הִתְפַּֽלְל֣וּ אֵלֶ֗י⁠ךָ דֶּ֣רֶךְ הָ⁠עִ֤יר הַ⁠זֹּאת֙ אֲשֶׁ֣ר בָּחַ֣רְתָּ בָּ֔⁠הּ וְ⁠הַ⁠בַּ֖יִת אֲשֶׁר־בָּנִ֥יתִי לִ⁠שְׁמֶֽ⁠ךָ׃","kiֽ̇y-yéẕé֨ʼ ʻamĕ̇⁠ká֤ la⁠mi̇lĕẖámáh֙ ʻal-ʼ֣wòyĕbá֔y⁠w bȧ⁠dė֖rekĕ ʼàşě֣r ţi̇şĕ̌láẖé֑⁠m wĕ⁠hiţĕpȧֽlĕl֣ẇ ʼéle֗y⁠ká dė֣rekĕ há⁠ʻi֤yr ha⁠zò̇ʼţ֙ ʼàşě֣r bá̇ẖa֣rĕţá̇ bá̇֔⁠ḣ wĕ⁠ha⁠bȧ֖yiţ ʼàşěr-bá̇ni֥yţiy li⁠şĕ̌meֽ⁠ká׃"],[6,35,"וְ⁠שָׁמַעְתָּ֙ מִן־הַ⁠שָּׁמַ֔יִם אֶת־תְּפִלָּתָ֖⁠ם וְ⁠אֶת־תְּחִנָּתָ֑⁠ם וְ⁠עָשִׂ֖יתָ מִשְׁפָּטָֽ⁠ם׃","wĕ⁠şá̌maʻĕţá̇֙ min-ha⁠şá̇̌ma֔yim ʼeţ-ţĕ̇pilá̇ţá֖⁠m wĕ⁠ʼeţ-ţĕ̇ẖiná̇ţá֑⁠m wĕ⁠ʻáşî֖yţá mişĕ̌pá̇táֽ⁠m׃"],[6,36,"כִּ֣י יֶחֶטְאוּ־לָ֗⁠ךְ כִּ֣י אֵ֤ין אָדָם֙ אֲשֶׁ֣ר לֹא־יֶחֱטָ֔א וְ⁠אָנַפְתָּ֣ בָ֔⁠ם וּ⁠נְתַתָּ֖⁠ם לִ⁠פְנֵ֣י אוֹיֵ֑ב וְ⁠שָׁב֧וּ⁠ם שׁוֹבֵי⁠הֶ֛ם אֶל־אֶ֥רֶץ רְחוֹקָ֖ה א֥וֹ קְרוֹבָֽה׃","ki֣̇y yeẖetĕʼẇ-lá֗⁠kĕ ki֣̇y ʼé֤yn ʼádám֙ ʼàşě֣r lòʼ-yeẖètá֔ʼ wĕ⁠ʼánapĕţá֣̇ bá֔⁠m ẇ⁠nĕţaţá֖̇⁠m li⁠pĕné֣y ʼwòyé֑b wĕ⁠şá̌b֧ẇ⁠m ş̌wòbéy⁠he֛m ʼel-ʼe֥reẕ rĕẖwòqá֖h ʼ֥wò qĕrwòbáֽh׃"],[6,37,"וְ⁠הֵשִׁ֨יבוּ֙ אֶל־לְבָבָ֔⁠ם בָּ⁠אָ֖רֶץ אֲשֶׁ֣ר נִשְׁבּוּ־שָׁ֑ם וְ⁠שָׁ֣בוּ ׀ וְ⁠הִֽתְחַנְּנ֣וּ אֵלֶ֗י⁠ךָ בְּ⁠אֶ֤רֶץ שִׁבְיָ⁠ם֙ לֵ⁠אמֹ֔ר חָטָ֥אנוּ הֶעֱוִ֖ינוּ וְ⁠רָשָֽׁעְנוּ׃","wĕ⁠héşǐ֨ybẇ֙ ʼel-lĕbábá֔⁠m bá̇⁠ʼá֖reẕ ʼàşě֣r nişĕ̌ḃẇ-şá֑̌m wĕ⁠şá֣̌bẇ ׀ wĕ⁠hiֽţĕẖanĕ̇n֣ẇ ʼéle֗y⁠ká bĕ̇⁠ʼe֤reẕ şǐbĕyá⁠m֙ lé⁠ʼmò֔r ẖátá֥ʼnẇ heʻèwi֖ynẇ wĕ⁠ráşáֽ̌ʻĕnẇ׃"],[6,38,"וְ⁠שָׁ֣בוּ אֵלֶ֗י⁠ךָ בְּ⁠כָל־לִבָּ⁠ם֙ וּ⁠בְ⁠כָל־נַפְשָׁ֔⁠ם בְּ⁠אֶ֥רֶץ שִׁבְיָ֖⁠ם אֲשֶׁר־שָׁב֣וּ אֹתָ֑⁠ם וְ⁠הִֽתְפַּֽלְל֗וּ דֶּ֤רֶךְ אַרְצָ⁠ם֙ אֲשֶׁ֣ר נָתַ֣תָּה לַ⁠אֲבוֹתָ֔⁠ם וְ⁠הָ⁠עִיר֙ אֲשֶׁ֣ר בָּחַ֔רְתָּ וְ⁠לַ⁠בַּ֖יִת אֲשֶׁר־בָּנִ֥יתִי לִ⁠שְׁמֶֽ⁠ךָ׃","wĕ⁠şá֣̌bẇ ʼéle֗y⁠ká bĕ̇⁠kál-libá̇⁠m֙ ẇ⁠bĕ⁠kál-napĕşá̌֔⁠m bĕ̇⁠ʼe֥reẕ şǐbĕyá֖⁠m ʼàşěr-şá̌b֣ẇ ʼòţá֑⁠m wĕ⁠hiֽţĕpȧֽlĕl֗ẇ dė֤rekĕ ʼarĕẕá⁠m֙ ʼàşě֣r náţa֣ţá̇h la⁠ʼàbwòţá֔⁠m wĕ⁠há⁠ʻiyr֙ ʼàşě֣r bá̇ẖa֔rĕţá̇ wĕ⁠la⁠bȧ֖yiţ ʼàşěr-bá̇ni֥yţiy li⁠şĕ̌meֽ⁠ká׃"],[6,39,"וְ⁠שָׁמַעְתָּ֨ מִן־הַ⁠שָּׁמַ֜יִם מִ⁠מְּכ֣וֹן שִׁבְתְּ⁠ךָ֗ אֶת־תְּפִלָּתָ⁠ם֙ וְ⁠אֶת־תְּחִנֹּ֣תֵי⁠הֶ֔ם וְ⁠עָשִׂ֖יתָ מִשְׁפָּטָ֑⁠ם וְ⁠סָלַחְתָּ֥ לְ⁠עַמְּ⁠ךָ֖ אֲשֶׁ֥ר חָֽטְאוּ־לָֽ⁠ךְ׃","wĕ⁠şá̌maʻĕţá̇֨ min-ha⁠şá̇̌ma֜yim mi⁠mĕ̇k֣wòn şǐbĕţĕ̇⁠ká֗ ʼeţ-ţĕ̇pilá̇ţá⁠m֙ wĕ⁠ʼeţ-ţĕ̇ẖinò֣̇ţéy⁠he֔m wĕ⁠ʻáşî֖yţá mişĕ̌pá̇tá֑⁠m wĕ⁠sálaẖĕţá֥̇ lĕ⁠ʻamĕ̇⁠ká֖ ʼàşě֥r ẖáֽtĕʼẇ-láֽ⁠kĕ׃"],[6,40,"עַתָּ֣ה אֱלֹהַ֗⁠י יִֽהְיוּ־נָ֤א עֵינֶ֨י⁠ךָ֙ פְּתֻח֔וֹת וְ⁠אָזְנֶ֖י⁠ךָ קַשֻּׁב֑וֹת לִ⁠תְפִלַּ֖ת הַ⁠מָּק֥וֹם הַ⁠זֶּֽה׃ס","ʻaţá֣̇h ʼèlòha֗⁠y yiֽhĕyẇ-ná֤ʼ ʻéyne֨y⁠ká֙ pĕ̇ţuẖ֔wòţ wĕ⁠ʼázĕne֖y⁠ká qaşu̇̌b֑wòţ li⁠ţĕpilȧ֖ţ ha⁠má̇q֥wòm ha⁠zėֽh׃s"],[6,41,"וְ⁠עַתָּ֗ה קוּמָ֞⁠ה יְהוָ֤ה אֱלֹהִים֙ לְֽ⁠נוּחֶ֔⁠ךָ אַתָּ֖ה וַ⁠אֲר֣וֹן עֻזֶּ֑⁠ךָ כֹּהֲנֶ֜י⁠ךָ יְהוָ֤ה אֱלֹהִים֙ יִלְבְּשׁ֣וּ תְשׁוּעָ֔ה וַ⁠חֲסִידֶ֖י⁠ךָ יִשְׂמְח֥וּ בַ⁠טּֽוֹב׃","wĕ⁠ʻaţá̇֗h qẇmá֞⁠h yĕhwá֤h ʼèlòhiym֙ lĕֽ⁠nẇẖe֔⁠ká ʼaţá֖̇h wa⁠ʼàr֣wòn ʻuzė֑⁠ká kò̇hàne֜y⁠ká yĕhwá֤h ʼèlòhiym֙ yilĕbĕ̇ş֣̌ẇ ţĕş̌ẇʻá֔h wa⁠ẖàsiyde֖y⁠ká yişĕ̂mĕẖ֥ẇ ba⁠ṫֽwòb׃"],[6,42,"יְהוָ֣ה אֱלֹהִ֔ים אַל־תָּשֵׁ֖ב פְּנֵ֣י מְשִׁיחֶ֑י⁠ךָ זָכְרָ֕⁠ה לְ⁠חַֽסְדֵ֖י דָּוִ֥יד עַבְדֶּֽ⁠ךָ׃פ","yĕhwá֣h ʼèlòhi֔ym ʼal-ţá̇şé֖̌b pĕ̇né֣y mĕşǐyẖe֑y⁠ká zákĕrá֕⁠h lĕ⁠ẖaֽsĕdé֖y dá̇wi֥yd ʻabĕdėֽ⁠ká׃p"],[7,1,"וּ⁠כְ⁠כַלּ֤וֹת שְׁלֹמֹה֙ לְ⁠הִתְפַּלֵּ֔ל וְ⁠הָ⁠אֵ֗שׁ יָֽרְדָה֙ מֵֽ⁠הַ⁠שָּׁמַ֔יִם וַ⁠תֹּ֥אכַל הָ⁠עֹלָ֖ה וְ⁠הַ⁠זְּבָחִ֑ים וּ⁠כְב֥וֹד יְהוָ֖ה מָלֵ֥א אֶת־הַ⁠בָּֽיִת׃","ẇ⁠kĕ⁠kal֤̇wòţ şĕ̌lòmòh֙ lĕ⁠hiţĕpȧlé̇֔l wĕ⁠há⁠ʼé֗ş̌ yáֽrĕdáh֙ méֽ⁠ha⁠şá̇̌ma֔yim wa⁠ţò֥̇ʼkal há⁠ʻòlá֖h wĕ⁠ha⁠zĕ̇báẖi֑ym ẇ⁠kĕb֥wòd yĕhwá֖h málé֥ʼ ʼeţ-ha⁠báֽ̇yiţ׃"],[7,2,"וְ⁠לֹ֤א יָֽכְלוּ֙ הַ⁠כֹּ֣הֲנִ֔ים לָ⁠ב֖וֹא אֶל־בֵּ֣ית יְהוָ֑ה כִּֽי־מָלֵ֥א כְבוֹד־יְהוָ֖ה אֶת־בֵּ֥ית יְהוָֽה׃","wĕ⁠lò֤ʼ yáֽkĕlẇ֙ ha⁠kò֣̇hàni֔ym lá⁠b֖wòʼ ʼel-bé֣̇yţ yĕhwá֑h kiֽ̇y-málé֥ʼ kĕbwòd-yĕhwá֖h ʼeţ-bé֥̇yţ yĕhwáֽh׃"],[7,3,"וְ⁠כֹ֣ל ׀ בְּנֵ֣י יִשְׂרָאֵ֗ל רֹאִים֙ בְּ⁠רֶ֣דֶת הָ⁠אֵ֔שׁ וּ⁠כְב֥וֹד יְהוָ֖ה עַל־הַ⁠בָּ֑יִת וַ⁠יִּכְרְעוּ֩ אַפַּ֨יִם אַ֤רְצָ⁠ה עַל־הָ⁠רִֽצְפָה֙ וַ⁠יִּֽשְׁתַּֽחֲו֔וּ וְ⁠הוֹד֤וֹת לַ⁠יהוָה֙ כִּ֣י ט֔וֹב כִּ֥י לְ⁠עוֹלָ֖ם חַסְדּֽ⁠וֹ׃","wĕ⁠kò֣l ׀ bĕ̇né֣y yişĕ̂ráʼé֗l ròʼiym֙ bĕ̇⁠re֣deţ há⁠ʼé֔ş̌ ẇ⁠kĕb֥wòd yĕhwá֖h ʻal-ha⁠bá֑̇yiţ wa⁠yi̇kĕrĕʻẇ֩ ʼapȧ֨yim ʼa֤rĕẕá⁠h ʻal-há⁠riֽẕĕpáh֙ wa⁠yiֽ̇şĕ̌ţֽ̇aẖàw֔ẇ wĕ⁠hwòd֤wòţ la⁠yhwáh֙ ki֣̇y t֔wòb ki֥̇y lĕ⁠ʻwòlá֖m ẖasĕḋֽ⁠wò׃"],[7,4,"וְ⁠הַ⁠מֶּ֖לֶךְ וְ⁠כָל־הָ⁠עָ֑ם זֹבְחִ֥ים זֶ֖בַח לִ⁠פְנֵ֥י יְהוָֽה׃ס","wĕ⁠ha⁠mė֖lekĕ wĕ⁠kál-há⁠ʻá֑m zòbĕẖi֥ym ze֖baẖ li⁠pĕné֥y yĕhwáֽh׃s"],[7,5,"וַ⁠יִּזְבַּ֞ח הַ⁠מֶּ֣לֶךְ שְׁלֹמֹה֮ אֶת־זֶ֣בַח הַ⁠בָּקָ֗ר עֶשְׂרִ֤ים וּ⁠שְׁנַ֨יִם֙ אֶ֔לֶף וְ⁠צֹ֕אן מֵאָ֥ה וְ⁠עֶשְׂרִ֖ים אָ֑לֶף וַֽ⁠יַּחְנְכוּ֙ אֶת־בֵּ֣ית הָֽ⁠אֱלֹהִ֔ים הַ⁠מֶּ֖לֶךְ וְ⁠כָל־הָ⁠עָֽם׃","wa⁠yi̇zĕbȧ֞ẖ ha⁠mė֣lekĕ şĕ̌lòmòh֮ ʼeţ-ze֣baẖ ha⁠bá̇qá֗r ʻeşĕ̂ri֤ym ẇ⁠şĕ̌na֨yim֙ ʼe֔lep wĕ⁠ẕò֕ʼn méʼá֥h wĕ⁠ʻeşĕ̂ri֖ym ʼá֑lep waֽ⁠yȧẖĕnĕkẇ֙ ʼeţ-bé֣̇yţ hֽá⁠ʼèlòhi֔ym ha⁠mė֖lekĕ wĕ⁠kál-há⁠ʻáֽm׃"],[7,6,"וְ⁠הַ⁠כֹּהֲנִ֞ים עַל־מִשְׁמְרוֹתָ֣⁠ם עֹמְדִ֗ים וְ⁠הַ⁠לְוִיִּ֞ם בִּ⁠כְלֵי־שִׁ֤יר יְהוָה֙ אֲשֶׁ֨ר עָשָׂ֜ה דָּוִ֣יד הַ⁠מֶּ֗לֶךְ לְ⁠הֹד֤וֹת לַ⁠יהוָה֙ כִּֽי־לְ⁠עוֹלָ֣ם חַסְדּ֔⁠וֹ בְּ⁠הַלֵּ֥ל דָּוִ֖יד בְּ⁠יָדָ֑⁠ם וְ⁠הַ⁠כֹּהֲנִים֙ מחצצרים נֶגְדָּ֔⁠ם וְ⁠כָל־יִשְׂרָאֵ֖ל עֹמְדִֽים׃ס","wĕ⁠ha⁠kò̇hàni֞ym ʻal-mişĕ̌mĕrwòţá֣⁠m ʻòmĕdi֗ym wĕ⁠ha⁠lĕwiyi̇֞m bi̇⁠kĕléy-şǐ֤yr yĕhwáh֙ ʼàşě֨r ʻáşá̂֜h dá̇wi֣yd ha⁠mė֗lekĕ lĕ⁠hòd֤wòţ la⁠yhwáh֙ kiֽ̇y-lĕ⁠ʻwòlá֣m ẖasĕḋ֔⁠wò bĕ̇⁠halé֥̇l dá̇wi֖yd bĕ̇⁠yádá֑⁠m wĕ⁠ha⁠kò̇hàniym֙ mẖẕẕrym negĕdá̇֔⁠m wĕ⁠kál-yişĕ̂ráʼé֖l ʻòmĕdiֽym׃s"],[7,7,"וַ⁠יְקַדֵּ֣שׁ שְׁלֹמֹ֗ה אֶת־תּ֤וֹךְ הֶֽ⁠חָצֵר֙ אֲשֶׁר֙ לִ⁠פְנֵ֣י בֵית־יְהוָ֔ה כִּֽי־עָ֤שָׂה שָׁם֙ הָֽ⁠עֹל֔וֹת וְ⁠אֵ֖ת חֶלְבֵ֣י הַ⁠שְּׁלָמִ֑ים כִּֽי־מִזְבַּ֤ח הַ⁠נְּחֹ֨שֶׁת֙ אֲשֶׁ֣ר עָשָׂ֣ה שְׁלֹמֹ֔ה לֹ֣א יָכ֗וֹל לְ⁠הָכִ֛יל אֶת־הָ⁠עֹלָ֥ה וְ⁠אֶת־הַ⁠מִּנְחָ֖ה וְ⁠אֶת־הַ⁠חֲלָבִֽים׃","wa⁠yĕqadé֣̇ş̌ şĕ̌lòmò֗h ʼeţ-ţ֤̇wòkĕ heֽ⁠ẖáẕér֙ ʼàşěr֙ li⁠pĕné֣y béyţ-yĕhwá֔h kiֽ̇y-ʻá֤şá̂h şá̌m֙ háֽ⁠ʻòl֔wòţ wĕ⁠ʼé֖ţ ẖelĕbé֣y ha⁠şĕ̇̌lámi֑ym kiֽ̇y-mizĕbȧ֤ẖ ha⁠nĕ̇ẖò֨şěţ֙ ʼàşě֣r ʻáşá֣̂h şĕ̌lòmò֔h lò֣ʼ yák֗wòl lĕ⁠háki֛yl ʼeţ-há⁠ʻòlá֥h wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֖h wĕ⁠ʼeţ-ha⁠ẖàlábiֽym׃"],[7,8,"וַ⁠יַּ֣עַשׂ שְׁלֹמֹ֣ה אֶת־הֶ֠⁠חָג בָּ⁠עֵ֨ת הַ⁠הִ֜יא שִׁבְעַ֤ת יָמִים֙ וְ⁠כָל־יִשְׂרָאֵ֣ל עִמּ֔⁠וֹ קָהָ֖ל גָּד֣וֹל מְאֹ֑ד מִ⁠לְּב֥וֹא חֲמָ֖ת עַד־נַ֥חַל מִצְרָֽיִם׃","wa⁠yȧ֣ʻaş̂ şĕ̌lòmò֣h ʼeţ-he֠⁠ẖág bá̇⁠ʻé֨ţ ha⁠hi֜yʼ şǐbĕʻa֤ţ yámiym֙ wĕ⁠kál-yişĕ̂ráʼé֣l ʻiṁ֔⁠wò qáhá֖l gá̇d֣wòl mĕʼò֑d mi⁠lĕ̇b֥wòʼ ẖàmá֖ţ ʻad-na֥ẖal miẕĕráֽyim׃"],[7,9,"וַֽ⁠יַּעֲשׂ֛וּ בַּ⁠יּ֥וֹם הַ⁠שְּׁמִינִ֖י עֲצָ֑רֶת כִּ֣י ׀ חֲנֻכַּ֣ת הַ⁠מִּזְבֵּ֗חַ עָשׂוּ֙ שִׁבְעַ֣ת יָמִ֔ים וְ⁠הֶ⁠חָ֖ג שִׁבְעַ֥ת יָמִֽים׃","wֽa⁠yȧʻàş֛̂ẇ bȧ⁠ẏ֥wòm ha⁠şĕ̇̌miyni֖y ʻàẕá֑reţ ki֣̇y ׀ ẖànukȧ֣ţ ha⁠mi̇zĕbé̇֗ẖa ʻáş̂ẇ֙ şǐbĕʻa֣ţ yámi֔ym wĕ⁠he⁠ẖá֖g şǐbĕʻa֥ţ yámiֽym׃"],[7,10,"וּ⁠בְ⁠י֨וֹם עֶשְׂרִ֤ים וּ⁠שְׁלֹשָׁה֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י שִׁלַּ֥ח אֶת־הָ⁠עָ֖ם לְ⁠אָהֳלֵי⁠הֶ֑ם שְׂמֵחִים֙ וְ⁠ט֣וֹבֵי לֵ֔ב עַל־הַ⁠טּוֹבָ֗ה אֲשֶׁ֨ר עָשָׂ֤ה יְהוָה֙ לְ⁠דָוִ֣יד וְ⁠לִ⁠שְׁלֹמֹ֔ה וּ⁠לְ⁠יִשְׂרָאֵ֖ל עַמּֽ⁠וֹ׃","ẇ⁠bĕ⁠y֨wòm ʻeşĕ̂ri֤ym ẇ⁠şĕ̌lòşá̌h֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y şǐlȧ֥ẖ ʼeţ-há⁠ʻá֖m lĕ⁠ʼáholéy⁠he֑m şĕ̂méẖiym֙ wĕ⁠t֣wòbéy lé֔b ʻal-ha⁠ṫwòbá֗h ʼàşě֨r ʻáşá֤̂h yĕhwáh֙ lĕ⁠dáwi֣yd wĕ⁠li⁠şĕ̌lòmò֔h ẇ⁠lĕ⁠yişĕ̂ráʼé֖l ʻaṁֽ⁠wò׃"],[7,11,"וַ⁠יְכַ֧ל שְׁלֹמֹ֛ה אֶת־בֵּ֥ית יְהוָ֖ה וְ⁠אֶת־בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ⁠אֵ֨ת כָּל־הַ⁠בָּ֜א עַל־לֵ֣ב שְׁלֹמֹ֗ה לַ⁠עֲשׂ֧וֹת בְּ⁠בֵית־יְהוָ֛ה וּ⁠בְ⁠בֵית֖⁠וֹ הִצְלִֽיחַ׃פ","wa⁠yĕka֧l şĕ̌lòmò֛h ʼeţ-bé֥̇yţ yĕhwá֖h wĕ⁠ʼeţ-bé֣̇yţ ha⁠mė֑lekĕ wĕ⁠ʼé֨ţ ká̇l-ha⁠bá̇֜ʼ ʻal-lé֣b şĕ̌lòmò֗h la⁠ʻàş֧̂wòţ bĕ̇⁠béyţ-yĕhwá֛h ẇ⁠bĕ⁠béyţ֖⁠wò hiẕĕliֽyẖa׃p"],[7,12,"וַ⁠יֵּרָ֧א יְהוָ֛ה אֶל־שְׁלֹמֹ֖ה בַּ⁠לָּ֑יְלָה וַ⁠יֹּ֣אמֶר ל֗⁠וֹ שָׁמַ֨עְתִּי֙ אֶת־תְּפִלָּתֶ֔⁠ךָ וּ⁠בָחַ֜רְתִּי בַּ⁠מָּק֥וֹם הַ⁠זֶּ֛ה לִ֖⁠י לְ⁠בֵ֥ית זָֽבַח׃","wa⁠yé̇rá֧ʼ yĕhwá֛h ʼel-şĕ̌lòmò֖h bȧ⁠lá֑̇yĕláh wa⁠yò֣̇ʼmer l֗⁠wò şá̌ma֨ʻĕţi̇y֙ ʼeţ-ţĕ̇pilá̇ţe֔⁠ká ẇ⁠báẖa֜rĕţi̇y bȧ⁠má̇q֥wòm ha⁠zė֛h li֖⁠y lĕ⁠bé֥yţ záֽbaẖ׃"],[7,13,"הֵ֣ן אֶֽעֱצֹ֤ר הַ⁠שָּׁמַ֨יִם֙ וְ⁠לֹֽא־יִהְיֶ֣ה מָטָ֔ר וְ⁠הֵן־אֲצַוֶּ֥ה עַל־חָגָ֖ב לֶ⁠אֱכ֣וֹל הָ⁠אָ֑רֶץ וְ⁠אִם־אֲשַׁלַּ֥ח דֶּ֖בֶר בְּ⁠עַמִּֽ⁠י׃","hé֣n ʼeֽʻèẕò֤r ha⁠şá̇̌ma֨yim֙ wĕ⁠lòֽʼ-yihĕye֣h mátá֔r wĕ⁠hén-ʼàẕawė֥h ʻal-ẖágá֖b le⁠ʼèk֣wòl há⁠ʼá֑reẕ wĕ⁠ʼim-ʼàşǎlȧ֥ẖ dė֖ber bĕ̇⁠ʻamiֽ̇⁠y׃"],[7,14,"וְ⁠יִכָּנְע֨וּ עַמִּ֜⁠י אֲשֶׁ֧ר נִֽקְרָא־שְׁמִ֣⁠י עֲלֵי⁠הֶ֗ם וְ⁠יִֽתְפַּֽלְלוּ֙ וִֽ⁠יבַקְשׁ֣וּ פָנַ֔⁠י וְ⁠יָשֻׁ֖בוּ מִ⁠דַּרְכֵי⁠הֶ֣ם הָ⁠רָעִ֑ים וַ⁠אֲנִי֙ אֶשְׁמַ֣ע מִן־הַ⁠שָּׁמַ֔יִם וְ⁠אֶסְלַח֙ לְ⁠חַטָּאתָ֔⁠ם וְ⁠אֶרְפָּ֖א אֶת־אַרְצָֽ⁠ם׃","wĕ⁠yiká̇nĕʻ֨ẇ ʻami̇֜⁠y ʼàşě֧r niֽqĕráʼ-şĕ̌mi֣⁠y ʻàléy⁠he֗m wĕ⁠yiֽţĕpȧֽlĕlẇ֙ wiֽ⁠ybaqĕş֣̌ẇ pána֔⁠y wĕ⁠yáşǔ֖bẇ mi⁠dȧrĕkéy⁠he֣m há⁠ráʻi֑ym wa⁠ʼàniy֙ ʼeşĕ̌ma֣ʻ min-ha⁠şá̇̌ma֔yim wĕ⁠ʼesĕlaẖ֙ lĕ⁠ẖatá̇ʼţá֔⁠m wĕ⁠ʼerĕpá֖̇ʼ ʼeţ-ʼarĕẕáֽ⁠m׃"],[7,15,"עַתָּ֗ה עֵינַ⁠י֙ יִהְי֣וּ פְתֻח֔וֹת וְ⁠אָזְנַ֖⁠י קַשֻּׁב֑וֹת לִ⁠תְפִלַּ֖ת הַ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","ʻaţá̇֗h ʻéyna⁠y֙ yihĕy֣ẇ pĕţuẖ֔wòţ wĕ⁠ʼázĕna֖⁠y qaşu̇̌b֑wòţ li⁠ţĕpilȧ֖ţ ha⁠má̇q֥wòm ha⁠zėֽh׃"],[7,16,"וְ⁠עַתָּ֗ה בָּחַ֤רְתִּי וְ⁠הִקְדַּ֨שְׁתִּי֙ אֶת־הַ⁠בַּ֣יִת הַ⁠זֶּ֔ה לִ⁠הְיוֹת־שְׁמִ֥⁠י שָׁ֖ם עַד־עוֹלָ֑ם וְ⁠הָי֨וּ עֵינַ֧⁠י וְ⁠לִבִּ֛⁠י שָׁ֖ם כָּל־הַ⁠יָּמִֽים׃","wĕ⁠ʻaţá̇֗h bá̇ẖa֤rĕţi̇y wĕ⁠hiqĕdȧ֨şĕ̌ţi̇y֙ ʼeţ-ha⁠bȧ֣yiţ ha⁠zė֔h li⁠hĕywòţ-şĕ̌mi֥⁠y şá֖̌m ʻad-ʻwòlá֑m wĕ⁠háy֨ẇ ʻéyna֧⁠y wĕ⁠libi֛̇⁠y şá֖̌m ká̇l-ha⁠yá̇miֽym׃"],[7,17,"וְ⁠אַתָּ֞ה אִם־תֵּלֵ֣ךְ לְ⁠פָנַ֗⁠י כַּ⁠אֲשֶׁ֤ר הָלַךְ֙ דָּוִ֣יד אָבִ֔י⁠ךָ וְ⁠לַ⁠עֲשׂ֕וֹת כְּ⁠כֹ֖ל אֲשֶׁ֣ר צִוִּיתִ֑י⁠ךָ וְ⁠חֻקַּ֥⁠י וּ⁠מִשְׁפָּטַ֖⁠י תִּשְׁמֽוֹר׃","wĕ⁠ʼaţá̇֞h ʼim-ţé̇lé֣kĕ lĕ⁠pána֗⁠y kȧ⁠ʼàşě֤r hálakĕ֙ dá̇wi֣yd ʼábi֔y⁠ká wĕ⁠la⁠ʻàş̂֕wòţ kĕ̇⁠kò֖l ʼàşě֣r ẕiwi̇yţi֑y⁠ká wĕ⁠ẖuqȧ֥⁠y ẇ⁠mişĕ̌pá̇ta֖⁠y ţi̇şĕ̌mֽwòr׃"],[7,18,"וַ⁠הֲקִ֣ימוֹתִ֔י אֵ֖ת כִּסֵּ֣א מַלְכוּתֶ֑⁠ךָ כַּ⁠אֲשֶׁ֣ר כָּרַ֗תִּי לְ⁠דָוִ֤יד אָבִ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר לֹֽא־יִכָּרֵ֤ת לְ⁠ךָ֙ אִ֔ישׁ מוֹשֵׁ֖ל בְּ⁠יִשְׂרָאֵֽל׃","wa⁠hàqi֣ymwòţi֔y ʼé֖ţ ki̇sé֣̇ʼ malĕkẇţe֑⁠ká kȧ⁠ʼàşě֣r ká̇ra֗ţi̇y lĕ⁠dáwi֤yd ʼábi֨y⁠ká֙ lé⁠ʼmò֔r lòֽʼ-yiká̇ré֤ţ lĕ⁠ká֙ ʼi֔yş̌ mwòşé֖̌l bĕ̇⁠yişĕ̂ráʼéֽl׃"],[7,19,"וְ⁠אִם־תְּשׁוּב֣וּ⁠ן אַתֶּ֔ם וַ⁠עֲזַבְתֶּם֙ חֻקּוֹתַ֣⁠י וּ⁠מִצְוֺתַ֔⁠י אֲשֶׁ֥ר נָתַ֖תִּי לִ⁠פְנֵי⁠כֶ֑ם וַ⁠הֲלַכְתֶּ֗ם וַ⁠עֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְ⁠הִשְׁתַּחֲוִיתֶ֖ם לָ⁠הֶֽם׃","wĕ⁠ʼim-ţĕ̇ş̌ẇb֣ẇ⁠n ʼaţė֔m wa⁠ʻàzabĕţėm֙ ẖuq̇wòţa֣⁠y ẇ⁠miẕĕwֺţa֔⁠y ʼàşě֥r náţa֖ţi̇y li⁠pĕnéy⁠ke֑m wa⁠hàlakĕţė֗m wa⁠ʻàbadĕţėm֙ ʼèlòhi֣ym ʼàẖéri֔ym wĕ⁠hişĕ̌ţȧẖàwiyţe֖m lá⁠heֽm׃"],[7,20,"וּ⁠נְתַשְׁתִּ֗י⁠ם מֵ⁠עַ֤ל אַדְמָתִ⁠י֙ אֲשֶׁ֣ר נָתַ֣תִּי לָ⁠הֶ֔ם וְ⁠אֶת־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ אֲשֶׁ֣ר הִקְדַּ֣שְׁתִּי לִ⁠שְׁמִ֔⁠י אַשְׁלִ֖יךְ מֵ⁠עַ֣ל פָּנָ֑⁠י וְ⁠אֶתְּנֶ֛⁠נּוּ לְ⁠מָשָׁ֥ל וְ⁠לִ⁠שְׁנִינָ֖ה בְּ⁠כָל־הָ⁠עַמִּֽים׃","ẇ⁠nĕţaşĕ̌ţi̇֗y⁠m mé⁠ʻa֤l ʼadĕmáţi⁠y֙ ʼàşě֣r náţa֣ţi̇y lá⁠he֔m wĕ⁠ʼeţ-ha⁠bȧ֤yiţ ha⁠zėh֙ ʼàşě֣r hiqĕdȧ֣şĕ̌ţi̇y li⁠şĕ̌mi֔⁠y ʼaşĕ̌li֖ykĕ mé⁠ʻa֣l pá̇ná֑⁠y wĕ⁠ʼeţĕ̇ne֛⁠ṅẇ lĕ⁠máşá֥̌l wĕ⁠li⁠şĕ̌niyná֖h bĕ̇⁠kál-há⁠ʻamiֽ̇ym׃"],[7,21,"וְ⁠הַ⁠בַּ֤יִת הַ⁠זֶּה֙ אֲשֶׁ֣ר הָיָ֣ה עֶלְי֔וֹן לְ⁠כָל־עֹבֵ֥ר עָלָ֖י⁠ו יִשֹּׁ֑ם וְ⁠אָמַ֗ר בַּ⁠מֶּ֨ה עָשָׂ֤ה יְהוָה֙ כָּ֔כָה לָ⁠אָ֥רֶץ הַ⁠זֹּ֖את וְ⁠לַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","wĕ⁠ha⁠bȧ֤yiţ ha⁠zėh֙ ʼàşě֣r háyá֣h ʻelĕy֔wòn lĕ⁠kál-ʻòbé֥r ʻálá֖y⁠w yişò֑̇̌m wĕ⁠ʼáma֗r bȧ⁠mė֨h ʻáşá֤̂h yĕhwáh֙ ká̇֔káh lá⁠ʼá֥reẕ ha⁠zò֖̇ʼţ wĕ⁠la⁠bȧ֥yiţ ha⁠zėֽh׃"],[7,22,"וְ⁠אָמְר֗וּ עַל֩ אֲשֶׁ֨ר עָֽזְב֜וּ אֶת־יְהוָ֣ה ׀ אֱלֹהֵ֣י אֲבֹתֵי⁠הֶ֗ם אֲשֶׁ֣ר הוֹצִיאָ⁠ם֮ מֵ⁠אֶ֣רֶץ מִצְרַיִם֒ וַֽ⁠יַּחֲזִ֨יקוּ֙ בֵּ⁠אלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יִּשְׁתַּחֲו֥וּ לָ⁠הֶ֖ם וַ⁠יַּֽעַבְד֑וּ⁠ם עַל־כֵּן֙ הֵבִ֣יא עֲלֵי⁠הֶ֔ם אֵ֥ת כָּל־הָ⁠רָעָ֖ה הַ⁠זֹּֽאת׃פ","wĕ⁠ʼámĕr֗ẇ ʻal֩ ʼàşě֨r ʻáֽzĕb֜ẇ ʼeţ-yĕhwá֣h ׀ ʼèlòhé֣y ʼàbòţéy⁠he֗m ʼàşě֣r hwòẕiyʼá⁠m֮ mé⁠ʼe֣reẕ miẕĕrayim֒ waֽ⁠yȧẖàzi֨yqẇ֙ bé̇⁠ʼlòhi֣ym ʼàẖéri֔ym wa⁠yi̇şĕ̌ţȧẖàw֥ẇ lá⁠he֖m wa⁠yȧֽʻabĕd֑ẇ⁠m ʻal-ké̇n֙ hébi֣yʼ ʻàléy⁠he֔m ʼé֥ţ ká̇l-há⁠ráʻá֖h ha⁠zòֽ̇ʼţ׃p"],[8,1,"וַ⁠יְהִ֞י מִ⁠קֵּ֣ץ ׀ עֶשְׂרִ֣ים שָׁנָ֗ה אֲשֶׁ֨ר בָּנָ֧ה שְׁלֹמֹ֛ה אֶת־בֵּ֥ית יְהוָ֖ה וְ⁠אֶת־בֵּיתֽ⁠וֹ׃","wa⁠yĕhi֞y mi⁠qé֣̇ẕ ׀ ʻeşĕ̂ri֣ym şá̌ná֗h ʼàşě֨r bá̇ná֧h şĕ̌lòmò֛h ʼeţ-bé֥̇yţ yĕhwá֖h wĕ⁠ʼeţ-bé̇yţֽ⁠wò׃"],[8,2,"וְ⁠הֶ⁠עָרִ֗ים אֲשֶׁ֨ר נָתַ֤ן חוּרָם֙ לִ⁠שְׁלֹמֹ֔ה בָּנָ֥ה שְׁלֹמֹ֖ה אֹתָ֑⁠ם וַ⁠יּ֥וֹשֶׁב שָׁ֖ם אֶת־בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠he⁠ʻári֗ym ʼàşě֨r náţa֤n ẖẇrám֙ li⁠şĕ̌lòmò֔h bá̇ná֥h şĕ̌lòmò֖h ʼòţá֑⁠m wa⁠ẏ֥wòşěb şá֖̌m ʼeţ-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[8,3,"וַ⁠יֵּ֤לֶךְ שְׁלֹמֹה֙ חֲמָ֣ת צוֹבָ֔ה וַ⁠יֶּחֱזַ֖ק עָלֶֽי⁠הָ׃","wa⁠yé֤̇lekĕ şĕ̌lòmòh֙ ẖàmá֣ţ ẕwòbá֔h wa⁠yėẖèza֖q ʻáleֽy⁠há׃"],[8,4,"וַ⁠יִּ֥בֶן אֶת־תַּדְמֹ֖ר בַּ⁠מִּדְבָּ֑ר וְ⁠אֵת֙ כָּל־עָרֵ֣י הַֽ⁠מִּסְכְּנ֔וֹת אֲשֶׁ֥ר בָּנָ֖ה בַּ⁠חֲמָֽת׃","wa⁠yi֥̇ben ʼeţ-ţȧdĕmò֖r bȧ⁠mi̇dĕbá֑̇r wĕ⁠ʼéţ֙ ká̇l-ʻáré֣y haֽ⁠mi̇sĕkĕ̇n֔wòţ ʼàşě֥r bá̇ná֖h bȧ⁠ẖàmáֽţ׃"],[8,5,"וַ⁠יִּ֜בֶן אֶת־בֵּ֤ית חוֹרוֹן֙ הָֽ⁠עֶלְי֔וֹן וְ⁠אֶת־בֵּ֥ית חוֹר֖וֹן הַ⁠תַּחְתּ֑וֹן עָרֵ֣י מָצ֔וֹר חוֹמ֖וֹת דְּלָתַ֥יִם וּ⁠בְרִֽיחַ׃","wa⁠yi̇֜ben ʼeţ-bé֤̇yţ ẖwòrwòn֙ háֽ⁠ʻelĕy֔wòn wĕ⁠ʼeţ-bé֥̇yţ ẖwòr֖wòn ha⁠ţȧẖĕţ֑̇wòn ʻáré֣y máẕ֔wòr ẖwòm֖wòţ dĕ̇láţa֥yim ẇ⁠bĕriֽyẖa׃"],[8,6,"וְ⁠אֶֽת־בַּעֲלָ֗ת וְ⁠אֵ֨ת כָּל־עָרֵ֤י הַֽ⁠מִּסְכְּנוֹת֙ אֲשֶׁ֣ר הָי֣וּ לִ⁠שְׁלֹמֹ֔ה וְ⁠אֵת֙ כָּל־עָרֵ֣י הָ⁠רֶ֔כֶב וְ⁠אֵ֖ת עָרֵ֣י הַ⁠פָּרָשִׁ֑ים וְ⁠אֵ֣ת ׀ כָּל־חֵ֣שֶׁק שְׁלֹמֹ֗ה אֲשֶׁ֤ר חָשַׁק֙ לִ⁠בְנ֤וֹת בִּ⁠ירֽוּשָׁלִַ֨ם֙ וּ⁠בַ⁠לְּבָנ֔וֹן וּ⁠בְ⁠כֹ֖ל אֶ֥רֶץ מֶמְשַׁלְתּֽ⁠וֹ׃","wĕ⁠ʼeֽţ-bȧʻàlá֗ţ wĕ⁠ʼé֨ţ ká̇l-ʻáré֤y haֽ⁠mi̇sĕkĕ̇nwòţ֙ ʼàşě֣r háy֣ẇ li⁠şĕ̌lòmò֔h wĕ⁠ʼéţ֙ ká̇l-ʻáré֣y há⁠re֔keb wĕ⁠ʼé֖ţ ʻáré֣y ha⁠pá̇ráşǐ֑ym wĕ⁠ʼé֣ţ ׀ ká̇l-ẖé֣şěq şĕ̌lòmò֗h ʼàşě֤r ẖáşǎq֙ li⁠bĕn֤wòţ bi̇⁠yrֽẇşá̌lia֨m֙ ẇ⁠ba⁠lĕ̇bán֔wòn ẇ⁠bĕ⁠kò֖l ʼe֥reẕ memĕşǎlĕţֽ̇⁠wò׃"],[8,7,"כָּל־הָ֠⁠עָם הַ⁠נּוֹתָ֨ר מִן־הַ⁠חִתִּ֜י וְ⁠הָ⁠אֱמֹרִ֤י וְ⁠הַ⁠פְּרִזִּי֙ וְ⁠הַ⁠חִוִּ֣י וְ⁠הַ⁠יְבוּסִ֔י אֲשֶׁ֛ר לֹ֥א מִ⁠יִּשְׂרָאֵ֖ל הֵֽמָּה׃","ká̇l-há֠⁠ʻám ha⁠ṅwòţá֨r min-ha⁠ẖiţi̇֜y wĕ⁠há⁠ʼèmòri֤y wĕ⁠ha⁠pĕ̇rizi̇y֙ wĕ⁠ha⁠ẖiwi֣̇y wĕ⁠ha⁠yĕbẇsi֔y ʼàşě֛r lò֥ʼ mi⁠yi̇şĕ̂ráʼé֖l héֽmá̇h׃"],[8,8,"מִן־בְּנֵי⁠הֶ֗ם אֲשֶׁ֨ר נוֹתְר֤וּ אַחֲרֵי⁠הֶם֙ בָּ⁠אָ֔רֶץ אֲשֶׁ֥ר לֹֽא־כִלּ֖וּ⁠ם בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יַּעֲלֵ֤⁠ם שְׁלֹמֹה֙ לְ⁠מַ֔ס עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","min-bĕ̇néy⁠he֗m ʼàşě֨r nwòţĕr֤ẇ ʼaẖàréy⁠hem֙ bá̇⁠ʼá֔reẕ ʼàşě֥r lòֽʼ-kil֖̇ẇ⁠m bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yȧʻàlé֤⁠m şĕ̌lòmòh֙ lĕ⁠ma֔s ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[8,9,"וּ⁠מִן־בְּנֵי֙ יִשְׂרָאֵ֔ל אֲ֠שֶׁר לֹא־נָתַ֧ן שְׁלֹמֹ֛ה לַ⁠עֲבָדִ֖ים לִ⁠מְלַאכְתּ֑⁠וֹ כִּי־הֵ֜מָּה אַנְשֵׁ֤י מִלְחָמָה֙ וְ⁠שָׂרֵ֣י שָׁלִישָׁ֔י⁠ו וְ⁠שָׂרֵ֥י רִכְבּ֖⁠וֹ וּ⁠פָרָשָֽׁי⁠ו׃פ","ẇ⁠min-bĕ̇néy֙ yişĕ̂ráʼé֔l ʼà֠şěr lòʼ-náţa֧n şĕ̌lòmò֛h la⁠ʻàbádi֖ym li⁠mĕlaʼkĕţ֑̇⁠wò ki̇y-hé֜má̇h ʼanĕşé֤̌y milĕẖámáh֙ wĕ⁠şá̂ré֣y şá̌liyşá̌֔y⁠w wĕ⁠şá̂ré֥y rikĕḃ֖⁠wò ẇ⁠páráşáֽ̌y⁠w׃p"],[8,10,"וְ⁠אֵ֨לֶּה שָׂרֵ֤י ה⁠נציבים אֲשֶׁר־לַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה חֲמִשִּׁ֣ים וּ⁠מָאתָ֑יִם הָ⁠רֹדִ֖ים בָּ⁠עָֽם׃","wĕ⁠ʼé֨lėh şá̂ré֤y h⁠nẕybym ʼàşěr-la⁠mė֥lekĕ şĕ̌lòmò֖h ẖàmişi֣̇̌ym ẇ⁠máʼţá֑yim há⁠ròdi֖ym bá̇⁠ʻáֽm׃"],[8,11,"וְ⁠אֶת־בַּת־פַּרְעֹ֗ה הֶעֱלָ֤ה שְׁלֹמֹה֙ מֵ⁠עִ֣יר דָּוִ֔יד לַ⁠בַּ֖יִת אֲשֶׁ֣ר בָּֽנָה־לָ֑⁠הּ כִּ֣י אָמַ֗ר לֹא־תֵשֵׁ֨ב אִשָּׁ֥ה לִ⁠י֙ בְּ⁠בֵית֙ דָּוִ֣יד מֶֽלֶךְ־יִשְׂרָאֵ֔ל כִּי־קֹ֣דֶשׁ הֵ֔מָּה אֲשֶׁר־בָּֽאָ֥ה אֲלֵי⁠הֶ֖ם אֲר֥וֹן יְהוָֽה׃פ","wĕ⁠ʼeţ-bȧţ-pȧrĕʻò֗h heʻèlá֤h şĕ̌lòmòh֙ mé⁠ʻi֣yr dá̇wi֔yd la⁠bȧ֖yiţ ʼàşě֣r báֽ̇náh-lá֑⁠ḣ ki֣̇y ʼáma֗r lòʼ-ţéşé̌֨b ʼişá֥̇̌h li⁠y֙ bĕ̇⁠béyţ֙ dá̇wi֣yd meֽlekĕ-yişĕ̂ráʼé֔l ki̇y-qò֣deş̌ hé֔má̇h ʼàşěr-báֽ̇ʼá֥h ʼàléy⁠he֖m ʼàr֥wòn yĕhwáֽh׃p"],[8,12,"אָ֣ז הֶעֱלָ֧ה שְׁלֹמֹ֛ה עֹל֖וֹת לַ⁠יהוָ֑ה עַ֚ל מִזְבַּ֣ח יְהוָ֔ה אֲשֶׁ֥ר בָּנָ֖ה לִ⁠פְנֵ֥י הָ⁠אוּלָֽם׃","ʼá֣z heʻèlá֧h şĕ̌lòmò֛h ʻòl֖wòţ la⁠yhwá֑h ʻa֚l mizĕbȧ֣ẖ yĕhwá֔h ʼàşě֥r bá̇ná֖h li⁠pĕné֥y há⁠ʼẇláֽm׃"],[8,13,"וּ⁠בִ⁠דְבַר־י֣וֹם בְּ⁠י֗וֹם לְ⁠הַעֲלוֹת֙ כְּ⁠מִצְוַ֣ת מֹשֶׁ֔ה לַ⁠שַּׁבָּתוֹת֙ וְ⁠לֶ֣⁠חֳדָשִׁ֔ים וְ⁠לַ⁠מּ֣וֹעֲד֔וֹת שָׁל֥וֹשׁ פְּעָמִ֖ים בַּ⁠שָּׁנָ֑ה בְּ⁠חַ֧ג הַ⁠מַּצּ֛וֹת וּ⁠בְ⁠חַ֥ג הַ⁠שָּׁבֻע֖וֹת וּ⁠בְ⁠חַ֥ג הַ⁠סֻּכּֽוֹת׃","ẇ⁠bi⁠dĕbar-y֣wòm bĕ̇⁠y֗wòm lĕ⁠haʻàlwòţ֙ kĕ̇⁠miẕĕwa֣ţ mòşě֔h la⁠şȧ̌bá̇ţwòţ֙ wĕ⁠le֣⁠ẖodáşǐ֔ym wĕ⁠la⁠ṁ֣wòʻàd֔wòţ şá̌l֥wòş̌ pĕ̇ʻámi֖ym bȧ⁠şá̇̌ná֑h bĕ̇⁠ẖa֧g ha⁠mȧẕ֛̇wòţ ẇ⁠bĕ⁠ẖa֥g ha⁠şá̇̌buʻ֖wòţ ẇ⁠bĕ⁠ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[8,14,"וַ⁠יַּעֲמֵ֣ד כְּ⁠מִשְׁפַּ֣ט דָּֽוִיד־אָ֠בִי⁠ו אֶת־מַחְלְק֨וֹת הַ⁠כֹּהֲנִ֜ים עַל־עֲבֹדָתָ֗⁠ם וְ⁠הַ⁠לְוִיִּ֣ם עַל־מִ֠שְׁמְרוֹתָ⁠ם לְ⁠הַלֵּ֨ל וּ⁠לְ⁠שָׁרֵ֜ת נֶ֤גֶד הַ⁠כֹּֽהֲנִים֙ לִ⁠דְבַר־י֣וֹם בְּ⁠יוֹמ֔⁠וֹ וְ⁠הַ⁠שּׁוֹעֲרִ֥ים בְּ⁠מַחְלְקוֹתָ֖⁠ם לְ⁠שַׁ֣עַר וָ⁠שָׁ֑עַר כִּ֣י כֵ֔ן מִצְוַ֖ת דָּוִ֥יד אִישׁ־הָ⁠אֱלֹהִֽים׃","wa⁠yȧʻàmé֣d kĕ̇⁠mişĕ̌pȧ֣t dáֽ̇wiyd-ʼá֠biy⁠w ʼeţ-maẖĕlĕq֨wòţ ha⁠kò̇hàni֜ym ʻal-ʻàbòdáţá֗⁠m wĕ⁠ha⁠lĕwiyi֣̇m ʻal-mi֠şĕ̌mĕrwòţá⁠m lĕ⁠halé̇֨l ẇ⁠lĕ⁠şá̌ré֜ţ ne֤ged ha⁠kòֽ̇hàniym֙ li⁠dĕbar-y֣wòm bĕ̇⁠ywòm֔⁠wò wĕ⁠ha⁠ş̇̌wòʻàri֥ym bĕ̇⁠maẖĕlĕqwòţá֖⁠m lĕ⁠şǎ֣ʻar wá⁠şá֑̌ʻar ki֣̇y ké֔n miẕĕwa֖ţ dá̇wi֥yd ʼiyş̌-há⁠ʼèlòhiֽym׃"],[8,15,"וְ⁠לֹ֣א סָרוּ֩ מִצְוַ֨ת הַ⁠מֶּ֜לֶךְ עַל־הַ⁠כֹּהֲנִ֧ים וְ⁠הַ⁠לְוִיִּ֛ם לְ⁠כָל־דָּבָ֖ר וְ⁠לָ⁠אֹצָרֽוֹת׃","wĕ⁠lò֣ʼ sárẇ֩ miẕĕwa֨ţ ha⁠mė֜lekĕ ʻal-ha⁠kò̇hàni֧ym wĕ⁠ha⁠lĕwiyi֛̇m lĕ⁠kál-dá̇bá֖r wĕ⁠lá⁠ʼòẕárֽwòţ׃"],[8,16,"וַ⁠תִּכֹּן֙ כָּל־מְלֶ֣אכֶת שְׁלֹמֹ֔ה עַד־הַ⁠יּ֛וֹם מוּסַ֥ד בֵּית־יְהוָ֖ה וְ⁠עַד־כְּלֹת֑⁠וֹ שָׁלֵ֖ם בֵּ֥ית יְהוָֽה׃ס","wa⁠ţi̇kò̇n֙ ká̇l-mĕle֣ʼkeţ şĕ̌lòmò֔h ʻad-ha⁠ẏ֛wòm mẇsa֥d bé̇yţ-yĕhwá֖h wĕ⁠ʻad-kĕ̇lòţ֑⁠wò şá̌lé֖m bé֥̇yţ yĕhwáֽh׃s"],[8,17,"אָז֩ הָלַ֨ךְ שְׁלֹמֹ֜ה לְ⁠עֶצְיֽוֹן־גֶּ֧בֶר וְ⁠אֶל־אֵיל֛וֹת עַל־שְׂפַ֥ת הַ⁠יָּ֖ם בְּ⁠אֶ֥רֶץ אֱדֽוֹם׃","ʼáz֩ hála֨kĕ şĕ̌lòmò֜h lĕ⁠ʻeẕĕyֽwòn-gė֧ber wĕ⁠ʼel-ʼéyl֛wòţ ʻal-şĕ̂pa֥ţ ha⁠yá֖̇m bĕ̇⁠ʼe֥reẕ ʼèdֽwòm׃"],[8,18,"וַ⁠יִּֽשְׁלַֽח־ל⁠וֹ֩ חוּרָ֨ם בְּ⁠יַד־עֲבָדָ֜י⁠ו אוניות וַ⁠עֲבָדִים֮ י֣וֹדְעֵי יָם֒ וַ⁠יָּבֹ֜אוּ עִם־עַבְדֵ֤י שְׁלֹמֹה֙ אוֹפִ֔ירָ⁠ה וַ⁠יִּקְח֣וּ מִ⁠שָּׁ֔ם אַרְבַּע־מֵא֥וֹת וַ⁠חֲמִשִּׁ֖ים כִּכַּ֣ר זָהָ֑ב וַ⁠יָּבִ֖יאוּ אֶל־הַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃פ","wa⁠yiֽ̇şĕ̌laֽẖ-l⁠wò֩ ẖẇrá֨m bĕ̇⁠yad-ʻàbádá֜y⁠w ʼwnywţ wa⁠ʻàbádiym֮ y֣wòdĕʻéy yám֒ wa⁠yá̇bò֜ʼẇ ʻim-ʻabĕdé֤y şĕ̌lòmòh֙ ʼwòpi֔yrá⁠h wa⁠yi̇qĕẖ֣ẇ mi⁠şá̇̌֔m ʼarĕbȧʻ-méʼ֥wòţ wa⁠ẖàmişi֖̇̌ym ki̇kȧ֣r záhá֑b wa⁠yá̇bi֖yʼẇ ʼel-ha⁠mė֥lekĕ şĕ̌lòmòֽh׃p"],[9,1,"וּ⁠מַֽלְכַּת־שְׁבָ֗א שָֽׁמְעָה֮ אֶת־שֵׁ֣מַע שְׁלֹמֹה֒ וַ⁠תָּב֣וֹא לְ⁠נַסּוֹת֩ אֶת־שְׁלֹמֹ֨ה בְ⁠חִיד֜וֹת בִּ⁠ירֽוּשָׁלִַ֗ם בְּ⁠חַ֣יִל כָּבֵ֣ד מְאֹ֡ד וּ֠⁠גְמַלִּים נֹשְׂאִ֨ים בְּשָׂמִ֧ים וְ⁠זָהָ֛ב לָ⁠רֹ֖ב וְ⁠אֶ֣בֶן יְקָרָ֑ה וַ⁠תָּבוֹא֙ אֶל־שְׁלֹמֹ֔ה וַ⁠תְּדַבֵּ֣ר עִמּ֔⁠וֹ אֵ֛ת כָּל־אֲשֶׁ֥ר הָיָ֖ה עִם־לְבָבָֽ⁠הּ׃","ẇ⁠maֽlĕkȧţ-şĕ̌bá֗ʼ şáֽ̌mĕʻáh֮ ʼeţ-şé֣̌maʻ şĕ̌lòmòh֒ wa⁠ţá̇b֣wòʼ lĕ⁠naṡwòţ֩ ʼeţ-şĕ̌lòmò֨h bĕ⁠ẖiyd֜wòţ bi̇⁠yrֽẇşá̌lia֗m bĕ̇⁠ẖa֣yil ká̇bé֣d mĕʼò֡d ẇ֠⁠gĕmali̇ym nòşĕ̂ʼi֨ym bĕ̇şá̂mi֧ym wĕ⁠záhá֛b lá⁠rò֖b wĕ⁠ʼe֣ben yĕqárá֑h wa⁠ţá̇bwòʼ֙ ʼel-şĕ̌lòmò֔h wa⁠ţĕ̇dabé֣̇r ʻiṁ֔⁠wò ʼé֛ţ ká̇l-ʼàşě֥r háyá֖h ʻim-lĕbábáֽ⁠ḣ׃"],[9,2,"וַ⁠יַּגֶּד־לָ֥⁠הּ שְׁלֹמֹ֖ה אֶת־כָּל־דְּבָרֶ֑י⁠הָ וְ⁠לֹֽא־נֶעְלַ֤ם דָּבָר֙ מִ⁠שְּׁלֹמֹ֔ה אֲשֶׁ֧ר לֹ֦א הִגִּ֖יד לָֽ⁠הּ׃","wa⁠yȧgėd-lá֥⁠ḣ şĕ̌lòmò֖h ʼeţ-ká̇l-dĕ̇báre֑y⁠há wĕ⁠lòֽʼ-neʻĕla֤m dá̇bár֙ mi⁠şĕ̇̌lòmò֔h ʼàşě֧r lò֦ʼ higi֖̇yd láֽ⁠ḣ׃"],[9,3,"וַ⁠תֵּ֨רֶא֙ מַֽלְכַּת־שְׁבָ֔א אֵ֖ת חָכְמַ֣ת שְׁלֹמֹ֑ה וְ⁠הַ⁠בַּ֖יִת אֲשֶׁ֥ר בָּנָֽה׃","wa⁠ţé̇֨reʼ֙ maֽlĕkȧţ-şĕ̌bá֔ʼ ʼé֖ţ ẖákĕma֣ţ şĕ̌lòmò֑h wĕ⁠ha⁠bȧ֖yiţ ʼàşě֥r bá̇náֽh׃"],[9,4,"וּ⁠מַאֲכַ֣ל שֻׁלְחָנ֡⁠וֹ וּ⁠מוֹשַׁ֣ב עֲבָדָי⁠ו֩ וּ⁠מַעֲמַ֨ד מְשָׁרְתָ֜י⁠ו וּ⁠מַלְבּֽוּשֵׁי⁠הֶ֗ם וּ⁠מַשְׁקָי⁠ו֙ וּ⁠מַלְבּ֣וּשֵׁי⁠הֶ֔ם וַ⁠עֲלִיָּת֔⁠וֹ אֲשֶׁ֥ר יַעֲלֶ֖ה בֵּ֣ית יְהוָ֑ה וְ⁠לֹא־הָ֥יָה ע֛וֹד בָּ֖⁠הּ רֽוּחַ׃","ẇ⁠maʼàka֣l şǔlĕẖán֡⁠wò ẇ⁠mwòşǎ֣b ʻàbádáy⁠w֩ ẇ⁠maʻàma֨d mĕşá̌rĕţá֜y⁠w ẇ⁠malĕḃֽẇşé̌y⁠he֗m ẇ⁠maşĕ̌qáy⁠w֙ ẇ⁠malĕḃ֣ẇşé̌y⁠he֔m wa⁠ʻàliyá̇ţ֔⁠wò ʼàşě֥r yaʻàle֖h bé֣̇yţ yĕhwá֑h wĕ⁠lòʼ-há֥yáh ʻ֛wòd bá֖̇⁠ḣ rֽẇẖa׃"],[9,5,"וַ⁠תֹּ֨אמֶר֙ אֶל־הַ⁠מֶּ֔לֶךְ אֱמֶת֙ הַ⁠דָּבָ֔ר אֲשֶׁ֥ר שָׁמַ֖עְתִּי בְּ⁠אַרְצִ֑⁠י עַל־דְּבָרֶ֖י⁠ךָ וְ⁠עַל־חָכְמָתֶֽ⁠ךָ׃","wa⁠ţò̇֨ʼmer֙ ʼel-ha⁠mė֔lekĕ ʼèmeţ֙ ha⁠dá̇bá֔r ʼàşě֥r şá̌ma֖ʻĕţi̇y bĕ̇⁠ʼarĕẕi֑⁠y ʻal-dĕ̇báre֖y⁠ká wĕ⁠ʻal-ẖákĕmáţeֽ⁠ká׃"],[9,6,"וְ⁠לֹֽא־הֶאֱמַ֣נְתִּי לְ⁠דִבְרֵי⁠הֶ֗ם עַ֤ד אֲשֶׁר־בָּ֨אתִי֙ וַ⁠תִּרְאֶ֣ינָה עֵינַ֔⁠י וְ⁠הִנֵּה֙ לֹ֣א הֻגַּד־לִ֔⁠י חֲצִ֖י מַרְבִּ֣ית חָכְמָתֶ֑⁠ךָ יָסַ֕פְתָּ עַל־הַ⁠שְּׁמוּעָ֖ה אֲשֶׁ֥ר שָׁמָֽעְתִּי׃","wĕ⁠lòֽʼ-heʼèma֣nĕţi̇y lĕ⁠dibĕréy⁠he֗m ʻa֤d ʼàşěr-bá̇֨ʼţiy֙ wa⁠ţi̇rĕʼe֣ynáh ʻéyna֔⁠y wĕ⁠hiné̇h֙ lò֣ʼ hugȧd-li֔⁠y ẖàẕi֖y marĕbi֣̇yţ ẖákĕmáţe֑⁠ká yása֕pĕţá̇ ʻal-ha⁠şĕ̇̌mẇʻá֖h ʼàşě֥r şá̌máֽʻĕţi̇y׃"],[9,7,"אַשְׁרֵ֣י אֲנָשֶׁ֔י⁠ךָ וְ⁠אַשְׁרֵ֖י עֲבָדֶ֣י⁠ךָ אֵ֑לֶּה הָ⁠עֹמְדִ֤ים לְ⁠פָנֶ֨י⁠ךָ֙ תָּמִ֔יד וְ⁠שֹׁמְעִ֖ים אֶת־חָכְמָתֶֽ⁠ךָ׃","ʼaşĕ̌ré֣y ʼànáşě֔y⁠ká wĕ⁠ʼaşĕ̌ré֖y ʻàbáde֣y⁠ká ʼé֑lėh há⁠ʻòmĕdi֤ym lĕ⁠páne֨y⁠ká֙ ţá̇mi֔yd wĕ⁠şò̌mĕʻi֖ym ʼeţ-ẖákĕmáţeֽ⁠ká׃"],[9,8,"יְהִ֨י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בָּר֔וּךְ אֲשֶׁ֣ר ׀ חָפֵ֣ץ בְּ⁠ךָ֗ לְ⁠תִתְּ⁠ךָ֤ עַל־כִּסְא⁠וֹ֙ לְ⁠מֶ֔לֶךְ לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ בְּ⁠אַהֲבַ֨ת אֱלֹהֶ֤י⁠ךָ אֶת־יִשְׂרָאֵל֙ לְ⁠הַעֲמִיד֣⁠וֹ לְ⁠עוֹלָ֔ם וַ⁠יִּתֶּנְ⁠ךָ֤ עֲלֵי⁠הֶם֙ לְ⁠מֶ֔לֶךְ לַ⁠עֲשׂ֖וֹת מִשְׁפָּ֥ט וּ⁠צְדָקָֽה׃","yĕhi֨y yĕhwá֤h ʼèlòhe֨y⁠ká֙ bá̇r֔ẇkĕ ʼàşě֣r ׀ ẖápé֣ẕ bĕ̇⁠ká֗ lĕ⁠ţiţĕ̇⁠ká֤ ʻal-ki̇sĕʼ⁠wò֙ lĕ⁠me֔lekĕ la⁠yhwá֖h ʼèlòhe֑y⁠ká bĕ̇⁠ʼahàba֨ţ ʼèlòhe֤y⁠ká ʼeţ-yişĕ̂ráʼél֙ lĕ⁠haʻàmiyd֣⁠wò lĕ⁠ʻwòlá֔m wa⁠yi̇ţėnĕ⁠ká֤ ʻàléy⁠hem֙ lĕ⁠me֔lekĕ la⁠ʻàş֖̂wòţ mişĕ̌pá֥̇t ẇ⁠ẕĕdáqáֽh׃"],[9,9,"וַ⁠תִּתֵּ֨ן לַ⁠מֶּ֜לֶךְ מֵאָ֥ה וְ⁠עֶשְׂרִ֣ים ׀ כִּכַּ֣ר זָהָ֗ב וּ⁠בְשָׂמִ֛ים לָ⁠רֹ֥ב מְאֹ֖ד וְ⁠אֶ֣בֶן יְקָרָ֑ה וְ⁠לֹ֤א הָיָה֙ כַּ⁠בֹּ֣שֶׂם הַ⁠ה֔וּא אֲשֶׁר־נָתְנָ֥ה מַֽלְכַּת־שְׁבָ֖א לַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃","wa⁠ţi̇ţé̇֨n la⁠mė֜lekĕ méʼá֥h wĕ⁠ʻeşĕ̂ri֣ym ׀ ki̇kȧ֣r záhá֗b ẇ⁠bĕşá̂mi֛ym lá⁠rò֥b mĕʼò֖d wĕ⁠ʼe֣ben yĕqárá֑h wĕ⁠lò֤ʼ háyáh֙ kȧ⁠bò֣̇şêm ha⁠h֔ẇʼ ʼàşěr-náţĕná֥h maֽlĕkȧţ-şĕ̌bá֖ʼ la⁠mė֥lekĕ şĕ̌lòmòֽh׃"],[9,10,"וְ⁠גַם־עַבְדֵ֤י חירם וְ⁠עַבְדֵ֣י שְׁלֹמֹ֔ה אֲשֶׁר־הֵבִ֥יאוּ זָהָ֖ב מֵ⁠אוֹפִ֑יר הֵבִ֛יאוּ עֲצֵ֥י אַלְגּוּמִּ֖ים וְ⁠אֶ֥בֶן יְקָרָֽה׃","wĕ⁠gam-ʻabĕdé֤y ẖyrm wĕ⁠ʻabĕdé֣y şĕ̌lòmò֔h ʼàşěr-hébi֥yʼẇ záhá֖b mé⁠ʼwòpi֑yr hébi֛yʼẇ ʻàẕé֥y ʼalĕġẇmi֖̇ym wĕ⁠ʼe֥ben yĕqáráֽh׃"],[9,11,"וַ⁠יַּ֣עַשׂ הַ֠⁠מֶּלֶךְ אֶת־עֲצֵ֨י הָֽ⁠אַלְגּוּמִּ֜ים מְסִלּ֤וֹת לְ⁠בֵית־יְהוָה֙ וּ⁠לְ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠כִנֹּר֥וֹת וּ⁠נְבָלִ֖ים לַ⁠שָּׁרִ֑ים וְ⁠לֹא־נִרְא֥וּ כָ⁠הֵ֛ם לְ⁠פָנִ֖ים בְּ⁠אֶ֥רֶץ יְהוּדָֽה׃","wa⁠yȧ֣ʻaş̂ ha֠⁠mėlekĕ ʼeţ-ʻàẕé֨y háֽ⁠ʼalĕġẇmi̇֜ym mĕsil֤̇wòţ lĕ⁠béyţ-yĕhwáh֙ ẇ⁠lĕ⁠bé֣yţ ha⁠mė֔lekĕ wĕ⁠kinò̇r֥wòţ ẇ⁠nĕbáli֖ym la⁠şá̇̌ri֑ym wĕ⁠lòʼ-nirĕʼ֥ẇ ká⁠hé֛m lĕ⁠páni֖ym bĕ̇⁠ʼe֥reẕ yĕhẇdáֽh׃"],[9,12,"וְ⁠הַ⁠מֶּ֨לֶךְ שְׁלֹמֹ֜ה נָתַ֣ן לְ⁠מַֽלְכַּת־שְׁבָ֗א אֶת־כָּל־חֶפְצָ⁠הּ֙ אֲשֶׁ֣ר שָׁאָ֔לָה מִ⁠לְּ⁠בַ֖ד אֲשֶׁר־הֵבִ֣יאָה אֶל־הַ⁠מֶּ֑לֶךְ וַֽ⁠תַּהֲפֹ֛ךְ וַ⁠תֵּ֥לֶךְ לְ⁠אַרְצָ֖⁠הּ הִ֥יא וַ⁠עֲבָדֶֽי⁠הָ׃פ","wĕ⁠ha⁠mė֨lekĕ şĕ̌lòmò֜h náţa֣n lĕ⁠maֽlĕkȧţ-şĕ̌bá֗ʼ ʼeţ-ká̇l-ẖepĕẕá⁠ḣ֙ ʼàşě֣r şá̌ʼá֔láh mi⁠lĕ̇⁠ba֖d ʼàşěr-hébi֣yʼáh ʼel-ha⁠mė֑lekĕ waֽ⁠ţȧhàpò֛kĕ wa⁠ţé֥̇lekĕ lĕ⁠ʼarĕẕá֖⁠ḣ hi֥yʼ wa⁠ʻàbádeֽy⁠há׃p"],[9,13,"וַ⁠יְהִי֙ מִשְׁקַ֣ל הַ⁠זָּהָ֔ב אֲשֶׁר־בָּ֥א לִ⁠שְׁלֹמֹ֖ה בְּ⁠שָׁנָ֣ה אֶחָ֑ת שֵׁ֥שׁ מֵא֛וֹת וְ⁠שִׁשִּׁ֥ים וָ⁠שֵׁ֖שׁ כִּכְּרֵ֥י זָהָֽב׃","wa⁠yĕhiy֙ mişĕ̌qa֣l ha⁠zá̇há֔b ʼàşěr-bá֥̇ʼ li⁠şĕ̌lòmò֖h bĕ̇⁠şá̌ná֣h ʼeẖá֑ţ şé֥̌ş̌ méʼ֛wòţ wĕ⁠şǐşi֥̇̌ym wá⁠şé֖̌ş̌ ki̇kĕ̇ré֥y záháֽb׃"],[9,14,"לְ⁠בַ֞ד מֵ⁠אַנְשֵׁ֧י הַ⁠תָּרִ֛ים וְ⁠הַ⁠סֹּחֲרִ֖ים מְבִיאִ֑ים וְ⁠כָל־מַלְכֵ֤י עֲרַב֙ וּ⁠פַח֣וֹת הָ⁠אָ֔רֶץ מְבִיאִ֛ים זָהָ֥ב וָ⁠כֶ֖סֶף לִ⁠שְׁלֹמֹֽה׃","lĕ⁠ba֞d mé⁠ʼanĕşé֧̌y ha⁠ţá̇ri֛ym wĕ⁠ha⁠sò̇ẖàri֖ym mĕbiyʼi֑ym wĕ⁠kál-malĕké֤y ʻàrab֙ ẇ⁠paẖ֣wòţ há⁠ʼá֔reẕ mĕbiyʼi֛ym záhá֥b wá⁠ke֖sep li⁠şĕ̌lòmòֽh׃"],[9,15,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֧לֶךְ שְׁלֹמֹ֛ה מָאתַ֥יִם צִנָּ֖ה זָהָ֣ב שָׁח֑וּט שֵׁ֤שׁ מֵאוֹת֙ זָהָ֣ב שָׁח֔וּט יַעֲלֶ֖ה עַל־הַ⁠צִּנָּ֥ה הָ⁠אֶחָֽת׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֧lekĕ şĕ̌lòmò֛h máʼţa֥yim ẕiná֖̇h záhá֣b şá̌ẖ֑ẇt şé֤̌ş̌ méʼwòţ֙ záhá֣b şá̌ẖ֔ẇt yaʻàle֖h ʻal-ha⁠ẕi̇ná֥̇h há⁠ʼeẖáֽţ׃"],[9,16,"וּ⁠שְׁלֹשׁ־מֵא֤וֹת מָֽגִנִּים֙ זָהָ֣ב שָׁח֔וּט שְׁלֹ֤שׁ מֵאוֹת֙ זָהָ֔ב יַעֲלֶ֖ה עַל־הַ⁠מָּגֵ֣ן הָ⁠אֶחָ֑ת וַ⁠יִּתְּנֵ֣⁠ם הַ⁠מֶּ֔לֶךְ בְּ⁠בֵ֖ית יַ֥עַר הַ⁠לְּבָנֽוֹן׃פ","ẇ⁠şĕ̌lòş̌-méʼ֤wòţ máֽgini̇ym֙ záhá֣b şá̌ẖ֔ẇt şĕ̌lò֤ş̌ méʼwòţ֙ záhá֔b yaʻàle֖h ʻal-ha⁠má̇gé֣n há⁠ʼeẖá֑ţ wa⁠yi̇ţĕ̇né֣⁠m ha⁠mė֔lekĕ bĕ̇⁠bé֖yţ ya֥ʻar ha⁠lĕ̇bánֽwòn׃p"],[9,17,"וַ⁠יַּ֧עַשׂ הַ⁠מֶּ֛לֶךְ כִּסֵּא־שֵׁ֖ן גָּד֑וֹל וַ⁠יְצַפֵּ֖⁠הוּ זָהָ֥ב טָהֽוֹר׃","wa⁠yȧ֧ʻaş̂ ha⁠mė֛lekĕ ki̇sé̇ʼ-şé֖̌n gá̇d֑wòl wa⁠yĕẕapé֖̇⁠hẇ záhá֥b táhֽwòr׃"],[9,18,"וְ⁠שֵׁ֣שׁ מַעֲל֣וֹת לַ֠⁠כִּסֵּא וְ⁠כֶ֨בֶשׁ בַּ⁠זָּהָ֤ב לַ⁠כִּסֵּא֙ מָאֳחָזִ֔ים וְ⁠יָד֛וֹת מִ⁠זֶּ֥ה וּ⁠מִ⁠זֶּ֖ה עַל־מְק֣וֹם הַ⁠שָּׁ֑בֶת וּ⁠שְׁנַ֣יִם אֲרָי֔וֹת עֹמְדִ֖ים אֵ֥צֶל הַ⁠יָּדֽוֹת׃","wĕ⁠şé֣̌ş̌ maʻàl֣wòţ la֠⁠ki̇sé̇ʼ wĕ⁠ke֨beş̌ bȧ⁠zá̇há֤b la⁠ki̇sé̇ʼ֙ máʼoẖázi֔ym wĕ⁠yád֛wòţ mi⁠zė֥h ẇ⁠mi⁠zė֖h ʻal-mĕq֣wòm ha⁠şá֑̇̌beţ ẇ⁠şĕ̌na֣yim ʼàráy֔wòţ ʻòmĕdi֖ym ʼé֥ẕel ha⁠yá̇dֽwòţ׃"],[9,19,"וּ⁠שְׁנֵ֧ים עָשָׂ֣ר אֲרָי֗וֹת עֹמְדִ֥ים שָׁ֛ם עַל־שֵׁ֥שׁ הַֽ⁠מַּעֲל֖וֹת מִ⁠זֶּ֣ה וּ⁠מִ⁠זֶּ֑ה לֹא־נַעֲשָׂ֥ה כֵ֖ן לְ⁠כָל־מַמְלָכָֽה׃","ẇ⁠şĕ̌né֧ym ʻáşá֣̂r ʼàráy֗wòţ ʻòmĕdi֥ym şá֛̌m ʻal-şé֥̌ş̌ haֽ⁠mȧʻàl֖wòţ mi⁠zė֣h ẇ⁠mi⁠zė֑h lòʼ-naʻàşá֥̂h ké֖n lĕ⁠kál-mamĕlákáֽh׃"],[9,20,"וְ֠⁠כֹל כְּלֵ֞י מַשְׁקֵ֨ה הַ⁠מֶּ֤לֶךְ שְׁלֹמֹה֙ זָהָ֔ב וְ⁠כֹ֗ל כְּלֵ֛י בֵּֽית־יַ֥עַר הַ⁠לְּבָנ֖וֹן זָהָ֣ב סָג֑וּר אֵ֣ין כֶּ֗סֶף נֶחְשָׁ֛ב בִּ⁠ימֵ֥י שְׁלֹמֹ֖ה לִ⁠מְאֽוּמָה׃","wĕ֠⁠kòl kĕ̇lé֞y maşĕ̌qé֨h ha⁠mė֤lekĕ şĕ̌lòmòh֙ záhá֔b wĕ⁠kò֗l kĕ̇lé֛y béֽ̇yţ-ya֥ʻar ha⁠lĕ̇bán֖wòn záhá֣b ság֑ẇr ʼé֣yn kė֗sep neẖĕşá֛̌b bi̇⁠ymé֥y şĕ̌lòmò֖h li⁠mĕʼֽẇmáh׃"],[9,21,"כִּֽי־אֳנִיּ֤וֹת לַ⁠מֶּ֨לֶךְ֙ הֹלְכ֣וֹת תַּרְשִׁ֔ישׁ עִ֖ם עַבְדֵ֣י חוּרָ֑ם אַחַת֩ לְ⁠שָׁל֨וֹשׁ שָׁנִ֜ים תָּב֣וֹאנָה ׀ אֳנִיּ֣וֹת תַּרְשִׁ֗ישׁ נֹֽשְׂאוֹת֙ זָהָ֣ב וָ⁠כֶ֔סֶף שֶׁנְהַבִּ֥ים וְ⁠קוֹפִ֖ים וְ⁠תוּכִּיִּֽים׃פ","kiֽ̇y-ʼoniẏ֤wòţ la⁠mė֨lekĕ֙ hòlĕk֣wòţ ţȧrĕşǐ֔yş̌ ʻi֖m ʻabĕdé֣y ẖẇrá֑m ʼaẖaţ֩ lĕ⁠şá̌l֨wòş̌ şá̌ni֜ym ţá̇b֣wòʼnáh ׀ ʼoniẏ֣wòţ ţȧrĕşǐ֗yş̌ nòֽşĕ̂ʼwòţ֙ záhá֣b wá⁠ke֔sep şěnĕhabi֥̇ym wĕ⁠qwòpi֖ym wĕ⁠ţẇki̇yiֽ̇ym׃p"],[9,22,"וַ⁠יִּגְדַּל֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה מִ⁠כֹּ֖ל מַלְכֵ֣י הָ⁠אָ֑רֶץ לְ⁠עֹ֖שֶׁר וְ⁠חָכְמָֽה׃","wa⁠yi̇gĕdȧl֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h mi⁠kò֖̇l malĕké֣y há⁠ʼá֑reẕ lĕ⁠ʻò֖şěr wĕ⁠ẖákĕmáֽh׃"],[9,23,"וְ⁠כֹל֙ מַלְכֵ֣י הָ⁠אָ֔רֶץ מְבַקְשִׁ֖ים אֶת־פְּנֵ֣י שְׁלֹמֹ֑ה לִ⁠שְׁמֹ֨עַ֙ אֶת־חָכְמָת֔⁠וֹ אֲשֶׁר־נָתַ֥ן הָ⁠אֱלֹהִ֖ים בְּ⁠לִבּֽ⁠וֹ׃","wĕ⁠kòl֙ malĕké֣y há⁠ʼá֔reẕ mĕbaqĕşǐ֖ym ʼeţ-pĕ̇né֣y şĕ̌lòmò֑h li⁠şĕ̌mò֨ʻa֙ ʼeţ-ẖákĕmáţ֔⁠wò ʼàşěr-náţa֥n há⁠ʼèlòhi֖ym bĕ̇⁠liḃֽ⁠wò׃"],[9,24,"וְ⁠הֵ֣ם מְבִיאִ֣ים אִ֣ישׁ מִנְחָת֡⁠וֹ כְּלֵ֣י כֶסֶף֩ וּ⁠כְלֵ֨י זָהָ֤ב וּ⁠שְׂלָמוֹת֙ נֵ֣שֶׁק וּ⁠בְשָׂמִ֔ים סוּסִ֖ים וּ⁠פְרָדִ֑ים דְּבַר־שָׁנָ֖ה בְּ⁠שָׁנָֽה׃פ","wĕ⁠hé֣m mĕbiyʼi֣ym ʼi֣yş̌ minĕẖáţ֡⁠wò kĕ̇lé֣y kesep֩ ẇ⁠kĕlé֨y záhá֤b ẇ⁠şĕ̂lámwòţ֙ né֣şěq ẇ⁠bĕşá̂mi֔ym sẇsi֖ym ẇ⁠pĕrádi֑ym dĕ̇bar-şá̌ná֖h bĕ̇⁠şá̌náֽh׃p"],[9,25,"וַ⁠יְהִ֨י לִ⁠שְׁלֹמֹ֜ה אַרְבַּעַת֩ אֲלָפִ֨ים אֻֽרְי֤וֹת סוּסִים֙ וּ⁠מַרְכָּב֔וֹת וּ⁠שְׁנֵים־עָשָׂ֥ר אֶ֖לֶף פָּרָשִׁ֑ים וַ⁠יַּנִּיחֵ⁠ם֙ בְּ⁠עָרֵ֣י הָ⁠רֶ֔כֶב וְ⁠עִם־הַ⁠מֶּ֖לֶךְ בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yĕhi֨y li⁠şĕ̌lòmò֜h ʼarĕbȧʻaţ֩ ʼàlápi֨ym ʼuֽrĕy֤wòţ sẇsiym֙ ẇ⁠marĕká̇b֔wòţ ẇ⁠şĕ̌néym-ʻáşá֥̂r ʼe֖lep pá̇ráşǐ֑ym wa⁠yȧni̇yẖé⁠m֙ bĕ̇⁠ʻáré֣y há⁠re֔keb wĕ⁠ʻim-ha⁠mė֖lekĕ bi̇⁠yrẇşá̌liáֽm׃"],[9,26,"וַ⁠יְהִ֥י מוֹשֵׁ֖ל בְּ⁠כָל־הַ⁠מְּלָכִ֑ים מִן־הַ⁠נָּהָר֙ וְ⁠עַד־אֶ֣רֶץ פְּלִשְׁתִּ֔ים וְ⁠עַ֖ד גְּב֥וּל מִצְרָֽיִם׃","wa⁠yĕhi֥y mwòşé֖̌l bĕ̇⁠kál-ha⁠mĕ̇láki֑ym min-ha⁠ná̇hár֙ wĕ⁠ʻad-ʼe֣reẕ pĕ̇lişĕ̌ţi̇֔ym wĕ⁠ʻa֖d gĕ̇b֥ẇl miẕĕráֽyim׃"],[9,27,"וַ⁠יִּתֵּ֨ן הַ⁠מֶּ֧לֶךְ אֶת־הַ⁠כֶּ֛סֶף בִּ⁠ירוּשָׁלִַ֖ם כָּ⁠אֲבָנִ֑ים וְ⁠אֵ֣ת הָ⁠אֲרָזִ֗ים נָתַ֛ן כַּ⁠שִּׁקְמִ֥ים אֲשֶׁר־בַּ⁠שְּׁפֵלָ֖ה לָ⁠רֹֽב׃","wa⁠yi̇ţé̇֨n ha⁠mė֧lekĕ ʼeţ-ha⁠kė֛sep bi̇⁠yrẇşá̌lia֖m ká̇⁠ʼàbáni֑ym wĕ⁠ʼé֣ţ há⁠ʼàrázi֗ym náţa֛n kȧ⁠şi̇̌qĕmi֥ym ʼàşěr-bȧ⁠şĕ̇̌pélá֖h lá⁠ròֽb׃"],[9,28,"וּ⁠מוֹצִיאִ֨ים סוּסִ֧ים מִ⁠מִּצְרַ֛יִם לִ⁠שְׁלֹמֹ֖ה וּ⁠מִ⁠כָּל־הָ⁠אֲרָצֽוֹת׃","ẇ⁠mwòẕiyʼi֨ym sẇsi֧ym mi⁠mi̇ẕĕra֛yim li⁠şĕ̌lòmò֖h ẇ⁠mi⁠ká̇l-há⁠ʼàráẕֽwòţ׃"],[9,29,"וּ⁠שְׁאָר֙ דִּבְרֵ֣י שְׁלֹמֹ֔ה הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אֲחֲרוֹנִ֑ים הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־דִּבְרֵי֙ נָתָ֣ן הַ⁠נָּבִ֔יא וְ⁠עַל־נְבוּאַ֞ת אֲחִיָּ֣ה הַ⁠שִּֽׁילוֹנִ֗י וּ⁠בַ⁠חֲזוֹת֙ יעדי הַ⁠חֹזֶ֔ה עַל־יָרָבְעָ֖ם בֶּן־נְבָֽט׃","ẇ⁠şĕ̌ʼár֙ di̇bĕré֣y şĕ̌lòmò֔h há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼàẖàrwòni֑ym hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-di̇bĕréy֙ náţá֣n ha⁠ná̇bi֔yʼ wĕ⁠ʻal-nĕbẇʼa֞ţ ʼàẖiyá֣̇h ha⁠şiֽ̇̌ylwòni֗y ẇ⁠ba⁠ẖàzwòţ֙ yʻdy ha⁠ẖòze֔h ʻal-yárábĕʻá֖m bėn-nĕbáֽt׃"],[9,30,"וַ⁠יִּמְלֹ֨ךְ שְׁלֹמֹ֧ה בִֽ⁠ירוּשָׁלִַ֛ם עַל־כָּל־יִשְׂרָאֵ֖ל אַרְבָּעִ֥ים שָׁנָֽה׃","wa⁠yi̇mĕlò֨kĕ şĕ̌lòmò֧h biֽ⁠yrẇşá̌lia֛m ʻal-ká̇l-yişĕ̂ráʼé֖l ʼarĕbá̇ʻi֥ym şá̌náֽh׃"],[9,31,"וַ⁠יִּשְׁכַּ֤ב שְׁלֹמֹה֙ עִם־אֲבֹתָ֔י⁠ו וַֽ⁠יִּקְבְּרֻ֔⁠הוּ בְּ⁠עִ֖יר דָּוִ֣יד אָבִ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ רְחַבְעָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b şĕ̌lòmòh֙ ʻim-ʼàbòţá֔y⁠w waֽ⁠yi̇qĕbĕ̇ru֔⁠hẇ bĕ̇⁠ʻi֖yr dá̇wi֣yd ʼábi֑y⁠w wa⁠yi̇mĕlò֛kĕ rĕẖabĕʻá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[10,1,"וַ⁠יֵּ֥לֶךְ רְחַבְעָ֖ם שְׁכֶ֑מָ⁠ה כִּ֥י שְׁכֶ֛ם בָּ֥אוּ כָל־יִשְׂרָאֵ֖ל לְ⁠הַמְלִ֥יךְ אֹתֽ⁠וֹ׃","wa⁠yé֥̇lekĕ rĕẖabĕʻá֖m şĕ̌ke֑má⁠h ki֥̇y şĕ̌ke֛m bá֥̇ʼẇ kál-yişĕ̂ráʼé֖l lĕ⁠hamĕli֥ykĕ ʼòţֽ⁠wò׃"],[10,2,"וַ⁠יְהִ֞י כִּ⁠שְׁמֹ֨עַ יָרָבְעָ֤ם בֶּן־נְבָט֙ וְ⁠ה֣וּא בְ⁠מִצְרַ֔יִם אֲשֶׁ֣ר בָּרַ֔ח מִ⁠פְּנֵ֖י שְׁלֹמֹ֣ה הַ⁠מֶּ֑לֶךְ וַ⁠יָּ֥שָׁב יָרָבְעָ֖ם מִ⁠מִּצְרָֽיִם׃","wa⁠yĕhi֞y ki̇⁠şĕ̌mò֨ʻa yárábĕʻá֤m bėn-nĕbát֙ wĕ⁠h֣ẇʼ bĕ⁠miẕĕra֔yim ʼàşě֣r bá̇ra֔ẖ mi⁠pĕ̇né֖y şĕ̌lòmò֣h ha⁠mė֑lekĕ wa⁠yá֥̇şá̌b yárábĕʻá֖m mi⁠mi̇ẕĕráֽyim׃"],[10,3,"וַֽ⁠יִּשְׁלְחוּ֙ וַ⁠יִּקְרְאוּ־ל֔⁠וֹ וַ⁠יָּבֹ֥א יָרָבְעָ֖ם וְ⁠כָל־יִשְׂרָאֵ֑ל וַֽ⁠יְדַבְּר֔וּ אֶל־רְחַבְעָ֖ם לֵ⁠אמֹֽר׃","waֽ⁠yi̇şĕ̌lĕẖẇ֙ wa⁠yi̇qĕrĕʼẇ-l֔⁠wò wa⁠yá̇bò֥ʼ yárábĕʻá֖m wĕ⁠kál-yişĕ̂ráʼé֑l waֽ⁠yĕdabĕ̇r֔ẇ ʼel-rĕẖabĕʻá֖m lé⁠ʼmòֽr׃"],[10,4,"אָבִ֖י⁠ךָ הִקְשָׁ֣ה אֶת־עֻלֵּ֑⁠נוּ וְ⁠עַתָּ֡ה הָקֵל֩ מֵ⁠עֲבֹדַ֨ת אָבִ֜י⁠ךָ הַ⁠קָּשָׁ֗ה וּ⁠מֵ⁠עֻלּ֧⁠וֹ הַ⁠כָּבֵ֛ד אֲשֶׁר־נָתַ֥ן עָלֵ֖י⁠נוּ וְ⁠נַֽעַבְדֶֽ⁠ךָּ׃","ʼábi֖y⁠ká hiqĕşá֣̌h ʼeţ-ʻulé֑̇⁠nẇ wĕ⁠ʻaţá̇֡h háqél֩ mé⁠ʻàbòda֨ţ ʼábi֜y⁠ká ha⁠qá̇şá̌֗h ẇ⁠mé⁠ʻul֧̇⁠wò ha⁠ká̇bé֛d ʼàşěr-náţa֥n ʻálé֖y⁠nẇ wĕ⁠naֽʻabĕdeֽ⁠ká̇׃"],[10,5,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם ע֛וֹד שְׁלֹ֥שֶׁת יָמִ֖ים וְ⁠שׁ֣וּבוּ אֵלָ֑⁠י וַ⁠יֵּ֖לֶךְ הָ⁠עָֽם׃ס","wa⁠yò֣̇ʼmer ʼàlé⁠he֗m ʻ֛wòd şĕ̌lò֥şěţ yámi֖ym wĕ⁠ş֣̌ẇbẇ ʼélá֑⁠y wa⁠yé֖̇lekĕ há⁠ʻáֽm׃s"],[10,6,"וַ⁠יִּוָּעַ֞ץ הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם אֶת־הַ⁠זְּקֵנִים֙ אֲשֶׁר־הָי֣וּ עֹֽמְדִ֗ים לִ⁠פְנֵי֙ שְׁלֹמֹ֣ה אָבִ֔י⁠ו בִּֽ⁠הְיֹת֥⁠וֹ חַ֖י לֵ⁠אמֹ֑ר אֵ֚יךְ אַתֶּ֣ם נֽוֹעָצִ֔ים לְ⁠הָשִׁ֥יב לָֽ⁠עָם־הַ⁠זֶּ֖ה דָּבָֽר׃","wa⁠yi̇wá̇ʻa֞ẕ ha⁠mė֣lekĕ rĕẖabĕʻá֗m ʼeţ-ha⁠zĕ̇qéniym֙ ʼàşěr-háy֣ẇ ʻòֽmĕdi֗ym li⁠pĕnéy֙ şĕ̌lòmò֣h ʼábi֔y⁠w biֽ̇⁠hĕyòţ֥⁠wò ẖa֖y lé⁠ʼmò֑r ʼé֚ykĕ ʼaţė֣m nֽwòʻáẕi֔ym lĕ⁠háşǐ֥yb láֽ⁠ʻám-ha⁠zė֖h dá̇báֽr׃"],[10,7,"וַ⁠יְדַבְּר֨וּ אֵלָ֜י⁠ו לֵ⁠אמֹ֗ר אִם־תִּֽהְיֶ֨ה לְ⁠ט֜וֹב לְ⁠הָ⁠עָ֤ם הַ⁠זֶּה֙ וּ⁠רְצִיתָ֔⁠ם וְ⁠דִבַּרְתָּ֥ אֲלֵ⁠הֶ֖ם דְּבָרִ֣ים טוֹבִ֑ים וְ⁠הָי֥וּ לְ⁠ךָ֛ עֲבָדִ֖ים כָּל־הַ⁠יָּמִֽים׃","wa⁠yĕdabĕ̇r֨ẇ ʼélá֜y⁠w lé⁠ʼmò֗r ʼim-ţiֽ̇hĕye֨h lĕ⁠t֜wòb lĕ⁠há⁠ʻá֤m ha⁠zėh֙ ẇ⁠rĕẕiyţá֔⁠m wĕ⁠dibȧrĕţá֥̇ ʼàlé⁠he֖m dĕ̇bári֣ym twòbi֑ym wĕ⁠háy֥ẇ lĕ⁠ká֛ ʻàbádi֖ym ká̇l-ha⁠yá̇miֽym׃"],[10,8,"וַֽ⁠יַּעֲזֹ֛ב אֶת־עֲצַ֥ת הַ⁠זְּקֵנִ֖ים אֲשֶׁ֣ר יְעָצֻ֑⁠הוּ וַ⁠יִּוָּעַ֗ץ אֶת־הַ⁠יְלָדִים֙ אֲשֶׁ֣ר גָּדְל֣וּ אִתּ֔⁠וֹ הָ⁠עֹמְדִ֖ים לְ⁠פָנָֽי⁠ו׃","waֽ⁠yȧʻàzò֛b ʼeţ-ʻàẕa֥ţ ha⁠zĕ̇qéni֖ym ʼàşě֣r yĕʻáẕu֑⁠hẇ wa⁠yi̇wá̇ʻa֗ẕ ʼeţ-ha⁠yĕládiym֙ ʼàşě֣r gá̇dĕl֣ẇ ʼiţ̇֔⁠wò há⁠ʻòmĕdi֖ym lĕ⁠pánáֽy⁠w׃"],[10,9,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם מָ֚ה אַתֶּ֣ם נֽוֹעָצִ֔ים וְ⁠נָשִׁ֥יב דָּבָ֖ר אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֑ה אֲשֶׁ֨ר דִּבְּר֤וּ אֵלַ⁠י֙ לֵ⁠אמֹ֔ר הָקֵל֙ מִן־הָ⁠עֹ֔ל אֲשֶׁר־נָתַ֥ן אָבִ֖י⁠ךָ עָלֵֽי⁠נוּ׃","wa⁠yò֣̇ʼmer ʼàlé⁠he֗m má֚h ʼaţė֣m nֽwòʻáẕi֔ym wĕ⁠náşǐ֥yb dá̇bá֖r ʼeţ-há⁠ʻá֣m ha⁠zė֑h ʼàşě֨r di̇bĕ̇r֤ẇ ʼéla⁠y֙ lé⁠ʼmò֔r háqél֙ min-há⁠ʻò֔l ʼàşěr-náţa֥n ʼábi֖y⁠ká ʻáléֽy⁠nẇ׃"],[10,10,"וַ⁠יְדַבְּר֣וּ אִתּ֗⁠וֹ הַ⁠יְלָדִים֙ אֲשֶׁ֨ר גָּדְל֣וּ אִתּ⁠וֹ֮ לֵ⁠אמֹר֒ כֹּֽה־תֹאמַ֡ר לָ⁠עָם֩ אֲשֶׁר־דִּבְּר֨וּ אֵלֶ֜י⁠ךָ לֵ⁠אמֹ֗ר אָבִ֨י⁠ךָ֙ הִכְבִּ֣יד אֶת־עֻלֵּ֔⁠נוּ וְ⁠אַתָּ֖ה הָקֵ֣ל מֵ⁠עָלֵ֑י⁠נוּ כֹּ֚ה תֹּאמַ֣ר אֲלֵ⁠הֶ֔ם קָֽטָנִּ֥⁠י עָבָ֖ה מִ⁠מָּתְנֵ֥י אָבִֽ⁠י׃","wa⁠yĕdabĕ̇r֣ẇ ʼiţ̇֗⁠wò ha⁠yĕládiym֙ ʼàşě֨r gá̇dĕl֣ẇ ʼiţ̇⁠wò֮ lé⁠ʼmòr֒ kòֽ̇h-ţòʼma֡r lá⁠ʻám֩ ʼàşěr-di̇bĕ̇r֨ẇ ʼéle֜y⁠ká lé⁠ʼmò֗r ʼábi֨y⁠ká֙ hikĕbi֣̇yd ʼeţ-ʻulé̇֔⁠nẇ wĕ⁠ʼaţá֖̇h háqé֣l mé⁠ʻálé֑y⁠nẇ kò֚̇h ţò̇ʼma֣r ʼàlé⁠he֔m qáֽtáni֥̇⁠y ʻábá֖h mi⁠má̇ţĕné֥y ʼábiֽ⁠y׃"],[10,11,"וְ⁠עַתָּ֗ה אָבִ⁠י֙ הֶעְמִ֤יס עֲלֵי⁠כֶם֙ עֹ֣ל כָּבֵ֔ד וַ⁠אֲנִ֖י אֹסִ֣יף עַֽל־עֻלְּ⁠כֶ֑ם אָבִ֗⁠י יִסַּ֤ר אֶתְ⁠כֶם֙ בַּ⁠שּׁוֹטִ֔ים וַ⁠אֲנִ֖י בָּֽ⁠עֲקְרַבִּֽים׃ס","wĕ⁠ʻaţá̇֗h ʼábi⁠y֙ heʻĕmi֤ys ʻàléy⁠kem֙ ʻò֣l ká̇bé֔d wa⁠ʼàni֖y ʼòsi֣yp ʻaֽl-ʻulĕ̇⁠ke֑m ʼábi֗⁠y yisȧ֤r ʼeţĕ⁠kem֙ bȧ⁠ş̇̌wòti֔ym wa⁠ʼàni֖y báֽ̇⁠ʻàqĕrabiֽ̇ym׃s"],[10,12,"וַ⁠יָּבֹ֨א יָרָבְעָ֧ם וְ⁠כָל־הָ⁠עָ֛ם אֶל־רְחַבְעָ֖ם בַּ⁠יּ֣וֹם הַ⁠שְּׁלִשִׁ֑י כַּ⁠אֲשֶׁ֨ר דִּבֶּ֤ר הַ⁠מֶּ֨לֶךְ֙ לֵ⁠אמֹ֔ר שׁ֥וּבוּ אֵלַ֖⁠י בַּ⁠יּ֥וֹם הַ⁠שְּׁלִשִֽׁי׃","wa⁠yá̇bò֨ʼ yárábĕʻá֧m wĕ⁠kál-há⁠ʻá֛m ʼel-rĕẖabĕʻá֖m bȧ⁠ẏ֣wòm ha⁠şĕ̇̌lişǐ֑y kȧ⁠ʼàşě֨r di̇bė֤r ha⁠mė֨lekĕ֙ lé⁠ʼmò֔r ş֥̌ẇbẇ ʼéla֖⁠y bȧ⁠ẏ֥wòm ha⁠şĕ̇̌lişǐֽy׃"],[10,13,"וַ⁠יַּעֲנֵ֥⁠ם הַ⁠מֶּ֖לֶךְ קָשָׁ֑ה וַֽ⁠יַּעֲזֹב֙ הַ⁠מֶּ֣לֶךְ רְחַבְעָ֔ם אֵ֖ת עֲצַ֥ת הַ⁠זְּקֵנִֽים׃","wa⁠yȧʻàné֥⁠m ha⁠mė֖lekĕ qáşá֑̌h waֽ⁠yȧʻàzòb֙ ha⁠mė֣lekĕ rĕẖabĕʻá֔m ʼé֖ţ ʻàẕa֥ţ ha⁠zĕ̇qéniֽym׃"],[10,14,"וַ⁠יְדַבֵּ֣ר אֲלֵ⁠הֶ֗ם כַּ⁠עֲצַ֤ת הַ⁠יְלָדִים֙ לֵ⁠אמֹ֔ר אַכְבִּיד֙ אֶֽת־עֻלְּ⁠כֶ֔ם וַ⁠אֲנִ֖י אֹסִ֣יף עָלָ֑י⁠ו אָבִ֗⁠י יִסַּ֤ר אֶתְ⁠כֶם֙ בַּ⁠שּׁוֹטִ֔ים וַ⁠אֲנִ֖י בָּ⁠עֲקְרַבִּֽים׃","wa⁠yĕdabé֣̇r ʼàlé⁠he֗m kȧ⁠ʻàẕa֤ţ ha⁠yĕládiym֙ lé⁠ʼmò֔r ʼakĕbi̇yd֙ ʼeֽţ-ʻulĕ̇⁠ke֔m wa⁠ʼàni֖y ʼòsi֣yp ʻálá֑y⁠w ʼábi֗⁠y yisȧ֤r ʼeţĕ⁠kem֙ bȧ⁠ş̇̌wòti֔ym wa⁠ʼàni֖y bá̇⁠ʻàqĕrabiֽ̇ym׃"],[10,15,"וְ⁠לֹֽא־שָׁמַ֥ע הַ⁠מֶּ֖לֶךְ אֶל־הָ⁠עָ֑ם כִּֽי־הָיְתָ֤ה נְסִבָּה֙ מֵ⁠עִ֣ם הָֽ⁠אֱלֹהִ֔ים לְמַעַן֩ הָקִ֨ים יְהוָ֜ה אֶת־דְּבָר֗⁠וֹ אֲשֶׁ֤ר דִּבֶּר֙ בְּ⁠יַד֙ אֲחִיָּ֣הוּ הַ⁠שִּֽׁלוֹנִ֔י אֶל־יָרָבְעָ֖ם בֶּן־נְבָֽט׃","wĕ⁠lòֽʼ-şá̌ma֥ʻ ha⁠mė֖lekĕ ʼel-há⁠ʻá֑m kiֽ̇y-háyĕţá֤h nĕsibá̇h֙ mé⁠ʻi֣m hֽá⁠ʼèlòhi֔ym lĕmaʻan֩ háqi֨ym yĕhwá֜h ʼeţ-dĕ̇bár֗⁠wò ʼàşě֤r di̇bėr֙ bĕ̇⁠yad֙ ʼàẖiyá֣̇hẇ ha⁠şiֽ̇̌lwòni֔y ʼel-yárábĕʻá֖m bėn-nĕbáֽt׃"],[10,16,"וְ⁠כָל־יִשְׂרָאֵ֗ל כִּ֠י לֹא־שָׁמַ֣ע הַ⁠מֶּלֶךְ֮ לָ⁠הֶם֒ וַ⁠יָּשִׁ֣יבוּ הָ⁠עָ֣ם אֶת־הַ⁠מֶּ֣לֶךְ ׀ לֵ⁠אמֹ֡ר מַה־לָּ⁠נוּ֩ חֵ֨לֶק בְּ⁠דָוִ֜יד וְ⁠לֹֽא־נַחֲלָ֣ה בְּ⁠בֶן־יִשַׁ֗י אִ֤ישׁ לְ⁠אֹהָלֶ֨י⁠ךָ֙ יִשְׂרָאֵ֔ל עַתָּ֕ה רְאֵ֥ה בֵיתְ⁠ךָ֖ דָּוִ֑יד וַ⁠יֵּ֥לֶךְ כָּל־יִשְׂרָאֵ֖ל לְ⁠אֹהָלָֽי⁠ו׃ס","wĕ⁠kál-yişĕ̂ráʼé֗l ki̇֠y lòʼ-şá̌ma֣ʻ ha⁠mėlekĕ֮ lá⁠hem֒ wa⁠yá̇şǐ֣ybẇ há⁠ʻá֣m ʼeţ-ha⁠mė֣lekĕ ׀ lé⁠ʼmò֡r mah-lá̇⁠nẇ֩ ẖé֨leq bĕ̇⁠dáwi֜yd wĕ⁠lòֽʼ-naẖàlá֣h bĕ̇⁠ben-yişǎ֗y ʼi֤yş̌ lĕ⁠ʼòhále֨y⁠ká֙ yişĕ̂ráʼé֔l ʻaţá̇֕h rĕʼé֥h béyţĕ⁠ká֖ dá̇wi֑yd wa⁠yé֥̇lekĕ ká̇l-yişĕ̂ráʼé֖l lĕ⁠ʼòháláֽy⁠w׃s"],[10,17,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל הַ⁠יֹּֽשְׁבִ֖ים בְּ⁠עָרֵ֣י יְהוּדָ֑ה וַ⁠יִּמְלֹ֥ךְ עֲלֵי⁠הֶ֖ם רְחַבְעָֽם׃","ẇ⁠bĕné֣y yişĕ̂ráʼé֔l ha⁠yòֽ̇şĕ̌bi֖ym bĕ̇⁠ʻáré֣y yĕhẇdá֑h wa⁠yi̇mĕlò֥kĕ ʻàléy⁠he֖m rĕẖabĕʻáֽm׃"],[10,18,"וַ⁠יִּשְׁלַ֞ח הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם אֶת־הֲדֹרָם֙ אֲשֶׁ֣ר עַל־הַ⁠מַּ֔ס וַ⁠יִּרְגְּמוּ־ב֧⁠וֹ בְנֵֽי־יִשְׂרָאֵ֛ל אֶ֖בֶן וַ⁠יָּמֹ֑ת וְ⁠הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם הִתְאַמֵּץ֙ לַֽ⁠עֲל֣וֹת בַּ⁠מֶּרְכָּבָ֔ה לָ⁠נ֖וּס יְרוּשָׁלִָֽם׃ס","wa⁠yi̇şĕ̌la֞ẖ ha⁠mė֣lekĕ rĕẖabĕʻá֗m ʼeţ-hàdòrám֙ ʼàşě֣r ʻal-ha⁠mȧ֔s wa⁠yi̇rĕgĕ̇mẇ-b֧⁠wò bĕnéֽy-yişĕ̂ráʼé֛l ʼe֖ben wa⁠yá̇mò֑ţ wĕ⁠ha⁠mė֣lekĕ rĕẖabĕʻá֗m hiţĕʼamé̇ẕ֙ laֽ⁠ʻàl֣wòţ bȧ⁠mėrĕká̇bá֔h lá⁠n֖ẇs yĕrẇşá̌liáֽm׃s"],[10,19,"וַ⁠יִּפְשְׁע֤וּ יִשְׂרָאֵל֙ בְּ⁠בֵ֣ית דָּוִ֔יד עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wa⁠yi̇pĕşĕ̌ʻ֤ẇ yişĕ̂ráʼél֙ bĕ̇⁠bé֣yţ dá̇wi֔yd ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃s"],[11,1,"וַ⁠יָּבֹ֣א רְחַבְעָם֮ יְרוּשָׁלִַם֒ וַ⁠יַּקְהֵל֩ אֶת־בֵּ֨ית יְהוּדָ֜ה וּ⁠בִנְיָמִ֗ן מֵאָ֨ה וּ⁠שְׁמוֹנִ֥ים אֶ֛לֶף בָּח֖וּר עֹשֵׂ֣ה מִלְחָמָ֑ה לְ⁠הִלָּחֵם֙ עִם־יִשְׂרָאֵ֔ל לְ⁠הָשִׁ֥יב אֶת־הַ⁠מַּמְלָכָ֖ה לִ⁠רְחַבְעָֽם׃פ","wa⁠yá̇bò֣ʼ rĕẖabĕʻám֮ yĕrẇşá̌liam֒ wa⁠yȧqĕhél֩ ʼeţ-bé̇֨yţ yĕhẇdá֜h ẇ⁠binĕyámi֗n méʼá֨h ẇ⁠şĕ̌mwòni֥ym ʼe֛lep bá̇ẖ֖ẇr ʻòşé֣̂h milĕẖámá֑h lĕ⁠hilá̇ẖém֙ ʻim-yişĕ̂ráʼé֔l lĕ⁠háşǐ֥yb ʼeţ-ha⁠mȧmĕláká֖h li⁠rĕẖabĕʻáֽm׃p"],[11,2,"וַ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־שְׁמַֽעְיָ֥הוּ אִישׁ־הָ⁠אֱלֹהִ֖ים לֵ⁠אמֹֽר׃","wa⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-şĕ̌maֽʻĕyá֥hẇ ʼiyş̌-há⁠ʼèlòhi֖ym lé⁠ʼmòֽr׃"],[11,3,"אֱמֹ֕ר אֶל־רְחַבְעָ֥ם בֶּן־שְׁלֹמֹ֖ה מֶ֣לֶךְ יְהוּדָ֑ה וְ⁠אֶל֙ כָּל־יִשְׂרָאֵ֔ל בִּ⁠יהוּדָ֥ה וּ⁠בִנְיָמִ֖ן לֵ⁠אמֹֽר׃","ʼèmò֕r ʼel-rĕẖabĕʻá֥m bėn-şĕ̌lòmò֖h me֣lekĕ yĕhẇdá֑h wĕ⁠ʼel֙ ká̇l-yişĕ̂ráʼé֔l bi̇⁠yhẇdá֥h ẇ⁠binĕyámi֖n lé⁠ʼmòֽr׃"],[11,4,"כֹּ֣ה אָמַ֣ר יְהוָ֡ה לֹא־תַעֲלוּ֩ וְ⁠לֹא־תִלָּ֨חֲמ֜וּ עִם־אֲחֵי⁠כֶ֗ם שׁ֚וּבוּ אִ֣ישׁ לְ⁠בֵית֔⁠וֹ כִּ֧י מֵֽ⁠אִתִּ֛⁠י נִהְיָ֖ה הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַֽ⁠יִּשְׁמְעוּ֙ אֶת־דִּבְרֵ֣י יְהוָ֔ה וַ⁠יָּשֻׁ֖בוּ מִ⁠לֶּ֥כֶת אֶל־יָרָבְעָֽם׃פ","kò֣̇h ʼáma֣r yĕhwá֡h lòʼ-ţaʻàlẇ֩ wĕ⁠lòʼ-ţilá̇֨ẖàm֜ẇ ʻim-ʼàẖéy⁠ke֗m ş֚̌ẇbẇ ʼi֣yş̌ lĕ⁠béyţ֔⁠wò ki֧̇y méֽ⁠ʼiţi֛̇⁠y nihĕyá֖h ha⁠dá̇bá֣r ha⁠zė֑h waֽ⁠yi̇şĕ̌mĕʻẇ֙ ʼeţ-di̇bĕré֣y yĕhwá֔h wa⁠yá̇şǔ֖bẇ mi⁠lė֥keţ ʼel-yárábĕʻáֽm׃p"],[11,5,"וַ⁠יֵּ֥שֶׁב רְחַבְעָ֖ם בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יִּ֧בֶן עָרִ֛ים לְ⁠מָצ֖וֹר בִּ⁠יהוּדָֽה׃","wa⁠yé֥̇şěb rĕẖabĕʻá֖m bi̇⁠yrẇşá̌liá֑m wa⁠yi֧̇ben ʻári֛ym lĕ⁠máẕ֖wòr bi̇⁠yhẇdáֽh׃"],[11,6,"וַ⁠יִּ֧בֶן אֶת־בֵּֽית־לֶ֛חֶם וְ⁠אֶת־עֵיטָ֖ם וְ⁠אֶת־תְּקֽוֹעַ׃","wa⁠yi֧̇ben ʼeţ-béֽ̇yţ-le֛ẖem wĕ⁠ʼeţ-ʻéytá֖m wĕ⁠ʼeţ-ţĕ̇qֽwòʻa׃"],[11,7,"וְ⁠אֶת־בֵּֽית־צ֥וּר וְ⁠אֶת־שׂוֹכ֖וֹ וְ⁠אֶת־עֲדֻלָּֽם׃","wĕ⁠ʼeţ-béֽ̇yţ-ẕ֥ẇr wĕ⁠ʼeţ-ş̂wòk֖wò wĕ⁠ʼeţ-ʻàduláֽ̇m׃"],[11,8,"וְ⁠אֶת־גַּ֥ת וְ⁠אֶת־מָרֵשָׁ֖ה וְ⁠אֶת־זִֽיף׃","wĕ⁠ʼeţ-gȧ֥ţ wĕ⁠ʼeţ-máréşá֖̌h wĕ⁠ʼeţ-ziֽyp׃"],[11,9,"וְ⁠אֶת־אֲדוֹרַ֥יִם וְ⁠אֶת־לָכִ֖ישׁ וְ⁠אֶת־עֲזֵקָֽה׃","wĕ⁠ʼeţ-ʼàdwòra֥yim wĕ⁠ʼeţ-láki֖yş̌ wĕ⁠ʼeţ-ʻàzéqáֽh׃"],[11,10,"וְ⁠אֶת־צָרְעָה֙ וְ⁠אֶת־אַיָּל֔וֹן וְ⁠אֶת־חֶבְר֔וֹן אֲשֶׁ֥ר בִּ⁠יהוּדָ֖ה וּ⁠בְ⁠בִנְיָמִ֑ן עָרֵ֖י מְצֻרֽוֹת׃","wĕ⁠ʼeţ-ẕárĕʻáh֙ wĕ⁠ʼeţ-ʼayá̇l֔wòn wĕ⁠ʼeţ-ẖebĕr֔wòn ʼàşě֥r bi̇⁠yhẇdá֖h ẇ⁠bĕ⁠binĕyámi֑n ʻáré֖y mĕẕurֽwòţ׃"],[11,11,"וַ⁠יְחַזֵּ֖ק אֶת־הַ⁠מְּצֻר֑וֹת וַ⁠יִּתֵּ֤ן בָּ⁠הֶם֙ נְגִידִ֔ים וְ⁠אֹצְר֥וֹת מַאֲכָ֖ל וְ⁠שֶׁ֥מֶן וָ⁠יָֽיִן׃","wa⁠yĕẖazé֖̇q ʼeţ-ha⁠mĕ̇ẕur֑wòţ wa⁠yi̇ţé֤̇n bá̇⁠hem֙ nĕgiydi֔ym wĕ⁠ʼòẕĕr֥wòţ maʼàká֖l wĕ⁠şě֥men wá⁠yáֽyin׃"],[11,12,"וּ⁠בְ⁠כָל־עִ֤יר וָ⁠עִיר֙ צִנּ֣וֹת וּ⁠רְמָחִ֔ים וַֽ⁠יְחַזְּקֵ֖⁠ם לְ⁠הַרְבֵּ֣ה מְאֹ֑ד וַ⁠יְהִי־ל֖⁠וֹ יְהוּדָ֥ה וּ⁠בִנְיָמִֽן׃ס","ẇ⁠bĕ⁠kál-ʻi֤yr wá⁠ʻiyr֙ ẕiṅ֣wòţ ẇ⁠rĕmáẖi֔ym waֽ⁠yĕẖazĕ̇qé֖⁠m lĕ⁠harĕbé֣̇h mĕʼò֑d wa⁠yĕhiy-l֖⁠wò yĕhẇdá֥h ẇ⁠binĕyámiֽn׃s"],[11,13,"וְ⁠הַ⁠כֹּהֲנִים֙ וְ⁠הַ⁠לְוִיִּ֔ם אֲשֶׁ֖ר בְּ⁠כָל־יִשְׂרָאֵ֑ל הִֽתְיַצְּב֥וּ עָלָ֖י⁠ו מִ⁠כָּל־גְּבוּלָֽ⁠ם׃","wĕ⁠ha⁠kò̇hàniym֙ wĕ⁠ha⁠lĕwiyi̇֔m ʼàşě֖r bĕ̇⁠kál-yişĕ̂ráʼé֑l hiֽţĕyaẕĕ̇b֥ẇ ʻálá֖y⁠w mi⁠ká̇l-gĕ̇bẇláֽ⁠m׃"],[11,14,"כִּֽי־עָזְב֣וּ הַ⁠לְוִיִּ֗ם אֶת־מִגְרְשֵׁי⁠הֶם֙ וַ⁠אֲחֻזָּתָ֔⁠ם וַ⁠יֵּלְכ֥וּ לִ⁠יהוּדָ֖ה וְ⁠לִֽ⁠ירוּשָׁלִָ֑ם כִּֽי־הִזְנִיחָ֤⁠ם יָֽרָבְעָם֙ וּ⁠בָנָ֔י⁠ו מִ⁠כַּהֵ֖ן לַ⁠יהוָֽה׃","kiֽ̇y-ʻázĕb֣ẇ ha⁠lĕwiyi̇֗m ʼeţ-migĕrĕşé̌y⁠hem֙ wa⁠ʼàẖuzá̇ţá֔⁠m wa⁠yé̇lĕk֥ẇ li⁠yhẇdá֖h wĕ⁠liֽ⁠yrẇşá̌liá֑m kiֽ̇y-hizĕniyẖá֤⁠m yáֽrábĕʻám֙ ẇ⁠báná֔y⁠w mi⁠kȧhé֖n la⁠yhwáֽh׃"],[11,15,"וַ⁠יַּֽעֲמֶד־ל⁠וֹ֙ כֹּֽהֲנִ֔ים לַ⁠בָּמ֖וֹת וְ⁠לַ⁠שְּׂעִירִ֑ים וְ⁠לָ⁠עֲגָלִ֖ים אֲשֶׁ֥ר עָשָֽׂה׃","wa⁠yȧֽʻàmed-l⁠wò֙ kòֽ̇hàni֔ym la⁠bá̇m֖wòţ wĕ⁠la⁠şĕ̇̂ʻiyri֑ym wĕ⁠lá⁠ʻàgáli֖ym ʼàşě֥r ʻáşáֽ̂h׃"],[11,16,"וְ⁠אַחֲרֵי⁠הֶ֗ם מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל הַ⁠נֹּֽתְנִים֙ אֶת־לְבָבָ֔⁠ם לְ⁠בַקֵּ֕שׁ אֶת־יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל בָּ֚אוּ יְר֣וּשָׁלִַ֔ם לִ⁠זְבּ֕וֹחַ לַ⁠יהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃","wĕ⁠ʼaẖàréy⁠he֗m mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l ha⁠nòֽ̇ţĕniym֙ ʼeţ-lĕbábá֔⁠m lĕ⁠baqé̇֕ş̌ ʼeţ-yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l bá֚̇ʼẇ yĕr֣ẇşá̌lia֔m li⁠zĕḃ֕wòẖa la⁠yhwá֖h ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃"],[11,17,"וַֽ⁠יְחַזְּקוּ֙ אֶת־מַלְכ֣וּת יְהוּדָ֔ה וַֽ⁠יְאַמְּצ֛וּ אֶת־רְחַבְעָ֥ם בֶּן־שְׁלֹמֹ֖ה לְ⁠שָׁנִ֣ים שָׁל֑וֹשׁ כִּ֣י הָֽלְכ֗וּ בְּ⁠דֶ֧רֶךְ דָּוִ֛יד וּ⁠שְׁלֹמֹ֖ה לְ⁠שָׁנִ֥ים שָׁלֽוֹשׁ׃","waֽ⁠yĕẖazĕ̇qẇ֙ ʼeţ-malĕk֣ẇţ yĕhẇdá֔h waֽ⁠yĕʼamĕ̇ẕ֛ẇ ʼeţ-rĕẖabĕʻá֥m bėn-şĕ̌lòmò֖h lĕ⁠şá̌ni֣ym şá̌l֑wòş̌ ki֣̇y háֽlĕk֗ẇ bĕ̇⁠de֧rekĕ dá̇wi֛yd ẇ⁠şĕ̌lòmò֖h lĕ⁠şá̌ni֥ym şá̌lֽwòş̌׃"],[11,18,"וַ⁠יִּֽקַּֽח־ל֤⁠וֹ רְחַבְעָם֙ אִשָּׁ֔ה אֶת־מָ֣חֲלַ֔ת בן־יְרִימ֖וֹת בֶּן־דָּוִ֑יד אֲבִיהַ֕יִל בַּת־אֱלִיאָ֖ב בֶּן־יִשָֽׁי׃","wa⁠yiֽ̇qȧֽẖ-l֤⁠wò rĕẖabĕʻám֙ ʼişá̇̌֔h ʼeţ-má֣ẖàla֔ţ bn-yĕriym֖wòţ bėn-dá̇wi֑yd ʼàbiyha֕yil bȧţ-ʼèliyʼá֖b bėn-yişáֽ̌y׃"],[11,19,"וַ⁠תֵּ֥לֶד ל֖⁠וֹ בָּנִ֑ים אֶת־יְע֥וּשׁ וְ⁠אֶת־שְׁמַרְיָ֖ה וְ⁠אֶת־זָֽהַם׃","wa⁠ţé֥̇led l֖⁠wò bá̇ni֑ym ʼeţ-yĕʻ֥ẇş̌ wĕ⁠ʼeţ-şĕ̌marĕyá֖h wĕ⁠ʼeţ-záֽham׃"],[11,20,"וְ⁠אַחֲרֶ֣י⁠הָ לָקַ֔ח אֶֽת־מַעֲכָ֖ה בַּת־אַבְשָׁל֑וֹם וַ⁠תֵּ֣לֶד ל֗⁠וֹ אֶת־אֲבִיָּה֙ וְ⁠אֶת־עַתַּ֔י וְ⁠אֶת־זִיזָ֖א וְ⁠אֶת־שְׁלֹמִֽית׃","wĕ⁠ʼaẖàre֣y⁠há láqa֔ẖ ʼeֽţ-maʻàká֖h bȧţ-ʼabĕşá̌l֑wòm wa⁠ţé֣̇led l֗⁠wò ʼeţ-ʼàbiyá̇h֙ wĕ⁠ʼeţ-ʻaţȧ֔y wĕ⁠ʼeţ-ziyzá֖ʼ wĕ⁠ʼeţ-şĕ̌lòmiֽyţ׃"],[11,21,"וַ⁠יֶּאֱהַ֨ב רְחַבְעָ֜ם אֶת־מַעֲכָ֣ה בַת־אַבְשָׁל֗וֹם מִ⁠כָּל־נָשָׁי⁠ו֙ וּ⁠פִ֣ילַגְשָׁ֔י⁠ו כִּ֠י נָשִׁ֤ים שְׁמוֹנֶֽה־עֶשְׂרֵה֙ נָשָׂ֔א וּ⁠פִֽילַגְשִׁ֖ים שִׁשִּׁ֑ים וַ⁠יּ֗וֹלֶד עֶשְׂרִ֧ים וּ⁠שְׁמוֹנָ֛ה בָּנִ֖ים וְ⁠שִׁשִּׁ֥ים בָּנֽוֹת׃","wa⁠yėʼèha֨b rĕẖabĕʻá֜m ʼeţ-maʻàká֣h baţ-ʼabĕşá̌l֗wòm mi⁠ká̇l-náşá̌y⁠w֙ ẇ⁠pi֣ylagĕşá̌֔y⁠w ki̇֠y náşǐ֤ym şĕ̌mwòneֽh-ʻeşĕ̂réh֙ náşá̂֔ʼ ẇ⁠piֽylagĕşǐ֖ym şǐşi֑̇̌ym wa⁠ẏ֗wòled ʻeşĕ̂ri֧ym ẇ⁠şĕ̌mwòná֛h bá̇ni֖ym wĕ⁠şǐşi֥̇̌ym bá̇nֽwòţ׃"],[11,22,"וַ⁠יַּֽעֲמֵ֨ד לָ⁠רֹ֧אשׁ רְחַבְעָ֛ם אֶת־אֲבִיָּ֥ה בֶֽן־מַעֲכָ֖ה לְ⁠נָגִ֣יד בְּ⁠אֶחָ֑י⁠ו כִּ֖י לְ⁠הַמְלִיכֽ⁠וֹ׃","wa⁠yȧֽʻàmé֨d lá⁠rò֧ʼş̌ rĕẖabĕʻá֛m ʼeţ-ʼàbiyá֥̇h beֽn-maʻàká֖h lĕ⁠nági֣yd bĕ̇⁠ʼeẖá֑y⁠w ki֖̇y lĕ⁠hamĕliykֽ⁠wò׃"],[11,23,"וַ⁠יָּבֶן֩ וַ⁠יִּפְרֹ֨ץ מִ⁠כָּל־בָּנָ֜י⁠ו לְֽ⁠כָל־אַרְצ֧וֹת יְהוּדָ֣ה וּ⁠בִנְיָמִ֗ן לְ⁠כֹל֙ עָרֵ֣י הַ⁠מְּצֻר֔וֹת וַ⁠יִּתֵּ֥ן לָ⁠הֶ֛ם הַ⁠מָּז֖וֹן לָ⁠רֹ֑ב וַ⁠יִּשְׁאַ֖ל הֲמ֥וֹן נָשִֽׁים׃","wa⁠yá̇ben֩ wa⁠yi̇pĕrò֨ẕ mi⁠ká̇l-bá̇ná֜y⁠w lĕֽ⁠kál-ʼarĕẕ֧wòţ yĕhẇdá֣h ẇ⁠binĕyámi֗n lĕ⁠kòl֙ ʻáré֣y ha⁠mĕ̇ẕur֔wòţ wa⁠yi̇ţé֥̇n lá⁠he֛m ha⁠má̇z֖wòn lá⁠rò֑b wa⁠yi̇şĕ̌ʼa֖l hàm֥wòn náşǐֽym׃"],[12,1,"וַ⁠יְהִ֗י כְּ⁠הָכִ֞ין מַלְכ֤וּת רְחַבְעָם֙ וּ⁠כְ⁠חֶזְקָת֔⁠וֹ עָזַ֖ב אֶת־תּוֹרַ֣ת יְהוָ֑ה וְ⁠כָל־יִשְׂרָאֵ֖ל עִמּֽ⁠וֹ׃פ","wa⁠yĕhi֗y kĕ̇⁠háki֞yn malĕk֤ẇţ rĕẖabĕʻám֙ ẇ⁠kĕ⁠ẖezĕqáţ֔⁠wò ʻáza֖b ʼeţ-ţ̇wòra֣ţ yĕhwá֑h wĕ⁠kál-yişĕ̂ráʼé֖l ʻiṁֽ⁠wò׃p"],[12,2,"וַ⁠יְהִ֞י בַּ⁠שָּׁנָ֤ה הַֽ⁠חֲמִישִׁית֙ לַ⁠מֶּ֣לֶךְ רְחַבְעָ֔ם עָלָ֛ה שִׁישַׁ֥ק מֶֽלֶךְ־מִצְרַ֖יִם עַל־יְרוּשָׁלִָ֑ם כִּ֥י מָעֲל֖וּ בַּ⁠יהוָֽה׃","wa⁠yĕhi֞y bȧ⁠şá̇̌ná֤h haֽ⁠ẖàmiyşǐyţ֙ la⁠mė֣lekĕ rĕẖabĕʻá֔m ʻálá֛h şǐyşǎ֥q meֽlekĕ-miẕĕra֖yim ʻal-yĕrẇşá̌liá֑m ki֥̇y máʻàl֖ẇ bȧ⁠yhwáֽh׃"],[12,3,"בְּ⁠אֶ֤לֶף וּ⁠מָאתַ֨יִם֙ רֶ֔כֶב וּ⁠בְ⁠שִׁשִּׁ֥ים אֶ֖לֶף פָּרָשִׁ֑ים וְ⁠אֵ֣ין מִסְפָּ֗ר לָ⁠עָ֞ם אֲשֶׁר־בָּ֤אוּ עִמּ⁠וֹ֙ מִ⁠מִּצְרַ֔יִם לוּבִ֥ים סֻכִּיִּ֖ים וְ⁠כוּשִֽׁים׃","bĕ̇⁠ʼe֤lep ẇ⁠máʼţa֨yim֙ re֔keb ẇ⁠bĕ⁠şǐşi֥̇̌ym ʼe֖lep pá̇ráşǐ֑ym wĕ⁠ʼé֣yn misĕpá̇֗r lá⁠ʻá֞m ʼàşěr-bá֤̇ʼẇ ʻiṁ⁠wò֙ mi⁠mi̇ẕĕra֔yim lẇbi֥ym suki̇yi֖̇ym wĕ⁠kẇşǐֽym׃"],[12,4,"וַ⁠יִּלְכֹּ֛ד אֶת־עָרֵ֥י הַ⁠מְּצֻר֖וֹת אֲשֶׁ֣ר לִֽ⁠יהוּדָ֑ה וַ⁠יָּבֹ֖א עַד־יְרוּשָׁלִָֽם׃ס","wa⁠yi̇lĕkò֛̇d ʼeţ-ʻáré֥y ha⁠mĕ̇ẕur֖wòţ ʼàşě֣r liֽ⁠yhẇdá֑h wa⁠yá̇bò֖ʼ ʻad-yĕrẇşá̌liáֽm׃s"],[12,5,"וּֽ⁠שְׁמַֽעְיָ֤ה הַ⁠נָּבִיא֙ בָּ֣א אֶל־רְחַבְעָ֔ם וְ⁠שָׂרֵ֣י יְהוּדָ֔ה אֲשֶׁר־נֶאֶסְפ֥וּ אֶל־יְרוּשָׁלִַ֖ם מִ⁠פְּנֵ֣י שִׁישָׁ֑ק וַ⁠יֹּ֨אמֶר לָ⁠הֶ֜ם כֹּה־אָמַ֣ר יְהוָ֗ה אַתֶּם֙ עֲזַבְתֶּ֣ם אֹתִ֔⁠י וְ⁠אַף־אֲנִ֛י עָזַ֥בְתִּי אֶתְ⁠כֶ֖ם בְּ⁠יַד־שִׁישָֽׁק׃","ẇֽ⁠şĕ̌maֽʻĕyá֤h ha⁠ná̇biyʼ֙ bá֣̇ʼ ʼel-rĕẖabĕʻá֔m wĕ⁠şá̂ré֣y yĕhẇdá֔h ʼàşěr-neʼesĕp֥ẇ ʼel-yĕrẇşá̌lia֖m mi⁠pĕ̇né֣y şǐyşá֑̌q wa⁠yò̇֨ʼmer lá⁠he֜m kò̇h-ʼáma֣r yĕhwá֗h ʼaţėm֙ ʻàzabĕţė֣m ʼòţi֔⁠y wĕ⁠ʼap-ʼàni֛y ʻáza֥bĕţi̇y ʼeţĕ⁠ke֖m bĕ̇⁠yad-şǐyşáֽ̌q׃"],[12,6,"וַ⁠יִּכָּנְע֥וּ שָׂרֵֽי־יִשְׂרָאֵ֖ל וְ⁠הַ⁠מֶּ֑לֶךְ וַ⁠יֹּאמְר֖וּ צַדִּ֥יק ׀ יְהוָֽה׃","wa⁠yi̇ká̇nĕʻ֥ẇ şá̂réֽy-yişĕ̂ráʼé֖l wĕ⁠ha⁠mė֑lekĕ wa⁠yò̇ʼmĕr֖ẇ ẕadi֥̇yq ׀ yĕhwáֽh׃"],[12,7,"וּ⁠בִ⁠רְא֤וֹת יְהוָה֙ כִּ֣י נִכְנָ֔עוּ הָיָה֩ דְבַר־יְהוָ֨ה אֶל־שְׁמַֽעְיָ֧ה ׀ לֵ⁠אמֹ֛ר נִכְנְע֖וּ לֹ֣א אַשְׁחִיתֵ֑⁠ם וְ⁠נָתַתִּ֨י לָ⁠הֶ֤ם כִּ⁠מְעַט֙ לִ⁠פְלֵיטָ֔ה וְ⁠לֹא־תִתַּ֧ךְ חֲמָתִ֛⁠י בִּ⁠ירוּשָׁלִַ֖ם בְּ⁠יַד־שִׁישָֽׁק׃","ẇ⁠bi⁠rĕʼ֤wòţ yĕhwáh֙ ki֣̇y nikĕná֔ʻẇ háyáh֩ dĕbar-yĕhwá֨h ʼel-şĕ̌maֽʻĕyá֧h ׀ lé⁠ʼmò֛r nikĕnĕʻ֖ẇ lò֣ʼ ʼaşĕ̌ẖiyţé֑⁠m wĕ⁠náţaţi̇֨y lá⁠he֤m ki̇⁠mĕʻat֙ li⁠pĕléytá֔h wĕ⁠lòʼ-ţiţȧ֧kĕ ẖàmáţi֛⁠y bi̇⁠yrẇşá̌lia֖m bĕ̇⁠yad-şǐyşáֽ̌q׃"],[12,8,"כִּ֥י יִהְיוּ־ל֖⁠וֹ לַ⁠עֲבָדִ֑ים וְ⁠יֵדְעוּ֙ עֲב֣וֹדָתִ֔⁠י וַ⁠עֲבוֹדַ֖ת מַמְלְכ֥וֹת הָ⁠אֲרָצֽוֹת׃ס","ki֥̇y yihĕyẇ-l֖⁠wò la⁠ʻàbádi֑ym wĕ⁠yédĕʻẇ֙ ʻàb֣wòdáţi֔⁠y wa⁠ʻàbwòda֖ţ mamĕlĕk֥wòţ há⁠ʼàráẕֽwòţ׃s"],[12,9,"וַ⁠יַּ֨עַל שִׁישַׁ֥ק מֶֽלֶךְ־מִצְרַיִם֮ עַל־יְרוּשָׁלִַם֒ וַ⁠יִּקַּ֞ח אֶת־אֹצְר֣וֹת בֵּית־יְהוָ֗ה וְ⁠אֶת־אֹֽצְרוֹת֙ בֵּ֣ית הַ⁠מֶּ֔לֶךְ אֶת־הַ⁠כֹּ֖ל לָקָ֑ח וַ⁠יִּקַּח֙ אֶת־מָגִנֵּ֣י הַ⁠זָּהָ֔ב אֲשֶׁ֥ר עָשָׂ֖ה שְׁלֹמֹֽה׃","wa⁠yȧ֨ʻal şǐyşǎ֥q meֽlekĕ-miẕĕrayim֮ ʻal-yĕrẇşá̌liam֒ wa⁠yi̇qȧ֞ẖ ʼeţ-ʼòẕĕr֣wòţ bé̇yţ-yĕhwá֗h wĕ⁠ʼeţ-ʼòֽẕĕrwòţ֙ bé֣̇yţ ha⁠mė֔lekĕ ʼeţ-ha⁠kò֖̇l láqá֑ẖ wa⁠yi̇qȧẖ֙ ʼeţ-máginé֣̇y ha⁠zá̇há֔b ʼàşě֥r ʻáşá֖̂h şĕ̌lòmòֽh׃"],[12,10,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֤לֶךְ רְחַבְעָם֙ תַּחְתֵּי⁠הֶ֔ם מָגִנֵּ֖י נְחֹ֑שֶׁת וְ⁠הִפְקִ֗יד עַל־יַד֙ שָׂרֵ֣י הָ⁠רָצִ֔ים הַ⁠שֹּׁ֣מְרִ֔ים פֶּ֖תַח בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֤lekĕ rĕẖabĕʻám֙ ţȧẖĕţé̇y⁠he֔m máginé֖̇y nĕẖò֑şěţ wĕ⁠hipĕqi֗yd ʻal-yad֙ şá̂ré֣y há⁠ráẕi֔ym ha⁠şò֣̇̌mĕri֔ym pė֖ţaẖ bé֥̇yţ ha⁠mėֽlekĕ׃"],[12,11,"וַ⁠יְהִ֛י מִ⁠דֵּי־ב֥וֹא הַ⁠מֶּ֖לֶךְ בֵּ֣ית יְהוָ֑ה בָּ֤אוּ הָ⁠רָצִים֙ וּ⁠נְשָׂא֔וּ⁠ם וֶ⁠הֱשִׁב֖וּ⁠ם אֶל־תָּ֥א הָ⁠רָצִֽים׃","wa⁠yĕhi֛y mi⁠dé̇y-b֥wòʼ ha⁠mė֖lekĕ bé֣̇yţ yĕhwá֑h bá֤̇ʼẇ há⁠ráẕiym֙ ẇ⁠nĕşá̂ʼ֔ẇ⁠m we⁠hèşǐb֖ẇ⁠m ʼel-ţá֥̇ʼ há⁠ráẕiֽym׃"],[12,12,"וּ⁠בְ⁠הִכָּֽנְע֗⁠וֹ שָׁ֤ב מִמֶּ֨⁠נּוּ֙ אַף־יְהוָ֔ה וְ⁠לֹ֥א לְ⁠הַשְׁחִ֖ית לְ⁠כָלָ֑ה וְ⁠גַם֙ בִּֽ⁠יהוּדָ֔ה הָיָ֖ה דְּבָרִ֥ים טוֹבִֽים׃ס","ẇ⁠bĕ⁠hikáֽ̇nĕʻ֗⁠wò şá֤̌b mimė֨⁠ṅẇ֙ ʼap-yĕhwá֔h wĕ⁠lò֥ʼ lĕ⁠haşĕ̌ẖi֖yţ lĕ⁠kálá֑h wĕ⁠gam֙ biֽ̇⁠yhẇdá֔h háyá֖h dĕ̇bári֥ym twòbiֽym׃s"],[12,13,"וַ⁠יִּתְחַזֵּ֞ק הַ⁠מֶּ֧לֶךְ רְחַבְעָ֛ם בִּ⁠ירוּשָׁלִַ֖ם וַ⁠יִּמְלֹ֑ךְ כִּ֣י בֶן־אַרְבָּעִ֣ים וְ⁠אַחַ֣ת שָׁנָה֩ רְחַבְעָ֨ם בְּ⁠מָלְכ֜⁠וֹ וּֽ⁠שֲׁבַ֨ע עֶשְׂרֵ֥ה שָׁנָ֣ה ׀ מָלַ֣ךְ בִּֽ⁠ירוּשָׁלִַ֗ם הָ֠⁠עִיר אֲשֶׁר־בָּחַ֨ר יְהוָ֜ה לָ⁠שׂ֨וּם אֶת־שְׁמ֥⁠וֹ שָׁם֙ מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ נַעֲמָ֖ה הָֽ⁠עַמֹּנִֽית׃","wa⁠yi̇ţĕẖazé̇֞q ha⁠mė֧lekĕ rĕẖabĕʻá֛m bi̇⁠yrẇşá̌lia֖m wa⁠yi̇mĕlò֑kĕ ki֣̇y ben-ʼarĕbá̇ʻi֣ym wĕ⁠ʼaẖa֣ţ şá̌náh֩ rĕẖabĕʻá֨m bĕ̇⁠málĕk֜⁠wò ẇֽ⁠şà̌ba֨ʻ ʻeşĕ̂ré֥h şá̌ná֣h ׀ mála֣kĕ biֽ̇⁠yrẇşá̌lia֗m há֠⁠ʻiyr ʼàşěr-bá̇ẖa֨r yĕhwá֜h lá⁠ş̂֨ẇm ʼeţ-şĕ̌m֥⁠wò şá̌m֙ mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l wĕ⁠şé֣̌m ʼiṁ֔⁠wò naʻàmá֖h háֽ⁠ʻamò̇niֽyţ׃"],[12,14,"וַ⁠יַּ֖עַשׂ הָ⁠רָ֑ע כִּ֣י לֹ֤א הֵכִין֙ לִבּ֔⁠וֹ לִ⁠דְר֖וֹשׁ אֶת־יְהוָֽה׃ס","wa⁠yȧ֖ʻaş̂ há⁠rá֑ʻ ki֣̇y lò֤ʼ hékiyn֙ liḃ֔⁠wò li⁠dĕr֖wòş̌ ʼeţ-yĕhwáֽh׃s"],[12,15,"וְ⁠דִבְרֵ֣י רְחַבְעָ֗ם הָ⁠רִאשֹׁנִים֙ וְ⁠הָ⁠אֲ֣חַרוֹנִ֔ים הֲ⁠לֹא־הֵ֨ם כְּתוּבִ֜ים בְּ⁠דִבְרֵ֨י שְׁמַֽעְיָ֧ה הַ⁠נָּבִ֛יא וְ⁠עִדּ֥וֹ הַ⁠חֹזֶ֖ה לְ⁠הִתְיַחֵ֑שׂ וּ⁠מִלְחֲמ֧וֹת רְחַבְעָ֛ם וְ⁠יָרָבְעָ֖ם כָּל־הַ⁠יָּמִֽים׃","wĕ⁠dibĕré֣y rĕẖabĕʻá֗m há⁠riʼşò̌niym֙ wĕ⁠há⁠ʼà֣ẖarwòni֔ym hà⁠lòʼ-hé֨m kĕ̇ţẇbi֜ym bĕ̇⁠dibĕré֨y şĕ̌maֽʻĕyá֧h ha⁠ná̇bi֛yʼ wĕ⁠ʻiḋ֥wò ha⁠ẖòze֖h lĕ⁠hiţĕyaẖé֑ş̂ ẇ⁠milĕẖàm֧wòţ rĕẖabĕʻá֛m wĕ⁠yárábĕʻá֖m ká̇l-ha⁠yá̇miֽym׃"],[12,16,"וַ⁠יִּשְׁכַּ֤ב רְחַבְעָם֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֖ר בְּ⁠עִ֣יר דָּוִ֑יד וַ⁠יִּמְלֹ֛ךְ אֲבִיָּ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b rĕẖabĕʻám֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֖r bĕ̇⁠ʻi֣yr dá̇wi֑yd wa⁠yi̇mĕlò֛kĕ ʼàbiyá֥̇h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[13,1,"בִּ⁠שְׁנַ֛ת שְׁמוֹנֶ֥ה עֶשְׂרֵ֖ה לַ⁠מֶּ֣לֶךְ יָרָבְעָ֑ם וַ⁠יִּמְלֹ֥ךְ אֲבִיָּ֖ה עַל־יְהוּדָֽה׃","bi̇⁠şĕ̌na֛ţ şĕ̌mwòne֥h ʻeşĕ̂ré֖h la⁠mė֣lekĕ yárábĕʻá֑m wa⁠yi̇mĕlò֥kĕ ʼàbiyá֖̇h ʻal-yĕhẇdáֽh׃"],[13,2,"שָׁל֣וֹשׁ שָׁנִ֗ים מָלַךְ֙ בִּ⁠יר֣וּשָׁלִַ֔ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ מִיכָיָ֥הוּ בַת־אוּרִיאֵ֖ל מִן־גִּבְעָ֑ה וּ⁠מִלְחָמָ֥ה הָיְתָ֛ה בֵּ֥ין אֲבִיָּ֖ה וּ⁠בֵ֥ין יָרָבְעָֽם׃","şá̌l֣wòş̌ şá̌ni֗ym málakĕ֙ bi̇⁠yr֣ẇşá̌lia֔m wĕ⁠şé֣̌m ʼiṁ֔⁠wò miykáyá֥hẇ baţ-ʼẇriyʼé֖l min-gi̇bĕʻá֑h ẇ⁠milĕẖámá֥h háyĕţá֛h bé֥̇yn ʼàbiyá֖̇h ẇ⁠bé֥yn yárábĕʻáֽm׃"],[13,3,"וַ⁠יֶּאְסֹ֨ר אֲבִיָּ֜ה אֶת־הַ⁠מִּלְחָמָ֗ה בְּ⁠חַ֨יִל֙ גִּבּוֹרֵ֣י מִלְחָמָ֔ה אַרְבַּע־מֵא֥וֹת אֶ֖לֶף אִ֣ישׁ בָּח֑וּר ס וְ⁠יָרָבְעָ֗ם עָרַ֤ךְ עִמּ⁠וֹ֙ מִלְחָמָ֔ה בִּ⁠שְׁמוֹנֶ֨ה מֵא֥וֹת אֶ֛לֶף אִ֥ישׁ בָּח֖וּר גִּבּ֥וֹר חָֽיִל׃ס","wa⁠yėʼĕsò֨r ʼàbiyá̇֜h ʼeţ-ha⁠mi̇lĕẖámá֗h bĕ̇⁠ẖa֨yil֙ gi̇ḃwòré֣y milĕẖámá֔h ʼarĕbȧʻ-méʼ֥wòţ ʼe֖lep ʼi֣yş̌ bá̇ẖ֑ẇr s wĕ⁠yárábĕʻá֗m ʻára֤kĕ ʻiṁ⁠wò֙ milĕẖámá֔h bi̇⁠şĕ̌mwòne֨h méʼ֥wòţ ʼe֛lep ʼi֥yş̌ bá̇ẖ֖ẇr gi̇ḃ֥wòr ẖáֽyil׃s"],[13,4,"וַ⁠יָּ֣קָם אֲבִיָּ֗ה מֵ⁠עַל֙ לְ⁠הַ֣ר צְמָרַ֔יִם אֲשֶׁ֖ר בְּ⁠הַ֣ר אֶפְרָ֑יִם וַ⁠יֹּ֕אמֶר שְׁמָע֖וּ⁠נִי יָרָבְעָ֥ם וְ⁠כָל־יִשְׂרָאֵֽל׃","wa⁠yá֣̇qám ʼàbiyá̇֗h mé⁠ʻal֙ lĕ⁠ha֣r ẕĕmára֔yim ʼàşě֖r bĕ̇⁠ha֣r ʼepĕrá֑yim wa⁠yò̇֕ʼmer şĕ̌máʻ֖ẇ⁠niy yárábĕʻá֥m wĕ⁠kál-yişĕ̂ráʼéֽl׃"],[13,5,"הֲ⁠לֹ֤א לָ⁠כֶם֙ לָ⁠דַ֔עַת כִּ֞י יְהוָ֣ה ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל נָתַ֨ן מַמְלָכָ֧ה לְ⁠דָוִ֛יד עַל־יִשְׂרָאֵ֖ל לְ⁠עוֹלָ֑ם ל֥⁠וֹ וּ⁠לְ⁠בָנָ֖י⁠ו בְּרִ֥ית מֶֽלַח׃ס","hà⁠lò֤ʼ lá⁠kem֙ lá⁠da֔ʻaţ ki̇֞y yĕhwá֣h ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l náţa֨n mamĕláká֧h lĕ⁠dáwi֛yd ʻal-yişĕ̂ráʼé֖l lĕ⁠ʻwòlá֑m l֥⁠wò ẇ⁠lĕ⁠báná֖y⁠w bĕ̇ri֥yţ meֽlaẖ׃s"],[13,6,"וַ⁠יָּ֨קָם֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט עֶ֖בֶד שְׁלֹמֹ֣ה בֶן־דָּוִ֑יד וַ⁠יִּמְרֹ֖ד עַל־אֲדֹנָֽי⁠ו׃","wa⁠yá̇֨qám֙ yárábĕʻá֣m bėn-nĕbá֔t ʻe֖bed şĕ̌lòmò֣h ben-dá̇wi֑yd wa⁠yi̇mĕrò֖d ʻal-ʼàdònáֽy⁠w׃"],[13,7,"וַ⁠יִּקָּבְצ֣וּ עָלָ֗י⁠ו אֲנָשִׁ֤ים רֵקִים֙ בְּנֵ֣י בְלִיַּ֔עַל וַ⁠יִּֽתְאַמְּצ֖וּ עַל־רְחַבְעָ֣ם בֶּן־שְׁלֹמֹ֑ה וּ⁠רְחַבְעָ֗ם הָ֤יָה נַ֨עַר֙ וְ⁠רַךְ־לֵבָ֔ב וְ⁠לֹ֥א הִתְחַזַּ֖ק לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yi̇qá̇bĕẕ֣ẇ ʻálá֗y⁠w ʼànáşǐ֤ym réqiym֙ bĕ̇né֣y bĕliyȧ֔ʻal wa⁠yiֽ̇ţĕʼamĕ̇ẕ֖ẇ ʻal-rĕẖabĕʻá֣m bėn-şĕ̌lòmò֑h ẇ⁠rĕẖabĕʻá֗m há֤yáh na֨ʻar֙ wĕ⁠rakĕ-lébá֔b wĕ⁠lò֥ʼ hiţĕẖazȧ֖q li⁠pĕnéy⁠heֽm׃"],[13,8,"וְ⁠עַתָּ֣ה ׀ אַתֶּ֣ם אֹֽמְרִ֗ים לְ⁠הִתְחַזֵּק֙ לִ⁠פְנֵי֙ מַמְלֶ֣כֶת יְהוָ֔ה בְּ⁠יַ֖ד בְּנֵ֣י דָוִ֑יד וְ⁠אַתֶּם֙ הָמ֣וֹן רָ֔ב וְ⁠עִמָּ⁠כֶם֙ עֶגְלֵ֣י זָהָ֔ב אֲשֶׁ֨ר עָשָׂ֥ה לָ⁠כֶ֛ם יָרָבְעָ֖ם לֵ⁠אלֹהִֽים׃","wĕ⁠ʻaţá֣̇h ׀ ʼaţė֣m ʼòֽmĕri֗ym lĕ⁠hiţĕẖazé̇q֙ li⁠pĕnéy֙ mamĕle֣keţ yĕhwá֔h bĕ̇⁠ya֖d bĕ̇né֣y dáwi֑yd wĕ⁠ʼaţėm֙ hám֣wòn rá֔b wĕ⁠ʻimá̇⁠kem֙ ʻegĕlé֣y záhá֔b ʼàşě֨r ʻáşá֥̂h lá⁠ke֛m yárábĕʻá֖m lé⁠ʼlòhiֽym׃"],[13,9,"הֲ⁠לֹ֤א הִדַּחְתֶּם֙ אֶת־כֹּהֲנֵ֣י יְהוָ֔ה אֶת־בְּנֵ֥י אַהֲרֹ֖ן וְ⁠הַ⁠לְוִיִּ֑ם וַ⁠תַּעֲשׂ֨וּ לָ⁠כֶ֤ם כֹּהֲנִים֙ כְּ⁠עַמֵּ֣י הָ⁠אֲרָצ֔וֹת כָּל־הַ⁠בָּ֗א לְ⁠מַלֵּ֨א יָד֜⁠וֹ בְּ⁠פַ֤ר בֶּן־בָּקָר֙ וְ⁠אֵילִ֣ם שִׁבְעָ֔ה וְ⁠הָיָ֥ה כֹהֵ֖ן לְ⁠לֹ֥א אֱלֹהִֽים׃ס","hà⁠lò֤ʼ hidȧẖĕţėm֙ ʼeţ-kò̇hàné֣y yĕhwá֔h ʼeţ-bĕ̇né֥y ʼahàrò֖n wĕ⁠ha⁠lĕwiyi֑̇m wa⁠ţȧʻàş̂֨ẇ lá⁠ke֤m kò̇hàniym֙ kĕ̇⁠ʻamé֣̇y há⁠ʼàráẕ֔wòţ ká̇l-ha⁠bá̇֗ʼ lĕ⁠malé̇֨ʼ yád֜⁠wò bĕ̇⁠pa֤r bėn-bá̇qár֙ wĕ⁠ʼéyli֣m şǐbĕʻá֔h wĕ⁠háyá֥h kòhé֖n lĕ⁠lò֥ʼ ʼèlòhiֽym׃s"],[13,10,"וַ⁠אֲנַ֛חְנוּ יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ וְ⁠לֹ֣א עֲזַבְנֻ֑⁠הוּ וְ⁠כֹ֨הֲנִ֜ים מְשָׁרְתִ֤ים לַֽ⁠יהוָה֙ בְּנֵ֣י אַהֲרֹ֔ן וְ⁠הַ⁠לְוִיִּ֖ם בַּ⁠מְלָֽאכֶת׃","wa⁠ʼàna֛ẖĕnẇ yĕhwá֥h ʼèlòhé֖y⁠nẇ wĕ⁠lò֣ʼ ʻàzabĕnu֑⁠hẇ wĕ⁠kò֨hàni֜ym mĕşá̌rĕţi֤ym laֽ⁠yhwáh֙ bĕ̇né֣y ʼahàrò֔n wĕ⁠ha⁠lĕwiyi֖̇m bȧ⁠mĕláֽʼkeţ׃"],[13,11,"וּ⁠מַקְטִרִ֣ים לַ⁠יהוָ֡ה עֹל֣וֹת בַּ⁠בֹּֽקֶר־בַּ⁠בֹּ֣קֶר וּ⁠בָ⁠עֶֽרֶב־בָּ⁠עֶ֣רֶב וּ⁠קְטֹֽרֶת־סַמִּים֩ וּ⁠מַעֲרֶ֨כֶת לֶ֜חֶם עַל־הַ⁠שֻּׁלְחָ֣ן הַ⁠טָּה֗וֹר וּ⁠מְנוֹרַ֨ת הַ⁠זָּהָ֤ב וְ⁠נֵרֹתֶ֨י⁠הָ֙ לְ⁠בָעֵר֙ בָּ⁠עֶ֣רֶב בָּ⁠עֶ֔רֶב כִּֽי־שֹׁמְרִ֣ים אֲנַ֔חְנוּ אֶת־מִשְׁמֶ֖רֶת יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וְ⁠אַתֶּ֖ם עֲזַבְתֶּ֥ם אֹתֽ⁠וֹ׃","ẇ⁠maqĕtiri֣ym la⁠yhwá֡h ʻòl֣wòţ bȧ⁠bòֽ̇qer-bȧ⁠bò֣̇qer ẇ⁠bá⁠ʻeֽreb-bá̇⁠ʻe֣reb ẇ⁠qĕtòֽreţ-sami̇ym֩ ẇ⁠maʻàre֨keţ le֜ẖem ʻal-ha⁠şu̇̌lĕẖá֣n ha⁠tá̇h֗wòr ẇ⁠mĕnwòra֨ţ ha⁠zá̇há֤b wĕ⁠néròţe֨y⁠há֙ lĕ⁠báʻér֙ bá̇⁠ʻe֣reb bá̇⁠ʻe֔reb kiֽ̇y-şò̌mĕri֣ym ʼàna֔ẖĕnẇ ʼeţ-mişĕ̌me֖reţ yĕhwá֣h ʼèlòhé֑y⁠nẇ wĕ⁠ʼaţė֖m ʻàzabĕţė֥m ʼòţֽ⁠wò׃"],[13,12,"וְ⁠הִנֵּה֩ עִמָּ֨⁠נוּ בָ⁠רֹ֜אשׁ הָ⁠אֱלֹהִ֧ים ׀ וְ⁠כֹהֲנָ֛י⁠ו וַ⁠חֲצֹצְר֥וֹת הַ⁠תְּרוּעָ֖ה לְ⁠הָרִ֣יעַ עֲלֵי⁠כֶ֑ם בְּנֵ֣י יִשְׂרָאֵ֗ל אַל־תִּלָּֽחֲמ֛וּ עִם־יְהוָ֥ה אֱלֹהֵֽי־אֲבֹתֵי⁠כֶ֖ם כִּי־לֹ֥א תַצְלִֽיחוּ׃","wĕ⁠hiné̇h֩ ʻimá̇֨⁠nẇ bá⁠rò֜ʼş̌ há⁠ʼèlòhi֧ym ׀ wĕ⁠kòhàná֛y⁠w wa⁠ẖàẕòẕĕr֥wòţ ha⁠ţĕ̇rẇʻá֖h lĕ⁠hári֣yʻa ʻàléy⁠ke֑m bĕ̇né֣y yişĕ̂ráʼé֗l ʼal-ţi̇láֽ̇ẖàm֛ẇ ʻim-yĕhwá֥h ʼèlòhéֽy-ʼàbòţéy⁠ke֖m ki̇y-lò֥ʼ ţaẕĕliֽyẖẇ׃"],[13,13,"וְ⁠יָֽרָבְעָ֗ם הֵסֵב֙ אֶת־הַ⁠מַּאְרָ֔ב לָ⁠ב֖וֹא מֵֽ⁠אַחֲרֵי⁠הֶ֑ם וַ⁠יִּֽהְיוּ֙ לִ⁠פְנֵ֣י יְהוּדָ֔ה וְ⁠הַ⁠מַּאְרָ֖ב מֵ⁠אַחֲרֵי⁠הֶֽם׃","wĕ⁠yáֽrábĕʻá֗m héséb֙ ʼeţ-ha⁠mȧʼĕrá֔b lá⁠b֖wòʼ méֽ⁠ʼaẖàréy⁠he֑m wa⁠yiֽ̇hĕyẇ֙ li⁠pĕné֣y yĕhẇdá֔h wĕ⁠ha⁠mȧʼĕrá֖b mé⁠ʼaẖàréy⁠heֽm׃"],[13,14,"וַ⁠יִּפְנ֣וּ יְהוּדָ֗ה וְ⁠הִנֵּ֨ה לָ⁠הֶ֤ם הַ⁠מִּלְחָמָה֙ פָּנִ֣ים וְ⁠אָח֔וֹר וַֽ⁠יִּצְעֲק֖וּ לַ⁠יהוָ֑ה וְ⁠הַ⁠כֹּ֣הֲנִ֔ים מחצצרים בַּ⁠חֲצֹצְרֽוֹת׃","wa⁠yi̇pĕn֣ẇ yĕhẇdá֗h wĕ⁠hiné̇֨h lá⁠he֤m ha⁠mi̇lĕẖámáh֙ pá̇ni֣ym wĕ⁠ʼáẖ֔wòr waֽ⁠yi̇ẕĕʻàq֖ẇ la⁠yhwá֑h wĕ⁠ha⁠kò֣̇hàni֔ym mẖẕẕrym bȧ⁠ẖàẕòẕĕrֽwòţ׃"],[13,15,"וַ⁠יָּרִ֖יעוּ אִ֣ישׁ יְהוּדָ֑ה וַ⁠יְהִ֗י בְּ⁠הָרִ֨יעַ֙ אִ֣ישׁ יְהוּדָ֔ה וְ⁠הָ⁠אֱלֹהִ֗ים נָגַ֤ף אֶת־יָֽרָבְעָם֙ וְ⁠כָל־יִשְׂרָאֵ֔ל לִ⁠פְנֵ֥י אֲבִיָּ֖ה וִ⁠יהוּדָֽה׃","wa⁠yá̇ri֖yʻẇ ʼi֣yş̌ yĕhẇdá֑h wa⁠yĕhi֗y bĕ̇⁠hári֨yʻa֙ ʼi֣yş̌ yĕhẇdá֔h wĕ⁠há⁠ʼèlòhi֗ym nága֤p ʼeţ-yáֽrábĕʻám֙ wĕ⁠kál-yişĕ̂ráʼé֔l li⁠pĕné֥y ʼàbiyá֖̇h wi⁠yhẇdáֽh׃"],[13,16,"וַ⁠יָּנ֥וּסוּ בְנֵי־יִשְׂרָאֵ֖ל מִ⁠פְּנֵ֣י יְהוּדָ֑ה וַ⁠יִּתְּנֵ֥⁠ם אֱלֹהִ֖ים בְּ⁠יָדָֽ⁠ם׃","wa⁠yá̇n֥ẇsẇ bĕnéy-yişĕ̂ráʼé֖l mi⁠pĕ̇né֣y yĕhẇdá֑h wa⁠yi̇ţĕ̇né֥⁠m ʼèlòhi֖ym bĕ̇⁠yádáֽ⁠m׃"],[13,17,"וַ⁠יַּכּ֥וּ בָ⁠הֶ֛ם אֲבִיָּ֥ה וְ⁠עַמּ֖⁠וֹ מַכָּ֣ה רַבָּ֑ה וַ⁠יִּפְּל֤וּ חֲלָלִים֙ מִ⁠יִּשְׂרָאֵ֔ל חֲמֵשׁ־מֵא֥וֹת אֶ֖לֶף אִ֥ישׁ בָּחֽוּר׃","wa⁠yȧk֥̇ẇ bá⁠he֛m ʼàbiyá֥̇h wĕ⁠ʻaṁ֖⁠wò maká֣̇h rabá֑̇h wa⁠yi̇pĕ̇l֤ẇ ẖàláliym֙ mi⁠yi̇şĕ̂ráʼé֔l ẖàméş̌-méʼ֥wòţ ʼe֖lep ʼi֥yş̌ bá̇ẖֽẇr׃"],[13,18,"וַ⁠יִּכָּנְע֥וּ בְנֵי־יִשְׂרָאֵ֖ל בָּ⁠עֵ֣ת הַ⁠הִ֑יא וַ⁠יֶּֽאֶמְצוּ֙ בְּנֵ֣י יְהוּדָ֔ה כִּ֣י נִשְׁעֲנ֔וּ עַל־יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃","wa⁠yi̇ká̇nĕʻ֥ẇ bĕnéy-yişĕ̂ráʼé֖l bá̇⁠ʻé֣ţ ha⁠hi֑yʼ wa⁠yėֽʼemĕẕẇ֙ bĕ̇né֣y yĕhẇdá֔h ki֣̇y nişĕ̌ʻàn֔ẇ ʻal-yĕhwá֖h ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃"],[13,19,"וַ⁠יִּרְדֹּ֣ף אֲבִיָּה֮ אַחֲרֵ֣י יָרָבְעָם֒ וַ⁠יִּלְכֹּ֤ד מִמֶּ֨⁠נּוּ֙ עָרִ֔ים אֶת־בֵּֽית־אֵל֙ וְ⁠אֶת־בְּנוֹתֶ֔י⁠הָ וְ⁠אֶת־יְשָׁנָ֖ה וְ⁠אֶת־בְּנוֹתֶ֑י⁠הָ וְ⁠אֶת־עפרון וּ⁠בְנֹתֶֽי⁠הָ׃","wa⁠yi̇rĕdò֣̇p ʼàbiyá̇h֮ ʼaẖàré֣y yárábĕʻám֒ wa⁠yi̇lĕkò֤̇d mimė֨⁠ṅẇ֙ ʻári֔ym ʼeţ-béֽ̇yţ-ʼél֙ wĕ⁠ʼeţ-bĕ̇nwòţe֔y⁠há wĕ⁠ʼeţ-yĕşá̌ná֖h wĕ⁠ʼeţ-bĕ̇nwòţe֑y⁠há wĕ⁠ʼeţ-ʻprwn ẇ⁠bĕnòţeֽy⁠há׃"],[13,20,"וְ⁠לֹֽא־עָצַ֧ר כֹּֽחַ־יָרָבְעָ֛ם ע֖וֹד בִּ⁠ימֵ֣י אֲבִיָּ֑הוּ וַ⁠יִּגְּפֵ֥⁠הוּ יְהוָ֖ה וַ⁠יָּמֹֽת׃פ","wĕ⁠lòֽʼ-ʻáẕa֧r kòֽ̇ẖa-yárábĕʻá֛m ʻ֖wòd bi̇⁠ymé֣y ʼàbiyá֑̇hẇ wa⁠yi̇gĕ̇pé֥⁠hẇ yĕhwá֖h wa⁠yá̇mòֽţ׃p"],[13,21,"וַ⁠יִּתְחַזֵּ֣ק אֲבִיָּ֔הוּ וַ⁠יִּ֨שָּׂא־ל֔⁠וֹ נָשִׁ֖ים אַרְבַּ֣ע עֶשְׂרֵ֑ה וַ⁠יּ֗וֹלֶד עֶשְׂרִ֤ים וּ⁠שְׁנַ֨יִם֙ בָּנִ֔ים וְ⁠שֵׁ֥שׁ עֶשְׂרֵ֖ה בָּנֽוֹת׃ס","wa⁠yi̇ţĕẖazé֣̇q ʼàbiyá̇֔hẇ wa⁠yi̇֨şá̇̂ʼ-l֔⁠wò náşǐ֖ym ʼarĕbȧ֣ʻ ʻeşĕ̂ré֑h wa⁠ẏ֗wòled ʻeşĕ̂ri֤ym ẇ⁠şĕ̌na֨yim֙ bá̇ni֔ym wĕ⁠şé֥̌ş̌ ʻeşĕ̂ré֖h bá̇nֽwòţ׃s"],[13,22,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י אֲבִיָּ֔ה וּ⁠דְרָכָ֖י⁠ו וּ⁠דְבָרָ֑י⁠ו כְּתוּבִ֕ים בְּ⁠מִדְרַ֖שׁ הַ⁠נָּבִ֥יא עִדּֽוֹ׃","wĕ⁠ye֨ţer֙ di̇bĕré֣y ʼàbiyá̇֔h ẇ⁠dĕráká֖y⁠w ẇ⁠dĕbárá֑y⁠w kĕ̇ţẇbi֕ym bĕ̇⁠midĕra֖ş̌ ha⁠ná̇bi֥yʼ ʻiḋֽwò׃"],[14,1,"וַ⁠יִּשְׁכַּ֨ב אֲבִיָּ֜ה עִם־אֲבֹתָ֗י⁠ו וַ⁠יִּקְבְּר֤וּ אֹת⁠וֹ֙ בְּ⁠עִ֣יר דָּוִ֔יד וַ⁠יִּמְלֹ֛ךְ אָסָ֥א בְנ֖⁠וֹ תַּחְתָּ֑י⁠ו בְּ⁠יָמָ֛י⁠ו שָׁקְטָ֥ה הָ⁠אָ֖רֶץ עֶ֥שֶׂר שָׁנִֽים׃פ","wa⁠yi̇şĕ̌kȧ֨b ʼàbiyá̇֜h ʻim-ʼàbòţá֗y⁠w wa⁠yi̇qĕbĕ̇r֤ẇ ʼòţ⁠wò֙ bĕ̇⁠ʻi֣yr dá̇wi֔yd wa⁠yi̇mĕlò֛kĕ ʼásá֥ʼ bĕn֖⁠wò ţȧẖĕţá֑̇y⁠w bĕ̇⁠yámá֛y⁠w şá̌qĕtá֥h há⁠ʼá֖reẕ ʻe֥şêr şá̌niֽym׃p"],[14,2,"וַ⁠יַּ֤עַשׂ אָסָא֙ הַ⁠טּ֣וֹב וְ⁠הַ⁠יָּשָׁ֔ר בְּ⁠עֵינֵ֖י יְהוָ֥ה אֱלֹהָֽי⁠ו׃","wa⁠yȧ֤ʻaş̂ ʼásáʼ֙ ha⁠ṫ֣wòb wĕ⁠ha⁠yá̇şá̌֔r bĕ̇⁠ʻéyné֖y yĕhwá֥h ʼèlòháֽy⁠w׃"],[14,3,"וַ⁠יָּ֛סַר אֶת־מִזְבְּח֥וֹת הַ⁠נֵּכָ֖ר וְ⁠הַ⁠בָּמ֑וֹת וַ⁠יְשַׁבֵּר֙ אֶת־הַ⁠מַּצֵּב֔וֹת וַ⁠יְגַדַּ֖ע אֶת־הָ⁠אֲשֵׁרִֽים׃","wa⁠yá֛̇sar ʼeţ-mizĕbĕ̇ẖ֥wòţ ha⁠né̇ká֖r wĕ⁠ha⁠bá̇m֑wòţ wa⁠yĕşǎbé̇r֙ ʼeţ-ha⁠mȧẕé̇b֔wòţ wa⁠yĕgadȧ֖ʻ ʼeţ-há⁠ʼàşé̌riֽym׃"],[14,4,"וַ⁠יֹּ֨אמֶר֙ לִֽ⁠יהוּדָ֔ה לִ⁠דְר֕וֹשׁ אֶת־יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵי⁠הֶ֑ם וְ⁠לַ⁠עֲשׂ֖וֹת הַ⁠תּוֹרָ֥ה וְ⁠הַ⁠מִּצְוָֽה׃","wa⁠yò̇֨ʼmer֙ liֽ⁠yhẇdá֔h li⁠dĕr֕wòş̌ ʼeţ-yĕhwá֖h ʼèlòhé֣y ʼàbwòţéy⁠he֑m wĕ⁠la⁠ʻàş֖̂wòţ ha⁠ţ̇wòrá֥h wĕ⁠ha⁠mi̇ẕĕwáֽh׃"],[14,5,"וַ⁠יָּ֨סַר֙ מִ⁠כָּל־עָרֵ֣י יְהוּדָ֔ה אֶת־הַ⁠בָּמ֖וֹת וְ⁠אֶת־הַֽ⁠חַמָּנִ֑ים וַ⁠תִּשְׁקֹ֥ט הַ⁠מַּמְלָכָ֖ה לְ⁠פָנָֽי⁠ו׃","wa⁠yá̇֨sar֙ mi⁠ká̇l-ʻáré֣y yĕhẇdá֔h ʼeţ-ha⁠bá̇m֖wòţ wĕ⁠ʼeţ-haֽ⁠ẖamá̇ni֑ym wa⁠ţi̇şĕ̌qò֥t ha⁠mȧmĕláká֖h lĕ⁠pánáֽy⁠w׃"],[14,6,"וַ⁠יִּ֛בֶן עָרֵ֥י מְצוּרָ֖ה בִּ⁠יהוּדָ֑ה כִּֽי־שָׁקְטָ֣ה הָ⁠אָ֗רֶץ וְ⁠אֵין־עִמּ֤⁠וֹ מִלְחָמָה֙ בַּ⁠שָּׁנִ֣ים הָ⁠אֵ֔לֶּה כִּֽי־הֵנִ֥יחַ יְהוָ֖ה לֽ⁠וֹ׃","wa⁠yi֛̇ben ʻáré֥y mĕẕẇrá֖h bi̇⁠yhẇdá֑h kiֽ̇y-şá̌qĕtá֣h há⁠ʼá֗reẕ wĕ⁠ʼéyn-ʻiṁ֤⁠wò milĕẖámáh֙ bȧ⁠şá̇̌ni֣ym há⁠ʼé֔lėh kiֽ̇y-héni֥yẖa yĕhwá֖h lֽ⁠wò׃"],[14,7,"וַ⁠יֹּ֨אמֶר לִֽ⁠יהוּדָ֜ה נִבְנֶ֣ה ׀ אֶת־הֶ⁠עָרִ֣ים הָ⁠אֵ֗לֶּה וְ⁠נָסֵ֨ב חוֹמָ֣ה וּ⁠מִגְדָּלִים֮ דְּלָתַ֣יִם וּ⁠בְרִיחִים֒ עוֹדֶ֨⁠נּוּ הָ⁠אָ֜רֶץ לְ⁠פָנֵ֗י⁠נוּ כִּ֤י דָרַ֨שְׁנוּ֙ אֶת־יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ דָּרַ֕שְׁנוּ וַ⁠יָּ֥נַֽח לָ֖⁠נוּ מִ⁠סָּבִ֑יב וַ⁠יִּבְנ֖וּ וַ⁠יַּצְלִֽיחוּ׃פ","wa⁠yò̇֨ʼmer liֽ⁠yhẇdá֜h nibĕne֣h ׀ ʼeţ-he⁠ʻári֣ym há⁠ʼé֗lėh wĕ⁠násé֨b ẖwòmá֣h ẇ⁠migĕdá̇liym֮ dĕ̇láţa֣yim ẇ⁠bĕriyẖiym֒ ʻwòde֨⁠ṅẇ há⁠ʼá֜reẕ lĕ⁠páné֗y⁠nẇ ki֤̇y dára֨şĕ̌nẇ֙ ʼeţ-yĕhwá֣h ʼèlòhé֔y⁠nẇ dá̇ra֕şĕ̌nẇ wa⁠yá֥̇naֽẖ lá֖⁠nẇ mi⁠sá̇bi֑yb wa⁠yi̇bĕn֖ẇ wa⁠yȧẕĕliֽyẖẇ׃p"],[14,8,"וַ⁠יְהִ֣י לְ⁠אָסָ֗א חַיִל֮ נֹשֵׂ֣א צִנָּ֣ה וָ⁠רֹמַח֒ מִֽ⁠יהוּדָה֙ שְׁלֹ֣שׁ מֵא֣וֹת אֶ֔לֶף ס וּ⁠מִ⁠בִּנְיָמִ֗ן נֹשְׂאֵ֤י מָגֵן֙ וְ⁠דֹ֣רְכֵי קֶ֔שֶׁת מָאתַ֥יִם וּ⁠שְׁמוֹנִ֖ים אָ֑לֶף כָּל־אֵ֖לֶּה גִּבּ֥וֹרֵי חָֽיִל׃","wa⁠yĕhi֣y lĕ⁠ʼásá֗ʼ ẖayil֮ nòşé֣̂ʼ ẕiná֣̇h wá⁠ròmaẖ֒ miֽ⁠yhẇdáh֙ şĕ̌lò֣ş̌ méʼ֣wòţ ʼe֔lep s ẇ⁠mi⁠bi̇nĕyámi֗n nòşĕ̂ʼé֤y mágén֙ wĕ⁠dò֣rĕkéy qe֔şěţ máʼţa֥yim ẇ⁠şĕ̌mwòni֖ym ʼá֑lep ká̇l-ʼé֖lėh gi̇ḃ֥wòréy ẖáֽyil׃"],[14,9,"וַ⁠יֵּצֵ֨א אֲלֵי⁠הֶ֜ם זֶ֣רַח הַ⁠כּוּשִׁ֗י בְּ⁠חַ֨יִל֙ אֶ֣לֶף אֲלָפִ֔ים וּ⁠מַרְכָּב֖וֹת שְׁלֹ֣שׁ מֵא֑וֹת וַ⁠יָּבֹ֖א עַד־מָרֵשָֽׁה׃","wa⁠yé̇ẕé֨ʼ ʼàléy⁠he֜m ze֣raẖ ha⁠k̇ẇşǐ֗y bĕ̇⁠ẖa֨yil֙ ʼe֣lep ʼàlápi֔ym ẇ⁠marĕká̇b֖wòţ şĕ̌lò֣ş̌ méʼ֑wòţ wa⁠yá̇bò֖ʼ ʻad-máréşáֽ̌h׃"],[14,10,"וַ⁠יֵּצֵ֥א אָסָ֖א לְ⁠פָנָ֑י⁠ו וַ⁠יַּֽעַרְכוּ֙ מִלְחָמָ֔ה בְּ⁠גֵ֥יא צְפַ֖תָה לְ⁠מָרֵשָֽׁה׃","wa⁠yé̇ẕé֥ʼ ʼásá֖ʼ lĕ⁠páná֑y⁠w wa⁠yȧֽʻarĕkẇ֙ milĕẖámá֔h bĕ̇⁠gé֥yʼ ẕĕpa֖ţáh lĕ⁠máréşáֽ̌h׃"],[14,11,"וַ⁠יִּקְרָ֨א אָסָ֜א אֶל־יְהוָ֣ה אֱלֹהָי⁠ו֮ וַ⁠יֹּאמַר֒ יְהוָ֗ה אֵֽין־עִמְּ⁠ךָ֤ לַ⁠עְזוֹר֙ בֵּ֥ין רַב֙ לְ⁠אֵ֣ין כֹּ֔חַ עָזְרֵ֜⁠נוּ יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ כִּֽי־עָלֶ֣י⁠ךָ נִשְׁעַ֔נּוּ וּ⁠בְ⁠שִׁמְ⁠ךָ֣ בָ֔אנוּ עַל־הֶ⁠הָמ֖וֹן הַ⁠זֶּ֑ה יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ אַ֔תָּה אַל־יַעְצֹ֥ר עִמְּ⁠ךָ֖ אֱנֽוֹשׁ׃ס","wa⁠yi̇qĕrá֨ʼ ʼásá֜ʼ ʼel-yĕhwá֣h ʼèlòháy⁠w֮ wa⁠yò̇ʼmar֒ yĕhwá֗h ʼéֽyn-ʻimĕ̇⁠ká֤ la⁠ʻĕzwòr֙ bé֥̇yn rab֙ lĕ⁠ʼé֣yn kò̇֔ẖa ʻázĕré֜⁠nẇ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ kiֽ̇y-ʻále֣y⁠ká nişĕ̌ʻa֔ṅẇ ẇ⁠bĕ⁠şǐmĕ⁠ká֣ bá֔ʼnẇ ʻal-he⁠hám֖wòn ha⁠zė֑h yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ ʼa֔ţá̇h ʼal-yaʻĕẕò֥r ʻimĕ̇⁠ká֖ ʼènֽwòş̌׃s"],[14,12,"וַ⁠יִּגֹּ֤ף יְהוָה֙ אֶת־הַ⁠כּוּשִׁ֔ים לִ⁠פְנֵ֥י אָסָ֖א וְ⁠לִ⁠פְנֵ֣י יְהוּדָ֑ה וַ⁠יָּנֻ֖סוּ הַ⁠כּוּשִֽׁים׃","wa⁠yi̇gò֤̇p yĕhwáh֙ ʼeţ-ha⁠k̇ẇşǐ֔ym li⁠pĕné֥y ʼásá֖ʼ wĕ⁠li⁠pĕné֣y yĕhẇdá֑h wa⁠yá̇nu֖sẇ ha⁠k̇ẇşǐֽym׃"],[14,13,"וַ⁠יִּרְדְּפֵ֨⁠ם אָסָ֜א וְ⁠הָ⁠עָ֣ם אֲשֶׁר־עִמּ⁠וֹ֮ עַד־לִ⁠גְרָר֒ וַ⁠יִּפֹּ֤ל מִ⁠כּוּשִׁים֙ לְ⁠אֵ֣ין לָ⁠הֶ֣ם מִֽחְיָ֔ה כִּֽי־נִשְׁבְּר֥וּ לִ⁠פְנֵֽי־יְהוָ֖ה וְ⁠לִ⁠פְנֵ֣י מַחֲנֵ֑⁠הוּ וַ⁠יִּשְׂא֥וּ שָׁלָ֖ל הַרְבֵּ֥ה מְאֹֽד׃","wa⁠yi̇rĕdĕ̇pé֨⁠m ʼásá֜ʼ wĕ⁠há⁠ʻá֣m ʼàşěr-ʻiṁ⁠wò֮ ʻad-li⁠gĕrár֒ wa⁠yi̇pò֤̇l mi⁠k̇ẇşǐym֙ lĕ⁠ʼé֣yn lá⁠he֣m miֽẖĕyá֔h kiֽ̇y-nişĕ̌bĕ̇r֥ẇ li⁠pĕnéֽy-yĕhwá֖h wĕ⁠li⁠pĕné֣y maẖàné֑⁠hẇ wa⁠yi̇şĕ̂ʼ֥ẇ şá̌lá֖l harĕbé֥̇h mĕʼòֽd׃"],[14,14,"וַ⁠יַּכּ֗וּ אֵ֤ת כָּל־הֶֽ⁠עָרִים֙ סְבִיב֣וֹת גְּרָ֔ר כִּי־הָיָ֥ה פַֽחַד־יְהוָ֖ה עֲלֵי⁠הֶ֑ם וַ⁠יָּבֹ֨זּוּ֙ אֶת־כָּל־הֶ֣⁠עָרִ֔ים כִּֽי־בִזָּ֥ה רַבָּ֖ה הָיְתָ֥ה בָ⁠הֶֽם׃","wa⁠yȧk̇֗ẇ ʼé֤ţ ká̇l-heֽ⁠ʻáriym֙ sĕbiyb֣wòţ gĕ̇rá֔r ki̇y-háyá֥h paֽẖad-yĕhwá֖h ʻàléy⁠he֑m wa⁠yá̇bò֨żẇ֙ ʼeţ-ká̇l-he֣⁠ʻári֔ym kiֽ̇y-bizá֥̇h rabá֖̇h háyĕţá֥h bá⁠heֽm׃"],[14,15,"וְ⁠גַם־אָהֳלֵ֥י מִקְנֶ֖ה הִכּ֑וּ וַ⁠יִּשְׁבּ֨וּ צֹ֤אן לָ⁠רֹב֙ וּ⁠גְמַלִּ֔ים וַ⁠יָּשֻׁ֖בוּ יְרוּשָׁלִָֽם׃ס","wĕ⁠gam-ʼáholé֥y miqĕne֖h hik֑̇ẇ wa⁠yi̇şĕ̌ḃ֨ẇ ẕò֤ʼn lá⁠ròb֙ ẇ⁠gĕmali̇֔ym wa⁠yá̇şǔ֖bẇ yĕrẇşá̌liáֽm׃s"],[15,1,"וַ⁠עֲזַרְיָ֨הוּ֙ בֶּן־עוֹדֵ֔ד הָיְתָ֥ה עָלָ֖י⁠ו ר֥וּחַ אֱלֹהִֽים׃","wa⁠ʻàzarĕyá֨hẇ֙ bėn-ʻwòdé֔d háyĕţá֥h ʻálá֖y⁠w r֥ẇẖa ʼèlòhiֽym׃"],[15,2,"וַ⁠יֵּצֵא֮ לִ⁠פְנֵ֣י אָסָא֒ וַ⁠יֹּ֣אמֶר ל֔⁠וֹ שְׁמָע֕וּ⁠נִי אָסָ֖א וְ⁠כָל־יְהוּדָ֣ה וּ⁠בִנְיָמִ֑ן יְהוָ֤ה עִמָּ⁠כֶם֙ בִּֽ⁠הְיֽוֹתְ⁠כֶ֣ם עִמּ֔⁠וֹ וְ⁠אִֽם־תִּדְרְשֻׁ֨⁠הוּ֙ יִמָּצֵ֣א לָ⁠כֶ֔ם וְ⁠אִם־תַּעַזְבֻ֖⁠הוּ יַעֲזֹ֥ב אֶתְ⁠כֶֽם׃ס","wa⁠yé̇ẕéʼ֮ li⁠pĕné֣y ʼásáʼ֒ wa⁠yò֣̇ʼmer l֔⁠wò şĕ̌máʻ֕ẇ⁠niy ʼásá֖ʼ wĕ⁠kál-yĕhẇdá֣h ẇ⁠binĕyámi֑n yĕhwá֤h ʻimá̇⁠kem֙ biֽ̇⁠hĕyֽwòţĕ⁠ke֣m ʻiṁ֔⁠wò wĕ⁠ʼiֽm-ţi̇dĕrĕşǔ֨⁠hẇ֙ yimá̇ẕé֣ʼ lá⁠ke֔m wĕ⁠ʼim-ţȧʻazĕbu֖⁠hẇ yaʻàzò֥b ʼeţĕ⁠keֽm׃s"],[15,3,"וְ⁠יָמִ֥ים רַבִּ֖ים לְ⁠יִשְׂרָאֵ֑ל לְ⁠לֹ֣א ׀ אֱלֹהֵ֣י אֱמֶ֗ת וּ⁠לְ⁠לֹ֛א כֹּהֵ֥ן מוֹרֶ֖ה וּ⁠לְ⁠לֹ֥א תוֹרָֽה׃","wĕ⁠yámi֥ym rabi֖̇ym lĕ⁠yişĕ̂ráʼé֑l lĕ⁠lò֣ʼ ׀ ʼèlòhé֣y ʼème֗ţ ẇ⁠lĕ⁠lò֛ʼ kò̇hé֥n mwòre֖h ẇ⁠lĕ⁠lò֥ʼ ţwòráֽh׃"],[15,4,"וַ⁠יָּ֨שָׁב֙ בַּ⁠צַּר־ל֔⁠וֹ עַל־יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַ⁠יְבַקְשֻׁ֖⁠הוּ וַ⁠יִּמָּצֵ֥א לָ⁠הֶֽם׃","wa⁠yá̇֨şá̌b֙ bȧ⁠ẕȧr-l֔⁠wò ʻal-yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wa⁠yĕbaqĕşǔ֖⁠hẇ wa⁠yi̇má̇ẕé֥ʼ lá⁠heֽm׃"],[15,5,"וּ⁠בָ⁠עִתִּ֣ים הָ⁠הֵ֔ם אֵ֥ין שָׁל֖וֹם לַ⁠יּוֹצֵ֣א וְ⁠לַ⁠בָּ֑א כִּ֚י מְהוּמֹ֣ת רַבּ֔וֹת עַ֥ל כָּל־יוֹשְׁבֵ֖י הָ⁠אֲרָצֽוֹת׃","ẇ⁠bá⁠ʻiţi֣̇ym há⁠hé֔m ʼé֥yn şá̌l֖wòm la⁠ẏwòẕé֣ʼ wĕ⁠la⁠bá֑̇ʼ ki֚̇y mĕhẇmò֣ţ raḃ֔wòţ ʻa֥l ká̇l-ywòşĕ̌bé֖y há⁠ʼàráẕֽwòţ׃"],[15,6,"וְ⁠כֻתְּת֥וּ גוֹי־בְּ⁠ג֖וֹי וְ⁠עִ֣יר בְּ⁠עִ֑יר כִּֽי־אֱלֹהִ֥ים הֲמָמָ֖⁠ם בְּ⁠כָל־צָרָֽה׃","wĕ⁠kuţĕ̇ţ֥ẇ gwòy-bĕ̇⁠g֖wòy wĕ⁠ʻi֣yr bĕ̇⁠ʻi֑yr kiֽ̇y-ʼèlòhi֥ym hàmámá֖⁠m bĕ̇⁠kál-ẕáráֽh׃"],[15,7,"וְ⁠אַתֶּ֣ם חִזְק֔וּ וְ⁠אַל־יִרְפּ֖וּ יְדֵי⁠כֶ֑ם כִּ֛י יֵ֥שׁ שָׂכָ֖ר לִ⁠פְעֻלַּתְ⁠כֶֽם׃ס","wĕ⁠ʼaţė֣m ẖizĕq֔ẇ wĕ⁠ʼal-yirĕṗ֖ẇ yĕdéy⁠ke֑m ki֛̇y yé֥ş̌ şá̂ká֖r li⁠pĕʻulȧţĕ⁠keֽm׃s"],[15,8,"וְ⁠כִ⁠שְׁמֹ֨עַ אָסָ֜א הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה וְ⁠הַ⁠נְּבוּאָה֮ עֹדֵ֣ד הַ⁠נָּבִיא֒ הִתְחַזַּ֗ק וַ⁠יַּעֲבֵ֤ר הַ⁠שִּׁקּוּצִים֙ מִ⁠כָּל־אֶ֤רֶץ יְהוּדָה֙ וּ⁠בִנְיָמִ֔ן וּ⁠מִן־הֶ֣⁠עָרִ֔ים אֲשֶׁ֥ר לָכַ֖ד מֵ⁠הַ֣ר אֶפְרָ֑יִם וַ⁠יְחַדֵּשׁ֙ אֶת־מִזְבַּ֣ח יְהוָ֔ה אֲשֶׁ֕ר לִ⁠פְנֵ֖י אוּלָ֥ם יְהוָֽה׃","wĕ⁠ki⁠şĕ̌mò֨ʻa ʼásá֜ʼ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh wĕ⁠ha⁠nĕ̇bẇʼáh֮ ʻòdé֣d ha⁠ná̇biyʼ֒ hiţĕẖazȧ֗q wa⁠yȧʻàbé֤r ha⁠şi̇̌q̇ẇẕiym֙ mi⁠ká̇l-ʼe֤reẕ yĕhẇdáh֙ ẇ⁠binĕyámi֔n ẇ⁠min-he֣⁠ʻári֔ym ʼàşě֥r láka֖d mé⁠ha֣r ʼepĕrá֑yim wa⁠yĕẖadé̇ş̌֙ ʼeţ-mizĕbȧ֣ẖ yĕhwá֔h ʼàşě֕r li⁠pĕné֖y ʼẇlá֥m yĕhwáֽh׃"],[15,9,"וַ⁠יִּקְבֹּ֗ץ אֶת־כָּל־יְהוּדָה֙ וּ⁠בִנְיָמִ֔ן וְ⁠הַ⁠גָּרִים֙ עִמָּ⁠הֶ֔ם מֵ⁠אֶפְרַ֥יִם וּ⁠מְנַשֶּׁ֖ה וּ⁠מִ⁠שִּׁמְע֑וֹן כִּֽי־נָפְל֨וּ עָלָ֤י⁠ו מִ⁠יִּשְׂרָאֵל֙ לָ⁠רֹ֔ב בִּ⁠רְאֹתָ֕⁠ם כִּֽי־יְהוָ֥ה אֱלֹהָ֖י⁠ו עִמּֽ⁠וֹ׃פ","wa⁠yi̇qĕbò̇֗ẕ ʼeţ-ká̇l-yĕhẇdáh֙ ẇ⁠binĕyámi֔n wĕ⁠ha⁠gá̇riym֙ ʻimá̇⁠he֔m mé⁠ʼepĕra֥yim ẇ⁠mĕnaşė֖̌h ẇ⁠mi⁠şi̇̌mĕʻ֑wòn kiֽ̇y-nápĕl֨ẇ ʻálá֤y⁠w mi⁠yi̇şĕ̂ráʼél֙ lá⁠rò֔b bi̇⁠rĕʼòţá֕⁠m kiֽ̇y-yĕhwá֥h ʼèlòhá֖y⁠w ʻiṁֽ⁠wò׃p"],[15,10,"וַ⁠יִּקָּבְצ֥וּ יְרוּשָׁלִַ֖ם בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁלִישִׁ֑י לִ⁠שְׁנַ֥ת חֲמֵשׁ־עֶשְׂרֵ֖ה לְ⁠מַלְכ֥וּת אָסָֽא׃","wa⁠yi̇qá̇bĕẕ֥ẇ yĕrẇşá̌lia֖m bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌liyşǐ֑y li⁠şĕ̌na֥ţ ẖàméş̌-ʻeşĕ̂ré֖h lĕ⁠malĕk֥ẇţ ʼásáֽʼ׃"],[15,11,"וַ⁠יִּזְבְּח֤וּ לַ⁠יהוָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא מִן־הַ⁠שָּׁלָ֖ל הֵבִ֑יאוּ בָּקָר֙ שְׁבַ֣ע מֵא֔וֹת וְ⁠צֹ֖אן שִׁבְעַ֥ת אֲלָפִֽים׃","wa⁠yi̇zĕbĕ̇ẖ֤ẇ la⁠yhwáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ min-ha⁠şá̇̌lá֖l hébi֑yʼẇ bá̇qár֙ şĕ̌ba֣ʻ méʼ֔wòţ wĕ⁠ẕò֖ʼn şǐbĕʻa֥ţ ʼàlápiֽym׃"],[15,12,"וַ⁠יָּבֹ֣אוּ בַ⁠בְּרִ֔ית לִ⁠דְר֕וֹשׁ אֶת־יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵי⁠הֶ֑ם בְּ⁠כָל־לְבָבָ֖⁠ם וּ⁠בְ⁠כָל־נַפְשָֽׁ⁠ם׃","wa⁠yá̇bò֣ʼẇ ba⁠bĕ̇ri֔yţ li⁠dĕr֕wòş̌ ʼeţ-yĕhwá֖h ʼèlòhé֣y ʼàbwòţéy⁠he֑m bĕ̇⁠kál-lĕbábá֖⁠m ẇ⁠bĕ⁠kál-napĕşáֽ̌⁠m׃"],[15,13,"וְ⁠כֹ֨ל אֲשֶׁ֧ר לֹֽא־יִדְרֹ֛שׁ לַ⁠יהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל יוּמָ֑ת לְ⁠מִן־קָטֹן֙ וְ⁠עַד־גָּד֔וֹל לְ⁠מֵ⁠אִ֖ישׁ וְ⁠עַד־אִשָּֽׁה׃","wĕ⁠kò֨l ʼàşě֧r lòֽʼ-yidĕrò֛ş̌ la⁠yhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l yẇmá֑ţ lĕ⁠min-qátòn֙ wĕ⁠ʻad-gá̇d֔wòl lĕ⁠mé⁠ʼi֖yş̌ wĕ⁠ʻad-ʼişáֽ̇̌h׃"],[15,14,"וַ⁠יִּשָּֽׁבְעוּ֙ לַ⁠יהוָ֔ה בְּ⁠ק֥וֹל גָּד֖וֹל וּ⁠בִ⁠תְרוּעָ֑ה וּ⁠בַ⁠חֲצֹצְר֖וֹת וּ⁠בְ⁠שׁוֹפָרֽוֹת׃","wa⁠yi̇şáֽ̇̌bĕʻẇ֙ la⁠yhwá֔h bĕ̇⁠q֥wòl gá̇d֖wòl ẇ⁠bi⁠ţĕrẇʻá֑h ẇ⁠ba⁠ẖàẕòẕĕr֖wòţ ẇ⁠bĕ⁠ş̌wòpárֽwòţ׃"],[15,15,"וַ⁠יִּשְׂמְח֨וּ כָל־יְהוּדָ֜ה עַל־הַ⁠שְּׁבוּעָ֗ה כִּ֤י בְ⁠כָל־לְבָבָ⁠ם֙ נִשְׁבָּ֔עוּ וּ⁠בְ⁠כָל־רְצוֹנָ֣⁠ם בִּקְשֻׁ֔⁠הוּ וַ⁠יִּמָּצֵ֖א לָ⁠הֶ֑ם וַ⁠יָּ֧נַח יְהוָ֛ה לָ⁠הֶ֖ם מִ⁠סָּבִֽיב׃","wa⁠yi̇şĕ̂mĕẖ֨ẇ kál-yĕhẇdá֜h ʻal-ha⁠şĕ̇̌bẇʻá֗h ki֤̇y bĕ⁠kál-lĕbábá⁠m֙ nişĕ̌bá̇֔ʻẇ ẇ⁠bĕ⁠kál-rĕẕwòná֣⁠m bi̇qĕşǔ֔⁠hẇ wa⁠yi̇má̇ẕé֖ʼ lá⁠he֑m wa⁠yá֧̇naẖ yĕhwá֛h lá⁠he֖m mi⁠sá̇biֽyb׃"],[15,16,"וְ⁠גַֽם־מַעֲכָ֞ה אֵ֣ם ׀ אָסָ֣א הַ⁠מֶּ֗לֶךְ הֱסִירָ⁠הּ֙ מִ⁠גְּבִירָ֔ה אֲשֶׁר־עָשְׂתָ֥ה לַ⁠אֲשֵׁרָ֖ה מִפְלָ֑צֶת וַ⁠יִּכְרֹ֤ת אָסָא֙ אֶת־מִפְלַצְתָּ֔⁠הּ וַ⁠יָּ֕דֶק וַ⁠יִּשְׂרֹ֖ף בְּ⁠נַ֥חַל קִדְרֽוֹן׃","wĕ⁠gaֽm-maʻàká֞h ʼé֣m ׀ ʼásá֣ʼ ha⁠mė֗lekĕ hèsiyrá⁠ḣ֙ mi⁠gĕ̇biyrá֔h ʼàşěr-ʻáşĕ̂ţá֥h la⁠ʼàşé̌rá֖h mipĕlá֑ẕeţ wa⁠yi̇kĕrò֤ţ ʼásáʼ֙ ʼeţ-mipĕlaẕĕţá̇֔⁠ḣ wa⁠yá̇֕deq wa⁠yi̇şĕ̂rò֖p bĕ̇⁠na֥ẖal qidĕrֽwòn׃"],[15,17,"וְ⁠הַ֨⁠בָּמ֔וֹת לֹא־סָ֖רוּ מִ⁠יִּשְׂרָאֵ֑ל רַ֧ק לְבַב־אָסָ֛א הָיָ֥ה שָׁלֵ֖ם כָּל־יָמָֽי⁠ו׃","wĕ⁠ha֨⁠bá̇m֔wòţ lòʼ-sá֖rẇ mi⁠yi̇şĕ̂ráʼé֑l ra֧q lĕbab-ʼásá֛ʼ háyá֥h şá̌lé֖m ká̇l-yámáֽy⁠w׃"],[15,18,"וַ⁠יָּבֵ֞א אֶת־קָדְשֵׁ֥י אָבִ֛י⁠ו וְ⁠קָֽדָשָׁ֖י⁠ו בֵּ֣ית הָ⁠אֱלֹהִ֑ים כֶּ֥סֶף וְ⁠זָהָ֖ב וְ⁠כֵלִֽים׃","wa⁠yá̇bé֞ʼ ʼeţ-qádĕşé֥̌y ʼábi֛y⁠w wĕ⁠qáֽdáşá֖̌y⁠w bé֣̇yţ há⁠ʼèlòhi֑ym kė֥sep wĕ⁠záhá֖b wĕ⁠kéliֽym׃"],[15,19,"וּ⁠מִלְחָמָ֖ה לֹ֣א הָיָ֑תָה עַ֛ד שְׁנַת־שְׁלֹשִׁ֥ים וְ⁠חָמֵ֖שׁ לְ⁠מַלְכ֥וּת אָסָֽא׃ס","ẇ⁠milĕẖámá֖h lò֣ʼ háyá֑ţáh ʻa֛d şĕ̌naţ-şĕ̌lòşǐ֥ym wĕ⁠ẖámé֖ş̌ lĕ⁠malĕk֥ẇţ ʼásáֽʼ׃s"],[16,1,"בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וָ⁠שֵׁשׁ֙ לְ⁠מַלְכ֣וּת אָסָ֔א עָלָ֞ה בַּעְשָׁ֤א מֶֽלֶךְ־יִשְׂרָאֵל֙ עַל־יְהוּדָ֔ה וַ⁠יִּ֖בֶן אֶת־הָ⁠רָמָ֑ה לְ⁠בִלְתִּ֗י תֵּ֚ת יוֹצֵ֣א וָ⁠בָ֔א לְ⁠אָסָ֖א מֶ֥לֶךְ יְהוּדָֽה׃","bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym wá⁠şé̌ş̌֙ lĕ⁠malĕk֣ẇţ ʼásá֔ʼ ʻálá֞h bȧʻĕşá֤̌ʼ meֽlekĕ-yişĕ̂ráʼél֙ ʻal-yĕhẇdá֔h wa⁠yi֖̇ben ʼeţ-há⁠rámá֑h lĕ⁠bilĕţi̇֗y ţé֚̇ţ ywòẕé֣ʼ wá⁠bá֔ʼ lĕ⁠ʼásá֖ʼ me֥lekĕ yĕhẇdáֽh׃"],[16,2,"וַ⁠יֹּצֵ֨א אָסָ֜א כֶּ֣סֶף וְ⁠זָהָ֗ב מֵ⁠אֹֽצְר֛וֹת בֵּ֥ית יְהוָ֖ה וּ⁠בֵ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׁלַ֗ח אֶל־בֶּן־הֲדַד֙ מֶ֣לֶךְ אֲרָ֔ם הַ⁠יּוֹשֵׁ֥ב בְּ⁠דַרְמֶ֖שֶׂק לֵ⁠אמֹֽר׃","wa⁠yò̇ẕé֨ʼ ʼásá֜ʼ kė֣sep wĕ⁠záhá֗b mé⁠ʼòֽẕĕr֛wòţ bé֥̇yţ yĕhwá֖h ẇ⁠bé֣yţ ha⁠mė֑lekĕ wa⁠yi̇şĕ̌la֗ẖ ʼel-bėn-hàdad֙ me֣lekĕ ʼàrá֔m ha⁠ẏwòşé֥̌b bĕ̇⁠darĕme֖şêq lé⁠ʼmòֽr׃"],[16,3,"בְּרִית֙ בֵּינִ֣⁠י וּ⁠בֵינֶ֔⁠ךָ וּ⁠בֵ֥ין אָבִ֖⁠י וּ⁠בֵ֣ין אָבִ֑י⁠ךָ הִנֵּ֨ה שָׁלַ֤חְתִּֽי לְ⁠ךָ֙ כֶּ֣סֶף וְ⁠זָהָ֔ב לֵ֞ךְ הָפֵ֣ר בְּרִֽיתְ⁠ךָ֗ אֶת־בַּעְשָׁא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וְ⁠יַעֲלֶ֖ה מֵ⁠עָלָֽ⁠י׃","bĕ̇riyţ֙ bé̇yni֣⁠y ẇ⁠béyne֔⁠ká ẇ⁠bé֥yn ʼábi֖⁠y ẇ⁠bé֣yn ʼábi֑y⁠ká hiné̇֨h şá̌la֤ẖĕţiֽ̇y lĕ⁠ká֙ kė֣sep wĕ⁠záhá֔b lé֞kĕ hápé֣r bĕ̇riֽyţĕ⁠ká֗ ʼeţ-bȧʻĕşá̌ʼ֙ me֣lekĕ yişĕ̂ráʼé֔l wĕ⁠yaʻàle֖h mé⁠ʻáláֽ⁠y׃"],[16,4,"וַ⁠יִּשְׁמַ֨ע בֶּן הֲדַ֜ד אֶל־הַ⁠מֶּ֣לֶךְ אָסָ֗א וַ֠⁠יִּשְׁלַח אֶת־שָׂרֵ֨י הַ⁠חֲיָלִ֤ים אֲשֶׁר־ל⁠וֹ֙ אֶל־עָרֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּכּוּ֙ אֶת־עִיּ֣וֹן וְ⁠אֶת־דָּ֔ן וְ⁠אֵ֖ת אָבֵ֣ל מָ֑יִם וְ⁠אֵ֥ת כָּֽל־מִסְכְּנ֖וֹת עָרֵ֥י נַפְתָּלִֽי׃","wa⁠yi̇şĕ̌ma֨ʻ bėn hàda֜d ʼel-ha⁠mė֣lekĕ ʼásá֗ʼ wa֠⁠yi̇şĕ̌laẖ ʼeţ-şá̂ré֨y ha⁠ẖàyáli֤ym ʼàşěr-l⁠wò֙ ʼel-ʻáré֣y yişĕ̂ráʼé֔l wa⁠yȧk̇ẇ֙ ʼeţ-ʻiẏ֣wòn wĕ⁠ʼeţ-dá̇֔n wĕ⁠ʼé֖ţ ʼábé֣l má֑yim wĕ⁠ʼé֥ţ káֽ̇l-misĕkĕ̇n֖wòţ ʻáré֥y napĕţá̇liֽy׃"],[16,5,"וַ⁠יְהִי֙ כִּ⁠שְׁמֹ֣עַ בַּעְשָׁ֔א וַ⁠יֶּחְדַּ֕ל מִ⁠בְּנ֖וֹת אֶת־הָ⁠רָמָ֑ה וַ⁠יַּשְׁבֵּ֖ת אֶת־מְלַאכְתּֽ⁠וֹ׃ס","wa⁠yĕhiy֙ ki̇⁠şĕ̌mò֣ʻa bȧʻĕşá̌֔ʼ wa⁠yėẖĕdȧ֕l mi⁠bĕ̇n֖wòţ ʼeţ-há⁠rámá֑h wa⁠yȧşĕ̌bé֖̇ţ ʼeţ-mĕlaʼkĕţֽ̇⁠wò׃s"],[16,6,"וְ⁠אָסָ֣א הַ⁠מֶּ֗לֶךְ לָקַח֙ אֶת־כָּל־יְהוּדָ֔ה וַ⁠יִּשְׂא֞וּ אֶת־אַבְנֵ֤י הָֽ⁠רָמָה֙ וְ⁠אֶת־עֵצֶ֔י⁠הָ אֲשֶׁ֥ר בָּנָ֖ה בַּעְשָׁ֑א וַ⁠יִּ֣בֶן בָּ⁠הֶ֔ם אֶת־גֶּ֖בַע וְ⁠אֶת־הַ⁠מִּצְפָּֽה׃ס","wĕ⁠ʼásá֣ʼ ha⁠mė֗lekĕ láqaẖ֙ ʼeţ-ká̇l-yĕhẇdá֔h wa⁠yi̇şĕ̂ʼ֞ẇ ʼeţ-ʼabĕné֤y háֽ⁠rámáh֙ wĕ⁠ʼeţ-ʻéẕe֔y⁠há ʼàşě֥r bá̇ná֖h bȧʻĕşá֑̌ʼ wa⁠yi֣̇ben bá̇⁠he֔m ʼeţ-gė֖baʻ wĕ⁠ʼeţ-ha⁠mi̇ẕĕpáֽ̇h׃s"],[16,7,"וּ⁠בָ⁠עֵ֣ת הַ⁠הִ֗יא בָּ֚א חֲנָ֣נִי הָ⁠רֹאֶ֔ה אֶל־אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו בְּ⁠הִשָּׁ֨עֶנְ⁠ךָ֜ עַל־מֶ֤לֶךְ אֲרָם֙ וְ⁠לֹ֤א נִשְׁעַ֨נְתָּ֙ עַל־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ עַל־כֵּ֗ן נִמְלַ֛ט חֵ֥יל מֶֽלֶךְ־אֲרָ֖ם מִ⁠יָּדֶֽ⁠ךָ׃","ẇ⁠bá⁠ʻé֣ţ ha⁠hi֗yʼ bá֚̇ʼ ẖàná֣niy há⁠ròʼe֔h ʼel-ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h wa⁠yò֣̇ʼmer ʼélá֗y⁠w bĕ̇⁠hişá̇̌֨ʻenĕ⁠ká֜ ʻal-me֤lekĕ ʼàrám֙ wĕ⁠lò֤ʼ nişĕ̌ʻa֨nĕţá̇֙ ʻal-yĕhwá֣h ʼèlòhe֔y⁠ká ʻal-ké̇֗n nimĕla֛t ẖé֥yl meֽlekĕ-ʼàrá֖m mi⁠yá̇deֽ⁠ká׃"],[16,8,"הֲ⁠לֹ֧א הַ⁠כּוּשִׁ֣ים וְ⁠הַ⁠לּוּבִ֗ים הָי֨וּ לְ⁠חַ֧יִל ׀ לָ⁠רֹ֛ב לְ⁠רֶ֥כֶב וּ⁠לְ⁠פָרָשִׁ֖ים לְ⁠הַרְבֵּ֣ה מְאֹ֑ד וּ⁠בְ⁠הִשָּֽׁעֶנְ⁠ךָ֥ עַל־יְהוָ֖ה נְתָנָ֥⁠ם בְּ⁠יָדֶֽ⁠ךָ׃","hà⁠lò֧ʼ ha⁠k̇ẇşǐ֣ym wĕ⁠ha⁠l̇ẇbi֗ym háy֨ẇ lĕ⁠ẖa֧yil ׀ lá⁠rò֛b lĕ⁠re֥keb ẇ⁠lĕ⁠páráşǐ֖ym lĕ⁠harĕbé֣̇h mĕʼò֑d ẇ⁠bĕ⁠hişáֽ̇̌ʻenĕ⁠ká֥ ʻal-yĕhwá֖h nĕţáná֥⁠m bĕ̇⁠yádeֽ⁠ká׃"],[16,9,"כִּ֣י יְהוָ֗ה עֵינָ֞י⁠ו מְשֹׁטְט֤וֹת בְּ⁠כָל־הָ⁠אָ֨רֶץ֙ לְ֠⁠הִתְחַזֵּק עִם־לְבָבָ֥⁠ם שָׁלֵ֛ם אֵלָ֖י⁠ו נִסְכַּ֣לְתָּ עַל־זֹ֑את כִּ֣י מֵ⁠עַ֔תָּה יֵ֥שׁ עִמְּ⁠ךָ֖ מִלְחָמֽוֹת׃","ki֣̇y yĕhwá֗h ʻéyná֞y⁠w mĕşò̌tĕt֤wòţ bĕ̇⁠kál-há⁠ʼá֨reẕ֙ lĕ֠⁠hiţĕẖazé̇q ʻim-lĕbábá֥⁠m şá̌lé֛m ʼélá֖y⁠w nisĕkȧ֣lĕţá̇ ʻal-zò֑ʼţ ki֣̇y mé⁠ʻa֔ţá̇h yé֥ş̌ ʻimĕ̇⁠ká֖ milĕẖámֽwòţ׃"],[16,10,"וַ⁠יִּכְעַ֨ס אָסָ֜א אֶל־הָ⁠רֹאֶ֗ה וַֽ⁠יִּתְּנֵ֨⁠הוּ֙ בֵּ֣ית הַ⁠מַּהְפֶּ֔כֶת כִּֽי־בְ⁠זַ֥עַף עִמּ֖⁠וֹ עַל־זֹ֑את וַ⁠יְרַצֵּ֥ץ אָסָ֛א מִן־הָ⁠עָ֖ם בָּ⁠עֵ֥ת הַ⁠הִֽיא׃","wa⁠yi̇kĕʻa֨s ʼásá֜ʼ ʼel-há⁠ròʼe֗h waֽ⁠yi̇ţĕ̇né֨⁠hẇ֙ bé֣̇yţ ha⁠mȧhĕpė֔keţ kiֽ̇y-bĕ⁠za֥ʻap ʻiṁ֖⁠wò ʻal-zò֑ʼţ wa⁠yĕraẕé֥̇ẕ ʼásá֛ʼ min-há⁠ʻá֖m bá̇⁠ʻé֥ţ ha⁠hiֽyʼ׃"],[16,11,"וְ⁠הִנֵּה֙ דִּבְרֵ֣י אָסָ֔א הָ⁠רִאשׁוֹנִ֖ים וְ⁠הָ⁠אַחֲרוֹנִ֑ים הִנָּ֤⁠ם כְּתוּבִים֙ עַל־סֵ֣פֶר הַ⁠מְּלָכִ֔ים לִ⁠יהוּדָ֖ה וְ⁠יִשְׂרָאֵֽל׃","wĕ⁠hiné̇h֙ di̇bĕré֣y ʼásá֔ʼ há⁠riʼş̌wòni֖ym wĕ⁠há⁠ʼaẖàrwòni֑ym hiná֤̇⁠m kĕ̇ţẇbiym֙ ʻal-sé֣per ha⁠mĕ̇láki֔ym li⁠yhẇdá֖h wĕ⁠yişĕ̂ráʼéֽl׃"],[16,12,"וַ⁠יֶּחֱלֶ֣א אָסָ֡א בִּ⁠שְׁנַת֩ שְׁלוֹשִׁ֨ים וָ⁠תֵ֤שַׁע לְ⁠מַלְכוּת⁠וֹ֙ בְּ⁠רַגְלָ֔י⁠ו עַד־לְ⁠מַ֖עְלָ⁠ה חָלְי֑⁠וֹ וְ⁠גַם־בְּ⁠חָלְי⁠וֹ֙ לֹא־דָרַ֣שׁ אֶת־יְהוָ֔ה כִּ֖י בָּ⁠רֹפְאִֽים׃","wa⁠yėẖèle֣ʼ ʼásá֡ʼ bi̇⁠şĕ̌naţ֩ şĕ̌lwòşǐ֨ym wá⁠ţé֤şǎʻ lĕ⁠malĕkẇţ⁠wò֙ bĕ̇⁠ragĕlá֔y⁠w ʻad-lĕ⁠ma֖ʻĕlá⁠h ẖálĕy֑⁠wò wĕ⁠gam-bĕ̇⁠ẖálĕy⁠wò֙ lòʼ-dára֣ş̌ ʼeţ-yĕhwá֔h ki֖̇y bá̇⁠ròpĕʼiֽym׃"],[16,13,"וַ⁠יִּשְׁכַּ֥ב אָסָ֖א עִם־אֲבֹתָ֑י⁠ו וַ⁠יָּ֕מָת בִּ⁠שְׁנַ֛ת אַרְבָּעִ֥ים וְ⁠אַחַ֖ת לְ⁠מָלְכֽ⁠וֹ׃","wa⁠yi̇şĕ̌kȧ֥b ʼásá֖ʼ ʻim-ʼàbòţá֑y⁠w wa⁠yá̇֕máţ bi̇⁠şĕ̌na֛ţ ʼarĕbá̇ʻi֥ym wĕ⁠ʼaẖa֖ţ lĕ⁠málĕkֽ⁠wò׃"],[16,14,"וַ⁠יִּקְבְּרֻ֣⁠הוּ בְ⁠קִבְרֹתָ֗י⁠ו אֲשֶׁ֣ר כָּֽרָה־ל⁠וֹ֮ בְּ⁠עִ֣יר דָּוִיד֒ וַ⁠יַּשְׁכִּיבֻ֗⁠הוּ בַּ⁠מִּשְׁכָּב֙ אֲשֶׁ֤ר מִלֵּא֙ בְּשָׂמִ֣ים וּ⁠זְנִ֔ים מְרֻקָּחִ֖ים בְּ⁠מִרְקַ֣חַת מַעֲשֶׂ֑ה וַ⁠יִּשְׂרְפוּ־ל֥⁠וֹ שְׂרֵפָ֖ה גְּדוֹלָ֥ה עַד־לִ⁠מְאֹֽד׃פ","wa⁠yi̇qĕbĕ̇ru֣⁠hẇ bĕ⁠qibĕròţá֗y⁠w ʼàşě֣r káֽ̇ráh-l⁠wò֮ bĕ̇⁠ʻi֣yr dá̇wiyd֒ wa⁠yȧşĕ̌ki̇ybu֗⁠hẇ bȧ⁠mi̇şĕ̌ká̇b֙ ʼàşě֤r milé̇ʼ֙ bĕ̇şá̂mi֣ym ẇ⁠zĕni֔ym mĕruqá̇ẖi֖ym bĕ̇⁠mirĕqa֣ẖaţ maʻàşê֑h wa⁠yi̇şĕ̂rĕpẇ-l֥⁠wò şĕ̂répá֖h gĕ̇dwòlá֥h ʻad-li⁠mĕʼòֽd׃p"],[17,1,"וַ⁠יִּמְלֹ֛ךְ יְהוֹשָׁפָ֥ט בְּנ֖⁠וֹ תַּחְתָּ֑י⁠ו וַ⁠יִּתְחַזֵּ֖ק עַל־יִשְׂרָאֵֽל׃","wa⁠yi̇mĕlò֛kĕ yĕhwòşá̌pá֥t bĕ̇n֖⁠wò ţȧẖĕţá֑̇y⁠w wa⁠yi̇ţĕẖazé֖̇q ʻal-yişĕ̂ráʼéֽl׃"],[17,2,"וַ⁠יִּ֨תֶּן־חַ֔יִל בְּ⁠כָל־עָרֵ֥י יְהוּדָ֖ה הַ⁠בְּצֻר֑וֹת וַ⁠יִּתֵּ֤ן נְצִיבִים֙ בְּ⁠אֶ֣רֶץ יְהוּדָ֔ה וּ⁠בְ⁠עָרֵ֣י אֶפְרַ֔יִם אֲשֶׁ֥ר לָכַ֖ד אָסָ֥א אָבִֽי⁠ו׃","wa⁠yi̇֨ţėn-ẖa֔yil bĕ̇⁠kál-ʻáré֥y yĕhẇdá֖h ha⁠bĕ̇ẕur֑wòţ wa⁠yi̇ţé֤̇n nĕẕiybiym֙ bĕ̇⁠ʼe֣reẕ yĕhẇdá֔h ẇ⁠bĕ⁠ʻáré֣y ʼepĕra֔yim ʼàşě֥r láka֖d ʼásá֥ʼ ʼábiֽy⁠w׃"],[17,3,"וַ⁠יְהִ֥י יְהוָ֖ה עִם־יְהוֹשָׁפָ֑ט כִּ֣י הָלַ֗ךְ בְּ⁠דַרְכֵ֞י דָּוִ֤יד אָבִי⁠ו֙ הָ⁠רִ֣אשֹׁנִ֔ים וְ⁠לֹ֥א דָרַ֖שׁ לַ⁠בְּעָלִֽים׃","wa⁠yĕhi֥y yĕhwá֖h ʻim-yĕhwòşá̌pá֑t ki֣̇y hála֗kĕ bĕ̇⁠darĕké֞y dá̇wi֤yd ʼábiy⁠w֙ há⁠ri֣ʼşò̌ni֔ym wĕ⁠lò֥ʼ dára֖ş̌ la⁠bĕ̇ʻáliֽym׃"],[17,4,"כִּ֠י לֵֽ⁠אלֹהֵ֤י אָבִי⁠ו֙ דָּרָ֔שׁ וּ⁠בְ⁠מִצְוֺתָ֖י⁠ו הָלָ֑ךְ וְ⁠לֹ֖א כְּ⁠מַעֲשֵׂ֥ה יִשְׂרָאֵֽל׃","ki̇֠y lֽé⁠ʼlòhé֤y ʼábiy⁠w֙ dá̇rá֔ş̌ ẇ⁠bĕ⁠miẕĕwֺţá֖y⁠w hálá֑kĕ wĕ⁠lò֖ʼ kĕ̇⁠maʻàşé֥̂h yişĕ̂ráʼéֽl׃"],[17,5,"וַ⁠יָּ֨כֶן יְהוָ֤ה אֶת־הַ⁠מַּמְלָכָה֙ בְּ⁠יָד֔⁠וֹ וַ⁠יִּתְּנ֧וּ כָל־יְהוּדָ֛ה מִנְחָ֖ה לִ⁠יהוֹשָׁפָ֑ט וַֽ⁠יְהִי־ל֥⁠וֹ עֹֽשֶׁר־וְ⁠כָב֖וֹד לָ⁠רֹֽב׃","wa⁠yá̇֨ken yĕhwá֤h ʼeţ-ha⁠mȧmĕlákáh֙ bĕ̇⁠yád֔⁠wò wa⁠yi̇ţĕ̇n֧ẇ kál-yĕhẇdá֛h minĕẖá֖h li⁠yhwòşá̌pá֑t waֽ⁠yĕhiy-l֥⁠wò ʻòֽşěr-wĕ⁠káb֖wòd lá⁠ròֽb׃"],[17,6,"וַ⁠יִּגְבַּ֥הּ לִבּ֖⁠וֹ בְּ⁠דַרְכֵ֣י יְהוָ֑ה וְ⁠ע֗וֹד הֵסִ֛יר אֶת־הַ⁠בָּמ֥וֹת וְ⁠אֶת־הָ⁠אֲשֵׁרִ֖ים מִ⁠יהוּדָֽה׃פ","wa⁠yi̇gĕbȧ֥ḣ liḃ֖⁠wò bĕ̇⁠darĕké֣y yĕhwá֑h wĕ⁠ʻ֗wòd hési֛yr ʼeţ-ha⁠bá̇m֥wòţ wĕ⁠ʼeţ-há⁠ʼàşé̌ri֖ym mi⁠yhẇdáֽh׃p"],[17,7,"וּ⁠בִ⁠שְׁנַ֨ת שָׁל֜וֹשׁ לְ⁠מָלְכ֗⁠וֹ שָׁלַ֤ח לְ⁠שָׂרָי⁠ו֙ לְ⁠בֶן־חַ֨יִל֙ וּ⁠לְ⁠עֹבַדְיָ֣ה וְ⁠לִ⁠זְכַרְיָ֔ה וְ⁠לִ⁠נְתַנְאֵ֖ל וּ⁠לְ⁠מִיכָיָ֑הוּ לְ⁠לַמֵּ֖ד בְּ⁠עָרֵ֥י יְהוּדָֽה׃","ẇ⁠bi⁠şĕ̌na֨ţ şá̌l֜wòş̌ lĕ⁠málĕk֗⁠wò şá̌la֤ẖ lĕ⁠şá̂ráy⁠w֙ lĕ⁠ben-ẖa֨yil֙ ẇ⁠lĕ⁠ʻòbadĕyá֣h wĕ⁠li⁠zĕkarĕyá֔h wĕ⁠li⁠nĕţanĕʼé֖l ẇ⁠lĕ⁠miykáyá֑hẇ lĕ⁠lamé֖̇d bĕ̇⁠ʻáré֥y yĕhẇdáֽh׃"],[17,8,"וְ⁠עִמָּ⁠הֶ֣ם הַ⁠לְוִיִּ֗ם שְֽׁמַֽעְיָ֡הוּ וּ⁠נְתַנְיָ֡הוּ וּ⁠זְבַדְיָ֡הוּ וַ⁠עֲשָׂהאֵ֡ל ו⁠שמרימות וִֽ⁠יהוֹנָתָן֩ וַ⁠אֲדֹ֨נִיָּ֧הוּ וְ⁠טֽוֹבִיָּ֛הוּ וְ⁠ט֥וֹב אֲדוֹנִיָּ֖ה הַ⁠לְוִיִּ֑ם וְ⁠עִמָּ⁠הֶ֛ם אֱלִישָׁמָ֥ע וִֽ⁠יהוֹרָ֖ם הַ⁠כֹּהֲנִֽים׃","wĕ⁠ʻimá̇⁠he֣m ha⁠lĕwiyi̇֗m şĕֽ̌maֽʻĕyá֡hẇ ẇ⁠nĕţanĕyá֡hẇ ẇ⁠zĕbadĕyá֡hẇ wa⁠ʻàşá̂hʼé֡l w⁠şmrymwţ wiֽ⁠yhwònáţán֩ wa⁠ʼàdò֨niyá֧̇hẇ wĕ⁠tֽwòbiyá֛̇hẇ wĕ⁠t֥wòb ʼàdwòniyá֖̇h ha⁠lĕwiyi֑̇m wĕ⁠ʻimá̇⁠he֛m ʼèliyşá̌má֥ʻ wiֽ⁠yhwòrá֖m ha⁠kò̇hàniֽym׃"],[17,9,"וַֽ⁠יְלַמְּדוּ֙ בִּֽ⁠יהוּדָ֔ה וְ⁠עִ֨מָּ⁠הֶ֔ם סֵ֖פֶר תּוֹרַ֣ת יְהוָ֑ה וַ⁠יָּסֹ֨בּוּ֙ בְּ⁠כָל־עָרֵ֣י יְהוּדָ֔ה וַֽ⁠יְלַמְּד֖וּ בָּ⁠עָֽם׃","waֽ⁠yĕlamĕ̇dẇ֙ biֽ̇⁠yhẇdá֔h wĕ⁠ʻi֨má̇⁠he֔m sé֖per ţ̇wòra֣ţ yĕhwá֑h wa⁠yá̇sò֨ḃẇ֙ bĕ̇⁠kál-ʻáré֣y yĕhẇdá֔h waֽ⁠yĕlamĕ̇d֖ẇ bá̇⁠ʻáֽm׃"],[17,10,"וַ⁠יְהִ֣י ׀ פַּ֣חַד יְהוָ֗ה עַ֚ל כָּל־מַמְלְכ֣וֹת הָֽ⁠אֲרָצ֔וֹת אֲשֶׁ֖ר סְבִיב֣וֹת יְהוּדָ֑ה וְ⁠לֹ֥א נִלְחֲמ֖וּ עִם־יְהוֹשָׁפָֽט׃","wa⁠yĕhi֣y ׀ pȧ֣ẖad yĕhwá֗h ʻa֚l ká̇l-mamĕlĕk֣wòţ hֽá⁠ʼàráẕ֔wòţ ʼàşě֖r sĕbiyb֣wòţ yĕhẇdá֑h wĕ⁠lò֥ʼ nilĕẖàm֖ẇ ʻim-yĕhwòşá̌páֽt׃"],[17,11,"וּ⁠מִן־פְּלִשְׁתִּ֗ים מְבִיאִ֧ים לִֽ⁠יהוֹשָׁפָ֛ט מִנְחָ֖ה וְ⁠כֶ֣סֶף מַשָּׂ֑א גַּ֣ם הָֽ⁠עַרְבִיאִ֗ים מְבִיאִ֥ים ל⁠וֹ֙ צֹ֕אן אֵילִ֔ים שִׁבְעַ֤ת אֲלָפִים֙ וּ⁠שְׁבַ֣ע מֵא֔וֹת וּ⁠תְיָשִׁ֕ים שִׁבְעַ֥ת אֲלָפִ֖ים וּ⁠שְׁבַ֥ע מֵאֽוֹת׃פ","ẇ⁠min-pĕ̇lişĕ̌ţi̇֗ym mĕbiyʼi֧ym liֽ⁠yhwòşá̌pá֛t minĕẖá֖h wĕ⁠ke֣sep maşá֑̇̂ʼ gȧ֣m háֽ⁠ʻarĕbiyʼi֗ym mĕbiyʼi֥ym l⁠wò֙ ẕò֕ʼn ʼéyli֔ym şǐbĕʻa֤ţ ʼàlápiym֙ ẇ⁠şĕ̌ba֣ʻ méʼ֔wòţ ẇ⁠ţĕyáşǐ֕ym şǐbĕʻa֥ţ ʼàlápi֖ym ẇ⁠şĕ̌ba֥ʻ méʼֽwòţ׃p"],[17,12,"וַ⁠יְהִ֧י יְהוֹשָׁפָ֛ט הֹלֵ֥ךְ וְ⁠גָדֵ֖ל עַד־לְ⁠מָ֑עְלָ⁠ה וַ⁠יִּ֧בֶן בִּֽ⁠יהוּדָ֛ה בִּירָנִיּ֖וֹת וְ⁠עָרֵ֥י מִסְכְּנֽוֹת׃","wa⁠yĕhi֧y yĕhwòşá̌pá֛t hòlé֥kĕ wĕ⁠gádé֖l ʻad-lĕ⁠má֑ʻĕlá⁠h wa⁠yi֧̇ben biֽ̇⁠yhẇdá֛h bi̇yrániẏ֖wòţ wĕ⁠ʻáré֥y misĕkĕ̇nֽwòţ׃"],[17,13,"וּ⁠מְלָאכָ֥ה רַבָּ֛ה הָ֥יָה ל֖⁠וֹ בְּ⁠עָרֵ֣י יְהוּדָ֑ה וְ⁠אַנְשֵׁ֧י מִלְחָמָ֛ה גִּבּ֥וֹרֵי חַ֖יִל בִּ⁠ירוּשָׁלִָֽם׃","ẇ⁠mĕláʼká֥h rabá֛̇h há֥yáh l֖⁠wò bĕ̇⁠ʻáré֣y yĕhẇdá֑h wĕ⁠ʼanĕşé֧̌y milĕẖámá֛h gi̇ḃ֥wòréy ẖa֖yil bi̇⁠yrẇşá̌liáֽm׃"],[17,14,"וְ⁠אֵ֥לֶּה פְקֻדָּתָ֖⁠ם לְ⁠בֵ֣ית אֲבוֹתֵי⁠הֶ֑ם לִֽ⁠יהוּדָה֙ שָׂרֵ֣י אֲלָפִ֔ים עַדְנָ֣ה הַ⁠שָּׂ֔ר וְ⁠עִמּ⁠וֹ֙ גִּבּ֣וֹרֵי חַ֔יִל שְׁלֹ֥שׁ מֵא֖וֹת אָֽלֶף׃ס","wĕ⁠ʼé֥lėh pĕqudá̇ţá֖⁠m lĕ⁠bé֣yţ ʼàbwòţéy⁠he֑m liֽ⁠yhẇdáh֙ şá̂ré֣y ʼàlápi֔ym ʻadĕná֣h ha⁠şá̇̂֔r wĕ⁠ʻiṁ⁠wò֙ gi̇ḃ֣wòréy ẖa֔yil şĕ̌lò֥ş̌ méʼ֖wòţ ʼáֽlep׃s"],[17,15,"וְ⁠עַל־יָד֖⁠וֹ יְהוֹחָנָ֣ן הַ⁠שָּׂ֑ר וְ⁠עִמּ֕⁠וֹ מָאתַ֥יִם וּ⁠שְׁמוֹנִ֖ים אָֽלֶף׃ס","wĕ⁠ʻal-yád֖⁠wò yĕhwòẖáná֣n ha⁠şá֑̇̂r wĕ⁠ʻiṁ֕⁠wò máʼţa֥yim ẇ⁠şĕ̌mwòni֖ym ʼáֽlep׃s"],[17,16,"וְ⁠עַל־יָד⁠וֹ֙ עֲמַסְיָ֣ה בֶן־זִכְרִ֔י הַ⁠מִּתְנַדֵּ֖ב לַ⁠יהוָ֑ה וְ⁠עִמּ֛⁠וֹ מָאתַ֥יִם אֶ֖לֶף גִּבּ֥וֹר חָֽיִל׃ס","wĕ⁠ʻal-yád⁠wò֙ ʻàmasĕyá֣h ben-zikĕri֔y ha⁠mi̇ţĕnadé֖̇b la⁠yhwá֑h wĕ⁠ʻiṁ֛⁠wò máʼţa֥yim ʼe֖lep gi̇ḃ֥wòr ẖáֽyil׃s"],[17,17,"וּ⁠מִ֨ן־בִּנְיָמִ֔ן גִּבּ֥וֹר חַ֖יִל אֶלְיָדָ֑ע וְ⁠עִמּ֛⁠וֹ נֹֽשְׁקֵי־קֶ֥שֶׁת וּ⁠מָגֵ֖ן מָאתַ֥יִם אָֽלֶף׃ס","ẇ⁠mi֨n-bi̇nĕyámi֔n gi̇ḃ֥wòr ẖa֖yil ʼelĕyádá֑ʻ wĕ⁠ʻiṁ֛⁠wò nòֽşĕ̌qéy-qe֥şěţ ẇ⁠mágé֖n máʼţa֥yim ʼáֽlep׃s"],[17,18,"וְ⁠עַל־יָד֖⁠וֹ יְהוֹזָבָ֑ד וְ⁠עִמּ֛⁠וֹ מֵאָֽה־וּ⁠שְׁמוֹנִ֥ים אֶ֖לֶף חֲלוּצֵ֥י צָבָֽא׃ס","wĕ⁠ʻal-yád֖⁠wò yĕhwòzábá֑d wĕ⁠ʻiṁ֛⁠wò méʼáֽh-ẇ⁠şĕ̌mwòni֥ym ʼe֖lep ẖàlẇẕé֥y ẕábáֽʼ׃s"],[17,19,"אֵ֖לֶּה הַ⁠מְשָׁרְתִ֣ים אֶת־הַ⁠מֶּ֑לֶךְ מִ⁠לְּ⁠בַ֞ד אֲשֶׁר־נָתַ֥ן הַ⁠מֶּ֛לֶךְ בְּ⁠עָרֵ֥י הַ⁠מִּבְצָ֖ר בְּ⁠כָל־יְהוּדָֽה׃פ","ʼé֖lėh ha⁠mĕşá̌rĕţi֣ym ʼeţ-ha⁠mė֑lekĕ mi⁠lĕ̇⁠ba֞d ʼàşěr-náţa֥n ha⁠mė֛lekĕ bĕ̇⁠ʻáré֥y ha⁠mi̇bĕẕá֖r bĕ̇⁠kál-yĕhẇdáֽh׃p"],[18,1,"וַ⁠יְהִ֧י לִֽ⁠יהוֹשָׁפָ֛ט עֹ֥שֶׁר וְ⁠כָב֖וֹד לָ⁠רֹ֑ב וַ⁠יִּתְחַתֵּ֖ן לְ⁠אַחְאָֽב׃","wa⁠yĕhi֧y liֽ⁠yhwòşá̌pá֛t ʻò֥şěr wĕ⁠káb֖wòd lá⁠rò֑b wa⁠yi̇ţĕẖaţé֖̇n lĕ⁠ʼaẖĕʼáֽb׃"],[18,2,"וַ⁠יֵּרֶד֩ לְ⁠קֵ֨ץ שָׁנִ֤ים אֶל־אַחְאָב֙ לְ⁠שֹׁ֣מְר֔וֹן וַ⁠יִּֽזְבַּֽח־ל֨⁠וֹ אַחְאָ֜ב צֹ֤אן וּ⁠בָקָר֙ לָ⁠רֹ֔ב וְ⁠לָ⁠עָ֖ם אֲשֶׁ֣ר עִמּ֑⁠וֹ וַ⁠יְסִיתֵ֕⁠הוּ לַ⁠עֲל֖וֹת אֶל־רָמ֥וֹת גִּלְעָֽד׃","wa⁠yé̇red֩ lĕ⁠qé֨ẕ şá̌ni֤ym ʼel-ʼaẖĕʼáb֙ lĕ⁠şò֣̌mĕr֔wòn wa⁠yiֽ̇zĕbȧֽẖ-l֨⁠wò ʼaẖĕʼá֜b ẕò֤ʼn ẇ⁠báqár֙ lá⁠rò֔b wĕ⁠lá⁠ʻá֖m ʼàşě֣r ʻiṁ֑⁠wò wa⁠yĕsiyţé֕⁠hẇ la⁠ʻàl֖wòţ ʼel-rám֥wòţ gi̇lĕʻáֽd׃"],[18,3,"וַ⁠יֹּ֜אמֶר אַחְאָ֣ב מֶֽלֶךְ־יִשְׂרָאֵ֗ל אֶל־יְהֽוֹשָׁפָט֙ מֶ֣לֶךְ יְהוּדָ֔ה הֲ⁠תֵלֵ֥ךְ עִמִּ֖⁠י רָמֹ֣ת גִּלְעָ֑ד וַ⁠יֹּ֣אמֶר ל֗⁠וֹ כָּמ֤וֹ⁠נִי כָמ֨וֹ⁠ךָ֙ וּ⁠כְ⁠עַמְּ⁠ךָ֣ עַמִּ֔⁠י וְ⁠עִמְּ⁠ךָ֖ בַּ⁠מִּלְחָמָֽה׃","wa⁠yò̇֜ʼmer ʼaẖĕʼá֣b meֽlekĕ-yişĕ̂ráʼé֗l ʼel-yĕhֽwòşá̌pát֙ me֣lekĕ yĕhẇdá֔h hà⁠ţélé֥kĕ ʻimi֖̇⁠y rámò֣ţ gi̇lĕʻá֑d wa⁠yò֣̇ʼmer l֗⁠wò ká̇m֤wò⁠niy kám֨wò⁠ká֙ ẇ⁠kĕ⁠ʻamĕ̇⁠ká֣ ʻami̇֔⁠y wĕ⁠ʻimĕ̇⁠ká֖ bȧ⁠mi̇lĕẖámáֽh׃"],[18,4,"וַ⁠יֹּ֥אמֶר יְהוֹשָׁפָ֖ט אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֑ל דְּרָשׁ־נָ֥א כַ⁠יּ֖וֹם אֶת־דְּבַ֥ר יְהוָֽה׃","wa⁠yò֥̇ʼmer yĕhwòşá̌pá֖t ʼel-me֣lekĕ yişĕ̂ráʼé֑l dĕ̇ráş̌-ná֥ʼ ka⁠ẏ֖wòm ʼeţ-dĕ̇ba֥r yĕhwáֽh׃"],[18,5,"וַ⁠יִּקְבֹּ֨ץ מֶֽלֶךְ־יִשְׂרָאֵ֥ל אֶֽת־הַ⁠נְּבִאִים֮ אַרְבַּ֣ע מֵא֣וֹת אִישׁ֒ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם הֲ⁠נֵלֵ֞ךְ אֶל־רָמֹ֥ת גִּלְעָ֛ד לַ⁠מִּלְחָמָ֖ה אִם־אֶחְדָּ֑ל וַ⁠יֹּאמְר֣וּ עֲלֵ֔ה וְ⁠יִתֵּ֥ן הָ⁠אֱלֹהִ֖ים בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇qĕbò̇֨ẕ meֽlekĕ-yişĕ̂ráʼé֥l ʼeֽţ-ha⁠nĕ̇biʼiym֮ ʼarĕbȧ֣ʻ méʼ֣wòţ ʼiyş̌֒ wa⁠yò֣̇ʼmer ʼàlé⁠he֗m hà⁠nélé֞kĕ ʼel-rámò֥ţ gi̇lĕʻá֛d la⁠mi̇lĕẖámá֖h ʼim-ʼeẖĕdá֑̇l wa⁠yò̇ʼmĕr֣ẇ ʻàlé֔h wĕ⁠yiţé֥̇n há⁠ʼèlòhi֖ym bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[18,6,"וַ⁠יֹּ֨אמֶר֙ יְה֣וֹשָׁפָ֔ט הַ⁠אֵ֨ין פֹּ֥ה נָבִ֛יא לַ⁠יהוָ֖ה ע֑וֹד וְ⁠נִדְרְשָׁ֖ה מֵ⁠אֹתֽ⁠וֹ׃","wa⁠yò̇֨ʼmer֙ yĕh֣wòşá̌pá֔t ha⁠ʼé֨yn pò֥̇h nábi֛yʼ la⁠yhwá֖h ʻ֑wòd wĕ⁠nidĕrĕşá֖̌h mé⁠ʼòţֽ⁠wò׃"],[18,7,"וַ⁠יֹּ֣אמֶר מֶֽלֶךְ־יִשְׂרָאֵ֣ל ׀ אֶֽל־יְהוֹשָׁפָ֡ט ע֣וֹד אִישׁ־אֶחָ֡ד לִ⁠דְרוֹשׁ֩ אֶת־יְהוָ֨ה מֵֽ⁠אֹת֜⁠וֹ וַ⁠אֲנִ֣י שְׂנֵאתִ֗י⁠הוּ כִּֽי־אֵ֠ינֶ⁠נּוּ מִתְנַבֵּ֨א עָלַ֤⁠י לְ⁠טוֹבָה֙ כִּ֣י כָל־יָמָ֣י⁠ו לְ⁠רָעָ֔ה ה֖וּא מִיכָ֣יְהוּ בֶן־יִמְלָ֑א וַ⁠יֹּ֨אמֶר֙ יְה֣וֹשָׁפָ֔ט אַל־יֹאמַ֥ר הַ⁠מֶּ֖לֶךְ כֵּֽן׃","wa⁠yò֣̇ʼmer meֽlekĕ-yişĕ̂ráʼé֣l ׀ ʼeֽl-yĕhwòşá̌pá֡t ʻ֣wòd ʼiyş̌-ʼeẖá֡d li⁠dĕrwòş̌֩ ʼeţ-yĕhwá֨h mֽé⁠ʼòţ֜⁠wò wa⁠ʼàni֣y şĕ̂néʼţi֗y⁠hẇ kiֽ̇y-ʼé֠yne⁠ṅẇ miţĕnabé̇֨ʼ ʻála֤⁠y lĕ⁠twòbáh֙ ki֣̇y kál-yámá֣y⁠w lĕ⁠ráʻá֔h h֖ẇʼ miyká֣yĕhẇ ben-yimĕlá֑ʼ wa⁠yò̇֨ʼmer֙ yĕh֣wòşá̌pá֔t ʼal-yòʼma֥r ha⁠mė֖lekĕ kéֽ̇n׃"],[18,8,"וַ⁠יִּקְרָא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אֶל־סָרִ֖יס אֶחָ֑ד וַ⁠יֹּ֕אמֶר מַהֵ֖ר מיכהו בֶן־יִמְלָֽא׃","wa⁠yi̇qĕráʼ֙ me֣lekĕ yişĕ̂ráʼé֔l ʼel-sári֖ys ʼeẖá֑d wa⁠yò̇֕ʼmer mahé֖r mykhw ben-yimĕláֽʼ׃"],[18,9,"וּ⁠מֶ֣לֶךְ יִשְׂרָאֵ֡ל וִֽ⁠יהוֹשָׁפָ֣ט מֶֽלֶךְ־יְהוּדָ֡ה יוֹשְׁבִים֩ אִ֨ישׁ עַל־כִּסְא֜⁠וֹ מְלֻבָּשִׁ֤ים בְּגָדִים֙ וְ⁠יֹשְׁבִ֣ים בְּ⁠גֹ֔רֶן פֶּ֖תַח שַׁ֣עַר שֹׁמְר֑וֹן וְ⁠כָל־הַ֨⁠נְּבִיאִ֔ים מִֽתְנַבְּאִ֖ים לִ⁠פְנֵי⁠הֶֽם׃","ẇ⁠me֣lekĕ yişĕ̂ráʼé֡l wiֽ⁠yhwòşá̌pá֣t meֽlekĕ-yĕhẇdá֡h ywòşĕ̌biym֩ ʼi֨yş̌ ʻal-ki̇sĕʼ֜⁠wò mĕlubá̇şǐ֤ym bĕ̇gádiym֙ wĕ⁠yòşĕ̌bi֣ym bĕ̇⁠gò֔ren pė֖ţaẖ şǎ֣ʻar şò̌mĕr֑wòn wĕ⁠kál-ha֨⁠nĕ̇biyʼi֔ym miֽţĕnabĕ̇ʼi֖ym li⁠pĕnéy⁠heֽm׃"],[18,10,"וַ⁠יַּ֥עַשׂ ל֛⁠וֹ צִדְקִיָּ֥הוּ בֶֽן־כְּנַעֲנָ֖ה קַרְנֵ֣י בַרְזֶ֑ל וַ⁠יֹּ֨אמֶר֙ כֹּֽה־אָמַ֣ר יְהוָ֔ה בְּ⁠אֵ֛לֶּה תְּנַגַּ֥ח אֶת־אֲרָ֖ם עַד־כַּלּוֹתָֽ⁠ם׃","wa⁠yȧ֥ʻaş̂ l֛⁠wò ẕidĕqiyá֥̇hẇ beֽn-kĕ̇naʻàná֖h qarĕné֣y barĕze֑l wa⁠yò̇֨ʼmer֙ kòֽ̇h-ʼáma֣r yĕhwá֔h bĕ̇⁠ʼé֛lėh ţĕ̇nagȧ֥ẖ ʼeţ-ʼàrá֖m ʻad-kȧl̇wòţáֽ⁠m׃"],[18,11,"וְ⁠כָל־הַ֨⁠נְּבִאִ֔ים נִבְּאִ֥ים כֵּ֖ן לֵ⁠אמֹ֑ר עֲלֵ֞ה רָמֹ֤ת גִּלְעָד֙ וְ⁠הַצְלַ֔ח וְ⁠נָתַ֥ן יְהוָ֖ה בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wĕ⁠kál-ha֨⁠nĕ̇biʼi֔ym nibĕ̇ʼi֥ym ké֖̇n lé⁠ʼmò֑r ʻàlé֞h rámò֤ţ gi̇lĕʻád֙ wĕ⁠haẕĕla֔ẖ wĕ⁠náţa֥n yĕhwá֖h bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[18,12,"וְ⁠הַ⁠מַּלְאָ֞ךְ אֲשֶׁר־הָלַ֣ךְ ׀ לִ⁠קְרֹ֣א לְ⁠מִיכָ֗יְהוּ דִּבֶּ֤ר אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר הִנֵּ֞ה דִּבְרֵ֧י הַ⁠נְּבִאִ֛ים פֶּֽה־אֶחָ֥ד ט֖וֹב אֶל־הַ⁠מֶּ֑לֶךְ וִֽ⁠יהִי־נָ֧א דְבָרְ⁠ךָ֛ כְּ⁠אַחַ֥ד מֵ⁠הֶ֖ם וְ⁠דִבַּ֥רְתָּ טּֽוֹב׃","wĕ⁠ha⁠mȧlĕʼá֞kĕ ʼàşěr-hála֣kĕ ׀ li⁠qĕrò֣ʼ lĕ⁠miyká֗yĕhẇ di̇bė֤r ʼéláy⁠w֙ lé⁠ʼmò֔r hiné̇֞h di̇bĕré֧y ha⁠nĕ̇biʼi֛ym pėֽh-ʼeẖá֥d t֖wòb ʼel-ha⁠mė֑lekĕ wiֽ⁠yhiy-ná֧ʼ dĕbárĕ⁠ká֛ kĕ̇⁠ʼaẖa֥d mé⁠he֖m wĕ⁠dibȧ֥rĕţá̇ ṫֽwòb׃"],[18,13,"וַ⁠יֹּ֖אמֶר מִיכָ֑יְהוּ חַי־יְהוָ֕ה כִּ֛י אֶת־אֲשֶׁר־יֹאמַ֥ר אֱלֹהַ֖⁠י אֹת֥⁠וֹ אֲדַבֵּֽר׃","wa⁠yò֖̇ʼmer miyká֑yĕhẇ ẖay-yĕhwá֕h ki֛̇y ʼeţ-ʼàşěr-yòʼma֥r ʼèlòha֖⁠y ʼòţ֥⁠wò ʼàdabéֽ̇r׃"],[18,14,"וַ⁠יָּבֹא֮ אֶל־הַ⁠מֶּלֶךְ֒ וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ אֵלָ֗י⁠ו מִיכָה֙ הֲ⁠נֵלֵ֞ךְ אֶל־רָמֹ֥ת גִּלְעָ֛ד לַ⁠מִּלְחָמָ֖ה אִם־אֶחְדָּ֑ל וַ⁠יֹּ֨אמֶר֙ עֲל֣וּ וְ⁠הַצְלִ֔יחוּ וְ⁠יִנָּתְנ֖וּ בְּ⁠יֶדְ⁠כֶֽם׃","wa⁠yá̇bòʼ֮ ʼel-ha⁠mėlekĕ֒ wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ ʼélá֗y⁠w miykáh֙ hà⁠nélé֞kĕ ʼel-rámò֥ţ gi̇lĕʻá֛d la⁠mi̇lĕẖámá֖h ʼim-ʼeẖĕdá֑̇l wa⁠yò̇֨ʼmer֙ ʻàl֣ẇ wĕ⁠haẕĕli֔yẖẇ wĕ⁠yiná̇ţĕn֖ẇ bĕ̇⁠yedĕ⁠keֽm׃"],[18,15,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ הַ⁠מֶּ֔לֶךְ עַד־כַּ⁠מֶּ֥ה פְעָמִ֖ים אֲנִ֣י מַשְׁבִּיעֶ֑⁠ךָ אֲ֠שֶׁר לֹֽא־תְדַבֵּ֥ר אֵלַ֛⁠י רַק־אֱמֶ֖ת בְּ⁠שֵׁ֥ם יְהוָֽה׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ha⁠mė֔lekĕ ʻad-kȧ⁠mė֥h pĕʻámi֖ym ʼàni֣y maşĕ̌bi̇yʻe֑⁠ká ʼà֠şěr lòֽʼ-ţĕdabé֥̇r ʼéla֛⁠y raq-ʼème֖ţ bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[18,16,"וַ⁠יֹּ֗אמֶר רָאִ֤יתִי אֶת־כָּל־יִשְׂרָאֵל֙ נְפוֹצִ֣ים עַל־הֶֽ⁠הָרִ֔ים כַּ⁠צֹּ֕אן אֲשֶׁ֥ר אֵין־לָ⁠הֶ֖ן רֹעֶ֑ה וַ⁠יֹּ֤אמֶר יְהוָה֙ לֹֽא־אֲדֹנִ֣ים לָ⁠אֵ֔לֶּה יָשׁ֥וּבוּ אִישׁ־לְ⁠בֵית֖⁠וֹ בְּ⁠שָׁלֽוֹם׃","wa⁠yò̇֗ʼmer ráʼi֤yţiy ʼeţ-ká̇l-yişĕ̂ráʼél֙ nĕpwòẕi֣ym ʻal-heֽ⁠hári֔ym kȧ⁠ẕò̇֕ʼn ʼàşě֥r ʼéyn-lá⁠he֖n ròʻe֑h wa⁠yò֤̇ʼmer yĕhwáh֙ lòֽʼ-ʼàdòni֣ym lá⁠ʼé֔lėh yáş֥̌ẇbẇ ʼiyş̌-lĕ⁠béyţ֖⁠wò bĕ̇⁠şá̌lֽwòm׃"],[18,17,"וַ⁠יֹּ֥אמֶר מֶֽלֶךְ־יִשְׂרָאֵ֖ל אֶל־יְהוֹשָׁפָ֑ט הֲ⁠לֹא֙ אָמַ֣רְתִּי אֵלֶ֔י⁠ךָ לֹא־יִתְנַבֵּ֥א עָלַ֛⁠י ט֖וֹב כִּ֥י אִם־לְ⁠רָֽע׃ס","wa⁠yò֥̇ʼmer meֽlekĕ-yişĕ̂ráʼé֖l ʼel-yĕhwòşá̌pá֑t hà⁠lòʼ֙ ʼáma֣rĕţi̇y ʼéle֔y⁠ká lòʼ-yiţĕnabé֥̇ʼ ʻála֛⁠y t֖wòb ki֥̇y ʼim-lĕ⁠ráֽʻ׃s"],[18,18,"וַ⁠יֹּ֕אמֶר לָ⁠כֵ֖ן שִׁמְע֣וּ דְבַר־יְהוָ֑ה רָאִ֤יתִי אֶת־יְהוָה֙ יוֹשֵׁ֣ב עַל־כִּסְא֔⁠וֹ וְ⁠כָל־צְבָ֤א הַ⁠שָּׁמַ֨יִם֙ עֹֽמְדִ֔ים עַל־יְמִינ֖⁠וֹ וּ⁠שְׂמֹאלֽ⁠וֹ׃","wa⁠yò̇֕ʼmer lá⁠ké֖n şǐmĕʻ֣ẇ dĕbar-yĕhwá֑h ráʼi֤yţiy ʼeţ-yĕhwáh֙ ywòşé֣̌b ʻal-ki̇sĕʼ֔⁠wò wĕ⁠kál-ẕĕbá֤ʼ ha⁠şá̇̌ma֨yim֙ ʻòֽmĕdi֔ym ʻal-yĕmiyn֖⁠wò ẇ⁠şĕ̂mòʼlֽ⁠wò׃"],[18,19,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה מִ֤י יְפַתֶּה֙ אֶת־אַחְאָ֣ב מֶֽלֶךְ־יִשְׂרָאֵ֔ל וְ⁠יַ֕עַל וְ⁠יִפֹּ֖ל בְּ⁠רָמ֣וֹת גִּלְעָ֑ד וַ⁠יֹּ֕אמֶר זֶ֚ה אֹמֵ֣ר כָּ֔כָה וְ⁠זֶ֖ה אֹמֵ֥ר כָּֽכָה׃","wa⁠yò֣̇ʼmer yĕhwá֗h mi֤y yĕpaţėh֙ ʼeţ-ʼaẖĕʼá֣b meֽlekĕ-yişĕ̂ráʼé֔l wĕ⁠ya֕ʻal wĕ⁠yipò֖̇l bĕ̇⁠rám֣wòţ gi̇lĕʻá֑d wa⁠yò̇֕ʼmer ze֚h ʼòmé֣r ká̇֔káh wĕ⁠ze֖h ʼòmé֥r káֽ̇káh׃"],[18,20,"וַ⁠יֵּצֵ֣א הָ⁠ר֗וּחַ וַֽ⁠יַּעֲמֹד֙ לִ⁠פְנֵ֣י יְהוָ֔ה וַ⁠יֹּ֖אמֶר אֲנִ֣י אֲפַתֶּ֑⁠נּוּ וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֵלָ֖י⁠ו בַּ⁠מָּֽה׃","wa⁠yé̇ẕé֣ʼ há⁠r֗ẇẖa waֽ⁠yȧʻàmòd֙ li⁠pĕné֣y yĕhwá֔h wa⁠yò֖̇ʼmer ʼàni֣y ʼàpaţė֑⁠ṅẇ wa⁠yò֧̇ʼmer yĕhwá֛h ʼélá֖y⁠w bȧ⁠máֽ̇h׃"],[18,21,"וַ⁠יֹּ֗אמֶר אֵצֵא֙ וְ⁠הָיִ֨יתִי֙ לְ⁠ר֣וּחַ שֶׁ֔קֶר בְּ⁠פִ֖י כָּל־נְבִיאָ֑י⁠ו וַ⁠יֹּ֗אמֶר תְּפַתֶּה֙ וְ⁠גַם־תּוּכָ֔ל צֵ֖א וַ⁠עֲשֵׂה־כֵֽן׃","wa⁠yò̇֗ʼmer ʼéẕéʼ֙ wĕ⁠háyi֨yţiy֙ lĕ⁠r֣ẇẖa şě֔qer bĕ̇⁠pi֖y ká̇l-nĕbiyʼá֑y⁠w wa⁠yò̇֗ʼmer ţĕ̇paţėh֙ wĕ⁠gam-ţ̇ẇká֔l ẕé֖ʼ wa⁠ʻàşé̂h-kéֽn׃"],[18,22,"וְ⁠עַתָּ֗ה הִנֵּ֨ה נָתַ֤ן יְהוָה֙ ר֣וּחַ שֶׁ֔קֶר בְּ⁠פִ֖י נְבִיאֶ֣י⁠ךָ אֵ֑לֶּה וַֽ⁠יהוָ֔ה דִּבֶּ֥ר עָלֶ֖י⁠ךָ רָעָֽה׃ס","wĕ⁠ʻaţá̇֗h hiné̇֨h náţa֤n yĕhwáh֙ r֣ẇẖa şě֔qer bĕ̇⁠pi֖y nĕbiyʼe֣y⁠ká ʼé֑lėh waֽ⁠yhwá֔h di̇bė֥r ʻále֖y⁠ká ráʻáֽh׃s"],[18,23,"וַ⁠יִּגַּשׁ֙ צִדְקִיָּ֣הוּ בֶֽן־כְּנַעֲנָ֔ה וַ⁠יַּ֥ךְ אֶת־מִיכָ֖יְהוּ עַל־הַ⁠לֶּ֑חִי וַ⁠יֹּ֗אמֶר אֵ֣י זֶ֤ה הַ⁠דֶּ֨רֶךְ֙ עָבַ֧ר רֽוּחַ־יְהוָ֛ה מֵ⁠אִתִּ֖⁠י לְ⁠דַבֵּ֥ר אֹתָֽ⁠ךְ׃","wa⁠yi̇gȧş̌֙ ẕidĕqiyá֣̇hẇ beֽn-kĕ̇naʻàná֔h wa⁠yȧ֥kĕ ʼeţ-miyká֖yĕhẇ ʻal-ha⁠lė֑ẖiy wa⁠yò̇֗ʼmer ʼé֣y ze֤h ha⁠dė֨rekĕ֙ ʻába֧r rֽẇẖa-yĕhwá֛h mé⁠ʼiţi֖̇⁠y lĕ⁠dabé֥̇r ʼòţáֽ⁠kĕ׃"],[18,24,"וַ⁠יֹּ֣אמֶר מִיכָ֔יְהוּ הִנְּ⁠ךָ֥ רֹאֶ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֲשֶׁ֥ר תָּב֛וֹא חֶ֥דֶר בְּ⁠חֶ֖דֶר לְ⁠הֵחָבֵֽא׃","wa⁠yò֣̇ʼmer miyká֔yĕhẇ hinĕ̇⁠ká֥ ròʼe֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼàşě֥r ţá̇b֛wòʼ ẖe֥der bĕ̇⁠ẖe֖der lĕ⁠héẖábéֽʼ׃"],[18,25,"וַ⁠יֹּ֨אמֶר֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל קְחוּ֙ אֶת־מִיכָ֔יְהוּ וַ⁠הֲשִׁיבֻ֖⁠הוּ אֶל־אָמ֣וֹן שַׂר־הָ⁠עִ֑יר וְ⁠אֶל־יוֹאָ֖שׁ בֶּן־הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmer֙ me֣lekĕ yişĕ̂ráʼé֔l qĕẖẇ֙ ʼeţ-miyká֔yĕhẇ wa⁠hàşǐybu֖⁠hẇ ʼel-ʼám֣wòn şâr-há⁠ʻi֑yr wĕ⁠ʼel-ywòʼá֖ş̌ bėn-ha⁠mėֽlekĕ׃"],[18,26,"וַ⁠אֲמַרְתֶּ֗ם כֹּ֚ה אָמַ֣ר הַ⁠מֶּ֔לֶךְ שִׂ֥ימוּ זֶ֖ה בֵּ֣ית הַ⁠כֶּ֑לֶא וְ⁠הַאֲכִלֻ֜⁠הוּ לֶ֤חֶם לַ֨חַץ֙ וּ⁠מַ֣יִם לַ֔חַץ עַ֖ד שׁוּבִ֥⁠י בְ⁠שָׁלֽוֹם׃","wa⁠ʼàmarĕţė֗m kò֚̇h ʼáma֣r ha⁠mė֔lekĕ şî֥ymẇ ze֖h bé֣̇yţ ha⁠kė֑leʼ wĕ⁠haʼàkilu֜⁠hẇ le֤ẖem la֨ẖaẕ֙ ẇ⁠ma֣yim la֔ẖaẕ ʻa֖d ş̌ẇbi֥⁠y bĕ⁠şá̌lֽwòm׃"],[18,27,"וַ⁠יֹּ֣אמֶר מִיכָ֔יְהוּ אִם־שׁ֤וֹב תָּשׁוּב֙ בְּ⁠שָׁל֔וֹם לֹא־דִבֶּ֥ר יְהוָ֖ה בִּ֑⁠י וַ⁠יֹּ֕אמֶר שִׁמְע֖וּ עַמִּ֥ים כֻּלָּֽ⁠ם׃פ","wa⁠yò֣̇ʼmer miyká֔yĕhẇ ʼim-ş֤̌wòb ţá̇ş̌ẇb֙ bĕ̇⁠şá̌l֔wòm lòʼ-dibė֥r yĕhwá֖h bi֑̇⁠y wa⁠yò̇֕ʼmer şǐmĕʻ֖ẇ ʻami֥̇ym ku̇láֽ̇⁠m׃p"],[18,28,"וַ⁠יַּ֧עַל מֶֽלֶךְ־יִשְׂרָאֵ֛ל וִֽ⁠יהוֹשָׁפָ֥ט מֶֽלֶךְ־יְהוּדָ֖ה אֶל־רָמֹ֥ת גִּלְעָֽד׃","wa⁠yȧ֧ʻal meֽlekĕ-yişĕ̂ráʼé֛l wiֽ⁠yhwòşá̌pá֥t meֽlekĕ-yĕhẇdá֖h ʼel-rámò֥ţ gi̇lĕʻáֽd׃"],[18,29,"וַ⁠יֹּאמֶר֩ מֶ֨לֶךְ יִשְׂרָאֵ֜ל אֶל־יְהוֹשָׁפָ֗ט הִתְחַפֵּשׂ֙ וָ⁠ב֣וֹא בַ⁠מִּלְחָמָ֔ה וְ⁠אַתָּ֖ה לְבַ֣שׁ בְּגָדֶ֑י⁠ךָ וַ⁠יִּתְחַפֵּשׂ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יָּבֹ֖אוּ בַּ⁠מִּלְחָמָֽה׃","wa⁠yò̇ʼmer֩ me֨lekĕ yişĕ̂ráʼé֜l ʼel-yĕhwòşá̌pá֗t hiţĕẖapé̇ş̂֙ wá⁠b֣wòʼ ba⁠mi̇lĕẖámá֔h wĕ⁠ʼaţá֖̇h lĕba֣ş̌ bĕ̇gáde֑y⁠ká wa⁠yi̇ţĕẖapé̇ş̂֙ me֣lekĕ yişĕ̂ráʼé֔l wa⁠yá̇bò֖ʼẇ bȧ⁠mi̇lĕẖámáֽh׃"],[18,30,"וּ⁠מֶ֣לֶךְ אֲרָ֡ם צִוָּה֩ אֶת־שָׂרֵ֨י הָ⁠רֶ֤כֶב אֲשֶׁר־ל⁠וֹ֙ לֵ⁠אמֹ֔ר לֹ֚א תִּלָּ֣חֲמ֔וּ אֶת־הַ⁠קָּטֹ֖ן אֶת־הַ⁠גָּד֑וֹל כִּ֛י אִֽם־אֶת־מֶ֥לֶךְ יִשְׂרָאֵ֖ל לְ⁠בַדּֽ⁠וֹ׃","ẇ⁠me֣lekĕ ʼàrá֡m ẕiwá̇h֩ ʼeţ-şá̂ré֨y há⁠re֤keb ʼàşěr-l⁠wò֙ lé⁠ʼmò֔r lò֚ʼ ţi̇lá֣̇ẖàm֔ẇ ʼeţ-ha⁠qá̇tò֖n ʼeţ-ha⁠gá̇d֑wòl ki֛̇y ʼiֽm-ʼeţ-me֥lekĕ yişĕ̂ráʼé֖l lĕ⁠baḋֽ⁠wò׃"],[18,31,"וַ⁠יְהִ֡י כִּ⁠רְאוֹת֩ שָׂרֵ֨י הָ⁠רֶ֜כֶב אֶת־יְהוֹשָׁפָ֗ט וְ⁠הֵ֤מָּה אָֽמְרוּ֙ מֶ֣לֶךְ יִשְׂרָאֵ֣ל ה֔וּא וַ⁠יָּסֹ֥בּוּ עָלָ֖י⁠ו לְ⁠הִלָּחֵ֑ם וַ⁠יִּזְעַ֤ק יְהֽוֹשָׁפָט֙ וַֽ⁠יהוָ֣ה עֲזָר֔⁠וֹ וַ⁠יְסִיתֵ֥⁠ם אֱלֹהִ֖ים מִמֶּֽ⁠נּוּ׃","wa⁠yĕhi֡y ki̇⁠rĕʼwòţ֩ şá̂ré֨y há⁠re֜keb ʼeţ-yĕhwòşá̌pá֗t wĕ⁠hé֤má̇h ʼáֽmĕrẇ֙ me֣lekĕ yişĕ̂ráʼé֣l h֔ẇʼ wa⁠yá̇sò֥ḃẇ ʻálá֖y⁠w lĕ⁠hilá̇ẖé֑m wa⁠yi̇zĕʻa֤q yĕhֽwòşá̌pát֙ waֽ⁠yhwá֣h ʻàzár֔⁠wò wa⁠yĕsiyţé֥⁠m ʼèlòhi֖ym mimėֽ⁠ṅẇ׃"],[18,32,"וַ⁠יְהִ֗י כִּ⁠רְאוֹת֙ שָׂרֵ֣י הָ⁠רֶ֔כֶב כִּ֥י לֹא־הָיָ֖ה מֶ֣לֶךְ יִשְׂרָאֵ֑ל וַ⁠יָּשֻׁ֖בוּ מֵ⁠אַחֲרָֽי⁠ו׃","wa⁠yĕhi֗y ki̇⁠rĕʼwòţ֙ şá̂ré֣y há⁠re֔keb ki֥̇y lòʼ-háyá֖h me֣lekĕ yişĕ̂ráʼé֑l wa⁠yá̇şǔ֖bẇ mé⁠ʼaẖàráֽy⁠w׃"],[18,33,"וְ⁠אִ֗ישׁ מָשַׁ֤ךְ בַּ⁠קֶּ֨שֶׁת֙ לְ⁠תֻמּ֔⁠וֹ וַ⁠יַּךְ֙ אֶת־מֶ֣לֶךְ יִשְׂרָאֵ֔ל בֵּ֥ין הַ⁠דְּבָקִ֖ים וּ⁠בֵ֣ין הַ⁠שִּׁרְיָ֑ן וַ⁠יֹּ֣אמֶר לָֽ⁠רַכָּ֗ב הֲפֹ֧ךְ ידי⁠ך וְ⁠הוֹצֵאתַ֥⁠נִי מִן־הַֽ⁠מַּחֲנֶ֖ה כִּ֥י הָחֳלֵֽיתִי׃","wĕ⁠ʼi֗yş̌ máşǎ֤kĕ bȧ⁠qė֨şěţ֙ lĕ⁠ţuṁ֔⁠wò wa⁠yȧkĕ֙ ʼeţ-me֣lekĕ yişĕ̂ráʼé֔l bé֥̇yn ha⁠dĕ̇báqi֖ym ẇ⁠bé֣yn ha⁠şi̇̌rĕyá֑n wa⁠yò֣̇ʼmer láֽ⁠raká̇֗b hàpò֧kĕ ydy⁠k wĕ⁠hwòẕéʼţa֥⁠niy min-haֽ⁠mȧẖàne֖h ki֥̇y háẖoléֽyţiy׃"],[18,34,"וַ⁠תַּ֤עַל הַ⁠מִּלְחָמָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וּ⁠מֶ֣לֶךְ יִשְׂרָאֵ֗ל הָיָ֨ה מַעֲמִ֧יד בַּ⁠מֶּרְכָּבָ֛ה נֹ֥כַח אֲרָ֖ם עַד־הָ⁠עָ֑רֶב וַ⁠יָּ֕מָת לְ⁠עֵ֖ת בּ֥וֹא הַ⁠שָּֽׁמֶשׁ׃","wa⁠ţȧ֤ʻal ha⁠mi̇lĕẖámáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ẇ⁠me֣lekĕ yişĕ̂ráʼé֗l háyá֨h maʻàmi֧yd bȧ⁠mėrĕká̇bá֛h nò֥kaẖ ʼàrá֖m ʻad-há⁠ʻá֑reb wa⁠yá̇֕máţ lĕ⁠ʻé֖ţ ḃ֥wòʼ ha⁠şáֽ̇̌meş̌׃"],[19,1,"וַ֠⁠יָּשָׁב יְהוֹשָׁפָ֨ט מֶֽלֶךְ־יְהוּדָ֧ה אֶל־בֵּית֛⁠וֹ בְּ⁠שָׁל֖וֹם לִֽ⁠ירוּשָׁלִָֽם׃","wa֠⁠yá̇şá̌b yĕhwòşá̌pá֨t meֽlekĕ-yĕhẇdá֧h ʼel-bé̇yţ֛⁠wò bĕ̇⁠şá̌l֖wòm liֽ⁠yrẇşá̌liáֽm׃"],[19,2,"וַ⁠יֵּצֵ֣א אֶל־פָּנָ֗י⁠ו יֵה֣וּא בֶן־חֲנָ֘נִי֮ הַ⁠חֹזֶה֒ וַ⁠יֹּ֨אמֶר֙ אֶל־הַ⁠מֶּ֣לֶךְ יְהוֹשָׁפָ֔ט הֲ⁠לָ⁠רָשָׁ֣ע לַ⁠עְזֹ֔ר וּ⁠לְ⁠שֹׂנְאֵ֥י יְהוָ֖ה תֶּאֱהָ֑ב וּ⁠בָ⁠זֹאת֙ עָלֶ֣י⁠ךָ קֶּ֔צֶף מִ⁠לִּ⁠פְנֵ֖י יְהוָֽה׃","wa⁠yé̇ẕé֣ʼ ʼel-pá̇ná֗y⁠w yéh֣ẇʼ ben-ẖàná֘niy֮ ha⁠ẖòzeh֒ wa⁠yò̇֨ʼmer֙ ʼel-ha⁠mė֣lekĕ yĕhwòşá̌pá֔t hà⁠lá⁠ráşá֣̌ʻ la⁠ʻĕzò֔r ẇ⁠lĕ⁠şò̂nĕʼé֥y yĕhwá֖h ţėʼèhá֑b ẇ⁠bá⁠zòʼţ֙ ʻále֣y⁠ká qė֔ẕep mi⁠li̇⁠pĕné֖y yĕhwáֽh׃"],[19,3,"אֲבָ֕ל דְּבָרִ֥ים טוֹבִ֖ים נִמְצְא֣וּ עִמָּ֑⁠ךְ כִּֽי־בִעַ֤רְתָּ הָ⁠אֲשֵׁרוֹת֙ מִן־הָ⁠אָ֔רֶץ וַ⁠הֲכִינ֥וֹתָ לְבָבְ⁠ךָ֖ לִ⁠דְרֹ֥שׁ הָֽ⁠אֱלֹהִֽים׃","ʼàbá֕l dĕ̇bári֥ym twòbi֖ym nimĕẕĕʼ֣ẇ ʻimá֑̇⁠kĕ kiֽ̇y-biʻa֤rĕţá̇ há⁠ʼàşé̌rwòţ֙ min-há⁠ʼá֔reẕ wa⁠hàkiyn֥wòţá lĕbábĕ⁠ká֖ li⁠dĕrò֥ş̌ háֽ⁠ʼèlòhiֽym׃"],[19,4,"וַ⁠יֵּ֥שֶׁב יְהוֹשָׁפָ֖ט בִּ⁠ירוּשָׁלִָ֑ם ס וַ⁠יָּ֜שָׁב וַ⁠יֵּצֵ֣א בָ⁠עָ֗ם מִ⁠בְּאֵ֥ר שֶׁ֨בַע֙ עַד־הַ֣ר אֶפְרַ֔יִם וַ⁠יְשִׁיבֵ֕⁠ם אֶל־יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃","wa⁠yé֥̇şěb yĕhwòşá̌pá֖t bi̇⁠yrẇşá̌liá֑m s wa⁠yá̇֜şá̌b wa⁠yé̇ẕé֣ʼ bá⁠ʻá֗m mi⁠bĕ̇ʼé֥r şě֨baʻ֙ ʻad-ha֣r ʼepĕra֔yim wa⁠yĕşǐybé֕⁠m ʼel-yĕhwá֖h ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃"],[19,5,"וַ⁠יַּעֲמֵ֨ד שֹֽׁפְטִ֜ים בָּ⁠אָ֗רֶץ בְּ⁠כָל־עָרֵ֧י יְהוּדָ֛ה הַ⁠בְּצֻר֖וֹת לְ⁠עִ֥יר וָ⁠עִֽיר׃","wa⁠yȧʻàmé֨d şòֽ̌pĕti֜ym bá̇⁠ʼá֗reẕ bĕ̇⁠kál-ʻáré֧y yĕhẇdá֛h ha⁠bĕ̇ẕur֖wòţ lĕ⁠ʻi֥yr wá⁠ʻiֽyr׃"],[19,6,"וַ⁠יֹּ֣אמֶר אֶל־הַ⁠שֹּֽׁפְטִ֗ים רְאוּ֙ מָֽה־אַתֶּ֣ם עֹשִׂ֔ים כִּ֣י לֹ֧א לְ⁠אָדָ֛ם תִּשְׁפְּט֖וּ כִּ֣י לַ⁠יהוָ֑ה וְ⁠עִמָּ⁠כֶ֖ם בִּ⁠דְבַ֥ר מִשְׁפָּֽט׃","wa⁠yò֣̇ʼmer ʼel-ha⁠şòֽ̇̌pĕti֗ym rĕʼẇ֙ máֽh-ʼaţė֣m ʻòşî֔ym ki֣̇y lò֧ʼ lĕ⁠ʼádá֛m ţi̇şĕ̌pĕ̇t֖ẇ ki֣̇y la⁠yhwá֑h wĕ⁠ʻimá̇⁠ke֖m bi̇⁠dĕba֥r mişĕ̌páֽ̇t׃"],[19,7,"וְ⁠עַתָּ֕ה יְהִ֥י פַֽחַד־יְהוָ֖ה עֲלֵי⁠כֶ֑ם שִׁמְר֣וּ וַ⁠עֲשׂ֔וּ כִּֽי־אֵ֞ין עִם־יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ עַוְלָ֛ה וּ⁠מַשֹּׂ֥א פָנִ֖ים וּ⁠מִקַּח־שֹֽׁחַד׃","wĕ⁠ʻaţá̇֕h yĕhi֥y paֽẖad-yĕhwá֖h ʻàléy⁠ke֑m şǐmĕr֣ẇ wa⁠ʻàş̂֔ẇ kiֽ̇y-ʼé֞yn ʻim-yĕhwá֣h ʼèlòhé֗y⁠nẇ ʻawĕlá֛h ẇ⁠maşò֥̇̂ʼ páni֖ym ẇ⁠miqȧẖ-şòֽ̌ẖad׃"],[19,8,"וְ⁠גַ֣ם בִּ֠⁠ירוּשָׁלִַם הֶעֱמִ֨יד יְהוֹשָׁפָ֜ט מִן־הַ⁠לְוִיִּ֣ם וְ⁠הַ⁠כֹּהֲנִ֗ים וּ⁠מֵ⁠רָאשֵׁ֤י הָ⁠אָבוֹת֙ לְ⁠יִשְׂרָאֵ֔ל לְ⁠מִשְׁפַּ֥ט יְהוָ֖ה וְ⁠לָ⁠רִ֑יב וַ⁠יָּשֻׁ֖בוּ יְרוּשָׁלִָֽם׃","wĕ⁠ga֣m bi̇֠⁠yrẇşá̌liam heʻèmi֨yd yĕhwòşá̌pá֜t min-ha⁠lĕwiyi֣̇m wĕ⁠ha⁠kò̇hàni֗ym ẇ⁠mé⁠ráʼşé֤̌y há⁠ʼábwòţ֙ lĕ⁠yişĕ̂ráʼé֔l lĕ⁠mişĕ̌pȧ֥t yĕhwá֖h wĕ⁠lá⁠ri֑yb wa⁠yá̇şǔ֖bẇ yĕrẇşá̌liáֽm׃"],[19,9,"וַ⁠יְצַ֥ו עֲלֵי⁠הֶ֖ם לֵ⁠אמֹ֑ר כֹּ֤ה תַעֲשׂוּ⁠ן֙ בְּ⁠יִרְאַ֣ת יְהוָ֔ה בֶּ⁠אֱמוּנָ֖ה וּ⁠בְ⁠לֵבָ֥ב שָׁלֵֽם׃","wa⁠yĕẕa֥w ʻàléy⁠he֖m lé⁠ʼmò֑r kò֤̇h ţaʻàş̂ẇ⁠n֙ bĕ̇⁠yirĕʼa֣ţ yĕhwá֔h bė⁠ʼèmẇná֖h ẇ⁠bĕ⁠lébá֥b şá̌léֽm׃"],[19,10,"וְ⁠כָל־רִיב֩ אֲשֶׁר־יָב֨וֹא עֲלֵי⁠כֶ֜ם מֵ⁠אֲחֵי⁠כֶ֣ם ׀ הַ⁠יֹּשְׁבִ֣ים בְּ⁠עָרֵי⁠הֶ֗ם בֵּֽין־דָּ֣ם ׀ לְ⁠דָם֮ בֵּין־תּוֹרָ֣ה לְ⁠מִצְוָה֮ לְ⁠חֻקִּ֣ים וּ⁠לְ⁠מִשְׁפָּטִים֒ וְ⁠הִזְהַרְתֶּ֣ם אֹתָ֔⁠ם וְ⁠לֹ֤א יֶאְשְׁמוּ֙ לַ⁠יהוָ֔ה וְ⁠הָֽיָה־קֶ֥צֶף עֲלֵי⁠כֶ֖ם וְ⁠עַל־אֲחֵי⁠כֶ֑ם כֹּ֥ה תַעֲשׂ֖וּ⁠ן וְ⁠לֹ֥א תֶאְשָֽׁמוּ׃","wĕ⁠kál-riyb֩ ʼàşěr-yáb֨wòʼ ʻàléy⁠ke֜m mé⁠ʼàẖéy⁠ke֣m ׀ ha⁠yò̇şĕ̌bi֣ym bĕ̇⁠ʻáréy⁠he֗m béֽ̇yn-dá֣̇m ׀ lĕ⁠dám֮ bé̇yn-ţ̇wòrá֣h lĕ⁠miẕĕwáh֮ lĕ⁠ẖuqi֣̇ym ẇ⁠lĕ⁠mişĕ̌pá̇tiym֒ wĕ⁠hizĕharĕţė֣m ʼòţá֔⁠m wĕ⁠lò֤ʼ yeʼĕşĕ̌mẇ֙ la⁠yhwá֔h wĕ⁠háֽyáh-qe֥ẕep ʻàléy⁠ke֖m wĕ⁠ʻal-ʼàẖéy⁠ke֑m kò֥̇h ţaʻàş֖̂ẇ⁠n wĕ⁠lò֥ʼ ţeʼĕşáֽ̌mẇ׃"],[19,11,"וְ⁠הִנֵּ֡ה אֲמַרְיָ֣הוּ כֹהֵן֩ הָ⁠רֹ֨אשׁ עֲלֵי⁠כֶ֜ם לְ⁠כֹ֣ל דְּבַר־יְהוָ֗ה וּ⁠זְבַדְיָ֨הוּ בֶן־יִשְׁמָעֵ֜אל הַ⁠נָּגִ֤יד לְ⁠בֵית־יְהוּדָה֙ לְ⁠כֹ֣ל דְּבַר־הַ⁠מֶּ֔לֶךְ וְ⁠שֹׁטְרִ֥ים הַ⁠לְוִיִּ֖ם לִ⁠פְנֵי⁠כֶ֑ם חִזְק֣וּ וַ⁠עֲשׂ֔וּ וִ⁠יהִ֥י יְהוָ֖ה עִם־הַ⁠טּֽוֹב׃פ","wĕ⁠hiné̇֡h ʼàmarĕyá֣hẇ kòhén֩ há⁠rò֨ʼş̌ ʻàléy⁠ke֜m lĕ⁠kò֣l dĕ̇bar-yĕhwá֗h ẇ⁠zĕbadĕyá֨hẇ ben-yişĕ̌máʻé֜ʼl ha⁠ná̇gi֤yd lĕ⁠béyţ-yĕhẇdáh֙ lĕ⁠kò֣l dĕ̇bar-ha⁠mė֔lekĕ wĕ⁠şò̌tĕri֥ym ha⁠lĕwiyi֖̇m li⁠pĕnéy⁠ke֑m ẖizĕq֣ẇ wa⁠ʻàş̂֔ẇ wi⁠yhi֥y yĕhwá֖h ʻim-ha⁠ṫֽwòb׃p"],[20,1,"וַ⁠יְהִ֣י אַֽחֲרֵי כֵ֡ן בָּ֣אוּ בְנֵי־מוֹאָב֩ וּ⁠בְנֵ֨י עַמּ֜וֹן וְ⁠עִמָּ⁠הֶ֧ם ׀ מֵֽ⁠הָ⁠עַמּוֹנִ֛ים עַל־יְהוֹשָׁפָ֖ט לַ⁠מִּלְחָמָֽה׃","wa⁠yĕhi֣y ʼֽaẖàréy ké֡n bá֣̇ʼẇ bĕnéy-mwòʼáb֩ ẇ⁠bĕné֨y ʻaṁ֜wòn wĕ⁠ʻimá̇⁠he֧m ׀ méֽ⁠há⁠ʻaṁwòni֛ym ʻal-yĕhwòşá̌pá֖t la⁠mi̇lĕẖámáֽh׃"],[20,2,"וַ⁠יָּבֹ֗אוּ וַ⁠יַּגִּ֤ידוּ לִֽ⁠יהוֹשָׁפָט֙ לֵ⁠אמֹ֔ר בָּ֣א עָלֶ֜י⁠ךָ הָמ֥וֹן רָ֛ב מֵ⁠עֵ֥בֶר לַ⁠יָּ֖ם מֵ⁠אֲרָ֑ם וְ⁠הִנָּ⁠ם֙ בְּ⁠חַֽצְצ֣וֹן תָּמָ֔ר הִ֖יא עֵ֥ין גֶּֽדִי׃","wa⁠yá̇bò֗ʼẇ wa⁠yȧgi֤̇ydẇ liֽ⁠yhwòşá̌pát֙ lé⁠ʼmò֔r bá֣̇ʼ ʻále֜y⁠ká hám֥wòn rá֛b mé⁠ʻé֥ber la⁠yá֖̇m mé⁠ʼàrá֑m wĕ⁠hiná̇⁠m֙ bĕ̇⁠ẖaֽẕĕẕ֣wòn ţá̇má֔r hi֖yʼ ʻé֥yn gėֽdiy׃"],[20,3,"וַ⁠יִּרָ֕א וַ⁠יִּתֵּ֧ן יְהוֹשָׁפָ֛ט אֶת־פָּנָ֖י⁠ו לִ⁠דְר֣וֹשׁ לַ⁠יהוָ֑ה וַ⁠יִּקְרָא־צ֖וֹם עַל־כָּל־יְהוּדָֽה׃","wa⁠yi̇rá֕ʼ wa⁠yi̇ţé֧̇n yĕhwòşá̌pá֛t ʼeţ-pá̇ná֖y⁠w li⁠dĕr֣wòş̌ la⁠yhwá֑h wa⁠yi̇qĕráʼ-ẕ֖wòm ʻal-ká̇l-yĕhẇdáֽh׃"],[20,4,"וַ⁠יִּקָּבְצ֣וּ יְהוּדָ֔ה לְ⁠בַקֵּ֖שׁ מֵֽ⁠יְהוָ֑ה גַּ֚ם מִ⁠כָּל־עָרֵ֣י יְהוּדָ֔ה בָּ֖אוּ לְ⁠בַקֵּ֥שׁ אֶת־יְהוָֽה׃","wa⁠yi̇qá̇bĕẕ֣ẇ yĕhẇdá֔h lĕ⁠baqé֖̇ş̌ méֽ⁠yĕhwá֑h gȧ֚m mi⁠ká̇l-ʻáré֣y yĕhẇdá֔h bá֖̇ʼẇ lĕ⁠baqé֥̇ş̌ ʼeţ-yĕhwáֽh׃"],[20,5,"וַ⁠יַּעֲמֹ֣ד יְהוֹשָׁפָ֗ט בִּ⁠קְהַ֧ל יְהוּדָ֛ה וִ⁠ירוּשָׁלִַ֖ם בְּ⁠בֵ֣ית יְהוָ֑ה לִ⁠פְנֵ֖י הֶ⁠חָצֵ֥ר הַ⁠חֲדָשָֽׁה׃","wa⁠yȧʻàmò֣d yĕhwòşá̌pá֗t bi̇⁠qĕha֧l yĕhẇdá֛h wi⁠yrẇşá̌lia֖m bĕ̇⁠bé֣yţ yĕhwá֑h li⁠pĕné֖y he⁠ẖáẕé֥r ha⁠ẖàdáşáֽ̌h׃"],[20,6,"וַ⁠יֹּאמַ֗ר יְהוָ֞ה אֱלֹהֵ֤י אֲבֹתֵ֨י⁠נוּ֙ הֲ⁠לֹ֨א אַתָּֽה־ה֤וּא אֱלֹהִים֙ בַּ⁠שָּׁמַ֔יִם וְ⁠אַתָּ֣ה מוֹשֵׁ֔ל בְּ⁠כֹ֖ל מַמְלְכ֣וֹת הַ⁠גּוֹיִ֑ם וּ⁠בְ⁠יָדְ⁠ךָ֙ כֹּ֣חַ וּ⁠גְבוּרָ֔ה וְ⁠אֵ֥ין עִמְּ⁠ךָ֖ לְ⁠הִתְיַצֵּֽב׃","wa⁠yò̇ʼma֗r yĕhwá֞h ʼèlòhé֤y ʼàbòţé֨y⁠nẇ֙ hà⁠lò֨ʼ ʼaţáֽ̇h-h֤ẇʼ ʼèlòhiym֙ bȧ⁠şá̇̌ma֔yim wĕ⁠ʼaţá֣̇h mwòşé̌֔l bĕ̇⁠kò֖l mamĕlĕk֣wòţ ha⁠ġwòyi֑m ẇ⁠bĕ⁠yádĕ⁠ká֙ kò֣̇ẖa ẇ⁠gĕbẇrá֔h wĕ⁠ʼé֥yn ʻimĕ̇⁠ká֖ lĕ⁠hiţĕyaẕéֽ̇b׃"],[20,7,"הֲ⁠לֹ֣א ׀ אַתָּ֣ה אֱלֹהֵ֗י⁠נוּ הוֹרַ֨שְׁתָּ֙ אֶת־יֹשְׁבֵי֙ הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את מִ⁠לִּ⁠פְנֵ֖י עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל וַֽ⁠תִּתְּנָ֗⁠הּ לְ⁠זֶ֛רַע אַבְרָהָ֥ם אֹֽהַבְ⁠ךָ֖ לְ⁠עוֹלָֽם׃","hà⁠lò֣ʼ ׀ ʼaţá֣̇h ʼèlòhé֗y⁠nẇ hwòra֨şĕ̌ţá̇֙ ʼeţ-yòşĕ̌béy֙ há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ mi⁠li̇⁠pĕné֖y ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l waֽ⁠ţi̇ţĕ̇ná֗⁠ḣ lĕ⁠ze֛raʻ ʼabĕráhá֥m ʼòֽhabĕ⁠ká֖ lĕ⁠ʻwòláֽm׃"],[20,8,"וַ⁠יֵּשְׁב֖וּ־בָ֑⁠הּ וַ⁠יִּבְנ֨וּ לְ⁠ךָ֧ ׀ בָּ֛⁠הּ מִקְדָּ֖שׁ לְ⁠שִׁמְ⁠ךָ֥ לֵ⁠אמֹֽר׃","wa⁠yé̇şĕ̌b֖ẇ-bá֑⁠ḣ wa⁠yi̇bĕn֨ẇ lĕ⁠ká֧ ׀ bá֛̇⁠ḣ miqĕdá֖̇ş̌ lĕ⁠şǐmĕ⁠ká֥ lé⁠ʼmòֽr׃"],[20,9,"אִם־תָּב֨וֹא עָלֵ֜י⁠נוּ רָעָ֗ה חֶרֶב֮ שְׁפוֹט֮ וְ⁠דֶ֣בֶר וְ⁠רָעָב֒ נַֽעַמְדָ֞ה לִ⁠פְנֵ֨י הַ⁠בַּ֤יִת הַ⁠זֶּה֙ וּ⁠לְ⁠פָנֶ֔י⁠ךָ כִּ֥י שִׁמְ⁠ךָ֖ בַּ⁠בַּ֣יִת הַ⁠זֶּ֑ה וְ⁠נִזְעַ֥ק אֵלֶ֛י⁠ךָ מִ⁠צָּרָתֵ֖⁠נוּ וְ⁠תִשְׁמַ֥ע וְ⁠תוֹשִֽׁיעַ׃","ʼim-ţá̇b֨wòʼ ʻálé֜y⁠nẇ ráʻá֗h ẖereb֮ şĕ̌pwòt֮ wĕ⁠de֣ber wĕ⁠ráʻáb֒ naֽʻamĕdá֞h li⁠pĕné֨y ha⁠bȧ֤yiţ ha⁠zėh֙ ẇ⁠lĕ⁠páne֔y⁠ká ki֥̇y şǐmĕ⁠ká֖ bȧ⁠bȧ֣yiţ ha⁠zė֑h wĕ⁠nizĕʻa֥q ʼéle֛y⁠ká mi⁠ẕá̇ráţé֖⁠nẇ wĕ⁠ţişĕ̌ma֥ʻ wĕ⁠ţwòşǐֽyʻa׃"],[20,10,"וְ⁠עַתָּ֡ה הִנֵּה֩ בְנֵֽי־עַמּ֨וֹן וּ⁠מוֹאָ֜ב וְ⁠הַר־שֵׂעִ֗יר אֲ֠שֶׁר לֹֽא־נָתַ֤תָּה לְ⁠יִשְׂרָאֵל֙ לָ⁠ב֣וֹא בָ⁠הֶ֔ם בְּ⁠בֹאָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם כִּ֛י סָ֥רוּ מֵ⁠עֲלֵי⁠הֶ֖ם וְ⁠לֹ֥א הִשְׁמִידֽוּ⁠ם׃","wĕ⁠ʻaţá̇֡h hiné̇h֩ bĕnéֽy-ʻaṁ֨wòn ẇ⁠mwòʼá֜b wĕ⁠har-şé̂ʻi֗yr ʼà֠şěr lòֽʼ-náţa֤ţá̇h lĕ⁠yişĕ̂ráʼél֙ lá⁠b֣wòʼ bá⁠he֔m bĕ̇⁠bòʼá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim ki֛̇y sá֥rẇ mé⁠ʻàléy⁠he֖m wĕ⁠lò֥ʼ hişĕ̌miydֽẇ⁠m׃"],[20,11,"וְ⁠הִ֨נֵּה־הֵ֔ם גֹּמְלִ֖ים עָלֵ֑י⁠נוּ לָ⁠בוֹא֙ לְ⁠גָ֣רְשֵׁ֔⁠נוּ מִ⁠יְּרֻשָּׁתְ⁠ךָ֖ אֲשֶׁ֥ר הֽוֹרַשְׁתָּֽ⁠נוּ׃","wĕ⁠hi֨né̇h-hé֔m gò̇mĕli֖ym ʻálé֑y⁠nẇ lá⁠bwòʼ֙ lĕ⁠gá֣rĕşé̌֔⁠nẇ mi⁠yĕ̇ruşá̇̌ţĕ⁠ká֖ ʼàşě֥r hֽwòraşĕ̌ţáֽ̇⁠nẇ׃"],[20,12,"אֱלֹהֵ֨י⁠נוּ֙ הֲ⁠לֹ֣א תִשְׁפָּט־בָּ֔⁠ם כִּ֣י אֵ֥ין בָּ֨⁠נוּ֙ כֹּ֔חַ לִ֠⁠פְנֵי הֶ⁠הָמ֥וֹן הָ⁠רָ֛ב הַ⁠זֶּ֖ה הַ⁠בָּ֣א עָלֵ֑י⁠נוּ וַ⁠אֲנַ֗חְנוּ לֹ֤א נֵדַע֙ מַֽה־נַּעֲשֶׂ֔ה כִּ֥י עָלֶ֖י⁠ךָ עֵינֵֽי⁠נוּ׃","ʼèlòhé֨y⁠nẇ֙ hà⁠lò֣ʼ ţişĕ̌pá̇t-bá̇֔⁠m ki֣̇y ʼé֥yn bá̇֨⁠nẇ֙ kò̇֔ẖa li֠⁠pĕnéy he⁠hám֥wòn há⁠rá֛b ha⁠zė֖h ha⁠bá֣̇ʼ ʻálé֑y⁠nẇ wa⁠ʼàna֗ẖĕnẇ lò֤ʼ nédaʻ֙ maֽh-nȧʻàşê֔h ki֥̇y ʻále֖y⁠ká ʻéynéֽy⁠nẇ׃"],[20,13,"וְ⁠כָ֨ל־יְהוּדָ֔ה עֹמְדִ֖ים לִ⁠פְנֵ֣י יְהוָ֑ה גַּם־טַפָּ֖⁠ם נְשֵׁי⁠הֶ֥ם וּ⁠בְנֵי⁠הֶֽם׃פ","wĕ⁠ká֨l-yĕhẇdá֔h ʻòmĕdi֖ym li⁠pĕné֣y yĕhwá֑h gȧm-tapá֖̇⁠m nĕşé̌y⁠he֥m ẇ⁠bĕnéy⁠heֽm׃p"],[20,14,"וְ⁠יַחֲזִיאֵ֡ל בֶּן־זְכַרְיָ֡הוּ בֶּן־בְּ֠נָיָה בֶּן־יְעִיאֵ֧ל בֶּן־מַתַּנְיָ֛ה הַ⁠לֵּוִ֖י מִן־בְּנֵ֣י אָסָ֑ף הָיְתָ֤ה עָלָי⁠ו֙ ר֣וּחַ יְהוָ֔ה בְּ⁠ת֖וֹךְ הַ⁠קָּהָֽל׃","wĕ⁠yaẖàziyʼé֡l bėn-zĕkarĕyá֡hẇ bėn-bĕ̇֠náyáh bėn-yĕʻiyʼé֧l bėn-maţȧnĕyá֛h ha⁠lé̇wi֖y min-bĕ̇né֣y ʼásá֑p háyĕţá֤h ʻáláy⁠w֙ r֣ẇẖa yĕhwá֔h bĕ̇⁠ţ֖wòkĕ ha⁠qá̇háֽl׃"],[20,15,"וַ⁠יֹּ֗אמֶר הַקְשִׁ֤יבוּ כָל־יְהוּדָה֙ וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם וְ⁠הַ⁠מֶּ֖לֶךְ יְהוֹשָׁפָ֑ט כֹּֽה־אָמַ֨ר יְהוָ֜ה לָ⁠כֶ֗ם אַ֠תֶּם אַל־תִּֽירְא֤וּ וְ⁠אַל־תֵּחַ֨תּוּ֙ מִ⁠פְּנֵ֨י הֶ⁠הָמ֤וֹן הָ⁠רָב֙ הַ⁠זֶּ֔ה כִּ֣י לֹ֥א לָ⁠כֶ֛ם הַ⁠מִּלְחָמָ֖ה כִּ֥י לֵ⁠אלֹהִֽים׃","wa⁠yò̇֗ʼmer haqĕşǐ֤ybẇ kál-yĕhẇdáh֙ wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌lia֔m wĕ⁠ha⁠mė֖lekĕ yĕhwòşá̌pá֑t kòֽ̇h-ʼáma֨r yĕhwá֜h lá⁠ke֗m ʼa֠ţėm ʼal-ţiֽ̇yrĕʼ֤ẇ wĕ⁠ʼal-ţé̇ẖa֨ţ̇ẇ֙ mi⁠pĕ̇né֨y he⁠hám֤wòn há⁠ráb֙ ha⁠zė֔h ki֣̇y lò֥ʼ lá⁠ke֛m ha⁠mi̇lĕẖámá֖h ki֥̇y lé⁠ʼlòhiֽym׃"],[20,16,"מָחָר֙ רְד֣וּ עֲלֵי⁠הֶ֔ם הִנָּ֥⁠ם עֹלִ֖ים בְּ⁠מַעֲלֵ֣ה הַ⁠צִּ֑יץ וּ⁠מְצָאתֶ֤ם אֹתָ⁠ם֙ בְּ⁠ס֣וֹף הַ⁠נַּ֔חַל פְּנֵ֖י מִדְבַּ֥ר יְרוּאֵֽל׃","máẖár֙ rĕd֣ẇ ʻàléy⁠he֔m hiná֥̇⁠m ʻòli֖ym bĕ̇⁠maʻàlé֣h ha⁠ẕi֑̇yẕ ẇ⁠mĕẕáʼţe֤m ʼòţá⁠m֙ bĕ̇⁠s֣wòp ha⁠nȧ֔ẖal pĕ̇né֖y midĕbȧ֥r yĕrẇʼéֽl׃"],[20,17,"לֹ֥א לָ⁠כֶ֖ם לְ⁠הִלָּחֵ֣ם בָּ⁠זֹ֑את הִתְיַצְּב֣וּ עִמְד֡וּ וּ⁠רְא֣וּ אֶת־יְשׁוּעַת֩ יְהוָ֨ה עִמָּ⁠כֶ֜ם יְהוּדָ֣ה וִֽ⁠ירוּשָׁלִַ֗ם אַל־תִּֽירְאוּ֙ וְ⁠אַל־תֵּחַ֔תּוּ מָחָר֙ צְא֣וּ לִ⁠פְנֵי⁠הֶ֔ם וַ⁠יהוָ֖ה עִמָּ⁠כֶֽם׃","lò֥ʼ lá⁠ke֖m lĕ⁠hilá̇ẖé֣m bá̇⁠zò֑ʼţ hiţĕyaẕĕ̇b֣ẇ ʻimĕd֡ẇ ẇ⁠rĕʼ֣ẇ ʼeţ-yĕş̌ẇʻaţ֩ yĕhwá֨h ʻimá̇⁠ke֜m yĕhẇdá֣h wiֽ⁠yrẇşá̌lia֗m ʼal-ţiֽ̇yrĕʼẇ֙ wĕ⁠ʼal-ţé̇ẖa֔ţ̇ẇ máẖár֙ ẕĕʼ֣ẇ li⁠pĕnéy⁠he֔m wa⁠yhwá֖h ʻimá̇⁠keֽm׃"],[20,18,"וַ⁠יִּקֹּ֧ד יְהוֹשָׁפָ֛ט אַפַּ֖יִם אָ֑רְצָ⁠ה וְ⁠כָל־יְהוּדָ֞ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם נָֽפְלוּ֙ לִ⁠פְנֵ֣י יְהוָ֔ה לְ⁠הִֽשְׁתַּחֲוֺ֖ת לַ⁠יהוָֽה׃","wa⁠yi̇qò֧̇d yĕhwòşá̌pá֛t ʼapȧ֖yim ʼá֑rĕẕá⁠h wĕ⁠kál-yĕhẇdá֞h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌lia֗m náֽpĕlẇ֙ li⁠pĕné֣y yĕhwá֔h lĕ⁠hiֽşĕ̌ţȧẖàwֺ֖ţ la⁠yhwáֽh׃"],[20,19,"וַ⁠יָּקֻ֧מוּ הַ⁠לְוִיִּ֛ם מִן־בְּנֵ֥י הַ⁠קְּהָתִ֖ים וּ⁠מִן־בְּנֵ֣י הַ⁠קָּרְחִ֑ים לְ⁠הַלֵּ֗ל לַ⁠יהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל בְּ⁠ק֥וֹל גָּד֖וֹל לְ⁠מָֽעְלָ⁠ה׃","wa⁠yá̇qu֧mẇ ha⁠lĕwiyi֛̇m min-bĕ̇né֥y ha⁠qĕ̇háţi֖ym ẇ⁠min-bĕ̇né֣y ha⁠qá̇rĕẖi֑ym lĕ⁠halé̇֗l la⁠yhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l bĕ̇⁠q֥wòl gá̇d֖wòl lĕ⁠máֽʻĕlá⁠h׃"],[20,20,"וַ⁠יַּשְׁכִּ֣ימוּ בַ⁠בֹּ֔קֶר וַ⁠יֵּצְא֖וּ לְ⁠מִדְבַּ֣ר תְּק֑וֹעַ וּ⁠בְ⁠צֵאתָ֞⁠ם עָמַ֣ד יְהוֹשָׁפָ֗ט וַ⁠יֹּ֨אמֶר֙ שְׁמָע֗וּ⁠נִי יְהוּדָה֙ וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם הַאֲמִ֜ינוּ בַּ⁠יהוָ֤ה אֱלֹהֵי⁠כֶם֙ וְ⁠תֵ֣אָמֵ֔נוּ הַאֲמִ֥ינוּ בִ⁠נְבִיאָ֖י⁠ו וְ⁠הַצְלִֽיחוּ׃","wa⁠yȧşĕ̌ki֣̇ymẇ ba⁠bò̇֔qer wa⁠yé̇ẕĕʼ֖ẇ lĕ⁠midĕbȧ֣r ţĕ̇q֑wòʻa ẇ⁠bĕ⁠ẕéʼţá֞⁠m ʻáma֣d yĕhwòşá̌pá֗t wa⁠yò̇֨ʼmer֙ şĕ̌máʻ֗ẇ⁠niy yĕhẇdáh֙ wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌lia֔m haʼàmi֜ynẇ bȧ⁠yhwá֤h ʼèlòhéy⁠kem֙ wĕ⁠ţé֣ʼámé֔nẇ haʼàmi֥ynẇ bi⁠nĕbiyʼá֖y⁠w wĕ⁠haẕĕliֽyẖẇ׃"],[20,21,"וַ⁠יִּוָּעַץ֙ אֶל־הָ⁠עָ֔ם וַ⁠יַּעֲמֵ֤ד מְשֹֽׁרֲרִים֙ לַ⁠יהוָ֔ה וּֽ⁠מְהַֽלְלִ֖ים לְ⁠הַדְרַת־קֹ֑דֶשׁ בְּ⁠צֵאת֙ לִ⁠פְנֵ֣י הֶֽ⁠חָל֔וּץ וְ⁠אֹֽמְרִים֙ הוֹד֣וּ לַ⁠יהוָ֔ה כִּ֥י לְ⁠עוֹלָ֖ם חַסְדּֽ⁠וֹ׃","wa⁠yi̇wá̇ʻaẕ֙ ʼel-há⁠ʻá֔m wa⁠yȧʻàmé֤d mĕşòֽ̌ràriym֙ la⁠yhwá֔h ẇֽ⁠mĕhaֽlĕli֖ym lĕ⁠hadĕraţ-qò֑deş̌ bĕ̇⁠ẕéʼţ֙ li⁠pĕné֣y heֽ⁠ẖál֔ẇẕ wĕ⁠ʼòֽmĕriym֙ hwòd֣ẇ la⁠yhwá֔h ki֥̇y lĕ⁠ʻwòlá֖m ẖasĕḋֽ⁠wò׃"],[20,22,"וּ⁠בְ⁠עֵת֩ הֵחֵ֨לּוּ בְ⁠רִנָּ֜ה וּ⁠תְהִלָּ֗ה נָתַ֣ן יְהוָ֣ה ׀ מְ֠אָֽרְבִים עַל־בְּנֵ֨י עַמּ֜וֹן מוֹאָ֧ב וְ⁠הַר־שֵׂעִ֛יר הַ⁠בָּאִ֥ים לִֽ⁠יהוּדָ֖ה וַ⁠יִּנָּגֵֽפוּ׃","ẇ⁠bĕ⁠ʻéţ֩ héẖé֨l̇ẇ bĕ⁠riná̇֜h ẇ⁠ţĕhilá̇֗h náţa֣n yĕhwá֣h ׀ mĕ֠ʼáֽrĕbiym ʻal-bĕ̇né֨y ʻaṁ֜wòn mwòʼá֧b wĕ⁠har-şé̂ʻi֛yr ha⁠bá̇ʼi֥ym liֽ⁠yhẇdá֖h wa⁠yi̇ná̇géֽpẇ׃"],[20,23,"וַ֠⁠יַּֽעַמְדוּ בְּנֵ֨י עַמּ֧וֹן וּ⁠מוֹאָ֛ב עַל־יֹשְׁבֵ֥י הַר־שֵׂעִ֖יר לְ⁠הַחֲרִ֣ים וּ⁠לְ⁠הַשְׁמִ֑יד וּ⁠כְ⁠כַלּוֹתָ⁠ם֙ בְּ⁠יוֹשְׁבֵ֣י שֵׂעִ֔יר עָזְר֥וּ אִישׁ־בְּ⁠רֵעֵ֖⁠הוּ לְ⁠מַשְׁחִֽית׃","wa֠⁠yȧֽʻamĕdẇ bĕ̇né֨y ʻaṁ֧wòn ẇ⁠mwòʼá֛b ʻal-yòşĕ̌bé֥y har-şé̂ʻi֖yr lĕ⁠haẖàri֣ym ẇ⁠lĕ⁠haşĕ̌mi֑yd ẇ⁠kĕ⁠kal̇wòţá⁠m֙ bĕ̇⁠ywòşĕ̌bé֣y şé̂ʻi֔yr ʻázĕr֥ẇ ʼiyş̌-bĕ̇⁠réʻé֖⁠hẇ lĕ⁠maşĕ̌ẖiֽyţ׃"],[20,24,"וִֽ⁠יהוּדָ֛ה בָּ֥א עַל־הַ⁠מִּצְפֶּ֖ה לַ⁠מִּדְבָּ֑ר וַ⁠יִּפְנוּ֙ אֶל־הֶ֣⁠הָמ֔וֹן וְ⁠הִנָּ֧⁠ם פְּגָרִ֛ים נֹפְלִ֥ים אַ֖רְצָ⁠ה וְ⁠אֵ֥ין פְּלֵיטָֽה׃","wiֽ⁠yhẇdá֛h bá֥̇ʼ ʻal-ha⁠mi̇ẕĕpė֖h la⁠mi̇dĕbá֑̇r wa⁠yi̇pĕnẇ֙ ʼel-he֣⁠hám֔wòn wĕ⁠hiná֧̇⁠m pĕ̇gári֛ym nòpĕli֥ym ʼa֖rĕẕá⁠h wĕ⁠ʼé֥yn pĕ̇léytáֽh׃"],[20,25,"וַ⁠יָּבֹ֨א יְהוֹשָׁפָ֣ט וְ⁠עַמּ⁠וֹ֮ לָ⁠בֹ֣ז אֶת־שְׁלָלָ⁠ם֒ וַ⁠יִּמְצְאוּ֩ בָ⁠הֶ֨ם לָ⁠רֹ֜ב וּ⁠רְכ֤וּשׁ וּ⁠פְגָרִים֙ וּ⁠כְלֵ֣י חֲמֻד֔וֹת וַ⁠יְנַצְּל֥וּ לָ⁠הֶ֖ם לְ⁠אֵ֣ין מַשָּׂ֑א וַ⁠יִּֽהְי֞וּ יָמִ֧ים שְׁלוֹשָׁ֛ה בֹּזְזִ֥ים אֶת־הַ⁠שָּׁלָ֖ל כִּ֥י רַב־הֽוּא׃","wa⁠yá̇bò֨ʼ yĕhwòşá̌pá֣t wĕ⁠ʻaṁ⁠wò֮ lá⁠bò֣z ʼeţ-şĕ̌lálá⁠m֒ wa⁠yi̇mĕẕĕʼẇ֩ bá⁠he֨m lá⁠rò֜b ẇ⁠rĕk֤ẇş̌ ẇ⁠pĕgáriym֙ ẇ⁠kĕlé֣y ẖàmud֔wòţ wa⁠yĕnaẕĕ̇l֥ẇ lá⁠he֖m lĕ⁠ʼé֣yn maşá֑̇̂ʼ wa⁠yiֽ̇hĕy֞ẇ yámi֧ym şĕ̌lwòşá֛̌h bò̇zĕzi֥ym ʼeţ-ha⁠şá̇̌lá֖l ki֥̇y rab-hֽẇʼ׃"],[20,26,"וּ⁠בַ⁠יּ֣וֹם הָ⁠רְבִעִ֗י נִקְהֲלוּ֙ לְ⁠עֵ֣מֶק בְּרָכָ֔ה כִּי־שָׁ֖ם בֵּרֲכ֣וּ אֶת־יְהוָ֑ה עַל־כֵּ֡ן קָֽרְא֞וּ אֶת־שֵׁ֨ם הַ⁠מָּק֥וֹם הַ⁠ה֛וּא עֵ֥מֶק בְּרָכָ֖ה עַד־הַ⁠יּֽוֹם׃","ẇ⁠ba⁠ẏ֣wòm há⁠rĕbiʻi֗y niqĕhàlẇ֙ lĕ⁠ʻé֣meq bĕ̇ráká֔h ki̇y-şá֖̌m bé̇ràk֣ẇ ʼeţ-yĕhwá֑h ʻal-ké̇֡n qáֽrĕʼ֞ẇ ʼeţ-şé̌֨m ha⁠má̇q֥wòm ha⁠h֛ẇʼ ʻé֥meq bĕ̇ráká֖h ʻad-ha⁠ẏֽwòm׃"],[20,27,"וַ֠⁠יָּשֻׁבוּ כָּל־אִ֨ישׁ יְהוּדָ֤ה וִֽ⁠ירוּשָׁלִַ֨ם֙ וִֽ⁠יהוֹשָׁפָ֣ט בְּ⁠רֹאשָׁ֔⁠ם לָ⁠שׁ֥וּב אֶל־יְרוּשָׁלִַ֖ם בְּ⁠שִׂמְחָ֑ה כִּֽי־שִׂמְּחָ֥⁠ם יְהוָ֖ה מֵֽ⁠אוֹיְבֵי⁠הֶֽם׃","wa֠⁠yá̇şǔbẇ ká̇l-ʼi֨yş̌ yĕhẇdá֤h wiֽ⁠yrẇşá̌lia֨m֙ wiֽ⁠yhwòşá̌pá֣t bĕ̇⁠ròʼşá̌֔⁠m lá⁠ş֥̌ẇb ʼel-yĕrẇşá̌lia֖m bĕ̇⁠şîmĕẖá֑h kiֽ̇y-şîmĕ̇ẖá֥⁠m yĕhwá֖h méֽ⁠ʼwòyĕbéy⁠heֽm׃"],[20,28,"וַ⁠יָּבֹ֨אוּ֙ יְר֣וּשָׁלִַ֔ם בִּ⁠נְבָלִ֥ים וּ⁠בְ⁠כִנֹּר֖וֹת וּ⁠בַ⁠חֲצֹצְר֑וֹת אֶל־בֵּ֖ית יְהוָֽה׃","wa⁠yá̇bò֨ʼẇ֙ yĕr֣ẇşá̌lia֔m bi̇⁠nĕbáli֥ym ẇ⁠bĕ⁠kinò̇r֖wòţ ẇ⁠ba⁠ẖàẕòẕĕr֑wòţ ʼel-bé֖̇yţ yĕhwáֽh׃"],[20,29,"וַ⁠יְהִי֙ פַּ֣חַד אֱלֹהִ֔ים עַ֖ל כָּל־מַמְלְכ֣וֹת הָ⁠אֲרָצ֑וֹת בְּ⁠שָׁמְעָ֕⁠ם כִּ֚י נִלְחַ֣ם יְהוָ֔ה עִ֖ם אוֹיְבֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕhiy֙ pȧ֣ẖad ʼèlòhi֔ym ʻa֖l ká̇l-mamĕlĕk֣wòţ há⁠ʼàráẕ֑wòţ bĕ̇⁠şá̌mĕʻá֕⁠m ki֚̇y nilĕẖa֣m yĕhwá֔h ʻi֖m ʼwòyĕbé֥y yişĕ̂ráʼéֽl׃"],[20,30,"וַ⁠תִּשְׁקֹ֖ט מַלְכ֣וּת יְהוֹשָׁפָ֑ט וַ⁠יָּ֧נַֽח ל֦⁠וֹ אֱלֹהָ֖י⁠ו מִ⁠סָּבִֽיב׃פ","wa⁠ţi̇şĕ̌qò֖t malĕk֣ẇţ yĕhwòşá̌pá֑t wa⁠yá֧̇naֽẖ l֦⁠wò ʼèlòhá֖y⁠w mi⁠sá̇biֽyb׃p"],[20,31,"וַ⁠יִּמְלֹ֥ךְ יְהוֹשָׁפָ֖ט עַל־יְהוּדָ֑ה בֶּן־שְׁלֹשִׁים֩ וְ⁠חָמֵ֨שׁ שָׁנָ֜ה בְּ⁠מָלְכ֗⁠וֹ וְ⁠עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ מָלַ֣ךְ בִּֽ⁠ירוּשָׁלִַ֔ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ עֲזוּבָ֖ה בַּת־שִׁלְחִֽי׃","wa⁠yi̇mĕlò֥kĕ yĕhwòşá̌pá֖t ʻal-yĕhẇdá֑h bėn-şĕ̌lòşǐym֩ wĕ⁠ẖámé֨ş̌ şá̌ná֜h bĕ̇⁠málĕk֗⁠wò wĕ⁠ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ mála֣kĕ biֽ̇⁠yrẇşá̌lia֔m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ʻàzẇbá֖h bȧţ-şǐlĕẖiֽy׃"],[20,32,"וַ⁠יֵּ֗לֶךְ בְּ⁠דֶ֛רֶךְ אָבִ֥י⁠ו אָסָ֖א וְ⁠לֹא־סָ֣ר מִמֶּ֑⁠נָּה לַ⁠עֲשׂ֥וֹת הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yé̇֗lekĕ bĕ̇⁠de֛rekĕ ʼábi֥y⁠w ʼásá֖ʼ wĕ⁠lòʼ-sá֣r mimė֑⁠ná̇h la⁠ʻàş֥̂wòţ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[20,33,"אַ֥ךְ הַ⁠בָּמ֖וֹת לֹא־סָ֑רוּ וְ⁠ע֤וֹד הָ⁠עָם֙ לֹא־הֵכִ֣ינוּ לְבָבָ֔⁠ם לֵ⁠אלֹהֵ֖י אֲבֹתֵי⁠הֶֽם׃","ʼa֥kĕ ha⁠bá̇m֖wòţ lòʼ-sá֑rẇ wĕ⁠ʻ֤wòd há⁠ʻám֙ lòʼ-héki֣ynẇ lĕbábá֔⁠m lé⁠ʼlòhé֖y ʼàbòţéy⁠heֽm׃"],[20,34,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י יְהוֹשָׁפָ֔ט הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אַחֲרֹנִ֑ים הִנָּ֣⁠ם כְּתוּבִ֗ים בְּ⁠דִבְרֵי֙ יֵה֣וּא בֶן־חֲנָ֔נִי אֲשֶׁ֣ר הֹֽעֲלָ֔ה עַל־סֵ֖פֶר מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer֙ di̇bĕré֣y yĕhwòşá̌pá֔t há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼaẖàròni֑ym hiná֣̇⁠m kĕ̇ţẇbi֗ym bĕ̇⁠dibĕréy֙ yéh֣ẇʼ ben-ẖàná֔niy ʼàşě֣r hòֽʻàlá֔h ʻal-sé֖per malĕké֥y yişĕ̂ráʼéֽl׃"],[20,35,"וְ⁠אַחֲרֵי כֵ֗ן אֶתְחַבַּר֙ יְהוֹשָׁפָ֣ט מֶֽלֶךְ־יְהוּדָ֔ה עִ֖ם אֲחַזְיָ֣ה מֶֽלֶךְ־יִשְׂרָאֵ֑ל ה֖וּא הִרְשִׁ֥יעַ לַ⁠עֲשֽׂוֹת׃","wĕ⁠ʼaẖàréy ké֗n ʼeţĕẖabȧr֙ yĕhwòşá̌pá֣t meֽlekĕ-yĕhẇdá֔h ʻi֖m ʼàẖazĕyá֣h meֽlekĕ-yişĕ̂ráʼé֑l h֖ẇʼ hirĕşǐ֥yʻa la⁠ʻàşֽ̂wòţ׃"],[20,36,"וַ⁠יְחַבְּרֵ֣⁠הוּ עִמּ֔⁠וֹ לַ⁠עֲשׂ֥וֹת אֳנִיּ֖וֹת לָ⁠לֶ֣כֶת תַּרְשִׁ֑ישׁ וַ⁠יַּעֲשׂ֥וּ אֳנִיּ֖וֹת בְּ⁠עֶצְי֥וֹן גָּֽבֶר׃","wa⁠yĕẖabĕ̇ré֣⁠hẇ ʻiṁ֔⁠wò la⁠ʻàş֥̂wòţ ʼoniẏ֖wòţ lá⁠le֣keţ ţȧrĕşǐ֑yş̌ wa⁠yȧʻàş֥̂ẇ ʼoniẏ֖wòţ bĕ̇⁠ʻeẕĕy֥wòn gáֽ̇ber׃"],[20,37,"וַ⁠יִּתְנַבֵּ֞א אֱלִיעֶ֤זֶר בֶּן־דֹּדָוָ֨הוּ֙ מִ⁠מָּ֣רֵשָׁ֔ה עַל־יְהוֹשָׁפָ֖ט לֵ⁠אמֹ֑ר כְּ⁠הִֽתְחַבֶּרְ⁠ךָ֣ עִם־אֲחַזְיָ֗הוּ פָּרַ֤ץ יְהוָה֙ אֶֽת־מַעֲשֶׂ֔י⁠ךָ וַ⁠יִּשָּׁבְר֣וּ אֳנִיּ֔וֹת וְ⁠לֹ֥א עָצְר֖וּ לָ⁠לֶ֥כֶת אֶל־תַּרְשִֽׁישׁ׃","wa⁠yi̇ţĕnabé̇֞ʼ ʼèliyʻe֤zer bėn-dò̇dáwá֨hẇ֙ mi⁠má֣̇réşá̌֔h ʻal-yĕhwòşá̌pá֖t lé⁠ʼmò֑r kĕ̇⁠hiֽţĕẖabėrĕ⁠ká֣ ʻim-ʼàẖazĕyá֗hẇ pá̇ra֤ẕ yĕhwáh֙ ʼeֽţ-maʻàşê֔y⁠ká wa⁠yi̇şá̇̌bĕr֣ẇ ʼoniẏ֔wòţ wĕ⁠lò֥ʼ ʻáẕĕr֖ẇ lá⁠le֥keţ ʼel-ţȧrĕşǐֽyş̌׃"],[21,1,"וַ⁠יִּשְׁכַּ֤ב יְהֽוֹשָׁפָט֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֥ר עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֣יר דָּוִ֑יד וַ⁠יִּמְלֹ֛ךְ יְהוֹרָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yi̇şĕ̌kȧ֤b yĕhֽwòşá̌pát֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֥r ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֣yr dá̇wi֑yd wa⁠yi̇mĕlò֛kĕ yĕhwòrá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[21,2,"וְ⁠לֽ⁠וֹ־אַחִ֞ים בְּנֵ֣י יְהוֹשָׁפָ֗ט עֲזַרְיָ֤ה וִֽ⁠יחִיאֵל֙ וּ⁠זְכַרְיָ֣הוּ וַ⁠עֲזַרְיָ֔הוּ וּ⁠מִיכָאֵ֖ל וּ⁠שְׁפַטְיָ֑הוּ כָּל־אֵ֕לֶּה בְּנֵ֥י יְהוֹשָׁפָ֖ט מֶ֥לֶךְ־יִשְׂרָאֵֽל׃","wĕ⁠lֽ⁠wò-ʼaẖi֞ym bĕ̇né֣y yĕhwòşá̌pá֗t ʻàzarĕyá֤h wiֽ⁠yẖiyʼél֙ ẇ⁠zĕkarĕyá֣hẇ wa⁠ʻàzarĕyá֔hẇ ẇ⁠miykáʼé֖l ẇ⁠şĕ̌patĕyá֑hẇ ká̇l-ʼé֕lėh bĕ̇né֥y yĕhwòşá̌pá֖t me֥lekĕ-yişĕ̂ráʼéֽl׃"],[21,3,"וַ⁠יִּתֵּ֣ן לָ⁠הֶ֣ם ׀ אֲ֠בִי⁠הֶם מַתָּנ֨וֹת רַבּ֜וֹת לְ⁠כֶ֤סֶף וּ⁠לְ⁠זָהָב֙ וּ⁠לְ⁠מִגְדָּנ֔וֹת עִם־עָרֵ֥י מְצֻר֖וֹת בִּֽ⁠יהוּדָ֑ה וְ⁠אֶת־הַ⁠מַּמְלָכָ֛ה נָתַ֥ן לִֽ⁠יהוֹרָ֖ם כִּי־ה֥וּא הַ⁠בְּכֽוֹר׃פ","wa⁠yi̇ţé֣̇n lá⁠he֣m ׀ ʼà֠biy⁠hem maţá̇n֨wòţ raḃ֜wòţ lĕ⁠ke֤sep ẇ⁠lĕ⁠záháb֙ ẇ⁠lĕ⁠migĕdá̇n֔wòţ ʻim-ʻáré֥y mĕẕur֖wòţ biֽ̇⁠yhẇdá֑h wĕ⁠ʼeţ-ha⁠mȧmĕláká֛h náţa֥n liֽ⁠yhwòrá֖m ki̇y-h֥ẇʼ ha⁠bĕ̇kֽwòr׃p"],[21,4,"וַ⁠יָּ֨קָם יְהוֹרָ֜ם עַל־מַמְלֶ֤כַת אָבִי⁠ו֙ וַ⁠יִּתְחַזַּ֔ק וַ⁠יַּהֲרֹ֥ג אֶת־כָּל־אֶחָ֖י⁠ו בֶּ⁠חָ֑רֶב וְ⁠גַ֖ם מִ⁠שָּׂרֵ֥י יִשְׂרָאֵֽל׃","wa⁠yá̇֨qám yĕhwòrá֜m ʻal-mamĕle֤kaţ ʼábiy⁠w֙ wa⁠yi̇ţĕẖazȧ֔q wa⁠yȧhàrò֥g ʼeţ-ká̇l-ʼeẖá֖y⁠w bė⁠ẖá֑reb wĕ⁠ga֖m mi⁠şá̇̂ré֥y yişĕ̂ráʼéֽl׃"],[21,5,"בֶּן־שְׁלֹשִׁ֥ים וּ⁠שְׁתַּ֛יִם שָׁנָ֖ה יְהוֹרָ֣ם בְּ⁠מָלְכ֑⁠וֹ וּ⁠שְׁמוֹנֶ֣ה שָׁנִ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-şĕ̌lòşǐ֥ym ẇ⁠şĕ̌ţȧ֛yim şá̌ná֖h yĕhwòrá֣m bĕ̇⁠málĕk֑⁠wò ẇ⁠şĕ̌mwòne֣h şá̌ni֔ym mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[21,6,"וַ⁠יֵּ֜לֶךְ בְּ⁠דֶ֣רֶךְ ׀ מַלְכֵ֣י יִשְׂרָאֵ֗ל כַּ⁠אֲשֶׁ֤ר עָשׂוּ֙ בֵּ֣ית אַחְאָ֔ב כִּ֚י בַּת־אַחְאָ֔ב הָ֥יְתָה לּ֖⁠וֹ אִשָּׁ֑ה וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yé̇֜lekĕ bĕ̇⁠de֣rekĕ ׀ malĕké֣y yişĕ̂ráʼé֗l kȧ⁠ʼàşě֤r ʻáş̂ẇ֙ bé֣̇yţ ʼaẖĕʼá֔b ki֚̇y bȧţ-ʼaẖĕʼá֔b há֥yĕţáh l֖̇⁠wò ʼişá֑̇̌h wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[21,7,"וְ⁠לֹא־אָבָ֣ה יְהוָ֗ה לְ⁠הַשְׁחִית֙ אֶת־בֵּ֣ית דָּוִ֔יד לְמַ֣עַן הַ⁠בְּרִ֔ית אֲשֶׁ֥ר כָּרַ֖ת לְ⁠דָוִ֑יד וְ⁠כַ⁠אֲשֶׁ֣ר אָמַ֗ר לָ⁠תֵ֨ת ל֥⁠וֹ נִ֛יר וּ⁠לְ⁠בָנָ֖י⁠ו כָּל־הַ⁠יָּמִֽים׃","wĕ⁠lòʼ-ʼábá֣h yĕhwá֗h lĕ⁠haşĕ̌ẖiyţ֙ ʼeţ-bé֣̇yţ dá̇wi֔yd lĕma֣ʻan ha⁠bĕ̇ri֔yţ ʼàşě֥r ká̇ra֖ţ lĕ⁠dáwi֑yd wĕ⁠ka⁠ʼàşě֣r ʼáma֗r lá⁠ţé֨ţ l֥⁠wò ni֛yr ẇ⁠lĕ⁠báná֖y⁠w ká̇l-ha⁠yá̇miֽym׃"],[21,8,"בְּ⁠יָמָי⁠ו֙ פָּשַׁ֣ע אֱד֔וֹם מִ⁠תַּ֖חַת יַד־יְהוּדָ֑ה וַ⁠יַּמְלִ֥יכוּ עֲלֵי⁠הֶ֖ם מֶֽלֶךְ׃","bĕ̇⁠yámáy⁠w֙ pá̇şǎ֣ʻ ʼèd֔wòm mi⁠ţȧ֖ẖaţ yad-yĕhẇdá֑h wa⁠yȧmĕli֥ykẇ ʻàléy⁠he֖m meֽlekĕ׃"],[21,9,"וַ⁠יַּֽעֲבֹ֤ר יְהוֹרָם֙ עִם־שָׂרָ֔י⁠ו וְ⁠כָל־הָ⁠רֶ֖כֶב עִמּ֑⁠וֹ וַ⁠יְהִי֙ קָ֣ם לַ֔יְלָה וַ⁠יַּ֗ךְ אֶת־אֱדוֹם֙ הַ⁠סּוֹבֵ֣ב אֵלָ֔י⁠ו וְ⁠אֵ֖ת שָׂרֵ֥י הָ⁠רָֽכֶב׃","wa⁠yȧֽʻàbò֤r yĕhwòrám֙ ʻim-şá̂rá֔y⁠w wĕ⁠kál-há⁠re֖keb ʻiṁ֑⁠wò wa⁠yĕhiy֙ qá֣m la֔yĕláh wa⁠yȧ֗kĕ ʼeţ-ʼèdwòm֙ ha⁠ṡwòbé֣b ʼélá֔y⁠w wĕ⁠ʼé֖ţ şá̂ré֥y há⁠ráֽkeb׃"],[21,10,"וַ⁠יִּפְשַׁ֨ע אֱד֜וֹם מִ⁠תַּ֣חַת יַד־יְהוּדָ֗ה עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה אָ֣ז תִּפְשַׁ֥ע לִבְנָ֛ה בָּ⁠עֵ֥ת הַ⁠הִ֖יא מִ⁠תַּ֣חַת יָד֑⁠וֹ כִּ֣י עָזַ֔ב אֶת־יְהוָ֖ה אֱלֹהֵ֥י אֲבֹתָֽי⁠ו׃","wa⁠yi̇pĕşǎ֨ʻ ʼèd֜wòm mi⁠ţȧ֣ẖaţ yad-yĕhẇdá֗h ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h ʼá֣z ţi̇pĕşǎ֥ʻ libĕná֛h bá̇⁠ʻé֥ţ ha⁠hi֖yʼ mi⁠ţȧ֣ẖaţ yád֑⁠wò ki֣̇y ʻáza֔b ʼeţ-yĕhwá֖h ʼèlòhé֥y ʼàbòţáֽy⁠w׃"],[21,11,"גַּם־ה֥וּא עָשָֽׂה־בָמ֖וֹת בְּ⁠הָרֵ֣י יְהוּדָ֑ה וַ⁠יֶּ֨זֶן֙ אֶת־יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם וַ⁠יַּדַּ֖ח אֶת־יְהוּדָֽה׃פ","gȧm-h֥ẇʼ ʻáşáֽ̂h-bám֖wòţ bĕ̇⁠háré֣y yĕhẇdá֑h wa⁠yė֨zen֙ ʼeţ-yòşĕ̌bé֣y yĕrẇşá̌lia֔m wa⁠yȧdȧ֖ẖ ʼeţ-yĕhẇdáֽh׃p"],[21,12,"וַ⁠יָּבֹ֤א אֵלָי⁠ו֙ מִכְתָּ֔ב מֵֽ⁠אֵלִיָּ֥הוּ הַ⁠נָּבִ֖יא לֵ⁠אמֹ֑ר כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אֱלֹהֵי֙ דָּוִ֣יד אָבִ֔י⁠ךָ תַּ֗חַת אֲשֶׁ֤ר לֹֽא־הָלַ֨כְתָּ֙ בְּ⁠דַרְכֵי֙ יְהוֹשָׁפָ֣ט אָבִ֔י⁠ךָ וּ⁠בְ⁠דַרְכֵ֖י אָסָ֥א מֶֽלֶךְ־יְהוּדָֽה׃","wa⁠yá̇bò֤ʼ ʼéláy⁠w֙ mikĕţá̇֔b méֽ⁠ʼéliyá֥̇hẇ ha⁠ná̇bi֖yʼ lé⁠ʼmò֑r kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼèlòhéy֙ dá̇wi֣yd ʼábi֔y⁠ká ţȧ֗ẖaţ ʼàşě֤r lòֽʼ-hála֨kĕţá̇֙ bĕ̇⁠darĕkéy֙ yĕhwòşá̌pá֣t ʼábi֔y⁠ká ẇ⁠bĕ⁠darĕké֖y ʼásá֥ʼ meֽlekĕ-yĕhẇdáֽh׃"],[21,13,"וַ⁠תֵּ֗לֶךְ בְּ⁠דֶ֨רֶךְ֙ מַלְכֵ֣י יִשְׂרָאֵ֔ל וַ⁠תַּזְנֶ֤ה אֶת־יְהוּדָה֙ וְ⁠אֶת־יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם כְּ⁠הַזְנ֖וֹת בֵּ֣ית אַחְאָ֑ב וְ⁠גַ֨ם אֶת־אַחֶ֧י⁠ךָ בֵית־אָבִ֛י⁠ךָ הַ⁠טּוֹבִ֥ים מִמְּ⁠ךָ֖ הָרָֽגְתָּ׃","wa⁠ţé̇֗lekĕ bĕ̇⁠de֨rekĕ֙ malĕké֣y yişĕ̂ráʼé֔l wa⁠ţȧzĕne֤h ʼeţ-yĕhẇdáh֙ wĕ⁠ʼeţ-yòşĕ̌bé֣y yĕrẇşá̌lia֔m kĕ̇⁠hazĕn֖wòţ bé֣̇yţ ʼaẖĕʼá֑b wĕ⁠ga֨m ʼeţ-ʼaẖe֧y⁠ká béyţ-ʼábi֛y⁠ká ha⁠ṫwòbi֥ym mimĕ̇⁠ká֖ háráֽgĕţá̇׃"],[21,14,"הִנֵּ֣ה יְהוָ֗ה נֹגֵ֛ף מַגֵּפָ֥ה גְדוֹלָ֖ה בְּ⁠עַמֶּ֑⁠ךָ וּ⁠בְ⁠בָנֶ֥י⁠ךָ וּ⁠בְ⁠נָשֶׁ֖י⁠ךָ וּ⁠בְ⁠כָל־רְכוּשֶֽׁ⁠ךָ׃","hiné֣̇h yĕhwá֗h nògé֛p magé̇pá֥h gĕdwòlá֖h bĕ̇⁠ʻamė֑⁠ká ẇ⁠bĕ⁠báne֥y⁠ká ẇ⁠bĕ⁠náşě֖y⁠ká ẇ⁠bĕ⁠kál-rĕkẇşěֽ⁠ká׃"],[21,15,"וְ⁠אַתָּ֛ה בָּ⁠חֳלָיִ֥ים רַבִּ֖ים בְּ⁠מַחֲלֵ֣ה מֵעֶ֑י⁠ךָ עַד־יֵצְא֤וּ מֵעֶ֨י⁠ךָ֙ מִן־הַ⁠חֹ֔לִי יָמִ֖ים עַל־יָמִֽים׃","wĕ⁠ʼaţá֛̇h bá̇⁠ẖoláyi֥ym rabi֖̇ym bĕ̇⁠maẖàlé֣h méʻe֑y⁠ká ʻad-yéẕĕʼ֤ẇ méʻe֨y⁠ká֙ min-ha⁠ẖò֔liy yámi֖ym ʻal-yámiֽym׃"],[21,16,"וַ⁠יָּ֨עַר יְהוָ֜ה עַל־יְהוֹרָ֗ם אֵ֣ת ר֤וּחַ הַ⁠פְּלִשְׁתִּים֙ וְ⁠הָ֣⁠עַרְבִ֔ים אֲשֶׁ֖ר עַל־יַ֥ד כּוּשִֽׁים׃","wa⁠yá̇֨ʻar yĕhwá֜h ʻal-yĕhwòrá֗m ʼé֣ţ r֤ẇẖa ha⁠pĕ̇lişĕ̌ţi̇ym֙ wĕ⁠há֣⁠ʻarĕbi֔ym ʼàşě֖r ʻal-ya֥d k̇ẇşǐֽym׃"],[21,17,"וַ⁠יַּעֲל֤וּ בִֽ⁠יהוּדָה֙ וַ⁠יִּבְקָע֔וּ⁠הָ וַ⁠יִּשְׁבּ֗וּ אֵ֤ת כָּל־הָ⁠רְכוּשׁ֙ הַ⁠נִּמְצָ֣א לְ⁠בֵית־הַ⁠מֶּ֔לֶךְ וְ⁠גַם־בָּנָ֖י⁠ו וְ⁠נָשָׁ֑י⁠ו וְ⁠לֹ֤א נִשְׁאַר־ל⁠וֹ֙ בֵּ֔ן כִּ֥י אִם־יְהוֹאָחָ֖ז קְטֹ֥ן בָּנָֽי⁠ו׃","wa⁠yȧʻàl֤ẇ biֽ⁠yhẇdáh֙ wa⁠yi̇bĕqáʻ֔ẇ⁠há wa⁠yi̇şĕ̌ḃ֗ẇ ʼé֤ţ ká̇l-há⁠rĕkẇş̌֙ ha⁠ni̇mĕẕá֣ʼ lĕ⁠béyţ-ha⁠mė֔lekĕ wĕ⁠gam-bá̇ná֖y⁠w wĕ⁠náşá֑̌y⁠w wĕ⁠lò֤ʼ nişĕ̌ʼar-l⁠wò֙ bé̇֔n ki֥̇y ʼim-yĕhwòʼáẖá֖z qĕtò֥n bá̇náֽy⁠w׃"],[21,18,"וְ⁠אַחֲרֵ֖י כָּל־זֹ֑את נְגָפ֨⁠וֹ יְהוָ֧ה ׀ בְּ⁠מֵעָ֛י⁠ו לָ⁠חֳלִ֖י לְ⁠אֵ֥ין מַרְפֵּֽא׃","wĕ⁠ʼaẖàré֖y ká̇l-zò֑ʼţ nĕgáp֨⁠wò yĕhwá֧h ׀ bĕ̇⁠méʻá֛y⁠w lá⁠ẖoli֖y lĕ⁠ʼé֥yn marĕpéֽ̇ʼ׃"],[21,19,"וַ⁠יְהִ֣י לְ⁠יָמִ֣ים ׀ מִ⁠יָּמִ֡ים וּ⁠כְ⁠עֵת֩ צֵ֨את הַ⁠קֵּ֜ץ לְ⁠יָמִ֣ים שְׁנַ֗יִם יָצְא֤וּ מֵעָי⁠ו֙ עִם־חָלְי֔⁠וֹ וַ⁠יָּ֖מָת בְּ⁠תַחֲלֻאִ֣ים רָעִ֑ים וְ⁠לֹא־עָ֨שׂוּ ל֥⁠וֹ עַמּ֛⁠וֹ שְׂרֵפָ֖ה כִּ⁠שְׂרֵפַ֥ת אֲבֹתָֽי⁠ו׃","wa⁠yĕhi֣y lĕ⁠yámi֣ym ׀ mi⁠yá̇mi֡ym ẇ⁠kĕ⁠ʻéţ֩ ẕé֨ʼţ ha⁠qé̇֜ẕ lĕ⁠yámi֣ym şĕ̌na֗yim yáẕĕʼ֤ẇ méʻáy⁠w֙ ʻim-ẖálĕy֔⁠wò wa⁠yá֖̇máţ bĕ̇⁠ţaẖàluʼi֣ym ráʻi֑ym wĕ⁠lòʼ-ʻá֨ş̂ẇ l֥⁠wò ʻaṁ֛⁠wò şĕ̂répá֖h ki̇⁠şĕ̂répa֥ţ ʼàbòţáֽy⁠w׃"],[21,20,"בֶּן־שְׁלֹשִׁ֤ים וּ⁠שְׁתַּ֨יִם֙ הָיָ֣ה בְ⁠מָלְכ֔⁠וֹ וּ⁠שְׁמוֹנֶ֣ה שָׁנִ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יֵּ֨לֶךְ֙ בְּ⁠לֹ֣א חֶמְדָּ֔ה וַֽ⁠יִּקְבְּרֻ֨⁠הוּ֙ בְּ⁠עִ֣יר דָּוִ֔יד וְ⁠לֹ֖א בְּ⁠קִבְר֥וֹת הַ⁠מְּלָכִֽים׃","bėn-şĕ̌lòşǐ֤ym ẇ⁠şĕ̌ţȧ֨yim֙ háyá֣h bĕ⁠málĕk֔⁠wò ẇ⁠şĕ̌mwòne֣h şá̌ni֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wa⁠yé̇֨lekĕ֙ bĕ̇⁠lò֣ʼ ẖemĕdá̇֔h waֽ⁠yi̇qĕbĕ̇ru֨⁠hẇ֙ bĕ̇⁠ʻi֣yr dá̇wi֔yd wĕ⁠lò֖ʼ bĕ̇⁠qibĕr֥wòţ ha⁠mĕ̇lákiֽym׃"],[22,1,"וַ⁠יַּמְלִיכוּ֩ יוֹשְׁבֵ֨י יְרוּשָׁלִַ֜ם אֶת־אֲחַזְיָ֨הוּ בְנ֤⁠וֹ הַ⁠קָּטֹן֙ תַּחְתָּ֔י⁠ו כִּ֤י כָל־הָ⁠רִאשֹׁנִים֙ הָרַ֣ג הַ⁠גְּד֔וּד הַ⁠בָּ֥א בָֽ⁠עַרְבִ֖ים לַֽ⁠מַּחֲנֶ֑ה וַ⁠יִּמְלֹ֛ךְ אֲחַזְיָ֥הוּ בֶן־יְהוֹרָ֖ם מֶ֥לֶךְ יְהוּדָֽה׃פ","wa⁠yȧmĕliykẇ֩ ywòşĕ̌bé֨y yĕrẇşá̌lia֜m ʼeţ-ʼàẖazĕyá֨hẇ bĕn֤⁠wò ha⁠qá̇tòn֙ ţȧẖĕţá̇֔y⁠w ki֤̇y kál-há⁠riʼşò̌niym֙ hára֣g ha⁠gĕ̇d֔ẇd ha⁠bá֥̇ʼ báֽ⁠ʻarĕbi֖ym laֽ⁠mȧẖàne֑h wa⁠yi̇mĕlò֛kĕ ʼàẖazĕyá֥hẇ ben-yĕhwòrá֖m me֥lekĕ yĕhẇdáֽh׃p"],[22,2,"בֶּן־אַרְבָּעִ֨ים וּ⁠שְׁתַּ֤יִם שָׁנָה֙ אֲחַזְיָ֣הוּ בְ⁠מָלְכ֔⁠וֹ וְ⁠שָׁנָ֣ה אַחַ֔ת מָלַ֖ךְ בִּֽ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ עֲתַלְיָ֖הוּ בַּת־עָמְרִֽי׃","bėn-ʼarĕbá̇ʻi֨ym ẇ⁠şĕ̌ţȧ֤yim şá̌náh֙ ʼàẖazĕyá֣hẇ bĕ⁠málĕk֔⁠wò wĕ⁠şá̌ná֣h ʼaẖa֔ţ mála֖kĕ biֽ̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ʻàţalĕyá֖hẇ bȧţ-ʻámĕriֽy׃"],[22,3,"גַּם־ה֣וּא הָלַ֔ךְ בְּ⁠דַרְכֵ֖י בֵּ֣ית אַחְאָ֑ב כִּ֥י אִמּ֛⁠וֹ הָיְתָ֥ה יֽוֹעַצְתּ֖⁠וֹ לְ⁠הַרְשִֽׁיעַ׃","gȧm-h֣ẇʼ hála֔kĕ bĕ̇⁠darĕké֖y bé֣̇yţ ʼaẖĕʼá֑b ki֥̇y ʼiṁ֛⁠wò háyĕţá֥h yֽwòʻaẕĕţ֖̇⁠wò lĕ⁠harĕşǐֽyʻa׃"],[22,4,"וַ⁠יַּ֧עַשׂ הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה כְּ⁠בֵ֣ית אַחְאָ֑ב כִּי־הֵ֜מָּה הָֽיוּ־ל֣⁠וֹ יֽוֹעֲצִ֗ים אַחֲרֵ֛י מ֥וֹת אָבִ֖י⁠ו לְ⁠מַשְׁחִ֥ית לֽ⁠וֹ׃","wa⁠yȧ֧ʻaş̂ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h kĕ̇⁠bé֣yţ ʼaẖĕʼá֑b ki̇y-hé֜má̇h háֽyẇ-l֣⁠wò yֽwòʻàẕi֗ym ʼaẖàré֛y m֥wòţ ʼábi֖y⁠w lĕ⁠maşĕ̌ẖi֥yţ lֽ⁠wò׃"],[22,5,"גַּ֣ם בַּ⁠עֲצָתָ⁠ם֮ הָלַךְ֒ וַ⁠יֵּלֶךְ֩ אֶת־יְהוֹרָ֨ם בֶּן־אַחְאָ֜ב מֶ֣לֶךְ יִשְׂרָאֵ֗ל לַ⁠מִּלְחָמָ֛ה עַל־חֲזָאֵ֥ל מֶֽלֶךְ־אֲרָ֖ם בְּ⁠רָמ֣וֹת גִּלְעָ֑ד וַ⁠יַּכּ֥וּ הָֽ⁠רַמִּ֖ים אֶת־יוֹרָֽם׃","gȧ֣m bȧ⁠ʻàẕáţá⁠m֮ hálakĕ֒ wa⁠yé̇lekĕ֩ ʼeţ-yĕhwòrá֨m bėn-ʼaẖĕʼá֜b me֣lekĕ yişĕ̂ráʼé֗l la⁠mi̇lĕẖámá֛h ʻal-ẖàzáʼé֥l meֽlekĕ-ʼàrá֖m bĕ̇⁠rám֣wòţ gi̇lĕʻá֑d wa⁠yȧk֥̇ẇ háֽ⁠rami֖̇ym ʼeţ-ywòráֽm׃"],[22,6,"וַ⁠יָּ֜שָׁב לְ⁠הִתְרַפֵּ֣א בְ⁠יִזְרְעֶ֗אל כִּ֤י הַ⁠מַּכִּים֙ אֲשֶׁ֣ר הִכֻּ֣⁠הוּ בָֽ⁠רָמָ֔ה בְּ⁠הִלָּ֣חֲמ֔⁠וֹ אֶת־חֲזָהאֵ֖ל מֶ֣לֶךְ אֲרָ֑ם וַ⁠עֲזַרְיָ֨הוּ בֶן־יְהוֹרָ֜ם מֶ֣לֶךְ יְהוּדָ֗ה יָרַ֡ד לִ⁠רְא֞וֹת אֶת־יְהוֹרָ֧ם בֶּן־אַחְאָ֛ב בְּ⁠יִזְרְעֶ֖אל כִּי־חֹלֶ֥ה הֽוּא׃","wa⁠yá̇֜şá̌b lĕ⁠hiţĕrapé֣̇ʼ bĕ⁠yizĕrĕʻe֗ʼl ki֤̇y ha⁠mȧki̇ym֙ ʼàşě֣r hiku֣̇⁠hẇ báֽ⁠rámá֔h bĕ̇⁠hilá֣̇ẖàm֔⁠wò ʼeţ-ẖàzáhʼé֖l me֣lekĕ ʼàrá֑m wa⁠ʻàzarĕyá֨hẇ ben-yĕhwòrá֜m me֣lekĕ yĕhẇdá֗h yára֡d li⁠rĕʼ֞wòţ ʼeţ-yĕhwòrá֧m bėn-ʼaẖĕʼá֛b bĕ̇⁠yizĕrĕʻe֖ʼl ki̇y-ẖòle֥h hֽẇʼ׃"],[22,7,"וּ⁠מֵֽ⁠אֱלֹהִ֗ים הָיְתָה֙ תְּבוּסַ֣ת אֲחַזְיָ֔הוּ לָ⁠ב֖וֹא אֶל־יוֹרָ֑ם וּ⁠בְ⁠בֹא֗⁠וֹ יָצָ֤א עִם־יְהוֹרָם֙ אֶל־יֵה֣וּא בֶן־נִמְשִׁ֔י אֲשֶׁ֣ר מְשָׁח֣⁠וֹ יְהוָ֔ה לְ⁠הַכְרִ֖ית אֶת־בֵּ֥ית אַחְאָֽב׃","ẇ⁠méֽ⁠ʼèlòhi֗ym háyĕţáh֙ ţĕ̇bẇsa֣ţ ʼàẖazĕyá֔hẇ lá⁠b֖wòʼ ʼel-ywòrá֑m ẇ⁠bĕ⁠bòʼ֗⁠wò yáẕá֤ʼ ʻim-yĕhwòrám֙ ʼel-yéh֣ẇʼ ben-nimĕşǐ֔y ʼàşě֣r mĕşá̌ẖ֣⁠wò yĕhwá֔h lĕ⁠hakĕri֖yţ ʼeţ-bé֥̇yţ ʼaẖĕʼáֽb׃"],[22,8,"וַ⁠יְהִ֕י כְּ⁠הִשָּׁפֵ֥ט יֵה֖וּא עִם־בֵּ֣ית אַחְאָ֑ב וַ⁠יִּמְצָא֩ אֶת־שָׂרֵ֨י יְהוּדָ֜ה וּ⁠בְנֵ֨י אֲחֵ֧י אֲחַזְיָ֛הוּ מְשָׁרְתִ֥ים לַ⁠אֲחַזְיָ֖הוּ וַ⁠יַּהַרְגֵֽ⁠ם׃","wa⁠yĕhi֕y kĕ̇⁠hişá̇̌pé֥t yéh֖ẇʼ ʻim-bé֣̇yţ ʼaẖĕʼá֑b wa⁠yi̇mĕẕáʼ֩ ʼeţ-şá̂ré֨y yĕhẇdá֜h ẇ⁠bĕné֨y ʼàẖé֧y ʼàẖazĕyá֛hẇ mĕşá̌rĕţi֥ym la⁠ʼàẖazĕyá֖hẇ wa⁠yȧharĕgéֽ⁠m׃"],[22,9,"וַ⁠יְבַקֵּשׁ֩ אֶת־אֲחַזְיָ֨הוּ וַֽ⁠יִּלְכְּדֻ֜⁠הוּ וְ⁠ה֧וּא מִתְחַבֵּ֣א בְ⁠שֹֽׁמְר֗וֹן וַ⁠יְבִאֻ֣⁠הוּ אֶל־יֵהוּא֮ וַ⁠יְמִתֻ⁠הוּ֒ וַֽ⁠יִּקְבְּרֻ֔⁠הוּ כִּ֤י אָֽמְרוּ֙ בֶּן־יְהוֹשָׁפָ֣ט ה֔וּא אֲשֶׁר־דָּרַ֥שׁ אֶת־יְהוָ֖ה בְּ⁠כָל־לְבָב֑⁠וֹ וְ⁠אֵין֙ לְ⁠בֵ֣ית אֲחַזְיָ֔הוּ לַ⁠עְצֹ֥ר כֹּ֖חַ לְ⁠מַמְלָכָֽה׃","wa⁠yĕbaqé̇ş̌֩ ʼeţ-ʼàẖazĕyá֨hẇ waֽ⁠yi̇lĕkĕ̇du֜⁠hẇ wĕ⁠h֧ẇʼ miţĕẖabé֣̇ʼ bĕ⁠şòֽ̌mĕr֗wòn wa⁠yĕbiʼu֣⁠hẇ ʼel-yéhẇʼ֮ wa⁠yĕmiţu⁠hẇ֒ waֽ⁠yi̇qĕbĕ̇ru֔⁠hẇ ki֤̇y ʼáֽmĕrẇ֙ bėn-yĕhwòşá̌pá֣t h֔ẇʼ ʼàşěr-dá̇ra֥ş̌ ʼeţ-yĕhwá֖h bĕ̇⁠kál-lĕbáb֑⁠wò wĕ⁠ʼéyn֙ lĕ⁠bé֣yţ ʼàẖazĕyá֔hẇ la⁠ʻĕẕò֥r kò֖̇ẖa lĕ⁠mamĕlákáֽh׃"],[22,10,"וַ⁠עֲתַלְיָ֨הוּ֙ אֵ֣ם אֲחַזְיָ֔הוּ רָאֲתָ֖ה כִּ֣י מֵ֣ת בְּנָ֑⁠הּ וַ⁠תָּ֗קָם וַ⁠תְּדַבֵּ֛ר אֶת־כָּל־זֶ֥רַע הַ⁠מַּמְלָכָ֖ה לְ⁠בֵ֥ית יְהוּדָֽה׃","wa⁠ʻàţalĕyá֨hẇ֙ ʼé֣m ʼàẖazĕyá֔hẇ ráʼàţá֖h ki֣̇y mé֣ţ bĕ̇ná֑⁠ḣ wa⁠ţá̇֗qám wa⁠ţĕ̇dabé֛̇r ʼeţ-ká̇l-ze֥raʻ ha⁠mȧmĕláká֖h lĕ⁠bé֥yţ yĕhẇdáֽh׃"],[22,11,"וַ⁠תִּקַּח֩ יְהוֹשַׁבְעַ֨ת בַּת־הַ⁠מֶּ֜לֶךְ אֶת־יוֹאָ֣שׁ בֶּן־אֲחַזְיָ֗הוּ וַ⁠תִּגְנֹ֤ב אֹת⁠וֹ֙ מִ⁠תּ֤וֹךְ בְּנֵֽי־הַ⁠מֶּ֨לֶךְ֙ הַ⁠מּ֣וּמָתִ֔ים וַ⁠תִּתֵּ֥ן אֹת֛⁠וֹ וְ⁠אֶת־מֵֽינִקְתּ֖⁠וֹ בַּ⁠חֲדַ֣ר הַ⁠מִּטּ֑וֹת וַ⁠תַּסְתִּירֵ֡⁠הוּ יְהוֹשַׁבְעַ֣ת בַּת־הַ⁠מֶּ֣לֶךְ יְהוֹרָ֡ם אֵשֶׁת֩ יְהוֹיָדָ֨ע הַ⁠כֹּהֵ֜ן כִּ֣י הִיא֩ הָיְתָ֨ה אֲח֧וֹת אֲחַזְיָ֛הוּ מִ⁠פְּנֵ֥י עֲתַלְיָ֖הוּ וְ⁠לֹ֥א הֱמִיתָֽתְ⁠הוּ׃","wa⁠ţi̇qȧẖ֩ yĕhwòşǎbĕʻa֨ţ bȧţ-ha⁠mė֜lekĕ ʼeţ-ywòʼá֣ş̌ bėn-ʼàẖazĕyá֗hẇ wa⁠ţi̇gĕnò֤b ʼòţ⁠wò֙ mi⁠ţ֤̇wòkĕ bĕ̇néֽy-ha⁠mė֨lekĕ֙ ha⁠ṁ֣ẇmáţi֔ym wa⁠ţi̇ţé֥̇n ʼòţ֛⁠wò wĕ⁠ʼeţ-méֽyniqĕţ֖̇⁠wò bȧ⁠ẖàda֣r ha⁠mi̇ṫ֑wòţ wa⁠ţȧsĕţi̇yré֡⁠hẇ yĕhwòşǎbĕʻa֣ţ bȧţ-ha⁠mė֣lekĕ yĕhwòrá֡m ʼéşěţ֩ yĕhwòyádá֨ʻ ha⁠kò̇hé֜n ki֣̇y hiyʼ֩ háyĕţá֨h ʼàẖ֧wòţ ʼàẖazĕyá֛hẇ mi⁠pĕ̇né֥y ʻàţalĕyá֖hẇ wĕ⁠lò֥ʼ hèmiyţáֽţĕ⁠hẇ׃"],[22,12,"וַ⁠יְהִ֤י אִתָּ⁠ם֙ בְּ⁠בֵ֣ית הָֽ⁠אֱלֹהִ֔ים מִתְחַבֵּ֖א שֵׁ֣שׁ שָׁנִ֖ים וַ⁠עֲתַלְיָ֖ה מֹלֶ֥כֶת עַל־הָ⁠אָֽרֶץ׃פ","wa⁠yĕhi֤y ʼiţá̇⁠m֙ bĕ̇⁠bé֣yţ háֽ⁠ʼèlòhi֔ym miţĕẖabé֖̇ʼ şé֣̌ş̌ şá̌ni֖ym wa⁠ʻàţalĕyá֖h mòle֥keţ ʻal-há⁠ʼáֽreẕ׃p"],[23,1,"וּ⁠בַ⁠שָּׁנָ֨ה הַ⁠שְּׁבִעִ֜ית הִתְחַזַּ֣ק יְהוֹיָדָ֗ע וַ⁠יִּקַּ֣ח אֶת־שָׂרֵ֣י הַ⁠מֵּא֡וֹת לַ⁠עֲזַרְיָ֣הוּ בֶן־יְרֹחָ֡ם וּ⁠לְ⁠יִשְׁמָעֵ֣אל בֶּן־יְ֠הוֹחָנָן וְ⁠לַֽ⁠עֲזַרְיָ֨הוּ בֶן־עוֹבֵ֜ד וְ⁠אֶת־מַעֲשֵׂיָ֧הוּ בֶן־עֲדָיָ֛הוּ וְ⁠אֶת־אֱלִישָׁפָ֥ט בֶּן־זִכְרִ֖י עִמּ֥⁠וֹ בַ⁠בְּרִֽית׃","ẇ⁠ba⁠şá̇̌ná֨h ha⁠şĕ̇̌biʻi֜yţ hiţĕẖazȧ֣q yĕhwòyádá֗ʻ wa⁠yi̇qȧ֣ẖ ʼeţ-şá̂ré֣y ha⁠mé̇ʼ֡wòţ la⁠ʻàzarĕyá֣hẇ ben-yĕròẖá֡m ẇ⁠lĕ⁠yişĕ̌máʻé֣ʼl bėn-yĕ֠hwòẖánán wĕ⁠laֽ⁠ʻàzarĕyá֨hẇ ben-ʻwòbé֜d wĕ⁠ʼeţ-maʻàşé̂yá֧hẇ ben-ʻàdáyá֛hẇ wĕ⁠ʼeţ-ʼèliyşá̌pá֥t bėn-zikĕri֖y ʻiṁ֥⁠wò ba⁠bĕ̇riֽyţ׃"],[23,2,"וַ⁠יָּסֹ֨בּוּ֙ בִּֽ⁠יהוּדָ֔ה וַ⁠יִּקְבְּצ֤וּ אֶת־הַ⁠לְוִיִּם֙ מִ⁠כָּל־עָרֵ֣י יְהוּדָ֔ה וְ⁠רָאשֵׁ֥י הָ⁠אָב֖וֹת לְ⁠יִשְׂרָאֵ֑ל וַ⁠יָּבֹ֖אוּ אֶל־יְרוּשָׁלִָֽם׃","wa⁠yá̇sò֨ḃẇ֙ biֽ̇⁠yhẇdá֔h wa⁠yi̇qĕbĕ̇ẕ֤ẇ ʼeţ-ha⁠lĕwiyi̇m֙ mi⁠ká̇l-ʻáré֣y yĕhẇdá֔h wĕ⁠ráʼşé֥̌y há⁠ʼáb֖wòţ lĕ⁠yişĕ̂ráʼé֑l wa⁠yá̇bò֖ʼẇ ʼel-yĕrẇşá̌liáֽm׃"],[23,3,"וַ⁠יִּכְרֹ֨ת כָּל־הַ⁠קָּהָ֥ל בְּרִ֛ית בְּ⁠בֵ֥ית הָ⁠אֱלֹהִ֖ים עִם־הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ם הִנֵּ֤ה בֶן־הַ⁠מֶּ֨לֶךְ֙ יִמְלֹ֔ךְ כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה עַל־בְּנֵ֥י דָוִֽיד׃","wa⁠yi̇kĕrò֨ţ ká̇l-ha⁠qá̇há֥l bĕ̇ri֛yţ bĕ̇⁠bé֥yţ há⁠ʼèlòhi֖ym ʻim-ha⁠mė֑lekĕ wa⁠yò֣̇ʼmer lá⁠he֗m hiné֤̇h ben-ha⁠mė֨lekĕ֙ yimĕlò֔kĕ kȧ⁠ʼàşě֛r di̇bė֥r yĕhwá֖h ʻal-bĕ̇né֥y dáwiֽyd׃"],[23,4,"זֶ֥ה הַ⁠דָּבָ֖ר אֲשֶׁ֣ר תַּעֲשׂ֑וּ הַ⁠שְּׁלִשִׁ֨ית מִ⁠כֶּ֜ם בָּאֵ֣י הַ⁠שַּׁבָּ֗ת לַ⁠כֹּֽהֲנִים֙ וְ⁠לַ⁠לְוִיִּ֔ם לְ⁠שֹֽׁעֲרֵ֖י הַ⁠סִּפִּֽים׃","ze֥h ha⁠dá̇bá֖r ʼàşě֣r ţȧʻàş֑̂ẇ ha⁠şĕ̇̌lişǐ֨yţ mi⁠kė֜m bá̇ʼé֣y ha⁠şȧ̌bá̇֗ţ la⁠kòֽ̇hàniym֙ wĕ⁠la⁠lĕwiyi̇֔m lĕ⁠şòֽ̌ʻàré֖y ha⁠si̇piֽ̇ym׃"],[23,5,"וְ⁠הַ⁠שְּׁלִשִׁית֙ בְּ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠הַ⁠שְּׁלִשִׁ֖ית בְּ⁠שַׁ֣עַר הַ⁠יְס֑וֹד וְ⁠כָל־הָ⁠עָ֔ם בְּ⁠חַצְר֖וֹת בֵּ֥ית יְהוָֽה׃","wĕ⁠ha⁠şĕ̇̌lişǐyţ֙ bĕ̇⁠bé֣yţ ha⁠mė֔lekĕ wĕ⁠ha⁠şĕ̇̌lişǐ֖yţ bĕ̇⁠şǎ֣ʻar ha⁠yĕs֑wòd wĕ⁠kál-há⁠ʻá֔m bĕ̇⁠ẖaẕĕr֖wòţ bé֥̇yţ yĕhwáֽh׃"],[23,6,"וְ⁠אַל־יָב֣וֹא בֵית־יְהוָ֗ה כִּ֤י אִם־הַ⁠כֹּֽהֲנִים֙ וְ⁠הַ⁠מְשָׁרְתִ֣ים לַ⁠לְוִיִּ֔ם הֵ֥מָּה יָבֹ֖אוּ כִּי־קֹ֣דֶשׁ הֵ֑מָּה וְ⁠כָל־הָ⁠עָ֔ם יִשְׁמְר֖וּ מִשְׁמֶ֥רֶת יְהוָֽה׃","wĕ⁠ʼal-yáb֣wòʼ béyţ-yĕhwá֗h ki֤̇y ʼim-ha⁠kòֽ̇hàniym֙ wĕ⁠ha⁠mĕşá̌rĕţi֣ym la⁠lĕwiyi̇֔m hé֥má̇h yábò֖ʼẇ ki̇y-qò֣deş̌ hé֑má̇h wĕ⁠kál-há⁠ʻá֔m yişĕ̌mĕr֖ẇ mişĕ̌me֥reţ yĕhwáֽh׃"],[23,7,"וְ⁠הִקִּיפוּ֩ הַ⁠לְוִיִּ֨ם אֶת־הַ⁠מֶּ֜לֶךְ סָבִ֗יב אִ֚ישׁ וְ⁠כֵלָ֣י⁠ו בְּ⁠יָד֔⁠וֹ וְ⁠הַ⁠בָּ֥א אֶל־הַ⁠בַּ֖יִת יוּמָ֑ת וִֽ⁠הְי֥וּ אֶת־הַ⁠מֶּ֖לֶךְ בְּ⁠בֹא֥⁠וֹ וּ⁠בְ⁠צֵאתֽ⁠וֹ׃","wĕ⁠hiqi̇ypẇ֩ ha⁠lĕwiyi̇֨m ʼeţ-ha⁠mė֜lekĕ sábi֗yb ʼi֚yş̌ wĕ⁠kélá֣y⁠w bĕ̇⁠yád֔⁠wò wĕ⁠ha⁠bá֥̇ʼ ʼel-ha⁠bȧ֖yiţ yẇmá֑ţ wiֽ⁠hĕy֥ẇ ʼeţ-ha⁠mė֖lekĕ bĕ̇⁠bòʼ֥⁠wò ẇ⁠bĕ⁠ẕéʼţֽ⁠wò׃"],[23,8,"וַ⁠יַּעֲשׂ֨וּ הַ⁠לְוִיִּ֜ם וְ⁠כָל־יְהוּדָ֗ה כְּ⁠כֹ֣ל אֲשֶׁר־צִוָּה֮ יְהוֹיָדָ֣ע הַ⁠כֹּהֵן֒ וַ⁠יִּקְחוּ֙ אִ֣ישׁ אֶת־אֲנָשָׁ֔י⁠ו בָּאֵ֣י הַ⁠שַּׁבָּ֔ת עִ֖ם יוֹצְאֵ֣י הַ⁠שַּׁבָּ֑ת כִּ֣י לֹ֥א פָטַ֛ר יְהוֹיָדָ֥ע הַ⁠כֹּהֵ֖ן אֶת־הַֽ⁠מַּחְלְקֽוֹת׃","wa⁠yȧʻàş̂֨ẇ ha⁠lĕwiyi̇֜m wĕ⁠kál-yĕhẇdá֗h kĕ̇⁠kò֣l ʼàşěr-ẕiwá̇h֮ yĕhwòyádá֣ʻ ha⁠kò̇hén֒ wa⁠yi̇qĕẖẇ֙ ʼi֣yş̌ ʼeţ-ʼànáşá̌֔y⁠w bá̇ʼé֣y ha⁠şȧ̌bá̇֔ţ ʻi֖m ywòẕĕʼé֣y ha⁠şȧ̌bá֑̇ţ ki֣̇y lò֥ʼ páta֛r yĕhwòyádá֥ʻ ha⁠kò̇hé֖n ʼeţ-haֽ⁠mȧẖĕlĕqֽwòţ׃"],[23,9,"וַ⁠יִּתֵּן֩ יְהוֹיָדָ֨ע הַ⁠כֹּהֵ֜ן לְ⁠שָׂרֵ֣י הַ⁠מֵּא֗וֹת אֶת־הַֽ⁠חֲנִיתִים֙ וְ⁠אֶת־הַ⁠מָּגִנּוֹת֙ וְ⁠אֶת־הַ⁠שְּׁלָטִ֔ים אֲשֶׁ֖ר לַ⁠מֶּ֣לֶךְ דָּוִ֑יד אֲשֶׁ֖ר בֵּ֥ית הָ⁠אֱלֹהִֽים׃","wa⁠yi̇ţé̇n֩ yĕhwòyádá֨ʻ ha⁠kò̇hé֜n lĕ⁠şá̂ré֣y ha⁠mé̇ʼ֗wòţ ʼeţ-haֽ⁠ẖàniyţiym֙ wĕ⁠ʼeţ-ha⁠má̇giṅwòţ֙ wĕ⁠ʼeţ-ha⁠şĕ̇̌láti֔ym ʼàşě֖r la⁠mė֣lekĕ dá̇wi֑yd ʼàşě֖r bé֥̇yţ há⁠ʼèlòhiֽym׃"],[23,10,"וַ⁠יַּעֲמֵ֨ד אֶת־כָּל־הָ⁠עָ֜ם וְ⁠אִ֣ישׁ ׀ שִׁלְח֣⁠וֹ בְ⁠יָד֗⁠וֹ מִ⁠כֶּ֨תֶף הַ⁠בַּ֤יִת הַ⁠יְמָנִית֙ עַד־כֶּ֤תֶף הַ⁠בַּ֨יִת֙ הַ⁠שְּׂמָאלִ֔ית לַ⁠מִּזְבֵּ֖חַ וְ⁠לַ⁠בָּ֑יִת עַל־הַ⁠מֶּ֖לֶךְ סָבִֽיב׃","wa⁠yȧʻàmé֨d ʼeţ-ká̇l-há⁠ʻá֜m wĕ⁠ʼi֣yş̌ ׀ şǐlĕẖ֣⁠wò bĕ⁠yád֗⁠wò mi⁠kė֨ţep ha⁠bȧ֤yiţ ha⁠yĕmániyţ֙ ʻad-kė֤ţep ha⁠bȧ֨yiţ֙ ha⁠şĕ̇̂máʼli֔yţ la⁠mi̇zĕbé֖̇ẖa wĕ⁠la⁠bá֑̇yiţ ʻal-ha⁠mė֖lekĕ sábiֽyb׃"],[23,11,"וַ⁠יּוֹצִ֣יאוּ אֶת־בֶּן־הַ⁠מֶּ֗לֶךְ וַ⁠יִּתְּנ֤וּ עָלָי⁠ו֙ אֶת־הַ⁠נֵּ֨זֶר֙ וְ⁠אֶת־הָ֣⁠עֵד֔וּת וַ⁠יַּמְלִ֖יכוּ אֹת֑⁠וֹ וַ⁠יִּמְשָׁחֻ֨⁠הוּ֙ יְהוֹיָדָ֣ע וּ⁠בָנָ֔י⁠ו וַ⁠יֹּאמְר֖וּ יְחִ֥י הַ⁠מֶּֽלֶךְ׃ס","wa⁠ẏwòẕi֣yʼẇ ʼeţ-bėn-ha⁠mė֗lekĕ wa⁠yi̇ţĕ̇n֤ẇ ʻáláy⁠w֙ ʼeţ-ha⁠né̇֨zer֙ wĕ⁠ʼeţ-há֣⁠ʻéd֔ẇţ wa⁠yȧmĕli֖ykẇ ʼòţ֑⁠wò wa⁠yi̇mĕşá̌ẖu֨⁠hẇ֙ yĕhwòyádá֣ʻ ẇ⁠báná֔y⁠w wa⁠yò̇ʼmĕr֖ẇ yĕẖi֥y ha⁠mėֽlekĕ׃s"],[23,12,"וַ⁠תִּשְׁמַ֣ע עֲתַלְיָ֗הוּ אֶת־ק֤וֹל הָ⁠עָם֙ הָֽ⁠רָצִ֔ים וְ⁠הַֽ⁠מְהַֽלְלִ֖ים אֶת־הַ⁠מֶּ֑לֶךְ וַ⁠תָּב֥וֹא אֶל־הָ⁠עָ֖ם בֵּ֥ית יְהוָֽה׃","wa⁠ţi̇şĕ̌ma֣ʻ ʻàţalĕyá֗hẇ ʼeţ-q֤wòl há⁠ʻám֙ háֽ⁠ráẕi֔ym wĕ⁠haֽ⁠mĕhaֽlĕli֖ym ʼeţ-ha⁠mė֑lekĕ wa⁠ţá̇b֥wòʼ ʼel-há⁠ʻá֖m bé֥̇yţ yĕhwáֽh׃"],[23,13,"וַ⁠תֵּ֡רֶא וְ⁠הִנֵּ֣ה הַ⁠מֶּלֶךְ֩ עוֹמֵ֨ד עַֽל־עַמּוּד֜⁠וֹ בַּ⁠מָּב֗וֹא וְ⁠הַ⁠שָּׂרִ֣ים וְ⁠הַ⁠חֲצֹצְרוֹת֮ עַל־הַ⁠מֶּלֶךְ֒ וְ⁠כָל־עַ֨ם הָ⁠אָ֜רֶץ שָׂמֵ֗חַ וְ⁠תוֹקֵ֨עַ֙ בַּ⁠חֲצֹ֣צְר֔וֹת וְ⁠הַ⁠מְשֽׁוֹרֲרִים֙ בִּ⁠כְלֵ֣י הַ⁠שִּׁ֔יר וּ⁠מוֹדִיעִ֖ים לְ⁠הַלֵּ֑ל וַ⁠תִּקְרַ֤ע עֲתַלְיָ֨הוּ֙ אֶת־בְּגָדֶ֔י⁠הָ וַ⁠תֹּ֖אמֶר קֶ֥שֶׁר קָֽשֶׁר׃ס","wa⁠ţé̇֡reʼ wĕ⁠hiné֣̇h ha⁠mėlekĕ֩ ʻwòmé֨d ʻaֽl-ʻaṁẇd֜⁠wò bȧ⁠má̇b֗wòʼ wĕ⁠ha⁠şá̇̂ri֣ym wĕ⁠ha⁠ẖàẕòẕĕrwòţ֮ ʻal-ha⁠mėlekĕ֒ wĕ⁠kál-ʻa֨m há⁠ʼá֜reẕ şá̂mé֗ẖa wĕ⁠ţwòqé֨ʻa֙ bȧ⁠ẖàẕò֣ẕĕr֔wòţ wĕ⁠ha⁠mĕşֽ̌wòràriym֙ bi̇⁠kĕlé֣y ha⁠şi̇̌֔yr ẇ⁠mwòdiyʻi֖ym lĕ⁠halé֑̇l wa⁠ţi̇qĕra֤ʻ ʻàţalĕyá֨hẇ֙ ʼeţ-bĕ̇gáde֔y⁠há wa⁠ţò֖̇ʼmer qe֥şěr qáֽşěr׃s"],[23,14,"וַ⁠יּוֹצֵא֩ יְהוֹיָדָ֨ע הַ⁠כֹּהֵ֜ן אֶת־שָׂרֵ֥י הַ⁠מֵּא֣וֹת ׀ פְּקוּדֵ֣י הַ⁠חַ֗יִל וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ הֽוֹצִיא֨וּ⁠הָ֙ אֶל־מִ⁠בֵּ֣ית הַ⁠שְּׂדֵר֔וֹת וְ⁠הַ⁠בָּ֥א אַחֲרֶ֖י⁠הָ יוּמַ֣ת בֶּ⁠חָ֑רֶב כִּ֚י אָמַ֣ר הַ⁠כֹּהֵ֔ן לֹ֥א תְמִית֖וּ⁠הָ בֵּ֥ית יְהוָֽה׃","wa⁠ẏwòẕéʼ֩ yĕhwòyádá֨ʻ ha⁠kò̇hé֜n ʼeţ-şá̂ré֥y ha⁠mé̇ʼ֣wòţ ׀ pĕ̇qẇdé֣y ha⁠ẖa֗yil wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ hֽwòẕiyʼ֨ẇ⁠há֙ ʼel-mi⁠bé֣̇yţ ha⁠şĕ̇̂dér֔wòţ wĕ⁠ha⁠bá֥̇ʼ ʼaẖàre֖y⁠há yẇma֣ţ bė⁠ẖá֑reb ki֚̇y ʼáma֣r ha⁠kò̇hé֔n lò֥ʼ ţĕmiyţ֖ẇ⁠há bé֥̇yţ yĕhwáֽh׃"],[23,15,"וַ⁠יָּשִׂ֤ימוּ לָ⁠הּ֙ יָדַ֔יִם וַ⁠תָּב֛וֹא אֶל־מְב֥וֹא שַֽׁעַר־הַ⁠סּוּסִ֖ים בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יְמִית֖וּ⁠הָ שָֽׁם׃פ","wa⁠yá̇şî֤ymẇ lá⁠ḣ֙ yáda֔yim wa⁠ţá̇b֛wòʼ ʼel-mĕb֥wòʼ şǎֽʻar-ha⁠ṡẇsi֖ym bé֣̇yţ ha⁠mė֑lekĕ wa⁠yĕmiyţ֖ẇ⁠há şáֽ̌m׃p"],[23,16,"וַ⁠יִּכְרֹ֤ת יְהוֹיָדָע֙ בְּרִ֔ית בֵּינ֕⁠וֹ וּ⁠בֵ֥ין כָּל־הָ⁠עָ֖ם וּ⁠בֵ֣ין הַ⁠מֶּ֑לֶךְ לִ⁠הְי֥וֹת לְ⁠עָ֖ם לַ⁠יהוָֽה׃","wa⁠yi̇kĕrò֤ţ yĕhwòyádáʻ֙ bĕ̇ri֔yţ bé̇yn֕⁠wò ẇ⁠bé֥yn ká̇l-há⁠ʻá֖m ẇ⁠bé֣yn ha⁠mė֑lekĕ li⁠hĕy֥wòţ lĕ⁠ʻá֖m la⁠yhwáֽh׃"],[23,17,"וַ⁠יָּבֹ֨אוּ כָל־הָ⁠עָ֤ם בֵּית־הַ⁠בַּ֨עַל֙ וַֽ⁠יִּתְּצֻ֔⁠הוּ וְ⁠אֶת־מִזְבְּחֹתָ֥י⁠ו וְ⁠אֶת־צְלָמָ֖י⁠ו שִׁבֵּ֑רוּ וְ⁠אֵ֗ת מַתָּן֙ כֹּהֵ֣ן הַ⁠בַּ֔עַל הָרְג֖וּ לִ⁠פְנֵ֥י הַֽ⁠מִּזְבְּחֽוֹת׃","wa⁠yá̇bò֨ʼẇ kál-há⁠ʻá֤m bé̇yţ-ha⁠bȧ֨ʻal֙ waֽ⁠yi̇ţĕ̇ẕu֔⁠hẇ wĕ⁠ʼeţ-mizĕbĕ̇ẖòţá֥y⁠w wĕ⁠ʼeţ-ẕĕlámá֖y⁠w şǐbé֑̇rẇ wĕ⁠ʼé֗ţ maţá̇n֙ kò̇hé֣n ha⁠bȧ֔ʻal hárĕg֖ẇ li⁠pĕné֥y haֽ⁠mi̇zĕbĕ̇ẖֽwòţ׃"],[23,18,"וַ⁠יָּשֶׂם֩ יְהוֹיָדָ֨ע פְּקֻדֹּ֜ת בֵּ֣ית יְהוָ֗ה בְּ⁠יַ֨ד הַ⁠כֹּהֲנִ֣ים הַ⁠לְוִיִּם֮ אֲשֶׁ֣ר חָלַ֣ק דָּוִיד֮ עַל־בֵּ֣ית יְהוָה֒ לְֽ⁠הַעֲל֞וֹת עֹל֣וֹת יְהוָ֗ה כַּ⁠כָּת֛וּב בְּ⁠תוֹרַ֥ת מֹשֶׁ֖ה בְּ⁠שִׂמְחָ֣ה וּ⁠בְ⁠שִׁ֑יר עַ֖ל יְדֵ֥י דָוִֽיד׃","wa⁠yá̇şêm֩ yĕhwòyádá֨ʻ pĕ̇qudò̇֜ţ bé֣̇yţ yĕhwá֗h bĕ̇⁠ya֨d ha⁠kò̇hàni֣ym ha⁠lĕwiyi̇m֮ ʼàşě֣r ẖála֣q dá̇wiyd֮ ʻal-bé֣̇yţ yĕhwáh֒ lĕֽ⁠haʻàl֞wòţ ʻòl֣wòţ yĕhwá֗h kȧ⁠ká̇ţ֛ẇb bĕ̇⁠ţwòra֥ţ mòşě֖h bĕ̇⁠şîmĕẖá֣h ẇ⁠bĕ⁠şǐ֑yr ʻa֖l yĕdé֥y dáwiֽyd׃"],[23,19,"וַֽ⁠יַּעֲמֵד֙ הַ⁠שּׁ֣וֹעֲרִ֔ים עַֽל־שַׁעֲרֵ֖י בֵּ֣ית יְהוָ֑ה וְ⁠לֹֽא־יָבֹ֥א טָמֵ֖א לְ⁠כָל־דָּבָֽר׃","waֽ⁠yȧʻàméd֙ ha⁠ş֣̇̌wòʻàri֔ym ʻaֽl-şǎʻàré֖y bé֣̇yţ yĕhwá֑h wĕ⁠lòֽʼ-yábò֥ʼ támé֖ʼ lĕ⁠kál-dá̇báֽr׃"],[23,20,"וַ⁠יִּקַּ֣ח אֶת־שָׂרֵ֣י הַ⁠מֵּא֡וֹת וְ⁠אֶת־הָֽ⁠אַדִּירִים֩ וְ⁠אֶת־הַ⁠מּֽוֹשְׁלִ֨ים בָּ⁠עָ֜ם וְ⁠אֵ֣ת ׀ כָּל־עַ֣ם הָ⁠אָ֗רֶץ וַ⁠יּ֤וֹרֶד אֶת־הַ⁠מֶּ֨לֶךְ֙ מִ⁠בֵּ֣ית יְהוָ֔ה וַ⁠יָּבֹ֛אוּ בְּ⁠תֽוֹךְ־שַׁ֥עַר הָֽ⁠עֶלְי֖וֹן בֵּ֣ית הַ⁠מֶּ֑לֶךְ וַ⁠יּוֹשִׁ֨יבוּ֙ אֶת־הַ⁠מֶּ֔לֶךְ עַ֖ל כִּסֵּ֥א הַ⁠מַּמְלָכָֽה׃","wa⁠yi̇qȧ֣ẖ ʼeţ-şá̂ré֣y ha⁠mé̇ʼ֡wòţ wĕ⁠ʼeţ-háֽ⁠ʼadi̇yriym֩ wĕ⁠ʼeţ-ha⁠ṁֽwòşĕ̌li֨ym bá̇⁠ʻá֜m wĕ⁠ʼé֣ţ ׀ ká̇l-ʻa֣m há⁠ʼá֗reẕ wa⁠ẏ֤wòred ʼeţ-ha⁠mė֨lekĕ֙ mi⁠bé֣̇yţ yĕhwá֔h wa⁠yá̇bò֛ʼẇ bĕ̇⁠ţֽwòkĕ-şǎ֥ʻar háֽ⁠ʻelĕy֖wòn bé֣̇yţ ha⁠mė֑lekĕ wa⁠ẏwòşǐ֨ybẇ֙ ʼeţ-ha⁠mė֔lekĕ ʻa֖l ki̇sé֥̇ʼ ha⁠mȧmĕlákáֽh׃"],[23,21,"וַ⁠יִּשְׂמְח֥וּ כָל־עַם־הָ⁠אָ֖רֶץ וְ⁠הָ⁠עִ֣יר שָׁקָ֑טָה וְ⁠אֶת־עֲתַלְיָ֖הוּ הֵמִ֥יתוּ בֶ⁠חָֽרֶב׃ס","wa⁠yi̇şĕ̂mĕẖ֥ẇ kál-ʻam-há⁠ʼá֖reẕ wĕ⁠há⁠ʻi֣yr şá̌qá֑táh wĕ⁠ʼeţ-ʻàţalĕyá֖hẇ hémi֥yţẇ be⁠ẖáֽreb׃s"],[24,1,"בֶּן־שֶׁ֤בַע שָׁנִים֙ יֹאָ֣שׁ בְּ⁠מָלְכ֔⁠וֹ וְ⁠אַרְבָּעִ֣ים שָׁנָ֔ה מָלַ֖ךְ בִּֽ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ צִבְיָ֖ה מִ⁠בְּאֵ֥ר שָֽׁבַע׃","bėn-şě֤baʻ şá̌niym֙ yòʼá֣ş̌ bĕ̇⁠málĕk֔⁠wò wĕ⁠ʼarĕbá̇ʻi֣ym şá̌ná֔h mála֖kĕ biֽ̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ẕibĕyá֖h mi⁠bĕ̇ʼé֥r şáֽ̌baʻ׃"],[24,2,"וַ⁠יַּ֧עַשׂ יוֹאָ֛שׁ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כָּל־יְמֵ֖י יְהוֹיָדָ֥ע הַ⁠כֹּהֵֽן׃","wa⁠yȧ֧ʻaş̂ ywòʼá֛ş̌ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h ká̇l-yĕmé֖y yĕhwòyádá֥ʻ ha⁠kò̇héֽn׃"],[24,3,"וַ⁠יִּשָּׂא־ל֥⁠וֹ יְהוֹיָדָ֖ע נָשִׁ֣ים שְׁתָּ֑יִם וַ⁠יּ֖וֹלֶד בָּנִ֥ים וּ⁠בָנֽוֹת׃","wa⁠yi̇şá̇̂ʼ-l֥⁠wò yĕhwòyádá֖ʻ náşǐ֣ym şĕ̌ţá֑̇yim wa⁠ẏ֖wòled bá̇ni֥ym ẇ⁠bánֽwòţ׃"],[24,4,"וַ⁠יְהִ֖י אַחֲרֵי כֵ֑ן הָיָה֙ עִם־לֵ֣ב יוֹאָ֔שׁ לְ⁠חַדֵּ֖שׁ אֶת־בֵּ֥ית יְהוָֽה׃","wa⁠yĕhi֖y ʼaẖàréy ké֑n háyáh֙ ʻim-lé֣b ywòʼá֔ş̌ lĕ⁠ẖadé֖̇ş̌ ʼeţ-bé֥̇yţ yĕhwáֽh׃"],[24,5,"וַ⁠יִּקְבֹּץ֮ אֶת־הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּם֒ וַ⁠יֹּ֣אמֶר לָ⁠הֶ֡ם צְא֣וּ לְ⁠עָרֵ֪י יְהוּדָ֟ה וְ⁠קִבְצוּ֩ מִ⁠כָּל־יִשְׂרָאֵ֨ל כֶּ֜סֶף לְ⁠חַזֵּ֣ק ׀ אֶת־בֵּ֣ית אֱלֹֽהֵי⁠כֶ֗ם מִ⁠דֵּ֤י שָׁנָה֙ בְּ⁠שָׁנָ֔ה וְ⁠אַתֶּ֖ם תְּמַהֲר֣וּ לַ⁠דָּבָ֑ר וְ⁠לֹ֥א מִֽהֲר֖וּ הַֽ⁠לְוִיִּֽם׃","wa⁠yi̇qĕbò̇ẕ֮ ʼeţ-ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇m֒ wa⁠yò֣̇ʼmer lá⁠he֡m ẕĕʼ֣ẇ lĕ⁠ʻáré֪y yĕhẇdá֟h wĕ⁠qibĕẕẇ֩ mi⁠ká̇l-yişĕ̂ráʼé֨l kė֜sep lĕ⁠ẖazé֣̇q ׀ ʼeţ-bé֣̇yţ ʼèlòֽhéy⁠ke֗m mi⁠dé֤̇y şá̌náh֙ bĕ̇⁠şá̌ná֔h wĕ⁠ʼaţė֖m ţĕ̇mahàr֣ẇ la⁠dá̇bá֑r wĕ⁠lò֥ʼ miֽhàr֖ẇ haֽ⁠lĕwiyiֽ̇m׃"],[24,6,"וַ⁠יִּקְרָ֣א הַ⁠מֶּלֶךְ֮ לִֽ⁠יהוֹיָדָ֣ע הָ⁠רֹאשׁ֒ וַ⁠יֹּ֣אמֶר ל֗⁠וֹ מַדּ֨וּעַ֙ לֹֽא־דָרַ֣שְׁתָּ עַל־הַ⁠לְוִיִּ֔ם לְ⁠הָבִ֞יא מִֽ⁠יהוּדָ֣ה וּ⁠מִֽ⁠ירוּשָׁלִַ֗ם אֶת־מַשְׂאַת֙ מֹשֶׁ֣ה עֶֽבֶד־יְהוָ֔ה וְ⁠הַ⁠קָּהָ֖ל לְ⁠יִשְׂרָאֵ֑ל לְ⁠אֹ֖הֶל הָ⁠עֵדֽוּת׃","wa⁠yi̇qĕrá֣ʼ ha⁠mėlekĕ֮ liֽ⁠yhwòyádá֣ʻ há⁠ròʼş̌֒ wa⁠yò֣̇ʼmer l֗⁠wò maḋ֨ẇʻa֙ lòֽʼ-dára֣şĕ̌ţá̇ ʻal-ha⁠lĕwiyi̇֔m lĕ⁠hábi֞yʼ miֽ⁠yhẇdá֣h ẇ⁠miֽ⁠yrẇşá̌lia֗m ʼeţ-maşĕ̂ʼaţ֙ mòşě֣h ʻeֽbed-yĕhwá֔h wĕ⁠ha⁠qá̇há֖l lĕ⁠yişĕ̂ráʼé֑l lĕ⁠ʼò֖hel há⁠ʻédֽẇţ׃"],[24,7,"כִּ֤י עֲתַלְיָ֨הוּ֙ הַ⁠מִּרְשַׁ֔עַת בָּנֶ֥י⁠הָ פָרְצ֖וּ אֶת־בֵּ֣ית הָ⁠אֱלֹהִ֑ים וְ⁠גַם֙ כָּל־קָדְשֵׁ֣י בֵית־יְהוָ֔ה עָשׂ֖וּ לַ⁠בְּעָלִֽים׃","ki֤̇y ʻàţalĕyá֨hẇ֙ ha⁠mi̇rĕşǎ֔ʻaţ bá̇ne֥y⁠há párĕẕ֖ẇ ʼeţ-bé֣̇yţ há⁠ʼèlòhi֑ym wĕ⁠gam֙ ká̇l-qádĕşé֣̌y béyţ-yĕhwá֔h ʻáş֖̂ẇ la⁠bĕ̇ʻáliֽym׃"],[24,8,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ וַֽ⁠יַּעֲשׂ֖וּ אֲר֣וֹן אֶחָ֑ד וַֽ⁠יִּתְּנֻ֛⁠הוּ בְּ⁠שַׁ֥עַר בֵּית־יְהוָ֖ה חֽוּצָ⁠ה׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ waֽ⁠yȧʻàş֖̂ẇ ʼàr֣wòn ʼeẖá֑d waֽ⁠yi̇ţĕ̇nu֛⁠hẇ bĕ̇⁠şǎ֥ʻar bé̇yţ-yĕhwá֖h ẖֽẇẕá⁠h׃"],[24,9,"וַ⁠יִּתְּנוּ־ק֞וֹל בִּֽ⁠יהוּדָ֣ה וּ⁠בִֽ⁠ירוּשָׁלִַ֗ם לְ⁠הָבִ֤יא לַֽ⁠יהוָה֙ מַשְׂאַ֞ת מֹשֶׁ֧ה עֶֽבֶד־הָ⁠אֱלֹהִ֛ים עַל־יִשְׂרָאֵ֖ל בַּ⁠מִּדְבָּֽר׃","wa⁠yi̇ţĕ̇nẇ-q֞wòl biֽ̇⁠yhẇdá֣h ẇ⁠biֽ⁠yrẇşá̌lia֗m lĕ⁠hábi֤yʼ laֽ⁠yhwáh֙ maşĕ̂ʼa֞ţ mòşě֧h ʻeֽbed-há⁠ʼèlòhi֛ym ʻal-yişĕ̂ráʼé֖l bȧ⁠mi̇dĕbáֽ̇r׃"],[24,10,"וַ⁠יִּשְׂמְח֥וּ כָל־הַ⁠שָּׂרִ֖ים וְ⁠כָל־הָ⁠עָ֑ם וַ⁠יָּבִ֛יאוּ וַ⁠יַּשְׁלִ֥יכוּ לָ⁠אָר֖וֹן עַד־לְ⁠כַלֵּֽה׃","wa⁠yi̇şĕ̂mĕẖ֥ẇ kál-ha⁠şá̇̂ri֖ym wĕ⁠kál-há⁠ʻá֑m wa⁠yá̇bi֛yʼẇ wa⁠yȧşĕ̌li֥ykẇ lá⁠ʼár֖wòn ʻad-lĕ⁠kaléֽ̇h׃"],[24,11,"וַ⁠יְהִ֡י בְּ⁠עֵת֩ יָבִ֨יא אֶת־הָֽ⁠אָר֜וֹן אֶל־פְּקֻדַּ֣ת הַ⁠מֶּלֶךְ֮ בְּ⁠יַ֣ד הַ⁠לְוִיִּם֒ וְ⁠כִ⁠רְאוֹתָ֞⁠ם כִּי־רַ֣ב הַ⁠כֶּ֗סֶף וּ⁠בָ֨א סוֹפֵ֤ר הַ⁠מֶּ֨לֶךְ֙ וּ⁠פְקִיד֙ כֹּהֵ֣ן הָ⁠רֹ֔אשׁ וִ⁠יעָ֨רוּ֙ אֶת־הָ֣⁠אָר֔וֹן וְ⁠יִשָּׂאֻ֖⁠הוּ וִֽ⁠ישִׁיבֻ֣⁠הוּ אֶל־מְקֹמ֑⁠וֹ כֹּ֤ה עָשׂוּ֙ לְ⁠י֣וֹם ׀ בְּ⁠י֔וֹם וַ⁠יַּֽאַסְפוּ־כֶ֖סֶף לָ⁠רֹֽב׃","wa⁠yĕhi֡y bĕ̇⁠ʻéţ֩ yábi֨yʼ ʼeţ-hֽá⁠ʼár֜wòn ʼel-pĕ̇qudȧ֣ţ ha⁠mėlekĕ֮ bĕ̇⁠ya֣d ha⁠lĕwiyi̇m֒ wĕ⁠ki⁠rĕʼwòţá֞⁠m ki̇y-ra֣b ha⁠kė֗sep ẇ⁠bá֨ʼ swòpé֤r ha⁠mė֨lekĕ֙ ẇ⁠pĕqiyd֙ kò̇hé֣n há⁠rò֔ʼş̌ wi⁠yʻá֨rẇ֙ ʼeţ-há֣⁠ʼár֔wòn wĕ⁠yişá̇̂ʼu֖⁠hẇ wiֽ⁠yşǐybu֣⁠hẇ ʼel-mĕqòm֑⁠wò kò֤̇h ʻáş̂ẇ֙ lĕ⁠y֣wòm ׀ bĕ̇⁠y֔wòm wa⁠yȧֽʼasĕpẇ-ke֖sep lá⁠ròֽb׃"],[24,12,"וַ⁠יִּתְּנֵ֨⁠הוּ הַ⁠מֶּ֜לֶךְ וִֽ⁠יהוֹיָדָ֗ע אֶל־עוֹשֵׂה֙ מְלֶ֨אכֶת֙ עֲבוֹדַ֣ת בֵּית־יְהוָ֔ה וַ⁠יִּֽהְי֤וּ שֹׂכְרִים֙ חֹצְבִ֣ים וְ⁠חָרָשִׁ֔ים לְ⁠חַדֵּ֖שׁ בֵּ֣ית יְהוָ֑ה וְ֠⁠גַם לְ⁠חָרָשֵׁ֤י בַרְזֶל֙ וּ⁠נְחֹ֔שֶׁת לְ⁠חַזֵּ֖ק אֶת־בֵּ֥ית יְהוָֽה׃","wa⁠yi̇ţĕ̇né֨⁠hẇ ha⁠mė֜lekĕ wiֽ⁠yhwòyádá֗ʻ ʼel-ʻwòşé̂h֙ mĕle֨ʼkeţ֙ ʻàbwòda֣ţ bé̇yţ-yĕhwá֔h wa⁠yiֽ̇hĕy֤ẇ şò̂kĕriym֙ ẖòẕĕbi֣ym wĕ⁠ẖáráşǐ֔ym lĕ⁠ẖadé֖̇ş̌ bé֣̇yţ yĕhwá֑h wĕ֠⁠gam lĕ⁠ẖáráşé֤̌y barĕzel֙ ẇ⁠nĕẖò֔şěţ lĕ⁠ẖazé֖̇q ʼeţ-bé֥̇yţ yĕhwáֽh׃"],[24,13,"וַֽ⁠יַּעֲשׂוּ֙ עֹשֵׂ֣י הַ⁠מְּלָאכָ֔ה וַ⁠תַּ֧עַל אֲרוּכָ֛ה לַ⁠מְּלָאכָ֖ה בְּ⁠יָדָ֑⁠ם וַֽ⁠יַּעֲמִ֜ידוּ אֶת־בֵּ֧ית הָֽ⁠אֱלֹהִ֛ים עַל־מַתְכֻּנְתּ֖⁠וֹ וַֽ⁠יְאַמְּצֻֽ⁠הוּ׃","waֽ⁠yȧʻàş̂ẇ֙ ʻòşé֣̂y ha⁠mĕ̇láʼká֔h wa⁠ţȧ֧ʻal ʼàrẇká֛h la⁠mĕ̇láʼká֖h bĕ̇⁠yádá֑⁠m waֽ⁠yȧʻàmi֜ydẇ ʼeţ-bé֧̇yţ háֽ⁠ʼèlòhi֛ym ʻal-maţĕku̇nĕţ֖̇⁠wò waֽ⁠yĕʼamĕ̇ẕuֽ⁠hẇ׃"],[24,14,"וּֽ⁠כְ⁠כַלּוֹתָ֡⁠ם הֵבִ֣יאוּ לִ⁠פְנֵי֩ הַ⁠מֶּ֨לֶךְ וִֽ⁠יהוֹיָדָ֜ע אֶת־שְׁאָ֣ר הַ⁠כֶּ֗סֶף וַ⁠יַּעֲשֵׂ֨⁠הוּ כֵלִ֤ים לְ⁠בֵית־יְהוָה֙ כְּלֵ֣י שָׁרֵ֔ת וְ⁠הַעֲל֣וֹת וְ⁠כַפּ֔וֹת וּ⁠כְלֵ֥י זָהָ֖ב וָ⁠כָ֑סֶף וַ֠⁠יִּֽהְיוּ מַעֲלִ֨ים עֹל֤וֹת בְּ⁠בֵית־יְהוָה֙ תָּמִ֔יד כֹּ֖ל יְמֵ֥י יְהוֹיָדָֽע׃פ","ẇֽ⁠kĕ⁠kal̇wòţá֡⁠m hébi֣yʼẇ li⁠pĕnéy֩ ha⁠mė֨lekĕ wiֽ⁠yhwòyádá֜ʻ ʼeţ-şĕ̌ʼá֣r ha⁠kė֗sep wa⁠yȧʻàşé̂֨⁠hẇ kéli֤ym lĕ⁠béyţ-yĕhwáh֙ kĕ̇lé֣y şá̌ré֔ţ wĕ⁠haʻàl֣wòţ wĕ⁠kaṗ֔wòţ ẇ⁠kĕlé֥y záhá֖b wá⁠ká֑sep wa֠⁠yiֽ̇hĕyẇ maʻàli֨ym ʻòl֤wòţ bĕ̇⁠béyţ-yĕhwáh֙ ţá̇mi֔yd kò֖̇l yĕmé֥y yĕhwòyádáֽʻ׃p"],[24,15,"וַ⁠יִּזְקַ֧ן יְהוֹיָדָ֛ע וַ⁠יִּשְׂבַּ֥ע יָמִ֖ים וַ⁠יָּמֹ֑ת בֶּן־מֵאָ֧ה וּ⁠שְׁלֹשִׁ֛ים שָׁנָ֖ה בְּ⁠מוֹתֽ⁠וֹ׃","wa⁠yi̇zĕqa֧n yĕhwòyádá֛ʻ wa⁠yi̇şĕ̂bȧ֥ʻ yámi֖ym wa⁠yá̇mò֑ţ bėn-méʼá֧h ẇ⁠şĕ̌lòşǐ֛ym şá̌ná֖h bĕ̇⁠mwòţֽ⁠wò׃"],[24,16,"וַ⁠יִּקְבְּרֻ֥⁠הוּ בְ⁠עִיר־דָּוִ֖יד עִם־הַ⁠מְּלָכִ֑ים כִּֽי־עָשָׂ֤ה טוֹבָה֙ בְּ⁠יִשְׂרָאֵ֔ל וְ⁠עִ֥ם הָ⁠אֱלֹהִ֖ים וּ⁠בֵיתֽ⁠וֹ׃ס","wa⁠yi̇qĕbĕ̇ru֥⁠hẇ bĕ⁠ʻiyr-dá̇wi֖yd ʻim-ha⁠mĕ̇láki֑ym kiֽ̇y-ʻáşá֤̂h twòbáh֙ bĕ̇⁠yişĕ̂ráʼé֔l wĕ⁠ʻi֥m há⁠ʼèlòhi֖ym ẇ⁠béyţֽ⁠wò׃s"],[24,17,"וְ⁠אַֽחֲרֵ֥י מוֹת֙ יְה֣וֹיָדָ֔ע בָּ֚אוּ שָׂרֵ֣י יְהוּדָ֔ה וַ⁠יִּֽשְׁתַּחֲו֖וּ לַ⁠מֶּ֑לֶךְ אָ֛ז שָׁמַ֥ע הַ⁠מֶּ֖לֶךְ אֲלֵי⁠הֶֽם׃","wĕ⁠ʼaֽẖàré֥y mwòţ֙ yĕh֣wòyádá֔ʻ bá֚̇ʼẇ şá̂ré֣y yĕhẇdá֔h wa⁠yiֽ̇şĕ̌ţȧẖàw֖ẇ la⁠mė֑lekĕ ʼá֛z şá̌ma֥ʻ ha⁠mė֖lekĕ ʼàléy⁠heֽm׃"],[24,18,"וַ⁠יַּֽעַזְב֗וּ אֶת־בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י אֲבוֹתֵי⁠הֶ֔ם וַ⁠יַּֽעַבְד֥וּ אֶת־הָ⁠אֲשֵׁרִ֖ים וְ⁠אֶת־הָֽ⁠עֲצַבִּ֑ים וַֽ⁠יְהִי־קֶ֗צֶף עַל־יְהוּדָה֙ וִ⁠יר֣וּשָׁלִַ֔ם בְּ⁠אַשְׁמָתָ֖⁠ם זֹֽאת׃","wa⁠yȧֽʻazĕb֗ẇ ʼeţ-bé֤̇yţ yĕhwáh֙ ʼèlòhé֣y ʼàbwòţéy⁠he֔m wa⁠yȧֽʻabĕd֥ẇ ʼeţ-há⁠ʼàşé̌ri֖ym wĕ⁠ʼeţ-háֽ⁠ʻàẕabi֑̇ym waֽ⁠yĕhiy-qe֗ẕep ʻal-yĕhẇdáh֙ wi⁠yr֣ẇşá̌lia֔m bĕ̇⁠ʼaşĕ̌máţá֖⁠m zòֽʼţ׃"],[24,19,"וַ⁠יִּשְׁלַ֤ח בָּ⁠הֶם֙ נְבִאִ֔ים לַ⁠הֲשִׁיבָ֖⁠ם אֶל־יְהוָ֑ה וַ⁠יָּעִ֥ידוּ בָ֖⁠ם וְ⁠לֹ֥א הֶאֱזִֽינוּ׃ס","wa⁠yi̇şĕ̌la֤ẖ bá̇⁠hem֙ nĕbiʼi֔ym la⁠hàşǐybá֖⁠m ʼel-yĕhwá֑h wa⁠yá̇ʻi֥ydẇ bá֖⁠m wĕ⁠lò֥ʼ heʼèziֽynẇ׃s"],[24,20,"וְ⁠ר֣וּחַ אֱלֹהִ֗ים לָֽבְשָׁה֙ אֶת־זְכַרְיָה֙ בֶּן־יְהוֹיָדָ֣ע הַ⁠כֹּהֵ֔ן וַֽ⁠יַּעֲמֹ֖ד מֵ⁠עַ֣ל לָ⁠עָ֑ם וַ⁠יֹּ֨אמֶר לָ⁠הֶ֜ם כֹּ֣ה ׀ אָמַ֣ר הָ⁠אֱלֹהִ֗ים לָ⁠מָה֩ אַתֶּ֨ם עֹבְרִ֜ים אֶת־מִצְוֺ֤ת יְהוָה֙ וְ⁠לֹ֣א תַצְלִ֔יחוּ כִּֽי־עֲזַבְתֶּ֥ם אֶת־יְהוָ֖ה וַ⁠יַּֽעֲזֹ֥ב אֶתְ⁠כֶֽם׃","wĕ⁠r֣ẇẖa ʼèlòhi֗ym láֽbĕşá̌h֙ ʼeţ-zĕkarĕyáh֙ bėn-yĕhwòyádá֣ʻ ha⁠kò̇hé֔n waֽ⁠yȧʻàmò֖d mé⁠ʻa֣l lá⁠ʻá֑m wa⁠yò̇֨ʼmer lá⁠he֜m kò֣̇h ׀ ʼáma֣r há⁠ʼèlòhi֗ym lá⁠máh֩ ʼaţė֨m ʻòbĕri֜ym ʼeţ-miẕĕwֺ֤ţ yĕhwáh֙ wĕ⁠lò֣ʼ ţaẕĕli֔yẖẇ kiֽ̇y-ʻàzabĕţė֥m ʼeţ-yĕhwá֖h wa⁠yȧֽʻàzò֥b ʼeţĕ⁠keֽm׃"],[24,21,"וַ⁠יִּקְשְׁר֣וּ עָלָ֔י⁠ו וַ⁠יִּרְגְּמֻ֥⁠הוּ אֶ֖בֶן בְּ⁠מִצְוַ֣ת הַ⁠מֶּ֑לֶךְ בַּ⁠חֲצַ֖ר בֵּ֥ית יְהוָֽה׃","wa⁠yi̇qĕşĕ̌r֣ẇ ʻálá֔y⁠w wa⁠yi̇rĕgĕ̇mu֥⁠hẇ ʼe֖ben bĕ̇⁠miẕĕwa֣ţ ha⁠mė֑lekĕ bȧ⁠ẖàẕa֖r bé֥̇yţ yĕhwáֽh׃"],[24,22,"וְ⁠לֹא־זָכַ֞ר יוֹאָ֣שׁ הַ⁠מֶּ֗לֶךְ הַ⁠חֶ֨סֶד֙ אֲשֶׁ֨ר עָשָׂ֜ה יְהוֹיָדָ֤ע אָבִי⁠ו֙ עִמּ֔⁠וֹ וַֽ⁠יַּהֲרֹ֖ג אֶת־בְּנ֑⁠וֹ וּ⁠כְ⁠מוֹת֣⁠וֹ אָמַ֔ר יֵ֥רֶא יְהוָ֖ה וְ⁠יִדְרֹֽשׁ׃פ","wĕ⁠lòʼ-záka֞r ywòʼá֣ş̌ ha⁠mė֗lekĕ ha⁠ẖe֨sed֙ ʼàşě֨r ʻáşá̂֜h yĕhwòyádá֤ʻ ʼábiy⁠w֙ ʻiṁ֔⁠wò waֽ⁠yȧhàrò֖g ʼeţ-bĕ̇n֑⁠wò ẇ⁠kĕ⁠mwòţ֣⁠wò ʼáma֔r yé֥reʼ yĕhwá֖h wĕ⁠yidĕròֽş̌׃p"],[24,23,"וַ⁠יְהִ֣י ׀ לִ⁠תְקוּפַ֣ת הַ⁠שָּׁנָ֗ה עָלָ֣ה עָלָי⁠ו֮ חֵ֣יל אֲרָם֒ וַ⁠יָּבֹ֗אוּ אֶל־יְהוּדָה֙ וִ⁠יר֣וּשָׁלִַ֔ם וַ⁠יַּשְׁחִ֛יתוּ אֶת־כָּל־שָׂרֵ֥י הָ⁠עָ֖ם מֵ⁠עָ֑ם וְ⁠כָל־שְׁלָלָ֥⁠ם שִׁלְּח֖וּ לְ⁠מֶ֥לֶךְ דַּרְמָֽשֶׂק׃","wa⁠yĕhi֣y ׀ li⁠ţĕqẇpa֣ţ ha⁠şá̇̌ná֗h ʻálá֣h ʻáláy⁠w֮ ẖé֣yl ʼàrám֒ wa⁠yá̇bò֗ʼẇ ʼel-yĕhẇdáh֙ wi⁠yr֣ẇşá̌lia֔m wa⁠yȧşĕ̌ẖi֛yţẇ ʼeţ-ká̇l-şá̂ré֥y há⁠ʻá֖m mé⁠ʻá֑m wĕ⁠kál-şĕ̌lálá֥⁠m şǐlĕ̇ẖ֖ẇ lĕ⁠me֥lekĕ dȧrĕmáֽşêq׃"],[24,24,"כִּי֩ בְ⁠מִצְעַ֨ר אֲנָשִׁ֜ים בָּ֣אוּ ׀ חֵ֣יל אֲרָ֗ם וַֽ⁠יהוָה֙ נָתַ֨ן בְּ⁠יָדָ֥⁠ם חַ֨יִל֙ לָ⁠רֹ֣ב מְאֹ֔ד כִּ֣י עָֽזְב֔וּ אֶת־יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵי⁠הֶ֑ם וְ⁠אֶת־יוֹאָ֖שׁ עָשׂ֥וּ שְׁפָטִֽים׃","ki̇y֩ bĕ⁠miẕĕʻa֨r ʼànáşǐ֜ym bá֣̇ʼẇ ׀ ẖé֣yl ʼàrá֗m waֽ⁠yhwáh֙ náţa֨n bĕ̇⁠yádá֥⁠m ẖa֨yil֙ lá⁠rò֣b mĕʼò֔d ki֣̇y ʻáֽzĕb֔ẇ ʼeţ-yĕhwá֖h ʼèlòhé֣y ʼàbwòţéy⁠he֑m wĕ⁠ʼeţ-ywòʼá֖ş̌ ʻáş֥̂ẇ şĕ̌pátiֽym׃"],[24,25,"וּ⁠בְ⁠לֶכְתָּ֣⁠ם מִמֶּ֗⁠נּוּ כִּֽי־עָזְב֣וּ אֹת⁠וֹ֮ ב⁠מחליים רַבִּים֒ הִתְקַשְּׁר֨וּ עָלָ֜י⁠ו עֲבָדָ֗י⁠ו בִּ⁠דְמֵי֙ בְּנֵי֙ יְהוֹיָדָ֣ע הַ⁠כֹּהֵ֔ן וַ⁠יַּֽהַרְגֻ֥⁠הוּ עַל־מִטָּת֖⁠וֹ וַ⁠יָּמֹ֑ת וַֽ⁠יִּקְבְּרֻ֨⁠הוּ֙ בְּ⁠עִ֣יר דָּוִ֔יד וְ⁠לֹ֥א קְבָרֻ֖⁠הוּ בְּ⁠קִבְר֥וֹת הַ⁠מְּלָכִֽים׃ס","ẇ⁠bĕ⁠lekĕţá֣̇⁠m mimė֗⁠ṅẇ kiֽ̇y-ʻázĕb֣ẇ ʼòţ⁠wò֮ b⁠mẖlyym rabi̇ym֒ hiţĕqaşĕ̇̌r֨ẇ ʻálá֜y⁠w ʻàbádá֗y⁠w bi̇⁠dĕméy֙ bĕ̇néy֙ yĕhwòyádá֣ʻ ha⁠kò̇hé֔n wa⁠yȧֽharĕgu֥⁠hẇ ʻal-mitá̇ţ֖⁠wò wa⁠yá̇mò֑ţ waֽ⁠yi̇qĕbĕ̇ru֨⁠hẇ֙ bĕ̇⁠ʻi֣yr dá̇wi֔yd wĕ⁠lò֥ʼ qĕbáru֖⁠hẇ bĕ̇⁠qibĕr֥wòţ ha⁠mĕ̇lákiֽym׃s"],[24,26,"וְ⁠אֵ֖לֶּה הַ⁠מִּתְקַשְּׁרִ֣ים עָלָ֑י⁠ו זָבָ֗ד בֶּן־שִׁמְעָת֙ הָֽ⁠עַמּוֹנִ֔ית וִ⁠יה֣וֹזָבָ֔ד בֶּן־שִׁמְרִ֖ית הַ⁠מּוֹאָבִֽית׃","wĕ⁠ʼé֖lėh ha⁠mi̇ţĕqaşĕ̇̌ri֣ym ʻálá֑y⁠w zábá֗d bėn-şǐmĕʻáţ֙ háֽ⁠ʻaṁwòni֔yţ wi⁠yh֣wòzábá֔d bėn-şǐmĕri֖yţ ha⁠ṁwòʼábiֽyţ׃"],[24,27,"וּ⁠בָנָ֞י⁠ו ו⁠רב הַ⁠מַּשָּׂ֣א עָלָ֗י⁠ו וִ⁠יסוֹד֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־מִדְרַ֖שׁ סֵ֣פֶר הַ⁠מְּלָכִ֑ים וַ⁠יִּמְלֹ֛ךְ אֲמַצְיָ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","ẇ⁠báná֞y⁠w w⁠rb ha⁠mȧşá֣̇̂ʼ ʻálá֗y⁠w wi⁠yswòd֙ bé֣̇yţ há⁠ʼèlòhi֔ym hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-midĕra֖ş̌ sé֣per ha⁠mĕ̇láki֑ym wa⁠yi̇mĕlò֛kĕ ʼàmaẕĕyá֥hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[25,1,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ מָלַ֣ךְ אֲמַצְיָ֔הוּ וְ⁠עֶשְׂרִ֣ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יְהוֹעַדָּ֖ן מִ⁠ירוּשָׁלָֽיִם׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ mála֣kĕ ʼàmaẕĕyá֔hẇ wĕ⁠ʻeşĕ̂ri֣ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yĕhwòʻadá֖̇n mi⁠yrẇşá̌láֽyim׃"],[25,2,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה רַ֕ק לֹ֖א בְּ⁠לֵבָ֥ב שָׁלֵֽם׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h ra֕q lò֖ʼ bĕ̇⁠lébá֥b şá̌léֽm׃"],[25,3,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֛ר חָזְקָ֥ה הַ⁠מַּמְלָכָ֖ה עָלָ֑י⁠ו וַֽ⁠יַּהֲרֹג֙ אֶת־עֲבָדָ֔י⁠ו הַ⁠מַּכִּ֖ים אֶת־הַ⁠מֶּ֥לֶךְ אָבִֽי⁠ו׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֛r ẖázĕqá֥h ha⁠mȧmĕláká֖h ʻálá֑y⁠w waֽ⁠yȧhàròg֙ ʼeţ-ʻàbádá֔y⁠w ha⁠mȧki֖̇ym ʼeţ-ha⁠mė֥lekĕ ʼábiֽy⁠w׃"],[25,4,"וְ⁠אֶת־בְּנֵי⁠הֶ֖ם לֹ֣א הֵמִ֑ית כִּ֣י כַ⁠כָּת֣וּב בַּ⁠תּוֹרָ֡ה בְּ⁠סֵ֣פֶר מֹשֶׁה֩ אֲשֶׁר־צִוָּ֨ה יְהוָ֜ה לֵ⁠אמֹ֗ר לֹא־יָמ֨וּתוּ אָב֤וֹת עַל־בָּנִים֙ וּ⁠בָנִים֙ לֹא־יָמ֣וּתוּ עַל־אָב֔וֹת כִּ֛י אִ֥ישׁ בְּ⁠חֶטְא֖⁠וֹ יָמֽוּתוּ׃פ","wĕ⁠ʼeţ-bĕ̇néy⁠he֖m lò֣ʼ hémi֑yţ ki֣̇y ka⁠ká̇ţ֣ẇb bȧ⁠ţ̇wòrá֡h bĕ̇⁠sé֣per mòşěh֩ ʼàşěr-ẕiwá̇֨h yĕhwá֜h lé⁠ʼmò֗r lòʼ-yám֨ẇţẇ ʼáb֤wòţ ʻal-bá̇niym֙ ẇ⁠bániym֙ lòʼ-yám֣ẇţẇ ʻal-ʼáb֔wòţ ki֛̇y ʼi֥yş̌ bĕ̇⁠ẖetĕʼ֖⁠wò yámֽẇţẇ׃p"],[25,5,"וַ⁠יִּקְבֹּ֤ץ אֲמַצְיָ֨הוּ֙ אֶת־יְהוּדָ֔ה וַ⁠יַּֽעֲמִידֵ֣⁠ם לְ⁠בֵית־אָב֗וֹת לְ⁠שָׂרֵ֤י הָ⁠אֲלָפִים֙ וּ⁠לְ⁠שָׂרֵ֣י הַ⁠מֵּא֔וֹת לְ⁠כָל־יְהוּדָ֖ה וּ⁠בִנְיָמִ֑ן וַֽ⁠יִּפְקְדֵ֗⁠ם לְ⁠מִ⁠בֶּ֨ן עֶשְׂרִ֤ים שָׁנָה֙ וָ⁠מַ֔עְלָ⁠ה וַ⁠יִּמְצָאֵ֗⁠ם שְׁלֹשׁ־מֵא֨וֹת אֶ֤לֶף בָּחוּר֙ יוֹצֵ֣א צָבָ֔א אֹחֵ֖ז רֹ֥מַח וְ⁠צִנָּֽה׃","wa⁠yi̇qĕbò֤̇ẕ ʼàmaẕĕyá֨hẇ֙ ʼeţ-yĕhẇdá֔h wa⁠yȧֽʻàmiydé֣⁠m lĕ⁠béyţ-ʼáb֗wòţ lĕ⁠şá̂ré֤y há⁠ʼàlápiym֙ ẇ⁠lĕ⁠şá̂ré֣y ha⁠mé̇ʼ֔wòţ lĕ⁠kál-yĕhẇdá֖h ẇ⁠binĕyámi֑n waֽ⁠yi̇pĕqĕdé֗⁠m lĕ⁠mi⁠bė֨n ʻeşĕ̂ri֤ym şá̌náh֙ wá⁠ma֔ʻĕlá⁠h wa⁠yi̇mĕẕáʼé֗⁠m şĕ̌lòş̌-méʼ֨wòţ ʼe֤lep bá̇ẖẇr֙ ywòẕé֣ʼ ẕábá֔ʼ ʼòẖé֖z rò֥maẖ wĕ⁠ẕináֽ̇h׃"],[25,6,"וַ⁠יִּשְׂכֹּ֣ר מִ⁠יִּשְׂרָאֵ֗ל מֵ֥אָה אֶ֛לֶף גִּבּ֥וֹר חָ֖יִל בְּ⁠מֵאָ֥ה כִכַּר־כָּֽסֶף׃","wa⁠yi̇şĕ̂kò֣̇r mi⁠yi̇şĕ̂ráʼé֗l mé֥ʼáh ʼe֛lep gi̇ḃ֥wòr ẖá֖yil bĕ̇⁠méʼá֥h kikȧr-káֽ̇sep׃"],[25,7,"וְ⁠אִ֣ישׁ הָ⁠אֱלֹהִ֗ים בָּ֤א אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר הַ⁠מֶּ֕לֶךְ אַל־יָבֹ֥א עִמְּ⁠ךָ֖ צְבָ֣א יִשְׂרָאֵ֑ל כִּ֣י אֵ֤ין יְהוָה֙ עִם־יִשְׂרָאֵ֔ל כֹּ֖ל בְּנֵ֥י אֶפְרָֽיִם׃","wĕ⁠ʼi֣yş̌ há⁠ʼèlòhi֗ym bá֤̇ʼ ʼéláy⁠w֙ lé⁠ʼmò֔r ha⁠mė֕lekĕ ʼal-yábò֥ʼ ʻimĕ̇⁠ká֖ ẕĕbá֣ʼ yişĕ̂ráʼé֑l ki֣̇y ʼé֤yn yĕhwáh֙ ʻim-yişĕ̂ráʼé֔l kò֖̇l bĕ̇né֥y ʼepĕráֽyim׃"],[25,8,"כִּ֚י אִם־בֹּ֣א אַתָּ֔ה עֲשֵׂ֖ה חֲזַ֣ק לַ⁠מִּלְחָמָ֑ה יַכְשִֽׁילְ⁠ךָ֤ הָֽ⁠אֱלֹהִים֙ לִ⁠פְנֵ֣י אוֹיֵ֔ב כִּ֥י יֶשׁ־כֹּ֛חַ בֵּ⁠אלֹהִ֖ים לַ⁠עְז֥וֹר וּ⁠לְ⁠הַכְשִֽׁיל׃","ki֚̇y ʼim-bò֣̇ʼ ʼaţá̇֔h ʻàşé֖̂h ẖàza֣q la⁠mi̇lĕẖámá֑h yakĕşǐֽylĕ⁠ká֤ háֽ⁠ʼèlòhiym֙ li⁠pĕné֣y ʼwòyé֔b ki֥̇y yeş̌-kò֛̇ẖa bé̇⁠ʼlòhi֖ym la⁠ʻĕz֥wòr ẇ⁠lĕ⁠hakĕşǐֽyl׃"],[25,9,"וַ⁠יֹּ֤אמֶר אֲמַצְיָ֨הוּ֙ לְ⁠אִ֣ישׁ הָ⁠אֱלֹהִ֔ים וּ⁠מַֽה־לַּ⁠עֲשׂוֹת֙ לִ⁠מְאַ֣ת הַ⁠כִּכָּ֔ר אֲשֶׁ֥ר נָתַ֖תִּי לִ⁠גְד֣וּד יִשְׂרָאֵ֑ל וַ⁠יֹּ֨אמֶר֙ אִ֣ישׁ הָֽ⁠אֱלֹהִ֔ים יֵ֚שׁ לַֽ⁠יהוָ֔ה לָ֥⁠תֶת לְ⁠ךָ֖ הַרְבֵּ֥ה מִ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer ʼàmaẕĕyá֨hẇ֙ lĕ⁠ʼi֣yş̌ há⁠ʼèlòhi֔ym ẇ⁠maֽh-lȧ⁠ʻàş̂wòţ֙ li⁠mĕʼa֣ţ ha⁠ki̇ká̇֔r ʼàşě֥r náţa֖ţi̇y li⁠gĕd֣ẇd yişĕ̂ráʼé֑l wa⁠yò̇֨ʼmer֙ ʼi֣yş̌ háֽ⁠ʼèlòhi֔ym yé֚ş̌ laֽ⁠yhwá֔h lá֥⁠ţeţ lĕ⁠ká֖ harĕbé֥̇h mi⁠zėֽh׃"],[25,10,"וַ⁠יַּבְדִּילֵ֣⁠ם אֲמַצְיָ֗הוּ לְ⁠הַ⁠גְּדוּד֙ אֲשֶׁר־בָּ֤א אֵלָי⁠ו֙ מֵֽ⁠אֶפְרַ֔יִם לָ⁠לֶ֖כֶת לִ⁠מְקוֹמָ֑⁠ם וַ⁠יִּ֨חַר אַפָּ֤⁠ם מְאֹד֙ בִּֽ⁠יהוּדָ֔ה וַ⁠יָּשׁ֥וּבוּ לִ⁠מְקוֹמָ֖⁠ם בָּ⁠חֳרִי־אָֽף׃פ","wa⁠yȧbĕdi̇ylé֣⁠m ʼàmaẕĕyá֗hẇ lĕ⁠ha⁠gĕ̇dẇd֙ ʼàşěr-bá֤̇ʼ ʼéláy⁠w֙ méֽ⁠ʼepĕra֔yim lá⁠le֖keţ li⁠mĕqwòmá֑⁠m wa⁠yi̇֨ẖar ʼapá֤̇⁠m mĕʼòd֙ biֽ̇⁠yhẇdá֔h wa⁠yá̇ş֥̌ẇbẇ li⁠mĕqwòmá֖⁠m bá̇⁠ẖoriy-ʼáֽp׃p"],[25,11,"וַ⁠אֲמַצְיָ֨הוּ֙ הִתְחַזַּ֔ק וַ⁠יִּנְהַג֙ אֶת־עַמּ֔⁠וֹ וַ⁠יֵּ֖לֶךְ גֵּ֣יא הַמֶּ֑לַח וַ⁠יַּ֥ךְ אֶת־בְּנֵי־שֵׂעִ֖יר עֲשֶׂ֥רֶת אֲלָפִֽים׃","wa⁠ʼàmaẕĕyá֨hẇ֙ hiţĕẖazȧ֔q wa⁠yi̇nĕhag֙ ʼeţ-ʻaṁ֔⁠wò wa⁠yé֖̇lekĕ gé֣̇yʼ hamė֑laẖ wa⁠yȧ֥kĕ ʼeţ-bĕ̇néy-şé̂ʻi֖yr ʻàşê֥reţ ʼàlápiֽym׃"],[25,12,"וַ⁠עֲשֶׂ֨רֶת אֲלָפִ֜ים חַיִּ֗ים שָׁבוּ֙ בְּנֵ֣י יְהוּדָ֔ה וַ⁠יְבִיא֖וּ⁠ם לְ⁠רֹ֣אשׁ הַ⁠סָּ֑לַע וַ⁠יַּשְׁלִיכ֛וּ⁠ם מֵֽ⁠רֹאשׁ־הַ⁠סֶּ֖לַע וְ⁠כֻלָּ֥⁠ם נִבְקָֽעוּ׃ס","wa⁠ʻàşê֨reţ ʼàlápi֜ym ẖayi̇֗ym şá̌bẇ֙ bĕ̇né֣y yĕhẇdá֔h wa⁠yĕbiyʼ֖ẇ⁠m lĕ⁠rò֣ʼş̌ ha⁠sá֑̇laʻ wa⁠yȧşĕ̌liyk֛ẇ⁠m méֽ⁠ròʼş̌-ha⁠sė֖laʻ wĕ⁠kulá֥̇⁠m nibĕqáֽʻẇ׃s"],[25,13,"וּ⁠בְנֵ֣י הַ⁠גְּד֗וּד אֲשֶׁ֨ר הֵשִׁ֤יב אֲמַצְיָ֨הוּ֙ מִ⁠לֶּ֤כֶת עִמּ⁠וֹ֙ לַ⁠מִּלְחָמָ֔ה וַֽ⁠יִּפְשְׁטוּ֙ בְּ⁠עָרֵ֣י יְהוּדָ֔ה מִ⁠שֹּׁמְר֖וֹן וְ⁠עַד־בֵּ֣ית חוֹר֑וֹן וַ⁠יַּכּ֤וּ מֵ⁠הֶם֙ שְׁלֹ֣שֶׁת אֲלָפִ֔ים וַ⁠יָּבֹ֖זּוּ בִּזָּ֥ה רַבָּֽה׃ס","ẇ⁠bĕné֣y ha⁠gĕ̇d֗ẇd ʼàşě֨r héşǐ֤yb ʼàmaẕĕyá֨hẇ֙ mi⁠lė֤keţ ʻiṁ⁠wò֙ la⁠mi̇lĕẖámá֔h waֽ⁠yi̇pĕşĕ̌tẇ֙ bĕ̇⁠ʻáré֣y yĕhẇdá֔h mi⁠şò̇̌mĕr֖wòn wĕ⁠ʻad-bé֣̇yţ ẖwòr֑wòn wa⁠yȧk֤̇ẇ mé⁠hem֙ şĕ̌lò֣şěţ ʼàlápi֔ym wa⁠yá̇bò֖żẇ bi̇zá֥̇h rabáֽ̇h׃s"],[25,14,"וַ⁠יְהִ֗י אַחֲרֵ֨י ב֤וֹא אֲמַצְיָ֨הוּ֙ מֵֽ⁠הַכּ֣וֹת אֶת־אֲדוֹמִ֔ים וַ⁠יָּבֵ֗א אֶת־אֱלֹהֵי֙ בְּנֵ֣י שֵׂעִ֔יר וַ⁠יַּֽעֲמִידֵ֥⁠ם ל֖⁠וֹ לֵ⁠אלֹהִ֑ים וְ⁠לִ⁠פְנֵי⁠הֶ֥ם יִֽשְׁתַּחֲוֶ֖ה וְ⁠לָ⁠הֶ֥ם יְקַטֵּֽר׃","wa⁠yĕhi֗y ʼaẖàré֨y b֤wòʼ ʼàmaẕĕyá֨hẇ֙ méֽ⁠hak֣̇wòţ ʼeţ-ʼàdwòmi֔ym wa⁠yá̇bé֗ʼ ʼeţ-ʼèlòhéy֙ bĕ̇né֣y şé̂ʻi֔yr wa⁠yȧֽʻàmiydé֥⁠m l֖⁠wò lé⁠ʼlòhi֑ym wĕ⁠li⁠pĕnéy⁠he֥m yiֽşĕ̌ţȧẖàwe֖h wĕ⁠lá⁠he֥m yĕqatéֽ̇r׃"],[25,15,"וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בַּ⁠אֲמַצְיָ֑הוּ וַ⁠יִּשְׁלַ֤ח אֵלָי⁠ו֙ נָבִ֔יא וַ⁠יֹּ֣אמֶר ל֗⁠וֹ לָ֤⁠מָּה דָרַ֨שְׁתָּ֙ אֶת־אֱלֹהֵ֣י הָ⁠עָ֔ם אֲשֶׁ֛ר לֹא־הִצִּ֥ילוּ אֶת־עַמָּ֖⁠ם מִ⁠יָּדֶֽ⁠ךָ׃","wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bȧ⁠ʼàmaẕĕyá֑hẇ wa⁠yi̇şĕ̌la֤ẖ ʼéláy⁠w֙ nábi֔yʼ wa⁠yò֣̇ʼmer l֗⁠wò lá֤⁠má̇h dára֨şĕ̌ţá̇֙ ʼeţ-ʼèlòhé֣y há⁠ʻá֔m ʼàşě֛r lòʼ-hiẕi֥̇ylẇ ʼeţ-ʻamá֖̇⁠m mi⁠yá̇deֽ⁠ká׃"],[25,16,"וַ⁠יְהִ֣י ׀ בְּ⁠דַבְּר֣⁠וֹ אֵלָ֗י⁠ו וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הַ⁠לְ⁠יוֹעֵ֤ץ לַ⁠מֶּ֨לֶךְ֙ נְתַנּ֔וּ⁠ךָ חֲדַל־לְ⁠ךָ֖ לָ֣⁠מָּה יַכּ֑וּ⁠ךָ וַ⁠יֶּחְדַּ֣ל הַ⁠נָּבִ֗יא וַ⁠יֹּ֨אמֶר֙ יָדַ֗עְתִּי כִּֽי־יָעַ֤ץ אֱלֹהִים֙ לְ⁠הַשְׁחִיתֶ֔⁠ךָ כִּֽי־עָשִׂ֣יתָ זֹּ֔את וְ⁠לֹ֥א שָׁמַ֖עְתָּ לַ⁠עֲצָתִֽ⁠י׃פ","wa⁠yĕhi֣y ׀ bĕ̇⁠dabĕ̇r֣⁠wò ʼélá֗y⁠w wa⁠yò֤̇ʼmer l⁠wò֙ ha⁠lĕ⁠ywòʻé֤ẕ la⁠mė֨lekĕ֙ nĕţaṅ֔ẇ⁠ká ẖàdal-lĕ⁠ká֖ lá֣⁠má̇h yak֑̇ẇ⁠ká wa⁠yėẖĕdȧ֣l ha⁠ná̇bi֗yʼ wa⁠yò̇֨ʼmer֙ yáda֗ʻĕţi̇y kiֽ̇y-yáʻa֤ẕ ʼèlòhiym֙ lĕ⁠haşĕ̌ẖiyţe֔⁠ká kiֽ̇y-ʻáşî֣yţá zò̇֔ʼţ wĕ⁠lò֥ʼ şá̌ma֖ʻĕţá̇ la⁠ʻàẕáţiֽ⁠y׃p"],[25,17,"וַ⁠יִּוָּעַ֗ץ אֲמַצְיָ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה וַ֠⁠יִּשְׁלַח אֶל־יוֹאָ֨שׁ בֶּן־יְהוֹאָחָ֧ז בֶּן־יֵה֛וּא מֶ֥לֶךְ יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר לך נִתְרָאֶ֥ה פָנִֽים׃","wa⁠yi̇wá̇ʻa֗ẕ ʼàmaẕĕyá֨hẇ֙ me֣lekĕ yĕhẇdá֔h wa֠⁠yi̇şĕ̌laẖ ʼel-ywòʼá֨ş̌ bėn-yĕhwòʼáẖá֧z bėn-yéh֛ẇʼ me֥lekĕ yişĕ̂ráʼé֖l lé⁠ʼmò֑r lk niţĕráʼe֥h pániֽym׃"],[25,18,"וַ⁠יִּשְׁלַ֞ח יוֹאָ֣שׁ מֶֽלֶךְ־יִשְׂרָאֵ֗ל אֶל־אֲמַצְיָ֣הוּ מֶֽלֶךְ־יְהוּדָה֮ לֵ⁠אמֹר֒ הַ⁠ח֜וֹחַ אֲשֶׁ֣ר בַּ⁠לְּבָנ֗וֹן שָׁ֠לַח אֶל־הָ⁠אֶ֜רֶז אֲשֶׁ֤ר בַּ⁠לְּבָנוֹן֙ לֵ⁠אמֹ֔ר תְּנָֽ⁠ה־אֶת־בִּתְּ⁠ךָ֥ לִ⁠בְנִ֖⁠י לְ⁠אִשָּׁ֑ה וַֽ⁠תַּעֲבֹ֞ר חַיַּ֤ת הַ⁠שָּׂדֶה֙ אֲשֶׁ֣ר בַּ⁠לְּבָנ֔וֹן וַ⁠תִּרְמֹ֖ס אֶת־הַ⁠חֽוֹחַ׃","wa⁠yi̇şĕ̌la֞ẖ ywòʼá֣ş̌ meֽlekĕ-yişĕ̂ráʼé֗l ʼel-ʼàmaẕĕyá֣hẇ meֽlekĕ-yĕhẇdáh֮ lé⁠ʼmòr֒ ha⁠ẖ֜wòẖa ʼàşě֣r bȧ⁠lĕ̇bán֗wòn şá̌֠laẖ ʼel-há⁠ʼe֜rez ʼàşě֤r bȧ⁠lĕ̇bánwòn֙ lé⁠ʼmò֔r ţĕ̇náֽ⁠h-ʼeţ-bi̇ţĕ̇⁠ká֥ li⁠bĕni֖⁠y lĕ⁠ʼişá֑̇̌h waֽ⁠ţȧʻàbò֞r ẖayȧ֤ţ ha⁠şá̇̂deh֙ ʼàşě֣r bȧ⁠lĕ̇bán֔wòn wa⁠ţi̇rĕmò֖s ʼeţ-ha⁠ẖֽwòẖa׃"],[25,19,"אָמַ֗רְתָּ הִנֵּ֤ה הִכִּ֨יתָ֙ אֶת־אֱד֔וֹם וּ⁠נְשָׂאֲ⁠ךָ֥ לִבְּ⁠ךָ֖ לְ⁠הַכְבִּ֑יד עַתָּה֙ שְׁבָ֣⁠ה בְּ⁠בֵיתֶ֔⁠ךָ לָ֤⁠מָּה תִתְגָּרֶה֙ בְּ⁠רָעָ֔ה וְ⁠נָ֣פַלְתָּ֔ אַתָּ֖ה וִ⁠יהוּדָ֥ה עִמָּֽ⁠ךְ׃","ʼáma֗rĕţá̇ hiné֤̇h hiki̇֨yţá֙ ʼeţ-ʼèd֔wòm ẇ⁠nĕşá̂ʼà⁠ká֥ libĕ̇⁠ká֖ lĕ⁠hakĕbi֑̇yd ʻaţá̇h֙ şĕ̌bá֣⁠h bĕ̇⁠béyţe֔⁠ká lá֤⁠má̇h ţiţĕgá̇reh֙ bĕ̇⁠ráʻá֔h wĕ⁠ná֣palĕţá̇֔ ʼaţá֖̇h wi⁠yhẇdá֥h ʻimáֽ̇⁠kĕ׃"],[25,20,"וְ⁠לֹא־שָׁמַ֣ע אֲמַצְיָ֔הוּ כִּ֤י מֵ⁠הָֽ⁠אֱלֹהִים֙ הִ֔יא לְמַ֖עַן תִּתָּ֣⁠ם בְּ⁠יָ֑ד כִּ֣י דָֽרְשׁ֔וּ אֵ֖ת אֱלֹהֵ֥י אֱדֽוֹם׃","wĕ⁠lòʼ-şá̌ma֣ʻ ʼàmaẕĕyá֔hẇ ki֤̇y mé⁠háֽ⁠ʼèlòhiym֙ hi֔yʼ lĕma֖ʻan ţi̇ţá֣̇⁠m bĕ̇⁠yá֑d ki֣̇y dáֽrĕş̌֔ẇ ʼé֖ţ ʼèlòhé֥y ʼèdֽwòm׃"],[25,21,"וַ⁠יַּ֨עַל יוֹאָ֤שׁ מֶֽלֶךְ־יִשְׂרָאֵל֙ וַ⁠יִּתְרָא֣וּ פָנִ֔ים ה֖וּא וַ⁠אֲמַצְיָ֣הוּ מֶֽלֶךְ־יְהוּדָ֑ה בְּ⁠בֵ֥ית שֶׁ֖מֶשׁ אֲשֶׁ֥ר לִ⁠יהוּדָֽה׃","wa⁠yȧ֨ʻal ywòʼá֤ş̌ meֽlekĕ-yişĕ̂ráʼél֙ wa⁠yi̇ţĕráʼ֣ẇ páni֔ym h֖ẇʼ wa⁠ʼàmaẕĕyá֣hẇ meֽlekĕ-yĕhẇdá֑h bĕ̇⁠bé֥yţ şě֖meş̌ ʼàşě֥r li⁠yhẇdáֽh׃"],[25,22,"וַ⁠יִּנָּ֥גֶף יְהוּדָ֖ה לִ⁠פְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יָּנֻ֖סוּ אִ֥ישׁ לְ⁠אֹהָלָֽי⁠ו׃","wa⁠yi̇ná֥̇gep yĕhẇdá֖h li⁠pĕné֣y yişĕ̂ráʼé֑l wa⁠yá̇nu֖sẇ ʼi֥yş̌ lĕ⁠ʼòháláֽy⁠w׃"],[25,23,"וְ⁠אֵת֩ אֲמַצְיָ֨הוּ מֶֽלֶךְ־יְהוּדָ֜ה בֶּן־יוֹאָ֣שׁ בֶּן־יְהוֹאָחָ֗ז תָּפַ֛שׂ יוֹאָ֥שׁ מֶֽלֶךְ־יִשְׂרָאֵ֖ל בְּ⁠בֵ֣ית שָׁ֑מֶשׁ וַ⁠יְבִיאֵ֨⁠הוּ֙ יְר֣וּשָׁלִַ֔ם וַ⁠יִּפְרֹ֞ץ בְּ⁠חוֹמַ֣ת יְרוּשָׁלִַ֗ם מִ⁠שַּׁ֤עַר אֶפְרַ֨יִם֙ עַד־שַׁ֣עַר הַ⁠פּוֹנֶ֔ה אַרְבַּ֥ע מֵא֖וֹת אַמָּֽה׃","wĕ⁠ʼéţ֩ ʼàmaẕĕyá֨hẇ meֽlekĕ-yĕhẇdá֜h bėn-ywòʼá֣ş̌ bėn-yĕhwòʼáẖá֗z ţá̇pa֛ş̂ ywòʼá֥ş̌ meֽlekĕ-yişĕ̂ráʼé֖l bĕ̇⁠bé֣yţ şá֑̌meş̌ wa⁠yĕbiyʼé֨⁠hẇ֙ yĕr֣ẇşá̌lia֔m wa⁠yi̇pĕrò֞ẕ bĕ̇⁠ẖwòma֣ţ yĕrẇşá̌lia֗m mi⁠şȧ֤̌ʻar ʼepĕra֨yim֙ ʻad-şǎ֣ʻar ha⁠ṗwòne֔h ʼarĕbȧ֥ʻ méʼ֖wòţ ʼamáֽ̇h׃"],[25,24,"וְ⁠כָֽל־הַ⁠זָּהָ֣ב וְ⁠הַ⁠כֶּ֡סֶף וְ⁠אֵ֣ת כָּל־הַ֠⁠כֵּלִים הַ⁠נִּמְצְאִ֨ים בְּ⁠בֵית־הָ⁠אֱלֹהִ֜ים עִם־עֹבֵ֣ד אֱד֗וֹם וְ⁠אֶת־אֹצְרוֹת֙ בֵּ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠אֵ֖ת בְּנֵ֣י הַ⁠תַּֽעֲרֻב֑וֹת וַ⁠יָּ֖שָׁב שֹׁמְרֽוֹן׃פ","wĕ⁠káֽl-ha⁠zá̇há֣b wĕ⁠ha⁠kė֡sep wĕ⁠ʼé֣ţ ká̇l-ha֠⁠ké̇liym ha⁠ni̇mĕẕĕʼi֨ym bĕ̇⁠béyţ-há⁠ʼèlòhi֜ym ʻim-ʻòbé֣d ʼèd֗wòm wĕ⁠ʼeţ-ʼòẕĕrwòţ֙ bé֣̇yţ ha⁠mė֔lekĕ wĕ⁠ʼé֖ţ bĕ̇né֣y ha⁠ţȧֽʻàrub֑wòţ wa⁠yá֖̇şá̌b şò̌mĕrֽwòn׃p"],[25,25,"וַ⁠יְחִ֨י אֲמַצְיָ֤הוּ בֶן־יוֹאָשׁ֙ מֶ֣לֶךְ יְהוּדָ֔ה אַחֲרֵ֣י מ֔וֹת יוֹאָ֥שׁ בֶּן־יְהוֹאָחָ֖ז מֶ֣לֶךְ יִשְׂרָאֵ֑ל חֲמֵ֥שׁ עֶשְׂרֵ֖ה שָׁנָֽה׃","wa⁠yĕẖi֨y ʼàmaẕĕyá֤hẇ ben-ywòʼáş̌֙ me֣lekĕ yĕhẇdá֔h ʼaẖàré֣y m֔wòţ ywòʼá֥ş̌ bėn-yĕhwòʼáẖá֖z me֣lekĕ yişĕ̂ráʼé֑l ẖàmé֥ş̌ ʻeşĕ̂ré֖h şá̌náֽh׃"],[25,26,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י אֲמַצְיָ֔הוּ הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אַחֲרוֹנִ֑ים הֲ⁠לֹא֙ הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־סֵ֥פֶר מַלְכֵי־יְהוּדָ֖ה וְ⁠יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer֙ di̇bĕré֣y ʼàmaẕĕyá֔hẇ há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼaẖàrwòni֑ym hà⁠lòʼ֙ hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-sé֥per malĕkéy-yĕhẇdá֖h wĕ⁠yişĕ̂ráʼéֽl׃"],[25,27,"וּ⁠מֵ⁠עֵ֗ת אֲשֶׁר־סָ֤ר אֲמַצְיָ֨הוּ֙ מֵ⁠אַחֲרֵ֣י יְהוָ֔ה וַ⁠יִּקְשְׁר֨וּ עָלָ֥י⁠ו קֶ֛שֶׁר בִּ⁠ירוּשָׁלִַ֖ם וַ⁠יָּ֣נָס לָכִ֑ישָׁ⁠ה וַ⁠יִּשְׁלְח֤וּ אַחֲרָי⁠ו֙ לָכִ֔ישָׁ⁠ה וַ⁠יְמִיתֻ֖⁠הוּ שָֽׁם׃","ẇ⁠mé⁠ʻé֗ţ ʼàşěr-sá֤r ʼàmaẕĕyá֨hẇ֙ mé⁠ʼaẖàré֣y yĕhwá֔h wa⁠yi̇qĕşĕ̌r֨ẇ ʻálá֥y⁠w qe֛şěr bi̇⁠yrẇşá̌lia֖m wa⁠yá֣̇nás láki֑yşá̌⁠h wa⁠yi̇şĕ̌lĕẖ֤ẇ ʼaẖàráy⁠w֙ láki֔yşá̌⁠h wa⁠yĕmiyţu֖⁠hẇ şáֽ̌m׃"],[25,28,"וַ⁠יִּשָּׂאֻ֖⁠הוּ עַל־הַ⁠סּוּסִ֑ים וַֽ⁠יִּקְבְּר֥וּ אֹת֛⁠וֹ עִם־אֲבֹתָ֖י⁠ו בְּ⁠עִ֥יר יְהוּדָֽה׃","wa⁠yi̇şá̇̂ʼu֖⁠hẇ ʻal-ha⁠ṡẇsi֑ym waֽ⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֛⁠wò ʻim-ʼàbòţá֖y⁠w bĕ̇⁠ʻi֥yr yĕhẇdáֽh׃"],[26,1,"וַ⁠יִּקְח֞וּ כָּל־עַ֤ם יְהוּדָה֙ אֶת־עֻזִּיָּ֔הוּ וְ⁠ה֕וּא בֶּן־שֵׁ֥שׁ עֶשְׂרֵ֖ה שָׁנָ֑ה וַ⁠יַּמְלִ֣יכוּ אֹת֔⁠וֹ תַּ֖חַת אָבִ֥י⁠ו אֲמַצְיָֽהוּ׃","wa⁠yi̇qĕẖ֞ẇ ká̇l-ʻa֤m yĕhẇdáh֙ ʼeţ-ʻuzi̇yá̇֔hẇ wĕ⁠h֕ẇʼ bėn-şé֥̌ş̌ ʻeşĕ̂ré֖h şá̌ná֑h wa⁠yȧmĕli֣ykẇ ʼòţ֔⁠wò ţȧ֖ẖaţ ʼábi֥y⁠w ʼàmaẕĕyáֽhẇ׃"],[26,2,"ה֚וּא בָּנָ֣ה אֶת־אֵיל֔וֹת וַ⁠יְשִׁיבֶ֖⁠הָ לִֽ⁠יהוּדָ֑ה אַחֲרֵ֥י שְׁכַֽב־הַ⁠מֶּ֖לֶךְ עִם־אֲבֹתָֽי⁠ו׃פ","h֚ẇʼ bá̇ná֣h ʼeţ-ʼéyl֔wòţ wa⁠yĕşǐybe֖⁠há liֽ⁠yhẇdá֑h ʼaẖàré֥y şĕ̌kaֽb-ha⁠mė֖lekĕ ʻim-ʼàbòţáֽy⁠w׃p"],[26,3,"בֶּן־שֵׁ֨שׁ עֶשְׂרֵ֤ה שָׁנָה֙ עֻזִּיָּ֣הוּ בְ⁠מָלְכ֔⁠וֹ וַ⁠חֲמִשִּׁ֤ים וּ⁠שְׁתַּ֨יִם֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יכיליה מִן־יְרוּשָׁלִָֽם׃","bėn-şé̌֨ş̌ ʻeşĕ̂ré֤h şá̌náh֙ ʻuzi̇yá֣̇hẇ bĕ⁠málĕk֔⁠wò wa⁠ẖàmişi֤̇̌ym ẇ⁠şĕ̌ţȧ֨yim֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ykylyh min-yĕrẇşá̌liáֽm׃"],[26,4,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה אֲמַצְיָ֥הוּ אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h ʼàmaẕĕyá֥hẇ ʼábiֽy⁠w׃"],[26,5,"וַ⁠יְהִי֙ לִ⁠דְרֹ֣שׁ אֱלֹהִ֔ים בִּ⁠ימֵ֣י זְכַרְיָ֔הוּ הַ⁠מֵּבִ֖ין בִּ⁠רְאֹ֣ת הָ⁠אֱלֹהִ֑ים וּ⁠בִ⁠ימֵי֙ דָּרְשׁ֣⁠וֹ אֶת־יְהוָ֔ה הִצְלִיח֖⁠וֹ הָ⁠אֱלֹהִֽים׃ס","wa⁠yĕhiy֙ li⁠dĕrò֣ş̌ ʼèlòhi֔ym bi̇⁠ymé֣y zĕkarĕyá֔hẇ ha⁠mé̇bi֖yn bi̇⁠rĕʼò֣ţ há⁠ʼèlòhi֑ym ẇ⁠bi⁠yméy֙ dá̇rĕş֣̌⁠wò ʼeţ-yĕhwá֔h hiẕĕliyẖ֖⁠wò há⁠ʼèlòhiֽym׃s"],[26,6,"וַ⁠יֵּצֵא֙ וַ⁠יִּלָּ֣חֶם בַּ⁠פְּלִשְׁתִּ֔ים וַ⁠יִּפְרֹ֞ץ אֶת־ח֣וֹמַת גַּ֗ת וְ⁠אֵת֙ חוֹמַ֣ת יַבְנֵ֔ה וְ⁠אֵ֖ת חוֹמַ֣ת אַשְׁדּ֑וֹד וַ⁠יִּבְנֶ֣ה עָרִ֔ים בְּ⁠אַשְׁדּ֖וֹד וּ⁠בַ⁠פְּלִשְׁתִּֽים׃","wa⁠yé̇ẕéʼ֙ wa⁠yi̇lá֣̇ẖem bȧ⁠pĕ̇lişĕ̌ţi̇֔ym wa⁠yi̇pĕrò֞ẕ ʼeţ-ẖ֣wòmaţ gȧ֗ţ wĕ⁠ʼéţ֙ ẖwòma֣ţ yabĕné֔h wĕ⁠ʼé֖ţ ẖwòma֣ţ ʼaşĕ̌ḋ֑wòd wa⁠yi̇bĕne֣h ʻári֔ym bĕ̇⁠ʼaşĕ̌ḋ֖wòd ẇ⁠ba⁠pĕ̇lişĕ̌ţiֽ̇ym׃"],[26,7,"וַ⁠יַּעְזְרֵ֨⁠הוּ הָֽ⁠אֱלֹהִ֜ים עַל־פְּלִשְׁתִּ֧ים וְ⁠עַל־ה⁠ערביים הַ⁠יֹּשְׁבִ֥ים בְּ⁠גוּר־בָּ֖עַל וְ⁠הַ⁠מְּעוּנִֽים׃","wa⁠yȧʻĕzĕré֨⁠hẇ háֽ⁠ʼèlòhi֜ym ʻal-pĕ̇lişĕ̌ţi֧̇ym wĕ⁠ʻal-h⁠ʻrbyym ha⁠yò̇şĕ̌bi֥ym bĕ̇⁠gẇr-bá֖̇ʻal wĕ⁠ha⁠mĕ̇ʻẇniֽym׃"],[26,8,"וַ⁠יִּתְּנ֧וּ הָֽ⁠עַמּוֹנִ֛ים מִנְחָ֖ה לְ⁠עֻזִּיָּ֑הוּ וַ⁠יֵּ֤לֶךְ שְׁמ⁠וֹ֙ עַד־לְ⁠ב֣וֹא מִצְרַ֔יִם כִּ֥י הֶחֱזִ֖יק עַד־לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇ţĕ̇n֧ẇ háֽ⁠ʻaṁwòni֛ym minĕẖá֖h lĕ⁠ʻuzi̇yá֑̇hẇ wa⁠yé֤̇lekĕ şĕ̌m⁠wò֙ ʻad-lĕ⁠b֣wòʼ miẕĕra֔yim ki֥̇y heẖèzi֖yq ʻad-lĕ⁠máֽʻĕlá⁠h׃"],[26,9,"וַ⁠יִּ֨בֶן עֻזִּיָּ֤הוּ מִגְדָּלִים֙ בִּ⁠יר֣וּשָׁלִַ֔ם עַל־שַׁ֧עַר הַ⁠פִּנָּ֛ה וְ⁠עַל־שַׁ֥עַר הַ⁠גַּ֖יְא וְ⁠עַל־הַ⁠מִּקְצ֑וֹעַ וַֽ⁠יְחַזְּקֵֽ⁠ם׃","wa⁠yi̇֨ben ʻuzi̇yá֤̇hẇ migĕdá̇liym֙ bi̇⁠yr֣ẇşá̌lia֔m ʻal-şǎ֧ʻar ha⁠pi̇ná֛̇h wĕ⁠ʻal-şǎ֥ʻar ha⁠gȧ֖yĕʼ wĕ⁠ʻal-ha⁠mi̇qĕẕ֑wòʻa waֽ⁠yĕẖazĕ̇qéֽ⁠m׃"],[26,10,"וַ⁠יִּ֨בֶן מִגְדָּלִ֜ים בַּ⁠מִּדְבָּ֗ר וַ⁠יַּחְצֹב֙ בֹּר֣וֹת רַבִּ֔ים כִּ֤י מִקְנֶה־רַּב֙ הָ֣יָה ל֔⁠וֹ וּ⁠בַ⁠שְּׁפֵלָ֖ה וּ⁠בַ⁠מִּישׁ֑וֹר אִכָּרִ֣ים וְ⁠כֹֽרְמִ֗ים בֶּ⁠הָרִים֙ וּ⁠בַ⁠כַּרְמֶ֔ל כִּֽי־אֹהֵ֥ב אֲדָמָ֖ה הָיָֽה׃ס","wa⁠yi̇֨ben migĕdá̇li֜ym bȧ⁠mi̇dĕbá̇֗r wa⁠yȧẖĕẕòb֙ bò̇r֣wòţ rabi̇֔ym ki֤̇y miqĕneh-rȧb֙ há֣yáh l֔⁠wò ẇ⁠ba⁠şĕ̇̌pélá֖h ẇ⁠ba⁠mi̇yş֑̌wòr ʼiká̇ri֣ym wĕ⁠kòֽrĕmi֗ym bė⁠háriym֙ ẇ⁠ba⁠kȧrĕme֔l kiֽ̇y-ʼòhé֥b ʼàdámá֖h háyáֽh׃s"],[26,11,"וַ⁠יְהִ֣י לְ⁠עֻזִּיָּ֡הוּ חַיִל֩ עֹשֵׂ֨ה מִלְחָמָ֜ה יוֹצְאֵ֧י צָבָ֣א לִ⁠גְד֗וּד בְּ⁠מִסְפַּר֙ פְּקֻדָּתָ֔⁠ם בְּ⁠יַד֙ יעואל הַ⁠סּוֹפֵ֔ר וּ⁠מַעֲשֵׂיָ֖הוּ הַ⁠שּׁוֹטֵ֑ר עַ֚ל יַד־חֲנַנְיָ֔הוּ מִ⁠שָּׂרֵ֖י הַ⁠מֶּֽלֶךְ׃","wa⁠yĕhi֣y lĕ⁠ʻuzi̇yá̇֡hẇ ẖayil֩ ʻòşé̂֨h milĕẖámá֜h ywòẕĕʼé֧y ẕábá֣ʼ li⁠gĕd֗ẇd bĕ̇⁠misĕpȧr֙ pĕ̇qudá̇ţá֔⁠m bĕ̇⁠yad֙ yʻwʼl ha⁠ṡwòpé֔r ẇ⁠maʻàşé̂yá֖hẇ ha⁠ş̇̌wòté֑r ʻa֚l yad-ẖànanĕyá֔hẇ mi⁠şá̇̂ré֖y ha⁠mėֽlekĕ׃"],[26,12,"כֹּ֠ל מִסְפַּ֞ר רָאשֵׁ֤י הָ⁠אָבוֹת֙ לְ⁠גִבּ֣וֹרֵי חָ֔יִל אַלְפַּ֖יִם וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃","kò̇֠l misĕpȧ֞r ráʼşé֤̌y há⁠ʼábwòţ֙ lĕ⁠giḃ֣wòréy ẖá֔yil ʼalĕpȧ֖yim wĕ⁠şé֥̌ş̌ méʼֽwòţ׃"],[26,13,"וְ⁠עַל־יָדָ⁠ם֩ חֵ֨יל צָבָ֜א שְׁלֹ֧שׁ מֵא֣וֹת אֶ֗לֶף וְ⁠שִׁבְעַ֤ת אֲלָפִים֙ וַ⁠חֲמֵ֣שׁ מֵא֔וֹת עוֹשֵׂ֥י מִלְחָמָ֖ה בְּ⁠כֹ֣חַ חָ֑יִל לַ⁠עְזֹ֥ר לַ⁠מֶּ֖לֶךְ עַל־הָ⁠אוֹיֵֽב׃","wĕ⁠ʻal-yádá⁠m֩ ẖé֨yl ẕábá֜ʼ şĕ̌lò֧ş̌ méʼ֣wòţ ʼe֗lep wĕ⁠şǐbĕʻa֤ţ ʼàlápiym֙ wa⁠ẖàmé֣ş̌ méʼ֔wòţ ʻwòşé֥̂y milĕẖámá֖h bĕ̇⁠kò֣ẖa ẖá֑yil la⁠ʻĕzò֥r la⁠mė֖lekĕ ʻal-há⁠ʼwòyéֽb׃"],[26,14,"וַ⁠יָּכֶן֩ לָ⁠הֶ֨ם עֻזִּיָּ֜הוּ לְ⁠כָל־הַ⁠צָּבָ֗א מָגִנִּ֤ים וּ⁠רְמָחִים֙ וְ⁠כ֣וֹבָעִ֔ים וְ⁠שִׁרְיֹנ֖וֹת וּ⁠קְשָׁת֑וֹת וּ⁠לְ⁠אַבְנֵ֖י קְלָעִֽים׃","wa⁠yá̇ken֩ lá⁠he֨m ʻuzi̇yá̇֜hẇ lĕ⁠kál-ha⁠ẕá̇bá֗ʼ mágini֤̇ym ẇ⁠rĕmáẖiym֙ wĕ⁠k֣wòbáʻi֔ym wĕ⁠şǐrĕyòn֖wòţ ẇ⁠qĕşá̌ţ֑wòţ ẇ⁠lĕ⁠ʼabĕné֖y qĕláʻiֽym׃"],[26,15,"וַ⁠יַּ֣עַשׂ ׀ בִּ⁠ירוּשָׁלִַ֨ם חִשְּׁבֹנ֜וֹת מַחֲשֶׁ֣בֶת חוֹשֵׁ֗ב לִ⁠הְי֤וֹת עַל־הַ⁠מִּגְדָּלִים֙ וְ⁠עַל־הַ⁠פִּנּ֔וֹת לִ⁠ירוֹא֙ בַּֽ⁠חִצִּ֔ים וּ⁠בָ⁠אֲבָנִ֖ים גְּדֹל֑וֹת וַ⁠יֵּצֵ֤א שְׁמ⁠וֹ֙ עַד־לְ⁠מֵ֣⁠רָח֔וֹק כִּֽי־הִפְלִ֥יא לְ⁠הֵעָזֵ֖ר עַ֥ד כִּֽי־חָזָֽק׃","wa⁠yȧ֣ʻaş̂ ׀ bi̇⁠yrẇşá̌lia֨m ẖişĕ̇̌bòn֜wòţ maẖàşě֣beţ ẖwòşé̌֗b li⁠hĕy֤wòţ ʻal-ha⁠mi̇gĕdá̇liym֙ wĕ⁠ʻal-ha⁠pi̇ṅ֔wòţ li⁠yrwòʼ֙ bȧֽ⁠ẖiẕi̇֔ym ẇ⁠bá⁠ʼàbáni֖ym gĕ̇dòl֑wòţ wa⁠yé̇ẕé֤ʼ şĕ̌m⁠wò֙ ʻad-lĕ⁠mé֣⁠ráẖ֔wòq kiֽ̇y-hipĕli֥yʼ lĕ⁠héʻázé֖r ʻa֥d kiֽ̇y-ẖázáֽq׃"],[26,16,"וּ⁠כְ⁠חֶזְקָת֗⁠וֹ גָּבַ֤הּ לִבּ⁠וֹ֙ עַד־לְ⁠הַשְׁחִ֔ית וַ⁠יִּמְעַ֖ל בַּ⁠יהוָ֣ה אֱלֹהָ֑י⁠ו וַ⁠יָּבֹא֙ אֶל־הֵיכַ֣ל יְהוָ֔ה לְ⁠הַקְטִ֖יר עַל־מִזְבַּ֥ח הַ⁠קְּטֹֽרֶת׃","ẇ⁠kĕ⁠ẖezĕqáţ֗⁠wò gá̇ba֤ḣ liḃ⁠wò֙ ʻad-lĕ⁠haşĕ̌ẖi֔yţ wa⁠yi̇mĕʻa֖l bȧ⁠yhwá֣h ʼèlòhá֑y⁠w wa⁠yá̇bòʼ֙ ʼel-héyka֣l yĕhwá֔h lĕ⁠haqĕti֖yr ʻal-mizĕbȧ֥ẖ ha⁠qĕ̇tòֽreţ׃"],[26,17,"וַ⁠יָּבֹ֥א אַחֲרָ֖י⁠ו עֲזַרְיָ֣הוּ הַ⁠כֹּהֵ֑ן וְ⁠עִמּ֞⁠וֹ כֹּהֲנִ֧ים ׀ לַ⁠יהוָ֛ה שְׁמוֹנִ֖ים בְּנֵי־חָֽיִל׃","wa⁠yá̇bò֥ʼ ʼaẖàrá֖y⁠w ʻàzarĕyá֣hẇ ha⁠kò̇hé֑n wĕ⁠ʻiṁ֞⁠wò kò̇hàni֧ym ׀ la⁠yhwá֛h şĕ̌mwòni֖ym bĕ̇néy-ẖáֽyil׃"],[26,18,"וַ⁠יַּעַמְד֞וּ עַל־עֻזִּיָּ֣הוּ הַ⁠מֶּ֗לֶךְ וַ⁠יֹּ֤אמְרוּ ל⁠וֹ֙ לֹא־לְ⁠ךָ֣ עֻזִּיָּ֗הוּ לְ⁠הַקְטִיר֙ לַֽ⁠יהוָ֔ה כִּ֣י לַ⁠כֹּהֲנִ֧ים בְּנֵי־אַהֲרֹ֛ן הַ⁠מְקֻדָּשִׁ֖ים לְ⁠הַקְטִ֑יר צֵ֤א מִן־הַ⁠מִּקְדָּשׁ֙ כִּ֣י מָעַ֔לְתָּ וְ⁠לֹֽא־לְ⁠ךָ֥ לְ⁠כָב֖וֹד מֵ⁠יְהוָ֥ה אֱלֹהִֽים׃","wa⁠yȧʻamĕd֞ẇ ʻal-ʻuzi̇yá֣̇hẇ ha⁠mė֗lekĕ wa⁠yò֤̇ʼmĕrẇ l⁠wò֙ lòʼ-lĕ⁠ká֣ ʻuzi̇yá̇֗hẇ lĕ⁠haqĕtiyr֙ laֽ⁠yhwá֔h ki֣̇y la⁠kò̇hàni֧ym bĕ̇néy-ʼahàrò֛n ha⁠mĕqudá̇şǐ֖ym lĕ⁠haqĕti֑yr ẕé֤ʼ min-ha⁠mi̇qĕdá̇ş̌֙ ki֣̇y máʻa֔lĕţá̇ wĕ⁠lòֽʼ-lĕ⁠ká֥ lĕ⁠káb֖wòd mé⁠yĕhwá֥h ʼèlòhiֽym׃"],[26,19,"וַ⁠יִּזְעַף֙ עֻזִּיָּ֔הוּ וּ⁠בְ⁠יָד֥⁠וֹ מִקְטֶ֖רֶת לְ⁠הַקְטִ֑יר וּ⁠בְ⁠זַעְפּ֣⁠וֹ עִם־הַ⁠כֹּהֲנִ֗ים וְ֠⁠הַ⁠צָּרַעַת זָרְחָ֨ה בְ⁠מִצְח֜⁠וֹ לִ⁠פְנֵ֤י הַ⁠כֹּֽהֲנִים֙ בְּ⁠בֵ֣ית יְהוָ֔ה מֵ⁠עַ֖ל לְ⁠מִזְבַּ֥ח הַ⁠קְּטֹֽרֶת׃","wa⁠yi̇zĕʻap֙ ʻuzi̇yá̇֔hẇ ẇ⁠bĕ⁠yád֥⁠wò miqĕte֖reţ lĕ⁠haqĕti֑yr ẇ⁠bĕ⁠zaʻĕṗ֣⁠wò ʻim-ha⁠kò̇hàni֗ym wĕ֠⁠ha⁠ẕá̇raʻaţ zárĕẖá֨h bĕ⁠miẕĕẖ֜⁠wò li⁠pĕné֤y ha⁠kòֽ̇hàniym֙ bĕ̇⁠bé֣yţ yĕhwá֔h mé⁠ʻa֖l lĕ⁠mizĕbȧ֥ẖ ha⁠qĕ̇tòֽreţ׃"],[26,20,"וַ⁠יִּ֣פֶן אֵלָ֡י⁠ו עֲזַרְיָהוּ֩ כֹהֵ֨ן הָ⁠רֹ֜אשׁ וְ⁠כָל־הַ⁠כֹּהֲנִ֗ים וְ⁠הִנֵּה־ה֤וּא מְצֹרָע֙ בְּ⁠מִצְח֔⁠וֹ וַ⁠יַּבְהִל֖וּ⁠הוּ מִ⁠שָּׁ֑ם וְ⁠גַם־הוּא֙ נִדְחַ֣ף לָ⁠צֵ֔את כִּ֥י נִגְּע֖⁠וֹ יְהוָֽה׃","wa⁠yi֣̇pen ʼélá֡y⁠w ʻàzarĕyáhẇ֩ kòhé֨n há⁠rò֜ʼş̌ wĕ⁠kál-ha⁠kò̇hàni֗ym wĕ⁠hiné̇h-h֤ẇʼ mĕẕòráʻ֙ bĕ̇⁠miẕĕẖ֔⁠wò wa⁠yȧbĕhil֖ẇ⁠hẇ mi⁠şá֑̇̌m wĕ⁠gam-hẇʼ֙ nidĕẖa֣p lá⁠ẕé֔ʼţ ki֥̇y nigĕ̇ʻ֖⁠wò yĕhwáֽh׃"],[26,21,"וַ⁠יְהִי֩ עֻזִּיָּ֨הוּ הַ⁠מֶּ֜לֶךְ מְצֹרָ֣ע ׀ עַד־י֣וֹם מוֹת֗⁠וֹ וַ⁠יֵּ֜שֶׁב בֵּ֤ית ה⁠חפשות מְצֹרָ֔ע כִּ֥י נִגְזַ֖ר מִ⁠בֵּ֣ית יְהוָ֑ה וְ⁠יוֹתָ֤ם בְּנ⁠וֹ֙ עַל־בֵּ֣ית הַ⁠מֶּ֔לֶךְ שׁוֹפֵ֖ט אֶת־עַ֥ם הָ⁠אָֽרֶץ׃","wa⁠yĕhiy֩ ʻuzi̇yá̇֨hẇ ha⁠mė֜lekĕ mĕẕòrá֣ʻ ׀ ʻad-y֣wòm mwòţ֗⁠wò wa⁠yé̇֜şěb bé֤̇yţ h⁠ẖpşwţ mĕẕòrá֔ʻ ki֥̇y nigĕza֖r mi⁠bé֣̇yţ yĕhwá֑h wĕ⁠ywòţá֤m bĕ̇n⁠wò֙ ʻal-bé֣̇yţ ha⁠mė֔lekĕ ş̌wòpé֖t ʼeţ-ʻa֥m há⁠ʼáֽreẕ׃"],[26,22,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י עֻזִּיָּ֔הוּ הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אֲחֲרֹנִ֑ים כָּתַ֛ב יְשַֽׁעְיָ֥הוּ בֶן־אָמ֖וֹץ הַ⁠נָּבִֽיא׃","wĕ⁠ye֨ţer֙ di̇bĕré֣y ʻuzi̇yá̇֔hẇ há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼàẖàròni֑ym ká̇ţa֛b yĕşǎֽʻĕyá֥hẇ ben-ʼám֖wòẕ ha⁠ná̇biֽyʼ׃"],[26,23,"וַ⁠יִּשְׁכַּ֨ב עֻזִּיָּ֜הוּ עִם־אֲבֹתָ֗י⁠ו וַ⁠יִּקְבְּר֨וּ אֹת֤⁠וֹ עִם־אֲבֹתָי⁠ו֙ בִּ⁠שְׂדֵ֤ה הַ⁠קְּבוּרָה֙ אֲשֶׁ֣ר לַ⁠מְּלָכִ֔ים כִּ֥י אָמְר֖וּ מְצוֹרָ֣ע ה֑וּא וַ⁠יִּמְלֹ֛ךְ יוֹתָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֨b ʻuzi̇yá̇֜hẇ ʻim-ʼàbòţá֗y⁠w wa⁠yi̇qĕbĕ̇r֨ẇ ʼòţ֤⁠wò ʻim-ʼàbòţáy⁠w֙ bi̇⁠şĕ̂dé֤h ha⁠qĕ̇bẇráh֙ ʼàşě֣r la⁠mĕ̇láki֔ym ki֥̇y ʼámĕr֖ẇ mĕẕwòrá֣ʻ h֑ẇʼ wa⁠yi̇mĕlò֛kĕ ywòţá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[27,1,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ יוֹתָ֣ם בְּ⁠מָלְכ֔⁠וֹ וְ⁠שֵׁשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה מָלַ֖ךְ בִּֽ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ יְרוּשָׁ֖ה בַּת־צָדֽוֹק׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ ywòţá֣m bĕ̇⁠málĕk֔⁠wò wĕ⁠şé̌ş̌-ʻeşĕ̂ré֣h şá̌ná֔h mála֖kĕ biֽ̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò yĕrẇşá֖̌h bȧţ-ẕádֽwòq׃"],[27,2,"וַ⁠יַּ֨עַשׂ הַ⁠יָּשָׁ֜ר בְּ⁠עֵינֵ֣י יְהוָ֗ה כְּ⁠כֹ֤ל אֲשֶׁר־עָשָׂה֙ עֻזִּיָּ֣הוּ אָבִ֔י⁠ו רַ֕ק לֹא־בָ֖א אֶל־הֵיכַ֣ל יְהוָ֑ה וְ⁠ע֥וֹד הָ⁠עָ֖ם מַשְׁחִיתִֽים׃","wa⁠yȧ֨ʻaş̂ ha⁠yá̇şá̌֜r bĕ̇⁠ʻéyné֣y yĕhwá֗h kĕ̇⁠kò֤l ʼàşěr-ʻáşá̂h֙ ʻuzi̇yá֣̇hẇ ʼábi֔y⁠w ra֕q lòʼ-bá֖ʼ ʼel-héyka֣l yĕhwá֑h wĕ⁠ʻ֥wòd há⁠ʻá֖m maşĕ̌ẖiyţiֽym׃"],[27,3,"ה֗וּא בָּנָ֛ה אֶת־שַׁ֥עַר בֵּית־יְהוָ֖ה הָ⁠עֶלְי֑וֹן וּ⁠בְ⁠חוֹמַ֥ת הָ⁠עֹ֛פֶל בָּנָ֖ה לָ⁠רֹֽב׃","h֗ẇʼ bá̇ná֛h ʼeţ-şǎ֥ʻar bé̇yţ-yĕhwá֖h há⁠ʻelĕy֑wòn ẇ⁠bĕ⁠ẖwòma֥ţ há⁠ʻò֛pel bá̇ná֖h lá⁠ròֽb׃"],[27,4,"וְ⁠עָרִ֥ים בָּנָ֖ה בְּ⁠הַר־יְהוּדָ֑ה וּ⁠בֶ⁠חֳרָשִׁ֣ים בָּנָ֔ה בִּֽירָנִיּ֖וֹת וּ⁠מִגְדָּלִֽים׃","wĕ⁠ʻári֥ym bá̇ná֖h bĕ̇⁠har-yĕhẇdá֑h ẇ⁠be⁠ẖoráşǐ֣ym bá̇ná֔h biֽ̇yrániẏ֖wòţ ẇ⁠migĕdá̇liֽym׃"],[27,5,"וְ֠⁠הוּא נִלְחַ֞ם עִם־מֶ֣לֶךְ בְּנֵי־עַמּוֹן֮ וַ⁠יֶּחֱזַ֣ק עֲלֵי⁠הֶם֒ וַ⁠יִּתְּנוּ־ל֨⁠וֹ בְנֵֽי־עַמּ֜וֹן בַּ⁠שָּׁנָ֣ה הַ⁠הִ֗יא מֵאָה֙ כִּכַּר־כֶּ֔סֶף וַ⁠עֲשֶׂ֨רֶת אֲלָפִ֤ים כֹּרִים֙ חִטִּ֔ים וּ⁠שְׂעוֹרִ֖ים עֲשֶׂ֣רֶת אֲלָפִ֑ים זֹ֗את הֵשִׁ֤יבוּ ל⁠וֹ֙ בְּנֵ֣י עַמּ֔וֹן ס וּ⁠בַ⁠שָּׁנָ֥ה הַ⁠שֵּׁנִ֖ית וְ⁠הַ⁠שְּׁלִשִֽׁית׃","wĕ֠⁠hẇʼ nilĕẖa֞m ʻim-me֣lekĕ bĕ̇néy-ʻaṁwòn֮ wa⁠yėẖèza֣q ʻàléy⁠hem֒ wa⁠yi̇ţĕ̇nẇ-l֨⁠wò bĕnéֽy-ʻaṁ֜wòn bȧ⁠şá̇̌ná֣h ha⁠hi֗yʼ méʼáh֙ ki̇kȧr-kė֔sep wa⁠ʻàşê֨reţ ʼàlápi֤ym kò̇riym֙ ẖiti̇֔ym ẇ⁠şĕ̂ʻwòri֖ym ʻàşê֣reţ ʼàlápi֑ym zò֗ʼţ héşǐ֤ybẇ l⁠wò֙ bĕ̇né֣y ʻaṁ֔wòn s ẇ⁠ba⁠şá̇̌ná֥h ha⁠şé̇̌ni֖yţ wĕ⁠ha⁠şĕ̇̌lişǐֽyţ׃"],[27,6,"וַ⁠יִּתְחַזֵּ֖ק יוֹתָ֑ם כִּ֚י הֵכִ֣ין דְּרָכָ֔י⁠ו לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהָֽי⁠ו׃","wa⁠yi̇ţĕẖazé֖̇q ywòţá֑m ki֚̇y héki֣yn dĕ̇ráká֔y⁠w li⁠pĕné֖y yĕhwá֥h ʼèlòháֽy⁠w׃"],[27,7,"וְ⁠יֶתֶר֙ דִּבְרֵ֣י יוֹתָ֔ם וְ⁠כָל־מִלְחֲמֹתָ֖י⁠ו וּ⁠דְרָכָ֑י⁠ו הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־סֵ֥פֶר מַלְכֵֽי־יִשְׂרָאֵ֖ל וִ⁠יהוּדָֽה׃","wĕ⁠yeţer֙ di̇bĕré֣y ywòţá֔m wĕ⁠kál-milĕẖàmòţá֖y⁠w ẇ⁠dĕráká֑y⁠w hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-sé֥per malĕkéֽy-yişĕ̂ráʼé֖l wi⁠yhẇdáֽh׃"],[27,8,"בֶּן־עֶשְׂרִ֧ים וְ⁠חָמֵ֛שׁ שָׁנָ֖ה הָיָ֣ה בְ⁠מָלְכ֑⁠וֹ וְ⁠שֵׁשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-ʻeşĕ̂ri֧ym wĕ⁠ẖámé֛ş̌ şá̌ná֖h háyá֣h bĕ⁠málĕk֑⁠wò wĕ⁠şé̌ş̌-ʻeşĕ̂ré֣h şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[27,9,"וַ⁠יִּשְׁכַּ֤ב יוֹתָם֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקְבְּר֥וּ אֹת֖⁠וֹ בְּ⁠עִ֣יר דָּוִ֑יד וַ⁠יִּמְלֹ֛ךְ אָחָ֥ז בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ywòţám֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֖⁠wò bĕ̇⁠ʻi֣yr dá̇wi֑yd wa⁠yi̇mĕlò֛kĕ ʼáẖá֥z bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[28,1,"בֶּן־עֶשְׂרִ֤ים שָׁנָה֙ אָחָ֣ז בְּ⁠מָלְכ֔⁠וֹ וְ⁠שֵׁשׁ־עֶשְׂרֵ֣ה שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠לֹא־עָשָׂ֧ה הַ⁠יָּשָׁ֛ר בְּ⁠עֵינֵ֥י יְהוָ֖ה כְּ⁠דָוִ֥יד אָבִֽי⁠ו׃","bėn-ʻeşĕ̂ri֤ym şá̌náh֙ ʼáẖá֣z bĕ̇⁠málĕk֔⁠wò wĕ⁠şé̌ş̌-ʻeşĕ̂ré֣h şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠lòʼ-ʻáşá֧̂h ha⁠yá̇şá֛̌r bĕ̇⁠ʻéyné֥y yĕhwá֖h kĕ̇⁠dáwi֥yd ʼábiֽy⁠w׃"],[28,2,"וַ⁠יֵּ֕לֶךְ בְּ⁠דַרְכֵ֖י מַלְכֵ֣י יִשְׂרָאֵ֑ל וְ⁠גַ֧ם מַסֵּכ֛וֹת עָשָׂ֖ה לַ⁠בְּעָלִֽים׃","wa⁠yé̇֕lekĕ bĕ̇⁠darĕké֖y malĕké֣y yişĕ̂ráʼé֑l wĕ⁠ga֧m masé̇k֛wòţ ʻáşá֖̂h la⁠bĕ̇ʻáliֽym׃"],[28,3,"וְ⁠ה֥וּא הִקְטִ֖יר בְּ⁠גֵ֣יא בֶן־הִנֹּ֑ם וַ⁠יַּבְעֵ֤ר אֶת־בָּנָי⁠ו֙ בָּ⁠אֵ֔שׁ כְּ⁠תֹֽעֲבוֹת֙ הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ הֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠h֥ẇʼ hiqĕti֖yr bĕ̇⁠gé֣yʼ ben-hinò֑̇m wa⁠yȧbĕʻé֤r ʼeţ-bá̇náy⁠w֙ bá̇⁠ʼé֔ş̌ kĕ̇⁠ţòֽʻàbwòţ֙ ha⁠ġwòyi֔m ʼàşěr֙ hòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[28,4,"וַ⁠יְזַבֵּ֧חַ וַ⁠יְקַטֵּ֛ר בַּ⁠בָּמ֖וֹת וְ⁠עַל־הַ⁠גְּבָע֑וֹת וְ⁠תַ֖חַת כָּל־עֵ֥ץ רַעֲנָֽן׃","wa⁠yĕzabé֧̇ẖa wa⁠yĕqaté֛̇r bȧ⁠bá̇m֖wòţ wĕ⁠ʻal-ha⁠gĕ̇báʻ֑wòţ wĕ⁠ţa֖ẖaţ ká̇l-ʻé֥ẕ raʻànáֽn׃"],[28,5,"וַֽ⁠יִּתְּנֵ֜⁠הוּ יְהוָ֣ה אֱלֹהָי⁠ו֮ בְּ⁠יַ֣ד מֶ֣לֶךְ אֲרָם֒ וַ⁠יַּ֨כּוּ־ב֔⁠וֹ וַ⁠יִּשְׁבּ֤וּ מִמֶּ֨⁠נּוּ֙ שִׁבְיָ֣ה גְדוֹלָ֔ה וַ⁠יָּבִ֖יאוּ דַּרְמָ֑שֶׂק וְ֠⁠גַם בְּ⁠יַד־מֶ֤לֶךְ יִשְׂרָאֵל֙ נִתָּ֔ן וַ⁠יַּךְ־בּ֖⁠וֹ מַכָּ֥ה גְדוֹלָֽה׃ס","waֽ⁠yi̇ţĕ̇né֜⁠hẇ yĕhwá֣h ʼèlòháy⁠w֮ bĕ̇⁠ya֣d me֣lekĕ ʼàrám֒ wa⁠yȧ֨k̇ẇ-b֔⁠wò wa⁠yi̇şĕ̌ḃ֤ẇ mimė֨⁠ṅẇ֙ şǐbĕyá֣h gĕdwòlá֔h wa⁠yá̇bi֖yʼẇ dȧrĕmá֑şêq wĕ֠⁠gam bĕ̇⁠yad-me֤lekĕ yişĕ̂ráʼél֙ niţá̇֔n wa⁠yȧkĕ-ḃ֖⁠wò maká֥̇h gĕdwòláֽh׃s"],[28,6,"וַ⁠יַּהֲרֹג֩ פֶּ֨קַח בֶּן־רְמַלְיָ֜הוּ בִּֽ⁠יהוּדָ֗ה מֵאָ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֛לֶף בְּ⁠י֥וֹם אֶחָ֖ד הַ⁠כֹּ֣ל בְּנֵי־חָ֑יִל בְּ⁠עָזְבָ֕⁠ם אֶת־יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתָֽ⁠ם׃","wa⁠yȧhàròg֩ pė֨qaẖ bėn-rĕmalĕyá֜hẇ biֽ̇⁠yhẇdá֗h méʼá֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֛lep bĕ̇⁠y֥wòm ʼeẖá֖d ha⁠kò֣̇l bĕ̇néy-ẖá֑yil bĕ̇⁠ʻázĕbá֕⁠m ʼeţ-yĕhwá֖h ʼèlòhé֥y ʼàbwòţáֽ⁠m׃"],[28,7,"וַֽ⁠יַּהֲרֹ֞ג זִכְרִ֣י ׀ גִּבּ֣וֹר אֶפְרַ֗יִם אֶת־מַעֲשֵׂיָ֨הוּ֙ בֶּן־הַ⁠מֶּ֔לֶךְ וְ⁠אֶת־עַזְרִיקָ֖ם נְגִ֣יד הַ⁠בָּ֑יִת וְ⁠אֶת־אֶלְקָנָ֖ה מִשְׁנֵ֥ה הַ⁠מֶּֽלֶךְ׃ס","waֽ⁠yȧhàrò֞g zikĕri֣y ׀ gi̇ḃ֣wòr ʼepĕra֗yim ʼeţ-maʻàşé̂yá֨hẇ֙ bėn-ha⁠mė֔lekĕ wĕ⁠ʼeţ-ʻazĕriyqá֖m nĕgi֣yd ha⁠bá֑̇yiţ wĕ⁠ʼeţ-ʼelĕqáná֖h mişĕ̌né֥h ha⁠mėֽlekĕ׃s"],[28,8,"וַ⁠יִּשְׁבּוּ֩ בְנֵֽי־יִשְׂרָאֵ֨ל מֵֽ⁠אֲחֵי⁠הֶ֜ם מָאתַ֣יִם אֶ֗לֶף נָשִׁים֙ בָּנִ֣ים וּ⁠בָנ֔וֹת וְ⁠גַם־שָׁלָ֥ל רָ֖ב בָּזְז֣וּ מֵ⁠הֶ֑ם וַ⁠יָּבִ֥יאוּ אֶת־הַ⁠שָּׁלָ֖ל לְ⁠שֹׁמְרֽוֹן׃ס","wa⁠yi̇şĕ̌ḃẇ֩ bĕnéֽy-yişĕ̂ráʼé֨l méֽ⁠ʼàẖéy⁠he֜m máʼţa֣yim ʼe֗lep náşǐym֙ bá̇ni֣ym ẇ⁠bán֔wòţ wĕ⁠gam-şá̌lá֥l rá֖b bá̇zĕz֣ẇ mé⁠he֑m wa⁠yá̇bi֥yʼẇ ʼeţ-ha⁠şá̇̌lá֖l lĕ⁠şò̌mĕrֽwòn׃s"],[28,9,"וְ֠⁠שָׁם הָיָ֨ה נָבִ֥יא לַֽ⁠יהוָה֮ עֹדֵ֣ד שְׁמ⁠וֹ֒ וַ⁠יֵּצֵ֗א לִ⁠פְנֵ֤י הַ⁠צָּבָא֙ הַ⁠בָּ֣א לְ⁠שֹׁמְר֔וֹן וַ⁠יֹּ֣אמֶר לָ⁠הֶ֗ם הִ֠נֵּה בַּ⁠חֲמַ֨ת יְהוָ֧ה אֱלֹהֵֽי־אֲבוֹתֵי⁠כֶ֛ם עַל־יְהוּדָ֖ה נְתָנָ֣⁠ם בְּ⁠יֶדְ⁠כֶ֑ם וַ⁠תַּֽהַרְגוּ־בָ֣⁠ם בְ⁠זַ֔עַף עַ֥ד לַ⁠שָּׁמַ֖יִם הִגִּֽיעַ׃","wĕ֠⁠şá̌m háyá֨h nábi֥yʼ laֽ⁠yhwáh֮ ʻòdé֣d şĕ̌m⁠wò֒ wa⁠yé̇ẕé֗ʼ li⁠pĕné֤y ha⁠ẕá̇báʼ֙ ha⁠bá֣̇ʼ lĕ⁠şò̌mĕr֔wòn wa⁠yò֣̇ʼmer lá⁠he֗m hi֠né̇h bȧ⁠ẖàma֨ţ yĕhwá֧h ʼèlòhéֽy-ʼàbwòţéy⁠ke֛m ʻal-yĕhẇdá֖h nĕţáná֣⁠m bĕ̇⁠yedĕ⁠ke֑m wa⁠ţȧֽharĕgẇ-bá֣⁠m bĕ⁠za֔ʻap ʻa֥d la⁠şá̇̌ma֖yim higiֽ̇yʻa׃"],[28,10,"וְ֠⁠עַתָּה בְּנֵֽי־יְהוּדָ֤ה וִֽ⁠ירוּשָׁלִַ֨ם֙ אַתֶּ֣ם אֹמְרִ֔ים לִ⁠כְבֹּ֛שׁ לַ⁠עֲבָדִ֥ים וְ⁠לִ⁠שְׁפָח֖וֹת לָ⁠כֶ֑ם הֲ⁠לֹ֤א רַק־אַתֶּם֙ עִמָּ⁠כֶ֣ם אֲשָׁמ֔וֹת לַ⁠יהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ֠⁠ʻaţá̇h bĕ̇néֽy-yĕhẇdá֤h wiֽ⁠yrẇşá̌lia֨m֙ ʼaţė֣m ʼòmĕri֔ym li⁠kĕbò֛̇ş̌ la⁠ʻàbádi֥ym wĕ⁠li⁠şĕ̌páẖ֖wòţ lá⁠ke֑m hà⁠lò֤ʼ raq-ʼaţėm֙ ʻimá̇⁠ke֣m ʼàşá̌m֔wòţ la⁠yhwá֖h ʼèlòhéy⁠keֽm׃"],[28,11,"וְ⁠עַתָּ֣ה שְׁמָע֔וּ⁠נִי וְ⁠הָשִׁ֨יבוּ֙ הַ⁠שִּׁבְיָ֔ה אֲשֶׁ֥ר שְׁבִיתֶ֖ם מֵ⁠אֲחֵי⁠כֶ֑ם כִּ֛י חֲר֥וֹן אַף־יְהוָ֖ה עֲלֵי⁠כֶֽם׃ס","wĕ⁠ʻaţá֣̇h şĕ̌máʻ֔ẇ⁠niy wĕ⁠háşǐ֨ybẇ֙ ha⁠şi̇̌bĕyá֔h ʼàşě֥r şĕ̌biyţe֖m mé⁠ʼàẖéy⁠ke֑m ki֛̇y ẖàr֥wòn ʼap-yĕhwá֖h ʻàléy⁠keֽm׃s"],[28,12,"וַ⁠יָּקֻ֨מוּ אֲנָשִׁ֜ים מֵ⁠רָאשֵׁ֣י בְנֵֽי־אֶפְרַ֗יִם עֲזַרְיָ֤הוּ בֶן־יְהֽוֹחָנָן֙ בֶּרֶכְיָ֣הוּ בֶן־מְשִׁלֵּמ֔וֹת וִֽ⁠יחִזְקִיָּ֨הוּ֙ בֶּן־שַׁלֻּ֔ם וַ⁠עֲמָשָׂ֖א בֶּן־חַדְלָ֑י עַל־הַ⁠בָּאִ֖ים מִן־הַ⁠צָּבָֽא׃","wa⁠yá̇qu֨mẇ ʼànáşǐ֜ym mé⁠ráʼşé֣̌y bĕnéֽy-ʼepĕra֗yim ʻàzarĕyá֤hẇ ben-yĕhֽwòẖánán֙ bėrekĕyá֣hẇ ben-mĕşǐlé̇m֔wòţ wiֽ⁠yẖizĕqiyá̇֨hẇ֙ bėn-şǎlu̇֔m wa⁠ʻàmáşá֖̂ʼ bėn-ẖadĕlá֑y ʻal-ha⁠bá̇ʼi֖ym min-ha⁠ẕá̇báֽʼ׃"],[28,13,"וַ⁠יֹּאמְר֣וּ לָ⁠הֶ֗ם לֹא־תָבִ֤יאוּ אֶת־הַ⁠שִּׁבְיָה֙ הֵ֔נָּה כִּי֩ לְ⁠אַשְׁמַ֨ת יְהוָ֤ה עָלֵ֨י⁠נוּ֙ אַתֶּ֣ם אֹמְרִ֔ים לְ⁠הֹסִ֥יף עַל־חַטֹּאתֵ֖י⁠נוּ וְ⁠עַל־אַשְׁמָתֵ֑י⁠נוּ כִּֽי־רַבָּ֤ה אַשְׁמָה֙ לָ֔⁠נוּ וַ⁠חֲר֥וֹן אָ֖ף עַל־יִשְׂרָאֵֽל׃ס","wa⁠yò̇ʼmĕr֣ẇ lá⁠he֗m lòʼ-ţábi֤yʼẇ ʼeţ-ha⁠şi̇̌bĕyáh֙ hé֔ná̇h ki̇y֩ lĕ⁠ʼaşĕ̌ma֨ţ yĕhwá֤h ʻálé֨y⁠nẇ֙ ʼaţė֣m ʼòmĕri֔ym lĕ⁠hòsi֥yp ʻal-ẖatò̇ʼţé֖y⁠nẇ wĕ⁠ʻal-ʼaşĕ̌máţé֑y⁠nẇ kiֽ̇y-rabá֤̇h ʼaşĕ̌máh֙ lá֔⁠nẇ wa⁠ẖàr֥wòn ʼá֖p ʻal-yişĕ̂ráʼéֽl׃s"],[28,14,"וַ⁠יַּעֲזֹ֣ב הֶֽ⁠חָל֗וּץ אֶת־הַ⁠שִּׁבְיָה֙ וְ⁠אֶת־הַ⁠בִּזָּ֔ה לִ⁠פְנֵ֥י הַ⁠שָּׂרִ֖ים וְ⁠כָל־הַ⁠קָּהָֽל׃","wa⁠yȧʻàzò֣b heֽ⁠ẖál֗ẇẕ ʼeţ-ha⁠şi̇̌bĕyáh֙ wĕ⁠ʼeţ-ha⁠bi̇zá̇֔h li⁠pĕné֥y ha⁠şá̇̂ri֖ym wĕ⁠kál-ha⁠qá̇háֽl׃"],[28,15,"וַ⁠יָּקֻ֣מוּ הָ⁠אֲנָשִׁים֩ אֲשֶׁר־נִקְּב֨וּ בְ⁠שֵׁמ֜וֹת וַ⁠יַּחֲזִ֣יקוּ בַ⁠שִּׁבְיָ֗ה וְ⁠כָֽל־מַעֲרֻמֵּי⁠הֶם֮ הִלְבִּ֣ישׁוּ מִן־הַ⁠שָּׁלָל֒ וַ⁠יַּלְבִּשׁ֣וּ⁠ם וַ֠⁠יַּנְעִלוּ⁠ם וַ⁠יַּאֲכִל֨וּ⁠ם וַ⁠יַּשְׁק֜וּ⁠ם וַ⁠יְסֻכ֗וּ⁠ם וַ⁠יְנַהֲל֤וּ⁠ם בַּ⁠חֲמֹרִים֙ לְ⁠כָל־כּוֹשֵׁ֔ל וַ⁠יְבִיא֛וּ⁠ם יְרֵח֥וֹ עִיר־הַ⁠תְּמָרִ֖ים אֵ֣צֶל אֲחֵי⁠הֶ֑ם וַ⁠יָּשׁ֖וּבוּ שֹׁמְרֽוֹן׃פ","wa⁠yá̇qu֣mẇ há⁠ʼànáşǐym֩ ʼàşěr-niqĕ̇b֨ẇ bĕ⁠şé̌m֜wòţ wa⁠yȧẖàzi֣yqẇ ba⁠şi̇̌bĕyá֗h wĕ⁠káֽl-maʻàrumé̇y⁠hem֮ hilĕbi֣̇yş̌ẇ min-ha⁠şá̇̌lál֒ wa⁠yȧlĕbi̇ş֣̌ẇ⁠m wa֠⁠yȧnĕʻilẇ⁠m wa⁠yȧʼàkil֨ẇ⁠m wa⁠yȧşĕ̌q֜ẇ⁠m wa⁠yĕsuk֗ẇ⁠m wa⁠yĕnahàl֤ẇ⁠m bȧ⁠ẖàmòriym֙ lĕ⁠kál-k̇wòşé̌֔l wa⁠yĕbiyʼ֛ẇ⁠m yĕréẖ֥wò ʻiyr-ha⁠ţĕ̇mári֖ym ʼé֣ẕel ʼàẖéy⁠he֑m wa⁠yá̇ş֖̌ẇbẇ şò̌mĕrֽwòn׃p"],[28,16,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא שָׁלַ֞ח הַ⁠מֶּ֧לֶךְ אָחָ֛ז עַל־מַלְכֵ֥י אַשּׁ֖וּר לַ⁠עְזֹ֥ר לֽ⁠וֹ׃","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ şá̌la֞ẖ ha⁠mė֧lekĕ ʼáẖá֛z ʻal-malĕké֥y ʼaş֖̇̌ẇr la⁠ʻĕzò֥r lֽ⁠wò׃"],[28,17,"וְ⁠ע֥וֹד אֲדוֹמִ֖ים בָּ֑אוּ וַ⁠יַּכּ֥וּ בִ⁠יהוּדָ֖ה וַ⁠יִּשְׁבּוּ־שֶֽׁבִי׃","wĕ⁠ʻ֥wòd ʼàdwòmi֖ym bá֑̇ʼẇ wa⁠yȧk֥̇ẇ bi⁠yhẇdá֖h wa⁠yi̇şĕ̌ḃẇ-şěֽbiy׃"],[28,18,"וּ⁠פְלִשְׁתִּ֣ים פָּשְׁט֗וּ בְּ⁠עָרֵ֨י הַ⁠שְּׁפֵלָ֣ה וְ⁠הַ⁠נֶּגֶב֮ לִֽ⁠יהוּדָה֒ וַֽ֠⁠יִּלְכְּדוּ אֶת־בֵּֽית־שֶׁ֨מֶשׁ וְ⁠אֶת־אַיָּל֜וֹן וְ⁠אֶת־הַ⁠גְּדֵר֗וֹת וְ⁠אֶת־שׂוֹכ֤וֹ וּ⁠בְנוֹתֶ֨י⁠הָ֙ וְ⁠אֶת־תִּמְנָ֣ה וּ⁠בְנוֹתֶ֔י⁠הָ וְ⁠אֶת־גִּמְז֖וֹ וְ⁠אֶת־בְּנֹתֶ֑י⁠הָ וַ⁠יֵּשְׁב֖וּ שָֽׁם׃","ẇ⁠pĕlişĕ̌ţi֣̇ym pá̇şĕ̌t֗ẇ bĕ̇⁠ʻáré֨y ha⁠şĕ̇̌pélá֣h wĕ⁠ha⁠nėgeb֮ liֽ⁠yhẇdáh֒ waֽ֠⁠yi̇lĕkĕ̇dẇ ʼeţ-béֽ̇yţ-şě֨meş̌ wĕ⁠ʼeţ-ʼayá̇l֜wòn wĕ⁠ʼeţ-ha⁠gĕ̇dér֗wòţ wĕ⁠ʼeţ-ş̂wòk֤wò ẇ⁠bĕnwòţe֨y⁠há֙ wĕ⁠ʼeţ-ţi̇mĕná֣h ẇ⁠bĕnwòţe֔y⁠há wĕ⁠ʼeţ-gi̇mĕz֖wò wĕ⁠ʼeţ-bĕ̇nòţe֑y⁠há wa⁠yé̇şĕ̌b֖ẇ şáֽ̌m׃"],[28,19,"כִּֽי־הִכְנִ֤יעַ יְהוָה֙ אֶת־יְהוּדָ֔ה בַּ⁠עֲב֖וּר אָחָ֣ז מֶֽלֶךְ־יִשְׂרָאֵ֑ל כִּ֤י הִפְרִ֨יעַ֙ בִּֽ⁠יהוּדָ֔ה וּ⁠מָע֥וֹל מַ֖עַל בַּ⁠יהוָֽה׃","kiֽ̇y-hikĕni֤yʻa yĕhwáh֙ ʼeţ-yĕhẇdá֔h bȧ⁠ʻàb֖ẇr ʼáẖá֣z meֽlekĕ-yişĕ̂ráʼé֑l ki֤̇y hipĕri֨yʻa֙ biֽ̇⁠yhẇdá֔h ẇ⁠máʻ֥wòl ma֖ʻal bȧ⁠yhwáֽh׃"],[28,20,"וַ⁠יָּבֹ֣א עָלָ֔י⁠ו תִּלְּגַ֥ת פִּלְנְאֶ֖סֶר מֶ֣לֶךְ אַשּׁ֑וּר וַ⁠יָּ֥צַר ל֖⁠וֹ וְ⁠לֹ֥א חֲזָקֽ⁠וֹ׃","wa⁠yá̇bò֣ʼ ʻálá֔y⁠w ţi̇lĕ̇ga֥ţ pi̇lĕnĕʼe֖ser me֣lekĕ ʼaş֑̇̌ẇr wa⁠yá֥̇ẕar l֖⁠wò wĕ⁠lò֥ʼ ẖàzáqֽ⁠wò׃"],[28,21,"כִּֽי־חָלַ֤ק אָחָז֙ אֶת־בֵּ֣ית יְהוָ֔ה וְ⁠אֶת־בֵּ֥ית הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠שָּׂרִ֑ים וַ⁠יִּתֵּן֙ לְ⁠מֶ֣לֶךְ אַשּׁ֔וּר וְ⁠לֹ֥א לְ⁠עֶזְרָ֖ה לֽ⁠וֹ׃","kiֽ̇y-ẖála֤q ʼáẖáz֙ ʼeţ-bé֣̇yţ yĕhwá֔h wĕ⁠ʼeţ-bé֥̇yţ ha⁠mė֖lekĕ wĕ⁠ha⁠şá̇̂ri֑ym wa⁠yi̇ţé̇n֙ lĕ⁠me֣lekĕ ʼaş̇̌֔ẇr wĕ⁠lò֥ʼ lĕ⁠ʻezĕrá֖h lֽ⁠wò׃"],[28,22,"וּ⁠בְ⁠עֵת֙ הָצֵ֣ר ל֔⁠וֹ וַ⁠יּ֖וֹסֶף לִ⁠מְע֣וֹל בַּ⁠יהוָ֑ה ה֖וּא הַ⁠מֶּ֥לֶךְ אָחָֽז׃","ẇ⁠bĕ⁠ʻéţ֙ háẕé֣r l֔⁠wò wa⁠ẏ֖wòsep li⁠mĕʻ֣wòl bȧ⁠yhwá֑h h֖ẇʼ ha⁠mė֥lekĕ ʼáẖáֽz׃"],[28,23,"וַ⁠יִּזְבַּ֗ח לֵֽ⁠אלֹהֵ֣י דַרְמֶשֶׂק֮ הַ⁠מַּכִּ֣ים בּ⁠וֹ֒ וַ⁠יֹּ֗אמֶר כִּ֠י אֱלֹהֵ֤י מַלְכֵֽי־אֲרָם֙ הֵ֚ם מַעְזְרִ֣ים אוֹתָ֔⁠ם לָ⁠הֶ֥ם אֲזַבֵּ֖חַ וְ⁠יַעְזְר֑וּ⁠נִי וְ⁠הֵ֛ם הָֽיוּ־ל֥⁠וֹ לְ⁠הַכְשִׁיל֖⁠וֹ וּ⁠לְ⁠כָל־יִשְׂרָאֵֽל׃","wa⁠yi̇zĕbȧ֗ẖ léֽ⁠ʼlòhé֣y darĕmeşêq֮ ha⁠mȧki֣̇ym ḃ⁠wò֒ wa⁠yò̇֗ʼmer ki̇֠y ʼèlòhé֤y malĕkéֽy-ʼàrám֙ hé֚m maʻĕzĕri֣ym ʼwòţá֔⁠m lá⁠he֥m ʼàzabé֖̇ẖa wĕ⁠yaʻĕzĕr֑ẇ⁠niy wĕ⁠hé֛m háֽyẇ-l֥⁠wò lĕ⁠hakĕşǐyl֖⁠wò ẇ⁠lĕ⁠kál-yişĕ̂ráʼéֽl׃"],[28,24,"וַ⁠יֶּאֱסֹ֨ף אָחָ֜ז אֶת־כְּלֵ֣י בֵית־הָֽ⁠אֱלֹהִ֗ים וַ⁠יְקַצֵּץ֙ אֶת־כְּלֵ֣י בֵית־הָֽ⁠אֱלֹהִ֔ים וַ⁠יִּסְגֹּ֖ר אֶת־דַּלְת֣וֹת בֵּית־יְהוָ֑ה וַ⁠יַּ֨עַשׂ ל֧⁠וֹ מִזְבְּח֛וֹת בְּ⁠כָל־פִּנָּ֖ה בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yėʼèsò֨p ʼáẖá֜z ʼeţ-kĕ̇lé֣y béyţ-hֽá⁠ʼèlòhi֗ym wa⁠yĕqaẕé̇ẕ֙ ʼeţ-kĕ̇lé֣y béyţ-háֽ⁠ʼèlòhi֔ym wa⁠yi̇sĕgò֖̇r ʼeţ-dȧlĕţ֣wòţ bé̇yţ-yĕhwá֑h wa⁠yȧ֨ʻaş̂ l֧⁠wò mizĕbĕ̇ẖ֛wòţ bĕ̇⁠kál-pi̇ná֖̇h bi̇⁠yrẇşá̌liáֽm׃"],[28,25,"וּ⁠בְ⁠כָל־עִ֨יר וָ⁠עִ֤יר לִֽ⁠יהוּדָה֙ עָשָׂ֣ה בָמ֔וֹת לְ⁠קַטֵּ֖ר לֵֽ⁠אלֹהִ֣ים אֲחֵרִ֑ים וַ⁠יַּכְעֵ֕ס אֶת־יְהוָ֖ה אֱלֹהֵ֥י אֲבֹתָֽי⁠ו׃","ẇ⁠bĕ⁠kál-ʻi֨yr wá⁠ʻi֤yr liֽ⁠yhẇdáh֙ ʻáşá֣̂h bám֔wòţ lĕ⁠qaté֖̇r léֽ⁠ʼlòhi֣ym ʼàẖéri֑ym wa⁠yȧkĕʻé֕s ʼeţ-yĕhwá֖h ʼèlòhé֥y ʼàbòţáֽy⁠w׃"],[28,26,"וְ⁠יֶ֤תֶר דְּבָרָי⁠ו֙ וְ⁠כָל־דְּרָכָ֔י⁠ו הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אַחֲרוֹנִ֑ים הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־סֵ֥פֶר מַלְכֵֽי־יְהוּדָ֖ה וְ⁠יִשְׂרָאֵֽל׃","wĕ⁠ye֤ţer dĕ̇báráy⁠w֙ wĕ⁠kál-dĕ̇ráká֔y⁠w há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼaẖàrwòni֑ym hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-sé֥per malĕkéֽy-yĕhẇdá֖h wĕ⁠yişĕ̂ráʼéֽl׃"],[28,27,"וַ⁠יִּשְׁכַּ֨ב אָחָ֜ז עִם־אֲבֹתָ֗י⁠ו וַֽ⁠יִּקְבְּרֻ֤⁠הוּ בָ⁠עִיר֙ בִּ⁠יר֣וּשָׁלִַ֔ם כִּ֚י לֹ֣א הֱבִיאֻ֔⁠הוּ לְ⁠קִבְרֵ֖י מַלְכֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּמְלֹ֛ךְ יְחִזְקִיָּ֥הֽוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֨b ʼáẖá֜z ʻim-ʼàbòţá֗y⁠w waֽ⁠yi̇qĕbĕ̇ru֤⁠hẇ bá⁠ʻiyr֙ bi̇⁠yr֣ẇşá̌lia֔m ki֚̇y lò֣ʼ hèbiyʼu֔⁠hẇ lĕ⁠qibĕré֖y malĕké֣y yişĕ̂ráʼé֑l wa⁠yi̇mĕlò֛kĕ yĕẖizĕqiyá֥̇hֽẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[29,1,"יְחִזְקִיָּ֣הוּ מָלַ֗ךְ בֶּן־עֶשְׂרִ֤ים וְ⁠חָמֵשׁ֙ שָׁנָ֔ה וְ⁠עֶשְׂרִ֤ים וָ⁠תֵ֨שַׁע֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ אֲבִיָּ֖ה בַּת־זְכַרְיָֽהוּ׃","yĕẖizĕqiyá֣̇hẇ mála֗kĕ bėn-ʻeşĕ̂ri֤ym wĕ⁠ẖáméş̌֙ şá̌ná֔h wĕ⁠ʻeşĕ̂ri֤ym wá⁠ţé֨şǎʻ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ʼàbiyá֖̇h bȧţ-zĕkarĕyáֽhẇ׃"],[29,2,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה דָּוִ֥יד אָבִֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h dá̇wi֥yd ʼábiֽy⁠w׃"],[29,3,"ה֣וּא בַ⁠שָּׁנָה֩ הָ⁠רִאשׁוֹנָ֨ה לְ⁠מָלְכ֜⁠וֹ בַּ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֗וֹן פָּתַ֛ח אֶת־דַּלְת֥וֹת בֵּית־יְהוָ֖ה וַֽ⁠יְחַזְּקֵֽ⁠ם׃","h֣ẇʼ ba⁠şá̇̌náh֩ há⁠riʼş̌wòná֨h lĕ⁠málĕk֜⁠wò bȧ⁠ẖò֣deş̌ há⁠riʼş̌֗wòn pá̇ţa֛ẖ ʼeţ-dȧlĕţ֥wòţ bé̇yţ-yĕhwá֖h waֽ⁠yĕẖazĕ̇qéֽ⁠m׃"],[29,4,"וַ⁠יָּבֵ֥א אֶת־הַ⁠כֹּהֲנִ֖ים וְ⁠אֶת־הַ⁠לְוִיִּ֑ם וַ⁠יַּֽאַסְפֵ֖⁠ם לִ⁠רְח֥וֹב הַ⁠מִּזְרָֽח׃","wa⁠yá̇bé֥ʼ ʼeţ-ha⁠kò̇hàni֖ym wĕ⁠ʼeţ-ha⁠lĕwiyi֑̇m wa⁠yȧֽʼasĕpé֖⁠m li⁠rĕẖ֥wòb ha⁠mi̇zĕráֽẖ׃"],[29,5,"וַ⁠יֹּ֥אמֶר לָ⁠הֶ֖ם שְׁמָע֣וּ⁠נִי הַ⁠לְוִיִּ֑ם עַתָּ֣ה הִֽתְקַדְּשׁ֗וּ וְ⁠קַדְּשׁוּ֙ אֶת־בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י אֲבֹתֵי⁠כֶ֔ם וְ⁠הוֹצִ֥יאוּ אֶת־הַ⁠נִּדָּ֖ה מִן־הַ⁠קֹּֽדֶשׁ׃","wa⁠yò֥̇ʼmer lá⁠he֖m şĕ̌máʻ֣ẇ⁠niy ha⁠lĕwiyi֑̇m ʻaţá֣̇h hiֽţĕqadĕ̇ş̌֗ẇ wĕ⁠qadĕ̇ş̌ẇ֙ ʼeţ-bé֤̇yţ yĕhwáh֙ ʼèlòhé֣y ʼàbòţéy⁠ke֔m wĕ⁠hwòẕi֥yʼẇ ʼeţ-ha⁠ni̇dá֖̇h min-ha⁠qòֽ̇deş̌׃"],[29,6,"כִּֽי־מָעֲל֣וּ אֲבֹתֵ֗י⁠נוּ וְ⁠עָשׂ֥וּ הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָֽה־אֱלֹהֵ֖י⁠נוּ וַ⁠יַּֽעַזְבֻ֑⁠הוּ וַ⁠יַּסֵּ֧בּוּ פְנֵי⁠הֶ֛ם מִ⁠מִּשְׁכַּ֥ן יְהוָ֖ה וַ⁠יִּתְּנוּ־עֹֽרֶף׃","kiֽ̇y-máʻàl֣ẇ ʼàbòţé֗y⁠nẇ wĕ⁠ʻáş֥̂ẇ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh-ʼèlòhé֖y⁠nẇ wa⁠yȧֽʻazĕbu֑⁠hẇ wa⁠yȧsé֧̇ḃẇ pĕnéy⁠he֛m mi⁠mi̇şĕ̌kȧ֥n yĕhwá֖h wa⁠yi̇ţĕ̇nẇ-ʻòֽrep׃"],[29,7,"גַּ֣ם סָֽגְר֞וּ דַּלְת֣וֹת הָ⁠אוּלָ֗ם וַ⁠יְכַבּוּ֙ אֶת־הַ⁠נֵּר֔וֹת וּ⁠קְטֹ֖רֶת לֹ֣א הִקְטִ֑ירוּ וְ⁠עֹלָה֙ לֹא־הֶעֱל֣וּ בַ⁠קֹּ֔דֶשׁ לֵ⁠אלֹהֵ֖י יִשְׂרָאֵֽל׃","gȧ֣m sáֽgĕr֞ẇ dȧlĕţ֣wòţ há⁠ʼẇlá֗m wa⁠yĕkaḃẇ֙ ʼeţ-ha⁠né̇r֔wòţ ẇ⁠qĕtò֖reţ lò֣ʼ hiqĕti֑yrẇ wĕ⁠ʻòláh֙ lòʼ-heʻèl֣ẇ ba⁠qò̇֔deş̌ lé⁠ʼlòhé֖y yişĕ̂ráʼéֽl׃"],[29,8,"וַ⁠יְהִי֙ קֶ֣צֶף יְהוָ֔ה עַל־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָ֑ם וַ⁠יִּתְּנֵ֤⁠ם ל⁠זועה לְ⁠שַׁמָּ֣ה וְ⁠לִ⁠שְׁרֵקָ֔ה כַּ⁠אֲשֶׁ֛ר אַתֶּ֥ם רֹאִ֖ים בְּ⁠עֵינֵי⁠כֶֽם׃","wa⁠yĕhiy֙ qe֣ẕep yĕhwá֔h ʻal-yĕhẇdá֖h wi⁠yrẇşá̌liá֑m wa⁠yi̇ţĕ̇né֤⁠m l⁠zwʻh lĕ⁠şǎmá֣̇h wĕ⁠li⁠şĕ̌réqá֔h kȧ⁠ʼàşě֛r ʼaţė֥m ròʼi֖ym bĕ̇⁠ʻéynéy⁠keֽm׃"],[29,9,"וְ⁠הִנֵּ֛ה נָפְל֥וּ אֲבוֹתֵ֖י⁠נוּ בֶּ⁠חָ֑רֶב וּ⁠בָנֵ֨י⁠נוּ וּ⁠בְנוֹתֵ֧י⁠נוּ וְ⁠נָשֵׁ֛י⁠נוּ בַּ⁠שְּׁבִ֖י עַל־זֹֽאת׃","wĕ⁠hiné֛̇h nápĕl֥ẇ ʼàbwòţé֖y⁠nẇ bė⁠ẖá֑reb ẇ⁠báné֨y⁠nẇ ẇ⁠bĕnwòţé֧y⁠nẇ wĕ⁠náşé֛̌y⁠nẇ bȧ⁠şĕ̇̌bi֖y ʻal-zòֽʼţ׃"],[29,10,"עַתָּה֙ עִם־לְבָבִ֔⁠י לִ⁠כְר֣וֹת בְּרִ֔ית לַ⁠יהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְ⁠יָשֹׁ֥ב מִמֶּ֖⁠נּוּ חֲר֥וֹן אַפּֽ⁠וֹ׃","ʻaţá̇h֙ ʻim-lĕbábi֔⁠y li⁠kĕr֣wòţ bĕ̇ri֔yţ la⁠yhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wĕ⁠yáşò֥̌b mimė֖⁠ṅẇ ẖàr֥wòn ʼaṗֽ⁠wò׃"],[29,11,"בָּנַ֕⁠י עַתָּ֖ה אַל־תִּשָּׁל֑וּ כִּֽי־בָ⁠כֶ֞ם בָּחַ֣ר יְהוָ֗ה לַ⁠עֲמֹ֤ד לְ⁠פָנָי⁠ו֙ לְ⁠שָׁ֣רְת֔⁠וֹ וְ⁠לִ⁠הְי֥וֹת ל֖⁠וֹ מְשָׁרְתִ֥ים וּ⁠מַקְטִרִֽים׃ס","bá̇na֕⁠y ʻaţá֖̇h ʼal-ţi̇şá̇̌l֑ẇ kiֽ̇y-bá⁠ke֞m bá̇ẖa֣r yĕhwá֗h la⁠ʻàmò֤d lĕ⁠pánáy⁠w֙ lĕ⁠şá֣̌rĕţ֔⁠wò wĕ⁠li⁠hĕy֥wòţ l֖⁠wò mĕşá̌rĕţi֥ym ẇ⁠maqĕtiriֽym׃s"],[29,12,"וַ⁠יָּקֻ֣מוּ הַ֠⁠לְוִיִּם מַ֣חַת בֶּן־עֲמָשַׂ֞י וְ⁠יוֹאֵ֣ל בֶּן־עֲזַרְיָהוּ֮ מִן־בְּנֵ֣י הַ⁠קְּהָתִי֒ וּ⁠מִן־בְּנֵ֣י מְרָרִ֔י קִ֚ישׁ בֶּן־עַבְדִּ֔י וַ⁠עֲזַרְיָ֖הוּ בֶּן־יְהַלֶּלְאֵ֑ל וּ⁠מִן־הַ⁠גֵּ֣רְשֻׁנִּ֔י יוֹאָח֙ בֶּן־זִמָּ֔ה וְ⁠עֵ֖דֶן בֶּן־יוֹאָֽח׃","wa⁠yá̇qu֣mẇ ha֠⁠lĕwiyi̇m ma֣ẖaţ bėn-ʻàmáşâ֞y wĕ⁠ywòʼé֣l bėn-ʻàzarĕyáhẇ֮ min-bĕ̇né֣y ha⁠qĕ̇háţiy֒ ẇ⁠min-bĕ̇né֣y mĕrári֔y qi֚yş̌ bėn-ʻabĕdi̇֔y wa⁠ʻàzarĕyá֖hẇ bėn-yĕhalėlĕʼé֑l ẇ⁠min-ha⁠gé֣̇rĕşǔni̇֔y ywòʼáẖ֙ bėn-zimá̇֔h wĕ⁠ʻé֖den bėn-ywòʼáֽẖ׃"],[29,13,"וּ⁠מִן־בְּנֵי֙ אֱלִ֣יצָפָ֔ן שִׁמְרִ֖י ו⁠יעואל וּ⁠מִן־בְּנֵ֣י אָסָ֔ף זְכַרְיָ֖הוּ וּ⁠מַתַּנְיָֽהוּ׃ס","ẇ⁠min-bĕ̇néy֙ ʼèli֣yẕápá֔n şǐmĕri֖y w⁠yʻwʼl ẇ⁠min-bĕ̇né֣y ʼásá֔p zĕkarĕyá֖hẇ ẇ⁠maţȧnĕyáֽhẇ׃s"],[29,14,"וּ⁠מִן־בְּנֵ֥י הֵימָ֖ן יחואל וְ⁠שִׁמְעִ֑י ס וּ⁠מִן־בְּנֵ֣י יְדוּת֔וּן שְׁמַֽעְיָ֖ה וְ⁠עֻזִּיאֵֽל׃","ẇ⁠min-bĕ̇né֥y héymá֖n yẖwʼl wĕ⁠şǐmĕʻi֑y s ẇ⁠min-bĕ̇né֣y yĕdẇţ֔ẇn şĕ̌maֽʻĕyá֖h wĕ⁠ʻuzi̇yʼéֽl׃"],[29,15,"וַ⁠יַּֽאַסְפ֤וּ אֶת־אֲחֵי⁠הֶם֙ וַ⁠יִּֽתְקַדְּשׁ֔וּ וַ⁠יָּבֹ֥אוּ כְ⁠מִצְוַת־הַ⁠מֶּ֖לֶךְ בְּ⁠דִבְרֵ֣י יְהוָ֑ה לְ⁠טַהֵ֖ר בֵּ֥ית יְהוָֽה׃","wa⁠yȧֽʼasĕp֤ẇ ʼeţ-ʼàẖéy⁠hem֙ wa⁠yiֽ̇ţĕqadĕ̇ş̌֔ẇ wa⁠yá̇bò֥ʼẇ kĕ⁠miẕĕwaţ-ha⁠mė֖lekĕ bĕ̇⁠dibĕré֣y yĕhwá֑h lĕ⁠tahé֖r bé֥̇yţ yĕhwáֽh׃"],[29,16,"וַ⁠יָּבֹ֣אוּ הַ֠⁠כֹּהֲנִים לִ⁠פְנִ֣ימָה בֵית־יְהוָה֮ לְ⁠טַהֵר֒ וַ⁠יּוֹצִ֗יאוּ אֵ֤ת כָּל־הַ⁠טֻּמְאָה֙ אֲשֶׁ֤ר מָֽצְאוּ֙ בְּ⁠הֵיכַ֣ל יְהוָ֔ה לַ⁠חֲצַ֖ר בֵּ֣ית יְהוָ֑ה וַֽ⁠יְקַבְּלוּ֙ הַ⁠לְוִיִּ֔ם לְ⁠הוֹצִ֥יא לְ⁠נַֽחַל־קִדְר֖וֹן חֽוּצָ⁠ה׃","wa⁠yá̇bò֣ʼẇ ha֠⁠kò̇hàniym li⁠pĕni֣ymáh béyţ-yĕhwáh֮ lĕ⁠tahér֒ wa⁠ẏwòẕi֗yʼẇ ʼé֤ţ ká̇l-ha⁠tu̇mĕʼáh֙ ʼàşě֤r máֽẕĕʼẇ֙ bĕ̇⁠héyka֣l yĕhwá֔h la⁠ẖàẕa֖r bé֣̇yţ yĕhwá֑h waֽ⁠yĕqabĕ̇lẇ֙ ha⁠lĕwiyi̇֔m lĕ⁠hwòẕi֥yʼ lĕ⁠naֽẖal-qidĕr֖wòn ẖֽẇẕá⁠h׃"],[29,17,"וַ֠⁠יָּחֵלּוּ בְּ⁠אֶחָ֞ד לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁוֹן֮ לְ⁠קַדֵּשׁ֒ וּ⁠בְ⁠י֧וֹם שְׁמוֹנָ֣ה לַ⁠חֹ֗דֶשׁ בָּ֚אוּ לְ⁠אוּלָ֣ם יְהוָ֔ה וַ⁠יְקַדְּשׁ֥וּ אֶת־בֵּית־יְהוָ֖ה לְ⁠יָמִ֣ים שְׁמוֹנָ֑ה וּ⁠בְ⁠י֨וֹם שִׁשָּׁ֥ה עָשָׂ֛ר לַ⁠חֹ֥דֶשׁ הָ⁠רִאשׁ֖וֹן כִּלּֽוּ׃ס","wa֠⁠yá̇ẖél̇ẇ bĕ̇⁠ʼeẖá֞d la⁠ẖò֣deş̌ há⁠riʼş̌wòn֮ lĕ⁠qadé̇ş̌֒ ẇ⁠bĕ⁠y֧wòm şĕ̌mwòná֣h la⁠ẖò֗deş̌ bá֚̇ʼẇ lĕ⁠ʼẇlá֣m yĕhwá֔h wa⁠yĕqadĕ̇ş֥̌ẇ ʼeţ-bé̇yţ-yĕhwá֖h lĕ⁠yámi֣ym şĕ̌mwòná֑h ẇ⁠bĕ⁠y֨wòm şǐşá֥̇̌h ʻáşá֛̂r la⁠ẖò֥deş̌ há⁠riʼş֖̌wòn ki̇lֽ̇ẇ׃s"],[29,18,"וַ⁠יָּב֤וֹאוּ פְנִ֨ימָה֙ אֶל־חִזְקִיָּ֣הוּ הַ⁠מֶּ֔לֶךְ וַ⁠יֹּ֣אמְר֔וּ טִהַ֖רְנוּ אֶת־כָּל־בֵּ֣ית יְהוָ֑ה אֶת־מִזְבַּ֤ח הָ⁠עוֹלָה֙ וְ⁠אֶת־כָּל־כֵּלָ֔י⁠ו וְ⁠אֶת־שֻׁלְחַ֥ן הַֽ⁠מַּעֲרֶ֖כֶת וְ⁠אֶת־כָּל־כֵּלָֽי⁠ו׃","wa⁠yá̇b֤wòʼẇ pĕni֨ymáh֙ ʼel-ẖizĕqiyá֣̇hẇ ha⁠mė֔lekĕ wa⁠yò֣̇ʼmĕr֔ẇ tiha֖rĕnẇ ʼeţ-ká̇l-bé֣̇yţ yĕhwá֑h ʼeţ-mizĕbȧ֤ẖ há⁠ʻwòláh֙ wĕ⁠ʼeţ-ká̇l-ké̇lá֔y⁠w wĕ⁠ʼeţ-şǔlĕẖa֥n haֽ⁠mȧʻàre֖keţ wĕ⁠ʼeţ-ká̇l-ké̇láֽy⁠w׃"],[29,19,"וְ⁠אֵ֣ת כָּל־הַ⁠כֵּלִ֗ים אֲשֶׁ֣ר הִזְנִיחַ֩ הַ⁠מֶּ֨לֶךְ אָחָ֧ז בְּ⁠מַלְכוּת֛⁠וֹ בְּ⁠מַעֲל֖⁠וֹ הֵכַ֣נּוּ וְ⁠הִקְדָּ֑שְׁנוּ וְ⁠הִנָּ֕⁠ם לִ⁠פְנֵ֖י מִזְבַּ֥ח יְהוָֽה׃ס","wĕ⁠ʼé֣ţ ká̇l-ha⁠ké̇li֗ym ʼàşě֣r hizĕniyẖa֩ ha⁠mė֨lekĕ ʼáẖá֧z bĕ̇⁠malĕkẇţ֛⁠wò bĕ̇⁠maʻàl֖⁠wò héka֣ṅẇ wĕ⁠hiqĕdá֑̇şĕ̌nẇ wĕ⁠hiná̇֕⁠m li⁠pĕné֖y mizĕbȧ֥ẖ yĕhwáֽh׃s"],[29,20,"וַ⁠יַּשְׁכֵּם֙ יְחִזְקִיָּ֣הוּ הַ⁠מֶּ֔לֶךְ וַ⁠יֶּאֱסֹ֕ף אֵ֖ת שָׂרֵ֣י הָ⁠עִ֑יר וַ⁠יַּ֖עַל בֵּ֥ית יְהוָֽה׃","wa⁠yȧşĕ̌ké̇m֙ yĕẖizĕqiyá֣̇hẇ ha⁠mė֔lekĕ wa⁠yėʼèsò֕p ʼé֖ţ şá̂ré֣y há⁠ʻi֑yr wa⁠yȧ֖ʻal bé֥̇yţ yĕhwáֽh׃"],[29,21,"וַ⁠יָּבִ֣יאוּ פָרִים־שִׁבְעָה֩ וְ⁠אֵילִ֨ים שִׁבְעָ֜ה וּ⁠כְבָשִׂ֣ים שִׁבְעָ֗ה וּ⁠צְפִירֵ֨י עִזִּ֤ים שִׁבְעָה֙ לְ⁠חַטָּ֔את עַל־הַ⁠מַּמְלָכָ֥ה וְ⁠עַל־הַ⁠מִּקְדָּ֖שׁ וְ⁠עַל־יְהוּדָ֑ה וַ⁠יֹּ֗אמֶר לִ⁠בְנֵ֤י אַהֲרֹן֙ הַ⁠כֹּ֣הֲנִ֔ים לְ⁠הַעֲל֖וֹת עַל־מִזְבַּ֥ח יְהוָֽה׃","wa⁠yá̇bi֣yʼẇ páriym-şǐbĕʻáh֩ wĕ⁠ʼéyli֨ym şǐbĕʻá֜h ẇ⁠kĕbáşî֣ym şǐbĕʻá֗h ẇ⁠ẕĕpiyré֨y ʻizi֤̇ym şǐbĕʻáh֙ lĕ⁠ẖatá̇֔ʼţ ʻal-ha⁠mȧmĕláká֥h wĕ⁠ʻal-ha⁠mi̇qĕdá֖̇ş̌ wĕ⁠ʻal-yĕhẇdá֑h wa⁠yò̇֗ʼmer li⁠bĕné֤y ʼahàròn֙ ha⁠kò֣̇hàni֔ym lĕ⁠haʻàl֖wòţ ʻal-mizĕbȧ֥ẖ yĕhwáֽh׃"],[29,22,"וַֽ⁠יִּשְׁחֲטוּ֙ הַ⁠בָּקָ֔ר וַ⁠יְקַבְּל֤וּ הַ⁠כֹּֽהֲנִים֙ אֶת־הַ⁠דָּ֔ם וַֽ⁠יִּזְרְק֖וּ הַ⁠מִּזְבֵּ֑חָ⁠ה וַ⁠יִּשְׁחֲט֣וּ הָ⁠אֵלִ֗ים וַ⁠יִּזְרְק֤וּ הַ⁠דָּם֙ הַ⁠מִּזְבֵּ֔חָ⁠ה וַֽ⁠יִּשְׁחֲטוּ֙ הַ⁠כְּבָשִׂ֔ים וַ⁠יִּזְרְק֥וּ הַ⁠דָּ֖ם הַ⁠מִּזְבֵּֽחָ⁠ה׃","waֽ⁠yi̇şĕ̌ẖàtẇ֙ ha⁠bá̇qá֔r wa⁠yĕqabĕ̇l֤ẇ ha⁠kòֽ̇hàniym֙ ʼeţ-ha⁠dá̇֔m waֽ⁠yi̇zĕrĕq֖ẇ ha⁠mi̇zĕbé֑̇ẖá⁠h wa⁠yi̇şĕ̌ẖàt֣ẇ há⁠ʼéli֗ym wa⁠yi̇zĕrĕq֤ẇ ha⁠dá̇m֙ ha⁠mi̇zĕbé̇֔ẖá⁠h waֽ⁠yi̇şĕ̌ẖàtẇ֙ ha⁠kĕ̇báşî֔ym wa⁠yi̇zĕrĕq֥ẇ ha⁠dá֖̇m ha⁠mi̇zĕbéֽ̇ẖá⁠h׃"],[29,23,"וַ⁠יַּגִּ֨ישׁוּ֙ אֶת־שְׂעִירֵ֣י הַֽ⁠חַטָּ֔את לִ⁠פְנֵ֥י הַ⁠מֶּ֖לֶךְ וְ⁠הַ⁠קָּהָ֑ל וַ⁠יִּסְמְכ֥וּ יְדֵי⁠הֶ֖ם עֲלֵי⁠הֶֽם׃","wa⁠yȧgi̇֨yş̌ẇ֙ ʼeţ-şĕ̂ʻiyré֣y haֽ⁠ẖatá̇֔ʼţ li⁠pĕné֥y ha⁠mė֖lekĕ wĕ⁠ha⁠qá̇há֑l wa⁠yi̇sĕmĕk֥ẇ yĕdéy⁠he֖m ʻàléy⁠heֽm׃"],[29,24,"וַ⁠יִּשְׁחָטוּ⁠ם֙ הַ⁠כֹּ֣הֲנִ֔ים וַֽ⁠יְחַטְּא֤וּ אֶת־דָּמָ⁠ם֙ הַ⁠מִּזְבֵּ֔חָ⁠ה לְ⁠כַפֵּ֖ר עַל־כָּל־יִשְׂרָאֵ֑ל כִּ֤י לְ⁠כָל־יִשְׂרָאֵל֙ אָמַ֣ר הַ⁠מֶּ֔לֶךְ הָ⁠עוֹלָ֖ה וְ⁠הַ⁠חַטָּֽאת׃","wa⁠yi̇şĕ̌ẖátẇ⁠m֙ ha⁠kò֣̇hàni֔ym waֽ⁠yĕẖatĕ̇ʼ֤ẇ ʼeţ-dá̇má⁠m֙ ha⁠mi̇zĕbé̇֔ẖá⁠h lĕ⁠kapé֖̇r ʻal-ká̇l-yişĕ̂ráʼé֑l ki֤̇y lĕ⁠kál-yişĕ̂ráʼél֙ ʼáma֣r ha⁠mė֔lekĕ há⁠ʻwòlá֖h wĕ⁠ha⁠ẖatáֽ̇ʼţ׃"],[29,25,"וַ⁠יַּֽעֲמֵ֨ד אֶת־הַ⁠לְוִיִּ֜ם בֵּ֣ית יְהוָ֗ה בִּ⁠מְצִלְתַּ֨יִם֙ בִּ⁠נְבָלִ֣ים וּ⁠בְ⁠כִנֹּר֔וֹת בְּ⁠מִצְוַ֥ת דָּוִ֛יד וְ⁠גָ֥ד חֹזֵֽה־הַ⁠מֶּ֖לֶךְ וְ⁠נָתָ֣ן הַ⁠נָּבִ֑יא כִּ֧י בְ⁠יַד־יְהוָ֛ה הַ⁠מִּצְוָ֖ה בְּ⁠יַד־נְבִיאָֽי⁠ו׃ס","wa⁠yȧֽʻàmé֨d ʼeţ-ha⁠lĕwiyi̇֜m bé֣̇yţ yĕhwá֗h bi̇⁠mĕẕilĕţȧ֨yim֙ bi̇⁠nĕbáli֣ym ẇ⁠bĕ⁠kinò̇r֔wòţ bĕ̇⁠miẕĕwa֥ţ dá̇wi֛yd wĕ⁠gá֥d ẖòzéֽh-ha⁠mė֖lekĕ wĕ⁠náţá֣n ha⁠ná̇bi֑yʼ ki֧̇y bĕ⁠yad-yĕhwá֛h ha⁠mi̇ẕĕwá֖h bĕ̇⁠yad-nĕbiyʼáֽy⁠w׃s"],[29,26,"וַ⁠יַּֽעַמְד֤וּ הַ⁠לְוִיִּם֙ בִּ⁠כְלֵ֣י דָוִ֔יד וְ⁠הַ⁠כֹּהֲנִ֖ים בַּ⁠חֲצֹצְרֽוֹת׃ס","wa⁠yȧֽʻamĕd֤ẇ ha⁠lĕwiyi̇m֙ bi̇⁠kĕlé֣y dáwi֔yd wĕ⁠ha⁠kò̇hàni֖ym bȧ⁠ẖàẕòẕĕrֽwòţ׃s"],[29,27,"וַ⁠יֹּ֨אמֶר֙ חִזְקִיָּ֔הוּ לְ⁠הַעֲל֥וֹת הָ⁠עֹלָ֖ה לְ⁠הַ⁠מִּזְבֵּ֑חַ וּ⁠בְ⁠עֵ֞ת הֵחֵ֣ל הָֽ⁠עוֹלָ֗ה הֵחֵ֤ל שִׁיר־יְהוָה֙ וְ⁠הַ⁠חֲצֹ֣צְר֔וֹת וְ⁠עַ֨ל־יְדֵ֔י כְּלֵ֖י דָּוִ֥יד מֶֽלֶךְ־יִשְׂרָאֵֽל׃","wa⁠yò̇֨ʼmer֙ ẖizĕqiyá̇֔hẇ lĕ⁠haʻàl֥wòţ há⁠ʻòlá֖h lĕ⁠ha⁠mi̇zĕbé֑̇ẖa ẇ⁠bĕ⁠ʻé֞ţ héẖé֣l háֽ⁠ʻwòlá֗h héẖé֤l şǐyr-yĕhwáh֙ wĕ⁠ha⁠ẖàẕò֣ẕĕr֔wòţ wĕ⁠ʻa֨l-yĕdé֔y kĕ̇lé֖y dá̇wi֥yd meֽlekĕ-yişĕ̂ráʼéֽl׃"],[29,28,"וְ⁠כָל־הַ⁠קָּהָל֙ מִֽשְׁתַּחֲוִ֔ים וְ⁠הַ⁠שִּׁ֣יר מְשׁוֹרֵ֔ר וְ⁠הַ⁠חֲצֹצְר֖וֹת מחצצרים הַ⁠כֹּ֕ל עַ֖ד לִ⁠כְל֥וֹת הָ⁠עֹלָֽה׃","wĕ⁠kál-ha⁠qá̇hál֙ miֽşĕ̌ţȧẖàwi֔ym wĕ⁠ha⁠şi֣̇̌yr mĕş̌wòré֔r wĕ⁠ha⁠ẖàẕòẕĕr֖wòţ mẖẕẕrym ha⁠kò̇֕l ʻa֖d li⁠kĕl֥wòţ há⁠ʻòláֽh׃"],[29,29,"וּ⁠כְ⁠כַלּ֖וֹת לְ⁠הַעֲל֑וֹת כָּרְע֗וּ הַ⁠מֶּ֛לֶךְ וְ⁠כָֽל־הַ⁠נִּמְצְאִ֥ים אִתּ֖⁠וֹ וַ⁠יִּֽשְׁתַּחֲוֽוּ׃","ẇ⁠kĕ⁠kal֖̇wòţ lĕ⁠haʻàl֑wòţ ká̇rĕʻ֗ẇ ha⁠mė֛lekĕ wĕ⁠káֽl-ha⁠ni̇mĕẕĕʼi֥ym ʼiţ֖̇⁠wò wa⁠yiֽ̇şĕ̌ţȧẖàwֽẇ׃"],[29,30,"וַ֠⁠יֹּאמֶר יְחִזְקִיָּ֨הוּ הַ⁠מֶּ֤לֶךְ וְ⁠הַ⁠שָּׂרִים֙ לַ⁠לְוִיִּ֔ם לְ⁠הַלֵּל֙ לַֽ⁠יהוָ֔ה בְּ⁠דִבְרֵ֥י דָוִ֖יד וְ⁠אָסָ֣ף הַ⁠חֹזֶ֑ה וַֽ⁠יְהַלְלוּ֙ עַד־לְ⁠שִׂמְחָ֔ה וַֽ⁠יִּקְּד֖וּ וַ⁠יִּֽשְׁתַּחֲוֽוּ׃פ","wa֠⁠yò̇ʼmer yĕẖizĕqiyá̇֨hẇ ha⁠mė֤lekĕ wĕ⁠ha⁠şá̇̂riym֙ la⁠lĕwiyi̇֔m lĕ⁠halé̇l֙ laֽ⁠yhwá֔h bĕ̇⁠dibĕré֥y dáwi֖yd wĕ⁠ʼásá֣p ha⁠ẖòze֑h waֽ⁠yĕhalĕlẇ֙ ʻad-lĕ⁠şîmĕẖá֔h waֽ⁠yi̇qĕ̇d֖ẇ wa⁠yiֽ̇şĕ̌ţȧẖàwֽẇ׃p"],[29,31,"וַ⁠יַּ֨עַן יְחִזְקִיָּ֜הוּ וַ⁠יֹּ֗אמֶר עַתָּ֨ה מִלֵּאתֶ֤ם יֶדְ⁠כֶם֙ לַ⁠יהוָ֔ה גֹּ֧שׁוּ וְ⁠הָבִ֛יאוּ זְבָחִ֥ים וְ⁠תוֹד֖וֹת לְ⁠בֵ֣ית יְהוָ֑ה וַ⁠יָּבִ֤יאוּ הַ⁠קָּהָל֙ זְבָחִ֣ים וְ⁠תוֹד֔וֹת וְ⁠כָל־נְדִ֥יב לֵ֖ב עֹלֽוֹת׃","wa⁠yȧ֨ʻan yĕẖizĕqiyá̇֜hẇ wa⁠yò̇֗ʼmer ʻaţá̇֨h milé̇ʼţe֤m yedĕ⁠kem֙ la⁠yhwá֔h gò֧̇ş̌ẇ wĕ⁠hábi֛yʼẇ zĕbáẖi֥ym wĕ⁠ţwòd֖wòţ lĕ⁠bé֣yţ yĕhwá֑h wa⁠yá̇bi֤yʼẇ ha⁠qá̇hál֙ zĕbáẖi֣ym wĕ⁠ţwòd֔wòţ wĕ⁠kál-nĕdi֥yb lé֖b ʻòlֽwòţ׃"],[29,32,"וַ⁠יְהִ֞י מִסְפַּ֣ר הָ⁠עֹלָה֮ אֲשֶׁ֣ר הֵבִ֣יאוּ הַ⁠קָּהָל֒ בָּקָ֣ר שִׁבְעִ֔ים אֵילִ֥ים מֵאָ֖ה כְּבָשִׂ֣ים מָאתָ֑יִם לְ⁠עֹלָ֥ה לַ⁠יהוָ֖ה כָּל־אֵֽלֶּה׃","wa⁠yĕhi֞y misĕpȧ֣r há⁠ʻòláh֮ ʼàşě֣r hébi֣yʼẇ ha⁠qá̇hál֒ bá̇qá֣r şǐbĕʻi֔ym ʼéyli֥ym méʼá֖h kĕ̇báşî֣ym máʼţá֑yim lĕ⁠ʻòlá֥h la⁠yhwá֖h ká̇l-ʼéֽlėh׃"],[29,33,"וְֽ⁠הַ⁠קֳּדָשִׁ֑ים בָּקָר֙ שֵׁ֣שׁ מֵא֔וֹת וְ⁠צֹ֖אן שְׁלֹ֥שֶׁת אֲלָפִֽים׃","wĕֽ⁠ha⁠qȯdáşǐ֑ym bá̇qár֙ şé֣̌ş̌ méʼ֔wòţ wĕ⁠ẕò֖ʼn şĕ̌lò֥şěţ ʼàlápiֽym׃"],[29,34,"רַ֤ק הַ⁠כֹּֽהֲנִים֙ הָי֣וּ לִ⁠מְעָ֔ט וְ⁠לֹ֣א יָֽכְל֔וּ לְ⁠הַפְשִׁ֖יט אֶת־כָּל־הָ⁠עֹל֑וֹת וַֽ⁠יְּחַזְּק֞וּ⁠ם אֲחֵי⁠הֶ֣ם הַ⁠לְוִיִּ֗ם עַד־כְּל֤וֹת הַ⁠מְּלָאכָה֙ וְ⁠עַ֣ד יִתְקַדְּשׁ֣וּ הַ⁠כֹּֽהֲנִ֔ים כִּ֤י הַ⁠לְוִיִּם֙ יִשְׁרֵ֣י לֵבָ֔ב לְ⁠הִתְקַדֵּ֖שׁ מֵֽ⁠הַ⁠כֹּהֲנִֽים׃","ra֤q ha⁠kòֽ̇hàniym֙ háy֣ẇ li⁠mĕʻá֔t wĕ⁠lò֣ʼ yáֽkĕl֔ẇ lĕ⁠hapĕşǐ֖yt ʼeţ-ká̇l-há⁠ʻòl֑wòţ waֽ⁠yĕ̇ẖazĕ̇q֞ẇ⁠m ʼàẖéy⁠he֣m ha⁠lĕwiyi̇֗m ʻad-kĕ̇l֤wòţ ha⁠mĕ̇láʼkáh֙ wĕ⁠ʻa֣d yiţĕqadĕ̇ş֣̌ẇ ha⁠kòֽ̇hàni֔ym ki֤̇y ha⁠lĕwiyi̇m֙ yişĕ̌ré֣y lébá֔b lĕ⁠hiţĕqadé֖̇ş̌ méֽ⁠ha⁠kò̇hàniֽym׃"],[29,35,"וְ⁠גַם־עֹלָ֨ה לָ⁠רֹ֜ב בְּ⁠חֶלְבֵ֧י הַ⁠שְּׁלָמִ֛ים וּ⁠בַ⁠נְּסָכִ֖ים לָ⁠עֹלָ֑ה וַ⁠תִּכּ֖וֹן עֲבוֹדַ֥ת בֵּית־יְהוָֽה׃","wĕ⁠gam-ʻòlá֨h lá⁠rò֜b bĕ̇⁠ẖelĕbé֧y ha⁠şĕ̇̌lámi֛ym ẇ⁠ba⁠nĕ̇sáki֖ym lá⁠ʻòlá֑h wa⁠ţi̇k֖̇wòn ʻàbwòda֥ţ bé̇yţ-yĕhwáֽh׃"],[29,36,"וַ⁠יִּשְׂמַ֤ח יְחִזְקִיָּ֨הוּ֙ וְ⁠כָל־הָ⁠עָ֔ם עַ֛ל הַ⁠הֵכִ֥ין הָ⁠אֱלֹהִ֖ים לָ⁠עָ֑ם כִּ֥י בְּ⁠פִתְאֹ֖ם הָיָ֥ה הַ⁠דָּבָֽר׃פ","wa⁠yi̇şĕ̂ma֤ẖ yĕẖizĕqiyá̇֨hẇ֙ wĕ⁠kál-há⁠ʻá֔m ʻa֛l ha⁠héki֥yn há⁠ʼèlòhi֖ym lá⁠ʻá֑m ki֥̇y bĕ̇⁠piţĕʼò֖m háyá֥h ha⁠dá̇báֽr׃p"],[30,1,"וַ⁠יִּשְׁלַ֨ח יְחִזְקִיָּ֜הוּ עַל־כָּל־יִשְׂרָאֵ֣ל וִֽ⁠יהוּדָ֗ה וְ⁠גַֽם־אִגְּרוֹת֙ כָּתַב֙ עַל־אֶפְרַ֣יִם וּ⁠מְנַשֶּׁ֔ה לָ⁠ב֥וֹא לְ⁠בֵית־יְהוָ֖ה בִּֽ⁠ירוּשָׁלִָ֑ם לַ⁠עֲשׂ֣וֹת פֶּ֔סַח לַ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇şĕ̌la֨ẖ yĕẖizĕqiyá̇֜hẇ ʻal-ká̇l-yişĕ̂ráʼé֣l wiֽ⁠yhẇdá֗h wĕ⁠gaֽm-ʼigĕ̇rwòţ֙ ká̇ţab֙ ʻal-ʼepĕra֣yim ẇ⁠mĕnaşė̌֔h lá⁠b֥wòʼ lĕ⁠béyţ-yĕhwá֖h biֽ̇⁠yrẇşá̌liá֑m la⁠ʻàş֣̂wòţ pė֔saẖ la⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[30,2,"וַ⁠יִּוָּעַ֨ץ הַ⁠מֶּ֧לֶךְ וְ⁠שָׂרָ֛י⁠ו וְ⁠כָל־הַ⁠קָּהָ֖ל בִּ⁠ירוּשָׁלִָ֑ם לַ⁠עֲשׂ֥וֹת הַ⁠פֶּ֖סַח בַּ⁠חֹ֥דֶשׁ הַ⁠שֵּׁנִֽי׃","wa⁠yi̇wá̇ʻa֨ẕ ha⁠mė֧lekĕ wĕ⁠şá̂rá֛y⁠w wĕ⁠kál-ha⁠qá̇há֖l bi̇⁠yrẇşá̌liá֑m la⁠ʻàş֥̂wòţ ha⁠pė֖saẖ bȧ⁠ẖò֥deş̌ ha⁠şé̇̌niֽy׃"],[30,3,"כִּ֣י לֹ֧א יָכְל֛וּ לַ⁠עֲשֹׂת֖⁠וֹ בָּ⁠עֵ֣ת הַ⁠הִ֑יא כִּ֤י הַ⁠כֹּהֲנִים֙ לֹֽא־הִתְקַדְּשׁ֣וּ לְ⁠מַ דַּ֔י וְ⁠הָ⁠עָ֖ם לֹא־נֶאֶסְפ֥וּ לִֽ⁠ירוּשָׁלִָֽם׃","ki֣̇y lò֧ʼ yákĕl֛ẇ la⁠ʻàşò̂ţ֖⁠wò bá̇⁠ʻé֣ţ ha⁠hi֑yʼ ki֤̇y ha⁠kò̇hàniym֙ lòֽʼ-hiţĕqadĕ̇ş֣̌ẇ lĕ⁠ma dȧ֔y wĕ⁠há⁠ʻá֖m lòʼ-neʼesĕp֥ẇ liֽ⁠yrẇşá̌liáֽm׃"],[30,4,"וַ⁠יִּישַׁ֥ר הַ⁠דָּבָ֖ר בְּ⁠עֵינֵ֣י הַ⁠מֶּ֑לֶךְ וּ⁠בְ⁠עֵינֵ֖י כָּל־הַ⁠קָּהָֽל׃","wa⁠yi̇yşǎ֥r ha⁠dá̇bá֖r bĕ̇⁠ʻéyné֣y ha⁠mė֑lekĕ ẇ⁠bĕ⁠ʻéyné֖y ká̇l-ha⁠qá̇háֽl׃"],[30,5,"וַ⁠יַּֽעֲמִ֣ידוּ דָבָ֗ר לְ⁠הַעֲבִ֨יר ק֤וֹל בְּ⁠כָל־יִשְׂרָאֵל֙ מִ⁠בְּאֵֽר־שֶׁ֣בַע וְ⁠עַד־דָּ֔ן לָ⁠ב֞וֹא לַ⁠עֲשׂ֥וֹת פֶּ֛סַח לַ⁠יהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל בִּ⁠ירוּשָׁלִָ֑ם כִּ֣י לֹ֥א לָ⁠רֹ֛ב עָשׂ֖וּ כַּ⁠כָּתֽוּב׃","wa⁠yȧֽʻàmi֣ydẇ dábá֗r lĕ⁠haʻàbi֨yr q֤wòl bĕ̇⁠kál-yişĕ̂ráʼél֙ mi⁠bĕ̇ʼéֽr-şě֣baʻ wĕ⁠ʻad-dá̇֔n lá⁠b֞wòʼ la⁠ʻàş֥̂wòţ pė֛saẖ la⁠yhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l bi̇⁠yrẇşá̌liá֑m ki֣̇y lò֥ʼ lá⁠rò֛b ʻáş֖̂ẇ kȧ⁠ká̇ţֽẇb׃"],[30,6,"וַ⁠יֵּלְכוּ֩ הָ⁠רָצִ֨ים בָּֽ⁠אִגְּר֜וֹת מִ⁠יַּ֧ד הַ⁠מֶּ֣לֶךְ וְ⁠שָׂרָ֗י⁠ו בְּ⁠כָל־יִשְׂרָאֵל֙ וִֽ⁠יהוּדָ֔ה וּ⁠כְ⁠מִצְוַ֥ת הַ⁠מֶּ֖לֶךְ לֵ⁠אמֹ֑ר בְּנֵ֣י יִשְׂרָאֵ֗ל שׁ֚וּבוּ אֶל־יְהוָ֗ה אֱלֹהֵי֙ אַבְרָהָם֙ יִצְחָ֣ק וְ⁠יִשְׂרָאֵ֔ל וְ⁠יָשֹׁב֙ אֶל־הַ⁠פְּלֵיטָ֔ה הַ⁠נִּשְׁאֶ֣רֶת לָ⁠כֶ֔ם מִ⁠כַּ֖ף מַלְכֵ֥י אַשּֽׁוּר׃","wa⁠yé̇lĕkẇ֩ há⁠ráẕi֨ym báֽ̇⁠ʼigĕ̇r֜wòţ mi⁠yȧ֧d ha⁠mė֣lekĕ wĕ⁠şá̂rá֗y⁠w bĕ̇⁠kál-yişĕ̂ráʼél֙ wiֽ⁠yhẇdá֔h ẇ⁠kĕ⁠miẕĕwa֥ţ ha⁠mė֖lekĕ lé⁠ʼmò֑r bĕ̇né֣y yişĕ̂ráʼé֗l ş֚̌ẇbẇ ʼel-yĕhwá֗h ʼèlòhéy֙ ʼabĕráhám֙ yiẕĕẖá֣q wĕ⁠yişĕ̂ráʼé֔l wĕ⁠yáşò̌b֙ ʼel-ha⁠pĕ̇léytá֔h ha⁠ni̇şĕ̌ʼe֣reţ lá⁠ke֔m mi⁠kȧ֖p malĕké֥y ʼaşֽ̇̌ẇr׃"],[30,7,"וְ⁠אַל־תִּֽהְי֗וּ כַּ⁠אֲבֽוֹתֵי⁠כֶם֙ וְ⁠כַ֣⁠אֲחֵי⁠כֶ֔ם אֲשֶׁ֣ר מָעֲל֔וּ בַּ⁠יהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵי⁠הֶ֑ם וַ⁠יִּתְּנֵ֣⁠ם לְ⁠שַׁמָּ֔ה כַּ⁠אֲשֶׁ֖ר אַתֶּ֥ם רֹאִֽים׃","wĕ⁠ʼal-ţiֽ̇hĕy֗ẇ kȧ⁠ʼàbֽwòţéy⁠kem֙ wĕ⁠ka֣⁠ʼàẖéy⁠ke֔m ʼàşě֣r máʻàl֔ẇ bȧ⁠yhwá֖h ʼèlòhé֣y ʼàbwòţéy⁠he֑m wa⁠yi̇ţĕ̇né֣⁠m lĕ⁠şǎmá̇֔h kȧ⁠ʼàşě֖r ʼaţė֥m ròʼiֽym׃"],[30,8,"עַתָּ֕ה אַל־תַּקְשׁ֥וּ עָרְפְּ⁠כֶ֖ם כַּ⁠אֲבוֹתֵי⁠כֶ֑ם תְּנוּ־יָ֣ד לַ⁠יהוָ֗ה וּ⁠בֹ֤אוּ לְ⁠מִקְדָּשׁ⁠וֹ֙ אֲשֶׁ֣ר הִקְדִּ֣ישׁ לְ⁠עוֹלָ֔ם וְ⁠עִבְדוּ֙ אֶת־יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם וְ⁠יָשֹׁ֥ב מִ⁠כֶּ֖ם חֲר֥וֹן אַפּֽ⁠וֹ׃","ʻaţá̇֕h ʼal-ţȧqĕş֥̌ẇ ʻárĕpĕ̇⁠ke֖m kȧ⁠ʼàbwòţéy⁠ke֑m ţĕ̇nẇ-yá֣d la⁠yhwá֗h ẇ⁠bò֤ʼẇ lĕ⁠miqĕdá̇ş̌⁠wò֙ ʼàşě֣r hiqĕdi֣̇yş̌ lĕ⁠ʻwòlá֔m wĕ⁠ʻibĕdẇ֙ ʼeţ-yĕhwá֣h ʼèlòhéy⁠ke֔m wĕ⁠yáşò֥̌b mi⁠kė֖m ẖàr֥wòn ʼaṗֽ⁠wò׃"],[30,9,"כִּ֣י בְ⁠שׁוּבְ⁠כֶ֞ם עַל־יְהוָ֗ה אֲחֵי⁠כֶ֨ם וּ⁠בְנֵי⁠כֶ֤ם לְ⁠רַחֲמִים֙ לִ⁠פְנֵ֣י שֽׁוֹבֵי⁠הֶ֔ם וְ⁠לָ⁠שׁ֖וּב לָ⁠אָ֣רֶץ הַ⁠זֹּ֑את כִּֽי־חַנּ֤וּן וְ⁠רַחוּם֙ יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם וְ⁠לֹא־יָסִ֤יר פָּנִים֙ מִ⁠כֶּ֔ם אִם־תָּשׁ֖וּבוּ אֵלָֽי⁠ו׃פ","ki֣̇y bĕ⁠ş̌ẇbĕ⁠ke֞m ʻal-yĕhwá֗h ʼàẖéy⁠ke֨m ẇ⁠bĕnéy⁠ke֤m lĕ⁠raẖàmiym֙ li⁠pĕné֣y şֽ̌wòbéy⁠he֔m wĕ⁠lá⁠ş֖̌ẇb lá⁠ʼá֣reẕ ha⁠zò֑̇ʼţ kiֽ̇y-ẖaṅ֤ẇn wĕ⁠raẖẇm֙ yĕhwá֣h ʼèlòhéy⁠ke֔m wĕ⁠lòʼ-yási֤yr pá̇niym֙ mi⁠kė֔m ʼim-ţá̇ş֖̌ẇbẇ ʼéláֽy⁠w׃p"],[30,10,"וַ⁠יִּֽהְי֨וּ הָ⁠רָצִ֜ים עֹבְרִ֨ים מֵ⁠עִ֧יר ׀ לָ⁠עִ֛יר בְּ⁠אֶֽרֶץ־אֶפְרַ֥יִם וּ⁠מְנַשֶּׁ֖ה וְ⁠עַד־זְבֻל֑וּן וַ⁠יִּֽהְיוּ֙ מַשְׂחִיקִ֣ים עֲלֵי⁠הֶ֔ם וּ⁠מַלְעִגִ֖ים בָּֽ⁠ם׃","wa⁠yiֽ̇hĕy֨ẇ há⁠ráẕi֜ym ʻòbĕri֨ym mé⁠ʻi֧yr ׀ lá⁠ʻi֛yr bĕ̇⁠ʼeֽreẕ-ʼepĕra֥yim ẇ⁠mĕnaşė֖̌h wĕ⁠ʻad-zĕbul֑ẇn wa⁠yiֽ̇hĕyẇ֙ maşĕ̂ẖiyqi֣ym ʻàléy⁠he֔m ẇ⁠malĕʻigi֖ym báֽ̇⁠m׃"],[30,11,"אַךְ־אֲנָשִׁ֛ים מֵ⁠אָשֵׁ֥ר וּ⁠מְנַשֶּׁ֖ה וּ⁠מִ⁠זְּבֻל֑וּן נִֽכְנְע֔וּ וַ⁠יָּבֹ֖אוּ לִ⁠ירוּשָׁלִָֽם׃","ʼakĕ-ʼànáşǐ֛ym mé⁠ʼáşé֥̌r ẇ⁠mĕnaşė֖̌h ẇ⁠mi⁠zĕ̇bul֑ẇn niֽkĕnĕʻ֔ẇ wa⁠yá̇bò֖ʼẇ li⁠yrẇşá̌liáֽm׃"],[30,12,"גַּ֣ם בִּ⁠יהוּדָ֗ה הָֽיְתָה֙ יַ֣ד הָ⁠אֱלֹהִ֔ים לָ⁠תֵ֥ת לָ⁠הֶ֖ם לֵ֣ב אֶחָ֑ד לַ⁠עֲשׂ֞וֹת מִצְוַ֥ת הַ⁠מֶּ֛לֶךְ וְ⁠הַ⁠שָּׂרִ֖ים בִּ⁠דְבַ֥ר יְהוָֽה׃","gȧ֣m bi̇⁠yhẇdá֗h háֽyĕţáh֙ ya֣d há⁠ʼèlòhi֔ym lá⁠ţé֥ţ lá⁠he֖m lé֣b ʼeẖá֑d la⁠ʻàş̂֞wòţ miẕĕwa֥ţ ha⁠mė֛lekĕ wĕ⁠ha⁠şá̇̂ri֖ym bi̇⁠dĕba֥r yĕhwáֽh׃"],[30,13,"וַ⁠יֵּֽאָסְפ֤וּ יְרוּשָׁלִַ֨ם֙ עַם־רָ֔ב לַ⁠עֲשׂ֛וֹת אֶת־חַ֥ג הַ⁠מַּצּ֖וֹת בַּ⁠חֹ֣דֶשׁ הַ⁠שֵּׁנִ֑י קָהָ֖ל לָ⁠רֹ֥ב מְאֹֽד׃","wa⁠yéֽ̇ʼásĕp֤ẇ yĕrẇşá̌lia֨m֙ ʻam-rá֔b la⁠ʻàş֛̂wòţ ʼeţ-ẖa֥g ha⁠mȧẕ֖̇wòţ bȧ⁠ẖò֣deş̌ ha⁠şé̇̌ni֑y qáhá֖l lá⁠rò֥b mĕʼòֽd׃"],[30,14,"וַ⁠יָּקֻ֕מוּ וַ⁠יָּסִ֨ירוּ֙ אֶת־הַֽ⁠מִּזְבְּח֔וֹת אֲשֶׁ֖ר בִּ⁠ירוּשָׁלִָ֑ם וְ⁠אֵ֤ת כָּל־הַֽ⁠מְקַטְּרוֹת֙ הֵסִ֔ירוּ וַ⁠יַּשְׁלִ֖יכוּ לְ⁠נַ֥חַל קִדְרֽוֹן׃","wa⁠yá̇qu֕mẇ wa⁠yá̇si֨yrẇ֙ ʼeţ-haֽ⁠mi̇zĕbĕ̇ẖ֔wòţ ʼàşě֖r bi̇⁠yrẇşá̌liá֑m wĕ⁠ʼé֤ţ ká̇l-haֽ⁠mĕqatĕ̇rwòţ֙ hési֔yrẇ wa⁠yȧşĕ̌li֖ykẇ lĕ⁠na֥ẖal qidĕrֽwòn׃"],[30,15,"וַ⁠יִּשְׁחֲט֣וּ הַ⁠פֶּ֔סַח בְּ⁠אַרְבָּעָ֥ה עָשָׂ֖ר לַ⁠חֹ֣דֶשׁ הַ⁠שֵּׁנִ֑י וְ⁠הַ⁠כֹּהֲנִ֨ים וְ⁠הַ⁠לְוִיִּ֤ם נִכְלְמוּ֙ וַ⁠יִּֽתְקַדְּשׁ֔וּ וַ⁠יָּבִ֥יאוּ עֹל֖וֹת בֵּ֥ית יְהוָֽה׃","wa⁠yi̇şĕ̌ẖàt֣ẇ ha⁠pė֔saẖ bĕ̇⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r la⁠ẖò֣deş̌ ha⁠şé̇̌ni֑y wĕ⁠ha⁠kò̇hàni֨ym wĕ⁠ha⁠lĕwiyi֤̇m nikĕlĕmẇ֙ wa⁠yiֽ̇ţĕqadĕ̇ş̌֔ẇ wa⁠yá̇bi֥yʼẇ ʻòl֖wòţ bé֥̇yţ yĕhwáֽh׃"],[30,16,"וַ⁠יַּֽעַמְד֤וּ עַל־עָמְדָ⁠ם֙ כְּ⁠מִשְׁפָּטָ֔⁠ם כְּ⁠תוֹרַ֖ת מֹשֶׁ֣ה אִישׁ־הָ⁠אֱלֹהִ֑ים הַ⁠כֹּֽהֲנִים֙ זֹרְקִ֣ים אֶת־הַ⁠דָּ֔ם מִ⁠יַּ֖ד הַ⁠לְוִיִּֽם׃","wa⁠yȧֽʻamĕd֤ẇ ʻal-ʻámĕdá⁠m֙ kĕ̇⁠mişĕ̌pá̇tá֔⁠m kĕ̇⁠ţwòra֖ţ mòşě֣h ʼiyş̌-há⁠ʼèlòhi֑ym ha⁠kòֽ̇hàniym֙ zòrĕqi֣ym ʼeţ-ha⁠dá̇֔m mi⁠yȧ֖d ha⁠lĕwiyiֽ̇m׃"],[30,17,"כִּי־רַבַּ֥ת בַּ⁠קָּהָ֖ל אֲשֶׁ֣ר לֹא־הִתְקַדָּ֑שׁוּ וְ⁠הַ⁠לְוִיִּ֞ם עַל־שְׁחִיטַ֣ת הַ⁠פְּסָחִ֗ים לְ⁠כֹל֙ לֹ֣א טָה֔וֹר לְ⁠הַקְדִּ֖ישׁ לַ⁠יהוָֽה׃","ki̇y-rabȧ֥ţ bȧ⁠qá̇há֖l ʼàşě֣r lòʼ-hiţĕqadá֑̇ş̌ẇ wĕ⁠ha⁠lĕwiyi̇֞m ʻal-şĕ̌ẖiyta֣ţ ha⁠pĕ̇sáẖi֗ym lĕ⁠kòl֙ lò֣ʼ táh֔wòr lĕ⁠haqĕdi֖̇yş̌ la⁠yhwáֽh׃"],[30,18,"כִּ֣י מַרְבִּ֣ית הָ⁠עָ֡ם רַ֠בַּת מֵֽ⁠אֶפְרַ֨יִם וּ⁠מְנַשֶּׁ֜ה יִשָּׂשכָ֤ר וּ⁠זְבֻלוּן֙ לֹ֣א הִטֶּהָ֔רוּ כִּֽי־אָכְל֥וּ אֶת־הַ⁠פֶּ֖סַח בְּ⁠לֹ֣א כַ⁠כָּת֑וּב כִּי֩ הִתְפַּלֵּ֨ל יְחִזְקִיָּ֤הוּ עֲלֵי⁠הֶם֙ לֵ⁠אמֹ֔ר יְהוָ֥ה הַ⁠טּ֖וֹב יְכַפֵּ֥ר בְּעַֽד׃","ki֣̇y marĕbi֣̇yţ há⁠ʻá֡m ra֠bȧţ méֽ⁠ʼepĕra֨yim ẇ⁠mĕnaşė̌֜h yişá̇̂şká֤r ẇ⁠zĕbulẇn֙ lò֣ʼ hitėhá֔rẇ kiֽ̇y-ʼákĕl֥ẇ ʼeţ-ha⁠pė֖saẖ bĕ̇⁠lò֣ʼ ka⁠ká̇ţ֑ẇb ki̇y֩ hiţĕpȧlé̇֨l yĕẖizĕqiyá֤̇hẇ ʻàléy⁠hem֙ lé⁠ʼmò֔r yĕhwá֥h ha⁠ṫ֖wòb yĕkapé֥̇r bĕ̇ʻaֽd׃"],[30,19,"כָּל־לְבָב֣⁠וֹ הֵכִ֔ין לִ⁠דְר֛וֹשׁ הָ⁠אֱלֹהִ֥ים ׀ יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתָ֑י⁠ו וְ⁠לֹ֖א כְּ⁠טָהֳרַ֥ת הַ⁠קֹּֽדֶשׁ׃ס","ká̇l-lĕbáb֣⁠wò héki֔yn li⁠dĕr֛wòş̌ há⁠ʼèlòhi֥ym ׀ yĕhwá֖h ʼèlòhé֣y ʼàbwòţá֑y⁠w wĕ⁠lò֖ʼ kĕ̇⁠táhora֥ţ ha⁠qòֽ̇deş̌׃s"],[30,20,"וַ⁠יִּשְׁמַ֤ע יְהוָה֙ אֶל־יְחִזְקִיָּ֔הוּ וַ⁠יִּרְפָּ֖א אֶת־הָ⁠עָֽם׃ס","wa⁠yi̇şĕ̌ma֤ʻ yĕhwáh֙ ʼel-yĕẖizĕqiyá̇֔hẇ wa⁠yi̇rĕpá֖̇ʼ ʼeţ-há⁠ʻáֽm׃s"],[30,21,"וַ⁠יַּעֲשׂ֣וּ בְנֵֽי־יִ֠שְׂרָאֵל הַ⁠נִּמְצְאִ֨ים בִּ⁠ירוּשָׁלִַ֜ם אֶת־חַ֧ג הַ⁠מַּצּ֛וֹת שִׁבְעַ֥ת יָמִ֖ים בְּ⁠שִׂמְחָ֣ה גְדוֹלָ֑ה וּֽ⁠מְהַלְלִ֣ים לַ֠⁠יהוָה י֣וֹם ׀ בְּ⁠י֞וֹם הַ⁠לְוִיִּ֧ם וְ⁠הַ⁠כֹּהֲנִ֛ים בִּ⁠כְלֵי־עֹ֖ז לַ⁠יהוָֽה׃ס","wa⁠yȧʻàş֣̂ẇ bĕnéֽy-yi֠şĕ̂ráʼél ha⁠ni̇mĕẕĕʼi֨ym bi̇⁠yrẇşá̌lia֜m ʼeţ-ẖa֧g ha⁠mȧẕ֛̇wòţ şǐbĕʻa֥ţ yámi֖ym bĕ̇⁠şîmĕẖá֣h gĕdwòlá֑h ẇֽ⁠mĕhalĕli֣ym la֠⁠yhwáh y֣wòm ׀ bĕ̇⁠y֞wòm ha⁠lĕwiyi֧̇m wĕ⁠ha⁠kò̇hàni֛ym bi̇⁠kĕléy-ʻò֖z la⁠yhwáֽh׃s"],[30,22,"וַ⁠יְדַבֵּ֣ר יְחִזְקִיָּ֗הוּ עַל־לֵב֙ כָּל־הַ⁠לְוִיִּ֔ם הַ⁠מַּשְׂכִּילִ֥ים שֵֽׂכֶל־ט֖וֹב לַ⁠יהוָ֑ה וַ⁠יֹּאכְל֤וּ אֶת־הַ⁠מּוֹעֵד֙ שִׁבְעַ֣ת הַ⁠יָּמִ֔ים מְזַבְּחִים֙ זִבְחֵ֣י שְׁלָמִ֔ים וּ⁠מִ֨תְוַדִּ֔ים לַ⁠יהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃ס","wa⁠yĕdabé֣̇r yĕẖizĕqiyá̇֗hẇ ʻal-léb֙ ká̇l-ha⁠lĕwiyi̇֔m ha⁠mȧşĕ̂ki̇yli֥ym şéֽ̂kel-t֖wòb la⁠yhwá֑h wa⁠yò̇ʼkĕl֤ẇ ʼeţ-ha⁠ṁwòʻéd֙ şǐbĕʻa֣ţ ha⁠yá̇mi֔ym mĕzabĕ̇ẖiym֙ zibĕẖé֣y şĕ̌lámi֔ym ẇ⁠mi֨ţĕwadi̇֔ym la⁠yhwá֖h ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃s"],[30,23,"וַ⁠יִּוָּֽעֲצוּ֙ כָּל־הַ⁠קָּהָ֔ל לַ⁠עֲשׂ֕וֹת שִׁבְעַ֥ת יָמִ֖ים אֲחֵרִ֑ים וַ⁠יַּֽעֲשׂ֥וּ שִׁבְעַת־יָמִ֖ים שִׂמְחָֽה׃","wa⁠yi̇wáֽ̇ʻàẕẇ֙ ká̇l-ha⁠qá̇há֔l la⁠ʻàş̂֕wòţ şǐbĕʻa֥ţ yámi֖ym ʼàẖéri֑ym wa⁠yȧֽʻàş֥̂ẇ şǐbĕʻaţ-yámi֖ym şîmĕẖáֽh׃"],[30,24,"כִּ֣י חִזְקִיָּ֣הוּ מֶֽלֶךְ־יְ֠הוּדָה הֵרִ֨ים לַ⁠קָּהָ֜ל אֶ֣לֶף פָּרִים֮ וְ⁠שִׁבְעַ֣ת אֲלָפִ֣ים צֹאן֒ ס וְ⁠הַ⁠שָּׂרִ֞ים הֵרִ֤ימוּ לַ⁠קָּהָל֙ פָּרִ֣ים אֶ֔לֶף וְ⁠צֹ֖אן עֲשֶׂ֣רֶת אֲלָפִ֑ים וַ⁠יִּֽתְקַדְּשׁ֥וּ כֹהֲנִ֖ים לָ⁠רֹֽב׃","ki֣̇y ẖizĕqiyá֣̇hẇ meֽlekĕ-yĕ֠hẇdáh héri֨ym la⁠qá̇há֜l ʼe֣lep pá̇riym֮ wĕ⁠şǐbĕʻa֣ţ ʼàlápi֣ym ẕòʼn֒ s wĕ⁠ha⁠şá̇̂ri֞ym héri֤ymẇ la⁠qá̇hál֙ pá̇ri֣ym ʼe֔lep wĕ⁠ẕò֖ʼn ʻàşê֣reţ ʼàlápi֑ym wa⁠yiֽ̇ţĕqadĕ̇ş֥̌ẇ kòhàni֖ym lá⁠ròֽb׃"],[30,25,"וַֽ⁠יִּשְׂמְח֣וּ ׀ כָּל־קְהַ֣ל יְהוּדָ֗ה וְ⁠הַ⁠כֹּהֲנִים֙ וְ⁠הַ⁠לְוִיִּ֔ם וְ⁠כָל־הַ⁠קָּהָ֖ל הַ⁠בָּאִ֣ים מִ⁠יִּשְׂרָאֵ֑ל וְ⁠הַ⁠גֵּרִ֗ים הַ⁠בָּאִים֙ מֵ⁠אֶ֣רֶץ יִשְׂרָאֵ֔ל וְ⁠הַ⁠יּוֹשְׁבִ֖ים בִּ⁠יהוּדָֽה׃","waֽ⁠yi̇şĕ̂mĕẖ֣ẇ ׀ ká̇l-qĕha֣l yĕhẇdá֗h wĕ⁠ha⁠kò̇hàniym֙ wĕ⁠ha⁠lĕwiyi̇֔m wĕ⁠kál-ha⁠qá̇há֖l ha⁠bá̇ʼi֣ym mi⁠yi̇şĕ̂ráʼé֑l wĕ⁠ha⁠gé̇ri֗ym ha⁠bá̇ʼiym֙ mé⁠ʼe֣reẕ yişĕ̂ráʼé֔l wĕ⁠ha⁠ẏwòşĕ̌bi֖ym bi̇⁠yhẇdáֽh׃"],[30,26,"וַ⁠תְּהִ֥י שִׂמְחָֽה־גְדוֹלָ֖ה בִּֽ⁠ירוּשָׁלִָ֑ם כִּ֠י מִ⁠ימֵ֞י שְׁלֹמֹ֤ה בֶן־דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל לֹ֥א כָ⁠זֹ֖את בִּ⁠ירוּשָׁלִָֽם׃ס","wa⁠ţĕ̇hi֥y şîmĕẖáֽh-gĕdwòlá֖h biֽ̇⁠yrẇşá̌liá֑m ki̇֠y mi⁠ymé֞y şĕ̌lòmò֤h ben-dá̇wiyd֙ me֣lekĕ yişĕ̂ráʼé֔l lò֥ʼ ká⁠zò֖ʼţ bi̇⁠yrẇşá̌liáֽm׃s"],[30,27,"וַ⁠יָּקֻ֜מוּ הַ⁠כֹּהֲנִ֤ים הַ⁠לְוִיִּם֙ וַ⁠יְבָרֲכ֣וּ אֶת־הָ⁠עָ֔ם וַ⁠יִּשָּׁמַ֖ע בְּ⁠קוֹלָ֑⁠ם וַ⁠תָּב֧וֹא תְפִלָּתָ֛⁠ם לִ⁠מְע֥וֹן קָדְשׁ֖⁠וֹ לַ⁠שָּׁמָֽיִם׃פ","wa⁠yá̇qu֜mẇ ha⁠kò̇hàni֤ym ha⁠lĕwiyi̇m֙ wa⁠yĕbáràk֣ẇ ʼeţ-há⁠ʻá֔m wa⁠yi̇şá̇̌ma֖ʻ bĕ̇⁠qwòlá֑⁠m wa⁠ţá̇b֧wòʼ ţĕpilá̇ţá֛⁠m li⁠mĕʻ֥wòn qádĕş֖̌⁠wò la⁠şá̇̌máֽyim׃p"],[31,1,"וּ⁠כְ⁠כַלּ֣וֹת כָּל־זֹ֗את יָצְא֨וּ כָּל־יִשְׂרָאֵ֥ל הַֽ⁠נִּמְצְאִים֮ לְ⁠עָרֵ֣י יְהוּדָה֒ וַ⁠יְשַׁבְּר֣וּ הַ⁠מַּצֵּב֣וֹת וַ⁠יְגַדְּע֣וּ הָ⁠אֲשֵׁרִ֡ים וַ⁠יְנַתְּצ֣וּ אֶת־הַ֠⁠בָּמוֹת וְ⁠אֶת־הַֽ⁠מִּזְבְּחֹ֞ת מִ⁠כָּל־יְהוּדָ֧ה וּ⁠בִנְיָמִ֛ן וּ⁠בְ⁠אֶפְרַ֥יִם וּ⁠מְנַשֶּׁ֖ה עַד־לְ⁠כַלֵּ֑ה וַ⁠יָּשׁ֜וּבוּ כָּל־בְּנֵ֧י יִשְׂרָאֵ֛ל אִ֥ישׁ לַ⁠אֲחֻזָּת֖⁠וֹ לְ⁠עָרֵי⁠הֶֽם׃ס","ẇ⁠kĕ⁠kal֣̇wòţ ká̇l-zò֗ʼţ yáẕĕʼ֨ẇ ká̇l-yişĕ̂ráʼé֥l haֽ⁠ni̇mĕẕĕʼiym֮ lĕ⁠ʻáré֣y yĕhẇdáh֒ wa⁠yĕşǎbĕ̇r֣ẇ ha⁠mȧẕé̇b֣wòţ wa⁠yĕgadĕ̇ʻ֣ẇ há⁠ʼàşé̌ri֡ym wa⁠yĕnaţĕ̇ẕ֣ẇ ʼeţ-ha֠⁠bá̇mwòţ wĕ⁠ʼeţ-haֽ⁠mi̇zĕbĕ̇ẖò֞ţ mi⁠ká̇l-yĕhẇdá֧h ẇ⁠binĕyámi֛n ẇ⁠bĕ⁠ʼepĕra֥yim ẇ⁠mĕnaşė֖̌h ʻad-lĕ⁠kalé֑̇h wa⁠yá̇ş̌֜ẇbẇ ká̇l-bĕ̇né֧y yişĕ̂ráʼé֛l ʼi֥yş̌ la⁠ʼàẖuzá̇ţ֖⁠wò lĕ⁠ʻáréy⁠heֽm׃s"],[31,2,"וַ⁠יַּעֲמֵ֣ד יְחִזְקִיָּ֡הוּ אֶת־מַחְלְק֣וֹת הַ⁠כֹּהֲנִ֣ים וְ֠⁠הַ⁠לְוִיִּם עַֽל־מַחְלְקוֹתָ֞⁠ם אִ֣ישׁ ׀ כְּ⁠פִ֣י עֲבֹדָת֗⁠וֹ לַ⁠כֹּהֲנִים֙ וְ⁠לַ⁠לְוִיִּ֔ם לְ⁠עֹלָ֖ה וְ⁠לִ⁠שְׁלָמִ֑ים לְ⁠שָׁרֵת֙ וּ⁠לְ⁠הֹד֣וֹת וּ⁠לְ⁠הַלֵּ֔ל בְּ⁠שַׁעֲרֵ֖י מַחֲנ֥וֹת יְהוָֽה׃ס","wa⁠yȧʻàmé֣d yĕẖizĕqiyá̇֡hẇ ʼeţ-maẖĕlĕq֣wòţ ha⁠kò̇hàni֣ym wĕ֠⁠ha⁠lĕwiyi̇m ʻaֽl-maẖĕlĕqwòţá֞⁠m ʼi֣yş̌ ׀ kĕ̇⁠pi֣y ʻàbòdáţ֗⁠wò la⁠kò̇hàniym֙ wĕ⁠la⁠lĕwiyi̇֔m lĕ⁠ʻòlá֖h wĕ⁠li⁠şĕ̌lámi֑ym lĕ⁠şá̌réţ֙ ẇ⁠lĕ⁠hòd֣wòţ ẇ⁠lĕ⁠halé̇֔l bĕ̇⁠şǎʻàré֖y maẖàn֥wòţ yĕhwáֽh׃s"],[31,3,"וּ⁠מְנָת֩ הַ⁠מֶּ֨לֶךְ מִן־רְכוּשׁ֜⁠וֹ לָ⁠עֹל֗וֹת לְ⁠עֹלוֹת֙ הַ⁠בֹּ֣קֶר וְ⁠הָ⁠עֶ֔רֶב וְ⁠הָ֣⁠עֹל֔וֹת לַ⁠שַּׁבָּת֖וֹת וְ⁠לֶ⁠חֳדָשִׁ֣ים וְ⁠לַ⁠מֹּעֲדִ֑ים כַּ⁠כָּת֖וּב בְּ⁠תוֹרַ֥ת יְהוָֽה׃","ẇ⁠mĕnáţ֩ ha⁠mė֨lekĕ min-rĕkẇş̌֜⁠wò lá⁠ʻòl֗wòţ lĕ⁠ʻòlwòţ֙ ha⁠bò֣̇qer wĕ⁠há⁠ʻe֔reb wĕ⁠há֣⁠ʻòl֔wòţ la⁠şȧ̌bá̇ţ֖wòţ wĕ⁠le⁠ẖodáşǐ֣ym wĕ⁠la⁠mò̇ʻàdi֑ym kȧ⁠ká̇ţ֖ẇb bĕ̇⁠ţwòra֥ţ yĕhwáֽh׃"],[31,4,"וַ⁠יֹּ֤אמֶר לָ⁠עָם֙ לְ⁠יוֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם לָ⁠תֵ֕ת מְנָ֥ת הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּ֑ם לְמַ֥עַן יֶחֶזְק֖וּ בְּ⁠תוֹרַ֥ת יְהוָֽה׃","wa⁠yò֤̇ʼmer lá⁠ʻám֙ lĕ⁠ywòşĕ̌bé֣y yĕrẇşá̌lia֔m lá⁠ţé֕ţ mĕná֥ţ ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyi֑̇m lĕma֥ʻan yeẖezĕq֖ẇ bĕ̇⁠ţwòra֥ţ yĕhwáֽh׃"],[31,5,"וְ⁠כִ⁠פְרֹ֣ץ הַ⁠דָּבָ֗ר הִרְבּ֤וּ בְנֵֽי־יִשְׂרָאֵל֙ רֵאשִׁ֣ית דָּגָ֗ן תִּיר֤וֹשׁ וְ⁠יִצְהָר֙ וּ⁠דְבַ֔שׁ וְ⁠כֹ֖ל תְּבוּאַ֣ת שָׂדֶ֑ה וּ⁠מַעְשַׂ֥ר הַ⁠כֹּ֛ל לָ⁠רֹ֖ב הֵבִֽיאוּ׃","wĕ⁠ki⁠pĕrò֣ẕ ha⁠dá̇bá֗r hirĕḃ֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ réʼşǐ֣yţ dá̇gá֗n ţi̇yr֤wòş̌ wĕ⁠yiẕĕhár֙ ẇ⁠dĕba֔ş̌ wĕ⁠kò֖l ţĕ̇bẇʼa֣ţ şá̂de֑h ẇ⁠maʻĕşâ֥r ha⁠kò֛̇l lá⁠rò֖b hébiֽyʼẇ׃"],[31,6,"וּ⁠בְנֵ֧י יִשְׂרָאֵ֣ל וִֽ⁠יהוּדָ֗ה הַ⁠יּֽוֹשְׁבִים֮ בְּ⁠עָרֵ֣י יְהוּדָה֒ גַּם־הֵ֗ם מַעְשַׂ֤ר בָּקָר֙ וָ⁠צֹ֔אן וּ⁠מַעְשַׂ֣ר קָֽדָשִׁ֔ים הַ⁠מְקֻדָּשִׁ֖ים לַ⁠יהוָ֣ה אֱלֹהֵי⁠הֶ֑ם הֵבִ֕יאוּ וַֽ⁠יִּתְּנ֖וּ עֲרֵמ֥וֹת עֲרֵמֽוֹת׃ס","ẇ⁠bĕné֧y yişĕ̂ráʼé֣l wiֽ⁠yhẇdá֗h ha⁠ẏֽwòşĕ̌biym֮ bĕ̇⁠ʻáré֣y yĕhẇdáh֒ gȧm-hé֗m maʻĕşâ֤r bá̇qár֙ wá⁠ẕò֔ʼn ẇ⁠maʻĕşâ֣r qáֽdáşǐ֔ym ha⁠mĕqudá̇şǐ֖ym la⁠yhwá֣h ʼèlòhéy⁠he֑m hébi֕yʼẇ waֽ⁠yi̇ţĕ̇n֖ẇ ʻàrém֥wòţ ʻàrémֽwòţ׃s"],[31,7,"בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שְּׁלִשִׁ֔י הֵחֵ֥לּוּ הָ⁠עֲרֵמ֖וֹת לְ⁠יִסּ֑וֹד וּ⁠בַ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִיעִ֖י כִּלּֽוּ׃ס","bȧ⁠ẖò֨deş̌֙ ha⁠şĕ̇̌lişǐ֔y héẖé֥l̇ẇ há⁠ʻàrém֖wòţ lĕ⁠yiṡ֑wòd ẇ⁠ba⁠ẖò֥deş̌ ha⁠şĕ̇̌biyʻi֖y ki̇lֽ̇ẇ׃s"],[31,8,"וַ⁠יָּבֹ֨אוּ֙ יְחִזְקִיָּ֣הוּ וְ⁠הַ⁠שָּׂרִ֔ים וַ⁠יִּרְא֖וּ אֶת־הָ⁠עֲרֵמ֑וֹת וַֽ⁠יְבָרֲכוּ֙ אֶת־יְהוָ֔ה וְ⁠אֵ֖ת עַמּ֥⁠וֹ יִשְׂרָאֵֽל׃פ","wa⁠yá̇bò֨ʼẇ֙ yĕẖizĕqiyá֣̇hẇ wĕ⁠ha⁠şá̇̂ri֔ym wa⁠yi̇rĕʼ֖ẇ ʼeţ-há⁠ʻàrém֑wòţ waֽ⁠yĕbáràkẇ֙ ʼeţ-yĕhwá֔h wĕ⁠ʼé֖ţ ʻaṁ֥⁠wò yişĕ̂ráʼéֽl׃p"],[31,9,"וַ⁠יִּדְרֹ֣שׁ יְחִזְקִיָּ֗הוּ עַל־הַ⁠כֹּֽהֲנִ֛ים וְ⁠הַ⁠לְוִיִּ֖ם עַל־הָ⁠עֲרֵמֽוֹת׃","wa⁠yi̇dĕrò֣ş̌ yĕẖizĕqiyá̇֗hẇ ʻal-ha⁠kòֽ̇hàni֛ym wĕ⁠ha⁠lĕwiyi֖̇m ʻal-há⁠ʻàrémֽwòţ׃"],[31,10,"וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו עֲזַרְיָ֧הוּ הַ⁠כֹּהֵ֛ן הָ⁠רֹ֖אשׁ לְ⁠בֵ֣ית צָד֑וֹק וַ֠⁠יֹּאמֶר מֵ⁠הָחֵ֨ל הַ⁠תְּרוּמָ֜ה לָ⁠בִ֣יא בֵית־יְהוָ֗ה אָכ֨וֹל וְ⁠שָׂב֤וֹעַ וְ⁠הוֹתֵר֙ עַד־לָ⁠ר֔וֹב כִּ֤י יְהוָה֙ בֵּרַ֣ךְ אֶת־עַמּ֔⁠וֹ וְ⁠הַ⁠נּוֹתָ֖ר אֶת־הֶ⁠הָמ֥וֹן הַ⁠זֶּֽה׃ס","wa⁠yò֣̇ʼmer ʼélá֗y⁠w ʻàzarĕyá֧hẇ ha⁠kò̇hé֛n há⁠rò֖ʼş̌ lĕ⁠bé֣yţ ẕád֑wòq wa֠⁠yò̇ʼmer mé⁠háẖé֨l ha⁠ţĕ̇rẇmá֜h lá⁠bi֣yʼ béyţ-yĕhwá֗h ʼák֨wòl wĕ⁠şá̂b֤wòʻa wĕ⁠hwòţér֙ ʻad-lá⁠r֔wòb ki֤̇y yĕhwáh֙ bé̇ra֣kĕ ʼeţ-ʻaṁ֔⁠wò wĕ⁠ha⁠ṅwòţá֖r ʼeţ-he⁠hám֥wòn ha⁠zėֽh׃s"],[31,11,"וַ⁠יֹּ֣אמֶר יְחִזְקִיָּ֗הוּ לְ⁠הָכִ֧ין לְשָׁכ֛וֹת בְּ⁠בֵ֥ית יְהוָ֖ה וַ⁠יָּכִֽינוּ׃","wa⁠yò֣̇ʼmer yĕẖizĕqiyá̇֗hẇ lĕ⁠háki֧yn lĕşá̌k֛wòţ bĕ̇⁠bé֥yţ yĕhwá֖h wa⁠yá̇kiֽynẇ׃"],[31,12,"וַ⁠יָּבִ֨יאוּ אֶת־הַ⁠תְּרוּמָ֧ה וְ⁠הַֽ⁠מַּעֲשֵׂ֛ר וְ⁠הַ⁠קֳּדָשִׁ֖ים בֶּ⁠אֱמוּנָ֑ה וַ⁠עֲלֵי⁠הֶ֤ם נָגִיד֙ כונניהו הַ⁠לֵּוִ֔י וְ⁠שִׁמְעִ֥י אָחִ֖י⁠הוּ מִשְׁנֶֽה׃","wa⁠yá̇bi֨yʼẇ ʼeţ-ha⁠ţĕ̇rẇmá֧h wĕ⁠haֽ⁠mȧʻàşé֛̂r wĕ⁠ha⁠qȯdáşǐ֖ym bė⁠ʼèmẇná֑h wa⁠ʻàléy⁠he֤m nágiyd֙ kwnnyhw ha⁠lé̇wi֔y wĕ⁠şǐmĕʻi֥y ʼáẖi֖y⁠hẇ mişĕ̌neֽh׃"],[31,13,"וִֽ⁠יחִיאֵ֡ל וַ֠⁠עֲזַזְיָהוּ וְ⁠נַ֨חַת וַ⁠עֲשָׂהאֵ֜ל וִֽ⁠ירִימ֤וֹת וְ⁠יוֹזָבָד֙ וֶ⁠אֱלִיאֵ֣ל וְ⁠יִסְמַכְיָ֔הוּ וּ⁠מַ֖חַת וּ⁠בְנָיָ֑הוּ פְּקִידִ֗ים מִ⁠יַּ֤ד כונניהו וְ⁠שִׁמְעִ֣י אָחִ֔י⁠ו בְּ⁠מִפְקַד֙ יְחִזְקִיָּ֣הוּ הַ⁠מֶּ֔לֶךְ וַ⁠עֲזַרְיָ֖הוּ נְגִ֥יד בֵּית־הָ⁠אֱלֹהִֽים׃","wiֽ⁠yẖiyʼé֡l wa֠⁠ʻàzazĕyáhẇ wĕ⁠na֨ẖaţ wa⁠ʻàşá̂hʼé֜l wiֽ⁠yriym֤wòţ wĕ⁠ywòzábád֙ we⁠ʼèliyʼé֣l wĕ⁠yisĕmakĕyá֔hẇ ẇ⁠ma֖ẖaţ ẇ⁠bĕnáyá֑hẇ pĕ̇qiydi֗ym mi⁠yȧ֤d kwnnyhw wĕ⁠şǐmĕʻi֣y ʼáẖi֔y⁠w bĕ̇⁠mipĕqad֙ yĕẖizĕqiyá֣̇hẇ ha⁠mė֔lekĕ wa⁠ʻàzarĕyá֖hẇ nĕgi֥yd bé̇yţ-há⁠ʼèlòhiֽym׃"],[31,14,"וְ⁠קוֹרֵ֨א בֶן־יִמְנָ֤ה הַ⁠לֵּוִי֙ הַ⁠שּׁוֹעֵ֣ר לַ⁠מִּזְרָ֔חָ⁠ה עַ֖ל נִדְב֣וֹת הָ⁠אֱלֹהִ֑ים לָ⁠תֵת֙ תְּרוּמַ֣ת יְהוָ֔ה וְ⁠קָדְשֵׁ֖י הַ⁠קֳּדָשִֽׁים׃","wĕ⁠qwòré֨ʼ ben-yimĕná֤h ha⁠lé̇wiy֙ ha⁠ş̇̌wòʻé֣r la⁠mi̇zĕrá֔ẖá⁠h ʻa֖l nidĕb֣wòţ há⁠ʼèlòhi֑ym lá⁠ţéţ֙ ţĕ̇rẇma֣ţ yĕhwá֔h wĕ⁠qádĕşé֖̌y ha⁠qȯdáşǐֽym׃"],[31,15,"וְ⁠עַל־יָד֡⁠וֹ עֵ֣דֶן וּ֠⁠מִנְיָמִן וְ⁠יֵשׁ֨וּעַ וּֽ⁠שְׁמַֽעְיָ֜הוּ אֲמַרְיָ֧הוּ וּ⁠שְׁכַנְיָ֛הוּ בְּ⁠עָרֵ֥י הַ⁠כֹּהֲנִ֖ים בֶּ⁠אֱמוּנָ֑ה לָ⁠תֵ֤ת לַ⁠אֲחֵי⁠הֶם֙ בְּ⁠מַחְלְק֔וֹת כַּ⁠גָּד֖וֹל כַּ⁠קָּטָֽן׃","wĕ⁠ʻal-yád֡⁠wò ʻé֣den ẇ֠⁠minĕyámin wĕ⁠yéş̌֨ẇʻa ẇֽ⁠şĕ̌maֽʻĕyá֜hẇ ʼàmarĕyá֧hẇ ẇ⁠şĕ̌kanĕyá֛hẇ bĕ̇⁠ʻáré֥y ha⁠kò̇hàni֖ym bė⁠ʼèmẇná֑h lá⁠ţé֤ţ la⁠ʼàẖéy⁠hem֙ bĕ̇⁠maẖĕlĕq֔wòţ kȧ⁠gá̇d֖wòl kȧ⁠qá̇táֽn׃"],[31,16,"מִ⁠לְּ⁠בַ֞ד הִתְיַחְשָׂ֣⁠ם לִ⁠זְכָרִ֗ים מִ⁠בֶּ֨ן שָׁל֤וֹשׁ שָׁנִים֙ וּ⁠לְ⁠מַ֔עְלָ⁠ה לְ⁠כָל־הַ⁠בָּ֥א לְ⁠בֵית־יְהוָ֖ה לִ⁠דְבַר־י֣וֹם בְּ⁠יוֹמ֑⁠וֹ לַ⁠עֲב֣וֹדָתָ֔⁠ם בְּ⁠מִשְׁמְרוֹתָ֖⁠ם כְּ⁠מַחְלְקוֹתֵי⁠הֶֽם׃","mi⁠lĕ̇⁠ba֞d hiţĕyaẖĕşá֣̂⁠m li⁠zĕkári֗ym mi⁠bė֨n şá̌l֤wòş̌ şá̌niym֙ ẇ⁠lĕ⁠ma֔ʻĕlá⁠h lĕ⁠kál-ha⁠bá֥̇ʼ lĕ⁠béyţ-yĕhwá֖h li⁠dĕbar-y֣wòm bĕ̇⁠ywòm֑⁠wò la⁠ʻàb֣wòdáţá֔⁠m bĕ̇⁠mişĕ̌mĕrwòţá֖⁠m kĕ̇⁠maẖĕlĕqwòţéy⁠heֽm׃"],[31,17,"וְ⁠אֵ֨ת הִתְיַחֵ֤שׂ הַ⁠כֹּהֲנִים֙ לְ⁠בֵ֣ית אֲבוֹתֵי⁠הֶ֔ם וְ⁠הַ֨⁠לְוִיִּ֔ם מִ⁠בֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וּ⁠לְ⁠מָ֑עְלָ⁠ה בְּ⁠מִשְׁמְרוֹתֵי⁠הֶ֖ם בְּ⁠מַחְלְקוֹתֵי⁠הֶֽם׃","wĕ⁠ʼé֨ţ hiţĕyaẖé֤ş̂ ha⁠kò̇hàniym֙ lĕ⁠bé֣yţ ʼàbwòţéy⁠he֔m wĕ⁠ha֨⁠lĕwiyi̇֔m mi⁠bė֛n ʻeşĕ̂ri֥ym şá̌ná֖h ẇ⁠lĕ⁠má֑ʻĕlá⁠h bĕ̇⁠mişĕ̌mĕrwòţéy⁠he֖m bĕ̇⁠maẖĕlĕqwòţéy⁠heֽm׃"],[31,18,"וּ⁠לְ⁠הִתְיַחֵ֗שׂ בְּ⁠כָל־טַפָּ֧⁠ם נְשֵׁי⁠הֶ֛ם וּ⁠בְנֵי⁠הֶ֥ם וּ⁠בְנוֹתֵי⁠הֶ֖ם לְ⁠כָל־קָהָ֑ל כִּ֥י בֶ⁠אֱמוּנָתָ֖⁠ם יִתְקַדְּשׁוּ־קֹֽדֶשׁ׃","ẇ⁠lĕ⁠hiţĕyaẖé֗ş̂ bĕ̇⁠kál-tapá֧̇⁠m nĕşé̌y⁠he֛m ẇ⁠bĕnéy⁠he֥m ẇ⁠bĕnwòţéy⁠he֖m lĕ⁠kál-qáhá֑l ki֥̇y be⁠ʼèmẇnáţá֖⁠m yiţĕqadĕ̇ş̌ẇ-qòֽdeş̌׃"],[31,19,"וְ⁠לִ⁠בְנֵי֩ אַהֲרֹ֨ן הַ⁠כֹּהֲנִ֜ים בִּ⁠שְׂדֵ֨י מִגְרַ֤שׁ עָרֵי⁠הֶם֙ בְּ⁠כָל־עִ֣יר וָ⁠עִ֔יר אֲנָשִׁ֕ים אֲשֶׁ֥ר נִקְּב֖וּ בְּ⁠שֵׁמ֑וֹת לָ⁠תֵ֣ת מָנ֗וֹת לְ⁠כָל־זָכָר֙ בַּ⁠כֹּ֣הֲנִ֔ים וּ⁠לְ⁠כָל־הִתְיַחֵ֖שׂ בַּ⁠לְוִיִּֽם׃","wĕ⁠li⁠bĕnéy֩ ʼahàrò֨n ha⁠kò̇hàni֜ym bi̇⁠şĕ̂dé֨y migĕra֤ş̌ ʻáréy⁠hem֙ bĕ̇⁠kál-ʻi֣yr wá⁠ʻi֔yr ʼànáşǐ֕ym ʼàşě֥r niqĕ̇b֖ẇ bĕ̇⁠şé̌m֑wòţ lá⁠ţé֣ţ mán֗wòţ lĕ⁠kál-zákár֙ bȧ⁠kò֣̇hàni֔ym ẇ⁠lĕ⁠kál-hiţĕyaẖé֖ş̂ bȧ⁠lĕwiyiֽ̇m׃"],[31,20,"וַ⁠יַּ֧עַשׂ כָּ⁠זֹ֛את יְחִזְקִיָּ֖הוּ בְּ⁠כָל־יְהוּדָ֑ה וַ⁠יַּ֨עַשׂ הַ⁠טּ֤וֹב וְ⁠הַ⁠יָּשָׁר֙ וְ⁠הָ֣⁠אֱמֶ֔ת לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהָֽי⁠ו׃","wa⁠yȧ֧ʻaş̂ ká̇⁠zò֛ʼţ yĕẖizĕqiyá֖̇hẇ bĕ̇⁠kál-yĕhẇdá֑h wa⁠yȧ֨ʻaş̂ ha⁠ṫ֤wòb wĕ⁠ha⁠yá̇şá̌r֙ wĕ⁠há֣⁠ʼème֔ţ li⁠pĕné֖y yĕhwá֥h ʼèlòháֽy⁠w׃"],[31,21,"וּ⁠בְ⁠כָֽל־מַעֲשֶׂ֞ה אֲשֶׁר־הֵחֵ֣ל ׀ בַּ⁠עֲבוֹדַ֣ת בֵּית־הָ⁠אֱלֹהִ֗ים וּ⁠בַ⁠תּוֹרָה֙ וּ⁠בַ⁠מִּצְוָ֔ה לִ⁠דְרֹ֖שׁ לֵֽ⁠אלֹהָ֑י⁠ו בְּ⁠כָל־לְבָב֥⁠וֹ עָשָׂ֖ה וְ⁠הִצְלִֽיחַ׃פ","ẇ⁠bĕ⁠káֽl-maʻàşê֞h ʼàşěr-héẖé֣l ׀ bȧ⁠ʻàbwòda֣ţ bé̇yţ-há⁠ʼèlòhi֗ym ẇ⁠ba⁠ţ̇wòráh֙ ẇ⁠ba⁠mi̇ẕĕwá֔h li⁠dĕrò֖ş̌ léֽ⁠ʼlòhá֑y⁠w bĕ̇⁠kál-lĕbáb֥⁠wò ʻáşá֖̂h wĕ⁠hiẕĕliֽyẖa׃p"],[32,1,"אַחֲרֵ֨י הַ⁠דְּבָרִ֤ים וְ⁠הָ⁠אֱמֶת֙ הָ⁠אֵ֔לֶּה בָּ֖א סַנְחֵרִ֣יב מֶֽלֶךְ־אַשּׁ֑וּר וַ⁠יָּבֹ֣א בִֽ⁠יהוּדָ֗ה וַ⁠יִּ֨חַן֙ עַל־הֶ⁠עָרִ֣ים הַ⁠בְּצֻר֔וֹת וַ⁠יֹּ֖אמֶר לְ⁠בִקְעָ֥⁠ם אֵלָֽי⁠ו׃","ʼaẖàré֨y ha⁠dĕ̇bári֤ym wĕ⁠há⁠ʼèmeţ֙ há⁠ʼé֔lėh bá֖̇ʼ sanĕẖéri֣yb meֽlekĕ-ʼaş֑̇̌ẇr wa⁠yá̇bò֣ʼ biֽ⁠yhẇdá֗h wa⁠yi̇֨ẖan֙ ʻal-he⁠ʻári֣ym ha⁠bĕ̇ẕur֔wòţ wa⁠yò֖̇ʼmer lĕ⁠biqĕʻá֥⁠m ʼéláֽy⁠w׃"],[32,2,"וַ⁠יַּרְא֙ יְחִזְקִיָּ֔הוּ כִּי־בָ֖א סַנְחֵרִ֑יב וּ⁠פָנָ֕י⁠ו לַ⁠מִּלְחָמָ֖ה עַל־יְרוּשָׁלִָֽם׃","wa⁠yȧrĕʼ֙ yĕẖizĕqiyá̇֔hẇ ki̇y-bá֖ʼ sanĕẖéri֑yb ẇ⁠páná֕y⁠w la⁠mi̇lĕẖámá֖h ʻal-yĕrẇşá̌liáֽm׃"],[32,3,"וַ⁠יִּוָּעַ֗ץ עִם־שָׂרָי⁠ו֙ וְ⁠גִבֹּרָ֔י⁠ו לִ⁠סְתּוֹם֙ אֶת־מֵימֵ֣י הָ⁠עֲיָנ֔וֹת אֲשֶׁ֖ר מִ⁠ח֣וּץ לָ⁠עִ֑יר וַֽ⁠יַּעְזְרֽוּ⁠הוּ׃","wa⁠yi̇wá̇ʻa֗ẕ ʻim-şá̂ráy⁠w֙ wĕ⁠gibò̇rá֔y⁠w li⁠sĕţ̇wòm֙ ʼeţ-méymé֣y há⁠ʻàyán֔wòţ ʼàşě֖r mi⁠ẖ֣ẇẕ lá⁠ʻi֑yr waֽ⁠yȧʻĕzĕrֽẇ⁠hẇ׃"],[32,4,"וַ⁠יִּקָּבְצ֣וּ עַם־רָ֔ב וַֽ⁠יִּסְתְּמוּ֙ אֶת־כָּל־הַ⁠מַּעְיָנ֔וֹת וְ⁠אֶת־הַ⁠נַּ֛חַל הַ⁠שּׁוֹטֵ֥ף בְּ⁠תוֹךְ־הָ⁠אָ֖רֶץ לֵ⁠אמֹ֑ר לָ֤⁠מָּה יָב֨וֹאוּ֙ מַלְכֵ֣י אַשּׁ֔וּר וּ⁠מָצְא֖וּ מַ֥יִם רַבִּֽים׃","wa⁠yi̇qá̇bĕẕ֣ẇ ʻam-rá֔b waֽ⁠yi̇sĕţĕ̇mẇ֙ ʼeţ-ká̇l-ha⁠mȧʻĕyán֔wòţ wĕ⁠ʼeţ-ha⁠nȧ֛ẖal ha⁠ş̇̌wòté֥p bĕ̇⁠ţwòkĕ-há⁠ʼá֖reẕ lé⁠ʼmò֑r lá֤⁠má̇h yáb֨wòʼẇ֙ malĕké֣y ʼaş̇̌֔ẇr ẇ⁠máẕĕʼ֖ẇ ma֥yim rabiֽ̇ym׃"],[32,5,"וַ⁠יִּתְחַזַּ֡ק וַ⁠יִּבֶן֩ אֶת־כָּל־הַ⁠חוֹמָ֨ה הַ⁠פְּרוּצָ֜ה וַ⁠יַּ֣עַל עַל־הַ⁠מִּגְדָּל֗וֹת וְ⁠לַ⁠ח֨וּצָ⁠ה֙ הַ⁠חוֹמָ֣ה אַחֶ֔רֶת וַ⁠יְחַזֵּ֥ק אֶת־הַ⁠מִּלּ֖וֹא עִ֣יר דָּוִ֑יד וַ⁠יַּ֥עַשׂ שֶׁ֛לַח לָ⁠רֹ֖ב וּ⁠מָגִנִּֽים׃","wa⁠yi̇ţĕẖazȧ֡q wa⁠yi̇ben֩ ʼeţ-ká̇l-ha⁠ẖwòmá֨h ha⁠pĕ̇rẇẕá֜h wa⁠yȧ֣ʻal ʻal-ha⁠mi̇gĕdá̇l֗wòţ wĕ⁠la⁠ẖ֨ẇẕá⁠h֙ ha⁠ẖwòmá֣h ʼaẖe֔reţ wa⁠yĕẖazé֥̇q ʼeţ-ha⁠mi̇l֖̇wòʼ ʻi֣yr dá̇wi֑yd wa⁠yȧ֥ʻaş̂ şě֛laẖ lá⁠rò֖b ẇ⁠máginiֽ̇ym׃"],[32,6,"וַ⁠יִּתֵּ֛ן שָׂרֵ֥י מִלְחָמ֖וֹת עַל־הָ⁠עָ֑ם וַ⁠יִּקְבְּצֵ֣⁠ם אֵלָ֗י⁠ו אֶל־רְחוֹב֙ שַׁ֣עַר הָ⁠עִ֔יר וַ⁠יְדַבֵּ֥ר עַל־לְבָבָ֖⁠ם לֵ⁠אמֹֽר׃","wa⁠yi̇ţé֛̇n şá̂ré֥y milĕẖám֖wòţ ʻal-há⁠ʻá֑m wa⁠yi̇qĕbĕ̇ẕé֣⁠m ʼélá֗y⁠w ʼel-rĕẖwòb֙ şǎ֣ʻar há⁠ʻi֔yr wa⁠yĕdabé֥̇r ʻal-lĕbábá֖⁠m lé⁠ʼmòֽr׃"],[32,7,"חִזְק֣וּ וְ⁠אִמְצ֔וּ אַל־תִּֽירְא֣וּ וְ⁠אַל־תֵּחַ֗תּוּ מִ⁠פְּנֵי֙ מֶ֣לֶךְ אַשּׁ֔וּר וּ⁠מִ⁠לִּ⁠פְנֵ֖י כָּל־הֶ⁠הָמ֣וֹן אֲשֶׁר־עִמּ֑⁠וֹ כִּֽי־עִמָּ֥⁠נוּ רַ֖ב מֵ⁠עִמּֽ⁠וֹ׃","ẖizĕq֣ẇ wĕ⁠ʼimĕẕ֔ẇ ʼal-ţiֽ̇yrĕʼ֣ẇ wĕ⁠ʼal-ţé̇ẖa֗ţ̇ẇ mi⁠pĕ̇néy֙ me֣lekĕ ʼaş̇̌֔ẇr ẇ⁠mi⁠li̇⁠pĕné֖y ká̇l-he⁠hám֣wòn ʼàşěr-ʻiṁ֑⁠wò kiֽ̇y-ʻimá֥̇⁠nẇ ra֖b mé⁠ʻiṁֽ⁠wò׃"],[32,8,"עִמּ⁠וֹ֙ זְר֣וֹעַ בָּשָׂ֔ר וְ⁠עִמָּ֜⁠נוּ יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ לְ⁠עָזְרֵ֔⁠נוּ וּ⁠לְ⁠הִלָּחֵ֖ם מִלְחֲמֹתֵ֑⁠נוּ וַ⁠יִּסָּמְכ֣וּ הָ⁠עָ֔ם עַל־דִּבְרֵ֖י יְחִזְקִיָּ֥הוּ מֶֽלֶךְ־יְהוּדָֽה׃פ","ʻiṁ⁠wò֙ zĕr֣wòʻa bá̇şá̂֔r wĕ⁠ʻimá̇֜⁠nẇ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ lĕ⁠ʻázĕré֔⁠nẇ ẇ⁠lĕ⁠hilá̇ẖé֖m milĕẖàmòţé֑⁠nẇ wa⁠yi̇sá̇mĕk֣ẇ há⁠ʻá֔m ʻal-di̇bĕré֖y yĕẖizĕqiyá֥̇hẇ meֽlekĕ-yĕhẇdáֽh׃p"],[32,9,"אַ֣חַר זֶ֗ה שָׁ֠לַח סַנְחֵרִ֨יב מֶֽלֶךְ־אַשּׁ֤וּר עֲבָדָי⁠ו֙ יְר֣וּשָׁלַ֔יְמָ⁠ה וְ⁠הוּא֙ עַל־לָכִ֔ישׁ וְ⁠כָל־מֶמְשַׁלְתּ֖⁠וֹ עִמּ֑⁠וֹ עַל־יְחִזְקִיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה וְ⁠עַל־כָּל־יְהוּדָ֛ה אֲשֶׁ֥ר בִּ⁠ירוּשָׁלִַ֖ם לֵ⁠אמֹֽר׃","ʼa֣ẖar ze֗h şá̌֠laẖ sanĕẖéri֨yb meֽlekĕ-ʼaş֤̇̌ẇr ʻàbádáy⁠w֙ yĕr֣ẇşá̌la֔yĕmá⁠h wĕ⁠hẇʼ֙ ʻal-láki֔yş̌ wĕ⁠kál-memĕşǎlĕţ֖̇⁠wò ʻiṁ֑⁠wò ʻal-yĕẖizĕqiyá̇֨hẇ֙ me֣lekĕ yĕhẇdá֔h wĕ⁠ʻal-ká̇l-yĕhẇdá֛h ʼàşě֥r bi̇⁠yrẇşá̌lia֖m lé⁠ʼmòֽr׃"],[32,10,"כֹּ֣ה אָמַ֔ר סַנְחֵרִ֖יב מֶ֣לֶךְ אַשּׁ֑וּר עַל־מָה֙ אַתֶּ֣ם בֹּטְחִ֔ים וְ⁠יֹשְׁבִ֥ים בְּ⁠מָצ֖וֹר בִּ⁠ירוּשָׁלִָֽם׃","kò֣̇h ʼáma֔r sanĕẖéri֖yb me֣lekĕ ʼaş֑̇̌ẇr ʻal-máh֙ ʼaţė֣m bò̇tĕẖi֔ym wĕ⁠yòşĕ̌bi֥ym bĕ̇⁠máẕ֖wòr bi̇⁠yrẇşá̌liáֽm׃"],[32,11,"הֲ⁠לֹ֤א יְחִזְקִיָּ֨הוּ֙ מַסִּ֣ית אֶתְ⁠כֶ֔ם לָ⁠תֵ֣ת אֶתְ⁠כֶ֔ם לָ⁠מ֛וּת בְּ⁠רָעָ֥ב וּ⁠בְ⁠צָמָ֖א לֵ⁠אמֹ֑ר יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ יַצִּילֵ֕⁠נוּ מִ⁠כַּ֖ף מֶ֥לֶךְ אַשּֽׁוּר׃","hà⁠lò֤ʼ yĕẖizĕqiyá̇֨hẇ֙ masi֣̇yţ ʼeţĕ⁠ke֔m lá⁠ţé֣ţ ʼeţĕ⁠ke֔m lá⁠m֛ẇţ bĕ̇⁠ráʻá֥b ẇ⁠bĕ⁠ẕámá֖ʼ lé⁠ʼmò֑r yĕhwá֣h ʼèlòhé֔y⁠nẇ yaẕi̇ylé֕⁠nẇ mi⁠kȧ֖p me֥lekĕ ʼaşֽ̇̌ẇr׃"],[32,12,"הֲ⁠לֹא־הוּא֙ יְחִזְקִיָּ֔הוּ הֵסִ֥יר אֶת־בָּמֹתָ֖י⁠ו וְ⁠אֶת־מִזְבְּחֹתָ֑י⁠ו וַ⁠יֹּ֨אמֶר לִֽ⁠יהוּדָ֤ה וְ⁠לִֽ⁠ירוּשָׁלִַ֨ם֙ לֵ⁠אמֹ֔ר לִ⁠פְנֵ֨י מִזְבֵּ֧חַ אֶחָ֛ד תִּֽשְׁתַּחֲו֖וּ וְ⁠עָלָ֥י⁠ו תַּקְטִֽירוּ׃","hà⁠lòʼ-hẇʼ֙ yĕẖizĕqiyá̇֔hẇ hési֥yr ʼeţ-bá̇mòţá֖y⁠w wĕ⁠ʼeţ-mizĕbĕ̇ẖòţá֑y⁠w wa⁠yò̇֨ʼmer liֽ⁠yhẇdá֤h wĕ⁠liֽ⁠yrẇşá̌lia֨m֙ lé⁠ʼmò֔r li⁠pĕné֨y mizĕbé֧̇ẖa ʼeẖá֛d ţiֽ̇şĕ̌ţȧẖàw֖ẇ wĕ⁠ʻálá֥y⁠w ţȧqĕtiֽyrẇ׃"],[32,13,"הֲ⁠לֹ֣א תֵדְע֗וּ מֶ֤ה עָשִׂ֨יתִי֙ אֲנִ֣י וַ⁠אֲבוֹתַ֔⁠י לְ⁠כֹ֖ל עַמֵּ֣י הָ⁠אֲרָצ֑וֹת הֲ⁠יָכ֣וֹל יָֽכְל֗וּ אֱלֹהֵי֙ גּוֹיֵ֣ הָ⁠אֲרָצ֔וֹת לְ⁠הַצִּ֥יל אֶת־אַרְצָ֖⁠ם מִ⁠יָּדִֽ⁠י׃","hà⁠lò֣ʼ ţédĕʻ֗ẇ me֤h ʻáşî֨yţiy֙ ʼàni֣y wa⁠ʼàbwòţa֔⁠y lĕ⁠kò֖l ʻamé֣̇y há⁠ʼàráẕ֑wòţ hà⁠yák֣wòl yáֽkĕl֗ẇ ʼèlòhéy֙ ġwòyé֣ há⁠ʼàráẕ֔wòţ lĕ⁠haẕi֥̇yl ʼeţ-ʼarĕẕá֖⁠m mi⁠yá̇diֽ⁠y׃"],[32,14,"מִ֠י בְּֽ⁠כָל־אֱלֹהֵ֞י הַ⁠גּוֹיִ֤ם הָ⁠אֵ֨לֶּה֙ אֲשֶׁ֣ר הֶחֱרִ֣ימוּ אֲבוֹתַ֔⁠י אֲשֶׁ֣ר יָכ֔וֹל לְ⁠הַצִּ֥יל אֶת־עַמּ֖⁠וֹ מִ⁠יָּדִ֑⁠י כִּ֤י יוּכַל֙ אֱלֹ֣הֵי⁠כֶ֔ם לְ⁠הַצִּ֥יל אֶתְ⁠כֶ֖ם מִ⁠יָּדִֽ⁠י׃","mi֠y bĕֽ̇⁠kál-ʼèlòhé֞y ha⁠ġwòyi֤m há⁠ʼé֨lėh֙ ʼàşě֣r heẖèri֣ymẇ ʼàbwòţa֔⁠y ʼàşě֣r yák֔wòl lĕ⁠haẕi֥̇yl ʼeţ-ʻaṁ֖⁠wò mi⁠yá̇di֑⁠y ki֤̇y yẇkal֙ ʼèlò֣héy⁠ke֔m lĕ⁠haẕi֥̇yl ʼeţĕ⁠ke֖m mi⁠yá̇diֽ⁠y׃"],[32,15,"וְ⁠עַתָּ֡ה אַל־יַשִּׁיא֩ אֶתְ⁠כֶ֨ם חִזְקִיָּ֜הוּ וְ⁠אַל־יַסִּ֨ית אֶתְ⁠כֶ֣ם כָּ⁠זֹאת֮ וְ⁠אַל־תַּאֲמִ֣ינוּ ל⁠וֹ֒ כִּי־לֹ֣א יוּכַ֗ל כָּל־אֱל֨וֹהַ֙ כָּל־גּ֣וֹי וּ⁠מַמְלָכָ֔ה לְ⁠הַצִּ֥יל עַמּ֛⁠וֹ מִ⁠יָּדִ֖⁠י וּ⁠מִ⁠יַּ֣ד אֲבוֹתָ֑⁠י אַ֚ף כִּ֣י אֱֽלֹהֵי⁠כֶ֔ם לֹא־יַצִּ֥ילוּ אֶתְ⁠כֶ֖ם מִ⁠יָּדִֽ⁠י׃","wĕ⁠ʻaţá̇֡h ʼal-yaşi̇̌yʼ֩ ʼeţĕ⁠ke֨m ẖizĕqiyá̇֜hẇ wĕ⁠ʼal-yasi̇֨yţ ʼeţĕ⁠ke֣m ká̇⁠zòʼţ֮ wĕ⁠ʼal-ţȧʼàmi֣ynẇ l⁠wò֒ ki̇y-lò֣ʼ yẇka֗l ká̇l-ʼèl֨wòha֙ ká̇l-ġ֣wòy ẇ⁠mamĕláká֔h lĕ⁠haẕi֥̇yl ʻaṁ֛⁠wò mi⁠yá̇di֖⁠y ẇ⁠mi⁠yȧ֣d ʼàbwòţá֑⁠y ʼa֚p ki֣̇y ʼèֽlòhéy⁠ke֔m lòʼ-yaẕi֥̇ylẇ ʼeţĕ⁠ke֖m mi⁠yá̇diֽ⁠y׃"],[32,16,"וְ⁠עוֹד֙ דִּבְּר֣וּ עֲבָדָ֔י⁠ו עַל־יְהוָ֖ה הָ⁠אֱלֹהִ֑ים וְ⁠עַ֖ל יְחִזְקִיָּ֥הוּ עַבְדּֽ⁠וֹ׃","wĕ⁠ʻwòd֙ di̇bĕ̇r֣ẇ ʻàbádá֔y⁠w ʻal-yĕhwá֖h há⁠ʼèlòhi֑ym wĕ⁠ʻa֖l yĕẖizĕqiyá֥̇hẇ ʻabĕḋֽ⁠wò׃"],[32,17,"וּ⁠סְפָרִ֣ים כָּתַ֔ב לְ⁠חָרֵ֕ף לַ⁠יהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְ⁠לֵֽ⁠אמֹ֨ר עָלָ֜י⁠ו לֵ⁠אמֹ֗ר כֵּֽ⁠אלֹהֵ֞י גּוֹיֵ֤ הָ⁠אֲרָצוֹת֙ אֲשֶׁ֨ר לֹא־הִצִּ֤ילוּ עַמָּ⁠ם֙ מִ⁠יָּדִ֔⁠י כֵּ֣ן לֹֽא־יַצִּ֞יל אֱלֹהֵ֧י יְחִזְקִיָּ֛הוּ עַמּ֖⁠וֹ מִ⁠יָּדִֽ⁠י׃","ẇ⁠sĕpári֣ym ká̇ţa֔b lĕ⁠ẖáré֕p la⁠yhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l wĕ⁠léֽ⁠ʼmò֨r ʻálá֜y⁠w lé⁠ʼmò֗r kéֽ̇⁠ʼlòhé֞y ġwòyé֤ há⁠ʼàráẕwòţ֙ ʼàşě֨r lòʼ-hiẕi֤̇ylẇ ʻamá̇⁠m֙ mi⁠yá̇di֔⁠y ké֣̇n lòֽʼ-yaẕi̇֞yl ʼèlòhé֧y yĕẖizĕqiyá֛̇hẇ ʻaṁ֖⁠wò mi⁠yá̇diֽ⁠y׃"],[32,18,"וַ⁠יִּקְרְא֨וּ בְ⁠קוֹל־גָּד֜וֹל יְהוּדִ֗ית עַל־עַ֤ם יְרוּשָׁלִַ֨ם֙ אֲשֶׁ֣ר עַל־הַֽ⁠חוֹמָ֔ה לְ⁠יָֽרְאָ֖⁠ם וּֽ⁠לְ⁠בַהֲלָ֑⁠ם לְמַ֖עַן יִלְכְּד֥וּ אֶת־הָ⁠עִֽיר׃","wa⁠yi̇qĕrĕʼ֨ẇ bĕ⁠qwòl-gá̇d֜wòl yĕhẇdi֗yţ ʻal-ʻa֤m yĕrẇşá̌lia֨m֙ ʼàşě֣r ʻal-haֽ⁠ẖwòmá֔h lĕ⁠yáֽrĕʼá֖⁠m ẇֽ⁠lĕ⁠bahàlá֑⁠m lĕma֖ʻan yilĕkĕ̇d֥ẇ ʼeţ-há⁠ʻiֽyr׃"],[32,19,"וַֽ⁠יְדַבְּר֔וּ אֶל־אֱלֹהֵ֖י יְרוּשָׁלִָ֑ם כְּ⁠עַ֗ל אֱלֹהֵי֙ עַמֵּ֣י הָ⁠אָ֔רֶץ מַעֲשֵׂ֖ה יְדֵ֥י הָ⁠אָדָֽם׃ס","waֽ⁠yĕdabĕ̇r֔ẇ ʼel-ʼèlòhé֖y yĕrẇşá̌liá֑m kĕ̇⁠ʻa֗l ʼèlòhéy֙ ʻamé֣̇y há⁠ʼá֔reẕ maʻàşé֖̂h yĕdé֥y há⁠ʼádáֽm׃s"],[32,20,"וַ⁠יִּתְפַּלֵּ֞ל יְחִזְקִיָּ֣הוּ הַ⁠מֶּ֗לֶךְ וִֽ⁠ישַֽׁעְיָ֧הוּ בֶן־אָמ֛וֹץ הַ⁠נָּבִ֖יא עַל־זֹ֑את וַֽ⁠יִּזְעֲק֖וּ הַ⁠שָּׁמָֽיִם׃פ","wa⁠yi̇ţĕpȧlé̇֞l yĕẖizĕqiyá֣̇hẇ ha⁠mė֗lekĕ wiֽ⁠yşǎֽʻĕyá֧hẇ ben-ʼám֛wòẕ ha⁠ná̇bi֖yʼ ʻal-zò֑ʼţ waֽ⁠yi̇zĕʻàq֖ẇ ha⁠şá̇̌máֽyim׃p"],[32,21,"וַ⁠יִּשְׁלַ֤ח יְהוָה֙ מַלְאָ֔ךְ וַ⁠יַּכְחֵ֞ד כָּל־גִּבּ֥וֹר חַ֨יִל֙ וְ⁠נָגִ֣יד וְ⁠שָׂ֔ר בְּ⁠מַחֲנֵ֖ה מֶ֣לֶךְ אַשּׁ֑וּר וַ⁠יָּשָׁב֩ בְּ⁠בֹ֨שֶׁת פָּנִ֜ים לְ⁠אַרְצ֗⁠וֹ וַ⁠יָּבֹא֙ בֵּ֣ית אֱלֹהָ֔י⁠ו ו⁠מ⁠יציא⁠ו מֵעָ֔י⁠ו שָׁ֖ם הִפִּילֻ֥⁠הוּ בֶ⁠חָֽרֶב׃","wa⁠yi̇şĕ̌la֤ẖ yĕhwáh֙ malĕʼá֔kĕ wa⁠yȧkĕẖé֞d ká̇l-gi̇ḃ֥wòr ẖa֨yil֙ wĕ⁠nági֣yd wĕ⁠şá̂֔r bĕ̇⁠maẖàné֖h me֣lekĕ ʼaş֑̇̌ẇr wa⁠yá̇şá̌b֩ bĕ̇⁠bò֨şěţ pá̇ni֜ym lĕ⁠ʼarĕẕ֗⁠wò wa⁠yá̇bòʼ֙ bé֣̇yţ ʼèlòhá֔y⁠w w⁠m⁠yẕyʼ⁠w méʻá֔y⁠w şá֖̌m hipi̇ylu֥⁠hẇ be⁠ẖáֽreb׃"],[32,22,"וַ⁠יּוֹשַׁע֩ יְהוָ֨ה אֶת־יְחִזְקִיָּ֜הוּ וְ⁠אֵ֣ת ׀ יֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם מִ⁠יַּ֛ד סַנְחֵרִ֥יב מֶֽלֶךְ־אַשּׁ֖וּר וּ⁠מִ⁠יַּד־כֹּ֑ל וַֽ⁠יְנַהֲלֵ֖⁠ם מִ⁠סָּבִֽיב׃","wa⁠ẏwòşǎʻ֩ yĕhwá֨h ʼeţ-yĕẖizĕqiyá̇֜hẇ wĕ⁠ʼé֣ţ ׀ yòşĕ̌bé֣y yĕrẇşá̌lia֗m mi⁠yȧ֛d sanĕẖéri֥yb meֽlekĕ-ʼaş֖̇̌ẇr ẇ⁠mi⁠yȧd-kò֑̇l waֽ⁠yĕnahàlé֖⁠m mi⁠sá̇biֽyb׃"],[32,23,"וְ֠⁠רַבִּים מְבִיאִ֨ים מִנְחָ֤ה לַ⁠יהוָה֙ לִ⁠יר֣וּשָׁלִַ֔ם וּ⁠מִ֨גְדָּנ֔וֹת לִֽ⁠יחִזְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּנַּשֵּׂ֛א לְ⁠עֵינֵ֥י כָל־הַ⁠גּוֹיִ֖ם מֵ⁠אַֽחֲרֵי־כֵֽן׃ס","wĕ֠⁠rabi̇ym mĕbiyʼi֨ym minĕẖá֤h la⁠yhwáh֙ li⁠yr֣ẇşá̌lia֔m ẇ⁠mi֨gĕdá̇n֔wòţ liֽ⁠yẖizĕqiyá֖̇hẇ me֣lekĕ yĕhẇdá֑h wa⁠yi̇nȧşé֛̇̂ʼ lĕ⁠ʻéyné֥y kál-ha⁠ġwòyi֖m mé⁠ʼaֽẖàréy-kéֽn׃s"],[32,24,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם חָלָ֥ה יְחִזְקִיָּ֖הוּ עַד־לָ⁠מ֑וּת וַ⁠יִּתְפַּלֵּל֙ אֶל־יְהוָ֔ה וַ⁠יֹּ֣אמֶר ל֔⁠וֹ וּ⁠מוֹפֵ֖ת נָ֥תַן לֽ⁠וֹ׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ẖálá֥h yĕẖizĕqiyá֖̇hẇ ʻad-lá⁠m֑ẇţ wa⁠yi̇ţĕpȧlé̇l֙ ʼel-yĕhwá֔h wa⁠yò֣̇ʼmer l֔⁠wò ẇ⁠mwòpé֖ţ ná֥ţan lֽ⁠wò׃"],[32,25,"וְ⁠לֹא־כִ⁠גְמֻ֤ל עָלָי⁠ו֙ הֵשִׁ֣יב יְחִזְקִיָּ֔הוּ כִּ֥י גָבַ֖הּ לִבּ֑⁠וֹ וַ⁠יְהִ֤י עָלָי⁠ו֙ קֶ֔צֶף וְ⁠עַל־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃","wĕ⁠lòʼ-ki⁠gĕmu֤l ʻáláy⁠w֙ héşǐ֣yb yĕẖizĕqiyá̇֔hẇ ki֥̇y gába֖ḣ liḃ֑⁠wò wa⁠yĕhi֤y ʻáláy⁠w֙ qe֔ẕep wĕ⁠ʻal-yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃"],[32,26,"וַ⁠יִּכָּנַ֤ע יְחִזְקִיָּ֨הוּ֙ בְּ⁠גֹ֣בַהּ לִבּ֔⁠וֹ ה֖וּא וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וְ⁠לֹא־בָ֤א עֲלֵי⁠הֶם֙ קֶ֣צֶף יְהוָ֔ה בִּ⁠ימֵ֖י יְחִזְקִיָּֽהוּ׃","wa⁠yi̇ká̇na֤ʻ yĕẖizĕqiyá̇֨hẇ֙ bĕ̇⁠gò֣baḣ liḃ֔⁠wò h֖ẇʼ wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌liá֑m wĕ⁠lòʼ-bá֤ʼ ʻàléy⁠hem֙ qe֣ẕep yĕhwá֔h bi̇⁠ymé֖y yĕẖizĕqiyáֽ̇hẇ׃"],[32,27,"וַ⁠יְהִ֧י לִֽ⁠יחִזְקִיָּ֛הוּ עֹ֥שֶׁר וְ⁠כָב֖וֹד הַרְבֵּ֣ה מְאֹ֑ד וְ⁠אֹֽצָר֣וֹת עָֽשָׂה־ל֠⁠וֹ לְ⁠כֶ֨סֶף וּ⁠לְ⁠זָהָ֜ב וּ⁠לְ⁠אֶ֣בֶן יְקָרָ֗ה וְ⁠לִ⁠בְשָׂמִים֙ וּ⁠לְ⁠מָ֣גִנִּ֔ים וּ⁠לְ⁠כֹ֖ל כְּלֵ֥י חֶמְדָּֽה׃","wa⁠yĕhi֧y liֽ⁠yẖizĕqiyá֛̇hẇ ʻò֥şěr wĕ⁠káb֖wòd harĕbé֣̇h mĕʼò֑d wĕ⁠ʼòֽẕár֣wòţ ʻáֽşá̂h-l֠⁠wò lĕ⁠ke֨sep ẇ⁠lĕ⁠záhá֜b ẇ⁠lĕ⁠ʼe֣ben yĕqárá֗h wĕ⁠li⁠bĕşá̂miym֙ ẇ⁠lĕ⁠má֣gini̇֔ym ẇ⁠lĕ⁠kò֖l kĕ̇lé֥y ẖemĕdáֽ̇h׃"],[32,28,"וּ⁠מִ֨סְכְּנ֔וֹת לִ⁠תְבוּאַ֥ת דָּגָ֖ן וְ⁠תִיר֣וֹשׁ וְ⁠יִצְהָ֑ר וְ⁠אֻֽרָוֺת֙ לְ⁠כָל־בְּהֵמָ֣ה וּ⁠בְהֵמָ֔ה וַ⁠עֲדָרִ֖ים לָ⁠אֲוֵרֽוֹת׃","ẇ⁠mi֨sĕkĕ̇n֔wòţ li⁠ţĕbẇʼa֥ţ dá̇gá֖n wĕ⁠ţiyr֣wòş̌ wĕ⁠yiẕĕhá֑r wĕ⁠ʼuֽráwֺţ֙ lĕ⁠kál-bĕ̇hémá֣h ẇ⁠bĕhémá֔h wa⁠ʻàdári֖ym lá⁠ʼàwérֽwòţ׃"],[32,29,"וְ⁠עָרִים֙ עָ֣שָׂה ל֔⁠וֹ וּ⁠מִקְנֵה־צֹ֥אן וּ⁠בָקָ֖ר לָ⁠רֹ֑ב כִּ֤י נָֽתַן־ל⁠וֹ֙ אֱלֹהִ֔ים רְכ֖וּשׁ רַ֥ב מְאֹֽד׃","wĕ⁠ʻáriym֙ ʻá֣şá̂h l֔⁠wò ẇ⁠miqĕnéh-ẕò֥ʼn ẇ⁠báqá֖r lá⁠rò֑b ki֤̇y náֽţan-l⁠wò֙ ʼèlòhi֔ym rĕk֖ẇş̌ ra֥b mĕʼòֽd׃"],[32,30,"וְ⁠ה֣וּא יְחִזְקִיָּ֗הוּ סָתַם֙ אֶת־מוֹצָ֞א מֵימֵ֤י גִיחוֹן֙ הָֽ⁠עֶלְי֔וֹן וַֽ⁠יַּישְּׁרֵ֥⁠ם לְ⁠מַֽטָּה־מַּעְרָ֖בָ⁠ה לְ⁠עִ֣יר דָּוִ֑יד וַ⁠יַּצְלַ֥ח יְחִזְקִיָּ֖הוּ בְּ⁠כָֽל־מַעֲשֵֽׂ⁠הוּ׃","wĕ⁠h֣ẇʼ yĕẖizĕqiyá̇֗hẇ sáţam֙ ʼeţ-mwòẕá֞ʼ méymé֤y giyẖwòn֙ háֽ⁠ʻelĕy֔wòn waֽ⁠yȧyşĕ̇̌ré֥⁠m lĕ⁠maֽtá̇h-mȧʻĕrá֖bá⁠h lĕ⁠ʻi֣yr dá̇wi֑yd wa⁠yȧẕĕla֥ẖ yĕẖizĕqiyá֖̇hẇ bĕ̇⁠káֽl-maʻàşéֽ̂⁠hẇ׃"],[32,31,"וְ⁠כֵ֞ן בִּ⁠מְלִיצֵ֣י ׀ שָׂרֵ֣י בָּבֶ֗ל הַֽ⁠מְשַׁלְּחִ֤ים עָלָי⁠ו֙ לִ⁠דְרֹ֗שׁ הַ⁠מּוֹפֵת֙ אֲשֶׁ֣ר הָיָ֣ה בָ⁠אָ֔רֶץ עֲזָב֖⁠וֹ הָֽ⁠אֱלֹהִ֑ים לְ⁠נַ֨סּוֹת֔⁠וֹ לָ⁠דַ֖עַת כָּל־בִּ⁠לְבָבֽ⁠וֹ׃","wĕ⁠ké֞n bi̇⁠mĕliyẕé֣y ׀ şá̂ré֣y bá̇be֗l haֽ⁠mĕşǎlĕ̇ẖi֤ym ʻáláy⁠w֙ li⁠dĕrò֗ş̌ ha⁠ṁwòpéţ֙ ʼàşě֣r háyá֣h bá⁠ʼá֔reẕ ʻàzáb֖⁠wò hֽá⁠ʼèlòhi֑ym lĕ⁠na֨ṡwòţ֔⁠wò lá⁠da֖ʻaţ ká̇l-bi̇⁠lĕbábֽ⁠wò׃"],[32,32,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יְחִזְקִיָּ֖הוּ וַ⁠חֲסָדָ֑י⁠ו הִנָּ֣⁠ם כְּתוּבִ֗ים בַּ⁠חֲז֞וֹן יְשַֽׁעְיָ֤הוּ בֶן־אָמוֹץ֙ הַ⁠נָּבִ֔יא עַל־סֵ֥פֶר מַלְכֵי־יְהוּדָ֖ה וְ⁠יִשְׂרָאֵֽל׃","wĕ⁠ye֛ţer di̇bĕré֥y yĕẖizĕqiyá֖̇hẇ wa⁠ẖàsádá֑y⁠w hiná֣̇⁠m kĕ̇ţẇbi֗ym bȧ⁠ẖàz֞wòn yĕşǎֽʻĕyá֤hẇ ben-ʼámwòẕ֙ ha⁠ná̇bi֔yʼ ʻal-sé֥per malĕkéy-yĕhẇdá֖h wĕ⁠yişĕ̂ráʼéֽl׃"],[32,33,"וַ⁠יִּשְׁכַּ֨ב יְחִזְקִיָּ֜הוּ עִם־אֲבֹתָ֗י⁠ו וַֽ⁠יִּקְבְּרֻ⁠הוּ֮ בְּֽ⁠מַעֲלֵה֮ קִבְרֵ֣י בְנֵי־דָוִיד֒ וְ⁠כָבוֹד֙ עָֽשׂוּ־ל֣⁠וֹ בְ⁠מוֹת֔⁠וֹ כָּל־יְהוּדָ֖ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וַ⁠יִּמְלֹ֛ךְ מְנַשֶּׁ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֨b yĕẖizĕqiyá̇֜hẇ ʻim-ʼàbòţá֗y⁠w waֽ⁠yi̇qĕbĕ̇ru⁠hẇ֮ bĕֽ̇⁠maʻàléh֮ qibĕré֣y bĕnéy-dáwiyd֒ wĕ⁠kábwòd֙ ʻáֽş̂ẇ-l֣⁠wò bĕ⁠mwòţ֔⁠wò ká̇l-yĕhẇdá֖h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌liá֑m wa⁠yi̇mĕlò֛kĕ mĕnaşė֥̌h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[33,1,"בֶּן־שְׁתֵּ֥ים עֶשְׂרֵ֛ה שָׁנָ֖ה מְנַשֶּׁ֣ה בְ⁠מָלְכ֑⁠וֹ וַ⁠חֲמִשִּׁ֤ים וְ⁠חָמֵשׁ֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-şĕ̌ţé֥̇ym ʻeşĕ̂ré֛h şá̌ná֖h mĕnaşė֣̌h bĕ⁠málĕk֑⁠wò wa⁠ẖàmişi֤̇̌ym wĕ⁠ẖáméş̌֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[33,2,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠תֽוֹעֲבוֹת֙ הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠ţֽwòʻàbwòţ֙ ha⁠ġwòyi֔m ʼàşěr֙ hwòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[33,3,"וַ⁠יָּ֗שָׁב וַ⁠יִּ֨בֶן֙ אֶת־הַ⁠בָּמ֔וֹת אֲשֶׁ֥ר נִתַּ֖ץ יְחִזְקִיָּ֣הוּ אָבִ֑י⁠ו וַ⁠יָּ֨קֶם מִזְבְּח֤וֹת לַ⁠בְּעָלִים֙ וַ⁠יַּ֣עַשׂ אֲשֵׁר֔וֹת וַ⁠יִּשְׁתַּ֨חוּ֙ לְ⁠כָל־צְבָ֣א הַ⁠שָּׁמַ֔יִם וַֽ⁠יַּעֲבֹ֖ד אֹתָֽ⁠ם׃","wa⁠yá̇֗şá̌b wa⁠yi̇֨ben֙ ʼeţ-ha⁠bá̇m֔wòţ ʼàşě֥r niţȧ֖ẕ yĕẖizĕqiyá֣̇hẇ ʼábi֑y⁠w wa⁠yá̇֨qem mizĕbĕ̇ẖ֤wòţ la⁠bĕ̇ʻáliym֙ wa⁠yȧ֣ʻaş̂ ʼàşé̌r֔wòţ wa⁠yi̇şĕ̌ţȧ֨ẖẇ֙ lĕ⁠kál-ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim waֽ⁠yȧʻàbò֖d ʼòţáֽ⁠m׃"],[33,4,"וּ⁠בָנָ֥ה מִזְבְּח֖וֹת בְּ⁠בֵ֣ית יְהוָ֑ה אֲשֶׁר֙ אָמַ֣ר יְהוָ֔ה בִּ⁠ירוּשָׁלִַ֥ם יִֽהְיֶה־שְּׁמִ֖⁠י לְ⁠עוֹלָֽם׃","ẇ⁠báná֥h mizĕbĕ̇ẖ֖wòţ bĕ̇⁠bé֣yţ yĕhwá֑h ʼàşěr֙ ʼáma֣r yĕhwá֔h bi̇⁠yrẇşá̌lia֥m yiֽhĕyeh-şĕ̇̌mi֖⁠y lĕ⁠ʻwòláֽm׃"],[33,5,"וַ⁠יִּ֥בֶן מִזְבְּח֖וֹת לְ⁠כָל־צְבָ֣א הַ⁠שָּׁמָ֑יִם בִּ⁠שְׁתֵּ֖י חַצְר֥וֹת בֵּית־יְהוָֽה׃","wa⁠yi֥̇ben mizĕbĕ̇ẖ֖wòţ lĕ⁠kál-ẕĕbá֣ʼ ha⁠şá̇̌má֑yim bi̇⁠şĕ̌ţé֖̇y ẖaẕĕr֥wòţ bé̇yţ-yĕhwáֽh׃"],[33,6,"וְ⁠הוּא֩ הֶעֱבִ֨יר אֶת־בָּנָ֤י⁠ו בָּ⁠אֵשׁ֙ בְּ⁠גֵ֣י בֶן־הִנֹּ֔ם וְ⁠עוֹנֵ֤ן וְ⁠נִחֵשׁ֙ וְֽ⁠כִשֵּׁ֔ף וְ⁠עָ֥שָׂה א֖וֹב וְ⁠יִדְּעוֹנִ֑י הִרְבָּ֗ה לַ⁠עֲשׂ֥וֹת הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה לְ⁠הַכְעִיסֽ⁠וֹ׃","wĕ⁠hẇʼ֩ heʻèbi֨yr ʼeţ-bá̇ná֤y⁠w bá̇⁠ʼéş̌֙ bĕ̇⁠gé֣y ben-hinò̇֔m wĕ⁠ʻwòné֤n wĕ⁠niẖéş̌֙ wĕֽ⁠kişé̇̌֔p wĕ⁠ʻá֥şá̂h ʼ֖wòb wĕ⁠yidĕ̇ʻwòni֑y hirĕbá̇֗h la⁠ʻàş֥̂wòţ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h lĕ⁠hakĕʻiysֽ⁠wò׃"],[33,7,"וַ⁠יָּ֕שֶׂם אֶת־פֶּ֥סֶל הַ⁠סֶּ֖מֶל אֲשֶׁ֣ר עָשָׂ֑ה בְּ⁠בֵ֣ית הָ⁠אֱלֹהִ֗ים אֲשֶׁ֨ר אָמַ֤ר אֱלֹהִים֙ אֶל־דָּוִיד֙ וְ⁠אֶל־שְׁלֹמֹ֣ה בְנ֔⁠וֹ בַּ⁠בַּ֨יִת הַ⁠זֶּ֜ה וּ⁠בִֽ⁠ירוּשָׁלִַ֗ם אֲשֶׁ֤ר בָּחַ֨רְתִּי֙ מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל אָשִׂ֥ים אֶת־שְׁמִ֖⁠י לְ⁠עֵילֽוֹם׃","wa⁠yá̇֕şêm ʼeţ-pė֥sel ha⁠sė֖mel ʼàşě֣r ʻáşá֑̂h bĕ̇⁠bé֣yţ há⁠ʼèlòhi֗ym ʼàşě֨r ʼáma֤r ʼèlòhiym֙ ʼel-dá̇wiyd֙ wĕ⁠ʼel-şĕ̌lòmò֣h bĕn֔⁠wò bȧ⁠bȧ֨yiţ ha⁠zė֜h ẇ⁠biֽ⁠yrẇşá̌lia֗m ʼàşě֤r bá̇ẖa֨rĕţi̇y֙ mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l ʼáşî֥ym ʼeţ-şĕ̌mi֖⁠y lĕ⁠ʻéylֽwòm׃"],[33,8,"וְ⁠לֹ֣א אוֹסִ֗יף לְ⁠הָסִיר֙ אֶת־רֶ֣גֶל יִשְׂרָאֵ֔ל מֵ⁠עַל֙ הָֽ⁠אֲדָמָ֔ה אֲשֶׁ֥ר הֶֽעֱמַ֖דְתִּי לַ⁠אֲבֹֽתֵי⁠כֶ֑ם רַ֣ק ׀ אִם־יִשְׁמְר֣וּ לַ⁠עֲשׂ֗וֹת אֵ֚ת כָּל־אֲשֶׁ֣ר צִוִּיתִ֔י⁠ם לְ⁠כָל־הַ⁠תּוֹרָ֛ה וְ⁠הַֽ⁠חֻקִּ֥ים וְ⁠הַ⁠מִּשְׁפָּטִ֖ים בְּ⁠יַד־מֹשֶֽׁה׃","wĕ⁠lò֣ʼ ʼwòsi֗yp lĕ⁠hásiyr֙ ʼeţ-re֣gel yişĕ̂ráʼé֔l mé⁠ʻal֙ hֽá⁠ʼàdámá֔h ʼàşě֥r heֽʻèma֖dĕţi̇y la⁠ʼàbòֽţéy⁠ke֑m ra֣q ׀ ʼim-yişĕ̌mĕr֣ẇ la⁠ʻàş̂֗wòţ ʼé֚ţ ká̇l-ʼàşě֣r ẕiwi̇yţi֔y⁠m lĕ⁠kál-ha⁠ţ̇wòrá֛h wĕ⁠haֽ⁠ẖuqi֥̇ym wĕ⁠ha⁠mi̇şĕ̌pá̇ti֖ym bĕ̇⁠yad-mòşěֽh׃"],[33,9,"וַ⁠יֶּ֣תַע מְנַשֶּׁ֔ה אֶת־יְהוּדָ֖ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם לַ⁠עֲשׂ֣וֹת רָ֔ע מִן־הַ֨⁠גּוֹיִ֔ם אֲשֶׁר֙ הִשְׁמִ֣יד יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yė֣ţaʻ mĕnaşė̌֔h ʼeţ-yĕhẇdá֖h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌liá֑m la⁠ʻàş֣̂wòţ rá֔ʻ min-ha֨⁠ġwòyi֔m ʼàşěr֙ hişĕ̌mi֣yd yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃p"],[33,10,"וַ⁠יְדַבֵּ֧ר יְהוָ֛ה אֶל־מְנַשֶּׁ֥ה וְ⁠אֶל־עַמּ֖⁠וֹ וְ⁠לֹ֥א הִקְשִֽׁיבוּ׃","wa⁠yĕdabé֧̇r yĕhwá֛h ʼel-mĕnaşė֥̌h wĕ⁠ʼel-ʻaṁ֖⁠wò wĕ⁠lò֥ʼ hiqĕşǐֽybẇ׃"],[33,11,"וַ⁠יָּבֵ֨א יְהוָ֜ה עֲלֵי⁠הֶ֗ם אֶת־שָׂרֵ֤י הַ⁠צָּבָא֙ אֲשֶׁר֙ לְ⁠מֶ֣לֶךְ אַשּׁ֔וּר וַ⁠יִּלְכְּד֥וּ אֶת־מְנַשֶּׁ֖ה בַּ⁠חֹחִ֑ים וַ⁠יַּֽאַסְרֻ֨⁠הוּ֙ בַּֽ⁠נְחֻשְׁתַּ֔יִם וַ⁠יּוֹלִיכֻ֖⁠הוּ בָּבֶֽלָ⁠ה׃","wa⁠yá̇bé֨ʼ yĕhwá֜h ʻàléy⁠he֗m ʼeţ-şá̂ré֤y ha⁠ẕá̇báʼ֙ ʼàşěr֙ lĕ⁠me֣lekĕ ʼaş̇̌֔ẇr wa⁠yi̇lĕkĕ̇d֥ẇ ʼeţ-mĕnaşė֖̌h bȧ⁠ẖòẖi֑ym wa⁠yȧֽʼasĕru֨⁠hẇ֙ bȧֽ⁠nĕẖuşĕ̌ţȧ֔yim wa⁠ẏwòliyku֖⁠hẇ bá̇beֽlá⁠h׃"],[33,12,"וּ⁠כְ⁠הָצֵ֣ר ל֔⁠וֹ חִלָּ֕ה אֶת־פְּנֵ֖י יְהוָ֣ה אֱלֹהָ֑י⁠ו וַ⁠יִּכָּנַ֣ע מְאֹ֔ד מִ⁠לִּ⁠פְנֵ֖י אֱלֹהֵ֥י אֲבֹתָֽי⁠ו׃","ẇ⁠kĕ⁠háẕé֣r l֔⁠wò ẖilá̇֕h ʼeţ-pĕ̇né֖y yĕhwá֣h ʼèlòhá֑y⁠w wa⁠yi̇ká̇na֣ʻ mĕʼò֔d mi⁠li̇⁠pĕné֖y ʼèlòhé֥y ʼàbòţáֽy⁠w׃"],[33,13,"וַ⁠יִּתְפַּלֵּ֣ל אֵלָ֗י⁠ו וַ⁠יֵּעָ֤תֶר ל⁠וֹ֙ וַ⁠יִּשְׁמַ֣ע תְּחִנָּת֔⁠וֹ וַ⁠יְשִׁיבֵ֥⁠הוּ יְרוּשָׁלִַ֖ם לְ⁠מַלְכוּת֑⁠וֹ וַ⁠יֵּ֣דַע מְנַשֶּׁ֔ה כִּ֥י יְהוָ֖ה ה֥וּא הָֽ⁠אֱלֹהִֽים׃","wa⁠yi̇ţĕpȧlé֣̇l ʼélá֗y⁠w wa⁠yé̇ʻá֤ţer l⁠wò֙ wa⁠yi̇şĕ̌ma֣ʻ ţĕ̇ẖiná̇ţ֔⁠wò wa⁠yĕşǐybé֥⁠hẇ yĕrẇşá̌lia֖m lĕ⁠malĕkẇţ֑⁠wò wa⁠yé֣̇daʻ mĕnaşė̌֔h ki֥̇y yĕhwá֖h h֥ẇʼ háֽ⁠ʼèlòhiֽym׃"],[33,14,"וְ⁠אַחֲרֵי־כֵ֡ן בָּנָ֣ה חוֹמָ֣ה חִֽיצוֹנָ֣ה ׀ לְ⁠עִיר־דָּוִ֡יד מַעְרָבָ⁠ה֩ לְ⁠גִיח֨וֹן בַּ⁠נַּ֜חַל וְ⁠לָ⁠ב֨וֹא בְ⁠שַׁ֤עַר הַ⁠דָּגִים֙ וְ⁠סָבַ֣ב לָ⁠עֹ֔פֶל וַ⁠יַּגְבִּיהֶ֖⁠הָ מְאֹ֑ד וַ⁠יָּ֧שֶׂם שָֽׂרֵי־חַ֛יִל בְּ⁠כָל־הֶ⁠עָרִ֥ים הַ⁠בְּצֻר֖וֹת בִּ⁠יהוּדָֽה׃","wĕ⁠ʼaẖàréy-ké֡n bá̇ná֣h ẖwòmá֣h ẖiֽyẕwòná֣h ׀ lĕ⁠ʻiyr-dá̇wi֡yd maʻĕrábá⁠h֩ lĕ⁠giyẖ֨wòn bȧ⁠nȧ֜ẖal wĕ⁠lá⁠b֨wòʼ bĕ⁠şǎ֤ʻar ha⁠dá̇giym֙ wĕ⁠sába֣b lá⁠ʻò֔pel wa⁠yȧgĕbi̇yhe֖⁠há mĕʼò֑d wa⁠yá֧̇şêm şáֽ̂réy-ẖa֛yil bĕ̇⁠kál-he⁠ʻári֥ym ha⁠bĕ̇ẕur֖wòţ bi̇⁠yhẇdáֽh׃"],[33,15,"וַ֠⁠יָּסַר אֶת־אֱלֹהֵ֨י הַ⁠נֵּכָ֤ר וְ⁠אֶת־הַ⁠סֶּ֨מֶל֙ מִ⁠בֵּ֣ית יְהוָ֔ה וְ⁠כָל־הַֽ⁠מִּזְבְּח֗וֹת אֲשֶׁ֥ר בָּנָ֛ה בְּ⁠הַ֥ר בֵּית־יְהוָ֖ה וּ⁠בִ⁠ירוּשָׁלִָ֑ם וַ⁠יַּשְׁלֵ֖ךְ ח֥וּצָ⁠ה לָ⁠עִֽיר׃","wa֠⁠yá̇sar ʼeţ-ʼèlòhé֨y ha⁠né̇ká֤r wĕ⁠ʼeţ-ha⁠sė֨mel֙ mi⁠bé֣̇yţ yĕhwá֔h wĕ⁠kál-haֽ⁠mi̇zĕbĕ̇ẖ֗wòţ ʼàşě֥r bá̇ná֛h bĕ̇⁠ha֥r bé̇yţ-yĕhwá֖h ẇ⁠bi⁠yrẇşá̌liá֑m wa⁠yȧşĕ̌lé֖kĕ ẖ֥ẇẕá⁠h lá⁠ʻiֽyr׃"],[33,16,"ו⁠יכן אֶת־מִזְבַּ֣ח יְהוָ֔ה וַ⁠יִּזְבַּ֣ח עָלָ֔י⁠ו זִבְחֵ֥י שְׁלָמִ֖ים וְ⁠תוֹדָ֑ה וַ⁠יֹּ֨אמֶר֙ לִֽ⁠יהוּדָ֔ה לַ⁠עֲב֕וֹד אֶת־יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","w⁠ykn ʼeţ-mizĕbȧ֣ẖ yĕhwá֔h wa⁠yi̇zĕbȧ֣ẖ ʻálá֔y⁠w zibĕẖé֥y şĕ̌lámi֖ym wĕ⁠ţwòdá֑h wa⁠yò̇֨ʼmer֙ liֽ⁠yhẇdá֔h la⁠ʻàb֕wòd ʼeţ-yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[33,17,"אֲבָל֙ ע֣וֹד הָ⁠עָ֔ם זֹבְחִ֖ים בַּ⁠בָּמ֑וֹת רַ֖ק לַ⁠יהוָ֥ה אֱלֹהֵי⁠הֶֽם׃","ʼàbál֙ ʻ֣wòd há⁠ʻá֔m zòbĕẖi֖ym bȧ⁠bá̇m֑wòţ ra֖q la⁠yhwá֥h ʼèlòhéy⁠heֽm׃"],[33,18,"וְ⁠יֶ֨תֶר דִּבְרֵ֣י מְנַשֶּׁה֮ וּ⁠תְפִלָּת֣⁠וֹ אֶל־אֱלֹהָי⁠ו֒ וְ⁠דִבְרֵי֙ הַֽ⁠חֹזִ֔ים הַֽ⁠מְדַבְּרִ֣ים אֵלָ֔י⁠ו בְּ⁠שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל הִנָּ֕⁠ם עַל־דִּבְרֵ֖י מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֣y mĕnaşė̌h֮ ẇ⁠ţĕpilá̇ţ֣⁠wò ʼel-ʼèlòháy⁠w֒ wĕ⁠dibĕréy֙ haֽ⁠ẖòzi֔ym haֽ⁠mĕdabĕ̇ri֣ym ʼélá֔y⁠w bĕ̇⁠şé֥̌m yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l hiná̇֕⁠m ʻal-di̇bĕré֖y malĕké֥y yişĕ̂ráʼéֽl׃"],[33,19,"וּ⁠תְפִלָּת֣⁠וֹ וְ⁠הֵֽעָתֶר־ל⁠וֹ֮ וְ⁠כָל־חַטָּאת֣⁠וֹ וּ⁠מַעְל⁠וֹ֒ וְ⁠הַ⁠מְּקֹמ֗וֹת אֲשֶׁר֩ בָּנָ֨ה בָ⁠הֶ֤ם בָּמוֹת֙ וְ⁠הֶעֱמִיד֙ הָ⁠אֲשֵׁרִ֣ים וְ⁠הַ⁠פְּסִלִ֔ים לִ⁠פְנֵ֖י הִכָּנְע֑⁠וֹ הִנָּ֣⁠ם כְּתוּבִ֔ים עַ֖ל דִּבְרֵ֥י חוֹזָֽי׃","ẇ⁠ţĕpilá̇ţ֣⁠wò wĕ⁠héֽʻáţer-l⁠wò֮ wĕ⁠kál-ẖatá̇ʼţ֣⁠wò ẇ⁠maʻĕl⁠wò֒ wĕ⁠ha⁠mĕ̇qòm֗wòţ ʼàşěr֩ bá̇ná֨h bá⁠he֤m bá̇mwòţ֙ wĕ⁠heʻèmiyd֙ há⁠ʼàşé̌ri֣ym wĕ⁠ha⁠pĕ̇sili֔ym li⁠pĕné֖y hiká̇nĕʻ֑⁠wò hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻa֖l di̇bĕré֥y ẖwòzáֽy׃"],[33,20,"וַ⁠יִּשְׁכַּ֤ב מְנַשֶּׁה֙ עִם־אֲבֹתָ֔י⁠ו וַֽ⁠יִּקְבְּרֻ֖⁠הוּ בֵּית֑⁠וֹ וַ⁠יִּמְלֹ֛ךְ אָמ֥וֹן בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b mĕnaşė̌h֙ ʻim-ʼàbòţá֔y⁠w waֽ⁠yi̇qĕbĕ̇ru֖⁠hẇ bé̇yţ֑⁠wò wa⁠yi̇mĕlò֛kĕ ʼám֥wòn bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[33,21,"בֶּן־עֶשְׂרִ֧ים וּ⁠שְׁתַּ֛יִם שָׁנָ֖ה אָמ֣וֹן בְּ⁠מָלְכ֑⁠וֹ וּ⁠שְׁתַּ֣יִם שָׁנִ֔ים מָלַ֖ךְ בִּֽ⁠ירוּשָׁלִָֽם׃","bėn-ʻeşĕ̂ri֧ym ẇ⁠şĕ̌ţȧ֛yim şá̌ná֖h ʼám֣wòn bĕ̇⁠málĕk֑⁠wò ẇ⁠şĕ̌ţȧ֣yim şá̌ni֔ym mála֖kĕ biֽ̇⁠yrẇşá̌liáֽm׃"],[33,22,"וַ⁠יַּ֤עַשׂ הָ⁠רַע֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה מְנַשֶּׁ֣ה אָבִ֑י⁠ו וּֽ⁠לְ⁠כָל־הַ⁠פְּסִילִ֗ים אֲשֶׁ֤ר עָשָׂה֙ מְנַשֶּׁ֣ה אָבִ֔י⁠ו זִבַּ֥ח אָמ֖וֹן וַ⁠יַּֽעַבְדֵֽ⁠ם׃","wa⁠yȧ֤ʻaş̂ há⁠raʻ֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h kȧ⁠ʼàşě֥r ʻáşá֖̂h mĕnaşė֣̌h ʼábi֑y⁠w ẇֽ⁠lĕ⁠kál-ha⁠pĕ̇siyli֗ym ʼàşě֤r ʻáşá̂h֙ mĕnaşė֣̌h ʼábi֔y⁠w zibȧ֥ẖ ʼám֖wòn wa⁠yȧֽʻabĕdéֽ⁠m׃"],[33,23,"וְ⁠לֹ֤א נִכְנַע֙ מִ⁠לִּ⁠פְנֵ֣י יְהוָ֔ה כְּ⁠הִכָּנַ֖ע מְנַשֶּׁ֣ה אָבִ֑י⁠ו כִּ֛י ה֥וּא אָמ֖וֹן הִרְבָּ֥ה אַשְׁמָֽה׃","wĕ⁠lò֤ʼ nikĕnaʻ֙ mi⁠li̇⁠pĕné֣y yĕhwá֔h kĕ̇⁠hiká̇na֖ʻ mĕnaşė֣̌h ʼábi֑y⁠w ki֛̇y h֥ẇʼ ʼám֖wòn hirĕbá֥̇h ʼaşĕ̌máֽh׃"],[33,24,"וַ⁠יִּקְשְׁר֤וּ עָלָי⁠ו֙ עֲבָדָ֔י⁠ו וַ⁠יְמִיתֻ֖⁠הוּ בְּ⁠בֵיתֽ⁠וֹ׃","wa⁠yi̇qĕşĕ̌r֤ẇ ʻáláy⁠w֙ ʻàbádá֔y⁠w wa⁠yĕmiyţu֖⁠hẇ bĕ̇⁠béyţֽ⁠wò׃"],[33,25,"וַ⁠יַּכּוּ֙ עַם־הָ⁠אָ֔רֶץ אֵ֥ת כָּל־הַ⁠קֹּֽשְׁרִ֖ים עַל־הַ⁠מֶּ֣לֶךְ אָמ֑וֹן וַ⁠יַּמְלִ֧יכוּ עַם־הָ⁠אָ֛רֶץ אֶת־יֹאשִׁיָּ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yȧk̇ẇ֙ ʻam-há⁠ʼá֔reẕ ʼé֥ţ ká̇l-ha⁠qòֽ̇şĕ̌ri֖ym ʻal-ha⁠mė֣lekĕ ʼám֑wòn wa⁠yȧmĕli֧ykẇ ʻam-há⁠ʼá֛reẕ ʼeţ-yòʼşǐyá֥̇hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[34,1,"בֶּן־שְׁמוֹנֶ֥ה שָׁנִ֖ים יֹאשִׁיָּ֣הוּ בְ⁠מָלְכ֑⁠וֹ וּ⁠שְׁלֹשִׁ֤ים וְ⁠אַחַת֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-şĕ̌mwòne֥h şá̌ni֖ym yòʼşǐyá֣̇hẇ bĕ⁠málĕk֑⁠wò ẇ⁠şĕ̌lòşǐ֤ym wĕ⁠ʼaẖaţ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[34,2,"וַ⁠יַּ֥עַשׂ הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יֵּ֗לֶךְ בְּ⁠דַרְכֵי֙ דָּוִ֣יד אָבִ֔י⁠ו וְ⁠לֹא־סָ֖ר יָמִ֥ין וּ⁠שְׂמֹֽאול׃","wa⁠yȧ֥ʻaş̂ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yé̇֗lekĕ bĕ̇⁠darĕkéy֙ dá̇wi֣yd ʼábi֔y⁠w wĕ⁠lòʼ-sá֖r yámi֥yn ẇ⁠şĕ̂mòֽʼwl׃"],[34,3,"וּ⁠בִ⁠שְׁמוֹנֶ֨ה שָׁנִ֜ים לְ⁠מָלְכ֗⁠וֹ וְ⁠הוּא֙ עוֹדֶ֣⁠נּוּ נַ֔עַר הֵחֵ֕ל לִ⁠דְר֕וֹשׁ לֵ⁠אלֹהֵ֖י דָּוִ֣יד אָבִ֑י⁠ו וּ⁠בִ⁠שְׁתֵּ֧ים עֶשְׂרֵ֣ה שָׁנָ֗ה הֵחֵל֙ לְ⁠טַהֵ֔ר אֶת־יְהוּדָה֙ וִ⁠יר֣וּשָׁלִַ֔ם מִן־הַ⁠בָּמוֹת֙ וְ⁠הָ֣⁠אֲשֵׁרִ֔ים וְ⁠הַ⁠פְּסִלִ֖ים וְ⁠הַ⁠מַּסֵּכֽוֹת׃","ẇ⁠bi⁠şĕ̌mwòne֨h şá̌ni֜ym lĕ⁠málĕk֗⁠wò wĕ⁠hẇʼ֙ ʻwòde֣⁠ṅẇ na֔ʻar héẖé֕l li⁠dĕr֕wòş̌ lé⁠ʼlòhé֖y dá̇wi֣yd ʼábi֑y⁠w ẇ⁠bi⁠şĕ̌ţé֧̇ym ʻeşĕ̂ré֣h şá̌ná֗h héẖél֙ lĕ⁠tahé֔r ʼeţ-yĕhẇdáh֙ wi⁠yr֣ẇşá̌lia֔m min-ha⁠bá̇mwòţ֙ wĕ⁠há֣⁠ʼàşé̌ri֔ym wĕ⁠ha⁠pĕ̇sili֖ym wĕ⁠ha⁠mȧsé̇kֽwòţ׃"],[34,4,"וַ⁠יְנַתְּצ֣וּ לְ⁠פָנָ֗י⁠ו אֵ֚ת מִזְבְּח֣וֹת הַ⁠בְּעָלִ֔ים וְ⁠הַֽ⁠חַמָּנִ֛ים אֲשֶׁר־לְ⁠מַ֥עְלָ⁠ה מֵ⁠עֲלֵי⁠הֶ֖ם גִּדֵּ֑עַ וְ֠⁠הָ⁠אֲשֵׁרִים וְ⁠הַ⁠פְּסִלִ֤ים וְ⁠הַ⁠מַּסֵּכוֹת֙ שִׁבַּ֣ר וְ⁠הֵדַ֔ק וַ⁠יִּזְרֹק֙ עַל־פְּנֵ֣י הַ⁠קְּבָרִ֔ים הַ⁠זֹּבְחִ֖ים לָ⁠הֶֽם׃","wa⁠yĕnaţĕ̇ẕ֣ẇ lĕ⁠páná֗y⁠w ʼé֚ţ mizĕbĕ̇ẖ֣wòţ ha⁠bĕ̇ʻáli֔ym wĕ⁠haֽ⁠ẖamá̇ni֛ym ʼàşěr-lĕ⁠ma֥ʻĕlá⁠h mé⁠ʻàléy⁠he֖m gi̇dé֑̇ʻa wĕ֠⁠há⁠ʼàşé̌riym wĕ⁠ha⁠pĕ̇sili֤ym wĕ⁠ha⁠mȧsé̇kwòţ֙ şǐbȧ֣r wĕ⁠héda֔q wa⁠yi̇zĕròq֙ ʻal-pĕ̇né֣y ha⁠qĕ̇bári֔ym ha⁠zò̇bĕẖi֖ym lá⁠heֽm׃"],[34,5,"וְ⁠עַצְמוֹת֙ כֹּֽהֲנִ֔ים שָׂרַ֖ף עַל־מזבחותים וַ⁠יְטַהֵ֥ר אֶת־יְהוּדָ֖ה וְ⁠אֶת־יְרוּשָׁלִָֽם׃","wĕ⁠ʻaẕĕmwòţ֙ kòֽ̇hàni֔ym şá̂ra֖p ʻal-mzbẖwţym wa⁠yĕtahé֥r ʼeţ-yĕhẇdá֖h wĕ⁠ʼeţ-yĕrẇşá̌liáֽm׃"],[34,6,"וּ⁠בְ⁠עָרֵ֨י מְנַשֶּׁ֧ה וְ⁠אֶפְרַ֛יִם וְ⁠שִׁמְע֖וֹן וְ⁠עַד־נַפְתָּלִ֑י ב⁠הר בתי⁠הם סָבִֽיב׃","ẇ⁠bĕ⁠ʻáré֨y mĕnaşė֧̌h wĕ⁠ʼepĕra֛yim wĕ⁠şǐmĕʻ֖wòn wĕ⁠ʻad-napĕţá̇li֑y b⁠hr bţy⁠hm sábiֽyb׃"],[34,7,"וַ⁠יְנַתֵּ֣ץ אֶת־הַֽ⁠מִּזְבְּח֗וֹת וְ⁠אֶת־הָ⁠אֲשֵׁרִ֤ים וְ⁠הַ⁠פְּסִלִים֙ כִּתַּ֣ת לְ⁠הֵדַ֔ק וְ⁠כָל־הַֽ⁠חַמָּנִ֥ים גִּדַּ֖ע בְּ⁠כָל־אֶ֣רֶץ יִשְׂרָאֵ֑ל וַ⁠יָּ֖שָׁב לִ⁠ירוּשָׁלִָֽם׃ס","wa⁠yĕnaţé֣̇ẕ ʼeţ-haֽ⁠mi̇zĕbĕ̇ẖ֗wòţ wĕ⁠ʼeţ-há⁠ʼàşé̌ri֤ym wĕ⁠ha⁠pĕ̇siliym֙ ki̇ţȧ֣ţ lĕ⁠héda֔q wĕ⁠kál-haֽ⁠ẖamá̇ni֥ym gi̇dȧ֖ʻ bĕ̇⁠kál-ʼe֣reẕ yişĕ̂ráʼé֑l wa⁠yá֖̇şá̌b li⁠yrẇşá̌liáֽm׃s"],[34,8,"וּ⁠בִ⁠שְׁנַ֨ת שְׁמוֹנֶ֤ה עֶשְׂרֵה֙ לְ⁠מָלְכ֔⁠וֹ לְ⁠טַהֵ֥ר הָ⁠אָ֖רֶץ וְ⁠הַ⁠בָּ֑יִת שָׁ֠לַח אֶת־שָׁפָ֨ן בֶּן־אֲצַלְיָ֜הוּ וְ⁠אֶת־מַעֲשֵׂיָ֣הוּ שַׂר־הָ⁠עִ֗יר וְ֠⁠אֵת יוֹאָ֤ח בֶּן־יֽוֹאָחָז֙ הַ⁠מַּזְכִּ֔יר לְ⁠חַזֵּ֕ק אֶת־בֵּ֖ית יְהוָ֥ה אֱלֹהָֽי⁠ו׃","ẇ⁠bi⁠şĕ̌na֨ţ şĕ̌mwòne֤h ʻeşĕ̂réh֙ lĕ⁠málĕk֔⁠wò lĕ⁠tahé֥r há⁠ʼá֖reẕ wĕ⁠ha⁠bá֑̇yiţ şá̌֠laẖ ʼeţ-şá̌pá֨n bėn-ʼàẕalĕyá֜hẇ wĕ⁠ʼeţ-maʻàşé̂yá֣hẇ şâr-há⁠ʻi֗yr wĕ֠⁠ʼéţ ywòʼá֤ẖ bėn-yֽwòʼáẖáz֙ ha⁠mȧzĕki̇֔yr lĕ⁠ẖazé̇֕q ʼeţ-bé֖̇yţ yĕhwá֥h ʼèlòháֽy⁠w׃"],[34,9,"וַ⁠יָּבֹ֜אוּ אֶל־חִלְקִיָּ֣הוּ ׀ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֗וֹל וַֽ⁠יִּתְּנוּ֮ אֶת־הַ⁠כֶּסֶף֮ הַ⁠מּוּבָ֣א בֵית־אֱלֹהִים֒ אֲשֶׁ֣ר אָסְפֽוּ־הַ⁠לְוִיִּם֩ שֹׁמְרֵ֨י הַ⁠סַּ֜ף מִ⁠יַּ֧ד מְנַשֶּׁ֣ה וְ⁠אֶפְרַ֗יִם וּ⁠מִ⁠כֹּל֙ שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל וּ⁠מִ⁠כָּל־יְהוּדָ֖ה וּ⁠בִנְיָמִ֑ן ו⁠ישבי יְרֽוּשָׁלִָֽם׃","wa⁠yá̇bò֜ʼẇ ʼel-ẖilĕqiyá֣̇hẇ ׀ ha⁠kò̇hé֣n ha⁠gá̇d֗wòl waֽ⁠yi̇ţĕ̇nẇ֮ ʼeţ-ha⁠kėsep֮ ha⁠ṁẇbá֣ʼ béyţ-ʼèlòhiym֒ ʼàşě֣r ʼásĕpֽẇ-ha⁠lĕwiyi̇m֩ şò̌mĕré֨y ha⁠sȧ֜p mi⁠yȧ֧d mĕnaşė֣̌h wĕ⁠ʼepĕra֗yim ẇ⁠mi⁠kò̇l֙ şĕ̌ʼéri֣yţ yişĕ̂ráʼé֔l ẇ⁠mi⁠ká̇l-yĕhẇdá֖h ẇ⁠binĕyámi֑n w⁠yşby yĕrֽẇşá̌liáֽm׃"],[34,10,"וַֽ⁠יִּתְּנ֗וּ עַל־יַד֙ עֹשֵׂ֣ה הַ⁠מְּלָאכָ֔ה הַ⁠מֻּפְקָדִ֖ים בְּ⁠בֵ֣ית יְהוָ֑ה וַ⁠יִּתְּנ֨וּ אֹת֜⁠וֹ עוֹשֵׂ֣י הַ⁠מְּלָאכָ֗ה אֲשֶׁ֤ר עֹשִׂים֙ בְּ⁠בֵ֣ית יְהוָ֔ה לִ⁠בְדּ֥וֹק וּ⁠לְ⁠חַזֵּ֖ק הַ⁠בָּֽיִת׃","waֽ⁠yi̇ţĕ̇n֗ẇ ʻal-yad֙ ʻòşé֣̂h ha⁠mĕ̇láʼká֔h ha⁠mu̇pĕqádi֖ym bĕ̇⁠bé֣yţ yĕhwá֑h wa⁠yi̇ţĕ̇n֨ẇ ʼòţ֜⁠wò ʻwòşé֣̂y ha⁠mĕ̇láʼká֗h ʼàşě֤r ʻòşîym֙ bĕ̇⁠bé֣yţ yĕhwá֔h li⁠bĕḋ֥wòq ẇ⁠lĕ⁠ẖazé֖̇q ha⁠báֽ̇yiţ׃"],[34,11,"וַֽ⁠יִּתְּנ֗וּ לֶ⁠חָֽרָשִׁים֙ וְ⁠לַ⁠בֹּנִ֔ים לִ⁠קְנוֹת֙ אַבְנֵ֣י מַחְצֵ֔ב וְ⁠עֵצִ֖ים לַֽ⁠מְחַבְּר֑וֹת וּ⁠לְ⁠קָרוֹת֙ אֶת־הַ⁠בָּ֣תִּ֔ים אֲשֶׁ֥ר הִשְׁחִ֖יתוּ מַלְכֵ֥י יְהוּדָֽה׃","waֽ⁠yi̇ţĕ̇n֗ẇ le⁠ẖáֽráşǐym֙ wĕ⁠la⁠bò̇ni֔ym li⁠qĕnwòţ֙ ʼabĕné֣y maẖĕẕé֔b wĕ⁠ʻéẕi֖ym laֽ⁠mĕẖabĕ̇r֑wòţ ẇ⁠lĕ⁠qárwòţ֙ ʼeţ-ha⁠bá֣̇ţi̇֔ym ʼàşě֥r hişĕ̌ẖi֖yţẇ malĕké֥y yĕhẇdáֽh׃"],[34,12,"וְ⁠הָ⁠אֲנָשִׁים֩ עֹשִׂ֨ים בֶּ⁠אֱמוּנָ֜ה בַּ⁠מְּלָאכָ֗ה וַ⁠עֲלֵי⁠הֶ֣ם ׀ מֻ֠פְקָדִים יַ֣חַת וְ⁠עֹבַדְיָ֤הוּ הַ⁠לְוִיִּם֙ מִן־בְּנֵ֣י מְרָרִ֔י וּ⁠זְכַרְיָ֧ה וּ⁠מְשֻׁלָּ֛ם מִן־בְּנֵ֥י הַ⁠קְּהָתִ֖ים לְ⁠נַצֵּ֑חַ וְ⁠הַ֨⁠לְוִיִּ֔ם כָּל־מֵבִ֖ין בִּ⁠כְלֵי־שִֽׁיר׃","wĕ⁠há⁠ʼànáşǐym֩ ʻòşî֨ym bė⁠ʼèmẇná֜h bȧ⁠mĕ̇láʼká֗h wa⁠ʻàléy⁠he֣m ׀ mu֠pĕqádiym ya֣ẖaţ wĕ⁠ʻòbadĕyá֤hẇ ha⁠lĕwiyi̇m֙ min-bĕ̇né֣y mĕrári֔y ẇ⁠zĕkarĕyá֧h ẇ⁠mĕşǔlá֛̇m min-bĕ̇né֥y ha⁠qĕ̇háţi֖ym lĕ⁠naẕé֑̇ẖa wĕ⁠ha֨⁠lĕwiyi̇֔m ká̇l-mébi֖yn bi̇⁠kĕléy-şǐֽyr׃"],[34,13,"וְ⁠עַ֣ל הַ⁠סַּבָּלִ֗ים וּֽ⁠מְנַצְּחִים֙ לְ⁠כֹל֙ עֹשֵׂ֣ה מְלָאכָ֔ה לַ⁠עֲבוֹדָ֖ה וַ⁠עֲבוֹדָ֑ה וּ⁠מֵֽ⁠הַ⁠לְוִיִּ֔ם סוֹפְרִ֥ים וְ⁠שֹׁטְרִ֖ים וְ⁠שׁוֹעֲרִֽים׃","wĕ⁠ʻa֣l ha⁠sȧbá̇li֗ym ẇֽ⁠mĕnaẕĕ̇ẖiym֙ lĕ⁠kòl֙ ʻòşé֣̂h mĕláʼká֔h la⁠ʻàbwòdá֖h wa⁠ʻàbwòdá֑h ẇ⁠méֽ⁠ha⁠lĕwiyi̇֔m swòpĕri֥ym wĕ⁠şò̌tĕri֖ym wĕ⁠ş̌wòʻàriֽym׃"],[34,14,"וּ⁠בְ⁠הוֹצִיאָ֣⁠ם אֶת־הַ⁠כֶּ֔סֶף הַ⁠מּוּבָ֖א בֵּ֣ית יְהוָ֑ה מָצָא֙ חִלְקִיָּ֣הוּ הַ⁠כֹּהֵ֔ן אֶת־סֵ֥פֶר תּֽוֹרַת־יְהוָ֖ה בְּ⁠יַד־מֹשֶֽׁה׃","ẇ⁠bĕ⁠hwòẕiyʼá֣⁠m ʼeţ-ha⁠kė֔sep ha⁠ṁẇbá֖ʼ bé֣̇yţ yĕhwá֑h máẕáʼ֙ ẖilĕqiyá֣̇hẇ ha⁠kò̇hé֔n ʼeţ-sé֥per ţֽ̇wòraţ-yĕhwá֖h bĕ̇⁠yad-mòşěֽh׃"],[34,15,"וַ⁠יַּ֣עַן חִלְקִיָּ֗הוּ וַ⁠יֹּ֨אמֶר֙ אֶל־שָׁפָ֣ן הַ⁠סּוֹפֵ֔ר סֵ֧פֶר הַ⁠תּוֹרָ֛ה מָצָ֖אתִי בְּ⁠בֵ֣ית יְהוָ֑ה וַ⁠יִּתֵּ֧ן חִלְקִיָּ֛הוּ אֶת־הַ⁠סֵּ֖פֶר אֶל־שָׁפָֽן׃","wa⁠yȧ֣ʻan ẖilĕqiyá̇֗hẇ wa⁠yò̇֨ʼmer֙ ʼel-şá̌pá֣n ha⁠ṡwòpé֔r sé֧per ha⁠ţ̇wòrá֛h máẕá֖ʼţiy bĕ̇⁠bé֣yţ yĕhwá֑h wa⁠yi̇ţé֧̇n ẖilĕqiyá֛̇hẇ ʼeţ-ha⁠sé֖̇per ʼel-şá̌páֽn׃"],[34,16,"וַ⁠יָּבֵ֨א שָׁפָ֤ן אֶת־הַ⁠סֵּ֨פֶר֙ אֶל־הַ⁠מֶּ֔לֶךְ וַ⁠יָּ֨שֶׁב ע֧וֹד אֶת־הַ⁠מֶּ֛לֶךְ דָּבָ֖ר לֵ⁠אמֹ֑ר כֹּ֛ל אֲשֶׁר־נִתַּ֥ן בְּ⁠יַד־עֲבָדֶ֖י⁠ךָ הֵ֥ם עֹשִֽׂים׃","wa⁠yá̇bé֨ʼ şá̌pá֤n ʼeţ-ha⁠sé̇֨per֙ ʼel-ha⁠mė֔lekĕ wa⁠yá̇֨şěb ʻ֧wòd ʼeţ-ha⁠mė֛lekĕ dá̇bá֖r lé⁠ʼmò֑r kò֛̇l ʼàşěr-niţȧ֥n bĕ̇⁠yad-ʻàbáde֖y⁠ká hé֥m ʻòşîֽym׃"],[34,17,"וַ⁠יַּתִּ֕יכוּ אֶת־הַ⁠כֶּ֖סֶף הַ⁠נִּמְצָ֣א בְּ⁠בֵית־יְהוָ֑ה וַֽ⁠יִּתְּנ֗וּ⁠הוּ עַל־יַד֙ הַ⁠מֻּפְקָדִ֔ים וְ⁠עַל־יַ֖ד עוֹשֵׂ֥י הַ⁠מְּלָאכָֽה׃","wa⁠yȧţi̇֕ykẇ ʼeţ-ha⁠kė֖sep ha⁠ni̇mĕẕá֣ʼ bĕ̇⁠béyţ-yĕhwá֑h waֽ⁠yi̇ţĕ̇n֗ẇ⁠hẇ ʻal-yad֙ ha⁠mu̇pĕqádi֔ym wĕ⁠ʻal-ya֖d ʻwòşé֥̂y ha⁠mĕ̇láʼkáֽh׃"],[34,18,"וַ⁠יַּגֵּ֞ד שָׁפָ֤ן הַ⁠סּוֹפֵר֙ לַ⁠מֶּ֣לֶךְ לֵ⁠אמֹ֔ר סֵ֚פֶר נָ֣תַן לִ֔⁠י חִלְקִיָּ֖הוּ הַ⁠כֹּהֵ֑ן וַ⁠יִּקְרָא־ב֥⁠וֹ שָׁפָ֖ן לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yȧgé̇֞d şá̌pá֤n ha⁠ṡwòpér֙ la⁠mė֣lekĕ lé⁠ʼmò֔r sé֚per ná֣ţan li֔⁠y ẖilĕqiyá֖̇hẇ ha⁠kò̇hé֑n wa⁠yi̇qĕráʼ-b֥⁠wò şá̌pá֖n li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[34,19,"וַ⁠יְהִי֙ כִּ⁠שְׁמֹ֣עַ הַ⁠מֶּ֔לֶךְ אֵ֖ת דִּבְרֵ֣י הַ⁠תּוֹרָ֑ה וַ⁠יִּקְרַ֖ע אֶת־בְּגָדָֽי⁠ו׃","wa⁠yĕhiy֙ ki̇⁠şĕ̌mò֣ʻa ha⁠mė֔lekĕ ʼé֖ţ di̇bĕré֣y ha⁠ţ̇wòrá֑h wa⁠yi̇qĕra֖ʻ ʼeţ-bĕ̇gádáֽy⁠w׃"],[34,20,"וַ⁠יְצַ֣ו הַ⁠מֶּ֡לֶךְ אֶת־חִלְקִיָּ֡הוּ וְ⁠אֶת־אֲחִיקָ֣ם בֶּן־שָׁ֠פָן וְ⁠אֶת־עַבְדּ֨וֹן בֶּן־מִיכָ֜ה וְ⁠אֵ֣ת ׀ שָׁפָ֣ן הַ⁠סּוֹפֵ֗ר וְ⁠אֵ֛ת עֲשָׂיָ֥ה עֶֽבֶד־הַ⁠מֶּ֖לֶךְ לֵ⁠אמֹֽר׃","wa⁠yĕẕa֣w ha⁠mė֡lekĕ ʼeţ-ẖilĕqiyá̇֡hẇ wĕ⁠ʼeţ-ʼàẖiyqá֣m bėn-şá̌֠pán wĕ⁠ʼeţ-ʻabĕḋ֨wòn bėn-miyká֜h wĕ⁠ʼé֣ţ ׀ şá̌pá֣n ha⁠ṡwòpé֗r wĕ⁠ʼé֛ţ ʻàşá̂yá֥h ʻeֽbed-ha⁠mė֖lekĕ lé⁠ʼmòֽr׃"],[34,21,"לְכוּ֩ דִרְשׁ֨וּ אֶת־יְהוָ֜ה בַּעֲדִ֗⁠י וּ⁠בְעַד֙ הַ⁠נִּשְׁאָר֙ בְּ⁠יִשְׂרָאֵ֣ל וּ⁠בִֽ⁠יהוּדָ֔ה עַל־דִּבְרֵ֥י הַ⁠סֵּ֖פֶר אֲשֶׁ֣ר נִמְצָ֑א כִּֽי־גְדוֹלָ֤ה חֲמַת־יְהוָה֙ אֲשֶׁ֣ר נִתְּכָ֣ה בָ֔⁠נוּ עַל֩ אֲשֶׁ֨ר לֹא־שָׁמְר֤וּ אֲבוֹתֵ֨י⁠נוּ֙ אֶת־דְּבַ֣ר יְהוָ֔ה לַ⁠עֲשׂ֕וֹת כְּ⁠כָל־הַ⁠כָּת֖וּב עַל־הַ⁠סֵּ֥פֶר הַ⁠זֶּֽה׃פ","lĕkẇ֩ dirĕş̌֨ẇ ʼeţ-yĕhwá֜h bȧʻàdi֗⁠y ẇ⁠bĕʻad֙ ha⁠ni̇şĕ̌ʼár֙ bĕ̇⁠yişĕ̂ráʼé֣l ẇ⁠biֽ⁠yhẇdá֔h ʻal-di̇bĕré֥y ha⁠sé֖̇per ʼàşě֣r nimĕẕá֑ʼ kiֽ̇y-gĕdwòlá֤h ẖàmaţ-yĕhwáh֙ ʼàşě֣r niţĕ̇ká֣h bá֔⁠nẇ ʻal֩ ʼàşě֨r lòʼ-şá̌mĕr֤ẇ ʼàbwòţé֨y⁠nẇ֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h la⁠ʻàş̂֕wòţ kĕ̇⁠kál-ha⁠ká̇ţ֖ẇb ʻal-ha⁠sé֥̇per ha⁠zėֽh׃p"],[34,22,"וַ⁠יֵּ֨לֶךְ חִלְקִיָּ֜הוּ וַ⁠אֲשֶׁ֣ר הַ⁠מֶּ֗לֶךְ אֶל־חֻלְדָּ֨ה הַ⁠נְּבִיאָ֜ה אֵ֣שֶׁת ׀ שַׁלֻּ֣ם בֶּן־תוקהת בֶּן־חַסְרָה֙ שׁוֹמֵ֣ר הַ⁠בְּגָדִ֔ים וְ⁠הִ֛יא יוֹשֶׁ֥בֶת בִּ⁠ירוּשָׁלִַ֖ם בַּ⁠מִּשְׁנֶ֑ה וַ⁠יְדַבְּר֥וּ אֵלֶ֖י⁠הָ כָּ⁠זֹֽאת׃ס","wa⁠yé̇֨lekĕ ẖilĕqiyá̇֜hẇ wa⁠ʼàşě֣r ha⁠mė֗lekĕ ʼel-ẖulĕdá̇֨h ha⁠nĕ̇biyʼá֜h ʼé֣şěţ ׀ şǎlu֣̇m bėn-ţwqhţ bėn-ẖasĕráh֙ ş̌wòmé֣r ha⁠bĕ̇gádi֔ym wĕ⁠hi֛yʼ ywòşě֥beţ bi̇⁠yrẇşá̌lia֖m bȧ⁠mi̇şĕ̌ne֑h wa⁠yĕdabĕ̇r֥ẇ ʼéle֖y⁠há ká̇⁠zòֽʼţ׃s"],[34,23,"וַ⁠תֹּ֣אמֶר לָ⁠הֶ֔ם כֹּה־אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אִמְר֣וּ לָ⁠אִ֔ישׁ אֲשֶׁר־שָׁלַ֥ח אֶתְ⁠כֶ֖ם אֵלָֽ⁠י׃ס","wa⁠ţò֣̇ʼmer lá⁠he֔m kò̇h-ʼáma֥r yĕhwá֖h ʼèlòhé֣y yişĕ̂ráʼé֑l ʼimĕr֣ẇ lá⁠ʼi֔yş̌ ʼàşěr-şá̌la֥ẖ ʼeţĕ⁠ke֖m ʼéláֽ⁠y׃s"],[34,24,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֨י מֵבִ֥יא רָעָ֛ה עַל־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה וְ⁠עַל־יוֹשְׁבָ֑י⁠ו אֵ֤ת כָּל־הָ⁠אָלוֹת֙ הַ⁠כְּתוּב֣וֹת עַל־הַ⁠סֵּ֔פֶר אֲשֶׁ֣ר קָֽרְא֔וּ לִ⁠פְנֵ֖י מֶ֥לֶךְ יְהוּדָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֨y mébi֥yʼ ráʻá֛h ʻal-ha⁠má̇q֥wòm ha⁠zė֖h wĕ⁠ʻal-ywòşĕ̌bá֑y⁠w ʼé֤ţ ká̇l-há⁠ʼálwòţ֙ ha⁠kĕ̇ţẇb֣wòţ ʻal-ha⁠sé̇֔per ʼàşě֣r qáֽrĕʼ֔ẇ li⁠pĕné֖y me֥lekĕ yĕhẇdáֽh׃"],[34,25,"תַּ֣חַת ׀ אֲשֶׁ֣ר עֲזָב֗וּ⁠נִי ו⁠יקטירו לֵֽ⁠אלֹהִ֣ים אֲחֵרִ֔ים לְמַ֨עַן֙ הַכְעִיסֵ֔⁠נִי בְּ⁠כֹ֖ל מַעֲשֵׂ֣י יְדֵי⁠הֶ֑ם וְ⁠תִתַּ֧ךְ חֲמָתִ֛⁠י בַּ⁠מָּק֥וֹם הַ⁠זֶּ֖ה וְ⁠לֹ֥א תִכְבֶּֽה׃","ţȧ֣ẖaţ ׀ ʼàşě֣r ʻàzáb֗ẇ⁠niy w⁠yqtyrw léֽ⁠ʼlòhi֣ym ʼàẖéri֔ym lĕma֨ʻan֙ hakĕʻiysé֔⁠niy bĕ̇⁠kò֖l maʻàşé֣̂y yĕdéy⁠he֑m wĕ⁠ţiţȧ֧kĕ ẖàmáţi֛⁠y bȧ⁠má̇q֥wòm ha⁠zė֖h wĕ⁠lò֥ʼ ţikĕbėֽh׃"],[34,26,"וְ⁠אֶל־מֶ֣לֶךְ יְהוּדָ֗ה הַ⁠שֹּׁלֵ֤חַ אֶתְ⁠כֶם֙ לִ⁠דְר֣וֹשׁ בַּֽ⁠יהוָ֔ה כֹּ֥ה תֹאמְר֖וּ אֵלָ֑י⁠ו ס כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַ⁠דְּבָרִ֖ים אֲשֶׁ֥ר שָׁמָֽעְתָּ׃","wĕ⁠ʼel-me֣lekĕ yĕhẇdá֗h ha⁠şò̇̌lé֤ẖa ʼeţĕ⁠kem֙ li⁠dĕr֣wòş̌ bȧֽ⁠yhwá֔h kò֥̇h ţòʼmĕr֖ẇ ʼélá֑y⁠w s kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ha⁠dĕ̇bári֖ym ʼàşě֥r şá̌máֽʻĕţá̇׃"],[34,27,"יַ֠עַן רַךְ־לְבָ֨בְ⁠ךָ֜ וַ⁠תִּכָּנַ֣ע ׀ מִ⁠לִּ⁠פְנֵ֣י אֱלֹהִ֗ים בְּ⁠שָׁמְעֲ⁠ךָ֤ אֶת־דְּבָרָי⁠ו֙ עַל־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ וְ⁠עַל־יֹ֣שְׁבָ֔י⁠ו וַ⁠תִּכָּנַ֣ע לְ⁠פָנַ֔⁠י וַ⁠תִּקְרַ֥ע אֶת־בְּגָדֶ֖י⁠ךָ וַ⁠תֵּ֣בְךְּ לְ⁠פָנָ֑⁠י וְ⁠גַם־אֲנִ֥י שָׁמַ֖עְתִּי נְאֻם־יְהוָֽה׃","ya֠ʻan rakĕ-lĕbá֨bĕ⁠ká֜ wa⁠ţi̇ká̇na֣ʻ ׀ mi⁠li̇⁠pĕné֣y ʼèlòhi֗ym bĕ̇⁠şá̌mĕʻà⁠ká֤ ʼeţ-dĕ̇báráy⁠w֙ ʻal-ha⁠má̇q֤wòm ha⁠zėh֙ wĕ⁠ʻal-yò֣şĕ̌bá֔y⁠w wa⁠ţi̇ká̇na֣ʻ lĕ⁠pána֔⁠y wa⁠ţi̇qĕra֥ʻ ʼeţ-bĕ̇gáde֖y⁠ká wa⁠ţé֣̇bĕkĕ̇ lĕ⁠páná֑⁠y wĕ⁠gam-ʼàni֥y şá̌ma֖ʻĕţi̇y nĕʼum-yĕhwáֽh׃"],[34,28,"הִנְ⁠נִ֨י אֹֽסִפְ⁠ךָ֜ אֶל־אֲבֹתֶ֗י⁠ךָ וְ⁠נֶאֱסַפְתָּ֣ אֶל־קִבְרֹתֶי⁠ךָ֮ בְּ⁠שָׁלוֹם֒ וְ⁠לֹא־תִרְאֶ֣ינָה עֵינֶ֔י⁠ךָ בְּ⁠כֹל֙ הָֽ⁠רָעָ֔ה אֲשֶׁ֨ר אֲנִ֥י מֵבִ֛יא עַל־הַ⁠מָּק֥וֹם הַ⁠זֶּ֖ה וְ⁠עַל־יֹשְׁבָ֑י⁠ו וַ⁠יָּשִׁ֥יבוּ אֶת־הַ⁠מֶּ֖לֶךְ דָּבָֽר׃פ","hinĕ⁠ni֨y ʼòֽsipĕ⁠ká֜ ʼel-ʼàbòţe֗y⁠ká wĕ⁠neʼèsapĕţá֣̇ ʼel-qibĕròţey⁠ká֮ bĕ̇⁠şá̌lwòm֒ wĕ⁠lòʼ-ţirĕʼe֣ynáh ʻéyne֔y⁠ká bĕ̇⁠kòl֙ háֽ⁠ráʻá֔h ʼàşě֨r ʼàni֥y mébi֛yʼ ʻal-ha⁠má̇q֥wòm ha⁠zė֖h wĕ⁠ʻal-yòşĕ̌bá֑y⁠w wa⁠yá̇şǐ֥ybẇ ʼeţ-ha⁠mė֖lekĕ dá̇báֽr׃p"],[34,29,"וַ⁠יִּשְׁלַ֖ח הַ⁠מֶּ֑לֶךְ וַ⁠יֶּאֱסֹ֕ף אֶת־כָּל־זִקְנֵ֥י יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃","wa⁠yi̇şĕ̌la֖ẖ ha⁠mė֑lekĕ wa⁠yėʼèsò֕p ʼeţ-ká̇l-ziqĕné֥y yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃"],[34,30,"וַ⁠יַּ֣עַל הַ⁠מֶּ֣לֶךְ בֵּית־יְ֠הוָה וְ⁠כָל־אִ֨ישׁ יְהוּדָ֜ה וְ⁠יֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם וְ⁠הַ⁠כֹּֽהֲנִים֙ וְ⁠הַ⁠לְוִיִּ֔ם וְ⁠כָל־הָ⁠עָ֖ם מִ⁠גָּד֣וֹל וְ⁠עַד־קָטָ֑ן וַ⁠יִּקְרָ֣א בְ⁠אָזְנֵי⁠הֶ֗ם אֶת־כָּל־דִּבְרֵי֙ סֵ֣פֶר הַ⁠בְּרִ֔ית הַ⁠נִּמְצָ֖א בֵּ֥ית יְהוָֽה׃","wa⁠yȧ֣ʻal ha⁠mė֣lekĕ bé̇yţ-yĕ֠hwáh wĕ⁠kál-ʼi֨yş̌ yĕhẇdá֜h wĕ⁠yòşĕ̌bé֣y yĕrẇşá̌lia֗m wĕ⁠ha⁠kòֽ̇hàniym֙ wĕ⁠ha⁠lĕwiyi̇֔m wĕ⁠kál-há⁠ʻá֖m mi⁠gá̇d֣wòl wĕ⁠ʻad-qátá֑n wa⁠yi̇qĕrá֣ʼ bĕ⁠ʼázĕnéy⁠he֗m ʼeţ-ká̇l-di̇bĕréy֙ sé֣per ha⁠bĕ̇ri֔yţ ha⁠ni̇mĕẕá֖ʼ bé֥̇yţ yĕhwáֽh׃"],[34,31,"וַ⁠יַּעֲמֹ֨ד הַ⁠מֶּ֜לֶךְ עַל־עָמְד֗⁠וֹ וַ⁠יִּכְרֹ֣ת אֶֽת־הַ⁠בְּרִית֮ לִ⁠פְנֵ֣י יְהוָה֒ לָ⁠לֶ֜כֶת אַחֲרֵ֣י יְהוָ֗ה וְ⁠לִ⁠שְׁמ֤וֹר אֶת־מִצְוֺתָי⁠ו֙ וְ⁠עֵֽדְוֺתָ֣י⁠ו וְ⁠חֻקָּ֔י⁠ו בְּ⁠כָל־לְבָב֖⁠וֹ וּ⁠בְ⁠כָל־נַפְשׁ֑⁠וֹ לַ⁠עֲשׂוֹת֙ אֶת־דִּבְרֵ֣י הַ⁠בְּרִ֔ית הַ⁠כְּתוּבִ֖ים עַל־הַ⁠סֵּ֥פֶר הַ⁠זֶּֽה׃","wa⁠yȧʻàmò֨d ha⁠mė֜lekĕ ʻal-ʻámĕd֗⁠wò wa⁠yi̇kĕrò֣ţ ʼeֽţ-ha⁠bĕ̇riyţ֮ li⁠pĕné֣y yĕhwáh֒ lá⁠le֜keţ ʼaẖàré֣y yĕhwá֗h wĕ⁠li⁠şĕ̌m֤wòr ʼeţ-miẕĕwֺţáy⁠w֙ wĕ⁠ʻéֽdĕwֺţá֣y⁠w wĕ⁠ẖuqá̇֔y⁠w bĕ̇⁠kál-lĕbáb֖⁠wò ẇ⁠bĕ⁠kál-napĕş֑̌⁠wò la⁠ʻàş̂wòţ֙ ʼeţ-di̇bĕré֣y ha⁠bĕ̇ri֔yţ ha⁠kĕ̇ţẇbi֖ym ʻal-ha⁠sé֥̇per ha⁠zėֽh׃"],[34,32,"וַ⁠יַּעֲמֵ֕ד אֵ֛ת כָּל־הַ⁠נִּמְצָ֥א בִ⁠ירוּשָׁלִַ֖ם וּ⁠בִנְיָמִ֑ן וַֽ⁠יַּעֲשׂוּ֙ יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם כִּ⁠בְרִ֥ית אֱלֹהִ֖ים אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃","wa⁠yȧʻàmé֕d ʼé֛ţ ká̇l-ha⁠ni̇mĕẕá֥ʼ bi⁠yrẇşá̌lia֖m ẇ⁠binĕyámi֑n waֽ⁠yȧʻàş̂ẇ֙ yòşĕ̌bé֣y yĕrẇşá̌lia֔m ki̇⁠bĕri֥yţ ʼèlòhi֖ym ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃"],[34,33,"וַ⁠יָּ֨סַר יֹֽאשִׁיָּ֜הוּ אֶת־כָּל־הַ⁠תּוֹעֵב֗וֹת מִֽ⁠כָּל־הָ⁠אֲרָצוֹת֮ אֲשֶׁ֣ר לִ⁠בְנֵ֣י יִשְׂרָאֵל֒ וַֽ⁠יַּעֲבֵ֗ד אֵ֤ת כָּל־הַ⁠נִּמְצָא֙ בְּ⁠יִשְׂרָאֵ֔ל לַ⁠עֲב֖וֹד אֶת־יְהוָ֣ה אֱלֹהֵי⁠הֶ֑ם כָּל־יָמָ֕י⁠ו לֹ֣א סָ֔רוּ מֵֽ⁠אַחֲרֵ֕י יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵי⁠הֶֽם׃פ","wa⁠yá̇֨sar yòֽʼşǐyá̇֜hẇ ʼeţ-ká̇l-ha⁠ţ̇wòʻéb֗wòţ miֽ⁠ká̇l-há⁠ʼàráẕwòţ֮ ʼàşě֣r li⁠bĕné֣y yişĕ̂ráʼél֒ waֽ⁠yȧʻàbé֗d ʼé֤ţ ká̇l-ha⁠ni̇mĕẕáʼ֙ bĕ̇⁠yişĕ̂ráʼé֔l la⁠ʻàb֖wòd ʼeţ-yĕhwá֣h ʼèlòhéy⁠he֑m ká̇l-yámá֕y⁠w lò֣ʼ sá֔rẇ méֽ⁠ʼaẖàré֕y yĕhwá֖h ʼèlòhé֥y ʼàbwòţéy⁠heֽm׃p"],[35,1,"וַ⁠יַּ֨עַשׂ יֹאשִׁיָּ֧הוּ בִֽ⁠ירוּשָׁלִַ֛ם פֶּ֖סַח לַ⁠יהוָ֑ה וַ⁠יִּשְׁחֲט֣וּ הַ⁠פֶּ֔סַח בְּ⁠אַרְבָּעָ֥ה עָשָׂ֖ר לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃","wa⁠yȧ֨ʻaş̂ yòʼşǐyá֧̇hẇ biֽ⁠yrẇşá̌lia֛m pė֖saẖ la⁠yhwá֑h wa⁠yi̇şĕ̌ẖàt֣ẇ ha⁠pė֔saẖ bĕ̇⁠ʼarĕbá̇ʻá֥h ʻáşá֖̂r la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃"],[35,2,"וַ⁠יַּעֲמֵ֥ד הַ⁠כֹּהֲנִ֖ים עַל־מִשְׁמְרוֹתָ֑⁠ם וַֽ⁠יְחַזְּקֵ֔⁠ם לַ⁠עֲבוֹדַ֖ת בֵּ֥ית יְהוָֽה׃","wa⁠yȧʻàmé֥d ha⁠kò̇hàni֖ym ʻal-mişĕ̌mĕrwòţá֑⁠m waֽ⁠yĕẖazĕ̇qé֔⁠m la⁠ʻàbwòda֖ţ bé֥̇yţ yĕhwáֽh׃"],[35,3,"וַ⁠יֹּ֣אמֶר לַ֠⁠לְוִיִּם ה⁠מבונים לְ⁠כָל־יִשְׂרָאֵ֜ל הַ⁠קְּדוֹשִׁ֣ים לַ⁠יהוָ֗ה תְּנ֤וּ אֶת־אֲרוֹן־הַ⁠קֹּ֨דֶשׁ֙ בַּ֠⁠בַּיִת אֲשֶׁ֨ר בָּנָ֜ה שְׁלֹמֹ֤ה בֶן־דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אֵין־לָ⁠כֶ֥ם מַשָּׂ֖א בַּ⁠כָּתֵ֑ף עַתָּ֗ה עִבְדוּ֙ אֶת־יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וְ⁠אֵ֖ת עַמּ֥⁠וֹ יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer la֠⁠lĕwiyi̇m h⁠mbwnym lĕ⁠kál-yişĕ̂ráʼé֜l ha⁠qĕ̇dwòşǐ֣ym la⁠yhwá֗h ţĕ̇n֤ẇ ʼeţ-ʼàrwòn-ha⁠qò̇֨deş̌֙ bȧ֠⁠bȧyiţ ʼàşě֨r bá̇ná֜h şĕ̌lòmò֤h ben-dá̇wiyd֙ me֣lekĕ yişĕ̂ráʼé֔l ʼéyn-lá⁠ke֥m maşá֖̇̂ʼ bȧ⁠ká̇ţé֑p ʻaţá̇֗h ʻibĕdẇ֙ ʼeţ-yĕhwá֣h ʼèlòֽhéy⁠ke֔m wĕ⁠ʼé֖ţ ʻaṁ֥⁠wò yişĕ̂ráʼéֽl׃"],[35,4,"והכונו לְ⁠בֵית־אֲבוֹתֵי⁠כֶ֖ם כְּ⁠מַחְלְקוֹתֵי⁠כֶ֑ם בִּ⁠כְתָ֗ב דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וּ⁠בְ⁠מִכְתַּ֖ב שְׁלֹמֹ֥ה בְנֽ⁠וֹ׃","whkwnw lĕ⁠béyţ-ʼàbwòţéy⁠ke֖m kĕ̇⁠maẖĕlĕqwòţéy⁠ke֑m bi̇⁠kĕţá֗b dá̇wiyd֙ me֣lekĕ yişĕ̂ráʼé֔l ẇ⁠bĕ⁠mikĕţȧ֖b şĕ̌lòmò֥h bĕnֽ⁠wò׃"],[35,5,"וְ⁠עִמְד֣וּ בַ⁠קֹּ֗דֶשׁ לִ⁠פְלֻגּוֹת֙ בֵּ֣ית הָֽ⁠אָב֔וֹת לַ⁠אֲחֵי⁠כֶ֖ם בְּנֵ֣י הָ⁠עָ֑ם וַ⁠חֲלֻקַּ֥ת בֵּֽית־אָ֖ב לַ⁠לְוִיִּֽם׃","wĕ⁠ʻimĕd֣ẇ ba⁠qò̇֗deş̌ li⁠pĕluġwòţ֙ bé֣̇yţ háֽ⁠ʼáb֔wòţ la⁠ʼàẖéy⁠ke֖m bĕ̇né֣y há⁠ʻá֑m wa⁠ẖàluqȧ֥ţ béֽ̇yţ-ʼá֖b la⁠lĕwiyiֽ̇m׃"],[35,6,"וְ⁠שַׁחֲט֖וּ הַ⁠פָּ֑סַח וְ⁠הִתְקַדְּשׁוּ֙ וְ⁠הָכִ֣ינוּ לַ⁠אֲחֵי⁠כֶ֔ם לַ⁠עֲשׂ֥וֹת כִּ⁠דְבַר־יְהוָ֖ה בְּ⁠יַד־מֹשֶֽׁה׃פ","wĕ⁠şǎẖàt֖ẇ ha⁠pá֑̇saẖ wĕ⁠hiţĕqadĕ̇ş̌ẇ֙ wĕ⁠háki֣ynẇ la⁠ʼàẖéy⁠ke֔m la⁠ʻàş֥̂wòţ ki̇⁠dĕbar-yĕhwá֖h bĕ̇⁠yad-mòşěֽh׃p"],[35,7,"וַ⁠יָּ֣רֶם יֹאשִׁיָּ֣הוּ לִ⁠בְנֵ֪י הָ⁠עָ֟ם צֹ֞אן כְּבָשִׂ֣ים וּ⁠בְנֵֽי־עִזִּים֮ הַ⁠כֹּ֣ל לַ⁠פְּסָחִים֒ לְ⁠כָל־הַ⁠נִּמְצָ֗א לְ⁠מִסְפַּר֙ שְׁלֹשִׁ֣ים אֶ֔לֶף וּ⁠בָקָ֖ר שְׁלֹ֣שֶׁת אֲלָפִ֑ים אֵ֖לֶּה מֵ⁠רְכ֥וּשׁ הַ⁠מֶּֽלֶךְ׃ס","wa⁠yá֣̇rem yòʼşǐyá֣̇hẇ li⁠bĕné֪y há⁠ʻá֟m ẕò֞ʼn kĕ̇báşî֣ym ẇ⁠bĕnéֽy-ʻizi̇ym֮ ha⁠kò֣̇l la⁠pĕ̇sáẖiym֒ lĕ⁠kál-ha⁠ni̇mĕẕá֗ʼ lĕ⁠misĕpȧr֙ şĕ̌lòşǐ֣ym ʼe֔lep ẇ⁠báqá֖r şĕ̌lò֣şěţ ʼàlápi֑ym ʼé֖lėh mé⁠rĕk֥ẇş̌ ha⁠mėֽlekĕ׃s"],[35,8,"וְ⁠שָׂרָ֞י⁠ו לִ⁠נְדָבָ֥ה לָ⁠עָ֛ם לַ⁠כֹּהֲנִ֥ים וְ⁠לַ⁠לְוִיִּ֖ם הֵרִ֑ימוּ חִלְקִיָּ֨ה וּ⁠זְכַרְיָ֜הוּ וִֽ⁠יחִיאֵ֗ל נְגִידֵי֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים לַ⁠כֹּהֲנִ֞ים נָתְנ֣וּ לַ⁠פְּסָחִ֗ים אַלְפַּ֨יִם֙ וְ⁠שֵׁ֣שׁ מֵא֔וֹת וּ⁠בָקָ֖ר שְׁלֹ֥שׁ מֵאֽוֹת׃","wĕ⁠şá̂rá֞y⁠w li⁠nĕdábá֥h lá⁠ʻá֛m la⁠kò̇hàni֥ym wĕ⁠la⁠lĕwiyi֖̇m héri֑ymẇ ẖilĕqiyá̇֨h ẇ⁠zĕkarĕyá֜hẇ wiֽ⁠yẖiyʼé֗l nĕgiydéy֙ bé֣̇yţ há⁠ʼèlòhi֔ym la⁠kò̇hàni֞ym náţĕn֣ẇ la⁠pĕ̇sáẖi֗ym ʼalĕpȧ֨yim֙ wĕ⁠şé֣̌ş̌ méʼ֔wòţ ẇ⁠báqá֖r şĕ̌lò֥ş̌ méʼֽwòţ׃"],[35,9,"ו⁠כונניהו וּ⁠שְׁמַֽעְיָ֨הוּ וּ⁠נְתַנְאֵ֜ל אֶחָ֗י⁠ו וַ⁠חֲשַׁבְיָ֧הוּ וִ⁠יעִיאֵ֛ל וְ⁠יוֹזָבָ֖ד שָׂרֵ֣י הַ⁠לְוִיִּ֑ם הֵרִ֨ימוּ לַ⁠לְוִיִּ֤ם לַ⁠פְּסָחִים֙ חֲמֵ֣שֶׁת אֲלָפִ֔ים וּ⁠בָקָ֖ר חֲמֵ֥שׁ מֵאֽוֹת׃","w⁠kwnnyhw ẇ⁠şĕ̌maֽʻĕyá֨hẇ ẇ⁠nĕţanĕʼé֜l ʼeẖá֗y⁠w wa⁠ẖàşǎbĕyá֧hẇ wi⁠yʻiyʼé֛l wĕ⁠ywòzábá֖d şá̂ré֣y ha⁠lĕwiyi֑̇m héri֨ymẇ la⁠lĕwiyi֤̇m la⁠pĕ̇sáẖiym֙ ẖàmé֣şěţ ʼàlápi֔ym ẇ⁠báqá֖r ẖàmé֥ş̌ méʼֽwòţ׃"],[35,10,"וַ⁠תִּכּ֖וֹן הָ⁠עֲבוֹדָ֑ה וַ⁠יַּֽעַמְד֨וּ הַ⁠כֹּהֲנִ֧ים עַל־עָמְדָ֛⁠ם וְ⁠הַ⁠לְוִיִּ֥ם עַל־מַחְלְקוֹתָ֖⁠ם כְּ⁠מִצְוַ֥ת הַ⁠מֶּֽלֶךְ׃","wa⁠ţi̇k֖̇wòn há⁠ʻàbwòdá֑h wa⁠yȧֽʻamĕd֨ẇ ha⁠kò̇hàni֧ym ʻal-ʻámĕdá֛⁠m wĕ⁠ha⁠lĕwiyi֥̇m ʻal-maẖĕlĕqwòţá֖⁠m kĕ̇⁠miẕĕwa֥ţ ha⁠mėֽlekĕ׃"],[35,11,"וַֽ⁠יִּשְׁחֲט֖וּ הַ⁠פָּ֑סַח וַ⁠יִּזְרְק֤וּ הַ⁠כֹּהֲנִים֙ מִ⁠יָּדָ֔⁠ם וְ⁠הַ⁠לְוִיִּ֖ם מַפְשִׁיטִֽים׃","waֽ⁠yi̇şĕ̌ẖàt֖ẇ ha⁠pá֑̇saẖ wa⁠yi̇zĕrĕq֤ẇ ha⁠kò̇hàniym֙ mi⁠yá̇dá֔⁠m wĕ⁠ha⁠lĕwiyi֖̇m mapĕşǐytiֽym׃"],[35,12,"וַ⁠יָּסִ֨ירוּ הָ⁠עֹלָ֜ה לְ֠⁠תִתָּ⁠ם לְ⁠מִפְלַגּ֤וֹת לְ⁠בֵית־אָבוֹת֙ לִ⁠בְנֵ֣י הָ⁠עָ֔ם לְ⁠הַקְרִיב֙ לַ⁠יהוָ֔ה כַּ⁠כָּת֖וּב בְּ⁠סֵ֣פֶר מֹשֶׁ֑ה וְ⁠כֵ֖ן לַ⁠בָּקָֽר׃","wa⁠yá̇si֨yrẇ há⁠ʻòlá֜h lĕ֠⁠ţiţá̇⁠m lĕ⁠mipĕlaġ֤wòţ lĕ⁠béyţ-ʼábwòţ֙ li⁠bĕné֣y há⁠ʻá֔m lĕ⁠haqĕriyb֙ la⁠yhwá֔h kȧ⁠ká̇ţ֖ẇb bĕ̇⁠sé֣per mòşě֑h wĕ⁠ké֖n la⁠bá̇qáֽr׃"],[35,13,"וַֽ⁠יְבַשְּׁל֥וּ הַ⁠פֶּ֛סַח בָּ⁠אֵ֖שׁ כַּ⁠מִּשְׁפָּ֑ט וְ⁠הַ⁠קֳּדָשִׁ֣ים בִּשְּׁל֗וּ בַּ⁠סִּיר֤וֹת וּ⁠בַ⁠דְּוָדִים֙ וּ⁠בַ⁠צֵּ֣לָח֔וֹת וַ⁠יָּרִ֖יצוּ לְ⁠כָל־בְּנֵ֥י הָ⁠עָֽם׃","waֽ⁠yĕbaşĕ̇̌l֥ẇ ha⁠pė֛saẖ bá̇⁠ʼé֖ş̌ kȧ⁠mi̇şĕ̌pá֑̇t wĕ⁠ha⁠qȯdáşǐ֣ym bi̇şĕ̇̌l֗ẇ bȧ⁠si̇yr֤wòţ ẇ⁠ba⁠dĕ̇wádiym֙ ẇ⁠ba⁠ẕé֣̇láẖ֔wòţ wa⁠yá̇ri֖yẕẇ lĕ⁠kál-bĕ̇né֥y há⁠ʻáֽm׃"],[35,14,"וְ⁠אַחַ֗ר הֵכִ֤ינוּ לָ⁠הֶם֙ וְ⁠לַ⁠כֹּ֣הֲנִ֔ים כִּ֤י הַ⁠כֹּהֲנִים֙ בְּנֵ֣י אַהֲרֹ֔ן בְּ⁠הַֽעֲל֛וֹת הָ⁠עוֹלָ֥ה וְ⁠הַ⁠חֲלָבִ֖ים עַד־לָ֑יְלָה וְ⁠הַ⁠לְוִיִּם֙ הֵכִ֣ינוּ לָ⁠הֶ֔ם וְ⁠לַ⁠כֹּהֲנִ֖ים בְּנֵ֥י אַהֲרֹֽן׃","wĕ⁠ʼaẖa֗r héki֤ynẇ lá⁠hem֙ wĕ⁠la⁠kò֣̇hàni֔ym ki֤̇y ha⁠kò̇hàniym֙ bĕ̇né֣y ʼahàrò֔n bĕ̇⁠haֽʻàl֛wòţ há⁠ʻwòlá֥h wĕ⁠ha⁠ẖàlábi֖ym ʻad-lá֑yĕláh wĕ⁠ha⁠lĕwiyi̇m֙ héki֣ynẇ lá⁠he֔m wĕ⁠la⁠kò̇hàni֖ym bĕ̇né֥y ʼahàròֽn׃"],[35,15,"וְ⁠הַ⁠מְשֹֽׁרֲרִ֨ים בְּנֵי־אָסָ֜ף עַל־מַעֲמָדָ֗⁠ם כְּ⁠מִצְוַ֤ת דָּוִיד֙ וְ⁠אָסָ֞ף וְ⁠הֵימָ֤ן וִֽ⁠ידֻתוּן֙ חוֹזֵ֣ה הַ⁠מֶּ֔לֶךְ וְ⁠הַ⁠שֹּׁעֲרִ֖ים לְ⁠שַׁ֣עַר וָ⁠שָׁ֑עַר אֵ֣ין לָ⁠הֶ֗ם לָ⁠סוּר֙ מֵ⁠עַ֣ל עֲבֹֽדָתָ֔⁠ם כִּֽי־אֲחֵי⁠הֶ֥ם הַ⁠לְוִיִּ֖ם הֵכִ֥ינוּ לָ⁠הֶֽם׃","wĕ⁠ha⁠mĕşòֽ̌ràri֨ym bĕ̇néy-ʼásá֜p ʻal-maʻàmádá֗⁠m kĕ̇⁠miẕĕwa֤ţ dá̇wiyd֙ wĕ⁠ʼásá֞p wĕ⁠héymá֤n wiֽ⁠yduţẇn֙ ẖwòzé֣h ha⁠mė֔lekĕ wĕ⁠ha⁠şò̇̌ʻàri֖ym lĕ⁠şǎ֣ʻar wá⁠şá֑̌ʻar ʼé֣yn lá⁠he֗m lá⁠sẇr֙ mé⁠ʻa֣l ʻàbòֽdáţá֔⁠m kiֽ̇y-ʼàẖéy⁠he֥m ha⁠lĕwiyi֖̇m héki֥ynẇ lá⁠heֽm׃"],[35,16,"וַ֠⁠תִּכּוֹן כָּל־עֲבוֹדַ֨ת יְהוָ֜ה בַּ⁠יּ֤וֹם הַ⁠הוּא֙ לַ⁠עֲשׂ֣וֹת הַ⁠פֶּ֔סַח וְ⁠הַעֲל֣וֹת עֹל֔וֹת עַ֖ל מִזְבַּ֣ח יְהוָ֑ה כְּ⁠מִצְוַ֖ת הַ⁠מֶּ֥לֶךְ יֹאשִׁיָּֽהוּ׃","wa֠⁠ţi̇k̇wòn ká̇l-ʻàbwòda֨ţ yĕhwá֜h bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ la⁠ʻàş֣̂wòţ ha⁠pė֔saẖ wĕ⁠haʻàl֣wòţ ʻòl֔wòţ ʻa֖l mizĕbȧ֣ẖ yĕhwá֑h kĕ̇⁠miẕĕwa֖ţ ha⁠mė֥lekĕ yòʼşǐyáֽ̇hẇ׃"],[35,17,"וַ⁠יַּעֲשׂ֨וּ בְנֵֽי־יִשְׂרָאֵ֧ל הַֽ⁠נִּמְצְאִ֛ים אֶת־הַ⁠פֶּ֖סַח בָּ⁠עֵ֣ת הַ⁠הִ֑יא וְ⁠אֶת־חַ֥ג הַ⁠מַּצּ֖וֹת שִׁבְעַ֥ת יָמִֽים׃","wa⁠yȧʻàş̂֨ẇ bĕnéֽy-yişĕ̂ráʼé֧l haֽ⁠ni̇mĕẕĕʼi֛ym ʼeţ-ha⁠pė֖saẖ bá̇⁠ʻé֣ţ ha⁠hi֑yʼ wĕ⁠ʼeţ-ẖa֥g ha⁠mȧẕ֖̇wòţ şǐbĕʻa֥ţ yámiֽym׃"],[35,18,"וְ⁠לֹֽא־נַעֲשָׂ֨ה פֶ֤סַח כָּמֹ֨⁠הוּ֙ בְּ⁠יִשְׂרָאֵ֔ל מִ⁠ימֵ֖י שְׁמוּאֵ֣ל הַ⁠נָּבִ֑יא וְ⁠כָל־מַלְכֵ֣י יִשְׂרָאֵ֣ל ׀ לֹֽא־עָשׂ֡וּ כַּ⁠פֶּ֣סַח אֲשֶׁר־עָשָׂ֣ה יֹֽ֠אשִׁיָּהוּ וְ⁠הַ⁠כֹּהֲנִ֨ים וְ⁠הַ⁠לְוִיִּ֤ם וְ⁠כָל־יְהוּדָה֙ וְ⁠יִשְׂרָאֵ֣ל הַ⁠נִּמְצָ֔א וְ⁠יוֹשְׁבֵ֖י יְרוּשָׁלִָֽם׃ס","wĕ⁠lòֽʼ-naʻàşá̂֨h pe֤saẖ ká̇mò֨⁠hẇ֙ bĕ̇⁠yişĕ̂ráʼé֔l mi⁠ymé֖y şĕ̌mẇʼé֣l ha⁠ná̇bi֑yʼ wĕ⁠kál-malĕké֣y yişĕ̂ráʼé֣l ׀ lòֽʼ-ʻáş̂֡ẇ kȧ⁠pė֣saẖ ʼàşěr-ʻáşá֣̂h yòֽ֠ʼşǐyá̇hẇ wĕ⁠ha⁠kò̇hàni֨ym wĕ⁠ha⁠lĕwiyi֤̇m wĕ⁠kál-yĕhẇdáh֙ wĕ⁠yişĕ̂ráʼé֣l ha⁠ni̇mĕẕá֔ʼ wĕ⁠ywòşĕ̌bé֖y yĕrẇşá̌liáֽm׃s"],[35,19,"בִּ⁠שְׁמוֹנֶ֤ה עֶשְׂרֵה֙ שָׁנָ֔ה לְ⁠מַלְכ֖וּת יֹאשִׁיָּ֑הוּ נַעֲשָׂ֖ה הַ⁠פֶּ֥סַח הַ⁠זֶּֽה׃","bi̇⁠şĕ̌mwòne֤h ʻeşĕ̂réh֙ şá̌ná֔h lĕ⁠malĕk֖ẇţ yòʼşǐyá֑̇hẇ naʻàşá֖̂h ha⁠pė֥saẖ ha⁠zėֽh׃"],[35,20,"אַחֲרֵ֣י כָל־זֹ֗את אֲשֶׁ֨ר הֵכִ֤ין יֹֽאשִׁיָּ֨הוּ֙ אֶת־הַ⁠בַּ֔יִת עָלָ֞ה נְכ֧וֹ מֶֽלֶךְ־מִצְרַ֛יִם לְ⁠הִלָּחֵ֥ם בְּ⁠כַרְכְּמִ֖ישׁ עַל־פְּרָ֑ת וַ⁠יֵּצֵ֥א לִ⁠קְרָאת֖⁠וֹ יֹאשִׁיָּֽהוּ׃","ʼaẖàré֣y kál-zò֗ʼţ ʼàşě֨r héki֤yn yòֽʼşǐyá̇֨hẇ֙ ʼeţ-ha⁠bȧ֔yiţ ʻálá֞h nĕk֧wò meֽlekĕ-miẕĕra֛yim lĕ⁠hilá̇ẖé֥m bĕ̇⁠karĕkĕ̇mi֖yş̌ ʻal-pĕ̇rá֑ţ wa⁠yé̇ẕé֥ʼ li⁠qĕráʼţ֖⁠wò yòʼşǐyáֽ̇hẇ׃"],[35,21,"וַ⁠יִּשְׁלַ֣ח אֵלָ֣י⁠ו מַלְאָכִ֣ים ׀ לֵ⁠אמֹר֩ ׀ מַה־לִּ֨⁠י וָ⁠לָ֜⁠ךְ מֶ֣לֶךְ יְהוּדָ֗ה לֹא־עָלֶ֨י⁠ךָ אַתָּ֤ה הַ⁠יּוֹם֙ כִּ֚י אֶל־בֵּ֣ית מִלְחַמְתִּ֔⁠י וֵ⁠אלֹהִ֖ים אָמַ֣ר לְ⁠בַֽהֲלֵ֑⁠נִי חֲדַל־לְ⁠ךָ֛ מֵ⁠אֱלֹהִ֥ים אֲשֶׁר־עִמִּ֖⁠י וְ⁠אַל־יַשְׁחִיתֶֽ⁠ךָ׃","wa⁠yi̇şĕ̌la֣ẖ ʼélá֣y⁠w malĕʼáki֣ym ׀ lé⁠ʼmòr֩ ׀ mah-li̇֨⁠y wá⁠lá֜⁠kĕ me֣lekĕ yĕhẇdá֗h lòʼ-ʻále֨y⁠ká ʼaţá֤̇h ha⁠ẏwòm֙ ki֚̇y ʼel-bé֣̇yţ milĕẖamĕţi̇֔⁠y wé⁠ʼlòhi֖ym ʼáma֣r lĕ⁠baֽhàlé֑⁠niy ẖàdal-lĕ⁠ká֛ mé⁠ʼèlòhi֥ym ʼàşěr-ʻimi֖̇⁠y wĕ⁠ʼal-yaşĕ̌ẖiyţeֽ⁠ká׃"],[35,22,"וְ⁠לֹֽא־הֵסֵב֩ יֹאשִׁיָּ֨הוּ פָנָ֜י⁠ו מִמֶּ֗⁠נּוּ כִּ֤י לְ⁠הִלָּחֵֽם־בּ⁠וֹ֙ הִתְחַפֵּ֔שׂ וְ⁠לֹ֥א שָׁמַ֛ע אֶל־דִּבְרֵ֥י נְכ֖וֹ מִ⁠פִּ֣י אֱלֹהִ֑ים וַ⁠יָּבֹ֕א לְ⁠הִלָּחֵ֖ם בְּ⁠בִקְעַ֥ת מְגִדּֽוֹ׃","wĕ⁠lòֽʼ-héséb֩ yòʼşǐyá̇֨hẇ páná֜y⁠w mimė֗⁠ṅẇ ki֤̇y lĕ⁠hilá̇ẖéֽm-ḃ⁠wò֙ hiţĕẖapé̇֔ş̂ wĕ⁠lò֥ʼ şá̌ma֛ʻ ʼel-di̇bĕré֥y nĕk֖wò mi⁠pi֣̇y ʼèlòhi֑ym wa⁠yá̇bò֕ʼ lĕ⁠hilá̇ẖé֖m bĕ̇⁠biqĕʻa֥ţ mĕgiḋֽwò׃"],[35,23,"וַ⁠יֹּרוּ֙ הַ⁠יֹּרִ֔ים לַ⁠מֶּ֖לֶךְ יֹאשִׁיָּ֑הוּ וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ לַ⁠עֲבָדָי⁠ו֙ הַעֲבִיר֔וּ⁠נִי כִּ֥י הָחֳלֵ֖יתִי מְאֹֽד׃","wa⁠yò̇rẇ֙ ha⁠yò̇ri֔ym la⁠mė֖lekĕ yòʼşǐyá֑̇hẇ wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ la⁠ʻàbádáy⁠w֙ haʻàbiyr֔ẇ⁠niy ki֥̇y háẖolé֖yţiy mĕʼòֽd׃"],[35,24,"וַ⁠יַּֽעֲבִירֻ֨⁠הוּ עֲבָדָ֜י⁠ו מִן־הַ⁠מֶּרְכָּבָ֗ה וַֽ⁠יַּרְכִּיבֻ⁠הוּ֮ עַ֣ל רֶ֣כֶב הַ⁠מִּשְׁנֶה֮ אֲשֶׁר־ל⁠וֹ֒ וַ⁠יּוֹלִיכֻ֨⁠הוּ֙ יְר֣וּשָׁלִַ֔ם וַ⁠יָּ֕מָת וַ⁠יִּקָּבֵ֖ר בְּ⁠קִבְר֣וֹת אֲבֹתָ֑י⁠ו וְ⁠כָל־יְהוּדָה֙ וִ⁠יר֣וּשָׁלִַ֔ם מִֽתְאַבְּלִ֖ים עַל־יֹאשִׁיָּֽהוּ׃פ","wa⁠yȧֽʻàbiyru֨⁠hẇ ʻàbádá֜y⁠w min-ha⁠mėrĕká̇bá֗h waֽ⁠yȧrĕki̇ybu⁠hẇ֮ ʻa֣l re֣keb ha⁠mi̇şĕ̌neh֮ ʼàşěr-l⁠wò֒ wa⁠ẏwòliyku֨⁠hẇ֙ yĕr֣ẇşá̌lia֔m wa⁠yá̇֕máţ wa⁠yi̇qá̇bé֖r bĕ̇⁠qibĕr֣wòţ ʼàbòţá֑y⁠w wĕ⁠kál-yĕhẇdáh֙ wi⁠yr֣ẇşá̌lia֔m miֽţĕʼabĕ̇li֖ym ʻal-yòʼşǐyáֽ̇hẇ׃p"],[35,25,"וַ⁠יְקוֹנֵ֣ן יִרְמְיָהוּ֮ עַל־יֹאשִׁיָּהוּ֒ וַ⁠יֹּאמְר֣וּ כָֽל־הַ⁠שָּׁרִ֣ים ׀ וְ֠⁠הַ⁠שָּׁרוֹת בְּ⁠קִינ֨וֹתֵי⁠הֶ֤ם עַל־יֹאשִׁיָּ֨הוּ֙ עַד־הַ⁠יּ֔וֹם וַ⁠יִּתְּנ֥וּ⁠ם לְ⁠חֹ֖ק עַל־יִשְׂרָאֵ֑ל וְ⁠הִנָּ֥⁠ם כְּתוּבִ֖ים עַל־הַ⁠קִּינֽוֹת׃","wa⁠yĕqwòné֣n yirĕmĕyáhẇ֮ ʻal-yòʼşǐyá̇hẇ֒ wa⁠yò̇ʼmĕr֣ẇ káֽl-ha⁠şá̇̌ri֣ym ׀ wĕ֠⁠ha⁠şá̇̌rwòţ bĕ̇⁠qiyn֨wòţéy⁠he֤m ʻal-yòʼşǐyá̇֨hẇ֙ ʻad-ha⁠ẏ֔wòm wa⁠yi̇ţĕ̇n֥ẇ⁠m lĕ⁠ẖò֖q ʻal-yişĕ̂ráʼé֑l wĕ⁠hiná֥̇⁠m kĕ̇ţẇbi֖ym ʻal-ha⁠qi̇ynֽwòţ׃"],[35,26,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י יֹאשִׁיָּ֖הוּ וַ⁠חֲסָדָ֑י⁠ו כַּ⁠כָּת֖וּב בְּ⁠תוֹרַ֥ת יְהוָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y yòʼşǐyá֖̇hẇ wa⁠ẖàsádá֑y⁠w kȧ⁠ká̇ţ֖ẇb bĕ̇⁠ţwòra֥ţ yĕhwáֽh׃"],[35,27,"וּ⁠דְבָרָ֕י⁠ו הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אַחֲרֹנִ֑ים הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־סֵ֥פֶר מַלְכֵֽי־יִשְׂרָאֵ֖ל וִ⁠יהוּדָֽה׃","ẇ⁠dĕbárá֕y⁠w há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼaẖàròni֑ym hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-sé֥per malĕkéֽy-yişĕ̂ráʼé֖l wi⁠yhẇdáֽh׃"],[36,1,"וַ⁠יִּקְחוּ֙ עַם־הָ⁠אָ֔רֶץ אֶת־יְהוֹאָחָ֖ז בֶּן־יֹאשִׁיָּ֑הוּ וַ⁠יַּמְלִיכֻ֥⁠הוּ תַֽחַת־אָבִ֖י⁠ו בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yi̇qĕẖẇ֙ ʻam-há⁠ʼá֔reẕ ʼeţ-yĕhwòʼáẖá֖z bėn-yòʼşǐyá֑̇hẇ wa⁠yȧmĕliyku֥⁠hẇ ţaֽẖaţ-ʼábi֖y⁠w bi̇⁠yrẇşá̌liáֽm׃"],[36,2,"בֶּן־שָׁל֧וֹשׁ וְ⁠עֶשְׂרִ֛ים שָׁנָ֖ה יוֹאָחָ֣ז בְּ⁠מָלְכ֑⁠וֹ וּ⁠שְׁלֹשָׁ֣ה חֳדָשִׁ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-şá̌l֧wòş̌ wĕ⁠ʻeşĕ̂ri֛ym şá̌ná֖h ywòʼáẖá֣z bĕ̇⁠málĕk֑⁠wò ẇ⁠şĕ̌lòşá֣̌h ẖodáşǐ֔ym mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[36,3,"וַ⁠יְסִירֵ֥⁠הוּ מֶֽלֶךְ־מִצְרַ֖יִם בִּֽ⁠ירוּשָׁלִָ֑ם וַֽ⁠יַּעֲנֹשׁ֙ אֶת־הָ⁠אָ֔רֶץ מֵאָ֥ה כִכַּר־כֶּ֖סֶף וְ⁠כִכַּ֥ר זָהָֽב׃","wa⁠yĕsiyré֥⁠hẇ meֽlekĕ-miẕĕra֖yim biֽ̇⁠yrẇşá̌liá֑m waֽ⁠yȧʻànòş̌֙ ʼeţ-há⁠ʼá֔reẕ méʼá֥h kikȧr-kė֖sep wĕ⁠kikȧ֥r záháֽb׃"],[36,4,"וַ⁠יַּמְלֵ֨ךְ מֶֽלֶךְ־מִצְרַ֜יִם אֶת־אֶלְיָקִ֣ים אָחִ֗י⁠ו עַל־יְהוּדָה֙ וִ⁠יר֣וּשָׁלִַ֔ם וַ⁠יַּסֵּ֥ב אֶת־שְׁמ֖⁠וֹ יְהוֹיָקִ֑ים וְ⁠אֶת־יוֹאָחָ֤ז אָחִי⁠ו֙ לָקַ֣ח נְכ֔וֹ וַ⁠יְבִיאֵ֖⁠הוּ מִצְרָֽיְמָ⁠ה׃פ","wa⁠yȧmĕlé֨kĕ meֽlekĕ-miẕĕra֜yim ʼeţ-ʼelĕyáqi֣ym ʼáẖi֗y⁠w ʻal-yĕhẇdáh֙ wi⁠yr֣ẇşá̌lia֔m wa⁠yȧsé֥̇b ʼeţ-şĕ̌m֖⁠wò yĕhwòyáqi֑ym wĕ⁠ʼeţ-ywòʼáẖá֤z ʼáẖiy⁠w֙ láqa֣ẖ nĕk֔wò wa⁠yĕbiyʼé֖⁠hẇ miẕĕráֽyĕmá⁠h׃p"],[36,5,"בֶּן־עֶשְׂרִ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ יְהוֹיָקִ֣ים בְּ⁠מָלְכ֔⁠וֹ וְ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יַּ֣עַשׂ הָ⁠רַ֔ע בְּ⁠עֵינֵ֖י יְהוָ֥ה אֱלֹהָֽי⁠ו׃","bėn-ʻeşĕ̂ri֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ yĕhwòyáqi֣ym bĕ̇⁠málĕk֔⁠wò wĕ⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wa⁠yȧ֣ʻaş̂ há⁠ra֔ʻ bĕ̇⁠ʻéyné֖y yĕhwá֥h ʼèlòháֽy⁠w׃"],[36,6,"עָלָ֣י⁠ו עָלָ֔ה נְבוּכַדְנֶאצַּ֖ר מֶ֣לֶךְ בָּבֶ֑ל וַ⁠יַּֽאַסְרֵ֨⁠הוּ֙ בַּֽ⁠נְחֻשְׁתַּ֔יִם לְ⁠הֹלִיכ֖⁠וֹ בָּבֶֽלָ⁠ה׃","ʻálá֣y⁠w ʻálá֔h nĕbẇkadĕneʼẕȧ֖r me֣lekĕ bá̇be֑l wa⁠yȧֽʼasĕré֨⁠hẇ֙ bȧֽ⁠nĕẖuşĕ̌ţȧ֔yim lĕ⁠hòliyk֖⁠wò bá̇beֽlá⁠h׃"],[36,7,"וּ⁠מִ⁠כְּלֵי֙ בֵּ֣ית יְהוָ֔ה הֵבִ֥יא נְבוּכַדְנֶאצַּ֖ר לְ⁠בָבֶ֑ל וַ⁠יִּתְּנֵ֥⁠ם בְּ⁠הֵיכָל֖⁠וֹ בְּ⁠בָבֶֽל׃","ẇ⁠mi⁠kĕ̇léy֙ bé֣̇yţ yĕhwá֔h hébi֥yʼ nĕbẇkadĕneʼẕȧ֖r lĕ⁠bábe֑l wa⁠yi̇ţĕ̇né֥⁠m bĕ̇⁠héykál֖⁠wò bĕ̇⁠bábeֽl׃"],[36,8,"וְ⁠יֶתֶר֩ דִּבְרֵ֨י יְהֽוֹיָקִ֜ים וְ⁠תֹֽעֲבֹתָ֤י⁠ו אֲשֶׁר־עָשָׂה֙ וְ⁠הַ⁠נִּמְצָ֣א עָלָ֔י⁠ו הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־סֵ֛פֶר מַלְכֵ֥י יִשְׂרָאֵ֖ל וִֽ⁠יהוּדָ֑ה וַ⁠יִּמְלֹ֛ךְ יְהוֹיָכִ֥ין בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wĕ⁠yeţer֩ di̇bĕré֨y yĕhֽwòyáqi֜ym wĕ⁠ţòֽʻàbòţá֤y⁠w ʼàşěr-ʻáşá̂h֙ wĕ⁠ha⁠ni̇mĕẕá֣ʼ ʻálá֔y⁠w hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-sé֛per malĕké֥y yişĕ̂ráʼé֖l wiֽ⁠yhẇdá֑h wa⁠yi̇mĕlò֛kĕ yĕhwòyáki֥yn bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[36,9,"בֶּן־שְׁמוֹנֶ֤ה שָׁנִים֙ יְהוֹיָכִ֣ין בְּ⁠מָלְכ֔⁠וֹ וּ⁠שְׁלֹשָׁ֤ה חֳדָשִׁים֙ וַ⁠עֲשֶׂ֣רֶת יָמִ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","bėn-şĕ̌mwòne֤h şá̌niym֙ yĕhwòyáki֣yn bĕ̇⁠málĕk֔⁠wò ẇ⁠şĕ̌lòşá֤̌h ẖodáşǐym֙ wa⁠ʻàşê֣reţ yámi֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[36,10,"וְ⁠לִ⁠תְשׁוּבַ֣ת הַ⁠שָּׁנָ֗ה שָׁלַח֙ הַ⁠מֶּ֣לֶךְ נְבֽוּכַדְנֶאצַּ֔ר וַ⁠יְבִאֵ֣⁠הוּ בָבֶ֔לָ⁠ה עִם־כְּלֵ֖י חֶמְדַּ֣ת בֵּית־יְהוָ֑ה וַ⁠יַּמְלֵךְ֙ אֶת־צִדְקִיָּ֣הוּ אָחִ֔י⁠ו עַל־יְהוּדָ֖ה וִֽ⁠ירוּשָׁלִָֽם׃פ","wĕ⁠li⁠ţĕş̌ẇba֣ţ ha⁠şá̇̌ná֗h şá̌laẖ֙ ha⁠mė֣lekĕ nĕbֽẇkadĕneʼẕȧ֔r wa⁠yĕbiʼé֣⁠hẇ bábe֔lá⁠h ʻim-kĕ̇lé֖y ẖemĕdȧ֣ţ bé̇yţ-yĕhwá֑h wa⁠yȧmĕlékĕ֙ ʼeţ-ẕidĕqiyá֣̇hẇ ʼáẖi֔y⁠w ʻal-yĕhẇdá֖h wiֽ⁠yrẇşá̌liáֽm׃p"],[36,11,"בֶּן־עֶשְׂרִ֧ים וְ⁠אַחַ֛ת שָׁנָ֖ה צִדְקִיָּ֣הוּ בְ⁠מָלְכ֑⁠וֹ וְ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃","bėn-ʻeşĕ̂ri֧ym wĕ⁠ʼaẖa֛ţ şá̌ná֖h ẕidĕqiyá֣̇hẇ bĕ⁠málĕk֑⁠wò wĕ⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃"],[36,12,"וַ⁠יַּ֣עַשׂ הָ⁠רַ֔ע בְּ⁠עֵינֵ֖י יְהוָ֣ה אֱלֹהָ֑י⁠ו לֹ֣א נִכְנַ֗ע מִ⁠לִּ⁠פְנֵ֛י יִרְמְיָ֥הוּ הַ⁠נָּבִ֖יא מִ⁠פִּ֥י יְהוָֽה׃","wa⁠yȧ֣ʻaş̂ há⁠ra֔ʻ bĕ̇⁠ʻéyné֖y yĕhwá֣h ʼèlòhá֑y⁠w lò֣ʼ nikĕna֗ʻ mi⁠li̇⁠pĕné֛y yirĕmĕyá֥hẇ ha⁠ná̇bi֖yʼ mi⁠pi֥̇y yĕhwáֽh׃"],[36,13,"וְ֠⁠גַם בַּ⁠מֶּ֤לֶךְ נְבֽוּכַדְנֶאצַּר֙ מָרָ֔ד אֲשֶׁ֥ר הִשְׁבִּיע֖⁠וֹ בֵּֽ⁠אלֹהִ֑ים וַ⁠יֶּ֤קֶשׁ אֶת־עָרְפּ⁠וֹ֙ וַ⁠יְאַמֵּ֣ץ אֶת־לְבָב֔⁠וֹ מִ⁠שּׁ֕וּב אֶל־יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wĕ֠⁠gam bȧ⁠mė֤lekĕ nĕbֽẇkadĕneʼẕȧr֙ márá֔d ʼàşě֥r hişĕ̌bi̇yʻ֖⁠wò béֽ̇⁠ʼlòhi֑ym wa⁠yė֤qeş̌ ʼeţ-ʻárĕṗ⁠wò֙ wa⁠yĕʼamé֣̇ẕ ʼeţ-lĕbáb֔⁠wò mi⁠ş̇̌֕ẇb ʼel-yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[36,14,"גַּ֠ם כָּל־שָׂרֵ֨י הַ⁠כֹּהֲנִ֤ים וְ⁠הָ⁠עָם֙ הִרְבּ֣וּ למעול־מַ֔עַל כְּ⁠כֹ֖ל תֹּעֲב֣וֹת הַ⁠גּוֹיִ֑ם וַֽ⁠יְטַמְּאוּ֙ אֶת־בֵּ֣ית יְהוָ֔ה אֲשֶׁ֥ר הִקְדִּ֖ישׁ בִּ⁠ירוּשָׁלִָֽם׃","gȧ֠m ká̇l-şá̂ré֨y ha⁠kò̇hàni֤ym wĕ⁠há⁠ʻám֙ hirĕḃ֣ẇ lmʻwl-ma֔ʻal kĕ̇⁠kò֖l ţò̇ʻàb֣wòţ ha⁠ġwòyi֑m waֽ⁠yĕtamĕ̇ʼẇ֙ ʼeţ-bé֣̇yţ yĕhwá֔h ʼàşě֥r hiqĕdi֖̇yş̌ bi̇⁠yrẇşá̌liáֽm׃"],[36,15,"וַ⁠יִּשְׁלַ֡ח יְהוָה֩ אֱלֹהֵ֨י אֲבוֹתֵי⁠הֶ֧ם עֲלֵי⁠הֶ֛ם בְּ⁠יַ֥ד מַלְאָכָ֖י⁠ו הַשְׁכֵּ֣ם וְ⁠שָׁל֑וֹחַ כִּֽי־חָמַ֥ל עַל־עַמּ֖⁠וֹ וְ⁠עַל־מְעוֹנֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֡ẖ yĕhwáh֩ ʼèlòhé֨y ʼàbwòţéy⁠he֧m ʻàléy⁠he֛m bĕ̇⁠ya֥d malĕʼáká֖y⁠w haşĕ̌ké֣̇m wĕ⁠şá̌l֑wòẖa kiֽ̇y-ẖáma֥l ʻal-ʻaṁ֖⁠wò wĕ⁠ʻal-mĕʻwònֽ⁠wò׃"],[36,16,"וַ⁠יִּֽהְי֤וּ מַלְעִבִים֙ בְּ⁠מַלְאֲכֵ֣י הָ⁠אֱלֹהִ֔ים וּ⁠בוֹזִ֣ים דְּבָרָ֔י⁠ו וּ⁠מִֽתַּעְתְּעִ֖ים בִּ⁠נְבִאָ֑י⁠ו עַ֠ד עֲל֧וֹת חֲמַת־יְהוָ֛ה בְּ⁠עַמּ֖⁠וֹ עַד־לְ⁠אֵ֥ין מַרְפֵּֽא׃","wa⁠yiֽ̇hĕy֤ẇ malĕʻibiym֙ bĕ̇⁠malĕʼàké֣y há⁠ʼèlòhi֔ym ẇ⁠bwòzi֣ym dĕ̇bárá֔y⁠w ẇ⁠miֽţȧʻĕţĕ̇ʻi֖ym bi̇⁠nĕbiʼá֑y⁠w ʻa֠d ʻàl֧wòţ ẖàmaţ-yĕhwá֛h bĕ̇⁠ʻaṁ֖⁠wò ʻad-lĕ⁠ʼé֥yn marĕpéֽ̇ʼ׃"],[36,17,"וַ⁠יַּ֨עַל עֲלֵי⁠הֶ֜ם אֶת־מֶ֣לֶךְ כשדיים וַ⁠יַּהֲרֹ֨ג בַּחוּרֵי⁠הֶ֤ם בַּ⁠חֶ֨רֶב֙ בְּ⁠בֵ֣ית מִקְדָּשָׁ֔⁠ם וְ⁠לֹ֥א חָמַ֛ל עַל־בָּח֥וּר וּ⁠בְתוּלָ֖ה זָקֵ֣ן וְ⁠יָשֵׁ֑שׁ הַ⁠כֹּ֖ל נָתַ֥ן בְּ⁠יָדֽ⁠וֹ׃","wa⁠yȧ֨ʻal ʻàléy⁠he֜m ʼeţ-me֣lekĕ kşdyym wa⁠yȧhàrò֨g bȧẖẇréy⁠he֤m bȧ⁠ẖe֨reb֙ bĕ̇⁠bé֣yţ miqĕdá̇şá̌֔⁠m wĕ⁠lò֥ʼ ẖáma֛l ʻal-bá̇ẖ֥ẇr ẇ⁠bĕţẇlá֖h záqé֣n wĕ⁠yáşé֑̌ş̌ ha⁠kò֖̇l náţa֥n bĕ̇⁠yádֽ⁠wò׃"],[36,18,"וְ֠⁠כֹל כְּלֵ֞י בֵּ֤ית הָ⁠אֱלֹהִים֙ הַ⁠גְּדֹלִ֣ים וְ⁠הַ⁠קְּטַנִּ֔ים וְ⁠אֹֽצְרוֹת֙ בֵּ֣ית יְהוָ֔ה וְ⁠אֹצְר֥וֹת הַ⁠מֶּ֖לֶךְ וְ⁠שָׂרָ֑י⁠ו הַ⁠כֹּ֖ל הֵבִ֥יא בָבֶֽל׃","wĕ֠⁠kòl kĕ̇lé֞y bé֤̇yţ há⁠ʼèlòhiym֙ ha⁠gĕ̇dòli֣ym wĕ⁠ha⁠qĕ̇tani̇֔ym wĕ⁠ʼòֽẕĕrwòţ֙ bé֣̇yţ yĕhwá֔h wĕ⁠ʼòẕĕr֥wòţ ha⁠mė֖lekĕ wĕ⁠şá̂rá֑y⁠w ha⁠kò֖̇l hébi֥yʼ bábeֽl׃"],[36,19,"וַֽ⁠יִּשְׂרְפוּ֙ אֶת־בֵּ֣ית הָ⁠אֱלֹהִ֔ים וַֽ⁠יְנַתְּצ֔וּ אֵ֖ת חוֹמַ֣ת יְרוּשָׁלִָ֑ם וְ⁠כָל־אַרְמְנוֹתֶ֨י⁠הָ֙ שָׂרְפ֣וּ בָ⁠אֵ֔שׁ וְ⁠כָל־כְּלֵ֥י מַחֲמַדֶּ֖י⁠הָ לְ⁠הַשְׁחִֽית׃ס","waֽ⁠yi̇şĕ̂rĕpẇ֙ ʼeţ-bé֣̇yţ há⁠ʼèlòhi֔ym waֽ⁠yĕnaţĕ̇ẕ֔ẇ ʼé֖ţ ẖwòma֣ţ yĕrẇşá̌liá֑m wĕ⁠kál-ʼarĕmĕnwòţe֨y⁠há֙ şá̂rĕp֣ẇ bá⁠ʼé֔ş̌ wĕ⁠kál-kĕ̇lé֥y maẖàmadė֖y⁠há lĕ⁠haşĕ̌ẖiֽyţ׃s"],[36,20,"וַ⁠יֶּ֛גֶל הַ⁠שְּׁאֵרִ֥ית מִן־הַ⁠חֶ֖רֶב אֶל־בָּבֶ֑ל וַֽ⁠יִּהְיוּ־ל֤⁠וֹ וּ⁠לְ⁠בָנָי⁠ו֙ לַ⁠עֲבָדִ֔ים עַד־מְלֹ֖ךְ מַלְכ֥וּת פָּרָֽס׃","wa⁠yė֛gel ha⁠şĕ̇̌ʼéri֥yţ min-ha⁠ẖe֖reb ʼel-bá̇be֑l waֽ⁠yi̇hĕyẇ-l֤⁠wò ẇ⁠lĕ⁠bánáy⁠w֙ la⁠ʻàbádi֔ym ʻad-mĕlò֖kĕ malĕk֥ẇţ pá̇ráֽs׃"],[36,21,"לְ⁠מַלֹּ֤אות דְּבַר־יְהוָה֙ בְּ⁠פִ֣י יִרְמְיָ֔הוּ עַד־רָצְתָ֥ה הָ⁠אָ֖רֶץ אֶת־שַׁבְּתוֹתֶ֑י⁠הָ כָּל־יְמֵ֤י הָשַּׁמָּ⁠ה֙ שָׁבָ֔תָה לְ⁠מַלֹּ֖אות שִׁבְעִ֥ים שָׁנָֽה׃פ","lĕ⁠malò֤̇ʼwţ dĕ̇bar-yĕhwáh֙ bĕ̇⁠pi֣y yirĕmĕyá֔hẇ ʻad-ráẕĕţá֥h há⁠ʼá֖reẕ ʼeţ-şǎbĕ̇ţwòţe֑y⁠há ká̇l-yĕmé֤y háşȧ̌má̇⁠h֙ şá̌bá֔ţáh lĕ⁠malò֖̇ʼwţ şǐbĕʻi֥ym şá̌náֽh׃p"],[36,22,"וּ⁠בִ⁠שְׁנַ֣ת אַחַ֗ת לְ⁠כ֨וֹרֶשׁ֙ מֶ֣לֶךְ פָּרַ֔ס לִ⁠כְל֥וֹת דְּבַר־יְהוָ֖ה בְּ⁠פִ֣י יִרְמְיָ֑הוּ הֵעִ֣יר יְהוָ֗ה אֶת־ר֨וּחַ֙ כּ֣וֹרֶשׁ מֶֽלֶךְ־פָּרַ֔ס וַ⁠יַּֽעֲבֶר־קוֹל֙ בְּ⁠כָל־מַלְכוּת֔⁠וֹ וְ⁠גַם־בְּ⁠מִכְתָּ֖ב לֵ⁠אמֹֽר׃ס","ẇ⁠bi⁠şĕ̌na֣ţ ʼaẖa֗ţ lĕ⁠k֨wòreş̌֙ me֣lekĕ pá̇ra֔s li⁠kĕl֥wòţ dĕ̇bar-yĕhwá֖h bĕ̇⁠pi֣y yirĕmĕyá֑hẇ héʻi֣yr yĕhwá֗h ʼeţ-r֨ẇẖa֙ k֣̇wòreş̌ meֽlekĕ-pá̇ra֔s wa⁠yȧֽʻàber-qwòl֙ bĕ̇⁠kál-malĕkẇţ֔⁠wò wĕ⁠gam-bĕ̇⁠mikĕţá֖̇b lé⁠ʼmòֽr׃s"],[36,23,"כֹּה־אָמַ֞ר כּ֣וֹרֶשׁ ׀ מֶ֣לֶךְ פָּרַ֗ס כָּל־מַמְלְכ֤וֹת הָ⁠אָ֨רֶץ֙ נָ֣תַן לִ֗⁠י יְהוָה֙ אֱלֹהֵ֣י הַ⁠שָּׁמַ֔יִם וְ⁠הֽוּא־פָקַ֤ד עָלַ⁠י֙ לִ⁠בְנֽוֹת־ל֣⁠וֹ בַ֔יִת בִּ⁠ירוּשָׁלִַ֖ם אֲשֶׁ֣ר בִּֽ⁠יהוּדָ֑ה מִֽי־בָ⁠כֶ֣ם מִ⁠כָּל־עַמּ֗⁠וֹ יְהוָ֧ה אֱלֹהָ֛י⁠ו עִמּ֖⁠וֹ וְ⁠יָֽעַל׃","kò̇h-ʼáma֞r k֣̇wòreş̌ ׀ me֣lekĕ pá̇ra֗s ká̇l-mamĕlĕk֤wòţ há⁠ʼá֨reẕ֙ ná֣ţan li֗⁠y yĕhwáh֙ ʼèlòhé֣y ha⁠şá̇̌ma֔yim wĕ⁠hֽẇʼ-páqa֤d ʻála⁠y֙ li⁠bĕnֽwòţ-l֣⁠wò ba֔yiţ bi̇⁠yrẇşá̌lia֖m ʼàşě֣r biֽ̇⁠yhẇdá֑h miֽy-bá⁠ke֣m mi⁠ká̇l-ʻaṁ֗⁠wò yĕhwá֧h ʼèlòhá֛y⁠w ʻiṁ֖⁠wò wĕ⁠yáֽʻal׃"]]}};